    if _G.script_key and _G.script_key ~= "" and writefile then
        writefile("sysgt_key.txt", tostring(_G.script_key))
    end
end)

local function getQueueBootstrapCode()
    local key = _G.script_key or (getgenv and getgenv().script_key) or ""
    if (not key or key == "") and isfile and isfile("sysgt_key.txt") and readfile then
        pcall(function()
            local saved = readfile("sysgt_key.txt")
            if saved and saved ~= "" then key = saved end
        end)
    end
    if key and key ~= "" and writefile then
        pcall(writefile, "sysgt_key.txt", key)
    end

    local url = _G.SYSHUB_LOADER_URL or (_G.script_url) or "https://syshub.my.id"

    return string.format([==[
task.spawn(function()
    if _G.SysHub_BootstrapRunning or (getgenv and getgenv().SysHub_BootstrapRunning) then return end
    _G.SysHub_BootstrapRunning = true
    if getgenv then getgenv().SysHub_BootstrapRunning = true end

    repeat task.wait(0.3) until game:IsLoaded()
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer or Players.PlayerAdded:Wait()
    local pg = lp and lp:WaitForChild("PlayerGui", 25)
    if pg then pg:WaitForChild("GameGui", 25) end
    task.wait(1.5)
    if pg and pg:FindFirstChild("PNB_UI") then return end

    -- 1. Restore Key ke environment server baru
    local currentKey = %q
    if (not currentKey or currentKey == "") and isfile and isfile("sysgt_key.txt") and readfile then
        pcall(function()
            local saved = readfile("sysgt_key.txt")
            if saved and saved ~= "" then currentKey = saved end
        end)
    end
    if currentKey and currentKey ~= "" then
        _G.script_key = currentKey
        if getgenv then getgenv().script_key = currentKey end
    end

    -- 2. Web Loader: Panggil loader resmi SysHub (Backend Laravel + Bootstrapper)
    local ranWeb = false
    pcall(function()
        if game.HttpGet then
            local code = game:HttpGet(%q)
            if code and code ~= "" then
                local fn = loadstring(code)
                if fn then
                    ranWeb = true
                    print("[QUEUE_ON_TELEPORT] Berhasil autoload SysHub via Web Loader!")
                    task.spawn(fn)
                end
            end
        end
    end)
    if ranWeb then return end

    -- 3. Fallback ke file lokal jika offline / testing lokal / web maintenance
    local fn = nil
    for _, path in ipairs({"mcp/pnb_script.luau", "MCP/pnb_script.luau", "pnb_script.luau"}) do
        local ok, res = pcall(loadfile, path)
        if ok and type(res) == "function" then
            fn = res
            break
        end
    end
    if fn then
        print("[QUEUE_ON_TELEPORT] Berhasil autoload SysHub via Local File!")
        task.spawn(fn)
    end
end)
]==], key, url)
end

local function safeQueueOnTeleport(code)
    if _G.SysHub_QueueOnTeleportSet or (getgenv and getgenv().SysHub_QueueOnTeleportSet) then return end
    _G.SysHub_QueueOnTeleportSet = true
    if getgenv then getgenv().SysHub_QueueOnTeleportSet = true end
    code = code or getQueueBootstrapCode()
    local qot = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport) or queueonteleport
    if qot and type(qot) == "function" then
        pcall(qot, code)
    end
end

-- Pasang langsung saat script dieksekusi agar siap untuk server hop / disconnect kapan saja
safeQueueOnTeleport()

