local function getAccountFileName(prefix, ext)
    ext = ext or "json"
    local rawName = ""
    pcall(function()
        local lp = (Players and Players.LocalPlayer) or LocalPlayer
        if lp and lp.Name and lp.Name ~= "" then
            rawName = tostring(lp.Name)
        elseif lp and lp.UserId and lp.UserId > 0 then
            rawName = tostring(lp.UserId)
        end
    end)
    local safeName = string.gsub(string.lower(rawName), "[^%w_]", "")
    if safeName == "" then safeName = "default" end
    return string.format("%s_%s.%s", prefix, safeName, ext)
end
_G.getAccountFileName = getAccountFileName

