--  NATIVE ENGINE & WORLD AUTO-RESOLVER (100% IMMUNE TO UPDATE OBFUSCATION)
-- ═══════════════════════════════════════
local cachedNativeWorld = nil
local cachedNativeEngine = nil
local lastWorldCheck = 0

local function getNativeEngine()
    if cachedNativeEngine and cachedNativeWorld and cachedNativeWorld.name and cachedNativeWorld.name ~= "" and cachedNativeWorld.name ~= "LOBBY" then
        return cachedNativeEngine, cachedNativeWorld
    end

    if not cachedNativeEngine and _G._Growblox_eng then
        cachedNativeEngine = _G._Growblox_eng
    end

    local w = cachedNativeWorld or _G._Growblox_w
    if not w and filtergc then
        local wList = filtergc("table", { Keys = {"dropList", "growScan"} }, false)
        w = wList and wList[1]
    end

    if w and w.tileChanged and debug and debug.getupvalues then
        local ups = debug.getupvalues(w.tileChanged)
        if ups and ups[1] and type(ups[1]) == "table" and (ups[1].world or ups[1].Items or ups[1].pool) then
            cachedNativeEngine = ups[1]
            cachedNativeWorld = ups[1].world or w
            _G._Growblox_w = cachedNativeWorld
            _G._Growblox_eng = cachedNativeEngine
            return cachedNativeEngine, cachedNativeWorld
        end
    end

    -- Direct fallback by native engine keys
    if not cachedNativeEngine and filtergc then
        local engList = filtergc("table", { Keys = {"px", "py", "tilesLayer", "worldFrame"} }, false)
        if engList and engList[1] then
            cachedNativeEngine = engList[1]
        end
    end

    if cachedNativeEngine and not w and cachedNativeEngine.world then
        w = cachedNativeEngine.world
    end

    cachedNativeWorld = w or cachedNativeWorld
    if cachedNativeWorld then _G._Growblox_w = cachedNativeWorld end
    if cachedNativeEngine then _G._Growblox_eng = cachedNativeEngine end
    return cachedNativeEngine, cachedNativeWorld
end
_G.getNativeEngine = getNativeEngine

local function getNativeWorld()
    if isWorldPickerOpen and isWorldPickerOpen() then
        cachedNativeWorld = nil
        cachedNativeEngine = nil
        return nil
    end

    local now = os.clock()
    if cachedNativeWorld and (now - lastWorldCheck < 0.5) then
        if cachedNativeWorld.name and cachedNativeWorld.name ~= "" and cachedNativeWorld.name ~= "LOBBY" then
            return cachedNativeWorld
        end
    end
    lastWorldCheck = now

    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    return w
end
_G.getNativeWorld = getNativeWorld

