local function censorLoading(gui)
    if not gui or (gui.Name ~= "Loading" and gui.Name ~= "TeleportLoading") then return end

    local function checkLabel(label)
        if label:IsA("TextLabel") then
            local function hideWorld()
                -- Deteksi jika teks diawali dengan "Entering " tapi belum disensor
                if string.sub(label.Text, 1, 9) == "Entering " and label.Text ~= "Entering World..." then
                    label.Text = "SYSHUBONTOP..." -- Ganti sesuai keinginan (misal: "Entering [STREAM]...")
                end
            end

            label:GetPropertyChangedSignal("Text"):Connect(hideWorld)
            hideWorld()
        end
    end

    gui.DescendantAdded:Connect(checkLabel)
    for _, desc in ipairs(gui:GetDescendants()) do
        checkLabel(desc)
    end
end

-- Pantau saat Loading GUI muncul
pg.ChildAdded:Connect(censorLoading)
