local ACT_KIND = {
    PUNCH = 1,
    BUILD = 2,
    PLANT = 3,
    HIT   = 6,
    LOCK  = 7
}

-- ═══════════════════════════════════════
--  NATIVE GROWSCAN & INVENTORY ENGINE
-- ═══════════════════════════════════════
local cachedInventory = nil
local function getNativeInventory()
    if cachedInventory and cachedInventory.slots then
        return cachedInventory
    end
    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    if eng and eng.inv and eng.inv.slots then
        cachedInventory = eng.inv
        return cachedInventory
    end
    if w and w.feedWell and debug and debug.getupvalues then
        local ok, upvals = pcall(debug.getupvalues, w.feedWell)
        if ok and upvals then
            for _, val in pairs(upvals) do
                if type(val) == "table" and val.capacity and val.slots and val.add then
                    cachedInventory = val
                    return val
                end
            end
        end
    end
    -- Fallback via curr.onDrop upvalue
    pcall(function()
        local LP = Players.LocalPlayer
        local invModule = LP and LP:FindFirstChild("PlayerGui") and LP.PlayerGui:FindFirstChild("GameGui") and LP.PlayerGui.GameGui:FindFirstChild("InventoryUI")
        if not invModule then return end
        local mod = require(invModule)
        local curr = mod and mod.current
        if curr and curr.onDrop and debug and debug.getupvalues then
            local ok, upvals = pcall(debug.getupvalues, curr.onDrop)
            if ok and upvals then
                for _, val in pairs(upvals) do
                    if type(val) == "table" and val.capacity and val.slots and val.add then
                        cachedInventory = val
                        return
                    end
                end
            end
        end
    end)
    return cachedInventory
end
_G.getNativeInventory = getNativeInventory

local function getInventoryUICurrent()
    local LP = Players.LocalPlayer
    local invModule = LP and LP:FindFirstChild("PlayerGui") and LP.PlayerGui:FindFirstChild("GameGui") and LP.PlayerGui.GameGui:FindFirstChild("InventoryUI")
    if not invModule then return nil end
    local ok, mod = pcall(require, invModule)
    if ok and mod and mod.current then
        return mod.current
    end
    return nil
end

local function sendActPacket(kind, tileX, tileY)
    -- Client resmi Growblox HANYA menggunakan Net.tile.send untuk build & plant.
    -- Pengiriman Net.act dengan kind BUILD / PLANT akan memicu kick Error 267 (Unexpected Client Behaviour)!
    if kind == ACT_KIND.BUILD or kind == ACT_KIND.PLANT then
        return
    end

    local cx = tileX + 0.5
    local cy = tileY + 0.5

    if Net and Net.act and Net.act.send then
        pcall(Net.act.send, {
            kind = kind,
            x = cx,
            y = cy
        })
    end
end

-- Legit ByteNet Tile Packet (Bypass Error 267 Honeypot)
local function sendTilePacket(layer, tileX, tileY, itemId, flip)
    local layerNum = (string.lower(tostring(layer or "fg")) == "bg") and 2 or 1
    local id = tonumber(itemId) or 0
    local tx = math.floor(tileX)
    local ty = math.floor(tileY)

    if Net and Net.tile and Net.tile.send then
        local ok = pcall(Net.tile.send, {
            layer = layerNum,
            x = tx,
            y = ty,
            id = id,
            flip = (flip == true)
        })
        return ok
    end
    return false
end

-- Legit ByteNet Drop Packet
local function sendDropPacket(itemId, count, dropX, dropY)
    local id = tonumber(itemId) or 0
    local cnt = math.clamp(math.floor(tonumber(count) or 1), 1, 65535)
    local dx = tonumber(dropX) or 0
    local dy = tonumber(dropY) or 0

    local netObj = Net or (getgenv and getgenv().SysHub_Net)
    if netObj and netObj.drop and netObj.drop.send then
        local ok = pcall(netObj.drop.send, {
            id = id,
            n = cnt,
            x = dx,
            y = dy
        })
        return ok
    end
    return false
end

-- Legit ByteNet Recycle/Trash Packet
local function sendRecyclePacket(itemId, count)
    local id = tonumber(itemId) or 0
    local cnt = math.clamp(math.floor(tonumber(count) or 1), 1, 65535)

    local invUI = (getInventoryUICurrent and getInventoryUICurrent()) or nil
    if invUI and invUI.onRecycle then
        local ok = pcall(invUI.onRecycle, id, cnt)
        if ok then return true end
    end

    if Net and Net.recycle and Net.recycle.send then
        local ok = pcall(Net.recycle.send, {
            id = id,
            n = cnt
        })
        return ok
    end
    return false
end

-- Legit ByteNet Lock Conversion Packet
local function sendConvertLock(fromId, toId)
    local fId = tonumber(fromId) or 0
    local tId = tonumber(toId) or 0

    if Net and Net.convert and Net.convert.send then
        local ok = pcall(Net.convert.send, {
            from = fId,
            to = tId
        })
        return ok
    end
    return false
end

-- ═══════════════════════════════════════
--  CLIENT TILE SYNC (FIX VISUAL DESYNC)
-- ═══════════════════════════════════════
--  CLIENT TILE & BREAK SYNC (100% NATIVE ENGINE SYNC)
-- ═══════════════════════════════════════
local function forceClientTileUpdate(layer, tx, ty, newId)
    newId = tonumber(newId) or 0
    layer = string.lower(tostring(layer or "fg"))
    if layer ~= "fg" and layer ~= "bg" then layer = "fg" end

    if not tx or not ty or tx < 0 or ty < 0 then return end
    tx = math.floor(tx)
    ty = math.floor(ty)

    local w = getNativeWorld and getNativeWorld()
    if w then
        -- 1. Panggil native tileChanged dari game engine (Sync Visual Chunk + Autotile Neighbors + Grid + Clear Cracks)
        if w.tileChanged then
            pcall(w.tileChanged, layer, tx, ty, newId, false)
        else
            -- Fallback manual jika w.tileChanged belum siap
            local grid = (layer == "bg") and w.bg or w.fg
            if grid and grid[ty] then
                grid[ty][tx] = newId
            end
        end

        -- 2. Bersihkan crack marks / animasi retakan secara instan saat blok hancur (newId == 0)
        if newId == 0 and w.breakTileGone then
            pcall(w.breakTileGone, tx, ty)
        end

        -- 3. Bersihkan cache pohon lokal jika foreground hancur
        if layer == "fg" and newId == 0 and w.setTree then
            pcall(w.setTree, tx, ty, nil)
        end
    end
end

-- ═══════════════════════════════════════
--  PLAYER COORDINATE CALCULATOR
-- ═══════════════════════════════════════
local getNativePhysicsFn

local camTilesCache = {
    camera = nil,
    tiles = nil,
    playerView = nil,
    lastCheck = 0,
    lastPacketX = nil,
    lastPacketY = nil,
    lastPacketTime = 0,
}

local function ensureMovePacketHook()
    pcall(function()
        local netObj = Net or (getgenv and getgenv().SysHub_Net)
        if netObj and netObj.move and netObj.move.send and not rawget(netObj.move, "_syshubTracked") then
            local origSend = netObj.move.send
            rawset(netObj.move, "_syshubTracked", true)
            netObj.move.send = function(packet)
                if type(packet) == "table" and packet.x and packet.y then
                    camTilesCache.lastPacketX = tonumber(packet.x)
                    camTilesCache.lastPacketY = tonumber(packet.y)
                    camTilesCache.lastPacketTime = os.clock()
                end
                return origSend(packet)
            end
        end
    end)
end
ensureMovePacketHook()

local function getCameraAndTiles()
    local now = os.clock()
    if camTilesCache.camera and camTilesCache.camera.Parent and camTilesCache.tiles and camTilesCache.tiles.Parent then
        return camTilesCache.camera, camTilesCache.tiles, camTilesCache.playerView
    end
    if now - camTilesCache.lastCheck < 0.25 then
        return camTilesCache.camera, camTilesCache.tiles, camTilesCache.playerView
    end
    camTilesCache.lastCheck = now

    -- 1. Direct from native engine (100% immune to obfuscated names & zero allocation)
    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    if eng and eng.tilesLayer and eng.tilesLayer.Parent then
        local camera = eng.tilesLayer.Parent
        local tiles = eng.tilesLayer
        local pView = camera:FindFirstChild("PlayerView") or camera:FindFirstChild("Player") or camera:FindFirstChild("Character")
        if not pView and eng.worldFrame then
            pView = eng.worldFrame:FindFirstChild("PlayerView") or eng.worldFrame:FindFirstChild("Player")
        end
        camTilesCache.camera = camera
        camTilesCache.tiles = tiles
        camTilesCache.playerView = pView
        return camera, tiles, pView
    end

    local pgui = PlayerGui
    local gameGui = pgui and pgui:FindFirstChild("GameGui")
    if not gameGui then return nil, nil, nil end

    -- 2. Legacy fallback
    local world = gameGui:FindFirstChild("World")
    local camera = world and world:FindFirstChild("Camera")
    local tiles = camera and camera:FindFirstChild("Tiles")
    local playerView = camera and (camera:FindFirstChild("PlayerView") or camera:FindFirstChild("Player") or camera:FindFirstChild("Character"))
    if camera and tiles then
        camTilesCache.camera = camera
        camTilesCache.tiles = tiles
        camTilesCache.playerView = playerView
        return camera, tiles, playerView
    end

    return nil, nil, nil
end

local function getPlayerTilePos()
    -- Jika di lobby atau WorldPicker terbuka, karakter TIDAK berada di world!
    if isWorldPickerOpen and isWorldPickerOpen() then
        return nil, nil, nil, nil
    end
    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    local worldName = (w and w.name) or (eng and eng.world and eng.world.name)
    if worldName and (string.upper(worldName) == "LOBBY" or worldName == "") then
        return nil, nil, nil, nil
    end
    if not w and not (eng and eng.px and eng.py) then
        return nil, nil, nil, nil
    end

    -- LAYER 0: Direct Native Engine Variables (Zero cost, 100% accurate)
    if eng and eng.px and eng.py then
        local rawX = tonumber(eng.px)
        local rawY = tonumber(eng.py)
        if rawX and rawY and rawX > 0 and rawY > 0 then
            local px = math.floor(rawX)
            local py = math.floor(rawY - 0.475)
            return px, py, rawX, rawY
        end
    end

    -- LAYER 1: Packet Hook Movement Tracker (100% Imun Luraph / Obfuscator)
    ensureMovePacketHook()
    if camTilesCache.lastPacketX and camTilesCache.lastPacketY then
        local rawX = camTilesCache.lastPacketX
        local rawY = camTilesCache.lastPacketY
        local px = math.floor(rawX)
        local py = math.floor(rawY - 0.475)
        return px, py, rawX, rawY
    end

    -- LAYER 2: GUI Resolution (Camera & Tiles Grid Calculation)
    local camera, tiles, playerView = getCameraAndTiles()
    if camera and tiles then
        local pXOffset, pYOffset
        if playerView and playerView.Position then
            pXOffset = playerView.Position.X.Offset
            pYOffset = playerView.Position.Y.Offset
        else
            pXOffset = camera.AbsoluteSize.X / 2
            pYOffset = camera.AbsoluteSize.Y / 2
        end

        local dSize = DISPLAY_SIZE or 64
        if dSize <= 0 then dSize = 64 end
        local rawX = (pXOffset - tiles.Position.X.Offset) / dSize
        local rawY = (pYOffset - tiles.Position.Y.Offset) / dSize

        local px = math.floor(rawX)
        local py = math.floor(rawY - 0.475)

        return px, py, rawX, rawY
    end

    return nil, nil, nil, nil
end

-- Universal Waiter: Menunggu game, World Object, Grid Tiles (w.fg) dan karakter benar-benar ter-load lengkap!
waitForWorldFullyLoaded = function(targetWorld, maxWait)
    if type(targetWorld) == "number" and not maxWait then
        maxWait = targetWorld
        targetWorld = nil
    end
    maxWait = maxWait or 30
    local targetClean = targetWorld and string.upper((string.gsub(tostring(targetWorld), "%s+", ""))) or nil
    local t0 = os.clock()

    -- Invalidate stale world cache sebelum menunggu agar membaca data terbaru
    cachedNativeWorld = nil
    lastWorldCheck = 0

    -- 1. Pastikan game client sudah IsLoaded
    if not game:IsLoaded() then
        repeat task.wait(0.2) until game:IsLoaded() or (os.clock() - t0 > maxWait)
    end

    -- 2. Tunggu Player & GameGui
    local lp = Players.LocalPlayer
    if not lp then
        pcall(function() lp = Players.PlayerAdded:Wait() end)
    end
    if lp then
        local pgui = lp:WaitForChild("PlayerGui", 20)
        if pgui then pgui:WaitForChild("GameGui", 20) end
    end

    -- 3. Tunggu WorldPicker / Lobby benar-benar tertutup (transisi keluar menu selesai)
    while (os.clock() - t0 < maxWait) do
        if not (isWorldPickerOpen and isWorldPickerOpen()) then
            break
        end
        task.wait(0.25)
    end

    -- 4. Tunggu World Object & nama world valid (sesuai targetClean jika di-specify)
    local w = nil
    while (os.clock() - t0 < maxWait) do
        if not (isWorldPickerOpen and isWorldPickerOpen()) then
            w = getNativeWorld and getNativeWorld()
            if w and w.name and w.name ~= "" and string.upper(w.name) ~= "LOBBY" then
                if not targetClean or string.upper(w.name) == targetClean then
                    break
                end
            end
        end
        task.wait(0.3)
    end

    if not w or not w.name or w.name == "" then
        _G.__wflFail = "step4: world nil / tanpa nama"
        return false
    end
    if targetClean and string.upper(w.name) ~= targetClean then
        _G.__wflFail = "step4: world " .. tostring(w.name) .. " ~= target " .. tostring(targetClean)
        return false
    end

    -- 5. Tunggu Grid w.fg benar-benar selesai di-stream dari server (minimal 50 baris valid)
    local fgReady = false
    while (os.clock() - t0 < maxWait) do
        if w.fg and type(w.fg) == "table" then
            local validRows = 0
            for r = 0, (w.h or 60) - 1 do
                if type(w.fg[r]) == "table" and w.fg[r][0] ~= nil then
                    validRows = validRows + 1
                end
            end
            if validRows >= 50 or (w.h and validRows >= math.floor(w.h * 0.8)) then
                fgReady = true
                break
            end
        end
        task.wait(0.3)
    end
    if not fgReady then
        _G.__wflFail = "step5: fg grid belum siap"
        return false
    end

    -- 6. Tunggu posisi karakter (px, py) valid dan berdiri di tile nyata di world
    -- (JANGAN tulis `local px, py = f and f()`: `and` memotong ke 1 nilai -> py selalu nil)
    local posReady = false
    while (os.clock() - t0 < maxWait) do
        if not (isWorldPickerOpen and isWorldPickerOpen()) then
            local px, py = getPlayerTilePos()
            if px and py and px >= 0 and px < (w.w or 100) and py >= 0 and py < (w.h or 60) then
                if w.fg and w.fg[py] and w.fg[py][px] ~= nil then
                    posReady = true
                    break
                end
            end
        end
        task.wait(0.2)
    end
    if not posReady then
        local px, py = getPlayerTilePos()
        _G.__wflFail = string.format("step6: posisi tidak valid px=%s py=%s t=%.1f max=%s", tostring(px), tostring(py), os.clock() - t0, tostring(maxWait))
        return false
    end
    _G.__wflFail = nil

    -- 7. Jeda stabilitas 1.2 detik agar semua event ByteNet & fisika grounded sinkron
    task.wait(1.2)
    return true
end
_G.waitForWorldFullyLoaded = waitForWorldFullyLoaded

-- Forward declaration of Waypoint handler
local setWaypoint
local clearWaypoint

local hookInstalled = false
local function ensureLocateHook()
    local w = getNativeWorld()
    if w and w.locate and not hookInstalled then
        local origLocate = w.locate
        w.locate = function(tx, ty, name)
            if setWaypoint then
                local tileX = math.floor(tx)
                local tileY = math.floor(ty)
                setWaypoint(name or "Target", tileX, tileY)
            end
            return origLocate(tx, ty, name)
        end
        hookInstalled = true
    end
end

local function openNativeGrowScan(mode)
    local w = getNativeWorld()
    if w and w.growScan then
        ensureLocateHook()
        w.growScan.open({
            item = 0,
            owner = true,
            blocksPublic = true,
            floatingPublic = true,
        })

        if mode == "blocks" then
            w.growScan.show("blocks")
        elseif mode == "floating" then
            w.growScan.show("floating")
        end
        return true
    end

    -- Fallback via GUI langsung
    local menuGui = PlayerGui:FindFirstChild("MenuGui")
    local gs = menuGui and menuGui:FindFirstChild("GrowScan")
    if gs then
        gs.Visible = true
        return true
    end

    return false
end

local function closeNativeGrowScan()
    local w = getNativeWorld()
    if w and w.growScan then
        w.growScan.close()
        return true
    end

    local menuGui = PlayerGui:FindFirstChild("MenuGui")
    local gs = menuGui and menuGui:FindFirstChild("GrowScan")
    if gs then
        gs.Visible = false
        return true
    end
    return false
end

