-- Inisialisasi awal status aktif jika terdapat rotasi berjalan dari file state akun
pcall(function()
    local sFile = AutoRotation.getStateFile and AutoRotation.getStateFile() or AutoRotation.STATE_FILE
    local raw = nil
    if isfile and readfile and isfile(sFile) then
        raw = readfile(sFile)
    elseif isfile and readfile and isfile(AutoRotation.STATE_FILE) then
        raw = readfile(AutoRotation.STATE_FILE)
    end
    if raw and raw ~= "" then
        local state = HttpService:JSONDecode(raw)
        if state and state.active == true then
            AutoRotation.active = true
            AutoRotation.status = string.format("[RESUME] Memuat subtask %s...", tostring(state.subtask or "ROTATION"))
        end
    end
end)

AutoRotation.getStorageStandPosition = function(dTileX, dTileY)
    local tx = tonumber(dTileX) or 1
    local ty = tonumber(dTileY) or 1

    -- Pilihan 1 (Utama): Tepat 1 tile di sebelah kiri / sebelum drop spot (tx - 1)
    local leftX = tx - 1
    if leftX >= 0 then
        local isSolid = false
        if isSolidTile then
            local ok, s = pcall(isSolidTile, leftX, ty)
            if ok and s then isSolid = true end
        end
        if not isSolid then
            return leftX, ty
        end
    end

    -- Pilihan 2: Jika sebelah kiri ada tembok/solid atau luar map, coba 1 tile di sebelah kanan (tx + 1)
    local rightX = tx + 1
    if rightX < 100 then
        local isSolid = false
        if isSolidTile then
            local ok, s = pcall(isSolidTile, rightX, ty)
            if ok and s then isSolid = true end
        end
        if not isSolid then
            return rightX, ty
        end
    end

    -- Fallback: Prioritaskan tx - 1 jika tx > 0
    if tx > 0 then return tx - 1, ty end
    return tx + 1, ty
end

AutoRotation.dropAndVerifySeedStorage = function(targetSeedId, dropAmt, dTileX, dTileY)
    if not targetSeedId or not dropAmt or dropAmt <= 0 then return end
    local tx = tonumber(dTileX) or 0
    local ty = tonumber(dTileY) or 0

    local standX, standY = AutoRotation.getStorageStandPosition(tx, ty)
    print(string.format("[ROTATION-SEED] Posisi drop: (%d, %d) | Posisi berdiri sebelum drop: (%d, %d)", tx + 1, ty + 1, standX + 1, standY + 1))
    local reached = walkOrPathfindTo(standX, standY, 100, 60)
    if not reached and approachTile then
        approachTile(standX, standY, 100, 60)
    end
    task.wait(0.2)

    -- Pastikan karakter menghadap ke arah tile drop (bukan membelakangi)
    if sendMovementPacket and standX ~= tx then
        sendMovementPacket({ x = standX + 0.5, y = standY, flags = (standX < tx) and 3 or 2 })
    end
    task.wait(0.1)

    -- Drop seed profit ke target tile (bukan di kaki karakter, sehingga tidak ter-take lagi)
    print(string.format("[ROTATION-SEED] Dropping Seed ID %d x%d ke target drop (%d, %d)...", targetSeedId, dropAmt, tx + 1, ty + 1))
    sendDropPacket(targetSeedId, dropAmt, tx + 0.5, ty + 0.5)

    local inv = getNativeInventory and getNativeInventory()
    if inv and inv.remove then pcall(inv.remove, inv, targetSeedId, dropAmt) end
    AutoRotation.totalProfitDropped = (AutoRotation.totalProfitDropped or 0) + (tonumber(dropAmt) or 0)
    if updateRotationUI then updateRotationUI() end

    task.wait(0.5)
    if AutoShop and AutoShop.syncInventory then pcall(AutoShop.syncInventory) end
end

AutoRotation.dropAndVerifyPackStorageItems = function(itemsToDrop, dTileX, dTileY)
    if not itemsToDrop or type(itemsToDrop) ~= "table" then return end

    -- 1. Delay setelah pembelian pack & tunggu sinkronisasi backpack
    print("[ROTATION-PACK] Delay & sinkronisasi backpack setelah pembelian pack...")
    AutoRotation.status = "[AUTO BUY] Menunggu item pack masuk ke tas..."
    if updateRotationUI then updateRotationUI() end
    task.wait(1.2)

    -- Paksa sinkronisasi inventory resmi dari server
    if AutoShop and AutoShop.syncInventory then
        pcall(AutoShop.syncInventory)
    end

    -- Polling singkat memastikan item dari pack telah masuk ke tas
    local pollStart = os.clock()
    while (os.clock() - pollStart) < 3.5 do
        local hasAny = false
        for itmId, _ in pairs(itemsToDrop) do
            local curStock = (getRealtimeItemCount and getRealtimeItemCount(itmId)) or 0
            if curStock > 0 then
                hasAny = true
                break
            end
        end
        if hasAny then break end
        task.wait(0.3)
        if AutoShop and AutoShop.syncInventory then pcall(AutoShop.syncInventory) end
    end
    task.wait(0.5)

    -- Pastikan posisi karakter berdiri di SEBELUM pos drop (bukan di atas tile drop)
    local standX, standY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
    local curPx, curPy = getPlayerTilePos()
    if curPx and curPy and curPx == dTileX and curPy == dTileY then
        print(string.format("[ROTATION-PACK] Karakter berada di tile drop (%d, %d), mundur ke (%d, %d)...", dTileX + 1, dTileY + 1, standX + 1, standY + 1))
        walkOrPathfindTo(standX, standY, 100, 60)
        task.wait(0.2)
    end
    if sendMovementPacket and standX ~= dTileX then
        sendMovementPacket({ x = standX + 0.5, y = standY, flags = (standX < dTileX) and 3 or 2 })
    end

    -- 2. Drop semua item hasil pack ke storage dengan retry verification
    local maxRounds = 4
    for round = 1, maxRounds do
        local droppedInThisRound = 0
        for itmId, _ in pairs(itemsToDrop) do
            local stock = (getRealtimeItemCount and getRealtimeItemCount(itmId)) or 0
            if stock > 0 then
                print(string.format("[ROTATION-PACK] (Round %d) Dropping Item ID %d x%d ke (%d, %d)...", round, itmId, stock, dTileX + 1, dTileY + 1))
                sendDropPacket(itmId, stock, dTileX + 0.5, dTileY + 0.5)
                local inv = getNativeInventory and getNativeInventory()
                if inv and inv.remove then
                    pcall(inv.remove, inv, itmId, stock)
                end
                AutoRotation.totalPackItemsDropped = (AutoRotation.totalPackItemsDropped or 0) + stock
                droppedInThisRound = droppedInThisRound + stock
                task.wait(0.35)
            end
        end

        task.wait(0.6)
        if AutoShop and AutoShop.syncInventory then
            pcall(AutoShop.syncInventory)
        end

        -- 3. Verifikasi apakah item pack masih ada di backpack sebelum pulang
        local remainingTotal = 0
        for itmId, _ in pairs(itemsToDrop) do
            local curStock = (getRealtimeItemCount and getRealtimeItemCount(itmId)) or 0
            if curStock > 0 then
                remainingTotal = remainingTotal + curStock
            end
        end

        if remainingTotal == 0 then
            print(string.format("[ROTATION-PACK] Verifikasi BERHASIL: Semua item pack telah bersih dari tas (Round %d)!", round))
            AutoRotation.status = "[AUTO BUY] Verifikasi: Semua item pack berhasil di-drop!"
            if updateRotationUI then updateRotationUI() end
            break
        else
            print(string.format("[ROTATION-PACK] Verifikasi: Masih ada %d item pack di tas! Mencoba drop ulang (%d/%d)...", remainingTotal, round, maxRounds))
            AutoRotation.status = string.format("[AUTO BUY] Masih ada %d item di tas, drop ulang (%d/%d)...", remainingTotal, round, maxRounds)
            if updateRotationUI then updateRotationUI() end
            task.wait(0.8)
        end
    end

    if updateRotationUI then updateRotationUI() end
    task.wait(0.5)
end

