AutoShop.syncInventory = function()
    local netObj = Net or (getgenv and getgenv().SysHub_Net)
    if not netObj and filtergc then
        local list = filtergc("table", { Keys = {"tile", "act", "call", "drop"} }, false)
        if list and list[1] then
            netObj = list[1]
            if getgenv then getgenv().SysHub_Net = netObj end
        end
    end
    if not netObj or not netObj.call then return false end
    local ok, res = pcall(netObj.call, "GetInventory")
    if ok and type(res) == "table" and type(res.slots) == "table" then
        local inv = getNativeInventory and getNativeInventory()
        if inv then
            if type(res.capacity) == "number" then
                inv.capacity = res.capacity
            end
            if type(inv.slots) == "table" then
                table.clear(inv.slots)
                for _, it in ipairs(res.slots) do
                    if inv.add then
                        pcall(inv.add, inv, it[1], it[2])
                    else
                        table.insert(inv.slots, { it[1], it[2] })
                    end
                end
            end
            if inv.changed and inv.changed.Fire then
                pcall(inv.changed.Fire, inv.changed)
            end
        end
        if refreshInventory then pcall(refreshInventory) end
        return true, res
    end
    return false
end

AutoShop.getGems = function()
    local netObj = Net or (getgenv and getgenv().SysHub_Net)
    if not netObj and filtergc then
        local list = filtergc("table", { Keys = {"tile", "act", "call", "drop"} }, false)
        if list and list[1] then
            netObj = list[1]
            if getgenv then getgenv().SysHub_Net = netObj end
        end
    end
    if not netObj or not netObj.call then return AutoShop.cachedGems or 0 end
    local ok, res = pcall(netObj.call, "GetGems")
    if ok and type(res) == "number" then
        AutoShop.cachedGems = res
        return res
    end
    return AutoShop.cachedGems or 0
end

AutoShop.getDynamicPrices = function()
    local raw = nil
    pcall(function()
        raw = game:GetService("ReplicatedStorage"):GetAttribute("StorePrices")
    end)
    if raw and type(raw) == "string" and raw ~= "" then
        local ok, map = pcall(function() return HttpService:JSONDecode(raw) end)
        if ok and type(map) == "table" then
            return map
        end
    end
    return {}
end

local function getStoreModule()
    if AutoShop.cachedStore then return AutoShop.cachedStore end

    if filtergc then
        local storeList = filtergc("table", { Keys = {"OFFERS", "byKey"} }, false)
        if storeList then
            for _, s in ipairs(storeList) do
                if s.byKey and s.byKey.world_lock and (s.byKey.world_lock.basePrice or (s.byKey.world_lock.price and s.byKey.world_lock.price > 2000)) then
                    AutoShop.cachedStore = s
                    return s
                end
            end
            if storeList[1] then
                AutoShop.cachedStore = storeList[1]
                return storeList[1]
            end
        end
    end
    return nil
end

AutoShop.syncPrices = function()
    local Store = getStoreModule()
    local dynMap = AutoShop.getDynamicPrices and AutoShop.getDynamicPrices() or {}
    if Store and Store.OFFERS then
        for _, j in ipairs(Store.OFFERS) do
            if not j.robux and type(j.price) == "number" then
                j.basePrice = j.basePrice or (j.upgrade and Store.BACKPACK and Store.BACKPACK.price) or j.price
                local v = tonumber(dynMap[j.key])
                if v and v >= 0 then
                    j.price = math.floor(v)
                else
                    j.price = j.basePrice
                end
                if j.upgrade and Store.BACKPACK then
                    Store.BACKPACK.price = j.price
                end
            end
        end
    end
end

AutoShop.getAllOffers = function()
    local Store = getStoreModule()
    if not Store then return {} end
    if AutoShop.syncPrices then AutoShop.syncPrices() end
    local dynMap = AutoShop.getDynamicPrices and AutoShop.getDynamicPrices() or {}
    local list = {}
    local seen = {}
    local function add(o)
        if not o then return end
        -- Filter out robux, hidden, disabled, non-positive price, donate, gems
        if o.robux or o.hidden or o.hide or o.disabled or o.status == "hidden" or o.available == false then return end
        if o.tab == "donate" or o.tab == "gems" then return end
        if dynMap[o.key] ~= nil then
            local numP = tonumber(dynMap[o.key])
            if numP and numP >= 0 then o.price = math.floor(numP) end
        end
        if type(o.price) ~= "number" or o.price <= 0 then return end
        if not seen[o.key] then
            seen[o.key] = true
            table.insert(list, o)
        end
    end
    -- Hanya membaca Store.OFFERS yang aktif di store game, Store.HELD (hidden/vaulted) tidak dimasukkan
    for _, o in ipairs(Store.OFFERS or {}) do add(o) end
    return list
end

AutoShop.getOfferByKey = function(key)
    if not key then return nil end
    local Store = getStoreModule()
    if not Store then return nil end
    if AutoShop.syncPrices then AutoShop.syncPrices() end
    local targetOffer = nil
    if Store.byKey and Store.byKey[key] then
        local o = Store.byKey[key]
        if not o.robux and not o.hidden and not o.hide and not o.disabled and o.tab ~= "donate" and o.tab ~= "gems" then
            targetOffer = o
        end
    end
    if not targetOffer then
        for _, o in ipairs(Store.OFFERS or {}) do
            if o.key == key and not o.robux and not o.hidden and not o.hide and not o.disabled and o.tab ~= "donate" and o.tab ~= "gems" then
                targetOffer = o
                break
            end
        end
    end
    if targetOffer then
        local dynMap = AutoShop.getDynamicPrices and AutoShop.getDynamicPrices() or {}
        if dynMap[key] ~= nil then
            local numP = tonumber(dynMap[key])
            if numP and numP >= 0 then targetOffer.price = math.floor(numP) end
        end
    end
    return targetOffer
end

AutoShop.getOfferPrice = function(key)
    if not key then return 0 end
    local dynMap = AutoShop.getDynamicPrices and AutoShop.getDynamicPrices() or {}
    if dynMap[key] ~= nil then
        local numP = tonumber(dynMap[key])
        if numP and numP >= 0 then return math.floor(numP) end
    end
    local off = AutoShop.getOfferByKey(key)
    return off and off.price or 0
end

AutoShop.buyPack = function(key, count)
    local netObj = Net or (getgenv and getgenv().SysHub_Net)
    if not netObj and filtergc then
        local list = filtergc("table", { Keys = {"tile", "act", "call", "drop"} }, false)
        if list and list[1] then
            netObj = list[1]
            if getgenv then getgenv().SysHub_Net = netObj end
        end
    end
    if not netObj or not netObj.call then return false, {} end
    local cnt = math.max(1, tonumber(count) or 1)
    local bought = 0
    local allItems = {}
    local inv = getNativeInventory and getNativeInventory()

    for i = 1, cnt do
        local ok, success, data = pcall(netObj.call, "BuyItem", key, (inv and inv.slots) or nil)
        if ok and success then
            bought = bought + 1
            if type(data) == "table" and data.items then
                for _, it in ipairs(data.items) do
                    allItems[it[1]] = true
                    if inv and inv.add then
                        pcall(inv.add, inv, it[1], it[2])
                    end
                end
                if inv and inv.changed and inv.changed.Fire then
                    pcall(inv.changed.Fire, inv.changed)
                end
            end
            if type(data) == "table" and type(data.gems) == "number" then
                AutoShop.cachedGems = data.gems
            end
            if Sfx and Sfx.play then pcall(Sfx.play, "buy") end
        else
            break
        end
        if cnt > 1 then task.wait(0.35) end
    end

    local offer = AutoShop.getOfferByKey(key)
    if offer and offer.items then
        for _, it in ipairs(offer.items) do
            allItems[it[1]] = true
        end
    end

    if bought > 0 then
        if AutoShop.syncInventory then pcall(AutoShop.syncInventory) end
        if refreshInventory then pcall(refreshInventory) end
    end

    return bought, allItems
end

task.spawn(function()
    while true do
        task.wait(3.0)
        pcall(AutoShop.getGems)
    end
end)

-- Realtime listener agar harga pack selalu sinkron otomatis saat server mengubah harga
