    local rs = game:GetService("ReplicatedStorage")
    rs:GetAttributeChangedSignal("StorePrices"):Connect(function()
        if AutoShop and AutoShop.syncPrices then pcall(AutoShop.syncPrices) end
        if AutoShop and AutoShop.updateUI then pcall(AutoShop.updateUI) end
        if updateRotationUI then pcall(updateRotationUI) end
    end)
end)

-- =========================================================================
-- PERSISTENT ROTATION STATE MACHINE (Cross-Server & Cross-Warp Persistence)
-- =========================================================================
AutoRotation.saveState = function(data)
    if not writefile then return end
    local state = {
        active            = (data and data.active ~= nil) and (data.active == true) or (AutoRotation.active == true),
        subtask           = (data and data.subtask) or "ROTATION_LOOP",
        currentWorldIndex = (data and data.currentWorldIndex) or AutoRotation.currentWorldIndex or 1,
        farmWorld         = (data and data.farmWorld) or (AutoRotation.worlds and AutoRotation.worlds[AutoRotation.currentWorldIndex or 1] and AutoRotation.worlds[AutoRotation.currentWorldIndex or 1].worldName) or "",
        farmDoor          = (data and data.farmDoor) or (AutoRotation.worlds and AutoRotation.worlds[AutoRotation.currentWorldIndex or 1] and AutoRotation.worlds[AutoRotation.currentWorldIndex or 1].door) or "",
        seedId            = (data and data.seedId) or AutoRotation.targetSeedId or 3,
        storageWorld      = (data and data.storageWorld) or AutoRotation.storageWorld or "",
        storageDoor       = (data and data.storageDoor) or AutoRotation.storageDoor or "",
        storageDropX      = (data and data.storageDropX) or AutoRotation.storageDropX,
        storageDropY      = (data and data.storageDropY) or AutoRotation.storageDropY,
        dropAmt           = (data and data.dropAmt) or AutoRotation.seedProfitToDrop or 100,
        packStorageWorld  = (data and data.packStorageWorld) or AutoRotation.packStorageWorld or "",
        packStorageDoor   = (data and data.packStorageDoor) or AutoRotation.packStorageDoor or "",
        packStorageDropX  = (data and data.packStorageDropX) or AutoRotation.packStorageDropX,
        packStorageDropY  = (data and data.packStorageDropY) or AutoRotation.packStorageDropY,
        buyPackKey        = (data and data.buyPackKey) or AutoRotation.buyPackKey or "world_lock",
        buyPackCount      = (data and data.buyPackCount) or AutoRotation.buyPackCount or 1,
        worlds            = AutoRotation.worlds or {},
        timestamp         = os.time(),
    }
    local sFile = AutoRotation.getStateFile and AutoRotation.getStateFile() or AutoRotation.STATE_FILE
    pcall(writefile, sFile, HttpService:JSONEncode(state))
end

AutoRotation.clearState = function()
    local sFile = AutoRotation.getStateFile and AutoRotation.getStateFile() or AutoRotation.STATE_FILE
    if isfile and delfile then
        if isfile(sFile) then pcall(delfile, sFile) end
        if isfile(AutoRotation.STATE_FILE) then pcall(delfile, AutoRotation.STATE_FILE) end
    end
    if writefile then
        pcall(writefile, sFile, HttpService:JSONEncode({ active = false }))
    end
end

AutoRotation.checkResume = function()
    if AutoRotation.busyResuming then return end
    local sFile = AutoRotation.getStateFile and AutoRotation.getStateFile() or AutoRotation.STATE_FILE
    if not isfile or not readfile then return end
    local fileToRead = nil
    if isfile(sFile) then
        fileToRead = sFile
    elseif isfile(AutoRotation.STATE_FILE) then
        fileToRead = AutoRotation.STATE_FILE
    end
    if not fileToRead then return end
    local ok, raw = pcall(readfile, fileToRead)
    if not ok or not raw or raw == "" then return end
    local ok_dec, state = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok_dec or type(state) ~= "table" or not state.active then return end

    AutoRotation.busyResuming = true
    AutoRotation.active = true
    AutoRotation.status = string.format("[RESUME] Memuat subtask %s...", tostring(state.subtask or "ROTATION_LOOP"))
    if updateRotationUI then updateRotationUI() end

    task.spawn(function()
        local targetWorld = (state.subtask == "DROP_SEED_STORAGE" and state.storageWorld) or
                            (state.subtask == "BUY_PACK_STORAGE" and state.packStorageWorld) or
                            state.farmWorld or ""
        targetWorld = string.upper((tostring(targetWorld):gsub("%s+", "")))

        if targetWorld == "" and state.worlds and #state.worlds > 0 then
            local idx = tonumber(state.currentWorldIndex) or 1
            local wEntry = state.worlds[idx] or state.worlds[1]
            targetWorld = wEntry and string.upper((tostring(wEntry.worldName or ""):gsub("%s+", ""))) or ""
        end

        print(string.format("[ROTATION-STATE] Ditemukan task rotasi tersimpan: Subtask=%s | TargetWorld=%s | Queue=%d",
            tostring(state.subtask), tostring(targetWorld), state.currentWorldIndex or 1))

        -- 1. Tunggu keluar dari Lobby / WorldPicker (maks 25s)
        local lobbyWait = 0
        while (isWorldPickerOpen and isWorldPickerOpen()) and lobbyWait < 25 do
            if targetWorld ~= "" and lobbyWait >= 2 and nativeJoinWorld then
                print(string.format("[ROTATION-RESUME] Menghubungkan nativeJoinWorld [%s] dari Lobby...", targetWorld))
                nativeJoinWorld(targetWorld)
                task.wait(2.5)
            else
                task.wait(0.5)
            end
            lobbyWait = lobbyWait + 1
        end

        -- 2. Tunggu world saat ini ter-load penuh (tanpa membatasi targetWorld dulu agar tidak timeout 30s)
        local loaded = waitForWorldFullyLoaded(nil, 25)
        if not loaded then
            print("[ROTATION-RESUME] ⚠️ Menunggu stabilisasi world...")
            task.wait(1.5)
            loaded = waitForWorldFullyLoaded(nil, 15)
        end

        -- 2. Restore data & aktifkan toggle di UI
        AutoRotation.active = true
        if state.currentWorldIndex then
            AutoRotation.currentWorldIndex = tonumber(state.currentWorldIndex) or 1
        end
        if (not AutoRotation.worlds or #AutoRotation.worlds == 0) and state.worlds and #state.worlds > 0 then
            AutoRotation.worlds = state.worlds
            if refreshRotationWorldList then refreshRotationWorldList() end
        end
        if state.storageWorld and state.storageWorld ~= "" then AutoRotation.storageWorld = state.storageWorld end
        if state.storageDoor ~= nil then AutoRotation.storageDoor = state.storageDoor end
        if state.storageDropX ~= nil then AutoRotation.storageDropX = state.storageDropX end
        if state.storageDropY ~= nil then AutoRotation.storageDropY = state.storageDropY end
        if state.packStorageWorld and state.packStorageWorld ~= "" then AutoRotation.packStorageWorld = state.packStorageWorld end
        if state.packStorageDoor ~= nil then AutoRotation.packStorageDoor = state.packStorageDoor end
        if state.packStorageDropX ~= nil then AutoRotation.packStorageDropX = state.packStorageDropX end
        if state.packStorageDropY ~= nil then AutoRotation.packStorageDropY = state.packStorageDropY end
        if state.buyPackKey ~= nil then AutoRotation.buyPackKey = state.buyPackKey end
        if state.buyPackCount ~= nil then AutoRotation.buyPackCount = tonumber(state.buyPackCount) or 1 end
        if state.dropAmt ~= nil then AutoRotation.seedProfitToDrop = tonumber(state.dropAmt) or 100 end

        if updateRotationUI then updateRotationUI() end

        local w = getNativeWorld and getNativeWorld()
        local currentWorld = (w and w.name and string.upper(w.name)) or ""

        -- SUBTASK 1: DROP_SEED_STORAGE (Tiba di Storage World untuk drop seed profit)
        if state.subtask == "DROP_SEED_STORAGE" then
            local sWorld = string.upper((tostring(state.storageWorld or ""):gsub("%s+", "")))
            if currentWorld == sWorld then
                print(string.format("[ROTATION-RESUME] Tiba di Storage World [%s]! Melakukan drop %d seed...", currentWorld, state.dropAmt or 100))
                AutoRotation.status = string.format("[RESUME] Drop %d bibit di Storage [%s]...", state.dropAmt or 100, currentWorld)
                if updateRotationUI then updateRotationUI() end

                task.wait(0.5)
                local dTileX = (tonumber(state.storageDropX) or 1) - 1
                local dTileY = (tonumber(state.storageDropY) or 1) - 1
                local sId = tonumber(state.seedId) or AutoRotation.targetSeedId or 3
                local dAmt = tonumber(state.dropAmt) or 100

                if AutoRotation.dropAndVerifySeedStorage then
                    AutoRotation.dropAndVerifySeedStorage(sId, dAmt, dTileX, dTileY)
                else
                    local standTileX, standTileY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
                    walkOrPathfindTo(standTileX, standTileY, 100, 60)
                    task.wait(0.2)
                    sendDropPacket(sId, dAmt, dTileX + 0.5, dTileY + 0.5)
                    local inv = getNativeInventory and getNativeInventory()
                    if inv and inv.remove then pcall(inv.remove, inv, sId, dAmt) end
                    AutoRotation.totalProfitDropped = (AutoRotation.totalProfitDropped or 0) + (tonumber(dAmt) or 0)
                end
                task.wait(0.8)

                AutoRotation.saveState({
                    subtask = "RETURN_FROM_SEED_STORAGE",
                    currentWorldIndex = state.currentWorldIndex,
                    farmWorld = state.farmWorld,
                    farmDoor = state.farmDoor,
                })
                print(string.format("[ROTATION-RESUME] Drop selesai! Warp kembali ke Farm World [%s]...", state.farmWorld))
                AutoRotation.status = string.format("Warp kembali ke Farm World [%s]...", state.farmWorld)
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                warpToWorld(state.farmWorld, state.farmDoor)
                return
            else
                print(string.format("[ROTATION-RESUME] Menuju Storage World [%s]...", sWorld))
                AutoRotation.status = string.format("Menuju Storage World [%s]...", sWorld)
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                warpToWorld(sWorld, state.storageDoor)
                return
            end

        -- SUBTASK 2: BUY_PACK_STORAGE (Tiba di Storage Pack World untuk beli pack & drop isi pack)
        elseif state.subtask == "BUY_PACK_STORAGE" then
            local pWorld = string.upper((tostring(state.packStorageWorld or ""):gsub("%s+", "")))
            if currentWorld == pWorld then
                print(string.format("[ROTATION-RESUME] Tiba di Storage Pack [%s]! Membeli %dx %s & drop...", currentWorld, state.buyPackCount or 1, state.buyPackKey or "pack"))
                AutoRotation.status = string.format("[RESUME] Beli %dx %s & drop di Storage Pack...", state.buyPackCount or 1, state.buyPackKey or "pack")
                if updateRotationUI then updateRotationUI() end

                task.wait(1.0)
                local dTileX = (tonumber(state.packStorageDropX) or 1) - 1
                local dTileY = (tonumber(state.packStorageDropY) or 1) - 1
                local standTileX, standTileY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
                local reached = walkOrPathfindTo(standTileX, standTileY, 100, 60)
                if not reached and approachTile then
                    approachTile(standTileX, standTileY, 100, 60)
                end
                task.wait(0.2)

                local packKey = state.buyPackKey or "world_lock"
                local packCount = tonumber(state.buyPackCount) or 1
                local bought, itemsToDrop = AutoShop.buyPack(packKey, packCount)
                AutoRotation.totalPacksBought = (AutoRotation.totalPacksBought or 0) + bought

                if AutoRotation.dropAndVerifyPackStorageItems then
                    AutoRotation.dropAndVerifyPackStorageItems(itemsToDrop, dTileX, dTileY)
                end

                if updateRotationUI then updateRotationUI() end
                task.wait(0.8)

                AutoRotation.saveState({
                    subtask = "RETURN_FROM_PACK_STORAGE",
                    currentWorldIndex = state.currentWorldIndex,
                    farmWorld = state.farmWorld,
                    farmDoor = state.farmDoor,
                })
                print(string.format("[ROTATION-RESUME] Beli & drop selesai! Warp kembali ke Farm World [%s]...", state.farmWorld))
                AutoRotation.status = string.format("Warp kembali ke Farm World [%s]...", state.farmWorld)
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                warpToWorld(state.farmWorld, state.farmDoor)
                return
            else
                print(string.format("[ROTATION-RESUME] Menuju Storage Pack [%s]...", pWorld))
                AutoRotation.status = string.format("Menuju Storage Pack [%s]...", pWorld)
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                warpToWorld(pWorld, state.packStorageDoor)
                return
            end

        -- SUBTASK 3: RETURN_FROM_SEED_STORAGE, RETURN_FROM_PACK_STORAGE, NEXT_FARM_WORLD, atau ROTATION_LOOP
        else
            local fWorld = string.upper((tostring(state.farmWorld or ""):gsub("%s+", "")))
            if fWorld == "" and #AutoRotation.worlds > 0 then
                local cEntry = AutoRotation.worlds[AutoRotation.currentWorldIndex or 1]
                fWorld = cEntry and string.upper((tostring(cEntry.worldName or ""):gsub("%s+", ""))) or ""
            end

            if currentWorld == fWorld then
                print(string.format("[ROTATION-RESUME] Tiba di Farm World [%s]! Melanjutkan rotasi PnB...", currentWorld))
                AutoRotation.status = string.format("Melanjutkan rotasi di [%s]...", currentWorld)
                AutoRotation.saveState({
                    subtask = "ROTATION_LOOP",
                    currentWorldIndex = AutoRotation.currentWorldIndex,
                    farmWorld = currentWorld,
                    farmDoor = state.farmDoor or "",
                })
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                if startAutoRotation then
                    startAutoRotation()
                end
            else
                print(string.format("[ROTATION-RESUME] Menghubungkan ke Farm World tujuan [%s]...", fWorld))
                AutoRotation.status = string.format("Menghubungkan ke Farm World [%s]...", fWorld)
                if updateRotationUI then updateRotationUI() end
                AutoRotation.busyResuming = false
                warpToWorld(fWorld, state.farmDoor)
            end
        end
    end)
end

