-- ═══════════════════════════════════════
--  MOBILITY: SPEED CONTROLLER
-- ═══════════════════════════════════════
local Mobility = {
    speedEnabled    = false,
    speedMultiplier = 2.0,       -- Kecepatan lari (default 2.0x)
    hookInstalled   = false,
}

local function applySpeedMode()
    local w = getNativeWorld()
    if w then
        if Mobility.speedEnabled then
            w.speedScale = Mobility.speedMultiplier
        else
            w.speedScale = 1.0
        end
    end
end

local cachedPhysicsFn = nil
local lastPhysicsCheck = 0
getNativePhysicsFn = function()
    if cachedPhysicsFn then return cachedPhysicsFn end
    local now = os.clock()
    if now - lastPhysicsCheck < 1 then return nil end
    lastPhysicsCheck = now

    if not (getconnections and debug and debug.getupvalues) then return nil end
    pcall(function()
        for _, conn in ipairs(getconnections(RunService.RenderStepped)) do
            if type(conn.Function) == "function" then
                local upvals = debug.getupvalues(conn.Function)
                for _, v in pairs(upvals) do
                    if type(v) == "table" and v.w and v.h and v.fg then
                        cachedPhysicsFn = conn.Function
                        return
                    end
                end
            end
        end
    end)
    return cachedPhysicsFn
end

local function ensureMobilityHooks()
    local w = getNativeWorld()
    if w and not Mobility.hookInstalled then
        Mobility.hookInstalled = true
    end
    if w and Mobility.speedEnabled then
        w.speedScale = Mobility.speedMultiplier
    end
    getNativePhysicsFn()
end

local function setInternalPlayerPos(newX, newY)
    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    if w and w.goTo then
        pcall(w.goTo, newX - 0.5, newY - 1)
    end
    if eng then
        pcall(function()
            eng.px = newX
            eng.py = newY
            eng.vx = 0
            eng.vy = 0
            eng.grounded = true
        end)
    end
end

-- ═══════════════════════════════════════
--  SAFE NETWORK MOVEMENT (PREVENT BYTENET U16 NIL CRASH)
-- ═══════════════════════════════════════
local function safeSendMove(data)
    if not (Net and Net.move and Net.move.send) then return false end

    -- Self-heal ByteNet client buffer if corrupted by any prior crash
    pcall(function()
        local client = require(ReplicatedStorage.ByteNet.process.client)
        if client and client.sendUnreliable and debug and debug.getupvalue and debug.setupvalue then
            local _, val = debug.getupvalue(client.sendUnreliable, 1)
            if val == nil then
                debug.setupvalue(client.sendUnreliable, 1, { cursor = 0, size = 256, references = {}, buff = buffer.create(256) })
            end
        end
    end)

    local curTick = math.floor(os.clock() * 1000) % 65536
    local vx = tonumber(data.vx) or 0
    local vy = tonumber(data.vy) or 0
    local facingBit = (vx >= 0) and 1 or 0
    -- Prioritaskan data.flags jika ditentukan caller (misal arah facing kustom), fallback ke grounded + facingBit
    local finalFlags = (data.flags ~= nil and tonumber(data.flags)) or (2 + facingBit)

    local packet = {
        x = tonumber(data.x) or 0,
        y = tonumber(data.y) or 0,
        vx = vx,
        vy = vy,
        flags = finalFlags,
        t = tonumber(data.t) or curTick,
    }

    local success, _ = pcall(function()
        Net.move.send(packet)
    end)
    if success and packet.x and packet.y and packet.x > 0 and packet.y > 0 then
        camTilesCache.lastPacketX = packet.x
        camTilesCache.lastPacketY = packet.y
        camTilesCache.lastPacketTime = os.clock()
    end
    return success
end

-- Global Hook Net.move.send dinonaktifkan:
-- Game native physics sudah menghitung grounded & collision secara akurat.
-- Membiarkan packet native lewat apa adanya mencegah bug visual karakter stuck animasi lompat di layar orang lain.

-- ═══════════════════════════════════════
--  FAST INVENTORY (FAST DROP & RECYCLE)
-- ═══════════════════════════════════════
local FastInventory = {
    fastDrop = false,
    fastRecycle = false,
    customCountEnabled = false,
    customCount = 1,
}
local ensureFastInventoryOverlays

do
    local fastDropOverlay = nil
    local fastRecycleOverlay = nil

    local function executeFastDrop()
        local inv = getNativeInventory()
        local selected = inv and inv.selected
        if not selected then return end

        local totalCount = 0
        if inv.count then
            local ok, c = pcall(inv.count, inv, selected)
            if ok and type(c) == "number" then totalCount = c end
        end
        if totalCount <= 0 and inv.slots then
            for _, s in ipairs(inv.slots) do
                if (s.id or s[1]) == selected then
                    totalCount = s.n or s[2] or 0
                    break
                end
            end
        end
        if totalCount <= 0 then return end

        local dropCount = totalCount
        if FastInventory.customCountEnabled and FastInventory.customCount and FastInventory.customCount > 0 then
            dropCount = math.min(math.floor(FastInventory.customCount), totalCount)
        end
        if dropCount <= 0 then return end

        local db = ItemDB and ItemDB[selected]
        local curr = getInventoryUICurrent()
        if db and (db.kind == "tool" or db.untradeable) then
            if curr and curr.onSay then curr.onSay("You can't drop that.") end
            return
        end
        if curr and curr.canDrop and not curr.canDrop(selected) then
            if curr and curr.onSay then curr.onSay("You can't drop that.") end
            return
        end

        local px, py, rawX, rawY = getPlayerTilePos()
        local dropX = (rawX or (px and px + 0.5) or 50) + 1.0
        local dropY = (rawY or (py and py + 1.0) or 30) - 0.45

        local handled = false
        if curr and curr.onDrop then
            local ok = pcall(curr.onDrop, selected, dropCount)
            if ok then handled = true end
        end

        if not handled then
            sendDropPacket(selected, dropCount, dropX, dropY)
            if inv.remove then
                pcall(inv.remove, inv, selected, dropCount)
            end
            if Sfx and Sfx.play then pcall(Sfx.play, "object_spawn2") end
        end

        if curr and curr.refresh then pcall(curr.refresh) end
    end

    local function executeFastRecycle()
        local inv = getNativeInventory()
        local selected = inv and inv.selected
        if not selected then return end

        local totalCount = 0
        if inv.count then
            local ok, c = pcall(inv.count, inv, selected)
            if ok and type(c) == "number" then totalCount = c end
        end
        if totalCount <= 0 and inv.slots then
            for _, s in ipairs(inv.slots) do
                if (s.id or s[1]) == selected then
                    totalCount = s.n or s[2] or 0
                    break
                end
            end
        end
        if totalCount <= 0 then return end

        local recCount = totalCount
        if FastInventory.customCountEnabled and FastInventory.customCount and FastInventory.customCount > 0 then
            recCount = math.min(math.floor(FastInventory.customCount), totalCount)
        end
        if recCount <= 0 then return end

        local db = ItemDB and ItemDB[selected]
        local curr = getInventoryUICurrent()
        if db and db.kind == "tool" then
            if curr and curr.onSay then curr.onSay("You can't recycle that.") end
            return
        end

        if inv.remove then
            pcall(inv.remove, inv, selected, recCount)
        end

        local handled = false
        if curr and curr.onRecycle then
            local ok = pcall(curr.onRecycle, selected, recCount)
            if ok then handled = true end
        end

        if not handled then
            sendRecyclePacket(selected, recCount)
        end

        if Sfx and Sfx.play then pcall(Sfx.play, "trash") end
        local name = db and db.name or ("Item #" .. selected)
        if curr and curr.onSay then
            pcall(curr.onSay, string.format("Recycled %d %s", recCount, name))
        end
        if curr and curr.refresh then pcall(curr.refresh) end
    end

    ensureFastInventoryOverlays = function()
        pcall(function()
            local LP = Players.LocalPlayer
            local ig = LP and LP:FindFirstChild("PlayerGui") and LP.PlayerGui:FindFirstChild("InventoryGui")
            if not ig then return end
            local holder = ig:FindFirstChild("Holder")
            local backpack = holder and holder:FindFirstChild("Backpack")
            local actions = backpack and backpack:FindFirstChild("Actions")
            if not actions then return end

            if not fastDropOverlay or fastDropOverlay.Parent ~= actions then
                local existing = actions:FindFirstChild("SyshubFastDropOverlay")
                if existing then existing:Destroy() end

                fastDropOverlay = Instance.new("TextButton")
                fastDropOverlay.Name = "SyshubFastDropOverlay"
                fastDropOverlay.Size = UDim2.fromOffset(63, 26)
                fastDropOverlay.Position = UDim2.fromOffset(1, 98)
                fastDropOverlay.BackgroundTransparency = 1
                fastDropOverlay.Text = ""
                fastDropOverlay.ZIndex = 50
                fastDropOverlay.Parent = actions

                fastDropOverlay.Activated:Connect(function()
                    if FastInventory.fastDrop then
                        executeFastDrop()
                    end
                end)
            end

            if not fastRecycleOverlay or fastRecycleOverlay.Parent ~= actions then
                local existing = actions:FindFirstChild("SyshubFastRecycleOverlay")
                if existing then existing:Destroy() end

                fastRecycleOverlay = Instance.new("TextButton")
                fastRecycleOverlay.Name = "SyshubFastRecycleOverlay"
                fastRecycleOverlay.Size = UDim2.fromOffset(63, 26)
                fastRecycleOverlay.Position = UDim2.fromOffset(1, 36)
                fastRecycleOverlay.BackgroundTransparency = 1
                fastRecycleOverlay.Text = ""
                fastRecycleOverlay.ZIndex = 50
                fastRecycleOverlay.Parent = actions

                fastRecycleOverlay.Activated:Connect(function()
                    if FastInventory.fastRecycle then
                        executeFastRecycle()
                    end
                end)
            end

            if fastDropOverlay then
                fastDropOverlay.Visible = FastInventory.fastDrop
                fastDropOverlay.Active = FastInventory.fastDrop
            end
            if fastRecycleOverlay then
                fastRecycleOverlay.Visible = FastInventory.fastRecycle
                fastRecycleOverlay.Active = FastInventory.fastRecycle
            end
        end)
    end

    local function setupDialogAutoDismiss()
        pcall(function()
            local LP = Players.LocalPlayer
            local ig = LP and LP:FindFirstChild("PlayerGui") and LP.PlayerGui:FindFirstChild("InventoryGui")
            if not ig then return end
            local dlg = ig:FindFirstChild("InfoDialog")
            if not dlg or dlg:GetAttribute("SyshubWatched") then return end
            dlg:SetAttribute("SyshubWatched", true)

            local function checkDismiss()
                if not dlg.Visible then return end
                if not FastInventory.fastDrop and not FastInventory.fastRecycle then return end

                local rows = dlg:FindFirstChild("Rows")
                if not rows then return end

                local okBtn = rows:FindFirstChild("OK")
                if not okBtn then return end

                -- Immediately hide dialog from screen
                dlg.Visible = false

                -- If custom count enabled, fill textbox
                if FastInventory.customCountEnabled and FastInventory.customCount and FastInventory.customCount > 0 then
                    for _, d in ipairs(rows:GetDescendants()) do
                        if d:IsA("TextBox") then
                            d.Text = tostring(math.floor(FastInventory.customCount))
                            break
                        end
                    end
                end

                -- Trigger OK button
                pcall(function()
                    if getconnections then
                        for _, conn in ipairs(getconnections(okBtn.Activated)) do
                            if type(conn.Function) == "function" then
                                conn.Function()
                            end
                        end
                    end
                end)
            end

            dlg:GetPropertyChangedSignal("Visible"):Connect(checkDismiss)
            dlg.ChildAdded:Connect(function(c)
                if c.Name == "Rows" then
                    task.defer(checkDismiss)
                end
            end)
        end)
    end

    -- Initialize overlays and maintain periodically
    ensureFastInventoryOverlays()
    setupDialogAutoDismiss()

    task.spawn(function()
        while true do
            task.wait(1.5)
            ensureFastInventoryOverlays()
            setupDialogAutoDismiss()
        end
    end)
end

-------------------------------------------------------------------------------
--  CAMERA ZOOM: UNLOCKED NATIVE GAME CAMERA (INFINITE ZOOM OUT)
-------------------------------------------------------------------------------
local CameraZoom = {
    enabled = false,
    zoomScale = 0.5,
    minZoom = 0.08,
    apply = nil,
    updateUI = nil,
}
getgenv().CameraZoom = CameraZoom

do
    CameraZoom.apply = function()
        pcall(function()
            local eng, w = getNativeEngine()
            w = w or (eng and eng.world)
            if CameraZoom.enabled then
                if eng then
                    eng.ZOOM_MIN = CameraZoom.minZoom or 0.08
                    eng.zoomTarget = math.clamp(CameraZoom.zoomScale or 0.5, eng.ZOOM_MIN, 2.5)
                    eng.zoom = eng.zoomTarget
                end
                if w then
                    w.zoomMin = CameraZoom.minZoom or 0.08
                    w.lowGfx = false
                end
            else
                if eng then
                    eng.ZOOM_MIN = 0.6
                    eng.zoomTarget = 0.6
                    eng.zoom = 0.6
                end
                if w then
                    w.zoomMin = 0.6
                    w.zoomOut = 1.0
                end
            end
        end)
    end

    -- Background enforcer agar zoomMin tetap unlock saat ganti world / respawn & realloc full pool (102x62)
    local lastZoomWorld = nil
    task.spawn(function()
        while true do
            task.wait(0.75)
            if CameraZoom.enabled then
                pcall(function()
                    local w = getNativeWorld()
                    local lp = Players.LocalPlayer
                    if w and lp then
                        local shouldRealloc = false
                        if w.zoomMin ~= (CameraZoom.minZoom or 0.08) then
                            w.zoomMin = CameraZoom.minZoom or 0.08
                            shouldRealloc = true
                        end
                        if w.lowGfx ~= false then
                            w.lowGfx = false
                        end
                        if lastZoomWorld ~= w.name then
                            lastZoomWorld = w.name
                            shouldRealloc = true
                        end
                        if shouldRealloc then
                            if CameraZoom.zoomScale then
                                w.zoomOut = math.clamp(CameraZoom.zoomScale, w.zoomMin, 2.0)
                            end
                            lp:SetAttribute("ModZoom", not lp:GetAttribute("ModZoom"))
                        end
                    end
                end)
            end
        end
    end)
end

-------------------------------------------------------------------------------
--  ANTI-STAFF: AUTO-FREEZE (MEMATUNG) & AUTO-KICK MODERATOR PROTECTION
-------------------------------------------------------------------------------
local AntiStaff = {
    enabled = true,
    autoKick = false,
    autoFreeze = true,
    isFrozen = false,
    detectedStaff = {},
    isPlayerStaff = nil,
    scan = nil,
    freeze = nil,
    unfreeze = nil,
    updateUI = nil,
}
getgenv().AntiStaff = AntiStaff

do
    local Roles = nil
    pcall(function()
        if Shared and Shared:FindFirstChild("Roles") then
            Roles = require(Shared.Roles)
        end
    end)
    if not Roles and filtergc then
        pcall(function()
            local rList = filtergc("table", { Keys = {"isDeveloper"} }, false)
            if rList and rList[1] then Roles = rList[1] end
        end)
    end

    AntiStaff.isPlayerStaff = function(player)
        if not player or player == Players.LocalPlayer then return false, nil end
        local uid = player.UserId
        local name = tostring(player.Name or "")
        local disp = tostring(player.DisplayName or "")

        -- 1. Shared.Roles module check
        if Roles then
            local okDev, isDev = pcall(Roles.isDeveloper, uid)
            if okDev and isDev then return true, "Developer" end
            local okMod, isMod = pcall(Roles.isModerator, uid)
            if okMod and isMod then return true, "Moderator" end
            local okStaff, isStaff = pcall(Roles.isStaff, uid)
            if okStaff and isStaff then return true, "Staff" end
        end

        -- 2. Player Attributes (Tag & Rank)
        local tag = player:GetAttribute("Tag")
        if tag and type(tag) == "string" then
            local low = string.lower(tag)
            if low == "developer" or low == "moderator" or low == "admin" or low == "owner" or low == "staff" then
                return true, tag
            end
        end

        local rank = player:GetAttribute("Rank")
        if rank and type(rank) == "string" then
            local low = string.lower(rank)
            if low == "developer" or low == "moderator" or low == "admin" or low == "owner" or low == "staff" then
                return true, rank
            end
        end

        -- 3. Display name or Name prefix '@' (Growblox staff standard)
        if string.sub(name, 1, 1) == "@" or string.sub(disp, 1, 1) == "@" then
            return true, "StaffPrefix"
        end

        return false, nil
    end

    AntiStaff.freeze = function(staffName, staffRole)
        if AntiStaff.isFrozen then return end
        AntiStaff.isFrozen = true
        print(string.format("[ANTI-STAFF] 🚨 STAFF TERDETEKSI: %s (%s)! Karakter MEMATUNG (FREEZE)...", tostring(staffName or "Unknown"), tostring(staffRole or "Staff")))

        -- Hentikan pergerakan & physics seketika
        pcall(function()
            local w = getNativeWorld()
            if w then
                w.vx = 0
                w.vy = 0
            end
            local px, py, rawX, rawY = getPlayerTilePos()
            local curX = rawX or (px and px + 0.5) or 50
            local curY = rawY or (py and py + 1.0) or 30
            safeSendMove({
                x = curX,
                y = curY,
                vx = 0,
                vy = 0,
                flags = 0,
            })
        end)

        if AntiStaff.updateUI then AntiStaff.updateUI() end
    end

    AntiStaff.unfreeze = function()
        if not AntiStaff.isFrozen then return end
        AntiStaff.isFrozen = false
        print("[ANTI-STAFF] ✅ Semua staff telah meninggalkan world! Melanjutkan kegiatan...")

        if AntiStaff.updateUI then AntiStaff.updateUI() end
    end

    AntiStaff.scan = function()
        if not AntiStaff.enabled then
            if AntiStaff.isFrozen then
                AntiStaff.unfreeze()
            end
            return
        end

        local currentStaff = {}
        local staffCount = 0
        local firstStaff = nil
        local firstRole = nil

        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= Players.LocalPlayer then
                local isStaff, role = AntiStaff.isPlayerStaff(p)
                if isStaff then
                    staffCount = staffCount + 1
                    currentStaff[p.UserId] = { name = p.Name, role = role or "Staff", player = p }
                    if not firstStaff then
                        firstStaff = p.Name
                        firstRole = role or "Staff"
                    end
                end
            end
        end

        AntiStaff.detectedStaff = currentStaff

        if staffCount > 0 then
            -- 1. Auto Kick (jika aktif)
            if AntiStaff.autoKick then
                print(string.format("[ANTI-STAFF] ⚠️ AUTO-KICK AKTIF! Mengeluarkan player karena ada staff: %s (%s)", tostring(firstStaff), tostring(firstRole)))
                task.spawn(function()
                    pcall(function()
                        Players.LocalPlayer:Kick(string.format("[SysHub Anti-Staff] Terdeteksi staff di world: %s (%s)", tostring(firstStaff), tostring(firstRole)))
                    end)
                end)
                return
            end

            -- 2. Auto Freeze (mematung)
            if AntiStaff.autoFreeze and not AntiStaff.isFrozen then
                AntiStaff.freeze(firstStaff, firstRole)
            end
        else
            -- Tidak ada staff
            if AntiStaff.isFrozen then
                AntiStaff.unfreeze()
            end
        end

        if AntiStaff.updateUI then AntiStaff.updateUI() end
    end

    -- Event Listeners
    pcall(function()
        Players.PlayerAdded:Connect(function(player)
            if not AntiStaff.enabled then return end
            task.wait(0.2)
            AntiStaff.scan()
            player:GetAttributeChangedSignal("Tag"):Connect(function()
                if AntiStaff.enabled then AntiStaff.scan() end
            end)
            player:GetAttributeChangedSignal("Rank"):Connect(function()
                if AntiStaff.enabled then AntiStaff.scan() end
            end)
        end)

        Players.PlayerRemoving:Connect(function(player)
            if not AntiStaff.enabled then return end
            task.wait(0.1)
            AntiStaff.scan()
        end)
    end)

    -- Background scanner periodik (tiap 1.5 detik)
    task.spawn(function()
        while true do
            task.wait(1.5)
            if AntiStaff.enabled then
                pcall(AntiStaff.scan)
            end
        end
    end)
end

-- ═══════════════════════════════════════
--  A* PATHFINDING ENGINE (AVOID SOLID TILES)
-- ═══════════════════════════════════════

-- Helper: Mengecek apakah LocalPlayer memiliki akses ke object lock (World Lock atau Area Lock)
local function hasAccessToLock(lockObj)
    if not lockObj then return true end
    local myId = (Players.LocalPlayer and Players.LocalPlayer.UserId)
    if not myId then return true end

    -- 1. Cek pemilik lock
    if lockObj.owner == myId then return true end

    -- 2. Cek public lock (akses bebas untuk semua player)
    if lockObj.public == true then return true end

    -- 3. Cek method resmi AreaLock dari game engine
    if AreaLock then
        if type(AreaLock.hasAccess) == "function" then
            local ok, res = pcall(AreaLock.hasAccess, lockObj, myId)
            if ok and res ~= nil then return res == true end
        end
        if type(AreaLock.role) == "function" then
            local ok, r = pcall(AreaLock.role, lockObj, myId)
            if ok and r and r ~= "none" then return true end
        end
        if type(AreaLock.onList) == "function" then
            local ok, res = pcall(AreaLock.onList, lockObj, myId)
            if ok and res == true then return true end
        end
    end

    -- 4. Cek method w.areas jika tersedia
    local w = getNativeWorld()
    if w and w.areas then
        if type(w.areas.hasAccess) == "function" then
            local ok, res = pcall(w.areas.hasAccess, lockObj)
            if ok and res ~= nil then return res == true end
        end
        if type(w.areas.role) == "function" then
            local ok, r = pcall(w.areas.role, lockObj)
            if ok and r and r ~= "none" then return true end
        end
    end

    -- 5. Cek tabel access (mendukung format [[userId, name], ...] maupun [userId, ...])
    if lockObj.access and type(lockObj.access) == "table" then
        for _, entry in pairs(lockObj.access) do
            if type(entry) == "table" and entry[1] == myId then
                return true
            elseif entry == myId then
                return true
            end
        end
    end

    -- 6. Fallback tabel allowed
    if lockObj.allowed and type(lockObj.allowed) == "table" then
        for _, entry in pairs(lockObj.allowed) do
            if type(entry) == "table" and entry[1] == myId then
                return true
            elseif entry == myId then
                return true
            end
        end
    end

    -- 7. Cek akses guild (sesuai engine resmi AreaLock.role)
    if lockObj.guild and type(lockObj.guild) == "number" and (lockObj.guildRank or 0) > 0 then
        local lp = Players.LocalPlayer
        if lp and lp:GetAttribute("GuildId") == lockObj.guild then
            local myRank = lp:GetAttribute("GuildRank") or 0
            if (lockObj.guildRank or 0) <= myRank then
                return true
            end
        end
    end

    return false
end

-- Helper: Mengecek apakah tile (tx, ty) berada di area yang terkunci tanpa akses player
local function isTileLocked(tx, ty)
    if not tx or not ty then return false end
    local w = getNativeWorld()
    if not w then return false end

    -- 1. Staff bypass (Game Moderator / Admin)
    if w.areas and w.areas.staff then return false end

    -- 2. PRIORITAS UTAMA: Area Lock (Small Lock, Big Lock, Huge Lock, Builder Lock) yang menaungi tile (tx, ty)!
    -- w.areas.holder(tx, ty) mengambil data lock lokal yang mencakup koordinat tersebut
    local localAreaLock = nil
    if w.areas and type(w.areas.holder) == "function" then
        local ok, holderLock = pcall(w.areas.holder, tx, ty)
        if ok and holderLock then
            localAreaLock = holderLock
        end
    end

    -- Cek juga jika root item lock diletakkan tepat di koordinat (tx, ty)
    if not localAreaLock and w.areas and type(w.areas.lockAt) == "function" then
        local ok, atLock = pcall(w.areas.lockAt, tx, ty)
        if ok and atLock then
            localAreaLock = atLock
        end
    end

    -- HUKUM PRIORITAS LOCK:
    -- Hak akses Area Lock (Small/Big/Huge Lock) MENGALAHKAN World Lock!
    -- Walaupun player punya akses ke World Lock (WL), jika tile ini berada di dalam lingkup
    -- Area Lock yang player TIDAK miliki aksesnya, maka tile ini MUTLAK TERKUNCI (LOCKED)!
    if localAreaLock then
        return not hasAccessToLock(localAreaLock)
    end

    -- 3. Cek native engine validator w.areas.mayBuild(w.lock, tx, ty)
    if w.areas and type(w.areas.mayBuild) == "function" then
        local ok, canBuild = pcall(w.areas.mayBuild, w.lock, tx, ty)
        if ok and canBuild ~= nil then
            if not canBuild then
                return true -- Engine menyatakan tidak boleh build/akses -> tile terkunci
            end
        end
    end

    -- 4. PRIORITAS TERAKHIR: World Lock (hanya jika tile tidak dicakup oleh Area Lock lokal)
    if w.lock then
        return not hasAccessToLock(w.lock)
    end

    return false
end

local function isSolidTile(tx, ty)
    if not tx or not ty then return true end
    local w = getNativeWorld()
    if not w then return false end

    local worldW = w.w or 100
    local worldH = w.h or 60

    -- Boundary checks
    if tx < 0 or tx >= worldW or ty >= worldH then
        return true -- Luar batas world adalah solid
    end
    if ty < 0 then
        return false -- Langit di atas batas world adalah udara
    end

    local row = w.fg and w.fg[ty]
    if not row then
        return true -- Baris tile belum selesai di-stream dari server, anggap SOLID demi keamanan!
    end
    local tid = row[tx]
    if tid == nil then
        return true -- Tile belum selesai di-stream dari server, anggap SOLID!
    end
    if tid == 0 then
        return false -- Air / kosong murni bukan solid
    end

    local db = ItemDB and ItemDB[tid]
    if not db then
        return false
    end

    -- 1. Combiner Blocks (Chemical Combiner, dsb)
    if db.combiner and w.combinerShut then
        local ok, shut = pcall(w.combinerShut, tx, ty)
        if ok then return shut == true end
    end

    -- 2. VIP Door
    if db.vip and w.vipMay then
        local ok, may = pcall(w.vipMay, tx, ty)
        if ok then return not may end
    end

    -- 3. ENTRANCE & DOORS (House Entrance, Gates, Wood Door, Portals, Main Door)
    -- Ketentuan: Pintu & Entrance BISA DILEWATI selagi bukan locked area yang tidak punya akses!
    -- House Entrance (id 224) di ItemDB memang bertuliskan solid=true, tetapi memiliki entrance=true
    local isEntrance = (db.entrance == true) or (db.door == true) or (db.passDoor == true) or (tid == 6) or (tid == 12) or (tid == 224)
    if isEntrance then
        local sw = w.switches and w.switches[ty * worldW + tx]

        -- A. Khusus tipe Gate (Laser Gate, Portcullis, dsb)
        if db.gate then
            if sw and sw.off == true then
                return false -- Saklar gate terbuka (OFF) -> bisa dilewati
            end
            if sw and sw.public then
                return false -- Public gate -> bisa dilewati
            end
            return isTileLocked(tx, ty) -- Jika terkunci tanpa akses -> blok
        end

        -- B. Entrance dengan status PUBLIC
        if sw and sw.public then
            return false
        end

        -- C. Normal Doors & House Entrance (House Entrance 224, Wood Door 12, Main Door 6, Portals, dsb)
        -- ATURAN UTAMA: Pintu & Entrance HANYA BISA DILEWATI jika player memiliki akses ke lock (atau tidak terkunci)!
        -- Jika area terkunci oleh Small Lock / Big Lock / Huge Lock / World Lock tanpa akses player -> SOLID (TIDAK BISA DILEWATI)!
        -- Jika player memiliki akses (atau status public) -> BUKAN SOLID (BISA DILEWATI)!
        return isTileLocked(tx, ty)
    end

    -- 4. Standard Solid Check dari ItemDB
    return db.solid == true
end

local function isPlatformTile(tx, ty)
    if not tx or not ty then return false end
    local w = getNativeWorld()
    if not w or not w.fg then return false end
    local row = w.fg[ty]
    local tid = row and row[tx]
    if not tid or tid == 0 then return false end
    if AutoBuildDF and AutoBuildDF.platBlockId and tid == AutoBuildDF.platBlockId then
        return true
    end
    local db = ItemDB and ItemDB[tid]
    if not db then return false end
    return (db.platform == true) or (db.name and string.find(string.lower(db.name), "platform") ~= nil)
end

local function isSeedOrTreeId(tid)
    if not tid or tid <= 0 then return false end
    local db = ItemDB or (resolveItemDB and resolveItemDB())
    local it = db and db[tid]
    if it then
        if it.kind == "seed" or it.tree ~= nil or it.grow ~= nil then
            return true
        end
        if it.name and string.find(string.lower(it.name), "seed") then
            return true
        end
    end
    if tid % 2 == 1 and tid > 1 then
        return true
    end
    return false
end

-- Menentukan apakah tile (tx, ty) memiliki pijakan (grounding / support)
hasFooting = function(tx, ty)
    if not tx or not ty then return false end
    local w = getNativeWorld()
    local worldH = (w and w.h) or 60
    if ty + 1 >= worldH then return true end -- Dasar world (bedrock terbawah)

    -- Cek apakah tepat di bawahnya (ty + 1) adalah blok solid atau platform
    if isSolidTile(tx, ty + 1) then return true end
    if isPlatformTile(tx, ty + 1) then return true end

    -- Khusus Auto DF: Cek jika platBlockId yang disetting berada tepat di bawahnya
    if AutoBuildDF and AutoBuildDF.platBlockId and w and w.fg and w.fg[ty + 1] then
        local bId = w.fg[ty + 1][tx]
        if bId == AutoBuildDF.platBlockId then return true end
    end

    -- Cek apakah tepat di bawahnya (ty + 1) ada blok FG apapun (bukan air / bukan pohon)
    if w and w.fg and w.fg[ty + 1] then
        local belowTid = w.fg[ty + 1][tx]
        if belowTid and belowTid > 0 and not isSeedOrTreeId(belowTid) then
            return true
        end
    end

    -- Cek apakah di tile (tx, ty) ada tangga panjat / vine (climbable)
    if w and w.fg then
        local curRow = w.fg[ty]
        local curTid = curRow and curRow[tx]
        if curTid and curTid > 0 then
            local db = ItemDB and ItemDB[curTid]
            if db and (db.ladder == true or db.vine == true or (db.name and (string.find(string.lower(db.name), "ladder") or string.find(string.lower(db.name), "vine")))) then
                return true
            end
        end
    end

    return false
end

local function makeHeap()
    local heap = {}
    local function push(node)
        table.insert(heap, node)
        local idx = #heap
        while idx > 1 do
            local parent = math.floor(idx / 2)
            if heap[idx].f < heap[parent].f then
                heap[idx], heap[parent] = heap[parent], heap[idx]
                idx = parent
            else
                break
            end
        end
    end

    local function pop()
        local top = heap[1]
        local last = table.remove(heap)
        if #heap > 0 then
            heap[1] = last
            local idx = 1
            while true do
                local left = idx * 2
                local right = idx * 2 + 1
                local smallest = idx
                if left <= #heap and heap[left].f < heap[smallest].f then
                    smallest = left
                end
                if right <= #heap and heap[right].f < heap[smallest].f then
                    smallest = right
                end
                if smallest ~= idx then
                    heap[idx], heap[smallest] = heap[smallest], heap[idx]
                    idx = smallest
                else
                    break
                end
            end
        end
        return top
    end

    return push, pop, function() return #heap == 0 end
end

local function findPath(startX, startY, goalX, goalY, maxExpansions)
    maxExpansions = maxExpansions or 25000

    if startX == goalX and startY == goalY then
        return { { x = goalX, y = goalY } }
    end

    -- Jika tile goal adalah solid (misal item drop berada di atas permukaan blok),
    -- alihkan target ke tetangga terdekat yang tidak solid (air)
    if isSolidTile(goalX, goalY) then
        local adj = {
            { x = goalX, y = goalY - 1 }, -- Atas
            { x = goalX - 1, y = goalY }, -- Kiri
            { x = goalX + 1, y = goalY }, -- Kanan
            { x = goalX, y = goalY + 1 }, -- Bawah
        }
        local bestN, bestDist = nil, 999999
        for _, n in ipairs(adj) do
            if not isSolidTile(n.x, n.y) then
                local d = math.abs(n.x - startX) + math.abs(n.y - startY)
                if d < bestDist then
                    bestDist = d
                    bestN = n
                end
            end
        end
        if bestN then
            goalX, goalY = bestN.x, bestN.y
        else
            return nil -- Goal tertutup rapat oleh blok solid
        end
    end

    -- Jika posisi start terdeteksi berada di dalam blok solid, cari tetangga terdekat
    if isSolidTile(startX, startY) then
        local adj = {
            { x = startX, y = startY - 1 },
            { x = startX - 1, y = startY },
            { x = startX + 1, y = startY },
            { x = startX, y = startY + 1 },
        }
        for _, n in ipairs(adj) do
            if not isSolidTile(n.x, n.y) then
                startX, startY = n.x, n.y
                break
            end
        end
    end

    local function key(x, y)
        return (y + 100) * 1000 + (x + 100)
    end

    local function heuristic(x, y)
        local dx = math.abs(x - goalX)
        local dy = math.abs(y - goalY)
        -- Octile Distance Heuristic
        local f = 1.414 - 1
        return (dx < dy) and (f * dx + dy) or (f * dy + dx)
    end

    local push, pop, isEmpty = makeHeap()
    local gScore = {}
    local closedSet = {}

    local startK = key(startX, startY)
    gScore[startK] = 0
    push({
        x = startX,
        y = startY,
        g = 0,
        f = heuristic(startX, startY),
        parent = nil
    })

    local DIRS = {
        -- 4 Arah Kardinal (cost 1.0)
        { dx = 1,  dy = 0,  cost = 1.0, isDiag = false },
        { dx = -1, dy = 0,  cost = 1.0, isDiag = false },
        { dx = 0,  dy = 1,  cost = 1.0, isDiag = false },
        { dx = 0,  dy = -1, cost = 1.0, isDiag = false },
        -- 4 Arah Diagonal (cost 1.414)
        { dx = 1,  dy = 1,  cost = 1.414, isDiag = true },
        { dx = -1, dy = 1,  cost = 1.414, isDiag = true },
        { dx = 1,  dy = -1, cost = 1.414, isDiag = true },
        { dx = -1, dy = -1, cost = 1.414, isDiag = true },
    }

    local expansions = 0
    while not isEmpty() do
        local cur = pop()
        expansions = expansions + 1
        if expansions > maxExpansions then
            break
        end

        if cur.x == goalX and cur.y == goalY then
            -- Rekonstruksi jalur
            local path = {}
            local currNode = cur
            while currNode do
                table.insert(path, 1, { x = currNode.x, y = currNode.y })
                currNode = currNode.parent
            end
            return path
        end

        local curK = key(cur.x, cur.y)
        closedSet[curK] = true

        for _, d in ipairs(DIRS) do
            local nx = cur.x + d.dx
            local ny = cur.y + d.dy
            local nK = key(nx, ny)

            if not closedSet[nK] and not isSolidTile(nx, ny) and not isPlatformTile(nx, ny) then
                local validMove = true
                if d.isDiag then
                    -- STRICT CORNER: Blokir diagonal HANYA JIKA kedua sisi ngebentuk sudut siku (Solid/Platform)
                    local halanganX = isSolidTile(cur.x + d.dx, cur.y) or isPlatformTile(cur.x + d.dx, cur.y)
                    local halanganY = isSolidTile(cur.x, cur.y + d.dy) or isPlatformTile(cur.x, cur.y + d.dy)
                    
                    -- Pakai 'and' brok, jangan 'or'. Biar bisa zigzag turun dari pinggiran platform!
                    if halanganX and halanganY then
                        validMove = false
                    end
                end

                if validMove then
                    -- Grounding Bias: Utamakan tile yang memiliki pijakan tanah/platform!
                    local stepCost = 1.0
                    local footing = hasFooting(nx, ny)
                    local isDF = (AutoBuildDF and AutoBuildDF.active)

                    if d.isDiag then
                        stepCost = footing and 1.5 or (isDF and 4.0 or 3.5)
                    elseif d.dy == 0 then
                        stepCost = footing and 1.0 or (isDF and 3.0 or 2.5)
                    else
                        if d.dy > 0 then
                            -- Drop down (terjun ke bawah): Utamakan napak platform/tanah
                            stepCost = footing and 1.2 or (isDF and 3.0 or 2.5)
                        else
                            -- Jump up (naik tangga/shaft/platform):
                            -- Biaya naik wajar agar A* mudah memanjat poros tangga vertikal tanpa gagal/timeout!
                            stepCost = footing and 1.5 or (isDF and 3.0 or 2.5)
                        end
                    end



                    local tentativeG = cur.g + stepCost
                    if not gScore[nK] or tentativeG < gScore[nK] then
                        gScore[nK] = tentativeG
                        push({
                            x = nx,
                            y = ny,
                            g = tentativeG,
                            f = tentativeG + heuristic(nx, ny),
                            parent = cur
                        })
                    end
                end
            end
        end
    end

    return nil -- Tidak ada jalur terbuka yang tidak menabrak blok solid
end

isMovementActive = function()
    if AntiStaff and AntiStaff.isFrozen then return false end
    if isWorldPickerOpen and isWorldPickerOpen() then return false end
    local w = getNativeWorld and getNativeWorld()
    if not w or not w.name or w.name == "" or string.upper(w.name) == "LOBBY" then return false end
    return (ClearWorld and ClearWorld.active) or
           (AutoBuildDF and AutoBuildDF.active) or
           (AutoPlant and AutoPlant.active) or
           (AutoHarvest and AutoHarvest.active) or
           (AutoFactory and AutoFactory.active) or
           (AutoRotation and AutoRotation.active) or
           (ClickPathfind and ClickPathfind.busy) or
           (Magnet and (Magnet.busy or Magnet.enabled)) or
           (PNB and (PNB.active or PNB.busy)) or
           (AutoEvent and (AutoEvent.active or AutoEvent.busy)) or
           (FarmLogistics and (FarmLogistics.move.active or FarmLogistics.busyResuming)) or
           (Proxy and Proxy.casino and Proxy.casino.busy)
end

local function followPath(path, stepSize, startOverrideX, startOverrideY)
    if not path or #path == 0 then return end

    local px, py, rawX, rawY = getPlayerTilePos()
    local startX = startOverrideX or rawX or (px and px + 0.5)
    local startY = startOverrideY or rawY or (py and py + 1.0)

    local waypoints = {}
    if startX and startY then
        table.insert(waypoints, { x = startX, y = startY })
    end

    for _, t in ipairs(path) do
        table.insert(waypoints, { x = t.x + 0.5, y = t.y + 1.0 })
    end
    
    -- [FIX] FILTER MANHATTAN (U KAKU 90 DERAJAT)
    local sikuWaypoints = {}
    table.insert(sikuWaypoints, waypoints[1])

    for i = 1, #waypoints - 1 do
        local pA = waypoints[i]
        local pB = waypoints[i + 1]
        
        local dx = pB.x - pA.x
        local dy = pB.y - pA.y

        -- Jika terdeteksi gerak miring/diagonal (X dan Y berubah barengan)
        if math.abs(dx) > 0.1 and math.abs(dy) > 0.1 then
            -- Bot dipaksa geser horizontal dulu (lepas dari pijakan), baru turun vertikal
            table.insert(sikuWaypoints, { x = pB.x, y = pA.y })
        end
        table.insert(sikuWaypoints, pB)
    end
    waypoints = sikuWaypoints

    -- Kecepatan pathfind aman anticheat: 5.4 tiles/sec (di bawah batas kick 267)
    local PATH_SPEED = 5.4

    for i = 1, #waypoints - 1 do
        if not isMovementActive() then break end
        local pA = waypoints[i]
        local pB = waypoints[i + 1]

        local dx = pB.x - pA.x
        local dy = pB.y - pA.y
        local segDist = math.sqrt(dx * dx + dy * dy)

        if segDist > 0 then
            local segTime = segDist / PATH_SPEED
            local t0 = os.clock()
            local elapsed = 0
            while elapsed < segTime do
                if not isMovementActive() then break end
                RunService.Heartbeat:Wait()
                elapsed = os.clock() - t0
                local alpha = math.clamp(elapsed / segTime, 0, 1)
                local curX = pA.x + dx * alpha
                local curY = pA.y + dy * alpha

                setInternalPlayerPos(curX, curY)
                local facingBit = (dx >= 0) and 1 or 0
                safeSendMove({
                    x = curX,
                    y = curY,
                    vx = (dx / segDist) * PATH_SPEED,
                    vy = (dy / segDist) * PATH_SPEED,
                    flags = 2 + facingBit,
                })
            end
        end
    end

    local finalP = waypoints[#waypoints]
    if finalP then
        setInternalPlayerPos(finalP.x, finalP.y)
        safeSendMove({
            x = finalP.x,
            y = finalP.y,
            vx = 0,
            vy = 0,
            flags = 2,
        })
    end
    RunService.Heartbeat:Wait()
end

-- ═════════════════════════════════════════════════════════════════════
--  CORE MOVEMENT & NAVIGATION (stepToColumn, walkOrPathfindTo, approachTile)
-- ═════════════════════════════════════════════════════════════════════
stepToColumn = function(targetX, targetY)
    local px, py, rawX, rawY = getPlayerTilePos()
    if not px or not py then return end

    -- Jangan pernah melangkah lurus ke dalam tile yang solid!
    if isSolidTile(targetX, targetY) then
        return false
    end

    local startX = rawX or (px + 0.5)
    local startY = py + 1.0
    local destX = targetX + 0.5
    local destY = targetY + 1.0

    local dx = destX - startX
    local dy = destY - startY
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist <= 0.05 then return end

    if dist > 1.2 then
        local steps = math.ceil(dist * 2)
        local hasSolidObstacle = false
        for s = 1, steps do
            local chkX = math.floor(startX + dx * (s / steps))
            local chkY = math.floor(startY + dy * (s / steps))
            -- [FIX]: Pastikan platform juga dianggap halangan biar gak ditembus lurus!
            if isSolidTile(chkX, chkY) or isPlatformTile(chkX, chkY) then
                hasSolidObstacle = true
                break
            end
        end 
        if hasSolidObstacle then
            -- Jalur lurus terhalang dinding/tanah! Gunakan A* pathfinding yang aman!
            local safePath = findPath(px, py, targetX, targetY, 25000)
            if safePath and #safePath > 0 then
                followPath(safePath, 0.48)
            end
            return
        end
    end

    -- Kecepatan langkah: 1.25x dari speed asli karakter (7.2 * 1.25 = 9.0 tiles/sec)
    local STEP_SPEED = 6.8
    local segTime = dist / STEP_SPEED
    local t0 = os.clock()
    local elapsed = 0
    while elapsed < segTime do
        if isMovementActive and not isMovementActive() then break end
        RunService.Heartbeat:Wait()
        elapsed = os.clock() - t0
        local alpha = math.clamp(elapsed / segTime, 0, 1)
        local cx = startX + dx * alpha
        local cy = startY + dy * alpha
        setInternalPlayerPos(cx, cy)
        local facingBit = (dx >= 0) and 1 or 0
        safeSendMove({
            x = cx,
            y = cy,
            vx = (dist > 0) and (dx / dist) * STEP_SPEED or 0,
            vy = (dist > 0) and (dy / dist) * STEP_SPEED or 0,
            flags = 2 + facingBit,
        })
    end

    setInternalPlayerPos(destX, destY)
    local finalFacing = (dx >= 0) and 1 or 0
    safeSendMove({
        x = destX,
        y = destY,
        vx = 0,
        vy = 0,
        flags = 2 + finalFacing,
    })
    RunService.Heartbeat:Wait()
end

walkOrPathfindTo = function(targetX, targetY, worldW, worldH)
    local px, py, rawX, rawY = getPlayerTilePos()
    if not px or not py then return false end

    local dist = math.abs(px - targetX) + math.abs(py - targetY)
    if dist <= 1 and not isSolidTile(targetX, targetY) then
        stepToColumn(targetX, targetY)
        return true
    end

    local path = findPath(px, py, targetX, targetY, 15000)
    if path and #path > 0 then
        if ClearWorld then ClearWorld.busy = true end
        if AutoBuildDF then AutoBuildDF.busy = true end
        if AutoPlant then AutoPlant.busy = true end
        if AutoHarvest then AutoHarvest.busy = true end
        followPath(path, 0.48)
        if ClearWorld then ClearWorld.busy = false end
        if AutoBuildDF then AutoBuildDF.busy = false end
        if AutoPlant then AutoPlant.busy = false end
        if AutoHarvest then AutoHarvest.busy = false end
        return true
    else
        for dy = -1, 1 do
            for dx = -1, 1 do
                local sx = targetX + dx
                local sy = targetY + dy
                if sx >= 0 and sx < (worldW or 100) and sy >= 0 and sy < (worldH or 60) then
                    if not isSolidTile(sx, sy) then
                        local altPath = findPath(px, py, sx, sy, 15000)
                        if altPath and #altPath > 0 then
                            if ClearWorld then ClearWorld.busy = true end
                            if AutoBuildDF then AutoBuildDF.busy = true end
                            if AutoPlant then AutoPlant.busy = true end
                            if AutoHarvest then AutoHarvest.busy = true end
                            followPath(altPath, 0.48)
                            if ClearWorld then ClearWorld.busy = false end
                            if AutoBuildDF then AutoBuildDF.busy = false end
                            if AutoPlant then AutoPlant.busy = false end
                            if AutoHarvest then AutoHarvest.busy = false end
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

-- Dekati target tile secara aman (jarak <= 2 tile):
-- Jika di baris yang sama dan jalan terbuka: stepToColumn (sangat cepat & mulus)
-- Jika beda baris atau ada obstacle: A* pathfinding (walkOrPathfindTo)
approachTile = function(targetX, targetY, worldW, worldH)
    local curPx, curPy = getPlayerTilePos()
    if not curPx or not curPy then return false end

    local dist = math.abs(curPx - targetX) + math.abs(curPy - targetY)
    if dist <= 2 then
        return true
    end

    -- 1. Jika di baris yang sama persis (curPy == targetY), cek apakah jalan terbuka DAN seluruh tile ada pijakan
    if curPy == targetY then
        local hasFullFooting = true
        local dir = (targetX > curPx) and 1 or -1
        for cx = curPx + dir, targetX, dir do
            if isSolidTile(cx, targetY) or not hasFooting(cx, targetY) then
                hasFullFooting = false
                break
            end
        end
        if hasFullFooting then
            stepToColumn(targetX, targetY)
            local npx, npy = getPlayerTilePos()
            if npx and npy and (math.abs(npx - targetX) + math.abs(npy - targetY) <= 2) then
                return true
            end
        end
    end

    -- 2. Jika beda baris atau terhalang, gunakan A* pathfinding
    walkOrPathfindTo(targetX, targetY, worldW, worldH)

    -- 3. Verifikasi posisi akhir
    local endPx, endPy = getPlayerTilePos()
    if endPx and endPy and (math.abs(endPx - targetX) + math.abs(endPy - targetY) <= 2) then
        return true
    end

    return false
end

-- Validasi jarak aman: jika jarak > 2 tile dari posisi char, langsung pathfind ulang ke posisi terdekat!
ensureTileInRange = function(tx, ty, worldW, worldH)
    if not tx or not ty then return false end
    local px, py = getPlayerTilePos()
    if not px or not py then return true end

    local dist = math.sqrt((px - tx)^2 + (py - ty)^2)
    if dist <= 2.0 then
        return true -- Sudah dalam jarak pukul aman (<= 2 tile)
    end

    -- Jarak > 2 tile! Jangan paksa break dari jauh, langsung pathfind ulang
    if lblClearStatus then
        lblClearStatus.Text = string.format("🚶 Jarak > 2 tile (%.1f) ➔ Pathfind ulang ke (%d, %d)...", dist, tx, ty)
    end

    -- Cari posisi berdiri non-solid di sekitar tile target (jarak 1 tile)
    local bestSpot = nil
    local bestDist = 999999
    local offsets = {
        { dx = -1, dy = 0 },
        { dx = 1,  dy = 0 },
        { dx = 0,  dy = 1 },
        { dx = 0,  dy = -1 },
        { dx = -1, dy = -1 },
        { dx = 1,  dy = -1 },
        { dx = -1, dy = 1 },
        { dx = 1,  dy = 1 },
    }

    for _, off in ipairs(offsets) do
        local sx = tx + off.dx
        local sy = ty + off.dy
        if sx >= 0 and sx < (worldW or 100) and sy >= 0 and sy < (worldH or 60) then
            if not isSolidTile(sx, sy) then
                local d = math.abs(px - sx) + math.abs(py - sy)
                if d < bestDist then
                    bestDist = d
                    bestSpot = { x = sx, y = sy }
                end
            end
        end
    end

    if bestSpot then
        walkOrPathfindTo(bestSpot.x, bestSpot.y, worldW, worldH)
    else
        walkOrPathfindTo(tx, ty, worldW, worldH)
    end
    task.wait(0.03)

    local npx, npy = getPlayerTilePos()
    if npx and npy then
        local newDist = math.sqrt((npx - tx)^2 + (npy - ty)^2)
        return (newDist <= 2.1)
    end
    return false
end



-- =======================================
--  CLICK-TO-PATHFIND ENGINE
-- =======================================
-- ClickPathfind state moved into ClickPathfind table

local function getOrCreateGridContainer()
    local camera, _, _ = getCameraAndTiles()
    if not camera then return nil end
    local existing = camera:FindFirstChild("SyshubPathfindGrid")
    if existing and existing:IsA("Frame") then
        ClickPathfind.gridContainer = existing
        return ClickPathfind.gridContainer
    end

    local frame = Instance.new("Frame")
    frame.Name = "SyshubPathfindGrid"
    frame.BackgroundTransparency = 1
    frame.Size = UDim2.fromScale(1, 1)
    frame.Position = UDim2.new(0, 0, 0, 0)
    frame.ZIndex = 4
    frame.ClipsDescendants = false
    frame.Parent = camera
    ClickPathfind.gridContainer = frame
    return ClickPathfind.gridContainer
end

local function screenToTile(screenX, screenY)
    local camera, tiles, _ = getCameraAndTiles()
    if not camera or not tiles then return nil, nil end
    local uiScale = 1
    local s = camera:FindFirstChild("UIScale")
    if s and s:IsA("UIScale") then
        uiScale = s.Scale
    end

    local tileSize = DISPLAY_SIZE * uiScale
    local absPos = tiles.AbsolutePosition
    local tx = math.floor((screenX - absPos.X) / tileSize)
    local ty = math.floor((screenY - absPos.Y) / tileSize)

    return tx, ty
end

local function triggerPathfindToTile(tx, ty)
    if not ClickPathfind.enabled then return false end

    local now = os.clock()
    if ClickPathfind.lastClickTx == tx and ClickPathfind.lastClickTy == ty and (now - ClickPathfind.lastClickTime) < 0.25 then
        return false
    end
    ClickPathfind.lastClickTime = now
    ClickPathfind.lastClickTx = tx
    ClickPathfind.lastClickTy = ty

    local w = getNativeWorld()
    local worldW = (w and w.w) or 100
    local worldH = (w and w.h) or 60
    if tx < 0 or tx >= worldW or ty < 0 or ty >= worldH then return false end

    -- Syarat 1: Jika tx, ty adalah blok solid, arahkan ke tile udara tepat di atasnya (ty - 1) jika kosong sebagai pijakan
    if isSolidTile(tx, ty) then
        if ty > 0 and not isSolidTile(tx, ty - 1) then
            ty = ty - 1
        else
            if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
                ClickPathfind.lblStatus:set(string.format("`4[X] Tile (%d, %d) adalah Blok Solid!``", tx, ty))
            end
            return false
        end
    end



    local curPx, curPy = getPlayerTilePos()
    if not curPx or not curPy then return false end
    if curPx == tx and curPy == ty then return false end

    -- Cari rute A* dengan Grounding Bias (Mencari pijakan tanah/platform)
    local path = findPath(curPx, curPy, tx, ty, 15000)
    if not path or #path == 0 then
        -- Coba cari alternatif pijakan di sekitar target jika terhalang
        for _, off in ipairs({{0, -1}, {-1, 0}, {1, 0}, {0, 1}}) do
            local altX = tx + off[1]
            local altY = ty + off[2]
            if altX >= 0 and altX < worldW and altY >= 0 and altY < worldH then
                if not isSolidTile(altX, altY) then
                    local altPath = findPath(curPx, curPy, altX, altY, 15000)
                    if altPath and #altPath > 0 then
                        path = altPath
                        tx = altX
                        ty = altY
                        break
                    end
                end
            end
        end
    end

    if not path or #path == 0 then
        if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
            ClickPathfind.lblStatus:set(string.format("`4[X] Tidak ada jalur ke (%d, %d) (Terhalang)!``", tx + 1, ty + 1))
        end
        return false
    end

    if ClickPathfind.thread then
        task.cancel(ClickPathfind.thread)
        ClickPathfind.thread = nil
    end

    if setWaypoint then
        setWaypoint("Target Klik", tx, ty)
    end

    ClickPathfind.busy = true
    ClickPathfind.targetX = tx
    ClickPathfind.targetY = ty
    if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
        ClickPathfind.lblStatus:set(string.format("`2Menuju ke (%d, %d) [%d langkah]...``", tx + 1, ty + 1, #path))
    end

    ClickPathfind.thread = task.spawn(function()
        followPath(path)
        ClickPathfind.busy = false
        ClickPathfind.thread = nil
        if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
            ClickPathfind.lblStatus:set(string.format("`2Sampai di tujuan (%d, %d)!``", tx + 1, ty + 1))
        end
        if clearWaypoint then
            task.delay(1.5, clearWaypoint)
        end
    end)
    return true
end

local function handleScreenClickPathfind(clickX, clickY, explicitTx, explicitTy)
    if not ClickPathfind.enabled then return end

    if explicitTx and explicitTy then
        triggerPathfindToTile(explicitTx, explicitTy)
        return
    end

    if not clickX or not clickY then return end

    -- Abaikan klik jika berada di dalam panel GUI SYSHUB atau WaypointHUD
    if MainDialog and MainDialog.Visible then
        local dPos = MainDialog.AbsolutePosition
        local dSize = MainDialog.AbsoluteSize
        if clickX >= dPos.X and clickX <= dPos.X + dSize.X and
           clickY >= dPos.Y and clickY <= dPos.Y + dSize.Y then
            return
        end
    end
    if WaypointHUD and WaypointHUD.Visible then
        local wPos = WaypointHUD.AbsolutePosition
        local wSize = WaypointHUD.AbsoluteSize
        if clickX >= wPos.X and clickX <= wPos.X + wSize.X and
           clickY >= wPos.Y and clickY <= wPos.Y + wSize.Y then
            return
        end
    end
    if SyshubSideBtn and SyshubSideBtn.Visible then
        local bPos = SyshubSideBtn.AbsolutePosition
        local bSize = SyshubSideBtn.AbsoluteSize
        if clickX >= bPos.X and clickX <= bPos.X + bSize.X and
           clickY >= bPos.Y and clickY <= bPos.Y + bSize.Y then
            return
        end
    end

    local tx, ty = screenToTile(clickX, clickY)
    if not tx or not ty then return end
    triggerPathfindToTile(tx, ty)
end

local hoverHighlightBox = nil

local function getOrCreateHoverBox(parent)
    if hoverHighlightBox and hoverHighlightBox.Parent then
        return hoverHighlightBox
    end
    local box = Instance.new("ImageLabel")
    box.Name = "HoverHighlightBox"
    box.BackgroundTransparency = 1
    box.Image = "rbxassetid://130382685204222"
    box.ImageRectOffset = Vector2.new(32, 0)
    box.ImageRectSize = Vector2.new(32, 32)
    box.ImageTransparency = 0.2
    box.ResampleMode = Enum.ResamplerMode.Pixelated
    box.Size = UDim2.fromOffset(DISPLAY_SIZE, DISPLAY_SIZE)
    box.ZIndex = 6
    box.Active = false
    box.Visible = false
    box.Parent = parent
    hoverHighlightBox = box
    return box
end

local function createGridTile(parent)
    local img = Instance.new("ImageLabel")
    img.Name = "PathGridBox"
    img.BackgroundTransparency = 1
    img.Image = "rbxassetid://130382685204222"
    img.ImageRectOffset = Vector2.new(32, 0)
    img.ImageRectSize = Vector2.new(32, 32)
    img.ImageTransparency = 0.65
    img.ResampleMode = Enum.ResamplerMode.Pixelated
    img.Size = UDim2.fromOffset(DISPLAY_SIZE, DISPLAY_SIZE)
    img.ZIndex = 4
    img.Active = false
    img.Visible = false
    img.Parent = parent
    return img
end

local function isShiftPressed()
    local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    if isMobile and ClickPathfind and ClickPathfind.enabled then
        return true -- Mobile touch mode: Grid otomatis aktif saat toggle ClickPathfind ON
    end
    return UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
end

local function updatePathfindGrid()
    if not ClickPathfind.enabled then
        if ClickPathfind.gridContainer then
            ClickPathfind.gridContainer.Visible = false
        end
        return
    end

    local camera, tiles, _ = getCameraAndTiles()
    if not camera or not tiles then return end
    local world = camera.Parent
    if not world then return end

    local container = getOrCreateGridContainer()
    if not container then return end

    local shiftHeld = isShiftPressed()
    if not shiftHeld then
        container.Visible = false
        if hoverHighlightBox then
            hoverHighlightBox.Visible = false
        end
        return
    end

    -- Shift sedang ditekan: Munculkan grid & update kotak!
    container.Visible = true

    local uiScale = 1
    local s = camera:FindFirstChild("UIScale")
    if s and s:IsA("UIScale") then
        uiScale = s.Scale
    end

    local camTileX = -tiles.Position.X.Offset / DISPLAY_SIZE
    local camTileY = -tiles.Position.Y.Offset / DISPLAY_SIZE
    local wSizeX = world.AbsoluteSize.X
    local wSizeY = world.AbsoluteSize.Y

    local w = getNativeWorld()
    local worldW = (w and w.w) or 100
    local worldH = (w and w.h) or 60

    local viewTilesW = math.ceil(wSizeX / (DISPLAY_SIZE * uiScale)) + 2
    local viewTilesH = math.ceil(wSizeY / (DISPLAY_SIZE * uiScale)) + 2

    local minTx = math.clamp(math.floor(camTileX) - 1, 0, worldW - 1)
    local maxTx = math.clamp(math.floor(camTileX + viewTilesW), 0, worldW - 1)
    local minTy = math.clamp(math.floor(camTileY) - 1, 0, worldH - 1)
    local maxTy = math.clamp(math.floor(camTileY + viewTilesH), 0, worldH - 1)

    local offsetX = tiles.Position.X.Offset
    local offsetY = tiles.Position.Y.Offset

    if math.abs(camTileX - ClickPathfind.lastCamTileX) >= 0.001 or
       math.abs(camTileY - ClickPathfind.lastCamTileY) >= 0.001 or
       math.abs(uiScale - ClickPathfind.lastUiScale) >= 0.001 or
       wSizeX ~= ClickPathfind.lastWorldSizeX or
       wSizeY ~= ClickPathfind.lastWorldSizeY then

        ClickPathfind.lastCamTileX = camTileX
        ClickPathfind.lastCamTileY = camTileY
        ClickPathfind.lastUiScale = uiScale
        ClickPathfind.lastWorldSizeX = wSizeX
        ClickPathfind.lastWorldSizeY = wSizeY

        local idx = 0
        for ty = minTy, maxTy do
            for tx = minTx, maxTx do
                idx = idx + 1
                local tileBox = ClickPathfind.gridButtonsPool[idx]
                if not tileBox then
                    tileBox = createGridTile(container)
                    ClickPathfind.gridButtonsPool[idx] = tileBox
                end

                tileBox:SetAttribute("tx", tx)
                tileBox:SetAttribute("ty", ty)
                tileBox.Position = UDim2.fromOffset(tx * DISPLAY_SIZE + offsetX, ty * DISPLAY_SIZE + offsetY)
                tileBox.Visible = true
            end
        end

        for i = idx + 1, #ClickPathfind.gridButtonsPool do
            ClickPathfind.gridButtonsPool[i].Visible = false
        end
    end

    -- Update highlight tile di bawah posisi mouse real-time
    local hoverBox = getOrCreateHoverBox(container)
    local mousePos = UserInputService:GetMouseLocation()
    local htx, hty = screenToTile(mousePos.X, mousePos.Y)
    if htx and hty and htx >= 0 and htx < worldW and hty >= 0 and hty < worldH then
        hoverBox.Position = UDim2.fromOffset(htx * DISPLAY_SIZE + offsetX, hty * DISPLAY_SIZE + offsetY)
        hoverBox.Visible = true
        if isSolidTile(htx, hty) then
            hoverBox.ImageColor3 = Color3.fromRGB(255, 75, 75)
        elseif isTileLocked(htx, hty) then
            hoverBox.ImageColor3 = Color3.fromRGB(255, 160, 40)
        else
            hoverBox.ImageColor3 = Color3.fromRGB(80, 255, 120)
        end
    else
        hoverBox.Visible = false
    end
end

local function toggleClickPathfindGrid(enabled)
    if enabled then
        ClickPathfind.lastCamTileX = -99999
        ClickPathfind.lastCamTileY = -99999
        if not ClickPathfind.gridConnection then
            ClickPathfind.gridConnection = RunService.RenderStepped:Connect(updatePathfindGrid)
        end
        updatePathfindGrid()
    else
        if ClickPathfind.gridConnection then
            ClickPathfind.gridConnection:Disconnect()
            ClickPathfind.gridConnection = nil
        end
        if ClickPathfind.gridContainer then
            ClickPathfind.gridContainer.Visible = false
        end
        if hoverHighlightBox then
            hoverHighlightBox.Visible = false
        end
        for _, btn in ipairs(ClickPathfind.gridButtonsPool) do
            btn.Visible = false
        end
    end
end

tryPickupDrop = function(drop, inv)
    if not drop or not drop.uid or not drop.n or drop.n <= 0 or drop.taking then
        return 0
    end

    local takeAmount = drop.n
    if drop.id ~= 112 and inv and inv.room then
        local space = inv:room(drop.id)
        if space <= 0 then
            return 0
        end
        takeAmount = math.min(takeAmount, space)
    end
    if takeAmount <= 0 then return 0 end

    drop.taking = true
    local taken = nil
    local w = getNativeWorld and getNativeWorld()
    if w and w.takeDrop then
        local ok_take, res = pcall(w.takeDrop, drop.uid, takeAmount)
        if ok_take and type(res) == "number" and res > 0 then
            taken = res
        end
    end
    if not taken and w and w.ask then
        local ok_ask, res = pcall(w.ask, "take", "took", { uid = drop.uid, want = math.clamp(math.floor(takeAmount), 1, 65535) })
        if ok_ask and res and type(res.got) == "number" and res.got > 0 then
            taken = res.got
        end
    end
    drop.taking = false

    if taken and taken > 0 then
        drop.n = drop.n - taken
        if drop.n <= 0 then
            if drop.frame then
                pcall(function() drop.frame:Destroy() end)
            end
            local w = getNativeWorld()
            if w and w.dropList then
                local drops = w.dropList()
                local idx = table.find(drops, drop)
                if idx then table.remove(drops, idx) end
            end
        else
            if drop.count and drop.count.set then
                drop.count:set(drop.n > 1 and tostring(drop.n) or "")
            end
        end

        if inv and inv.add and drop.id ~= 112 then
            pcall(inv.add, inv, drop.id, taken)
        end

        if Sfx and Sfx.play then
            if drop.id == 112 then
                Sfx.play("gem_pickup", "object_collect")
            else
                Sfx.play("object_collect")
            end
        end
        return taken
    end
    return 0
end
_G.tryPickupDrop = tryPickupDrop

local unreachableDrops = {}
local lastUnreachableClear = os.clock()

local function sweepDrops(radius, filterMode, maxPerPass, isManual)
    local w = getNativeWorld()
    if not w or not w.dropList then return 0 end
    local drops = w.dropList()
    if not drops or #drops == 0 then return 0 end

    if os.clock() - lastUnreachableClear > 30 then
        table.clear(unreachableDrops)
        lastUnreachableClear = os.clock()
    end

    local px, py, rawX, rawY = getPlayerTilePos()
    if not px or not py then return 0 end

    local origX = rawX or (px + 0.5)
    local origY = py + 1.0
    local origTileX = px
    local origTileY = py

    local inv = getNativeInventory()
    local targetItemId = PNB and PNB.itemId or 2
    local totalCollected = 0
    local passLimit = maxPerPass or 30

    local function isDropEligible(drop)
        if not drop or not drop.uid or not drop.n or drop.n <= 0 or drop.taking then
            return false
        end
        if unreachableDrops and unreachableDrops[drop.uid or drop] then
            return false
        end
        if filterMode == "ALL" then
            -- ok
        elseif filterMode == "GEMS" then
            if drop.id ~= 112 then return false end
        elseif filterMode == "ITEMS" then
            if drop.id == 112 then return false end
        elseif filterMode == "CURRENT" then
            if drop.id ~= targetItemId and drop.id ~= 112 then return false end
        end

        local dtx = math.floor(drop.x or 0)
        local dty = math.floor(drop.y or 0)

        -- JANGAN PERNAH COBA COLLECT DROPPAN YANG TERTUTUP BLOK SOLID!
        -- 1. Drop berada di dalam blok solid
        if isSolidTile(dtx, dty) then
            return false
        end

        -- 2. Drop berada di area locked pemain lain
        --if isTileLocked(dtx, dty) then
        --    return false
        --end

        -- 3. Drop terkurung rapat di keempat sisinya oleh blok solid tanpa celah akses
        if isSolidTile(dtx + 1, dty) and isSolidTile(dtx - 1, dty) and isSolidTile(dtx, dty + 1) and isSolidTile(dtx, dty - 1) then
            return false
        end

        return true
    end

    -- ── Phase 1: Local Sweep (Drop dekat <= 1.2 tile, sedot instan tanpa jalan) ──
    for i = #drops, 1, -1 do
        local drop = drops[i]
        if isDropEligible(drop) then
            local dropX = drop.x or px
            local dropY = drop.y or py
            local dx = dropX - origX
            local dy = dropY - origY
            local dist = math.sqrt(dx * dx + dy * dy)
            if dist <= 1.2 then
                local taken = tryPickupDrop(drop, inv)
                if taken > 0 then
                    totalCollected = totalCollected + taken
                    Magnet.totalPicked = Magnet.totalPicked + taken
                    passLimit = passLimit - 1
                    if passLimit <= 0 then break end
                end
            end
        end
    end

    if passLimit <= 0 then
        if totalCollected > 0 and refreshInventory then
            task.spawn(refreshInventory)
        end
        return totalCollected
    end

    -- Saat PNB aktif dan combo dengan Magnet:
    -- Jangan biarkan background magnet pathfind keluyuran ke seantero world!
    -- Biarkan alur siklus PNB yang menangani droppan di tile break secara bertahap & tertib.
    if PNB and PNB.active and not isManual then
        if totalCollected > 0 and refreshInventory then
            task.spawn(refreshInventory)
        end
        return totalCollected
    end

    -- ── Phase 2: FULL WORLD SWEEP (Radius >= 900) vs LOCAL RADIUS SWEEP ──
    if radius >= 900 then
        -- ═════════════════════════════════════════════════════════════
        -- FULL WORLD SWEEP: SAPU BERSIH ROW-BY-ROW UJUNG KE UJUNG
        -- ═════════════════════════════════════════════════════════════
        local rowsMap = {}
        local rowOrder = {}
        for _, drop in ipairs(drops) do
            if isDropEligible(drop) then
                local dy = math.floor(drop.y or 0)
                local dx = math.floor(drop.x or 0)
                if not rowsMap[dy] then
                    rowsMap[dy] = { minX = dx, maxX = dx, drops = {} }
                    table.insert(rowOrder, dy)
                else
                    if dx < rowsMap[dy].minX then rowsMap[dy].minX = dx end
                    if dx > rowsMap[dy].maxX then rowsMap[dy].maxX = dx end
                end
                table.insert(rowsMap[dy].drops, drop)
            end
        end

        if #rowOrder == 0 then
            if totalCollected > 0 and refreshInventory then task.spawn(refreshInventory) end
            return totalCollected
        end

        -- Urutkan baris dari atas ke bawah (Y ascending: 0 -> worldH)
        table.sort(rowOrder, function(a, b) return a < b end)

        for _, rY in ipairs(rowOrder) do
            if passLimit <= 0 then break end
            if not isMovementActive() and not isManual then break end
            local rowData = rowsMap[rY]
            if rowData and #rowData.drops > 0 then
                local curPx, curPy = getPlayerTilePos()
                curPx = curPx or origTileX
                curPy = curPy or origTileY

                -- Tentukan ujung terdekat untuk mulai sweep baris
                local startX, endX, stepX
                if math.abs(curPx - rowData.minX) <= math.abs(curPx - rowData.maxX) then
                    startX, endX, stepX = rowData.minX, rowData.maxX, 1
                else
                    startX, endX, stepX = rowData.maxX, rowData.minX, -1
                end

                if lblMagnetStats then
                    lblMagnetStats.Text = string.format("🧲 Sapu baris Y=%d (%d -> %d)...", rY, startX, endX)
                end

                -- Pathfind ke posisi awal baris
                local reached = walkOrPathfindTo(startX, rY)
                if not reached then
                    approachTile(startX, rY)
                end
                task.wait(0.02)

                -- Meluncur menyapu dari ujung ke ujung baris ini
                local cCol = startX
                while (stepX > 0 and cCol <= endX) or (stepX < 0 and cCol >= endX) do
                    if passLimit <= 0 then break end
                    if not isMovementActive() and not isManual then break end

                    -- Sedot drop dalam radius sedot 1.5 tile
                    for _, d in ipairs(rowData.drops) do
                        if d and d.uid and d.n and d.n > 0 and not d.taking then
                            local ddx = (d.x or cCol) - cCol
                            local ddy = (d.y or rY) - rY
                            if math.sqrt(ddx * ddx + ddy * ddy) <= 1.5 then
                                local taken = tryPickupDrop(d, inv)
                                if taken > 0 then
                                    totalCollected = totalCollected + taken
                                    Magnet.totalPicked = Magnet.totalPicked + taken
                                    passLimit = passLimit - 1
                                    if passLimit <= 0 then break end
                                end
                            end
                        end
                    end

                    local nextCol = cCol + stepX
                    if not isSolidTile(nextCol, rY) then
                        stepToColumn(nextCol, rY)
                        cCol = nextCol
                    else
                        break
                    end
                end
                task.wait(0.02)
            end
        end

        -- Return check: jika dontReturnToStart aktif, bot TETAP di titik akhir!
        if not Magnet.dontReturnToStart then
            local endPx, endPy = getPlayerTilePos()
            if endPx and endPy and (math.abs(endPx - origTileX) > 1 or math.abs(endPy - origTileY) > 1) then
                if lblMagnetStats then lblMagnetStats.Text = "🧲 Meluncur kembali ke posisi awal..." end
                local retPath = findPath(endPx, endPy, origTileX, origTileY, 25000)
                if retPath and #retPath > 0 then
                    followPath(retPath, Magnet.stepSize or 0.85)
                else
                    walkOrPathfindTo(origTileX, origTileY)
                end
            end
        end

        if totalCollected > 0 and refreshInventory then task.spawn(refreshInventory) end
        return totalCollected
    else
        -- ═════════════════════════════════════════════════════════════
        -- LOCAL RADIUS SWEEP (Radius < 900)
        -- ═════════════════════════════════════════════════════════════
        local candidateDrops = {}
        for _, drop in ipairs(drops) do
            if isDropEligible(drop) then
                local dropX = drop.x or px
                local dropY = drop.y or py
                local dx = dropX - origX
                local dy = dropY - origY
                local dist = math.sqrt(dx * dx + dy * dy)
                if dist > 1.2 and dist <= radius then
                    table.insert(candidateDrops, { drop = drop, x = dropX, y = dropY, dist = dist })
                end
            end
        end

        if #candidateDrops == 0 then
            if totalCollected > 0 and refreshInventory then task.spawn(refreshInventory) end
            return totalCollected
        end

        table.sort(candidateDrops, function(a, b) return a.dist < b.dist end)

        local maxDistantVisits = isManual and math.min(12, #candidateDrops) or math.min(4, #candidateDrops)
        local currentX, currentY = origX, origY
        local currentTileX, currentTileY = origTileX, origTileY

        for vIdx = 1, maxDistantVisits do
            if passLimit <= 0 then break end

            local bestDrop, bestDist = nil, 999999
            for _, cand in ipairs(candidateDrops) do
                if cand.drop and cand.drop.n and cand.drop.n > 0 and not cand.drop.taking then
                    local cdx = cand.x - currentX
                    local cdy = cand.y - currentY
                    local cdist = math.sqrt(cdx * cdx + cdy * cdy)
                    if cdist < bestDist then
                        bestDist = cdist
                        bestDrop = cand.drop
                    end
                end
            end

            if not bestDrop then break end

            local targetX = bestDrop.x or currentX
            local targetY = bestDrop.y or currentY
            local targetTileX = math.floor(targetX)
            local targetTileY = math.floor(targetY)

            local path = findPath(currentTileX, currentTileY, targetTileX, targetTileY, 25000)
            if path and #path > 0 then
                if lblMagnetStats then
                    lblMagnetStats.Text = string.format("🧲 Pathfind ke (%d, %d)...", targetTileX, targetTileY)
                end
                followPath(path, Magnet.stepSize or 0.85, currentX, currentY)
                local lastT = path[#path]
                currentTileX = lastT.x
                currentTileY = lastT.y
                currentX = lastT.x + 0.5
                currentY = lastT.y + 1.0

                local taken = tryPickupDrop(bestDrop, inv)
                if taken > 0 then
                    totalCollected = totalCollected + taken
                    Magnet.totalPicked = Magnet.totalPicked + taken
                    passLimit = passLimit - 1
                end

                -- Cluster Vacuum
                for _, drop in ipairs(drops) do
                    if isDropEligible(drop) and drop ~= bestDrop then
                        local dx = (drop.x or currentX) - currentX
                        local dy = (drop.y or currentY) - currentY
                        if math.sqrt(dx * dx + dy * dy) <= 1.2 then
                            local clusterTaken = tryPickupDrop(drop, inv)
                            if clusterTaken > 0 then
                                totalCollected = totalCollected + clusterTaken
                                Magnet.totalPicked = Magnet.totalPicked + clusterTaken
                                passLimit = passLimit - 1
                                if passLimit <= 0 then break end
                            end
                        end
                    end
                end
            else
                bestDrop.taking = false
                if unreachableDrops then unreachableDrops[bestDrop.uid or bestDrop] = true end
            end
        end

        -- ── Phase 3: Pathfind Return to Original Position (Aman Bebas Tabrak) ──
        if not Magnet.dontReturnToStart then
            local returnDist = math.sqrt((currentX - origX)^2 + (currentY - origY)^2)
            if returnDist > 0.4 then
                if lblMagnetStats then lblMagnetStats.Text = "🧲 Meluncur kembali ke posisi awal..." end
                local returnPath = findPath(currentTileX, currentTileY, origTileX, origTileY, 25000)
                if returnPath and #returnPath > 0 then
                    followPath(returnPath, Magnet.stepSize or 0.85, currentX, currentY)
                else
                    walkOrPathfindTo(origTileX, origTileY)
                end
            end
            local endPx, endPy = getPlayerTilePos()
            if endPx == origTileX and endPy == origTileY then
                safeSendMove({
                    x = origX,
                    y = origY,
                    vx = 0,
                    vy = 0,
                    flags = 2,
                })
            end
        end
    end

    if totalCollected > 0 and refreshInventory then
        task.spawn(refreshInventory)
    end

    return totalCollected
end

local function startMagnetLoop()
    if Magnet.thread then return end
    Magnet.thread = task.spawn(function()
        while Magnet.enabled do
            if AntiStaff and AntiStaff.isFrozen then
                task.wait(1)
            else
                if not Magnet.busy then
                Magnet.busy = true
                local count = sweepDrops(Magnet.radius, Magnet.filterMode, 20)
                if count > 0 and lblMagnetStats then
                    lblMagnetStats.Text = string.format("● Tersedot: %d item | Rad: %s | Flt: %s",
                        Magnet.totalPicked,
                        (Magnet.radius >= 900 and "World" or (Magnet.radius .. "T")),
                        Magnet.filterMode)
                end
                Magnet.busy = false
                end
            end
            task.wait(Magnet.delay)
        end
        Magnet.thread = nil
    end)
end

local function stopMagnetLoop()
    Magnet.enabled = false
    Magnet.thread = nil
end

-- ═══════════════════════════════════════
--  MOBILITY INPUT CONTROLLER
-- ═══════════════════════════════════════
UserInputService.InputBegan:Connect(function(input, gpe)
    if not gpe and ClickPathfind and ClickPathfind.enabled then
        local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
        local isShift = isMobile or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
        if isShift and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            handleScreenClickPathfind(input.Position.X, input.Position.Y)
        end
    end
end)

RunService.Heartbeat:Connect(function(dt)
    if Mobility.speedEnabled then
        ensureMobilityHooks()
    end
end)

-- ═══════════════════════════════════════
--  PNB STATE
-- ═══════════════════════════════════════
PNB = {
    active      = false,
    mode        = "PNB",      -- "PNB" | "BREAK" | "PLACE"
    layer       = "fg",       -- "fg" | "bg"
    itemId      = 2,          -- Default Dirt = 2
    itemName    = "Dirt",
    itemKind    = "block",
    hits        = 3,          -- Hits durabilitas blok
    hitDelay    = 0.18,       -- Cooldown antar hit
    loopDelay   = 0.12,       -- Jeda antar siklus
    targets     = {           -- Multi-target offset: ["dx_dy"] = {dx = X, dy = Y}
        ["1_0"] = { dx = 1, dy = 0 } -- Default: 1 tile di Kanan (+1, 0)
    },
    busy        = false,
    thread      = nil,
}

local function getSortedTargetList()
    local list = {}
    for _, t in pairs(PNB.targets) do
        table.insert(list, t)
    end
    table.sort(list, function(a, b)
        if a.dx == b.dx then
            return a.dy < b.dy
        end
        return a.dx < b.dx
    end)
    return list
end

-- ═══════════════════════════════════════
--  INVENTORY FETCHER & AUTO-DETECTION
-- ═══════════════════════════════════════
local function fetchInventoryItems()
    local items = {}
    local nativeInv = getNativeInventory()
    if nativeInv and type(nativeInv.slots) == "table" and #nativeInv.slots > 0 then
        for _, slot in ipairs(nativeInv.slots) do
            local id = slot.id or slot[1]
            local count = slot.n or slot[2]
            if id and count and count > 0 then
                local dbEntry = ItemDB and ItemDB[id] or {}
                local kind = dbEntry.kind or "block"

                if kind ~= "cloth" and kind ~= "tool" and kind ~= "gem" then
                    local isBg = (dbEntry.background == true)
                    local hits = dbEntry.hits
                    if not hits then
                        hits = (kind == "seed") and 1 or 3
                    end

                    table.insert(items, {
                        id = id,
                        count = count,
                        name = dbEntry.name or ("Item #" .. id),
                        kind = kind,
                        isBg = isBg,
                        layer = isBg and "bg" or "fg",
                        hits = hits,
                    })
                end
            end
        end
        if #items > 0 then return items end
    end

    local inv = nil
    if Net and Net.call then
        local ok, res = pcall(Net.call, "GetInventory")
        if ok and type(res) == "table" then
            inv = res
        end
    end
    if not inv and WorldRemotes and WorldRemotes:FindFirstChild("GetInventory") then
        local ok, res = pcall(WorldRemotes.GetInventory.InvokeServer, WorldRemotes.GetInventory)
        if ok and type(res) == "table" then
            inv = res
        end
    end
    if inv and type(inv) == "table" and type(inv.slots) == "table" then
        for _, slot in ipairs(inv.slots) do
            local id, count = slot[1], slot[2]
            if id and count and count > 0 then
                local dbEntry = ItemDB and ItemDB[id] or {}
                local kind = dbEntry.kind or "block"

                if kind ~= "cloth" and kind ~= "tool" and kind ~= "gem" then
                    local isBg = (dbEntry.background == true)
                    local hits = dbEntry.hits
                    if not hits then
                        hits = (kind == "seed") and 1 or 3
                    end

                    table.insert(items, {
                        id = id,
                        count = count,
                        name = dbEntry.name or ("Item #" .. id),
                        kind = kind,
                        isBg = isBg,
                        layer = isBg and "bg" or "fg",
                        hits = hits,
                    })
                end
            end
        end
    end
    return items
end

-- ═══════════════════════════════════════
--  REAL-TIME TILE & INVENTORY ENGINE
-- ═══════════════════════════════════════
local function getRealtimeTile(layer, tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return nil end
    local w = getNativeWorld()
    if not w then return nil end
    layer = string.lower(tostring(layer or "fg"))
    local grid = (layer == "bg") and w.bg or w.fg
    if grid and grid[ty] then
        return grid[ty][tx] or 0
    end
    return 0
end
_G.getRealtimeTile = getRealtimeTile

getRealtimeItemCount = function(itemId)
    if not itemId then return 0 end
    local inv = getNativeInventory()
    if inv then
        if inv.count then
            local ok, c = pcall(inv.count, inv, itemId)
            if ok and type(c) == "number" and c > 0 then return c end
        end
        if type(inv.slots) == "table" then
            local total = 0
            for _, s in ipairs(inv.slots) do
                local sid = s.id or s[1]
                if sid == itemId then
                    total = total + (s.n or s[2] or 0)
                end
            end
            if total > 0 then return total end
        end
    end

    local items = fetchInventoryItems()
    local total = 0
    for _, it in ipairs(items) do
        if it.id == itemId then
            total = total + (it.count or 0)
        end
    end
    return total
end

_G.getRealtimeItemCount = getRealtimeItemCount

findBlockForSeed = function(seedId)
    if not seedId or not ItemDB then return (seedId and seedId - 1) or 2 end
    local s = ItemDB[seedId]
    if not s then return seedId - 1 end
    if s.block and type(s.block) == "number" and s.block > 0 then return s.block end

    -- Check direct predecessor (seedId - 1)
    local prev = ItemDB[seedId - 1]
    if prev and s.name and prev.name then
        local cleanSeedName = s.name:gsub("%s*[Ss]eed%s*$", ""):lower()
        if prev.name:lower() == cleanSeedName then
            return seedId - 1
        end
    end

    if prev and prev.kind ~= "seed" then
        return seedId - 1
    end

    if s.name then
        local cleanSeedName = s.name:gsub("%s*[Ss]eed%s*$", ""):lower()
        for id, it in pairs(ItemDB) do
            if type(it) == "table" and it.name and it.name:lower() == cleanSeedName and it.kind ~= "seed" then
                return id
            end
        end
    end

    return seedId - 1
end
_G.findBlockForSeed = findBlockForSeed

sweepTargetDropsRowByRow = function(tItemId, maxCount)
    maxCount = maxCount or 180
    local w = getNativeWorld and getNativeWorld()
    if not w or not w.dropList then return 0 end
    local curDList = w.dropList() or {}
    local inv = getNativeInventory and getNativeInventory()
    local worldW = (w and w.w) or 100
    local worldH = (w and w.h) or 60

    local rowMap = {}
    local rowList = {}
    for _, d in ipairs(curDList) do
        if d and d.uid and d.id == tItemId and not d.taking then
            local dtx = math.floor(d.x or 0)
            local dty = math.floor(d.y or 0)
            if not isSolidTile(dtx, dty) then
                if not rowMap[dty] then
                    rowMap[dty] = { minX = dtx, maxX = dtx, drops = {} }
                    table.insert(rowList, dty)
                else
                    if dtx < rowMap[dty].minX then rowMap[dty].minX = dtx end
                    if dtx > rowMap[dty].maxX then rowMap[dty].maxX = dtx end
                end
                table.insert(rowMap[dty].drops, d)
            end
        end
    end

    if #rowList == 0 then return 0 end
    table.sort(rowList, function(a, b) return a < b end)

    local collected = 0
    for _, rY in ipairs(rowList) do
        if not isMovementActive() and not (AutoRotation and AutoRotation.active) and not (AutoBuildDF and AutoBuildDF.active) then break end
        local curCount = (getRealtimeItemCount and getRealtimeItemCount(tItemId)) or 0
        if curCount >= maxCount then break end

        local rData = rowMap[rY]
        if rData and #rData.drops > 0 then
            local curPx, curPy = getPlayerTilePos()
            curPx = curPx or rData.minX
            curPy = curPy or rY

            local startX, endX, stepX
            if math.abs(curPx - rData.minX) <= math.abs(curPx - rData.maxX) then
                startX, endX, stepX = rData.minX, rData.maxX, 1
            else
                startX, endX, stepX = rData.maxX, rData.minX, -1
            end

            local reached = walkOrPathfindTo and walkOrPathfindTo(startX, rY, worldW, worldH)
            if not reached and approachTile then
                approachTile(startX, rY, worldW, worldH)
            end
            task.wait(0.02)

            local cX = startX
            while (stepX > 0 and cX <= endX) or (stepX < 0 and cX >= endX) do
                if not isMovementActive() and not (AutoRotation and AutoRotation.active) and not (AutoBuildDF and AutoBuildDF.active) then break end
                local countNow = (getRealtimeItemCount and getRealtimeItemCount(tItemId)) or 0
                if countNow >= maxCount then break end

                for _, d in ipairs(rData.drops) do
                    if d and d.uid and not d.taking and d.id == tItemId then
                        local ddx = (d.x or cX) - cX
                        local ddy = (d.y or rY) - rY
                        if math.sqrt(ddx * ddx + ddy * ddy) <= 1.5 then
                            local taken = (tryPickupDrop and tryPickupDrop(d, inv)) or 0
                            if taken > 0 then
                                collected = collected + taken
                                if ((getRealtimeItemCount and getRealtimeItemCount(tItemId)) or 0) >= maxCount then break end
                            end
                        end
                    end
                end

                local nextX = cX + stepX
                if not isSolidTile(nextX, rY) and stepToColumn then
                    stepToColumn(nextX, rY)
                    cX = nextX
                else
                    break
                end
            end
        end
    end

    if collected > 0 and refreshInventory then
        task.spawn(refreshInventory)
    end
    return collected
end
_G.sweepTargetDropsRowByRow = sweepTargetDropsRowByRow


local invHooked = false
local function hookRealtimeInventory()
    if invHooked then return end
    local inv = getNativeInventory()
    if inv and inv.changed and inv.changed.Event then
        inv.changed.Event:Connect(function()
            task.spawn(function()
                -- Auto-Stop check secara real-time saat stok item berubah di tas
                if PNB and PNB.active and (PNB.mode == "PLACE" or PNB.mode == "PNB") then
                    local stock = getRealtimeItemCount(PNB.itemId)
                    if stock <= 0 then
                        if stopPNB then stopPNB() end
                        if lblStatus then
                            lblStatus.Text = string.format("● STOP: Item '%s' (#%d) di tas habis!", PNB.itemName or "Target", PNB.itemId)
                            lblStatus.TextColor3 = C.gold
                        end
                    end
                end

                -- Live update dropdown text jumlah item saat ini
                if btnDropdown and PNB and PNB.itemId then
                    local stock = getRealtimeItemCount(PNB.itemId)
                    btnDropdown.Text = string.format("📦 [%s] %s x%d",
                        string.upper(PNB.layer or "fg"),
                        PNB.itemName or ("Item #" .. PNB.itemId),
                        stock)
                end
            end)
        end)
        invHooked = true
    end
end

-- ═══════════════════════════════════════
--  PNB ACTIONS (REAL-TIME ADAPTIVE)
-- ═══════════════════════════════════════
local function executePlace(tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return false end

    local layer = string.lower(tostring(PNB.layer or "fg"))
    if layer ~= "fg" and layer ~= "bg" then layer = "fg" end

    -- Real-time check: pastikan tile kosong (0) sebelum menempatkan blok
    local cur = getRealtimeTile(layer, tx, ty)
    if cur and cur ~= 0 then
        return false -- Sudah ada blok, jangan buang item
    end

    -- Legit player facing towards placement target
    local px, py, rawX, rawY = getPlayerTilePos()
    if px and rawX and rawY and safeSendMove then
        local facingBit = (tx >= px) and 1 or 0
        safeSendMove({
            x = rawX,
            y = rawY,
            vx = 0,
            vy = 0,
            flags = 2 + facingBit
        })
    end

    local actKind = (PNB.itemKind == "seed") and ACT_KIND.PLANT or ACT_KIND.BUILD
    sendActPacket(actKind, tx, ty)
    sendTilePacket(layer, tx, ty, PNB.itemId, false)
    forceClientTileUpdate(layer, tx, ty, PNB.itemId)

    -- Kurangi inventory lokal seketika (Sync Backpack Real-time persis Auto DF)
    local inv = getNativeInventory and getNativeInventory()
    if inv and inv.remove then
        pcall(inv.remove, inv, PNB.itemId, 1)
    end
    if refreshInventory then task.spawn(refreshInventory) end

    return true
end

local function executeBreak(tx, ty, autoSweep)
    if not tx or not ty or tx < 0 or ty < 0 then return false end

    local layer = string.lower(tostring(PNB.layer or "fg"))
    if layer ~= "fg" and layer ~= "bg" then layer = "fg" end

    -- Real-time check: pastikan ada blok di target sebelum mulai memukul
    local cur = getRealtimeTile(layer, tx, ty)
    if cur == 0 then
        return true -- Target sudah kosong (air) / sudah hancur
    end

    -- Legit player facing towards break target
    local px, py, rawX, rawY = getPlayerTilePos()
    if px and rawX and rawY and safeSendMove then
        local facingBit = (tx >= px) and 1 or 0
        safeSendMove({
            x = rawX,
            y = rawY,
            vx = 0,
            vy = 0,
            flags = 2 + facingBit
        })
    end

    local totalHits = math.max(1, PNB.hits)

    for i = 1, totalHits do
        if not PNB.active then return false end

        -- Cek apakah blok sudah pecah di tengah-tengah pukulan
        if i > 1 and getRealtimeTile(layer, tx, ty) == 0 then
            break
        end

        sendActPacket(ACT_KIND.HIT, tx, ty)
        if i < totalHits then
            task.wait(PNB.hitDelay)
        end
    end

    task.wait(0.015)
    sendTilePacket(layer, tx, ty, 0, false)
    forceClientTileUpdate(layer, tx, ty, 0)

    -- Auto-sweep drops seketika jika Magnet aktif dan autoSweep diizinkan (tidak sedang dihandle alur PNB)
    if autoSweep ~= false and Magnet and Magnet.enabled and not (PNB and PNB.active) then
        task.spawn(function()
            sweepDrops(Magnet.radius, Magnet.filterMode, 15)
        end)
    end

    return true
end

collectDropsAtTiles = function(targetTiles, homePx, homePy, homeRawX, homeRawY)
    _G.collectDropsAtTiles = collectDropsAtTiles
    local w = getNativeWorld()
    if not w or not w.dropList then return 0 end

    -- Beri jeda sangat singkat agar packet drop dari server terbaca di client dropList
    task.wait(0.03)

    local drops = w.dropList()
    if not drops or #drops == 0 then return 0 end

    local inv = getNativeInventory()
    local targetItemId = (AutoFactory and AutoFactory.active and AutoFactory.targetBlockId) or (PNB and PNB.itemId or 2)
    local totalCollected = 0

    local function isDropOnTargetTiles(drop)
        if not drop or not drop.uid or not drop.n or drop.n <= 0 or drop.taking then
            return false
        end
        if unreachableDrops and unreachableDrops[drop.uid or drop] then
            return false
        end
        if ClearWorld and ClearWorld.active then
            -- Pada Clear World: kumpulkan SEMUA droppan (item & gem) di sekitar tile yang di-break
        elseif AutoRotation and AutoRotation.active then
            -- Pada Auto Rotation: kumpulkan SEMUA droppan (target block, seed, gem) di sekitar tile break
        elseif AutoFactory and AutoFactory.active then
            -- Pada Auto Factory: selalu kumpulkan seed, blok target, dan gems
            if drop.id ~= AutoFactory.targetSeedId and drop.id ~= AutoFactory.targetBlockId and drop.id ~= 112 then
                return false
            end
        elseif Magnet and Magnet.filterMode == "GEMS" then
            if drop.id ~= 112 then return false end
        elseif Magnet and Magnet.filterMode == "ITEMS" then
            if drop.id == 112 then return false end
        elseif Magnet and Magnet.filterMode == "CURRENT" then
            if drop.id ~= targetItemId and drop.id ~= 112 then return false end
        end

        local dtx = math.floor(drop.x or 0)
        local dty = math.floor(drop.y or 0)

        if isSolidTile(dtx, dty) or isTileLocked(dtx, dty) then
            return false
        end

        -- Cek apakah drop berada di sekitar salah satu tile target break (jarak <= 1.8 tile)
        for _, t in ipairs(targetTiles) do
            local ddx = (drop.x or 0) - (t.x + 0.5)
            local ddy = (drop.y or 0) - (t.y + 0.5)
            if (ddx * ddx + ddy * ddy) <= 3.24 then
                return true
            end
        end

        return false
    end

    local dropsToPick = {}
    for _, drop in ipairs(drops) do
        if isDropOnTargetTiles(drop) then
            table.insert(dropsToPick, drop)
        end
    end

    if #dropsToPick == 0 then
        return 0
    end

    local curPx, curPy, curRawX, curRawY = getPlayerTilePos()
    local cX = curRawX or (curPx and (curPx + 0.5)) or homeRawX
    local cY = curRawY or (curPy and (curPy + 1.0)) or homeRawY

    -- Cek apakah semua drop bisa dijangkau langsung tanpa bergeser (jarak <= 1.35 tile)
    local allNearby = true
    for _, drop in ipairs(dropsToPick) do
        local dx = (drop.x or cX) - cX
        local dy = (drop.y or cY) - cY
        if math.sqrt(dx * dx + dy * dy) > 1.35 then
            allNearby = false
            break
        end
    end

    if allNearby then
        -- Semua droppan berada dalam jangkauan sedot langsung, ambil seketika tanpa bergeser
        for _, drop in ipairs(dropsToPick) do
            local taken = tryPickupDrop(drop, inv)
            if taken > 0 then
                totalCollected = totalCollected + taken
                if Magnet then Magnet.totalPicked = (Magnet.totalPicked or 0) + taken end
            end
        end
    else
        -- Ada drop yang agak jauh (> 1.35 tile):
        -- Jalan ke tile break, sedot, lalu balik ke tempat semula
        local stepped = false
        local visited = {}
        for _, t in ipairs(targetTiles) do
            local key = t.x .. "," .. t.y
            if not visited[key] then
                visited[key] = true
                -- Cek apakah ada drop di dekat tile t ini
                local hasDropAtT = false
                for _, drop in ipairs(dropsToPick) do
                    local ddx = (drop.x or 0) - (t.x + 0.5)
                    local ddy = (drop.y or 0) - (t.y + 0.5)
                    if (ddx * ddx + ddy * ddy) <= 2.25 and not drop.taking and drop.n and drop.n > 0 then
                        hasDropAtT = true
                        break
                    end
                end

                if hasDropAtT then
                    if stepToColumn then
                        stepToColumn(t.x, t.y)
                        stepped = true
                    end
                    task.wait(0.02)
                    for _, drop in ipairs(dropsToPick) do
                        if not drop.taking and drop.n and drop.n > 0 then
                            local taken = tryPickupDrop(drop, inv)
                            if taken > 0 then
                                totalCollected = totalCollected + taken
                                if Magnet then Magnet.totalPicked = (Magnet.totalPicked or 0) + taken end
                            end
                        end
                    end
                end
            end
        end

        -- Balik ke posisi semula (home) secara mulus
        if stepped then
            if stepToColumn and homePx and homePy then
                stepToColumn(homePx, homePy)
            end
            if homeRawX and homeRawY then
                setInternalPlayerPos(homeRawX, homeRawY)
                safeSendMove({
                    x = homeRawX,
                    y = homeRawY,
                    vx = 0,
                    vy = 0,
                    flags = 2,
                })
            end
            task.wait(0.02)
        end
    end

    if totalCollected > 0 and refreshInventory then
        task.spawn(refreshInventory)
    end

    return totalCollected
end

local function executeCycle(onTargetStep)
    if PNB.busy or not PNB.active or (ClearWorld and ClearWorld.active) or (AntiStaff and AntiStaff.isFrozen) then return end
    if Magnet and Magnet.busy then return end
    PNB.busy = true

    local targets = getSortedTargetList()
    if #targets == 0 then
        PNB.busy = false
        return
    end

    local px, py, rawX, rawY = getPlayerTilePos()
    if not px or not py then
        PNB.busy = false
        return
    end

    local homeRawX = rawX or (px + 0.5)
    local homeRawY = py + 1.0

    local layer = string.lower(tostring(PNB.layer or "fg"))
    if layer ~= "fg" and layer ~= "bg" then layer = "fg" end

    -- Real-time Inventory Check:
    -- Jika mode PLACE atau PNB: otomatis hentikan jika item habis!
    if PNB.mode == "PLACE" or PNB.mode == "PNB" then
        local stock = getRealtimeItemCount(PNB.itemId)
        if stock <= 0 then
            if stopPNB then stopPNB() end
            if lblStatus then
                lblStatus:set(string.format("`4[!] STOP: Item '%s' (#%d) di tas habis!``", PNB.itemName or "Item", PNB.itemId))
            end
            PNB.busy = false
            return
        end
    end
    -- Jika BREAK ONLY: JANGAN PERNAH BERHENTI (tetap looping & waiting)

    if PNB.mode == "PLACE" then
        for idx, target in ipairs(targets) do
            if not PNB.active then break end
            if getRealtimeItemCount(PNB.itemId) <= 0 then
                if stopPNB then stopPNB() end
                if lblStatus then
                    lblStatus:set(string.format("`4[!] STOP: Item '%s' habis!``", PNB.itemName or "Item"))
                end
                break
            end
            local tx, ty = px + target.dx, py + target.dy
            local curTile = getRealtimeTile(layer, tx, ty)
            if curTile == 0 then
                if onTargetStep then onTargetStep(idx, #targets, tx, ty) end
                executePlace(tx, ty)
                task.wait(0.09)
            end
        end

    elseif PNB.mode == "BREAK" then
        -- BREAK ONLY: hancurkan SEMUA target yang ada bloknya, lalu sedot droppan
        local hadBlocks = false
        local brokenTiles = {}
        for idx, target in ipairs(targets) do
            if not PNB.active then break end
            local tx, ty = px + target.dx, py + target.dy
            local curTile = getRealtimeTile(layer, tx, ty)
            if curTile and curTile ~= 0 then
                hadBlocks = true
                if onTargetStep then onTargetStep(idx, #targets, tx, ty) end
                executeBreak(tx, ty, false)
                table.insert(brokenTiles, { x = tx, y = ty })
                task.wait(0.02)
            end
        end

        -- Jika Auto Collect / Magnet aktif: sedot droppan dari SEMUA tile yang baru di-break, lalu balik ke home
        if Magnet and Magnet.enabled and #brokenTiles > 0 then
            collectDropsAtTiles(brokenTiles, px, py, homeRawX, homeRawY)
        end

        -- Jika semua target sedang kosong, tunggu sebentar lalu loop lagi tanpa berhenti!
        if not hadBlocks then
            task.wait(0.12)
        end

    elseif PNB.mode == "PNB" then
        -- 1. Phase Place: tempatkan blok pada SEMUA target yang kosong sekaligus
        for idx, target in ipairs(targets) do
            if not PNB.active then break end
            if getRealtimeItemCount(PNB.itemId) <= 0 then
                if stopPNB then stopPNB() end
                if lblStatus then
                    lblStatus:set(string.format("`4[!] STOP: Item '%s' habis saat PNB!``", PNB.itemName or "Item"))
                end
                break
            end
            local tx, ty = px + target.dx, py + target.dy
            local curTile = getRealtimeTile(layer, tx, ty)
            if curTile == 0 then
                if onTargetStep then onTargetStep(idx, #targets, tx, ty) end
                executePlace(tx, ty)
                task.wait(0.09)
            end
        end

        task.wait(0.05)

        -- 2. Phase Break: hancurkan blok pada SEMUA target yang terisi
        local brokenTiles = {}
        for idx, target in ipairs(targets) do
            if not PNB.active then break end
            local tx, ty = px + target.dx, py + target.dy
            local curTile = getRealtimeTile(layer, tx, ty)
            if curTile and curTile ~= 0 then
                if onTargetStep then onTargetStep(idx, #targets, tx, ty) end
                executeBreak(tx, ty, false)
                table.insert(brokenTiles, { x = tx, y = ty })
                task.wait(0.02)
            end
        end

        -- 3. Phase Collect: Jika Magnet/Auto Collect aktif, sedot droppan dari SEMUA target break lalu kembali ke posisi home!
        if Magnet and Magnet.enabled and #brokenTiles > 0 then
            collectDropsAtTiles(brokenTiles, px, py, homeRawX, homeRawY)
        end
    end

    PNB.busy = false
end

-- ═══════════════════════════════════════
--  CLEAR WORLD AUTOMATION ENGINE (v10.2 - Smart Range & Pathfind)
-- ═══════════════════════════════════════
ClearWorld = {
    active         = false,
    busy           = false,
    clearBG        = true,       -- Hancurkan juga background
    autoSweep      = true,       -- Sapu / sedot droppan dari blok yang di-break
    autoTrash      = false,      -- Auto recycle/trash hasil sapuan agar tas tidak penuh
    hitDelay       = 0.17,       -- Delay per hit (sesuai cooldown native game agar tidak di-drop server)
    totalCleared   = 0,
    thread         = nil,
}

local function isBedrockTile(id)
    if not id or id == 0 then return false end
    if id == 8 then return true end
    local it = ItemDB and ItemDB[id]
    if it then
        if it.bedrock == true or it.unbreakable == true then return true end
        if it.hits and it.hits <= 0 then return true end
        local name = it.name and string.lower(it.name) or ""
        if string.find(name, "bedrock") then return true end
    end
    return false
end

local function isProtectedTile(id)
    if not id or id == 0 then return false end
    if id == 6 or id == 8 then return true end -- 6 = Main Door, 8 = Bedrock
    if id == 4992 and _G.SysHubClientAGActive then return true end -- AG client (/ag) = bedrock asli

    local it = ItemDB and ItemDB[id]
    if not it then return false end

    -- Indestructible (Bedrock, Main Door, hits <= 0)
    if it.hits and it.hits <= 0 then return true end
    if it.bedrock or it.unbreakable then return true end

    -- Locks & Area Locks
    if it.lock or it.area then return true end

    local name = it.name and string.lower(it.name) or ""
    if name == "main door" or name == "bedrock" then return true end

    -- Any lock item
    if string.find(name, "lock") then
        if not string.find(name, "clock")
           and not string.find(name, "block")
           and not string.find(name, "seed")
           and not string.find(name, "mask")
           and not string.find(name, "shades")
           and not string.find(name, "leash")
           and not string.find(name, "sign") then
            return true
        end
    end

    return false
end

local function isTileBreakable(layer, tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return false end

    local fg = getRealtimeTile("fg", tx, ty)
    -- ATURAN 1: JIKA TILE FG ADALAH BEDROCK ATAU PROTECTED (DOOR/LOCK), SKIP ALL!
    -- Background di belakang atau tepat di tile bedrock TIDAK BOLEH dan TIDAK BISA disentuh!
    if fg and fg ~= 0 and (isBedrockTile(fg) or isProtectedTile(fg)) then
        return false
    end

    local bg = getRealtimeTile("bg", tx, ty)
    if bg and bg ~= 0 and (isBedrockTile(bg) or isProtectedTile(bg)) then
        if layer == "bg" then return false end
    end

    if layer == "fg" then
        return (fg and fg ~= 0 and not isProtectedTile(fg) and not isBedrockTile(fg))
    elseif layer == "bg" then
        if not ClearWorld.clearBG then return false end
        return (bg and bg ~= 0 and not isProtectedTile(bg) and not isBedrockTile(bg))
    end
    return false
end

-- Menentukan apakah tile (tx, ty) memiliki blok breakable yang valid (FG atau BG)
local function hasBreakableAtTile(tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return false end
    local fg = getRealtimeTile("fg", tx, ty)
    -- Jika FG adalah bedrock atau protected, SKIP ALL (jangan target tile ini!)
    if fg and fg ~= 0 and (isBedrockTile(fg) or isProtectedTile(fg)) then
        return false
    end
    if isTileBreakable("fg", tx, ty) then
        return true
    end
    if ClearWorld.clearBG and isTileBreakable("bg", tx, ty) then
        return true
    end
    return false
end

local function getBlockHits(id)
    if not id or id == 0 then return 0 end
    local it = ItemDB and ItemDB[id]
    if it and it.hits and it.hits > 0 then
        return it.hits
    end
    if it and it.kind == "seed" then
        return 1
    end
    return 3
end

local calculateBlockHits = getBlockHits



-- Eksekusi penghancuran tile secara realtime dengan safety check jarak <= 2 tile
local function breakTileRealtime(layer, tx, ty, worldW, worldH)
    if not tx or not ty or tx < 0 or ty < 0 then return true end
    if not ClearWorld.active then return false end

    local curId = getRealtimeTile(layer, tx, ty)
    if not curId or curId == 0 or isProtectedTile(curId) or isBedrockTile(curId) then
        return true -- Sudah kosong atau tidak boleh dihancurkan
    end

    -- CEK JARAK REALTIME: Jika jarak > 2 tile, langsung pathfind ulang ke dekat target!
    local inRange = ensureTileInRange(tx, ty, worldW or 100, worldH or 60)
    if not inRange then
        return false -- Tidak terjangkau, jangan memukul dari jauh
    end

    local reqHits = getBlockHits(curId)
    local hitDelay = ClearWorld.hitDelay or 0.17

    -- Kirim paket pukulan (HIT) sesuai kebutuhan durabilitas blok
    for h = 1, reqHits do
        if not ClearWorld.active then return false end
        if h > 1 and getRealtimeTile(layer, tx, ty) == 0 then
            break -- Sudah pecah lebih awal
        end
        sendActPacket(ACT_KIND.HIT, tx, ty)
        task.wait(hitDelay)
    end

    -- Safety hit ekstra jika blok keras (> 1 hit) untuk mencegah paket drop akibat lag
    if reqHits > 1 and getRealtimeTile(layer, tx, ty) ~= 0 then
        sendActPacket(ACT_KIND.HIT, tx, ty)
        task.wait(0.04)
    end

    -- Komit penghancuran ke server dan paksa update visual client
    sendTilePacket(layer, tx, ty, 0, false)
    forceClientTileUpdate(layer, tx, ty, 0)
    task.wait(0.02)

    return (getRealtimeTile(layer, tx, ty) == 0)
end

-- STRICT WHITELIST: Hanya ID blok/seed natural sampah hasil world generation yang diizinkan untuk di-trash!
-- Di luar 8 ID ini (atau rarity > 1, clothing, tool, lock, farmable lain), DILARANG KERAS DI-TRASH!
local SAFE_WORLD_JUNK_IDS = {
    [2]  = true, -- Dirt
    [3]  = true, -- Dirt Seed
    [4]  = true, -- Lava
    [5]  = true, -- Lava Seed
    [10] = true, -- Rock
    [11] = true, -- Rock Seed
    [14] = true, -- Cave Background
    [15] = true, -- Cave Background Seed
}

local function isSafeNaturalJunk(itemId)
    if not itemId or itemId <= 0 or itemId == 112 then return false end
    if not SAFE_WORLD_JUNK_IDS[itemId] then return false end

    local it = ItemDB and ItemDB[itemId]
    if it then
        if it.rarity and it.rarity > 1 then return false end
        if it.slot then return false end -- clothing / wearables / wings / hats
        if it.kind == "tool" then return false end
        if it.lock or it.area or it.bedrock or it.unbreakable then return false end
    end
    return true
end

-- Hanya membuang sejumlah 'amount' spesifik dari item sampah hasil break yang baru dipungut
local function trashSpecificJunkItem(itemId, amount)
    if not isSafeNaturalJunk(itemId) then return end
    if not amount or amount <= 0 then return end

    local inv = getNativeInventory()
    if not inv then return end

    local totalCount = getRealtimeItemCount(itemId)
    if totalCount <= 0 then return end

    local countToTrash = math.min(math.floor(amount), totalCount)
    if countToTrash <= 0 then return end

    if inv.remove then
        pcall(inv.remove, inv, itemId, countToTrash)
    end

    local curr = nil
    pcall(function()
        local LP = Players.LocalPlayer
        local invModule = LP and LP:FindFirstChild("PlayerGui") and LP.PlayerGui:FindFirstChild("GameGui") and LP.PlayerGui.GameGui:FindFirstChild("InventoryUI")
        if invModule then
            local ok, mod = pcall(require, invModule)
            if ok and mod and mod.current then curr = mod.current end
        end
    end)

    sendRecyclePacket(itemId, countToTrash)

    if curr and curr.refresh then pcall(curr.refresh) end
end

-- Membersihkan satu kolom band (FG & BG) + Sweep Droppan + Strict Delta Auto-Trash
local function clearColumnBandRealtime(colX, bandRows, worldW, worldH)
    if not ClearWorld.active or not colX or colX < 0 or colX >= worldW then return end

    local brokenTiles = {}
    local brokenJunkIds = {}

    for _, rowY in ipairs(bandRows) do
        if not ClearWorld.active then break end
        if rowY >= 0 and rowY < worldH then
            -- 1. Foreground (FG)
            if isTileBreakable("fg", colX, rowY) then
                local fg = getRealtimeTile("fg", colX, rowY)
                if lblClearStatus and fg and fg ~= 0 then
                    local it = ItemDB and ItemDB[fg]
                    local name = it and it.name or ("ID " .. fg)
                    lblClearStatus.Text = string.format("⛏️ [FG] %s di (%d, %d)...", name, colX, rowY)
                end
                if fg and isSafeNaturalJunk(fg) then
                    brokenJunkIds[fg] = true
                    if isSafeNaturalJunk(fg + 1) then
                        brokenJunkIds[fg + 1] = true
                    end
                end
                breakTileRealtime("fg", colX, rowY, worldW, worldH)
                table.insert(brokenTiles, { x = colX, y = rowY })
                ClearWorld.totalCleared = ClearWorld.totalCleared + 1
                task.wait(0.015)
            end

            -- 2. Background (BG) jika clearBG aktif (hanya jika FG bukan Bedrock/Protected)
            if ClearWorld.clearBG and isTileBreakable("bg", colX, rowY) then
                local bg = getRealtimeTile("bg", colX, rowY)
                if lblClearStatus and bg and bg ~= 0 then
                    local it = ItemDB and ItemDB[bg]
                    local name = it and it.name or ("ID " .. bg)
                    lblClearStatus.Text = string.format("⛏️ [BG] %s di (%d, %d)...", name, colX, rowY)
                end
                if bg and isSafeNaturalJunk(bg) then
                    brokenJunkIds[bg] = true
                    if isSafeNaturalJunk(bg + 1) then
                        brokenJunkIds[bg + 1] = true
                    end
                end
                breakTileRealtime("bg", colX, rowY, worldW, worldH)
                table.insert(brokenTiles, { x = colX, y = rowY })
                ClearWorld.totalCleared = ClearWorld.totalCleared + 1
                task.wait(0.015)
            end
        end
    end

    -- Sweep drops on the broken column & ONLY trash the newly collected delta of natural junk
    if ClearWorld.autoSweep and #brokenTiles > 0 then
        local px, py, rawX, rawY = getPlayerTilePos()

        -- Ambil snapshot jumlah stock item junk SEBELUM di-sweep
        local countsBefore = {}
        if ClearWorld.autoTrash then
            for jId, _ in pairs(brokenJunkIds) do
                countsBefore[jId] = getRealtimeItemCount(jId)
            end
        end

        collectDropsAtTiles(brokenTiles, px, py, rawX, rawY)

        -- HANYA buang delta (selisih bertambah) dari hasil sapuan kolom ini!
        -- Stok lama dan item lain yang tidak di-break TIDAK PERNAH disentuh!
        if ClearWorld.autoTrash then
            task.wait(0.03)
            for jId, _ in pairs(brokenJunkIds) do
                local countAfter = getRealtimeItemCount(jId)
                local before = countsBefore[jId] or 0
                local delta = countAfter - before
                if delta > 0 then
                    trashSpecificJunkItem(jId, delta)
                end
            end
        end
    end
end

local function clearColumn3Realtime(colX, y1, y2, y3, worldW, worldH)
    clearColumnBandRealtime(colX, { y1, y2, y3 }, worldW, worldH)
end

-- Mencari koordinat tile teratas pertama di world yang masih memiliki blok breakable (FG atau BG)
local function getTopmostBreakableTile(worldW, worldH)
    for y = 0, worldH - 1 do
        for x = 0, worldW - 1 do
            if hasBreakableAtTile(x, y) then
                return x, y
            end
        end
    end
    return nil, nil
end

-- Cek apakah sebuah baris y memiliki setidaknya satu blok breakable
local function rowHasBreakable(rY, worldW, worldH)
    if not rY or rY < 0 or rY >= worldH then return false end
    for x = 0, worldW - 1 do
        if hasBreakableAtTile(x, rY) then
            return true
        end
    end
    return false
end

-- Menentukan baris-baris breakable yang masuk ke dalam band (maksimal 3 baris)
-- dan menentukan ketinggian berjalan (walkY) yang aman (tidak pernah pada baris bedrock!)
local function getBandRowsAndWalkY(topY, worldW, worldH)
    local bandRows = {}
    for offset = 0, 2 do
        local rY = topY + offset
        if rY < worldH and rowHasBreakable(rY, worldW, worldH) then
            table.insert(bandRows, rY)
        end
    end

    if #bandRows == 0 then
        bandRows = { topY }
    end

    local walkY
    if #bandRows == 3 then
        walkY = bandRows[2] -- baris tengah
    elseif #bandRows == 2 then
        walkY = bandRows[2] -- baris bawah dari 2 baris (misal 57, 58 -> walkY = 58)
    else
        walkY = bandRows[1] -- baris tunggal (misal 58 -> walkY = 58, kaki di atas bedrock 59)
    end

    return bandRows, walkY
end

-- Menentukan batas kolom paling kiri (minX) dan paling kanan (maxX) yang memiliki blok pada band
local function getBandBlockBounds(bandRows, worldW, worldH)
    local minX, maxX = nil, nil
    for x = 0, worldW - 1 do
        local hasBlock = false
        for _, rY in ipairs(bandRows) do
            if rY >= 0 and rY < worldH then
                if hasBreakableAtTile(x, rY) then
                    hasBlock = true
                    break
                end
            end
        end
        if hasBlock then
            if not minX then minX = x end
            maxX = x
        end
    end
    return minX, maxX
end

-- Cek realtime apakah kolom colX memiliki blok yang perlu dihancurkan di baris bandRows
local function columnHasBlocks(colX, bandRows, worldH)
    if not colX then return false end
    for _, rY in ipairs(bandRows) do
        if rY >= 0 and rY < worldH then
            if hasBreakableAtTile(colX, rY) then
                return true
            end
        end
    end
    return false
end

stopClearWorld = function()
    ClearWorld.active = false
    ClearWorld.busy = false
    ClearWorld.thread = nil
    if updateClearWorldUI then updateClearWorldUI() end
end

startClearWorld = function()
    if ClearWorld.active then return end
    ClearWorld.active = true
    ClearWorld.busy = false

    if PNB and PNB.active and stopPNB then
        stopPNB()
    end

    if updateClearWorldUI then updateClearWorldUI() end

    ClearWorld.thread = task.spawn(function()
        local w = getNativeWorld()
        if not w then
            stopClearWorld()
            return
        end
        local worldW = w.w or 100
        local worldH = w.h or 60

        -- Cari tile teratas pertama di world yang masih memiliki blok breakable (FG atau BG)
        local initX, initY = getTopmostBreakableTile(worldW, worldH)
        if not initY then
            if lblClearStatus then
                lblClearStatus.Text = "🎉 Selesai! Tidak ada tile yang perlu dibersihkan."
                lblClearStatus.TextColor3 = C.green
            end
            stopClearWorld()
            return
        end

        local currentTopY = initY
        local bandIndex = 0

        while ClearWorld.active do
            local bandRows, walkY = getBandRowsAndWalkY(currentTopY, worldW, worldH)

            -- Cari batas minX dan maxX yang benar-benar ada blok breakable di band ini
            local minX, maxX = getBandBlockBounds(bandRows, worldW, worldH)
            if not minX or not maxX then
                -- Band ini kosong atau hanya berisi bedrock/protected! Cari tile teratas berikutnya
                local nextX, nextY = getTopmostBreakableTile(worldW, worldH)
                if not nextY then
                    if lblClearStatus then
                        lblClearStatus.Text = string.format("🎉 Selesai! World berhasil dibersihkan (%d tile).", ClearWorld.totalCleared)
                        lblClearStatus.TextColor3 = C.green
                    end
                    stopClearWorld()
                    break
                else
                    currentTopY = nextY
                    task.wait(0.02)
                    continue
                end
            end

            -- Smart Sweep Direction: Pilih ujung yang paling dekat dengan posisi player saat ini!
            -- Mencegah bolak-balik menyeberang map (anti ping-pong pathfinding).
            local curPx, curPy = getPlayerTilePos()
            local isLeftToRight
            if curPx then
                local distToMin = math.abs(curPx - minX)
                local distToMax = math.abs(curPx - maxX)
                if distToMin <= distToMax then
                    isLeftToRight = true
                else
                    isLeftToRight = false
                end
            else
                isLeftToRight = (bandIndex % 2 == 0)
            end

            local startX = isLeftToRight and minX or maxX
            local endX   = isLeftToRight and maxX or minX
            local stepDir = isLeftToRight and 1 or -1

            local dirName = isLeftToRight and "Kiri ➔ Kanan" or "Kanan ➔ Kiri"
            local bandDesc = (#bandRows == 1) and string.format("Y: %d (1 Baris)", bandRows[1])
                or string.format("Y: %d-%d (%d Baris)", bandRows[1], bandRows[#bandRows], #bandRows)

            if lblClearStatus then
                lblClearStatus.Text = string.format("⚡ Band %s [%d..%d] (%s) [6-Block Mode]...", bandDesc, minX, maxX, dirName)
            end

            -- 1. PATHFIND LANGSUNG KE TILE AWAL BLOK (Hanya jika belum berada di dekatnya)
            local px, py = getPlayerTilePos()
            if px and py then
                local distToStart = math.abs(px - startX) + math.abs(py - walkY)
                if distToStart > 1 then
                    if lblClearStatus then
                        lblClearStatus.Text = string.format("🚶 Menuju blok awal (%d, %d)...", startX, walkY)
                    end
                    walkOrPathfindTo(startX, walkY, worldW, worldH)
                end
            end
            if not ClearWorld.active then break end

            -- Bersihkan kolom tempat berdiri saat ini jika memuat blok
            if columnHasBlocks(startX, bandRows, worldH) then
                clearColumnBandRealtime(startX, bandRows, worldW, worldH)
            end
            if not ClearWorld.active then break end

            -- =========================================================================
            -- HELPER PRE-BREAK LAVA KHUSUS CLEAR WORLD (PERSIS AUTO BUILD DF)
            -- =========================================================================
            local function checkIsLava(id)
                if not id or id == 0 then return false end
                if id == 4 then return true end
                if isLavaTile and isLavaTile(id) then return true end
                local it = ItemDB and ItemDB[id]
                if it and it.name and string.find(string.lower(it.name), "lava") then
                    return true
                end
                return false
            end

            local function preBreakLavaAtTile(tx, ty)
                if not tx or not ty or tx < 0 or tx >= worldW or ty < 0 or ty >= worldH then return end
                -- 1. Cek Foreground (Lava FG)
                local fg = getRealtimeTile("fg", tx, ty)
                if checkIsLava(fg) then
                    local tries = 0
                    while ClearWorld.active and checkIsLava(getRealtimeTile("fg", tx, ty)) and tries < 4 do
                        tries = tries + 1
                        if lblClearStatus then
                            lblClearStatus.Text = string.format("🔥 [PRE-BREAK LAVA] Hancurkan Lava FG di (%d, %d)...", tx, ty)
                        end
                        breakTileRealtime("fg", tx, ty, worldW, worldH)
                        task.wait(0.025)
                    end
                end
                -- 2. Cek Background (Lava BG)
                local bg = getRealtimeTile("bg", tx, ty)
                if checkIsLava(bg) then
                    local tries = 0
                    while ClearWorld.active and checkIsLava(getRealtimeTile("bg", tx, ty)) and tries < 4 do
                        tries = tries + 1
                        if lblClearStatus then
                            lblClearStatus.Text = string.format("🔥 [PRE-BREAK LAVA] Hancurkan Lava BG di (%d, %d)...", tx, ty)
                        end
                        breakTileRealtime("bg", tx, ty, worldW, worldH)
                        task.wait(0.025)
                    end
                end
            end

            local function preBreakLavaColumn(colX)
                if not colX or colX < 0 or colX >= worldW then return end
                -- Cek seluruh layer vertikal yang bisa disentuh karakter:
                -- Pijakan kaki (walkY+1), Badan (walkY), Lantai jatuh (walkY+2), dan Kepala (walkY-1)
                for _, checkY in ipairs({ walkY + 1, walkY, walkY + 2, walkY - 1 }) do
                    if checkY >= 0 and checkY < worldH then
                        preBreakLavaAtTile(colX, checkY)
                    end
                end
            end

            -- 2. LOOP 6-BLOCK (Band Rows x 2 Kolom per langkah maju)
            local currCol = startX
            while (stepDir > 0 and currCol < endX) or (stepDir < 0 and currCol > endX) do
                if not ClearWorld.active then break end

                local col1 = currCol + stepDir
                local col2 = currCol + (stepDir * 2)

                -- Batasi col2 agar tidak melewati endX atau batas world
                if (stepDir > 0 and col2 > endX) or (stepDir < 0 and col2 < endX) or col2 < 0 or col2 >= worldW then
                    col2 = nil
                end

                -- PRE-BREAK LAVA SEJAK DINI: Cek pijakan currCol dan col1 sebelum ambil keputusan
                preBreakLavaColumn(currCol)
                if col1 and col1 >= 0 and col1 < worldW then
                    preBreakLavaColumn(col1)
                end

                -- DETEKSI REALTIME: Cek apakah col1 dan col2 memiliki blok
                local hasCol1 = columnHasBlocks(col1, bandRows, worldH)
                local hasCol2 = col2 and columnHasBlocks(col2, bandRows, worldH)

                if not hasCol1 and not hasCol2 then
                    -- Cari kolom terdekat berikutnya yang benar-benar memuat blok
                    local nextBlockCol = nil
                    local probe = (col2 or col1) + stepDir
                    while (stepDir > 0 and probe <= endX) or (stepDir < 0 and probe >= endX) do
                        if columnHasBlocks(probe, bandRows, worldH) then
                            nextBlockCol = probe
                            break
                        end
                        probe = probe + stepDir
                    end

                    if not nextBlockCol then
                        break
                    else
                        -- Sebelum melangkah lewat celah kosong, bersihkan lava di sepanjang jalur jalan!
                        local scanCol = currCol + stepDir
                        while (stepDir > 0 and scanCol <= nextBlockCol) or (stepDir < 0 and scanCol >= nextBlockCol) do
                            preBreakLavaColumn(scanCol)
                            scanCol = scanCol + stepDir
                        end

                        local standCol = nextBlockCol - stepDir
                        if currCol ~= standCol then
                            if lblClearStatus then
                                lblClearStatus.Text = string.format("⏩ Lewati celah kosong ➔ Maju ke X: %d...", standCol)
                            end
                            walkOrPathfindTo(standCol, walkY, worldW, worldH)
                            currCol = standCol
                        else
                            currCol = col1
                        end
                    end
                else
                    -- Cek apakah col1 terhalang blok solid terproteksi (Door/Bedrock/Lock)
                    local col1Blocked = false
                    for _, rY in ipairs(bandRows) do
                        local fg = getRealtimeTile("fg", col1, rY)
                        if fg and (isProtectedTile(fg) or isBedrockTile(fg)) and isSolidTile(col1, rY) then
                            col1Blocked = true
                            break
                        end
                    end

                    if col1Blocked then
                        local bypassCol = col1 + stepDir
                        if (stepDir > 0 and bypassCol <= endX) or (stepDir < 0 and bypassCol >= endX) then
                            preBreakLavaColumn(bypassCol)
                            if lblClearStatus then
                                lblClearStatus.Text = string.format("🔄 Bypass rintangan di X: %d...", col1)
                            end
                            walkOrPathfindTo(bypassCol, walkY, worldW, worldH)
                            currCol = bypassCol
                        else
                            break
                        end
                    else
                        -- A. HANCURKAN BATCH BLOK
                        if lblClearStatus then
                            local batchDesc = col2 and string.format("X: %d-%d (6 Blok)", col1, col2) or string.format("X: %d (3 Blok)", col1)
                            lblClearStatus.Text = string.format("⛏️ Menghancurkan batch %s...", batchDesc)
                        end

                        -- 1. Hancurkan col1 dulu
                        if hasCol1 then
                            clearColumnBandRealtime(col1, bandRows, worldW, worldH)
                        end

                        if not ClearWorld.active then break end

                        local retryCount = 0
                        while ClearWorld.active and columnHasBlocks(col1, bandRows, worldH) and retryCount < 2 do
                            retryCount = retryCount + 1
                            task.wait(0.04)
                            clearColumnBandRealtime(col1, bandRows, worldW, worldH)
                        end

                        if not ClearWorld.active then break end

                        -- Pastikan lava di col1 sudah 100% musnah sebelum melangkah ke col1
                        preBreakLavaColumn(col1)

                        -- Maju ke col1 jika ada col2
                        local col2Clean = true
                        if col2 then
                            if not isSolidTile(col1, walkY) then
                                stepToColumn(col1, walkY)
                                currCol = col1
                            else
                                ensureTileInRange(col2, walkY, worldW, worldH)
                            end

                            -- Sekarang karakter sudah di col1 (jarak ke col2 aman <= 1.41 tile), hancurkan lava col2!
                            preBreakLavaColumn(col2)

                            if hasCol2 then
                                clearColumnBandRealtime(col2, bandRows, worldW, worldH)
                            end

                            local retry2 = 0
                            while ClearWorld.active and columnHasBlocks(col2, bandRows, worldH) and retry2 < 2 do
                                retry2 = retry2 + 1
                                task.wait(0.04)
                                clearColumnBandRealtime(col2, bandRows, worldW, worldH)
                            end

                            if columnHasBlocks(col2, bandRows, worldH) then
                                col2Clean = false
                            end
                        end

                        if not ClearWorld.active then break end

                        -- Pastikan lava di col2 sudah 100% bersih sebelum melangkah ke col2
                        if col2 then
                            preBreakLavaColumn(col2)
                        end

                        -- B. GESER MAJU (Advance):
                        if col2 and col2Clean and not isSolidTile(col2, walkY) then
                            if lblClearStatus then
                                lblClearStatus.Text = string.format("🚶 Maju ke X: %d (%s)", col2, bandDesc)
                            end
                            stepToColumn(col2, walkY)
                            currCol = col2
                        elseif not isSolidTile(col1, walkY) then
                            stepToColumn(col1, walkY)
                            currCol = col1
                        else
                            currCol = col2 or col1
                        end

                        if updateClearWorldUI then
                            updateClearWorldUI()
                        end
                    end
                end

                task.wait(0.015)
            end

            -- Lanjut ke band berikutnya
            bandIndex = bandIndex + 1
            local nextX, nextY = getTopmostBreakableTile(worldW, worldH)
            if not nextY then
                if lblClearStatus then
                    lblClearStatus.Text = string.format("🎉 Selesai! World berhasil dibersihkan (%d tile).", ClearWorld.totalCleared)
                    lblClearStatus.TextColor3 = C.green
                end
                stopClearWorld()
                break
            else
                currentTopY = nextY
            end

            task.wait(0.04)
        end
    end)
end

-- ═══════════════════════════════════════
--  AUTO BUILD DIRT FARM (DF) ENGINE
-- ═══════════════════════════════════════
AutoBuildDF = {
    active        = false,
    busy          = false,
    isRestocking  = false,
    thread        = nil,
    getStateFile  = function()
        return getAccountFileName and getAccountFileName("sysgt_df_state", "json") or "sysgt_df_state.json"
    end,
    mainBlockId   = 2,            -- Default: Dirt (ID 2)
    mainBlockName = "Dirt",
    platBlockId   = 102,          -- Default: Wooden Platform (ID 102)
    platBlockName = "Wooden Platform",
    platWidth     = 1,            -- Default: 1 tile platform pada pinggiran kiri & kanan
    bottomY       = 53,           -- Default: Min Y = 53 (Lantai terbawah)
    topY          = 2,            -- Default: Max Y = 2 (Lantai teratas)
    stepY         = 2,            -- Jarak per lantai (2 tile)
    minX          = 1,            -- Internal index 1 -> Tampil di game & char pos sebagai X=2
    maxX          = 98,           -- Internal index 98 -> Tampil di game & char pos sebagai X=99
    buildDelay    = 0.06,         -- Delay pemasangan blok
    totalPlaced   = 0,
    currentY      = 37,
    autoRestock   = true,         -- Default TRUE: Auto restock bahan dari storage world saat habis
    storageWorld  = "",           -- Nama storage world (contoh: DFSTORE)
    storageDoor   = "",           -- Door ID / nama door di storage world (opsional)
    _manualGathering = false,
    _plantedSeeds = {},           -- [tileKey] = timestamp tanam pohon bot
}

local function getDFItemName(id)
    if not id then return "Unknown" end
    local db = ItemDB or (resolveItemDB and resolveItemDB())
    local it = db and db[id]
    if it and it.name then return it.name end
    if fetchInventoryItems then
        for _, invIt in ipairs(fetchInventoryItems()) do
            if invIt.id == id and invIt.name and invIt.name ~= "" and not invIt.name:find("^Item #") then
                return invIt.name
            end
        end
    end
    if id == 2 then return "Dirt" end
    if id == 3 then return "Dirt Seed" end
    if id == 102 then return "Wooden Platform" end
    if id == 103 then return "Wooden Platform Seed" end
    if id == 4 then return "Lava" end
    if id == 5 then return "Lava Seed" end
    if id == 10 then return "Rock" end
    if id == 11 then return "Rock Seed" end
    if id == 12 then return "Wood" end
    if id == 13 then return "Wood Seed" end
    return "Item #" .. tostring(id)
end

isLavaTile = function(id)
    if not id or id == 0 then return false end
    if id == 4 then return true end
    local it = ItemDB and ItemDB[id]
    if it and it.name and string.find(string.lower(it.name), "lava") then
        return true
    end
    return false
end

local DF_STATE_FILE = "sysgt_df_state.json"

-- ═══════════════════════════════════════
--  AUTO-REJOIN (Otomatis Masuk Kembali jika Terlempar ke World List / Lobby)
-- ═══════════════════════════════════════
local AutoRejoin = {
    enabled = true,  -- Toggle via /autojoin command
    lastWorld = "",
    lastDoor = "",
    isRejoining = false,
    pickerOpenCount = 0,
}
_G.AutoRejoin = AutoRejoin

local function nativeJoinWorld(targetWorldName)
    local lp = Players.LocalPlayer
    local mg = lp and lp.PlayerGui:FindFirstChild("MenuGui")
    local wp = mg and mg:FindFirstChild("WorldPicker")
    if not wp then return false end

    targetWorldName = string.upper((string.gsub(tostring(targetWorldName or ""), "%s+", "")))
    if targetWorldName == "" then return false end

    local VIM = pcall(function() return game:GetService("VirtualInputManager") end) and game:GetService("VirtualInputManager") or nil
    local area = wp:FindFirstChild("Area")

    local function clickGuiObject(guiObj)
        if not guiObj then return false end
        -- 1. VirtualInputManager real mouse click (100% native Roblox engine event)
        if VIM and guiObj.AbsoluteSize.X > 5 and guiObj.AbsoluteSize.Y > 5 then
            local pos = guiObj.AbsolutePosition
            local size = guiObj.AbsoluteSize
            local cx = pos.X + size.X / 2
            local cy = pos.Y + size.Y / 2
            pcall(function()
                VIM:SendMouseButtonEvent(cx, cy, 0, true, game, 1)
                task.wait(0.04)
                VIM:SendMouseButtonEvent(cx, cy, 0, false, game, 1)
            end)
        end
        -- 2. firesignal fallback
        if firesignal then
            if guiObj.Activated then pcall(firesignal, guiObj.Activated) end
            if guiObj.MouseButton1Click then pcall(firesignal, guiObj.MouseButton1Click) end
        end
        return true
    end

    -- METODE 1: Klik tombol world di recent list (Slot #1 di WorldPicker adalah world terakhir pemain!)
    local clickedRecent = false
    if area and area:FindFirstChild("recent") then
        for _, f in ipairs(area.recent:GetChildren()) do
            if f:IsA("Frame") then
                local btn = f:FindFirstChildOfClass("TextButton")
                if btn then
                    clickGuiObject(btn)
                    clickedRecent = true
                    task.wait(0.1)
                    break
                end
            end
        end
    end

    -- METODE 2: Isi TextBox WorldName dan Tekan Enter (ReleaseFocus dengan true)
    local wn = area and area:FindFirstChild("WorldName")
    local tb = wn and wn:FindFirstChildOfClass("TextBox")
    if tb then
        tb.Text = targetWorldName
        task.wait(0.04)
        pcall(function()
            tb:CaptureFocus()
            task.wait(0.04)
            tb:ReleaseFocus(true) -- enterPressed = true!
        end)
    end

    -- METODE 3: Klik Tombol "Enter World" (Button di sisi kanan Area, scaleX == 1)
    if area then
        for _, f in ipairs(area:GetChildren()) do
            if f.Name == "Frame" and f:FindFirstChildOfClass("TextButton") and f.Position.X.Scale == 1 then
                local enterBtn = f:FindFirstChildOfClass("TextButton")
                clickGuiObject(enterBtn)
                task.wait(0.1)
                break
            end
        end
    end

    -- METODE 4: Tombol BACK (Button di sisi kiri Area, scaleX == 0)
    if not clickedRecent and area then
        for _, f in ipairs(area:GetChildren()) do
            if f.Name == "Frame" and f:FindFirstChildOfClass("TextButton") and f.Position.X.Scale == 0 then
                local backBtn = f:FindFirstChildOfClass("TextButton")
                clickGuiObject(backBtn)
                task.wait(0.1)
                break
            end
        end
    end

    -- METODE 5: Native Warp sebagai pelengkap
    if nativeWarp then
        pcall(nativeWarp, targetWorldName)
    end

    return true
end

task.spawn(function()
    while true do
        task.wait(1.0)
        if AutoRejoin.enabled then
            local pickerOpen = isWorldPickerOpen and isWorldPickerOpen()
            local w = not pickerOpen and getNativeWorld and getNativeWorld() or nil
            local currentWorldName = (w and w.name) or ""

            if not pickerOpen and currentWorldName ~= "" and currentWorldName ~= "LOBBY" and currentWorldName ~= "World" then
                -- Player sedang aktif di dalam world
                AutoRejoin.lastWorld = currentWorldName
                if Proxy then Proxy.lastWorldName = currentWorldName end
                AutoRejoin.pickerOpenCount = 0
            else
                -- Player terlempar ke World List / Lobby (MenuGui.WorldPicker terbuka atau world kosong)
                if AutoRejoin.lastWorld ~= "" and not AutoRejoin.isRejoining then
                    AutoRejoin.pickerOpenCount = AutoRejoin.pickerOpenCount + 1
                    -- Tunggu 2 tick (~2 detik) agar transisi menu game stabil
                    if AutoRejoin.pickerOpenCount >= 2 then
                        AutoRejoin.isRejoining = true
                        print(string.format("[AUTO-REJOIN] Terdeteksi di World List / Lobby! Menghubungkan kembali ke: %s (Metode Native)...", AutoRejoin.lastWorld))
                        if Proxy and Proxy.notify then
                            Proxy.notify(string.format("`e[Auto-Rejoin] Terlempar ke World List! Menghubungkan ke world: %s...``", AutoRejoin.lastWorld))
                        end
                        if lblStatus and lblStatus.set then
                            lblStatus:set(string.format("`e[Auto-Rejoin] Masuk kembali ke: %s...``", AutoRejoin.lastWorld))
                        end

                        task.wait(1.0)
                        nativeJoinWorld(AutoRejoin.lastWorld)

                        -- Tunggu world baru ter-load penuh, lalu jalankan resume bersih dari Main Door!
                        task.spawn(function()
                            local ok = waitForWorldFullyLoaded(AutoRejoin.lastWorld, 30)
                            if ok then
                                print(string.format("[AUTO-REJOIN] Tiba di world [%s]! Mengulang proses pekerjaan dari Main Door...", AutoRejoin.lastWorld))
                                task.wait(0.6)
                                if checkResumeDFState then checkResumeDFState() end
                                if AutoRotation.checkResume then AutoRotation.checkResume() end
                                if AutoEvent and AutoEvent.checkResume then AutoEvent.checkResume() end
                                if FarmLogistics and FarmLogistics.checkResume then FarmLogistics.checkResume() end
                            end
                            AutoRejoin.isRejoining = false
                            AutoRejoin.pickerOpenCount = 0
                        end)
                    end
                end
            end
        end
    end
end)

-- Helper Universal Native Warp: Mengirimkan perintah /warp <world> resmi bawaan engine game
nativeWarp = function(targetWorld)
    _G.nativeWarp = nativeWarp
    if not targetWorld or targetWorld == "" then return false end
    targetWorld = string.upper((string.gsub(tostring(targetWorld), "%s+", "")))

    local sent = false

    -- 1. Metode Chat Controller Utama: tbl._origOnCommand / tbl.onCommand
    pcall(function()
        local chatTbl = (Proxy and Proxy.chatTableRef)
        if not chatTbl then
            local lp = Players.LocalPlayer
            local pg = lp and lp:FindFirstChild("PlayerGui")
            local chatGui = pg and pg:FindFirstChild("ChatGui")
            local input = chatGui and chatGui:FindFirstChildWhichIsA("TextBox", true)
            if input then
                local conns = getconnections(input.FocusLost)
                for _, conn in ipairs(conns or {}) do
                    local fn = conn.Function
                    if type(fn) == "function" then
                        local ok, sFn = pcall(debug.getupvalue, fn, 4)
                        if ok and type(sFn) == "function" then
                            local ok2, tbl = pcall(debug.getupvalue, sFn, 1)
                            if ok2 and type(tbl) == "table" and (type(tbl.onCommand) == "function" or type(tbl._origOnCommand) == "function") then
                                chatTbl = tbl
                                if Proxy then Proxy.chatTableRef = tbl end
                                break
                            end
                        end
                    end
                end
            end
        end

        if chatTbl then
            local cmdFn = chatTbl._origOnCommand or chatTbl.onCommand
            if type(cmdFn) == "function" then
                cmdFn("/warp " .. targetWorld)
                sent = true
            end
        end
    end)

    if sent then return true end

    -- 2. Metode sendFn Langsung dari FocusLost
    pcall(function()
        local lp = Players.LocalPlayer
        local pg = lp and lp:FindFirstChild("PlayerGui")
        local chatGui = pg and pg:FindFirstChild("ChatGui")
        local input = chatGui and chatGui:FindFirstChildWhichIsA("TextBox", true)
        if input then
            local conns = getconnections(input.FocusLost)
            for _, conn in ipairs(conns or {}) do
                local fn = conn.Function
                if type(fn) == "function" then
                    local ok, sFn = pcall(debug.getupvalue, fn, 4)
                    if ok and type(sFn) == "function" then
                        sFn("/warp " .. targetWorld)
                        sent = true
                        break
                    end
                end
            end
        end
    end)

    if sent then return true end

    -- 3. Fallback jika berada di WorldPicker / Menu Lobby
    if isWorldPickerOpen and isWorldPickerOpen() then
        return nativeJoinWorld(targetWorld)
    end

    -- 4. Fallback Paksa buka MenuGui.WorldPicker
    pcall(function()
        local lp = Players.LocalPlayer
        local pg = lp and lp:FindFirstChild("PlayerGui")
        local mg = pg and pg:FindFirstChild("MenuGui")
        local wp = mg and mg:FindFirstChild("WorldPicker")
        if wp then
            wp.Visible = true
            task.wait(0.08)
            nativeJoinWorld(targetWorld)
            sent = true
        end
    end)

    return sent
end

-- Fungsi Universal Warp: Menggunakan Native /warp Game & Cross-Server QueueOnTeleport
warpToWorld = function(targetWorld, doorId)
    _G.warpToWorld = warpToWorld
    if not targetWorld or targetWorld == "" then return false end
    targetWorld = string.upper((string.gsub(tostring(targetWorld), "%s+", "")))
    local passDoor = (doorId and doorId ~= "") and doorId or nil

    print(string.format("[WARP] Berpindah ke world [%s] via Native /warp (Door: %s)...", targetWorld, tostring(passDoor)))

    -- Invalidate stale world cache before warping
    cachedNativeWorld = nil
    lastWorldCheck = 0

    -- 1. Siapkan Queue on Teleport jika berpindah server instance
    safeQueueOnTeleport()

    -- 2. Jika saat ini berada di WorldPicker (World List / Lobby), gunakan NATIVE JOIN GUI!
    if isWorldPickerOpen and isWorldPickerOpen() then
        nativeJoinWorld(targetWorld)
    else
        -- 3. Eksekusi NATIVE GAME COMMAND: /warp <targetWorld>
        nativeWarp(targetWorld)
    end

    -- 4. Watcher lokal jika berpindah world pada server instance yang sama
    task.spawn(function()
        task.wait(0.8) -- Beri waktu request enter world diproses server
        local loaded = waitForWorldFullyLoaded(targetWorld, 25)
        if loaded then
            print(string.format("[WARP] Tiba di world [%s] (Same Server)! Memulai ulang task dari Main Door...", targetWorld))
            task.wait(0.5)
            if checkResumeDFState then
                checkResumeDFState()
            end
            if AutoRotation.checkResume then
                AutoRotation.checkResume()
            end
            if AutoEvent and AutoEvent.checkResume then
                AutoEvent.checkResume()
            end
            if FarmLogistics and FarmLogistics.checkResume then
                FarmLogistics.checkResume()
            end
        end
    end)

    return true
end



local function getSeedIdForBlock(blockId)
    if not blockId or blockId <= 0 then return nil end

    -- Jika blockId yang diinput ternyata sudah merupakan bibit (ganjil / kind seed)
    if blockId % 2 == 1 and blockId > 1 then
        return blockId
    end

    local db = ItemDB or (resolveItemDB and resolveItemDB())
    if db then
        local blockItem = db[blockId]
        local blockName = blockItem and blockItem.name and string.lower(blockItem.name) or ""

        if blockItem and (blockItem.kind == "seed" or blockItem.grow or blockItem.tree) then
            return blockId
        end

        -- 1. Cek direct successor (blockId + 1)
        local succ = db[blockId + 1]
        if succ then
            if succ.kind == "seed" or succ.grow or succ.tree or succ.block == blockId then
                return blockId + 1
            end
            if blockName ~= "" and succ.name and string.find(string.lower(succ.name), blockName, 1, true) then
                return blockId + 1
            end
        end

        -- 2. Scan db by block reference / seed name
        for id, it in pairs(db) do
            if type(it) == "table" and (it.kind == "seed" or it.grow or it.tree) then
                if (it.tree and it.tree.leaves == blockId) or (it.seed and it.seed.over == blockId) or (it.block == blockId) then
                    return id
                end
                if blockName ~= "" and it.name and string.lower(it.name) == blockName .. " seed" then
                    return id
                end
            end
        end
    end

    -- 3. Cek inventory tas langsung: apakah ada item bibit yang ID == blockId + 1 atau nama cocok
    if fetchInventoryItems then
        local invItems = fetchInventoryItems()
        for _, it in ipairs(invItems) do
            if it.id == (blockId + 1) and (it.count or 0) > 0 then
                return blockId + 1
            end
        end
        for _, it in ipairs(invItems) do
            if (it.count or 0) > 0 then
                local sName = (it.name or ""):lower()
                local bName = getDFItemName(blockId):lower():gsub(" block", ""):gsub(" item #%d+", "")
                if bName ~= "" and string.find(sName, bName, 1, true) and (string.find(sName, "seed", 1, true) or it.kind == "seed") then
                    return it.id
                end
            end
        end
    end

    -- 4. Guaranteed native Growblox convention fallback: bibit SELALU blockId + 1!
    return blockId + 1
end

collectDFMaterials = function(targetItemId, maxTarget, purePickupOnly)
    if not targetItemId or targetItemId <= 0 then return false, 0 end
    maxTarget = maxTarget or 180
    local isPure = purePickupOnly or (AutoBuildDF._storageGathering == true)
    local curCount = getRealtimeItemCount(targetItemId)
    if curCount >= maxTarget then
        return true, curCount
    end

    local w = getNativeWorld()
    local worldW = (w and w.w) or (w and w.worldSize and w.worldSize.x) or 100
    local worldH = (w and w.h) or (w and w.worldSize and w.worldSize.y) or 60
    local inv = getNativeInventory()

    -- Bibit MURNI otomatis dari target blok yang sedang dicari!
    -- Tidak boleh nyasar ke bibit lain di tas!
    local seedId = getSeedIdForBlock(targetItemId)
    if not seedId and ItemDB and ItemDB[targetItemId] and ItemDB[targetItemId].kind == "seed" then
        seedId = targetItemId
    end
    local itemName = getDFItemName(targetItemId)
    local seedName = (seedId and getDFItemName(seedId)) or "Seed" 

    if lblDFStatus and lblDFStatus.set then
        lblDFStatus:set(string.format("`c[GATHER] Mencari drop & bahan %s (ID %d) di world...``", itemName, targetItemId))
    end

    -- Simpan posisi awal sebelum gather bahan agar bot bisa kembali ke posisi kerja baris
    local startGatherPx, startGatherPy = getPlayerTilePos()

    -- Helper: Sapu bersih droppan bahan per baris ujung ke ujung (Row-by-Row Sweep)
    local function sweepTargetDropsRowByRow(tItemId, maxCount)
        local curDList = (w and w.dropList and w.dropList()) or {}
        local rowMap = {}
        local rowList = {}
        for _, d in ipairs(curDList) do
            if d and d.uid and d.id == tItemId and not d.taking then
                local dtx = math.floor(d.x or 0)
                local dty = math.floor(d.y or 0)
                if not isSolidTile(dtx, dty) then
                    if not rowMap[dty] then
                        rowMap[dty] = { minX = dtx, maxX = dtx, drops = {} }
                        table.insert(rowList, dty)
                    else
                        if dtx < rowMap[dty].minX then rowMap[dty].minX = dtx end
                        if dtx > rowMap[dty].maxX then rowMap[dty].maxX = dtx end
                    end
                    table.insert(rowMap[dty].drops, d)
                end
            end
        end

        if #rowList == 0 then return end

        -- Urutkan baris dari atas ke bawah (Y ascending: 0 -> worldH)
        table.sort(rowList, function(a, b) return a < b end)

        for _, rY in ipairs(rowList) do
            if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
            if getRealtimeItemCount(tItemId) >= maxCount then break end

            local rData = rowMap[rY]
            if rData and #rData.drops > 0 then
                local curPx, curPy = getPlayerTilePos()
                curPx = curPx or rData.minX
                curPy = curPy or rY

                local startX, endX, stepX
                if math.abs(curPx - rData.minX) <= math.abs(curPx - rData.maxX) then
                    startX, endX, stepX = rData.minX, rData.maxX, 1
                else
                    startX, endX, stepX = rData.maxX, rData.minX, -1
                end

                local reached = walkOrPathfindTo(startX, rY, worldW, worldH)
                if not reached then
                    approachTile(startX, rY, worldW, worldH)
                end
                task.wait(0.02)

                local cX = startX
                while (stepX > 0 and cX <= endX) or (stepX < 0 and cX >= endX) do
                    if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
                    if getRealtimeItemCount(tItemId) >= maxCount then break end

                    for _, d in ipairs(rData.drops) do
                        if d and d.uid and not d.taking and d.id == tItemId then
                            local ddx = (d.x or cX) - cX
                            local ddy = (d.y or rY) - rY
                            if math.sqrt(ddx * ddx + ddy * ddy) <= 1.5 then
                                tryPickupDrop(d, inv)
                            end
                        end
                    end

                    local nextX = cX + stepX
                    if not isSolidTile(nextX, rY) then
                        stepToColumn(nextX, rY)
                        cX = nextX
                    else
                        break
                    end
                end
                task.wait(0.02)
            end
        end
    end

    -- ─────────────────────────────────────────────────────────────
    -- 1. SWEEP DROPPED BLOCKS DI WORLD (targetItemId) - ROW BY ROW
    -- ─────────────────────────────────────────────────────────────
    sweepTargetDropsRowByRow(targetItemId, maxTarget)

    curCount = getRealtimeItemCount(targetItemId)
    if curCount >= maxTarget then
        return true, curCount
    end

    -- ─────────────────────────────────────────────────────────────
    -- 2. DETEKSI & AMBIL SEED JIKA ADA (DROP DI WORLD)
    -- ─────────────────────────────────────────────────────────────
    if seedId then
        local seedName = (ItemDB and ItemDB[seedId] and ItemDB[seedId].name) or ("Seed #" .. tostring(seedId))

        -- 2a. Ambil Seed yang tergeletak/drop di world (Maks 180 per stack di tas)
        local curSeedStock = getRealtimeItemCount(seedId)
        if curSeedStock < 180 then
            drops = (w and w.dropList and w.dropList()) or {}
            local seedDrops = {}
            for _, d in ipairs(drops) do
                if d and d.uid and d.id == seedId and not d.taking then
                    local dtx = math.floor(d.x or 0)
                    local dty = math.floor(d.y or 0)
                    if not isSolidTile(dtx, dty) then
                        table.insert(seedDrops, d)
                    end
                end
            end

            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`c[GATHER-SEED] Sapu bersih baris bibit %s...``", seedName))
            end
            sweepTargetDropsRowByRow(seedId, 180)
        end

        -- JIKA PURE PICKUP MODE (Storage World):
        -- BERHENTI DI SINI! World bahan HANYA untuk ambil droppan, TIDAK BOLEH menanam bibit!
        -- Bawa bibit ke DF World, tanam di DF World saja!
        if isPure then
            curCount = getRealtimeItemCount(targetItemId)
            return (curCount >= maxTarget), curCount
        end

        -- Helper: Panen pohon matang dengan pola Serpentine Zigzag (persis Auto Harvest Tab Farm)
        -- Baris atas ke bawah, baris ganjil kiri->kanan, baris genap kanan->kiri
        local function harvestTreesZigzag()
            if not scanWorldTrees then return end
            local allTrees = scanWorldTrees()
            local ripeTrees = {}
            for _, t in ipairs(allTrees) do
                -- Pohon yang dipanen HANYA pohon yang menghasilkan targetItemId atau bibitnya!
                local isMatch = (t.seedId == seedId or t.fruitId == targetItemId)

                if isMatch then
                    local isRipe = t.isRipe
                    local numKey = t.y * worldW + t.x
                    if not isRipe and AutoBuildDF._plantedSeeds and AutoBuildDF._plantedSeeds[numKey] then
                        local growTime = (ItemDB and ItemDB[t.seedId] and ItemDB[t.seedId].grow) or 20
                        if (os.clock() - AutoBuildDF._plantedSeeds[numKey]) >= growTime then
                            isRipe = true
                        end
                    end
                    if isRipe then
                        table.insert(ripeTrees, t)
                    end
                end
            end

            if #ripeTrees == 0 then return end

            -- Kelompokkan pohon ripe per baris Y
            local rowMap = {}
            local rowList = {}
            for _, t in ipairs(ripeTrees) do
                if not rowMap[t.y] then
                    rowMap[t.y] = {}
                    table.insert(rowList, t.y)
                end
                table.insert(rowMap[t.y], t)
            end

            -- Urutkan baris dari paling atas ke bawah (Top to Bottom: Y ascending)
            table.sort(rowList, function(a, b) return a < b end)

            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`e[HARVEST-DF] Panen %d pohon %s zigzag (Atas -> Bawah)...``", #ripeTrees, seedName))
            end

            -- Panen baris demi baris secara serpentine zigzag (Kiri->Kanan, Kanan->Kiri)
            for rowIndex, rY in ipairs(rowList) do
                if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
                if getRealtimeItemCount(targetItemId) >= maxTarget then break end

                local isLeftToRight = (rowIndex % 2 == 1)
                local rowTrees = rowMap[rY]
                table.sort(rowTrees, function(a, b)
                    if isLeftToRight then
                        return a.x < b.x
                    else
                        return a.x > b.x
                    end
                end)

                for _, t in ipairs(rowTrees) do
                    if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
                    if getRealtimeItemCount(targetItemId) >= maxTarget then break end

                    local curFg = getRealtimeTile("fg", t.x, t.y)
                    if curFg ~= 0 then
                        local reached = approachTile(t.x, t.y, worldW, worldH)
                        if reached then
                            -- Hadapkan karakter ke arah pohon
                            local curPx, curPy = getPlayerTilePos()
                            if curPx then
                                local facingBit = (t.x >= curPx) and 1 or 0
                                safeSendMove({
                                    x = (curPx + 0.5),
                                    y = (curPy + 1.0),
                                    vx = 0,
                                    vy = 0,
                                    flags = 2 + facingBit
                                })
                            end

                            sendActPacket(ACT_KIND.HIT, t.x, t.y)
                            task.wait(0.08)
                            sendTilePacket("fg", t.x, t.y, 0, false)
                            forceClientTileUpdate("fg", t.x, t.y, 0)
                            if w and w.setTree then pcall(w.setTree, t.x, t.y, nil) end
                            local numKey = t.y * worldW + t.x
                            if AutoBuildDF._plantedSeeds then AutoBuildDF._plantedSeeds[numKey] = nil end

                            -- Ambil droppan lokal di sekitar pohon (radius 2.5 tile)
                            local drops = (w and w.dropList and w.dropList()) or {}
                            for _, d in ipairs(drops) do
                                if d and d.uid and not d.taking and (d.id == targetItemId or d.id == seedId) then
                                    local dx = (d.x or t.x) - t.x
                                    local dy = (d.y or t.y) - t.y
                                    if (dx * dx + dy * dy) <= 6.25 then
                                        tryPickupDrop(d, inv)
                                    end
                                end
                            end

                            task.wait(0.12)
                        end
                    end
                end
            end

            -- Sapu bersih sisa droppan world secara row-by-row sekali di akhir
            sweepTargetDropsRowByRow(targetItemId, maxTarget)
            sweepTargetDropsRowByRow(seedId, 180)
        end

        -- 2b. Cek Pohon yang sudah Ripe di world: Panen & Ambil hasilnya! (Hanya di DF World)
        harvestTreesZigzag()

        curCount = getRealtimeItemCount(targetItemId)
        if curCount >= maxTarget then
            return true, curCount
        end

        -- Helper: Cek & tunggu pohon yang sedang tumbuh di world (Anti-shutdown saat pohon sedang berkembang!)
        local function checkAndHandleGrowingTrees()
            if not scanWorldTrees or isPure or not seedId then return end
            local allTrees = scanWorldTrees()
            local growing = {}
            for _, t in ipairs(allTrees) do
                local isMatch = (t.seedId == seedId or t.fruitId == targetItemId)
                if isMatch and not t.isRipe then
                    table.insert(growing, t)
                end
            end
            if #growing > 0 then
                local growTime = (ItemDB and ItemDB[seedId] and ItemDB[seedId].grow) or 25
                local waitLimit = math.min(growTime + 6, 60)
                local waitStart = os.clock()
                while (os.clock() - waitStart) < waitLimit do
                    if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
                    local elapsed = os.clock() - waitStart
                    local remSec = math.max(0, math.floor(growTime - elapsed))
                    if lblDFStatus and lblDFStatus.set then
                        lblDFStatus:set(string.format("`e[WAIT-GROW] Menunggu %d pohon %s di world matang (%ds tersisa)...``", #growing, seedName, remSec))
                    end
                    task.wait(1.0)
                    local chkTrees = scanWorldTrees()
                    local anyRipe = false
                    for _, ct in ipairs(chkTrees) do
                        if ct.isRipe then
                            anyRipe = true
                            break
                        end
                    end
                    if anyRipe or elapsed >= growTime then
                        break
                    end
                end
                harvestTreesZigzag()
                task.wait(0.1)
            end
        end

        -- 2c. Tanam Bibit dari Backpack jika ada stock bibit & stock blok masih < maxTarget (Hanya di DF World)
        local seedStock = getRealtimeItemCount(seedId)
        if seedStock > 0 and scanPlantableRows then
            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`c[PLANT-SEED] Menanam bibit %s zigzag (Stock: %d)...``", seedName, seedStock))
            end

            local rowList, rowsWithSpots = scanPlantableRows(worldW, worldH)
            local needed = math.clamp(maxTarget - curCount, 1, seedStock)
            local plantedCount = 0

            for rowIndex, rY in ipairs(rowList) do
                if plantedCount >= needed or not AutoBuildDF.active and not AutoBuildDF._manualGathering then break end
                local spotsInRow = rowsWithSpots[rY] or {}
                local isLeftToRight = (rowIndex % 2 == 1)
                table.sort(spotsInRow, function(a, b)
                    if isLeftToRight then
                        return a.x < b.x
                    else
                        return a.x > b.x
                    end
                end)

                for _, spot in ipairs(spotsInRow) do
                    if plantedCount >= needed or not AutoBuildDF.active and not AutoBuildDF._manualGathering then break end
                    if getRealtimeItemCount(seedId) <= 0 then break end

                    local curTile = getRealtimeTile("fg", spot.x, spot.y)
                    if curTile == 0 then
                        local reached = approachTile(spot.x, spot.y, worldW, worldH)
                        if reached and getRealtimeTile("fg", spot.x, spot.y) == 0 then
                            sendActPacket(ACT_KIND.PLANT, spot.x, spot.y)
                            sendTilePacket("fg", spot.x, spot.y, seedId, false)
                            forceClientTileUpdate("fg", spot.x, spot.y, seedId)
                            if AutoBuildDF._plantedSeeds then
                                AutoBuildDF._plantedSeeds[spot.y * worldW + spot.x] = os.clock()
                            end
                            local inv_local = getNativeInventory and getNativeInventory()
                            if inv_local and inv_local.remove then
                                pcall(inv_local.remove, inv_local, seedId, 1)
                            end
                            if refreshInventory then task.spawn(refreshInventory) end
                            plantedCount = plantedCount + 1
                            task.wait(0.18) -- Delay tanam aman
                        end
                    end
                end
            end

            -- Tunggu bibit yang baru ditanam sampai matang penuh, lalu panen secara zigzag
            if plantedCount > 0 then
                local growTime = (ItemDB and ItemDB[seedId] and ItemDB[seedId].grow) or 20
                local startWait = os.clock()
                local maxWaitTime = math.min(growTime + 6, 60)
                while (os.clock() - startWait) < maxWaitTime do
                    if not AutoBuildDF.active and not AutoBuildDF.isRestocking and not AutoBuildDF._manualGathering and not AutoBuildDF._storageGathering then break end
                    local elapsed = os.clock() - startWait
                    local sisaWait = math.max(0, math.floor(growTime - elapsed))
                    if lblDFStatus and lblDFStatus.set then
                        lblDFStatus:set(string.format("`e[WAIT-GROW] Menunggu %d bibit %s matang (%ds tersisa)...``", plantedCount, seedName, sisaWait))
                    end
                    task.wait(1.0)
                    if elapsed >= growTime then
                        break
                    end
                end

                -- Panen pohon yang baru matang dengan pola zigzag yang sama persis
                harvestTreesZigzag()
                task.wait(0.1)
            end
        else
            -- Jika tidak ada bibit di tas untuk ditanam, tetapi ada pohon yang sedang tumbuh di world:
            checkAndHandleGrowingTrees()
        end

        -- Cek sekali lagi jika stock masih kosong, barangkali ada pohon yang baru matang
        if getRealtimeItemCount(targetItemId) <= 0 then
            checkAndHandleGrowingTrees()
        end
    end

    -- Navigasikan kembali ke posisi awal kerja secara aman (bebas tabrak blok solid)
    if startGatherPx and startGatherPy then
        local curEndPx, curEndPy = getPlayerTilePos()
        if curEndPx and curEndPy and (math.abs(curEndPx - startGatherPx) > 1 or math.abs(curEndPy - startGatherPy) > 1) then
            walkOrPathfindTo(startGatherPx, startGatherPy, worldW, worldH)
            task.wait(0.04)
        end
    end

    curCount = getRealtimeItemCount(targetItemId)
    return (curCount >= maxTarget), curCount
end

initiateDFRestock = function(targetItemId)
    local w = getNativeWorld()
    local currentWorld = (w and w.name) or (Proxy and Proxy.lastWorldName) or ""
    if currentWorld == "" or not AutoBuildDF.storageWorld or AutoBuildDF.storageWorld == "" then
        if lblDFStatus and lblDFStatus.set then
            lblDFStatus:set("`4[!] Restock gagal: Nama Storage World belum disetting! Masukkan nama world storage di inputbox.``")
        end
        stopAutoBuildDF()
        return false
    end

    -- JANGAN MATIKAN TOGGLE! Tandai isRestocking = true agar tombol tetap merah (aktif)
    AutoBuildDF.active = true
    AutoBuildDF.isRestocking = true
    if AutoBuildDF.thread then
        pcall(task.cancel, AutoBuildDF.thread)
        AutoBuildDF.thread = nil
    end

    local passDoor = (AutoBuildDF.storageDoor and AutoBuildDF.storageDoor ~= "") and AutoBuildDF.storageDoor or nil

    local state = {
        active        = true,
        phase         = "GOTO_STORAGE",
        dfWorld       = currentWorld,
        dfDoor        = nil,
        storageWorld  = AutoBuildDF.storageWorld,
        storageDoor   = passDoor,
        targetItemId  = targetItemId,
        mainBlockId   = AutoBuildDF.mainBlockId,
        platBlockId   = AutoBuildDF.platBlockId,
        platWidth     = AutoBuildDF.platWidth,
        currentY      = AutoBuildDF.currentY,
        totalPlaced   = AutoBuildDF.totalPlaced,
        autoRestock   = true,
    }

    local sFile = AutoBuildDF.getStateFile and AutoBuildDF.getStateFile() or DF_STATE_FILE
    if writefile then
        pcall(writefile, sFile, HttpService:JSONEncode(state))
    end

    if lblDFStatus and lblDFStatus.set then
        lblDFStatus:set(string.format("`c[RESTOCK] Berpindah ke Storage World: %s untuk ambil bahan...``", AutoBuildDF.storageWorld))
    end
    if updateDirtFarmUI then updateDirtFarmUI() end

    -- Setup queue on teleport
    safeQueueOnTeleport()

    task.wait(0.5)
    warpToWorld(AutoBuildDF.storageWorld, passDoor)

    return true
end

checkResumeDFState = function()
    local sFile = AutoBuildDF.getStateFile and AutoBuildDF.getStateFile() or DF_STATE_FILE
    if not isfile or not readfile then return end
    local fileToRead = nil
    if isfile(sFile) then
        fileToRead = sFile
    elseif isfile(DF_STATE_FILE) then
        fileToRead = DF_STATE_FILE
    end
    if not fileToRead then return end
    local ok, raw = pcall(readfile, fileToRead)
    if not ok or not raw or raw == "" then return end
    local ok_dec, state = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok_dec or type(state) ~= "table" or not state.active then return end

    -- Jika masih di WorldPicker / Lobby, tunda resume sampai player benar-benar masuk ke world!
    if isWorldPickerOpen and isWorldPickerOpen() then
        print("[DF-STATE] Menunda resume: Player masih di World List / Lobby.")
        return
    end

    task.spawn(function()
        print("[DF-STATE] Ditemukan task tertunda: Phase " .. tostring(state.phase))
        local targetW = (state.phase == "HARVEST" or state.phase == "PLANT") and state.dfWorld or state.storageWorld

        -- Tunggu world & grid tiles benar-benar ter-load lengkap sebelum bergerak
        local loaded = waitForWorldFullyLoaded(targetW, 30)
        if not loaded then
            print("[DF-STATE] ⚠️ World belum siap atau timeout! Menunda resume.")
            return
        end
        local w = getNativeWorld and getNativeWorld()
        local currentWorld = (w and w.name) or ""

        -- ─────────────────────────────────────────────────────────────
        -- PHASE 1: GOTO_STORAGE (Tiba di Storage World - PURE PICKUP ONLY)
        -- ─────────────────────────────────────────────────────────────
        if state.phase == "GOTO_STORAGE" then
            print(string.format("[DF-RESTOCK] Tiba di Storage World [%s]! Mengambil bahan (Pure Pickup)...", currentWorld))

            local mainId = state.mainBlockId or 2
            local platId = state.platBlockId or 102
            local mainSeedId = getSeedIdForBlock(mainId)
            local platSeedId = getSeedIdForBlock(platId)

            AutoBuildDF.active = true
            AutoBuildDF.isRestocking = true
            AutoBuildDF._storageGathering = true
            if updateDirtFarmUI then updateDirtFarmUI() end

            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`c[RESTOCK] Menyapu drop bahan & bibit di Storage World: %s...``", currentWorld))
            end

            -- 1. Pathfind aktif menyapu droppan blok utama di Storage World sampai 180 (Pure Pickup, NO PLANTING)
            collectDFMaterials(mainId, 180, true)

            -- 2. Pathfind aktif menyapu droppan platform di Storage World sampai 180 
            collectDFMaterials(platId, 180, true)

            -- 3. Sapu juga droppan bibit utama & platform jika ada (maks 180 per stack) untuk dibawa ke DF World
            if mainSeedId and getRealtimeItemCount(mainSeedId) < 180 then
                collectDFMaterials(mainSeedId, 180, true)
            end
            if platSeedId and getRealtimeItemCount(platSeedId) < 180 then
                collectDFMaterials(platSeedId, 180, true)
            end

            -- 4. Sweep sisa droppan terdekat
            sweepDrops(999, "ALL", 30, true)
            AutoBuildDF._storageGathering = false

            task.wait(0.8)
            local finalMain = getRealtimeItemCount(mainId)
            local finalPlat = getRealtimeItemCount(platId)
            local finalMainSeed = (mainSeedId and getRealtimeItemCount(mainSeedId)) or 0
            local finalPlatSeed = (platSeedId and getRealtimeItemCount(platSeedId)) or 0
            local totalMain = finalMain + finalMainSeed

            print(string.format("[DF-RESTOCK] Sweep selesai! Stock: %s=%d, %s=%d, Seed=%d.",
                getDFItemName(mainId), finalMain, getDFItemName(platId), finalPlat, finalMainSeed
            ))

            -- Cek apakah bahan utama (Dirt & Seed) di Storage World dan tas benar-benar habis:
            if totalMain <= 0 then
                local w = getNativeWorld()
                local drops = (w and w.dropList and w.dropList()) or {}
                local hasRemainingMainDrops = false
                for _, d in ipairs(drops) do
                    if d and (d.id == mainId or (mainSeedId and d.id == mainSeedId)) then
                        hasRemainingMainDrops = true
                        break
                    end
                end

                if not hasRemainingMainDrops then
                    print("[DF-RESTOCK] ❌ Bahan utama (Dirt & Seed) KOSONG di Storage World & Tas! Menghentikan Auto DF.")
                    if lblDFStatus and lblDFStatus.set then
                        lblDFStatus:set(string.format("`4[!] Bahan utama %s & bibit habis di Storage World! Auto DF dihentikan.``", getDFItemName(mainId)))
                    end
                    if Proxy and Proxy.notify then
                        Proxy.notify(string.format("`4[Auto DF] Bahan utama %s habis di Storage World! Auto DF berhenti.``", getDFItemName(mainId)))
                    end
                    stopAutoBuildDF()
                    return
                end
            end

            -- Bahan atau bibit berhasil diambil! Kembali ke DF World untuk melanjutkan build / tanam di DF world
            state.phase = "RETURN_DF"
            local sFile = AutoBuildDF.getStateFile and AutoBuildDF.getStateFile() or DF_STATE_FILE
            if writefile then
                pcall(writefile, sFile, HttpService:JSONEncode(state))
            end

            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`2[RESTOCK] Bahan siap (Blok:%d, Seed:%d)! Kembali ke DF World: %s...``", finalMain, finalMainSeed, state.dfWorld))
            end

            task.wait(0.8)
            local returnDoor = (state.dfDoor and state.dfDoor ~= "") and state.dfDoor or nil
            warpToWorld(state.dfWorld, returnDoor)

        -- ─────────────────────────────────────────────────────────────
        -- PHASE 2: RETURN_DF (Kembali ke DF World)
        -- ─────────────────────────────────────────────────────────────
        elseif state.phase == "RETURN_DF" then
            print(string.format("[DF-RESUME] Kembali ke DF World [%s]! Melanjutkan Auto Build DF...", currentWorld))
            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`2[RESUME] Melanjutkan Auto Build DF di baris Y: %s...``", tostring(state.currentY or "--")))
            end

            if state.mainBlockId then AutoBuildDF.mainBlockId = state.mainBlockId end
            if state.platBlockId then AutoBuildDF.platBlockId = state.platBlockId end
            if state.platWidth then AutoBuildDF.platWidth = state.platWidth end
            if state.storageWorld then AutoBuildDF.storageWorld = state.storageWorld end
            if state.storageDoor then AutoBuildDF.storageDoor = state.storageDoor end
            if state.totalPlaced then AutoBuildDF.totalPlaced = state.totalPlaced end
            if state.currentY then AutoBuildDF.currentY = state.currentY end
            AutoBuildDF.autoRestock = true
            AutoBuildDF.isRestocking = false

            local sFile = AutoBuildDF.getStateFile and AutoBuildDF.getStateFile() or DF_STATE_FILE
            if delfile and isfile then
                if isfile(sFile) then pcall(delfile, sFile) end
                if isfile(DF_STATE_FILE) then pcall(delfile, DF_STATE_FILE) end
            elseif writefile then
                pcall(writefile, sFile, "{}")
            end

            if updateDirtFarmUI then updateDirtFarmUI() end

            task.wait(1.0)
            startAutoBuildDF()
        end
    end)
end

-- Helper: Cek apakah sebuah koordinat sudah benar-benar bersih (FG dan BG kosong atau bedrock)
local function isTileClear(tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return true end
    local fg = getRealtimeTile("fg", tx, ty)
    local bg = getRealtimeTile("bg", tx, ty)
    local fgClear = (not fg or fg == 0 or isBedrockTile(fg) or isProtectedTile(fg))
    local bgClear = (not bg or bg == 0 or isBedrockTile(bg) or isProtectedTile(bg))
    return fgClear and bgClear
end

-- Legit Place Tile Helper: 100% Mengikuti setTile Client Resmi Growblox (Bypass Error 267)
placeDFTile = function(layer, tx, ty, itemId)
    if not tx or not ty or tx < 0 or ty < 0 then return false end
    itemId = tonumber(itemId) or 0
    if itemId <= 0 then return false end
    layer = string.lower(tostring(layer or "fg"))
    local layerNum = (layer == "bg") and 2 or 1

    -- Real-time check: jika tile sudah terpasang item yang sama, anggap sukses
    if getRealtimeTile then
        local cur = getRealtimeTile(layer, tx, ty)
        if cur and cur == itemId then
            return true
        end
    end

    -- Hadapkan karakter ke arah tile target (legit player facing)
    if getPlayerTilePos and safeSendMove then
        local px, py, rawX, rawY = getPlayerTilePos()
        if px and rawX and rawY then
            local facingBit = (tx >= px) and 1 or 0
            safeSendMove({
                x = rawX,
                y = rawY,
                vx = 0,
                vy = 0,
                flags = 2 + facingBit
            })
        end
    end

    -- Murni Net.tile.send sesuai client resmi (JANGAN PERNAH panggil Net.act!)
    if Net and Net.tile and Net.tile.send then
        pcall(Net.tile.send, {
            layer = layerNum,
            x = tx,
            y = ty,
            id = itemId,
            flip = false,
        })
    end

    -- Kurangi inventory lokal
    local inv = getNativeInventory and getNativeInventory()
    if inv and inv.remove then
        pcall(inv.remove, inv, itemId, 1)
    end

    -- Update native world grid
    local w = getNativeWorld and getNativeWorld()
    if w then
        local grid = (layerNum == 2) and w.bg or w.fg
        if grid and grid[ty] then
            grid[ty][tx] = itemId
        end
    end

    if forceClientTileUpdate then
        forceClientTileUpdate(layer, tx, ty, itemId)
    end
    return true
end

-- Break tile dengan retry loop validasi ketat anti-lag & anti-packet drop
local function breakDFTile(layer, tx, ty, hitDelay)
    if not tx or not ty or tx < 0 or ty < 0 then return true end
    layer = string.lower(tostring(layer or "fg"))
    local cur = getRealtimeTile(layer, tx, ty)
    if not cur or cur == 0 or isBedrockTile(cur) or isProtectedTile(cur) then
        return true
    end

    local delay = hitDelay or 0.14
    local maxRetries = 4

    for attempt = 1, maxRetries do
        if not AutoBuildDF.active then return false end
        cur = getRealtimeTile(layer, tx, ty)
        if not cur or cur == 0 or isBedrockTile(cur) or isProtectedTile(cur) then
            return true
        end

        local reqHits = getBlockHits(cur)
        if reqHits <= 0 then reqHits = 3 end

        for h = 1, reqHits do
            if not AutoBuildDF.active then return false end
            if h > 1 and getRealtimeTile(layer, tx, ty) == 0 then
                break
            end
            sendActPacket(ACT_KIND.HIT, tx, ty)
            task.wait(delay)
        end

        -- Komit penghancuran & paksa update client visual
        sendTilePacket(layer, tx, ty, 0, false)
        forceClientTileUpdate(layer, tx, ty, 0)

        -- Toleransi latency server: verifikasi bertahap
        local destroyed = false
        for w = 1, 6 do
            task.wait(0.025)
            if getRealtimeTile(layer, tx, ty) == 0 then
                destroyed = true
                break
            end
        end

        if destroyed then
            return true
        end

        -- Jika masih ada sisa karena lag/packet drop, beri hit ekstra & ulangi
        sendActPacket(ACT_KIND.HIT, tx, ty)
        task.wait(0.04)
    end

    sendTilePacket(layer, tx, ty, 0, false)
    forceClientTileUpdate(layer, tx, ty, 0)
    task.wait(0.02)
    return (getRealtimeTile(layer, tx, ty) == 0)
end

-- Helper: Break both FG and BG on a coordinate dengan validasi berkelanjutan
local function clearBothLayersAt(tx, ty)
    if not tx or not ty or tx < 0 or ty < 0 then return true end
    
    -- 1. Validasi & Hancurkan Foreground
    local fg = getRealtimeTile("fg", tx, ty)
    if fg and fg ~= 0 and not isBedrockTile(fg) and not isProtectedTile(fg) then
        local ok = breakDFTile("fg", tx, ty)
        if not ok and AutoBuildDF.active then
            breakDFTile("fg", tx, ty, 0.16)
        end
    end

    -- 2. Validasi & Hancurkan Background
    local bg = getRealtimeTile("bg", tx, ty)
    if bg and bg ~= 0 and not isBedrockTile(bg) and not isProtectedTile(bg) then
        local ok = breakDFTile("bg", tx, ty)
        if not ok and AutoBuildDF.active then
            breakDFTile("bg", tx, ty, 0.16)
        end
    end

    return isTileClear(tx, ty)
end

-- Cek apakah level standY masih perlu digali atau lantai kaki belum selesai (Validasi Ketat Menyeluruh)
local function isStandLevelIncomplete(standY)
    local floorY = standY + 1
    local breakY = standY + 2

    -- 1. Cek tile berdiri standY (harus bersih dari FG & BG)
    for x = AutoBuildDF.minX, AutoBuildDF.maxX do
        if not isTileClear(x, standY) then
            return true
        end
    end

    -- 2. Cek lorong bawah breakY (harus bersih dari FG & BG)
    if breakY <= 53 then
        for x = AutoBuildDF.minX, AutoBuildDF.maxX do
            if not isTileClear(x, breakY) then
                return true
            end
        end
    end

    -- 3. Cek lantai kaki floorY:
    if floorY <= 53 then
        local platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)
        for x = AutoBuildDF.minX, AutoBuildDF.maxX do
            local isEdgePlat = (x <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (x >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)
            local fTile = getRealtimeTile("fg", x, floorY)

            if isEdgePlat then
                if platStock > 0 then
                    -- Jika ada platform di tas: harus terpasang platform di FG
                    if fTile ~= AutoBuildDF.platBlockId and not isBedrockTile(fTile) and not isProtectedTile(fTile) then
                        return true
                    end
                else
                    -- Jika platform KOSONG: tempat plat harus bersih total (0 di FG & BG, atau sudah terpasang plat sebelumnya)
                    if fTile ~= AutoBuildDF.platBlockId and not isTileClear(x, floorY) then
                        return true
                    end
                end
            else
                -- Bagian tengah farm: tidak boleh bolong (0) dan tidak boleh lava
                if not fTile or fTile == 0 or isLavaTile(fTile) then
                    return true
                end
            end
        end
    end

    -- 4. Cek sisi luar kiri (x1 / minX - 1)
    local leftX = AutoBuildDF.minX - 1
    if leftX >= 0 then
        if not isTileClear(leftX, standY) then return true end
        if breakY <= 53 and not isTileClear(leftX, breakY) then return true end
        if floorY <= 53 and not isTileClear(leftX, floorY) then return true end
    end

    -- 5. Cek sisi luar kanan (x100 / maxX + 1)
    local worldW = 100
    local w = getNativeWorld and getNativeWorld()
    if w and w.worldSize then worldW = w.worldSize.x or worldW end
    local rightX = AutoBuildDF.maxX + 1
    if rightX < worldW then
        if not isTileClear(rightX, standY) then return true end
        if breakY <= 53 and not isTileClear(rightX, breakY) then return true end
        if floorY <= 53 and not isTileClear(rightX, floorY) then return true end
    end

    return false
end

-- Cek apakah lantai sky kosong masih ada lubang yang belum terbangun
local function isSkyRowIncomplete(curY)
    local platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)
    for x = AutoBuildDF.minX, AutoBuildDF.maxX do
        local isEdgePlat = (x <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (x >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)
        local fTile = getRealtimeTile("fg", x, curY)
        if isEdgePlat then
            if platStock > 0 and (not fTile or fTile ~= AutoBuildDF.platBlockId) then
                return true
            end
        else
            if not fTile or fTile == 0 then
                return true
            end
        end
    end
    return false
end

stopAutoBuildDF = function()
    AutoBuildDF.active = false
    AutoBuildDF.busy = false
    AutoBuildDF.isRestocking = false
    if AutoBuildDF.thread then
        pcall(task.cancel, AutoBuildDF.thread)
        AutoBuildDF.thread = nil
    end
    local sFile = AutoBuildDF.getStateFile and AutoBuildDF.getStateFile() or DF_STATE_FILE
    if delfile and isfile then
        if isfile(sFile) then pcall(delfile, sFile) end
        if isfile(DF_STATE_FILE) then pcall(delfile, DF_STATE_FILE) end
    end
    if updateDirtFarmUI then updateDirtFarmUI() end
end

startAutoBuildDF = function()
    if AutoBuildDF.active then return end
    if PNB and PNB.active and stopPNB then stopPNB() end
    if ClearWorld and ClearWorld.active and stopClearWorld then stopClearWorld() end
    if AutoPlant and AutoPlant.active and stopAutoPlant then stopAutoPlant() end
    if AutoHarvest and AutoHarvest.active and stopAutoHarvest then stopAutoHarvest() end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end

    -- Sinkronkan setting storage world & door langsung dari textbox jika ada
    if inpStorageWorld and inpStorageWorld.Text ~= "" then
        AutoBuildDF.storageWorld = string.upper((string.gsub(inpStorageWorld.Text or "", "%s+", "")))
    end
    if inpStorageDoor then
        AutoBuildDF.storageDoor = string.gsub(inpStorageDoor.Text or "", "%s+", "")
    end
    if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end

    AutoBuildDF.active = true
    AutoBuildDF.busy = false
    if updateDirtFarmUI then updateDirtFarmUI() end

    AutoBuildDF.thread = task.spawn(function()
        local worldW = 100
        local worldH = 60
        local w = getNativeWorld()
        if w and w.worldSize then
            worldW = w.worldSize.x or worldW
            worldH = w.worldSize.y or worldH
        end

        ensureMobilityHooks()

        -- Periksa ketersediaan bahan awal:
        -- HANYA jika tas benar-benar 0 (kosong), cari drop/panen di local DF world terlebih dahulu
        local initMain = getRealtimeItemCount(AutoBuildDF.mainBlockId)
        if initMain <= 0 then
            local mainSeedId = getSeedIdForBlock(AutoBuildDF.mainBlockId)
            local seedStock = (mainSeedId and getRealtimeItemCount(mainSeedId)) or 0
            if lblDFStatus and lblDFStatus.set then
                if seedStock > 0 then
                    lblDFStatus:set(string.format("`c[GATHER] Tas kosong tapi ada %d bibit %s di BP! Menanam & memanen...``", seedStock, getDFItemName(mainSeedId)))
                else
                    lblDFStatus:set(string.format("`c[GATHER] Mengumpulkan bahan awal %s di world...``", AutoBuildDF.mainBlockName))
                end
            end
            collectDFMaterials(AutoBuildDF.mainBlockId, 180, false)
            initMain = getRealtimeItemCount(AutoBuildDF.mainBlockId)
        end

        -- Jika tas masih kosong setelah dicari di local DF world:
        if initMain <= 0 then
            local mainSeedId = getSeedIdForBlock(AutoBuildDF.mainBlockId)
            local hasTreesOrSeeds = false
            if mainSeedId then
                if getRealtimeItemCount(mainSeedId) > 0 then
                    hasTreesOrSeeds = true
                elseif scanWorldTrees then
                    for _, t in ipairs(scanWorldTrees()) do
                        if t.seedId == mainSeedId or t.fruitId == AutoBuildDF.mainBlockId then
                            hasTreesOrSeeds = true
                            break
                        end
                    end
                end
            end

            if hasTreesOrSeeds then
                collectDFMaterials(AutoBuildDF.mainBlockId, 180, false)
                initMain = getRealtimeItemCount(AutoBuildDF.mainBlockId)
            end
        end

        if initMain <= 0 then
            if (AutoBuildDF.autoRestock or AutoBuildDF.storageWorld ~= "") and AutoBuildDF.storageWorld ~= "" then
                initiateDFRestock(AutoBuildDF.mainBlockId)
                return
            end
            if lblDFStatus and lblDFStatus.set then
                lblDFStatus:set(string.format("`4[!] Tidak ada stock %s (ID %d) di tas atau pohon di world! Masukkan Storage World untuk auto-restock!``", AutoBuildDF.mainBlockName, AutoBuildDF.mainBlockId))
            end
            stopAutoBuildDF()
            return
        end

        -- ═════════════════════════════════════════════════════════════
        -- TAHAP 1: BENTUK TANAH UNDERGROUND DARI ATAS KE BAWAH (Y=37 -> Y=53)
        -- Karakter berjalan di udara terbuka (standY = 36, 38, 40, ..., 52)
        -- Lantai kaki: standY + 1 (dipertahankan tanah aslinya, lava diganti, platform pinggir)
        -- Target break: standY + 2 (skip 1 tile lantai kaki, lalu break FG & BG lorong bawah!)
        -- Validasi Ketat: Cek realtime berulang kali (while not isTileClear) agar tidak ada blok tertinggal saat lag!
        -- Auto Detect Alur: Langsung mendeteksi kolom yang belum selesai dan melanjutkan alur buka jalan secara mulus!
        local standLevels = {}
        local sY = 36
        while sY <= 52 do
            table.insert(standLevels, sY)
            sY = sY + 2
        end

        local startLvlIdx = nil
        for idx, lvlY in ipairs(standLevels) do
            if isStandLevelIncomplete(lvlY) then
                startLvlIdx = idx
                break
            end
        end

        if startLvlIdx then
            local lvlIdx = startLvlIdx
            while AutoBuildDF.active and lvlIdx <= #standLevels do
                local standY = standLevels[lvlIdx]
                local floorY = standY + 1
                local breakY = standY + 2
                AutoBuildDF.currentY = floorY + 1 -- Simpan koordinat 1-based (sesuai pos game)

                local isEvenSeq = (lvlIdx % 2 == 1)
                local startX  = isEvenSeq and AutoBuildDF.minX or AutoBuildDF.maxX
                local endX    = isEvenSeq and AutoBuildDF.maxX or AutoBuildDF.minX
                local stepDir = isEvenSeq and 1 or -1

                -- Cek apakah level ini sudah beres seluruhnya
                if not isStandLevelIncomplete(standY) then
                    lvlIdx = lvlIdx + 1
                    continue
                end

                -- =====================================================================
                -- AUTO DETECT ALUR: Cari kolom pertama yang belum selesai di baris ini
                -- =====================================================================
                local resumeCol = startX
                local scanCol = startX
                while (stepDir > 0 and scanCol <= endX) or (stepDir < 0 and scanCol >= endX) do
                    local isEdge = (scanCol <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (scanCol >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)
                    local platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)
                    local needBreakY = (breakY <= 53) and not isTileClear(scanCol, breakY)
                    local needStandY = not isTileClear(scanCol, standY)
                    local fTile = (floorY <= 53) and getRealtimeTile("fg", scanCol, floorY) or 0
                    local needFloor = false
                    if floorY <= 53 then
                        if isEdge then
                            if platStock > 0 then
                                needFloor = (fTile ~= AutoBuildDF.platBlockId and not isBedrockTile(fTile) and not isProtectedTile(fTile))
                            else
                                needFloor = (fTile ~= AutoBuildDF.platBlockId and not isTileClear(scanCol, floorY))
                            end
                        else
                            needFloor = (fTile == 0 or isLavaTile(fTile))
                        end
                    end

                    if needBreakY or needStandY or needFloor then
                        resumeCol = scanCol
                        break
                    end
                    scanCol = scanCol + stepDir
                end

                if lblDFStatus then
                    lblDFStatus.Text = string.format("[BENTUK-TANAH] Baris Y=%d (Lantai %d, Lorong %d)...", standY + 1, floorY + 1, breakY + 1)
                    lblDFStatus.TextColor3 = C.cyan
                end

                -- Pastikan titik awal berdiri standY bersih dari blok/background
                clearBothLayersAt(resumeCol, standY)

                -- Menuju posisi mulai kerja di baris ini secara aman
                local px, py = getPlayerTilePos()
                if not px or math.abs(px - resumeCol) > 1 or math.abs(py - standY) > 1 then
                    -- Hindari pathfind langsung ke tile solid! Jika resumeCol belum bersih, targetkan tile berdiri aman di sampingnya
                    local targetCol = resumeCol
                    if targetCol ~= startX and isSolidTile(targetCol, standY) then
                        targetCol = resumeCol - stepDir
                    end
                    local reached = walkOrPathfindTo(targetCol, standY, worldW, worldH)
                    if not reached then
                        -- Jika langsung gagal, dekati via poros tangga shaft terbuka (startX) terlebih dahulu
                        walkOrPathfindTo(startX, standY, worldW, worldH)
                        approachTile(targetCol, standY, worldW, worldH)
                    end
                    task.wait(0.04)
                end

                if Mobility then
                    Mobility.suspendedY = standY + 1.0
                end

                -- Serpentine sweep di ketinggian standY mulai dari resumeCol sampai endX:
                local currCol = resumeCol
                while AutoBuildDF.active do
                    if (stepDir > 0 and currCol > endX) or (stepDir < 0 and currCol < endX) then
                        break
                    end

                    local isEdgePlat = (currCol <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (currCol >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)

                    -- 0. PRE-BREAK LAVA PADA TILE PIJAKAN CHAR (currCol & nextCol)
                    local nextCol = currCol + stepDir
                    for _, colToCheck in ipairs({currCol, nextCol}) do
                        if colToCheck >= AutoBuildDF.minX and colToCheck <= AutoBuildDF.maxX then
                            -- Cek pijakan kaki (floorY): jika lava, break dan pasang blok pengganti
                            if floorY <= 53 and isLavaTile(getRealtimeTile("fg", colToCheck, floorY)) then
                                if lblDFStatus and lblDFStatus.set then
                                    lblDFStatus:set(string.format("`e[PRE-BREAK LAVA] Hancurkan Lava di pijakan kaki (%d, %d)...``", colToCheck + 1, floorY + 1))
                                end
                                clearBothLayersAt(colToCheck, floorY)
                                task.wait(0.04)
                                local isEdge = (colToCheck <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (colToCheck >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)
                                if isEdge then
                                    local pStock = getRealtimeItemCount(AutoBuildDF.platBlockId)
                                    if pStock > 0 then
                                        placeDFTile("fg", colToCheck, floorY, AutoBuildDF.platBlockId)
                                        AutoBuildDF.totalPlaced = AutoBuildDF.totalPlaced + 1
                                        if updateDirtFarmUI then updateDirtFarmUI() end
                                    end
                                else
                                    local mStock = getRealtimeItemCount(AutoBuildDF.mainBlockId)
                                    if mStock > 0 then
                                        placeDFTile("fg", colToCheck, floorY, AutoBuildDF.mainBlockId)
                                        AutoBuildDF.totalPlaced = AutoBuildDF.totalPlaced + 1
                                        if updateDirtFarmUI then updateDirtFarmUI() end
                                    end
                                end
                            end
                            -- Cek tile berdiri (standY)
                            if isLavaTile(getRealtimeTile("fg", colToCheck, standY)) then
                                clearBothLayersAt(colToCheck, standY)
                            end
                            -- Cek lorong bawah (breakY)
                            if breakY <= 53 and isLavaTile(getRealtimeTile("fg", colToCheck, breakY)) then
                                clearBothLayersAt(colToCheck, breakY)
                            end
                        end
                    end

                    -- 1. Bersihkan tile berdiri di standY jika ada halangan (Validasi ketat sampai bersih)
                    local standTries = 0
                    while AutoBuildDF.active and not isTileClear(currCol, standY) and standTries < 4 do
                        standTries = standTries + 1
                        clearBothLayersAt(currCol, standY)
                        task.wait(0.025)
                    end

                    -- Melangkah ke kolom currCol
                    stepToColumn(currCol, standY)

                    -- 2. GALI LORONG BAWAH: standY + 2 (Break BOTH FG AND BG!)
                    if breakY <= 53 then
                        if lblDFStatus then
                            lblDFStatus.Text = string.format("[BREAK-LORONG] Gali FG & BG lorong (%d, %d)...", currCol + 1, breakY + 1)
                            lblDFStatus.TextColor3 = C.cyan
                        end
                        local breakTries = 0
                        while AutoBuildDF.active and not isTileClear(currCol, breakY) and breakTries < 5 do
                            breakTries = breakTries + 1
                            clearBothLayersAt(currCol, breakY)
                            task.wait(0.025)
                        end
                    end

                    -- 3. BUKA JALAN SISI KIRI: Jika di minX (Tampil X=2), break tile x1 (index 0) di sebelah kiri!
                    if currCol == AutoBuildDF.minX then
                        local leftX = AutoBuildDF.minX - 1
                        if leftX >= 0 then
                            local leftTries = 0
                            while AutoBuildDF.active and not isTileClear(leftX, standY) and leftTries < 4 do
                                leftTries = leftTries + 1
                                clearBothLayersAt(leftX, standY)
                                task.wait(0.025)
                            end
                            if breakY <= 53 then
                                leftTries = 0
                                while AutoBuildDF.active and not isTileClear(leftX, breakY) and leftTries < 4 do
                                    leftTries = leftTries + 1
                                    clearBothLayersAt(leftX, breakY)
                                    task.wait(0.025)
                                end
                            end
                            if floorY <= 53 then
                                leftTries = 0
                                while AutoBuildDF.active and not isTileClear(leftX, floorY) and leftTries < 4 do
                                    leftTries = leftTries + 1
                                    clearBothLayersAt(leftX, floorY)
                                    task.wait(0.025)
                                end
                            end
                        end
                    end

                    -- 4. BUKA JALAN SISI KANAN: Jika di maxX (Tampil X=99), break tile x100 (index 99) di sebelah kanan!
                    if currCol == AutoBuildDF.maxX then
                        local rightX = AutoBuildDF.maxX + 1
                        if rightX < worldW then
                            local rightTries = 0
                            while AutoBuildDF.active and not isTileClear(rightX, standY) and rightTries < 4 do
                                rightTries = rightTries + 1
                                clearBothLayersAt(rightX, standY)
                                task.wait(0.025)
                            end
                            if breakY <= 53 then
                                rightTries = 0
                                while AutoBuildDF.active and not isTileClear(rightX, breakY) and rightTries < 4 do
                                    rightTries = rightTries + 1
                                    clearBothLayersAt(rightX, breakY)
                                    task.wait(0.025)
                                end
                            end
                            if floorY <= 53 then
                                rightTries = 0
                                while AutoBuildDF.active and not isTileClear(rightX, floorY) and rightTries < 4 do
                                    rightTries = rightTries + 1
                                    clearBothLayersAt(rightX, floorY)
                                    task.wait(0.025)
                                end
                            end
                        end
                    end

                    -- 5. BENTUK LANTAI KAKI: floorY = standY + 1
                    if floorY <= 53 then
                        local curTile = getRealtimeTile("fg", currCol, floorY)

                        if isEdgePlat then
                            -- Pinggiran tangga / platform:
                            local platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)

                            if platStock > 0 then
                                -- Ada platform di tas: pasang platform
                                local platTries = 0
                                while AutoBuildDF.active and getRealtimeTile("fg", currCol, floorY) ~= AutoBuildDF.platBlockId and platTries < 4 do
                                    platTries = platTries + 1
                                    if not isTileClear(currCol, floorY) then
                                        clearBothLayersAt(currCol, floorY)
                                    end
                                    platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)
                                    if platStock <= 0 then break end

                                    placeDFTile("fg", currCol, floorY, AutoBuildDF.platBlockId)
                                    AutoBuildDF.totalPlaced = AutoBuildDF.totalPlaced + 1
                                    if updateDirtFarmUI then updateDirtFarmUI() end
                                    task.wait(AutoBuildDF.buildDelay + 0.02)
                                end
                            else
                                -- Platform KOSONG: JANGAN PERNAH KE STORAGE WORLD!
                                -- Tetap break blok di tempat platform (FG & BG) sampai bersih (0) agar jalur terbuka untuk tempat plat nantinya!
                                local clearTries = 0
                                while AutoBuildDF.active and not isTileClear(currCol, floorY) and clearTries < 5 do
                                    clearTries = clearTries + 1
                                    clearBothLayersAt(currCol, floorY)
                                    task.wait(0.025)
                                end
                            end
                        else
                            -- Lantai tengah farm: pasang Dirt / mainBlockId
                            if isLavaTile(curTile) then
                                if lblDFStatus then
                                    lblDFStatus.Text = string.format("[BREAK-LAVA] Hancurkan Lava di (%d, %d)...", currCol + 1, floorY + 1)
                                    lblDFStatus.TextColor3 = C.gold
                                end
                                local lavaTries = 0
                                while AutoBuildDF.active and isLavaTile(getRealtimeTile("fg", currCol, floorY)) and lavaTries < 4 do
                                    lavaTries = lavaTries + 1
                                    clearBothLayersAt(currCol, floorY)
                                    task.wait(0.03)
                                end
                                curTile = getRealtimeTile("fg", currCol, floorY) or 0
                            end

                            if curTile == 0 then
                                local buildTries = 0
                                while AutoBuildDF.active and (getRealtimeTile("fg", currCol, floorY) or 0) == 0 and buildTries < 4 do
                                    buildTries = buildTries + 1
                                    local mainStock = getRealtimeItemCount(AutoBuildDF.mainBlockId)
                                    if mainStock <= 0 then
                                        collectDFMaterials(AutoBuildDF.mainBlockId, 180, false)
                                        mainStock = getRealtimeItemCount(AutoBuildDF.mainBlockId)
                                        -- Pastikan bot kembali ke posisi kerja baris (currCol, standY) secara aman
                                        local curPpx, curPpy = getPlayerTilePos()
                                        if curPpx and curPpy and (math.abs(curPpx - currCol) > 1 or math.abs(curPpy - standY) > 1) then
                                            local reached = walkOrPathfindTo(currCol, standY, worldW, worldH)
                                            if not reached then
                                                walkOrPathfindTo(startX, standY, worldW, worldH)
                                                approachTile(currCol, standY, worldW, worldH)
                                            end
                                            task.wait(0.04)
                                        end
                                    end

                                    if mainStock <= 0 then
                                        local mainSeedId = getSeedIdForBlock(AutoBuildDF.mainBlockId)
                                        local hasTreesOrSeeds = false
                                        if mainSeedId then
                                            if getRealtimeItemCount(mainSeedId) > 0 then
                                                hasTreesOrSeeds = true
                                            elseif scanWorldTrees then
                                                for _, t in ipairs(scanWorldTrees()) do
                                                    if t.seedId == mainSeedId or t.fruitId == AutoBuildDF.mainBlockId then
                                                        hasTreesOrSeeds = true
                                                        break
                                                    end
                                                end
                                            end
                                        end

                                        if hasTreesOrSeeds then
                                            collectDFMaterials(AutoBuildDF.mainBlockId, 180, false)
                                            mainStock = getRealtimeItemCount(AutoBuildDF.mainBlockId)
                                        end
                                    end

                                    if mainStock <= 0 then
                                        if (AutoBuildDF.autoRestock or AutoBuildDF.storageWorld ~= "") and AutoBuildDF.storageWorld ~= "" then
                                            initiateDFRestock(AutoBuildDF.mainBlockId)
                                            return
                                        end
                                        if lblDFStatus and lblDFStatus.set then
                                            lblDFStatus:set(string.format("`4[!] Bahan utama %s (ID %d) habis! Auto DF dihentikan.``", AutoBuildDF.mainBlockName, AutoBuildDF.mainBlockId))
                                        end
                                        stopAutoBuildDF()
                                        return
                                    end

                                    placeDFTile("fg", currCol, floorY, AutoBuildDF.mainBlockId)
                                    AutoBuildDF.totalPlaced = AutoBuildDF.totalPlaced + 1
                                    if updateDirtFarmUI then updateDirtFarmUI() end
                                    task.wait(AutoBuildDF.buildDelay + 0.02)
                                end
                            end
                        end
                    end

                    currCol = currCol + stepDir
                    task.wait(0.015)
                end

                -- =====================================================================
                -- VERIFIKASI AKHIR BARIS: Pastikan tidak ada blok terlewat sebelum turun!
                -- =====================================================================
                if isStandLevelIncomplete(standY) and AutoBuildDF.active then
                    if lblDFStatus then
                        lblDFStatus.Text = string.format("[VERIFIKASI-LAG] Merapikan sisa blok Y=%d...", standY + 1)
                        lblDFStatus.TextColor3 = C.gold
                    end
                    task.wait(0.05)
                    -- Ulangi level ini untuk membereskan sisa yang belum tuntas
                    continue
                end

                -- Selesai 1 baris tuntas 100%, turun ke lorong di bawahnya (breakY) lewat platform pinggir yang baru dibuat
                if breakY <= 52 and lvlIdx < #standLevels then
                    clearBothLayersAt(endX, breakY)
                    if endX == AutoBuildDF.minX and (endX - 1) >= 0 then
                        clearBothLayersAt(endX - 1, breakY)
                    elseif endX == AutoBuildDF.maxX and (endX + 1) < worldW then
                        clearBothLayersAt(endX + 1, breakY)
                    end
                    stepToColumn(endX, breakY)
                    task.wait(0.04)
                end

                lvlIdx = lvlIdx + 1
            end
        end

        -- TAHAP 2: BUILD LANTAI KOSONG SKY (DARI BAWAH KE ATAS: Y=35 -> topY)
        -- Hanya berjalan jika target topY berada di atas permukaan (< 36)
        -- ═════════════════════════════════════════════════════════════
        if AutoBuildDF.active and AutoBuildDF.topY < 36 then
            local skyFloors = {}
            local skyY = 35
            while skyY >= AutoBuildDF.topY do
                table.insert(skyFloors, skyY)
                skyY = skyY - AutoBuildDF.stepY
            end

            local skyStartIdx = nil
            for idx, yVal in ipairs(skyFloors) do
                if isSkyRowIncomplete(yVal) then
                    skyStartIdx = idx
                    break
                end
            end

            if skyStartIdx then
                for sIdx = skyStartIdx, #skyFloors do
                    if not AutoBuildDF.active then break end
                    local curY = skyFloors[sIdx]
                    AutoBuildDF.currentY = curY

                    local isEvenSeq = (sIdx % 2 == 1)
                    local startX  = isEvenSeq and AutoBuildDF.minX or AutoBuildDF.maxX
                    local endX    = isEvenSeq and AutoBuildDF.maxX or AutoBuildDF.minX
                    local stepDir = isEvenSeq and 1 or -1

                    if not isSkyRowIncomplete(curY) then
                        continue
                    end

                    local walkY = curY + 1 -- Berdiri di bawah memasang ke atas (overhead)

                    if lblDFStatus then
                        lblDFStatus.Text = string.format("[BUILD-SKY] Memasang Lantai Sky Y: %d (Bawah -> Atas)...", curY)
                        lblDFStatus.TextColor3 = C.cyan
                    end

                    local px, py = getPlayerTilePos()
                    if not px or math.abs(px - startX) > 1 or math.abs(py - walkY) > 1 then
                        local reached = walkOrPathfindTo(startX, walkY, worldW, worldH)
                        if not reached then
                            stepToColumn(startX, walkY)
                        end
                        task.wait(0.04)
                    end

                    if Mobility then
                        Mobility.suspendedY = walkY + 1.0
                    end

                    local currCol = startX
                    while AutoBuildDF.active do
                        if (stepDir > 0 and currCol > endX) or (stepDir < 0 and currCol < endX) then
                            break
                        end

                        local isEdgePlat = (currCol <= AutoBuildDF.minX + AutoBuildDF.platWidth - 1) or (currCol >= AutoBuildDF.maxX - AutoBuildDF.platWidth + 1)
                        local targetBuildId = isEdgePlat and AutoBuildDF.platBlockId or AutoBuildDF.mainBlockId
                        local platStock = getRealtimeItemCount(AutoBuildDF.platBlockId)

                        if isEdgePlat and platStock <= 0 then
                            targetBuildId = 0
                        end

                        stepToColumn(currCol, walkY)

                        local curTile = getRealtimeTile("fg", currCol, curY)
                        if curTile == 0 and targetBuildId > 0 then
                            local count = getRealtimeItemCount(targetBuildId)
                            if count <= 0 then
                                collectDFMaterials(targetBuildId, 180, false)
                                count = getRealtimeItemCount(targetBuildId)
                                local curPpx, curPpy = getPlayerTilePos()
                                if curPpx and curPpy and (math.abs(curPpx - currCol) > 1 or math.abs(curPpy - walkY) > 1) then
                                    walkOrPathfindTo(currCol, walkY, worldW, worldH)
                                    task.wait(0.04)
                                end
                            end
                            if count <= 0 and targetBuildId == AutoBuildDF.mainBlockId then
                                local mainSeedId = getSeedIdForBlock(AutoBuildDF.mainBlockId)
                                local hasTreesOrSeeds = false
                                if mainSeedId then
                                    if getRealtimeItemCount(mainSeedId) > 0 then
                                        hasTreesOrSeeds = true
                                    elseif scanWorldTrees then
                                        for _, t in ipairs(scanWorldTrees()) do
                                            if t.seedId == mainSeedId or t.fruitId == AutoBuildDF.mainBlockId then
                                                hasTreesOrSeeds = true
                                                break
                                            end
                                        end
                                    end
                                end

                                if hasTreesOrSeeds then
                                    collectDFMaterials(targetBuildId, 180, false)
                                    count = getRealtimeItemCount(targetBuildId)
                                end
                            end

                            if count <= 0 then
                                if (AutoBuildDF.autoRestock or AutoBuildDF.storageWorld ~= "") and AutoBuildDF.storageWorld ~= "" then
                                    initiateDFRestock(AutoBuildDF.mainBlockId)
                                    return
                                end
                                if lblDFStatus and lblDFStatus.set then
                                    lblDFStatus:set("`4[!] Habis bahan utama di tas! Auto DF dihentikan.``")
                                end
                                stopAutoBuildDF()
                                return
                            end

                            placeDFTile("fg", currCol, curY, targetBuildId)
                            AutoBuildDF.totalPlaced = AutoBuildDF.totalPlaced + 1
                            if updateDirtFarmUI then updateDirtFarmUI() end
                            task.wait(AutoBuildDF.buildDelay)
                        end

                        currCol = currCol + stepDir
                        task.wait(0.015)
                    end

                    task.wait(0.04)
                end
            end
        end

        if lblDFStatus then
            lblDFStatus.Text = string.format("[DONE] Selesai! Dirt Farm berhasil dibentuk & dibangun (%d blok dipasang).", AutoBuildDF.totalPlaced)
            lblDFStatus.TextColor3 = C.green
        end
        stopAutoBuildDF()
    end)
end

-- ═══════════════════════════════════════
--  AUTO EVENT BURN ENGINE (LOWKEYMOUNTAIN 1-10 & RESTOCK STORAGE)
-- ═══════════════════════════════════════
AutoEvent = {
    STATE_FILE       = "sysgt_event_state.json",
    getStateFile     = function()
        return getAccountFileName and getAccountFileName("sysgt_event_state", "json") or "sysgt_event_state.json"
    end,
    active           = false,
    busy             = false,
    busyResuming     = false,
    thread           = nil,
    status           = "Standby",
    
    -- Configs
    storageWorld     = "",
    storageDoor      = "",
    burnItemId       = 2,            -- Default: Dirt (ID 2)
    burnItemName     = "Dirt",
    burnTargetCount  = 200,          -- Jumlah bahan yang diambil di storage per trip
    npcPos           = nil,          -- { x = ..., y = ... }
    gameRarity       = 1267,
    gameTargetRarity = 5000000,
    
    -- Stats
    totalBurned      = 0,
    totalTrips       = 0,
    lastBurnedTime   = 0,
}
getgenv().AutoEvent = AutoEvent

AutoEvent.saveState = function(data)
    if not writefile then return end
    local state = {
        active            = (data and data.active ~= nil) and (data.active == true) or (AutoEvent.active == true),
        phase             = (data and data.phase) or "GOTO_STORAGE",
        storageWorld      = (data and data.storageWorld) or AutoEvent.storageWorld or "",
        storageDoor       = (data and data.storageDoor) or AutoEvent.storageDoor or "",
        burnItemId        = (data and data.burnItemId) or AutoEvent.burnItemId or 2,
        burnItemName      = (data and data.burnItemName) or AutoEvent.burnItemName or "Dirt",
        burnTargetCount   = (data and data.burnTargetCount) or AutoEvent.burnTargetCount or 200,
        currentEventWorld = (data and data.currentEventWorld) or AutoEvent.currentEventWorld or "",
        npcPos            = (data and data.npcPos) or AutoEvent.npcPos or nil,
        gameRarity        = AutoEvent.gameRarity or 1267,
        totalBurned       = AutoEvent.totalBurned or 0,
        totalTrips        = AutoEvent.totalTrips or 0,
        timestamp         = os.time(),
    }
    local sFile = AutoEvent.getStateFile and AutoEvent.getStateFile() or AutoEvent.STATE_FILE
    pcall(writefile, sFile, HttpService:JSONEncode(state))
end

AutoEvent.clearState = function()
    local sFile = AutoEvent.getStateFile and AutoEvent.getStateFile() or AutoEvent.STATE_FILE
    if isfile and delfile then
        if isfile(sFile) then pcall(delfile, sFile) end
        if isfile(AutoEvent.STATE_FILE) then pcall(delfile, AutoEvent.STATE_FILE) end
    end
    if writefile then
        pcall(writefile, sFile, HttpService:JSONEncode({ active = false }))
    end
end

stopAutoEvent = function()
    AutoEvent.active = false
    AutoEvent.busy = false
    if AutoEvent.thread then
        pcall(task.cancel, AutoEvent.thread)
        AutoEvent.thread = nil
    end
    AutoEvent.clearState()
    AutoEvent.status = "Standby"
    if updateEventUI then updateEventUI() end
    if Proxy and Proxy.notify then
        Proxy.notify("`4[Event] Auto Event Burn dihentikan!``")
    end
end
AutoEvent.stop = stopAutoEvent

startAutoEvent = function()
    if AutoEvent.active then return end
    
    -- Stop all conflicting routines
    if PNB and PNB.active and stopPNB then stopPNB() end
    if ClearWorld and ClearWorld.active and stopClearWorld then stopClearWorld() end
    if AutoPlant and AutoPlant.active and stopAutoPlant then stopAutoPlant() end
    if AutoHarvest and AutoHarvest.active and stopAutoHarvest then stopAutoHarvest() end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end
    if AutoRotation and AutoRotation.active and stopAutoRotation then stopAutoRotation() end
    if AutoBuildDF and AutoBuildDF.active and stopAutoBuildDF then stopAutoBuildDF() end

    AutoEvent.active = true
    AutoEvent.busy = false
    if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    if updateEventUI then updateEventUI() end

    if Proxy and Proxy.notify then
        Proxy.notify("`2[Event] Auto Event Burn dimulai! Memeriksa bahan di tas...``")
    end

    AutoEvent.runLoop()
end
AutoEvent.start = startAutoEvent

checkResumeEventState = function()
    if AutoEvent.busyResuming then return end
    local sFile = AutoEvent.getStateFile and AutoEvent.getStateFile() or AutoEvent.STATE_FILE
    if not isfile or not readfile then return end
    local fileToRead = nil
    if isfile(sFile) then
        fileToRead = sFile
    elseif isfile(AutoEvent.STATE_FILE) then
        fileToRead = AutoEvent.STATE_FILE
    end
    if not fileToRead then return end
    local ok, raw = pcall(readfile, fileToRead)
    if not ok or not raw or raw == "" then return end
    local ok_dec, state = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok_dec or type(state) ~= "table" or not state.active then return end

    if isWorldPickerOpen and isWorldPickerOpen() then
        print("[EVENT-STATE] Menunda resume: Player masih di World List / Lobby.")
        return
    end

    AutoEvent.busyResuming = true
    AutoEvent.active = true
    if state.storageWorld then AutoEvent.storageWorld = state.storageWorld end
    if state.storageDoor then AutoEvent.storageDoor = state.storageDoor end
    if state.burnItemId then AutoEvent.burnItemId = state.burnItemId end
    if state.burnItemName then AutoEvent.burnItemName = state.burnItemName end
    if state.burnTargetCount then AutoEvent.burnTargetCount = state.burnTargetCount end
    if state.npcPos then AutoEvent.npcPos = state.npcPos end
    if state.gameRarity then AutoEvent.gameRarity = state.gameRarity end
    if state.totalBurned then AutoEvent.totalBurned = state.totalBurned end
    if state.totalTrips then AutoEvent.totalTrips = state.totalTrips end
    AutoEvent.status = string.format("[RESUME] Melanjutkan Event (%s)...", tostring(state.phase or "GOTO_STORAGE"))

    if updateEventUI then updateEventUI() end

    task.spawn(function()
        task.wait(1.0)
        AutoEvent.busyResuming = false
        AutoEvent.runLoop(state.phase, state.currentEventWorld)
    end)
end
AutoEvent.checkResume = checkResumeEventState

-- Helper: Dedicated Storage Drops Gatherer (Vacuum & Pathfind)
AutoEvent.gatherStorageDrops = function(targetItemId, maxTarget)
    if not targetItemId or targetItemId <= 0 then return false end
    maxTarget = maxTarget or 200

    local startCount = getRealtimeItemCount(targetItemId)
    if startCount >= maxTarget then return true end

    local w = getNativeWorld and getNativeWorld()
    if not w then return false end
    local worldW = (w and w.w) or (w and w.worldSize and w.worldSize.x) or 100
    local worldH = (w and w.h) or (w and w.worldSize and w.worldSize.y) or 60
    local inv = getNativeInventory and getNativeInventory()

    local maxTries = 40
    local tryCount = 0

    while AutoEvent.active and tryCount < maxTries do
        tryCount = tryCount + 1
        local curCount = getRealtimeItemCount(targetItemId)
        if curCount >= maxTarget then break end

        local curDrops = (w and w.dropList and w.dropList()) or {}
        local matchingDrops = {}
        for _, d in ipairs(curDrops) do
            if d and d.uid and d.id == targetItemId and not d.taking and (d.n or 0) > 0 then
                local dtx = math.floor(d.x or 0)
                local dty = math.floor(d.y or 0)
                if not isSolidTile(dtx, dty) then
                    table.insert(matchingDrops, d)
                end
            end
        end

        if #matchingDrops == 0 then
            break
        end

        local px, py = getPlayerTilePos()
        px = px or 50
        py = py or 30

        table.sort(matchingDrops, function(a, b)
            local ax, ay = a.x or 0, a.y or 0
            local bx, by = b.x or 0, b.y or 0
            local da = (ax - px)^2 + (ay - py)^2
            local db = (bx - px)^2 + (by - py)^2
            return da < db
        end)

        local targetDrop = matchingDrops[1]
        local dtx = math.floor(targetDrop.x or 0)
        local dty = math.floor(targetDrop.y or 0)

        AutoEvent.status = string.format("[1/3] Menyapu drop %s (%d/%d)... Menuju (%d,%d)", AutoEvent.burnItemName or "Bahan", curCount, maxTarget, dtx, dty)
        if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`e" .. AutoEvent.status .. "``") end

        local reached = walkOrPathfindTo(dtx, dty, worldW, worldH)
        if not reached then
            approachTile(dtx, dty, worldW, worldH)
        end
        task.wait(0.05)

        local nowPx, nowPy = getPlayerTilePos()
        nowPx = nowPx or dtx
        nowPy = nowPy or dty

        for _, d in ipairs(matchingDrops) do
            if d and d.uid and not d.taking and d.id == targetItemId then
                local dx = (d.x or 0) - nowPx
                local dy = (d.y or 0) - nowPy
                if math.sqrt(dx*dx + dy*dy) <= 2.8 then
                    tryPickupDrop(d, inv)
                end
            end
        end

        task.wait(0.1)
    end

    local finalStock = getRealtimeItemCount(targetItemId)
    return finalStock >= maxTarget or finalStock > startCount
end

-- Helper: Locate NPC Lowkey in LOWKEYMOUNTAIN
AutoEvent.getNpcTile = function()
    local w = getNativeWorld and getNativeWorld()
    if not w then return nil, nil end

    if w.burnUI then
        if type(w.burnUI.x) == "number" and type(w.burnUI.y) == "number" then
            return w.burnUI.x, w.burnUI.y
        end
        if type(w.burnUI.npcX) == "number" and type(w.burnUI.npcY) == "number" then
            return w.burnUI.npcX, w.burnUI.npcY
        end
    end

    if w.npcs and type(w.npcs) == "table" then
        for _, n in pairs(w.npcs) do
            if type(n) == "table" and n.x and n.y then
                local nm = string.lower(tostring(n.name or n.id or ""))
                if string.find(nm, "lwkey") or string.find(nm, "lowkey") or string.find(nm, "inferno") or string.find(nm, "burn") then
                    return math.floor(n.x), math.floor(n.y)
                end
            end
        end
    end

    for _, tblName in ipairs({"signs", "displays", "areas"}) do
        local tbl = w[tblName]
        if type(tbl) == "table" then
            for k, it in pairs(tbl) do
                if type(it) == "table" then
                    local s = string.lower(tostring(it.text or it.name or it.tag or it.act or k))
                    if string.find(s, "lwkey") or string.find(s, "inferno") or string.find(s, "burn") then
                        local tx = it.x or it.tx
                        local ty = it.y or it.ty
                        if not tx and type(k) == "string" then
                            local kx, ky = k:match("(%d+)[,:](%d+)")
                            if kx and ky then tx, ty = tonumber(kx), tonumber(ky) end
                        end
                        if tx and ty then return tx, ty end
                    end
                end
            end
        end
    end

    if AutoEvent.npcPos and AutoEvent.npcPos.x and AutoEvent.npcPos.y then
        return AutoEvent.npcPos.x, AutoEvent.npcPos.y
    end

    local worldW = (w and w.w) or 100
    local worldH = (w and w.h) or 60
    local spawnX = (w and w.spawn and w.spawn.X) or 34
    local spawnY = (w and w.spawn and w.spawn.Y) or 22

    for dy = -10, 10 do
        local ty = spawnY + dy
        if ty >= 0 and ty < worldH and w.fg and w.fg[ty] then
            for dx = -30, 30 do
                local tx = spawnX + dx
                if tx >= 0 and tx < worldW then
                    local fg = w.fg[ty][tx] or 0
                    if fg > 0 and fg ~= 1 and fg ~= 2 and fg ~= 4 and fg ~= 6 and fg ~= 8 and fg ~= 10 and fg ~= 14 and fg ~= 102 then
                        return tx, ty
                    end
                end
            end
        end
    end

    for y = 0, worldH - 1 do
        if w.fg and w.fg[y] then
            for x = 0, worldW - 1 do
                local fg = w.fg[y][x] or 0
                if fg > 0 and fg ~= 1 and fg ~= 2 and fg ~= 4 and fg ~= 6 and fg ~= 8 and fg ~= 10 and fg ~= 14 and fg ~= 102 then
                    return x, y
                end
            end
        end
    end

    return nil, nil
end

AutoEvent.runLoop = function(initPhase, initEventWorld)
    if AutoEvent.thread then
        pcall(task.cancel, AutoEvent.thread)
        AutoEvent.thread = nil
    end

    AutoEvent.thread = task.spawn(function()
        local currentPhase = initPhase
        local currentEventW = initEventWorld

        while AutoEvent.active do
            -- Tentukan phase awal jika belum ada
            if not currentPhase then
                local stock = getRealtimeItemCount(AutoEvent.burnItemId)
                if stock >= 10 then
                    currentPhase = "GOTO_EVENT"
                else
                    currentPhase = "GOTO_STORAGE"
                end
            end

            -- ─────────────────────────────────────────────────────────────
            -- PHASE 1: GOTO_STORAGE (Ambil Bahan Target di Storage World)
            -- ─────────────────────────────────────────────────────────────
            if currentPhase == "GOTO_STORAGE" then
                local curStock = getRealtimeItemCount(AutoEvent.burnItemId)
                local targetAmt = AutoEvent.burnTargetCount or 200
                if curStock >= targetAmt then
                    currentPhase = "GOTO_EVENT"
                else
                    if not AutoEvent.storageWorld or AutoEvent.storageWorld == "" then
                        AutoEvent.status = "[!] Storage World kosong! Masukkan nama storage world atau siapkan bahan di tas."
                        if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`4" .. AutoEvent.status .. "``") end
                        if Proxy and Proxy.notify then Proxy.notify("`4[Event] Storage World belum diisi! Auto Event dihentikan.``") end
                        stopAutoEvent()
                        return
                    end

                    local sWorld = string.upper((tostring(AutoEvent.storageWorld):gsub("%s+", "")))
                    local sDoor = (AutoEvent.storageDoor and AutoEvent.storageDoor ~= "") and AutoEvent.storageDoor or nil

                    local w = getNativeWorld and getNativeWorld()
                    local nowW = w and w.name and string.upper(tostring(w.name)) or ""

                    if nowW ~= sWorld then
                        AutoEvent.status = string.format("[1/3] Berpindah ke Storage World: %s...", sWorld)
                        if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`c" .. AutoEvent.status .. "``") end
                        AutoEvent.saveState({ phase = "GOTO_STORAGE" })

                        safeQueueOnTeleport()
                        task.wait(0.5)
                        warpToWorld(sWorld, sDoor)

                        local loaded = waitForWorldFullyLoaded(sWorld, 30)
                        if not loaded then
                            AutoEvent.status = "[!] Gagal memuat Storage World! Mencoba kembali..."
                            task.wait(3.0)
                        end
                    end

                    if AutoEvent.active then
                        AutoEvent.status = string.format("[1/3] Menyapu droppan bahan %s di Storage World...", AutoEvent.burnItemName or "Bahan")
                        if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`e" .. AutoEvent.status .. "``") end

                        -- Sapu droppan bahan dengan vacuum khusus AutoEvent
                        AutoEvent.gatherStorageDrops(AutoEvent.burnItemId, targetAmt)

                        task.wait(0.5)
                        local finalStock = getRealtimeItemCount(AutoEvent.burnItemId)
                        if finalStock <= 0 then
                            AutoEvent.status = string.format("[!] Bahan %s habis di Storage World! Auto Event berhenti.", AutoEvent.burnItemName or "Bahan")
                            if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`4" .. AutoEvent.status .. "``") end
                            if Proxy and Proxy.notify then Proxy.notify("`4[Event] " .. AutoEvent.status .. "``") end
                            stopAutoEvent()
                            return
                        end

                        currentPhase = "GOTO_EVENT"
                    end
                end

            -- ─────────────────────────────────────────────────────────────
            -- PHASE 2: GOTO_EVENT (Warp ke Event World LOWKEYMOUNTAIN 1-10)
            -- ─────────────────────────────────────────────────────────────
            elseif currentPhase == "GOTO_EVENT" then
                -- Default murni random LOWKEYMOUNTAIN 1-10 (tidak perlu setting ribet)
                local randIdx = math.random(1, 10)
                local targetWorld = "LOWKEYMOUNTAIN" .. tostring(randIdx)
                currentEventW = targetWorld

                AutoEvent.status = string.format("[2/3] OTW ke Event World: %s...", targetWorld)
                if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`2" .. AutoEvent.status .. "``") end
                AutoEvent.saveState({ phase = "BURN_ITEMS", currentEventWorld = targetWorld })

                safeQueueOnTeleport()
                task.wait(0.5)
                warpToWorld(targetWorld)

                local loaded = waitForWorldFullyLoaded(targetWorld, 30)
                if not loaded then
                    AutoEvent.status = "[!] Gagal memuat Event World! Mencoba kembali..."
                    task.wait(3.0)
                else
                    currentPhase = "BURN_ITEMS"
                end

            -- ─────────────────────────────────────────────────────────────
            -- PHASE 3: BURN_ITEMS (Pathfind ke NPC Lowkey & Burn Bahan Rarity)
            -- ─────────────────────────────────────────────────────────────
            elseif currentPhase == "BURN_ITEMS" then
                AutoEvent.status = string.format("[3/3] Tiba di %s! Mendeteksi & Pathfinding ke NPC Lowkey...", tostring(currentEventW or "Event World"))
                if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`a" .. AutoEvent.status .. "``") end

                local w = getNativeWorld and getNativeWorld()
                local worldW = (w and w.w) or 100
                local worldH = (w and w.h) or 60

                -- 1. Deteksi koordinat NPC Lowkey dan Pathfind ke sana!
                local npcX, npcY = AutoEvent.getNpcTile()
                if npcX and npcY then
                    AutoEvent.status = string.format("[3/3] Pathfind mendekati NPC Lowkey di (%d, %d)...", npcX, npcY)
                    if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`a" .. AutoEvent.status .. "``") end

                    local standX = (npcX > 2) and (npcX - 1) or (npcX + 1)
                    local standY = npcY
                    walkOrPathfindTo(standX, standY, worldW, worldH)
                    task.wait(0.3)
                end

                local attempts = 0
                local burnSuccessCount = 0

                while AutoEvent.active and getRealtimeItemCount(AutoEvent.burnItemId) > 0 and attempts < 60 do
                    attempts = attempts + 1

                    -- Auto-save posisi player saat ini sebagai NPC Pos jika dialog terbuka
                    local curPx, curPy = getPlayerTilePos()
                    if curPx and curPy and not AutoEvent.npcPos then
                        AutoEvent.npcPos = { x = curPx, y = curPy }
                    end

                    -- 1. Equip Fist
                    if selectSlot then pcall(selectSlot, 1) end

                    -- 2. Punch NPC Lowkey
                    local targetPunchX = npcX or (curPx and (curPx + 1)) or 35
                    local targetPunchY = npcY or curPy or 22
                    sendActPacket(ACT_KIND.PUNCH, targetPunchX, targetPunchY)
                    sendActPacket(ACT_KIND.HIT, targetPunchX, targetPunchY)
                    if curPx and curPy then
                        sendActPacket(ACT_KIND.PUNCH, curPx + 1, curPy)
                        sendActPacket(ACT_KIND.HIT, curPx + 1, curPy)
                        sendActPacket(ACT_KIND.PUNCH, curPx - 1, curPy)
                        sendActPacket(ACT_KIND.HIT, curPx - 1, curPy)
                        sendActPacket(ACT_KIND.PUNCH, curPx, curPy)
                        sendActPacket(ACT_KIND.HIT, curPx, curPy)
                    end

                    -- 3. Trigger native dialog opener jika w.burnUI tersedia
                    if w and w.burnUI and w.burnUI.open then
                        pcall(w.burnUI.open)
                    end

                    task.wait(0.2)

                    local beforeCount = getRealtimeItemCount(AutoEvent.burnItemId)

                    -- 4. Metode A: Direct RPC ByteNet & Client Method (Instant & 100% Legit)
                    if Net and Net.call then
                        pcall(Net.call, "BurnFarmable", "burn", AutoEvent.burnItemId, beforeCount)
                        pcall(Net.call, "BurnFarmable", "burn", AutoEvent.burnItemId)
                        pcall(Net.call, "BurnFarmable", "burn")
                    end
                    if w and w.burnUI and w.burnUI.burn then
                        pcall(w.burnUI.burn, AutoEvent.burnItemId, beforeCount)
                    end

                    -- 5. Metode B: UI Native Click Automation
                    local pgui = PlayerGui
                    local mg = pgui and pgui:FindFirstChild("MenuGui")
                    local bf = mg and mg:FindFirstChild("BurnFarmable")
                    local bp = mg and mg:FindFirstChild("BurnPick")

                    if bf and bf.Visible == true then
                        local panel = bf:FindFirstChild("Area") and bf.Area:FindFirstChild("Panel")
                        if panel then
                            for _, d in ipairs(panel:GetDescendants()) do
                                if d:IsA("GuiButton") and d.AbsoluteSize.X > 140 then
                                    clickGuiObject(d)
                                    break
                                end
                            end
                        end
                        task.wait(0.25)
                    end

                    if bp and bp.Visible == true then
                        local bpPanel = bp:FindFirstChild("Area") and bp.Area:FindFirstChild("Panel")
                        if bpPanel then
                            for _, d in ipairs(bpPanel:GetDescendants()) do
                                if d:IsA("GuiButton") then
                                    clickGuiObject(d)
                                end
                            end
                        end
                        task.wait(0.25)
                    end

                    -- Cek perubahan stok di tas
                    local afterCount = getRealtimeItemCount(AutoEvent.burnItemId)
                    local diff = beforeCount - afterCount
                    if diff > 0 then
                        burnSuccessCount = burnSuccessCount + diff
                        AutoEvent.totalBurned = (AutoEvent.totalBurned or 0) + diff
                        local rarityPerItem = 1
                        if AutoEvent.burnItemId == 4 then rarityPerItem = 2
                        elseif AutoEvent.burnItemId == 8 then rarityPerItem = 2
                        elseif AutoEvent.burnItemId == 102 then rarityPerItem = 2
                        end
                        AutoEvent.gameRarity = (AutoEvent.gameRarity or 1267) + (diff * rarityPerItem)
                        AutoEvent.status = string.format("[3/3] Berhasil burn %d %s! Sisa di tas: %d...", diff, AutoEvent.burnItemName or "Bahan", afterCount)
                        if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`2" .. AutoEvent.status .. "``") end
                        if updateEventUI then updateEventUI() end
                        attempts = 0
                    end

                    task.wait(0.35)
                end

                AutoEvent.totalTrips = (AutoEvent.totalTrips or 0) + 1
                AutoEvent.status = string.format("[EVENT] Trip selesai! %d bahan di-burn. Kembali ke Storage...", burnSuccessCount)
                if lblEventStatus and lblEventStatus.set then lblEventStatus:set("`2" .. AutoEvent.status .. "``") end
                if Proxy and Proxy.notify then
                    Proxy.notify(string.format("`2[Event] Selesai burn 1 batch (%d item)! Kembali restock storage...``", burnSuccessCount))
                end
                if updateEventUI then updateEventUI() end

                currentPhase = "GOTO_STORAGE"
                currentEventW = nil
                AutoEvent.saveState({ phase = "GOTO_STORAGE" })
                task.wait(1.0)
            end

            task.wait(0.25)
        end
    end)
end

-- ═══════════════════════════════════════
--  AUTO HARVEST & TREE SCANNER ENGINE (FULL WORLD & ROW-BY-ROW SERPENTINE)
-- ═══════════════════════════════════════
local itemLookup = {}
pcall(function()
    local Autotile = nil
    if Shared and Shared:FindFirstChild("Autotile") then
        local ok, at = pcall(require, Shared.Autotile)
        if ok and at then Autotile = at end
    end
    if not Autotile and filtergc then
        local atList = filtergc("table", { Keys = {"aloneCell", "blobCell"} }, false)
        if atList and atList[1] then Autotile = atList[1] end
    end
    local idb = ItemDB or (resolveItemDB and resolveItemDB())
    if idb and Autotile then
        for id = 1, 15000 do
            local it = idb[id]
            if it and it.atlas then
                local ax, ay = Autotile.aloneCell(it)
                if it.kind == "cloth" and it.slot == "feet" then
                    ay = ay * 2
                end
                itemLookup[string.format("%s_%d_%d", it.atlas, ax, ay)] = id
            end
        end
    end
end)

local cachedNativeTrees = nil
local lastTreeCheck = 0
local function getNativeTrees()
    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    if not w then
        cachedNativeTrees = nil
        return nil, nil, nil
    end

    if cachedNativeTrees and cachedNativeTrees._world == w then
        return cachedNativeTrees.trees, cachedNativeTrees.visual, cachedNativeTrees.setTree
    end

    local now = os.clock()
    if now - lastTreeCheck < 0.5 and cachedNativeTrees then
        return cachedNativeTrees.trees, cachedNativeTrees.visual, cachedNativeTrees.setTree
    end
    lastTreeCheck = now

    -- 1. Direct from native engine (Instant, 100% reliable)
    if eng and eng.trees then
        cachedNativeTrees = {
            trees = eng.trees,
            visual = nil,
            setTree = eng.setTree or (w and w.setTree),
            _world = w,
        }
        return eng.trees, nil, cachedNativeTrees.setTree
    end

    return nil, nil, nil
end

scanWorldTrees = function()
    local list = {}
    local nativeTrees, visualTrees, nativeSetTree = getNativeTrees()
    local w = getNativeWorld()
    local worldW = (w and w.w) or 100
    local worldH = (w and w.h) or 60
    local serverNow = workspace:GetServerTimeNow()
    local visited = {}

    -- 1. Scan semua pohon dari nativeTrees (full world database pohon game)
    if nativeTrees then
        for key, entry in pairs(nativeTrees) do
            local numKey = tonumber(key)
            if numKey and type(entry) == "table" then
                local tx = numKey % worldW
                local ty = math.floor(numKey / worldW)
                local curFg = w and w.fg and w.fg[ty] and w.fg[ty][tx]
                if curFg and curFg > 0 then
                    local seedId = curFg
                    local fruitCount = tonumber(entry.f) or 0
                    local growTime = (ItemDB and ItemDB[seedId] and ItemDB[seedId].grow) or 30
                    local plantTime = tonumber(entry.p)

                    -- STRICT RIPENESS: Formula resmi game (treeRipe: plantTime + grow <= serverNow)
                    local isRipe = false
                    local progress = 0
                    if plantTime and plantTime > 0 then
                        local elapsed = math.max(0, serverNow - plantTime)
                        progress = math.clamp(math.floor((elapsed / math.max(1, growTime)) * 100), 0, 100)
                        if elapsed >= growTime then
                            isRipe = true
                        end
                    end

                    local fruitId = (ItemDB and ItemDB[seedId] and ItemDB[seedId].block) or (seedId and seedId > 1 and (seedId - 1)) or nil

                    local treeName = "Pohon"
                    if fruitId and ItemDB and ItemDB[fruitId] then
                        treeName = (ItemDB[fruitId].name or "Item") .. " Tree"
                    elseif seedId and ItemDB and ItemDB[seedId] then
                        treeName = (ItemDB[seedId].name or "Seed") .. " Tree"
                    elseif fruitId then
                        treeName = getDFItemName(fruitId) .. " Tree"
                    end

                    visited[numKey] = true
                    table.insert(list, {
                        x = tx,
                        y = ty,
                        name = treeName,
                        seedId = seedId,
                        fruitId = fruitId,
                        fruits = isRipe and math.max(fruitCount, 1) or 0,
                        isRipe = isRipe,
                        progress = progress,
                        p = plantTime,
                        grow = growTime,
                    })
                end
            end
        end
    end

    -- 2. Scan foreground w.fg secara menyeluruh di seluruh world (100x60) untuk mendeteksi seed/tree yang belum terdata di nativeTrees
    if w and w.fg then
        for ty = 0, worldH - 1 do
            local row = w.fg[ty]
            if row then
                for tx = 0, worldW - 1 do
                    local tid = row[tx]
                    local numKey = ty * worldW + tx
                    if tid and tid > 0 and not visited[numKey] then
                        local db = ItemDB and ItemDB[tid]
                        local isSeed = (db and (db.kind == "seed" or db.tree ~= nil or db.grow ~= nil)) or (tid % 2 == 1 and tid > 1)
                        if isSeed then
                            local treeName = (db and db.name or getDFItemName(tid)) .. " Tree"
                            local fruitId = (db and db.block) or (tid - 1)
                            visited[numKey] = true

                            local isRipe = false
                            local progress = 0
                            local growTime = (db and db.grow) or 30

                            -- Cek tracking bot AutoBuildDF jika ada
                            if AutoBuildDF and AutoBuildDF._plantedSeeds and AutoBuildDF._plantedSeeds[numKey] then
                                local elapsed = os.clock() - AutoBuildDF._plantedSeeds[numKey]
                                progress = math.clamp(math.floor((elapsed / math.max(1, growTime)) * 100), 0, 100)
                                if elapsed >= growTime then
                                    isRipe = true
                                    progress = 100
                                end
                            end

                            table.insert(list, {
                                x = tx,
                                y = ty,
                                name = treeName,
                                seedId = tid,
                                fruitId = fruitId,
                                fruits = isRipe and 1 or 0,
                                isRipe = isRipe,
                                progress = progress,
                                p = nil,
                                grow = growTime,
                            })
                        end
                    end
                end
            end
        end
    end

    return list
end

stopAutoHarvest = function(keepState)
    AutoHarvest.active = false
    AutoHarvest.status = "Standby"
    if not keepState and FarmLogistics then
        FarmLogistics.clearTask("HARVEST")
    end
    if AutoHarvest.thread then
        pcall(task.cancel, AutoHarvest.thread)
        AutoHarvest.thread = nil
    end
    print("[SYSHUB] Auto Harvest dihentikan." .. (keepState and " (tugas disimpan, lanjut setelah warp)" or ""))
    if updateHarvestUI then updateHarvestUI() end
end

startAutoHarvest = function()
    if AutoHarvest.active then return end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end
    if AutoPlant and AutoPlant.active then stopAutoPlant() end
    if FarmLogistics and FarmLogistics.move.active then FarmLogistics.moveStop("Dihentikan (Auto Harvest mulai)") end
    AutoHarvest.status = "Scanning pohon matang..."
    print("[SYSHUB] Auto Harvest dimulai!")
    FarmLogistics.startHarvest()
end

-- ═══════════════════════════════════════
--  AUTO PLANT: SOIL SCANNER (ROW-BY-ROW SERPENTINE)
-- ═══════════════════════════════════════
scanPlantableRows = function(worldW, worldH)
    worldW = worldW or 100
    worldH = worldH or 60
    local rowsWithSpots = {}
    local rowList = {}

    -- Scan dari baris paling atas ke bawah (Top to Bottom)
    for y = 0, worldH - 2, 1 do
        local spotsInRow = {}
        for x = 0, worldW - 1 do
            local curFg = getRealtimeTile("fg", x, y)
            -- Tile kosong, bukan area terkunci orang lain, bukan solid,
            -- dan tepat di bawahnya ada blok FG yang bukan bibit/pohon.
            if curFg == 0 and not isTileLocked(x, y) and not isSolidTile(x, y) then
                local belowFg = getRealtimeTile("fg", x, y + 1)
                if belowFg and belowFg > 0 and not isSeedOrTreeId(belowFg) then
                    table.insert(spotsInRow, { x = x, y = y })
                end
            end
        end
        if #spotsInRow > 0 then
            rowsWithSpots[y] = spotsInRow
            table.insert(rowList, y)
        end
    end

    return rowList, rowsWithSpots
end

local function getActiveSeed()
    if AutoPlant.selectedSeedId then
        local count = getRealtimeItemCount(AutoPlant.selectedSeedId)
        if count > 0 then
            return AutoPlant.selectedSeedId, AutoPlant.selectedSeedName or ("Seed #" .. AutoPlant.selectedSeedId), count
        end
        -- Storage seed aktif: kunci bibit ini (di-restock dari storage), jangan ganti bibit lain
        local ps = FarmLogistics and FarmLogistics.plantStorage
        if ps and ps.enabled and ps.world ~= "" then
            return nil, nil, 0
        end
        AutoPlant.selectedSeedId = nil
        AutoPlant.selectedSeedName = nil
    end

    -- Cari bibit apapun yang ada di tas dengan count > 0
    local items = fetchInventoryItems()
    for _, it in ipairs(items) do
        local isSeed = (it.kind == "seed") or string.find((it.name or ""):lower(), "seed") or (it.id % 2 == 1 and it.id > 1)
        if isSeed and (it.count or 0) > 0 then
            AutoPlant.selectedSeedId = it.id
            AutoPlant.selectedSeedName = it.name or getDFItemName(it.id)
            if updatePlantUI then updatePlantUI() end
            return it.id, AutoPlant.selectedSeedName, it.count
        end
    end

    return nil, nil, 0
end

-- keepState = true: dipanggil bukan oleh user (UI di-destroy saat warp/teleport)
-- -> JANGAN hapus state file, supaya tugas dilanjutkan otomatis di world berikutnya.
stopAutoPlant = function(keepState)
    AutoPlant.active = false
    AutoPlant.status = "Standby"
    if not keepState and FarmLogistics then
        FarmLogistics.clearTask("PLANT")
    end
    if AutoPlant.thread then
        pcall(task.cancel, AutoPlant.thread)
        AutoPlant.thread = nil
    end
    print("[SYSHUB] Auto Plant dihentikan." .. (keepState and " (tugas disimpan, lanjut setelah warp)" or ""))
    if updatePlantUI then updatePlantUI() end
end

startAutoPlant = function()
    if AutoPlant.active then return end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end
    if AutoHarvest and AutoHarvest.active then stopAutoHarvest() end
    if FarmLogistics and FarmLogistics.move.active then FarmLogistics.moveStop("Dihentikan (Auto Plant mulai)") end
    AutoPlant.status = "Memeriksa bibit..."
    print("[SYSHUB] Auto Plant dimulai!")
    FarmLogistics.startPlant()
end

-- ═══════════════════════════════════════
--  FARM LOGISTICS v2: Auto Plant / Auto Harvest / Move World yang TETAP JALAN
--  setelah warp (seperti Auto Rotation). Satu tugas aktif disimpan ke
--  sysgt_farmlogi_state_<akun>.json lalu dilanjutkan tiap world selesai load
--  (warp server sama, warp beda server via queue_on_teleport, atau auto-rejoin).
--
--    PLANT   : list "WORLD|SEED|DOOR" -> tanam semua tanah kosong tiap world. Seed habis ->
--              ambil di storage seed -> balik -> lanjut. World penuh -> world berikutnya.
--    HARVEST : list "WORLD|SEED|DOOR" -> panen pohon matang (seed itu / semua) + collect.
--              Tas >= ambang -> setor ke storage -> balik -> lanjut. Beres -> world berikutnya.
--    MOVE    : sapu item target di world asal -> drop di world tujuan -> bolak-balik.
--  List kosong = hanya world saat ini (perilaku lama).
-- ═══════════════════════════════════════
FarmLogistics = {
    plantStorage   = { world = "", door = "", x = nil, y = nil, enabled = false },
    harvestStorage = { world = "", door = "", x = nil, y = nil, enabled = false, threshold = 180 },
    plantWorlds    = {}, -- { {world=, seedId=, seedName=, door=} }
    harvestWorlds  = {},
    move = {
        active = false, busy = false, status = "Standby",
        itemIds = {}, itemNames = {},
        fromWorld = "", fromDoor = "",
        toWorld = "", toDoor = "", toX = nil, toY = nil,
        totalMoved = 0, trips = 0,
    },
    busyResuming = false,
    runToken = 0,       -- naik tiap ada runner baru / STOP -> runner lama berhenti sendiri
    runnerThread = nil,
    lastWarpAt = nil,
}
do
    local FL = FarmLogistics
    local M = FL.move
    _G.SysHubFarmLogistics = FL -- untuk debug dari executor / console
    FL._dbg = { getPlayerTilePos = getPlayerTilePos, getNativeWorld = getNativeWorld, waitForWorldFullyLoaded = waitForWorldFullyLoaded }
    local MAX_STACK = 200
    local WRAP_IDLE = 30         -- detik jeda setelah satu putaran list world selesai
    local SEED_EMPTY_COOLDOWN = 600

    ------------------------------------------------------------------
    -- Util
    ------------------------------------------------------------------
    local function cleanWorld(s)
        return string.upper((string.gsub(tostring(s or ""), "%s+", "")))
    end
    FL.cleanWorld = cleanWorld

    function FL.currentWorld()
        local w = getNativeWorld and getNativeWorld()
        return (w and w.name and cleanWorld(w.name)) or ""
    end

    local function hereIs(world)
        world = cleanWorld(world)
        return world ~= "" and FL.currentWorld() == world
    end

    function FL.notify(msg)
        if Proxy and Proxy.notify then pcall(Proxy.notify, msg) end
        print("[FARM-LOGI] " .. (tostring(msg):gsub("`%w", ""):gsub("``", "")))
    end

    function FL.worldSize()
        local w = getNativeWorld and getNativeWorld()
        return (w and tonumber(w.w)) or 100, (w and tonumber(w.h)) or 60
    end

    function FL.itemName(id)
        id = tonumber(id)
        local db = ItemDB or (resolveItemDB and resolveItemDB())
        local it = db and id and db[id]
        return (it and it.name) or (id and ("Item #" .. id)) or "?"
    end

    -- "WORLD|SEED|DOOR". SEED boleh id (3), nama seed ("Dirt Seed") atau nama blok ("Dirt").
    function FL.parseWorldEntry(text)
        if type(text) ~= "string" then return nil, "kosong" end
        local parts = string.split(text, "|")
        local world = cleanWorld(parts[1])
        if world == "" then return nil, "nama world kosong" end
        local rawSeed = parts[2] and (parts[2]:gsub("^%s*(.-)%s*$", "%1")) or ""
        local seedId = tonumber(rawSeed)
        if not seedId and rawSeed ~= "" then
            local db = ItemDB or (resolveItemDB and resolveItemDB())
            local low = rawSeed:lower()
            if db then
                for id, v in pairs(db) do
                    if type(v) == "table" and v.name and v.name:lower() == low then seedId = id break end
                end
                if not seedId then
                    for id, v in pairs(db) do
                        if type(v) == "table" and v.name and v.name:lower() == low .. " seed" then seedId = id break end
                    end
                end
            end
            if not seedId then return nil, "seed '" .. rawSeed .. "' tidak ditemukan" end
        end
        if seedId and seedId % 2 == 0 and getSeedIdForBlock then
            seedId = getSeedIdForBlock(seedId) -- isi ID blok -> otomatis seed-nya
        end
        local door = parts[3] and (parts[3]:gsub("%s+", "")) or ""
        return { world = world, seedId = seedId, seedName = seedId and FL.itemName(seedId) or nil, door = door }
    end

    ------------------------------------------------------------------
    -- State file (1 tugas aktif)
    ------------------------------------------------------------------
    function FL.getStateFile()
        return getAccountFileName and getAccountFileName("sysgt_farmlogi_state", "json") or "sysgt_farmlogi_state.json"
    end

    function FL.saveState(st)
        if type(st) ~= "table" then return end
        st.active = true
        st.timestamp = os.time()
        FL.state = st
        if writefile then pcall(writefile, FL.getStateFile(), HttpService:JSONEncode(st)) end
    end

    function FL.clearState()
        FL.state = nil
        if writefile then pcall(writefile, FL.getStateFile(), HttpService:JSONEncode({ active = false })) end
    end

    function FL.readState()
        if FL.state and FL.state.active then return FL.state end
        if not (isfile and readfile) then return nil end
        local f = FL.getStateFile()
        local okE, ex = pcall(isfile, f)
        if not (okE and ex) then return nil end
        local ok, raw = pcall(readfile, f)
        if not ok or not raw or raw == "" then return nil end
        local okD, st = pcall(HttpService.JSONDecode, HttpService, raw)
        if not okD or type(st) ~= "table" or not st.active then return nil end
        -- format lama / basi (> 2 jam tanpa update) -> buang
        if not st.mode or (tonumber(st.timestamp) and (os.time() - st.timestamp) > 7200) then
            FL.clearState()
            return nil
        end
        FL.state = st
        return st
    end

    -- Dipanggil saat user STOP: hapus state hanya kalau milik mode ini
    function FL.clearTask(mode)
        local st = FL.readState()
        if st and st.mode == mode then
            FL.runToken = FL.runToken + 1
            FL.clearState()
        end
    end

    -- World yang seharusnya sedang kita injak untuk state ini
    function FL.targetWorldOf(st)
        if not st then return "" end
        if st.mode == "PLANT" then
            return cleanWorld(st.phase == "RESTOCK" and FL.plantStorage.world or st.world)
        elseif st.mode == "HARVEST" then
            return cleanWorld(st.phase == "DEPOSIT" and FL.harvestStorage.world or st.world)
        elseif st.mode == "MOVE" then
            local mv = st.move or {}
            return cleanWorld(st.phase == "DEST" and (mv.toWorld or M.toWorld) or (mv.fromWorld or M.fromWorld))
        end
        return ""
    end

    ------------------------------------------------------------------
    -- Gerak, drop, collect
    ------------------------------------------------------------------
    function FL.dropAt(itemId, count, x0, y0)
        count = math.floor(tonumber(count) or 0)
        if not itemId or count <= 0 then return 0 end
        local W, H = FL.worldSize()
        local standX, standY = x0, y0
        if AutoRotation and AutoRotation.getStorageStandPosition then
            standX, standY = AutoRotation.getStorageStandPosition(x0, y0)
        end
        local reached = walkOrPathfindTo and walkOrPathfindTo(standX, standY, W, H)
        if not reached and approachTile then approachTile(standX, standY, W, H) end
        task.wait(0.2)
        if standX ~= x0 then
            -- hadap ke titik drop (flags: 2 = grounded, +1 = hadap kanan)
            pcall(safeSendMove, { x = standX + 0.5, y = standY + 1.0, vx = 0, vy = 0, flags = 2 + ((standX < x0) and 1 or 0) })
        end
        task.wait(0.1)
        local dropped, left = 0, count
        while left > 0 do
            local n = math.min(left, MAX_STACK)
            if not sendDropPacket(itemId, n, x0 + 0.5, y0 + 0.5) then break end
            local inv = getNativeInventory and getNativeInventory()
            if inv and inv.remove then pcall(inv.remove, inv, itemId, n) end
            dropped = dropped + n
            left = left - n
            task.wait(0.35)
        end
        if AutoShop and AutoShop.syncInventory then pcall(AutoShop.syncInventory) end
        task.wait(1.2)
        return dropped
    end

    function FL.collectItem(itemId, maxCount)
        itemId = tonumber(itemId)
        if not itemId then return 0 end
        maxCount = maxCount or MAX_STACK
        for _ = 1, 3 do
            local before = getRealtimeItemCount(itemId)
            if before >= maxCount then break end
            if sweepTargetDropsRowByRow then sweepTargetDropsRowByRow(itemId, maxCount) end
            if getRealtimeItemCount(itemId) <= before then break end
        end
        return getRealtimeItemCount(itemId)
    end

    function FL.worldHasDrops(itemId)
        local w = getNativeWorld and getNativeWorld()
        local drops = (w and w.dropList and w.dropList()) or {}
        for _, d in ipairs(drops) do
            if d and d.id == itemId and (d.n or 0) > 0 then return true end
        end
        return false
    end

    -- Simpan state DULU, baru warp. Runner yang memanggil harus langsung `return`.
    function FL.warpWithState(st, world, door)
        world = cleanWorld(world)
        FL.saveState(st)
        FL.runToken = FL.runToken + 1
        if world == "" then return false end
        if hereIs(world) then
            task.defer(FL.checkResume) -- sudah di sana, lanjut langsung
            return true
        end
        FL.lastWarpAt = os.clock()
        task.wait(0.3)
        warpToWorld(world, (door and door ~= "") and door or nil)
        -- Watchdog: 40 dtk belum sampai (warp ditolak/gagal) -> coba sekali lagi
        local myToken = FL.runToken
        task.delay(40, function()
            if FL.runToken == myToken and FL.readState() and not hereIs(world) and not FL.busyResuming then
                print("[FARM-LOGI] Warp ke " .. world .. " belum sampai, mencoba lagi...")
                FL.lastWarpAt = os.clock()
                warpToWorld(world, (door and door ~= "") and door or nil)
            end
        end)
        return true
    end

    ------------------------------------------------------------------
    -- Runner helpers
    ------------------------------------------------------------------
    local function makeAlive(token, flagTbl)
        return function() return FL.runToken == token and flagTbl.active == true end
    end

    local function setPlantStatus(s)
        AutoPlant.status = s
        if updatePlantUI then pcall(updatePlantUI) end
    end
    local function setHarvestStatus(s)
        AutoHarvest.status = s
        if updateHarvestUI then pcall(updateHarvestUI) end
    end
    local function moveStatus(s)
        M.status = s
        if updateMoveUI then pcall(updateMoveUI) end
    end

    local function waitPlayable(alive)
        while alive() and ((isWorldPickerOpen and isWorldPickerOpen()) or (AntiStaff and AntiStaff.isFrozen)) do
            task.wait(1)
        end
        return alive()
    end

    local function fixIdx(st, list)
        if #list > 0 then
            st.idx = tonumber(st.idx) or 1
            if st.idx < 1 or st.idx > #list then st.idx = 1 end
        end
    end

    -- Pindah ke world berikutnya di list. Setelah satu putaran penuh, jeda WRAP_IDLE detik.
    local function nextWorld(st, list, setStatus)
        if #list == 0 then return false end
        st.idx = (tonumber(st.idx) or 1) + 1
        if st.idx > #list then
            st.idx = 1
            st.loops = (tonumber(st.loops) or 0) + 1
            st.idleUntil = os.time() + WRAP_IDLE
        end
        local e = list[st.idx]
        st.world, st.door = e.world, e.door
        setStatus(string.format("World #%d/%d -> warp ke [%s]...", st.idx, #list, e.world))
        return FL.warpWithState(st, e.world, e.door)
    end

    local function idleWait(st, alive, setStatus, what)
        while alive() and st.idleUntil and os.time() < st.idleUntil do
            setStatus(string.format("Semua world sudah %s. Putaran ke-%d dalam %d dtk...", what, (tonumber(st.loops) or 0) + 1, st.idleUntil - os.time()))
            task.wait(1)
        end
        st.idleUntil = nil
        return alive()
    end

    ------------------------------------------------------------------
    -- PLANT
    ------------------------------------------------------------------
    local function plantSeedFor(st)
        local list = FL.plantWorlds
        local e = (#list > 0) and list[tonumber(st.idx) or 1] or nil
        return tonumber((e and e.seedId) or st.seedId or AutoPlant.selectedSeedId)
    end

    local function runPlant(st, token)
        local alive = makeAlive(token, AutoPlant)
        local list = FL.plantWorlds
        fixIdx(st, list)
        ensureMobilityHooks()
        if not waitPlayable(alive) then return end

        -- RESTOCK: di world storage, ambil seed lalu balik ke world farm
        if st.phase == "RESTOCK" then
            local ps = FL.plantStorage
            if not hereIs(ps.world) then return FL.warpWithState(st, ps.world, ps.door) end
            local seedId = tonumber(st.seedId) or plantSeedFor(st)
            setPlantStatus(string.format("[STORAGE %s] Ambil seed %s...", ps.world, FL.itemName(seedId)))
            local got = FL.collectItem(seedId, MAX_STACK)
            if not alive() then return end
            if got <= 0 then
                st.emptySeeds = st.emptySeeds or {}
                st.emptySeeds[tostring(seedId)] = os.time()
                FL.notify(string.format("`4[Auto Plant] Seed %s habis di storage %s!``", FL.itemName(seedId), ps.world))
            end
            st.phase = "WORK"
            setPlantStatus(string.format("Seed: %d. Balik ke farm [%s]...", got, st.world or "?"))
            return FL.warpWithState(st, st.world, st.door)
        end

        -- WORK: pastikan di world farm
        if st.world and st.world ~= "" and not hereIs(st.world) then
            return FL.warpWithState(st, st.world, st.door)
        end
        st.world = FL.currentWorld()
        local W, H = FL.worldSize()

        while alive() do
            if not waitPlayable(alive) then return end
            if not idleWait(st, alive, setPlantStatus, "tertanam") then return end

            local seedId = plantSeedFor(st)
            if not seedId then seedId = getActiveSeed() end -- tanpa pilihan: bibit apapun di tas
            local seedName = seedId and FL.itemName(seedId) or "Bibit"
            local stock = seedId and getRealtimeItemCount(seedId) or 0

            local rowList, rowsWithSpots = scanPlantableRows(W, H)
            if #rowList == 0 then
                setPlantStatus(string.format("[%s] Semua tanah sudah tertanam", st.world))
                if #list > 0 then return nextWorld(st, list, setPlantStatus) end
                task.wait(2)
                continue
            end

            if stock <= 0 then
                local ps = FL.plantStorage
                local emptyAt = st.emptySeeds and seedId and st.emptySeeds[tostring(seedId)]
                local storageEmpty = emptyAt and (os.time() - emptyAt) < SEED_EMPTY_COOLDOWN
                if ps.enabled and ps.world ~= "" and seedId and not storageEmpty then
                    st.seedId = seedId
                    st.phase = "RESTOCK"
                    setPlantStatus(string.format("Seed %s habis -> ambil di storage [%s]...", seedName, ps.world))
                    if hereIs(ps.world) then
                        FL.saveState(st)
                        return runPlant(st, token) -- storage di world yang sama
                    end
                    return FL.warpWithState(st, ps.world, ps.door)
                end
                if #list > 0 then
                    setPlantStatus(string.format("[!] Seed %s habis, lanjut world berikutnya", seedName))
                    return nextWorld(st, list, setPlantStatus)
                end
                setPlantStatus(string.format("[!] Habis stock bibit [%s]! Auto Plant dihentikan.", seedName))
                FL.notify("`4[Auto Plant] " .. AutoPlant.status .. "``")
                stopAutoPlant()
                return
            end
            AutoPlant.lastSeedId, AutoPlant.lastSeedName = seedId, seedName

            for rowIndex, rY in ipairs(rowList) do
                if not alive() then return end
                local spots = rowsWithSpots[rY]
                local ltr = (rowIndex % 2 == 1)
                table.sort(spots, function(a, b) if ltr then return a.x < b.x else return a.x > b.x end end)
                for _, spot in ipairs(spots) do
                    if not alive() then return end
                    if getRealtimeItemCount(seedId) <= 0 then break end
                    if getRealtimeTile("fg", spot.x, spot.y) == 0 then
                        setPlantStatus(string.format("[%s] Tanam %s Y:%d X:%d (Stock: %d)", st.world, seedName, spot.y, spot.x, getRealtimeItemCount(seedId)))
                        if approachTile(spot.x, spot.y, W, H) and alive() and getRealtimeTile("fg", spot.x, spot.y) == 0 then
                            sendActPacket(ACT_KIND.PLANT, spot.x, spot.y)
                            sendTilePacket("fg", spot.x, spot.y, seedId, false)
                            forceClientTileUpdate("fg", spot.x, spot.y, seedId)
                            AutoPlant.totalPlanted = (AutoPlant.totalPlanted or 0) + 1
                            task.wait(0.18)
                        end
                    end
                end
                if getRealtimeItemCount(seedId) <= 0 then break end
            end
            FL.saveState(st)
            task.wait(0.1)
        end
    end

    ------------------------------------------------------------------
    -- HARVEST
    ------------------------------------------------------------------
    local function harvestSeedFor(st)
        local list = FL.harvestWorlds
        local e = (#list > 0) and list[tonumber(st.idx) or 1] or nil
        return e and tonumber(e.seedId) or nil -- nil = semua pohon matang
    end

    local function runHarvest(st, token)
        local alive = makeAlive(token, AutoHarvest)
        local list = FL.harvestWorlds
        local hs = FL.harvestStorage
        fixIdx(st, list)
        ensureMobilityHooks()
        if not waitPlayable(alive) then return end

        st.items = st.items or {}
        local storageOk = hs.enabled and hs.world ~= "" and hs.x and hs.y
        local thr = math.clamp(tonumber(hs.threshold) or 180, 1, MAX_STACK)
        local collectCap = storageOk and thr or MAX_STACK
        local function noteItem(id)
            id = tonumber(id)
            if id and id > 0 and not table.find(st.items, tostring(id)) then table.insert(st.items, tostring(id)) end
        end
        local function carried()
            local total, full = 0, false
            for _, s in ipairs(st.items) do
                local n = getRealtimeItemCount(tonumber(s))
                total = total + n
                if n >= thr then full = true end
            end
            return total, full
        end
        local function collectAll()
            for _, s in ipairs(st.items) do
                if not alive() then return end
                local id = tonumber(s)
                if id and getRealtimeItemCount(id) < collectCap and FL.worldHasDrops(id) then
                    FL.collectItem(id, collectCap)
                end
            end
        end

        -- DEPOSIT: di world storage, drop semua hasil panen lalu balik
        if st.phase == "DEPOSIT" then
            if not hereIs(hs.world) then return FL.warpWithState(st, hs.world, hs.door) end
            for _, s in ipairs(st.items) do
                if not alive() then return end
                local id = tonumber(s)
                local n = id and getRealtimeItemCount(id) or 0
                if n > 0 then
                    setHarvestStatus(string.format("[STORAGE %s] Setor %d %s...", hs.world, n, FL.itemName(id)))
                    FL.dropAt(id, n, hs.x - 1, hs.y - 1)
                    task.wait(1.5)
                end
            end
            if not alive() then return end
            st.items = {}
            st.phase = "WORK"
            setHarvestStatus(string.format("Setor selesai, balik ke [%s]...", st.world or "?"))
            return FL.warpWithState(st, st.world, st.door)
        end

        if st.world and st.world ~= "" and not hereIs(st.world) then
            return FL.warpWithState(st, st.world, st.door)
        end
        st.world = FL.currentWorld()
        local W, H = FL.worldSize()
        local seedFilter = harvestSeedFor(st)
        if seedFilter then
            noteItem(seedFilter)
            local db = ItemDB or (resolveItemDB and resolveItemDB())
            noteItem((db and db[seedFilter] and db[seedFilter].block) or (seedFilter - 1))
        end

        local function goDeposit(reason)
            st.phase = "DEPOSIT"
            setHarvestStatus(string.format("%s -> setor ke storage [%s]...", reason, hs.world))
            if hereIs(hs.world) then
                FL.saveState(st)
                return runHarvest(st, token)
            end
            return FL.warpWithState(st, hs.world, hs.door)
        end

        while alive() do
            if not waitPlayable(alive) then return end
            if not idleWait(st, alive, setHarvestStatus, "dipanen") then return end

            local ripe, total = {}, 0
            for _, t in ipairs(scanWorldTrees()) do
                if not seedFilter or t.seedId == seedFilter then
                    total = total + 1
                    if t.isRipe then ripe[#ripe + 1] = t end
                end
            end

            if #ripe == 0 then
                -- world ini beres: sapu sisa drop, setor kalau perlu, lalu world berikutnya
                collectAll()
                if not alive() then return end
                if storageOk then
                    local n, full = carried()
                    local endOfLoop = (#list == 0) or ((tonumber(st.idx) or 1) >= #list)
                    if full or (endOfLoop and n >= math.max(1, math.floor(thr * 0.25))) then
                        return goDeposit(full and "Tas penuh" or "Putaran selesai")
                    end
                end
                if #list > 0 then
                    setHarvestStatus(string.format("[%s] Tidak ada pohon matang (%d belum matang)", st.world, total))
                    return nextWorld(st, list, setHarvestStatus)
                end
                setHarvestStatus(string.format("Menunggu pohon matang (%d pohon belum ripe)", total))
                task.wait(1.5)
                continue
            end

            -- panen baris per baris (zigzag), atas ke bawah
            local rowMap, rowList = {}, {}
            for _, t in ipairs(ripe) do
                if not rowMap[t.y] then rowMap[t.y] = {}; table.insert(rowList, t.y) end
                table.insert(rowMap[t.y], t)
            end
            table.sort(rowList)
            local needDeposit = false
            for rowIndex, rY in ipairs(rowList) do
                if not alive() then return end
                local ltr = (rowIndex % 2 == 1)
                table.sort(rowMap[rY], function(a, b) if ltr then return a.x < b.x else return a.x > b.x end end)
                for _, target in ipairs(rowMap[rY]) do
                    if not alive() then return end
                    if getRealtimeTile("fg", target.x, target.y) ~= 0 then
                        -- verifikasi matang realtime sebelum mendekat (sama seperti Auto Harvest asli)
                        local nTrees, vTrees = getNativeTrees()
                        local key = target.y * W + target.x
                        local entry = nTrees and (nTrees[key] or nTrees[tostring(key)])
                        local vEntry = vTrees and (vTrees[key] or vTrees[tostring(key)])
                        local stillRipe = (vEntry and vEntry.ripe == true) or false
                        if not stillRipe and entry and entry.p and entry.p > 0 then
                            local g = (ItemDB and ItemDB[target.seedId] and ItemDB[target.seedId].grow) or 30
                            stillRipe = (workspace:GetServerTimeNow() - entry.p) >= g
                        end
                        if stillRipe then
                            setHarvestStatus(string.format("[%s] Panen %s Y:%d X:%d", st.world, target.name, target.y, target.x))
                            if approachTile(target.x, target.y, W, H) and alive() then
                                local cpx, cpy = getPlayerTilePos()
                                if cpx then
                                    safeSendMove({ x = cpx + 0.5, y = cpy + 1.0, vx = 0, vy = 0, flags = 2 + ((target.x >= cpx) and 1 or 0) })
                                end
                                sendActPacket(ACT_KIND.HIT, target.x, target.y)
                                task.wait(0.08)
                                sendTilePacket("fg", target.x, target.y, 0, false)
                                forceClientTileUpdate("fg", target.x, target.y, 0)
                                local wh = getNativeWorld and getNativeWorld()
                                if wh and wh.setTree then pcall(wh.setTree, target.x, target.y, nil) end
                                AutoHarvest.totalHarvested = (AutoHarvest.totalHarvested or 0) + 1
                                noteItem(target.seedId)
                                noteItem(target.fruitId)
                                if Magnet and Magnet.enabled then
                                    task.spawn(function() sweepDrops(Magnet.radius, Magnet.filterMode, 15) end)
                                end
                                task.wait(0.12)
                            end
                        end
                    end
                    if storageOk then
                        local _, full = carried()
                        if full then needDeposit = true break end
                    end
                end
                if needDeposit then break end
            end
            if not alive() then return end

            -- sapu hasil panen putaran ini
            collectAll()
            if not alive() then return end
            if storageOk then
                local _, full = carried()
                if needDeposit or full then return goDeposit("Tas penuh") end
            end
            FL.saveState(st)
            task.wait(0.1)
        end
    end

    ------------------------------------------------------------------
    -- MOVE WORLD -> WORLD
    ------------------------------------------------------------------
    function FL.moveConfigOk()
        return #M.itemIds > 0 and M.fromWorld ~= "" and M.toWorld ~= "" and M.toX and M.toY
            and cleanWorld(M.fromWorld) ~= cleanWorld(M.toWorld)
    end

    local function runMove(st, token)
        local alive = makeAlive(token, M)
        ensureMobilityHooks()
        M.totalMoved, M.trips = tonumber(st.totalMoved) or 0, tonumber(st.trips) or 0
        if not waitPlayable(alive) then return end

        if st.phase == "DEST" then
            if not hereIs(M.toWorld) then
                moveStatus(string.format("Warp ke tujuan [%s]...", M.toWorld))
                return FL.warpWithState(st, M.toWorld, M.toDoor)
            end
            local moved = 0
            M.busy = true
            for i, id in ipairs(M.itemIds) do
                if not alive() then M.busy = false return end
                local n = getRealtimeItemCount(id)
                if n > 0 then
                    moveStatus(string.format("[TUJUAN %s] Drop %d %s...", M.toWorld, n, M.itemNames[i] or ("#" .. id)))
                    moved = moved + FL.dropAt(id, n, M.toX - 1, M.toY - 1)
                    task.wait(1.5)
                end
            end
            M.busy = false
            if not alive() then return end
            local still = 0
            for _, id in ipairs(M.itemIds) do still = still + getRealtimeItemCount(id) end
            if moved <= 0 and still > 0 then
                FL.moveStop(string.format("[!] Gagal drop di %s (titik drop penuh/terblok?)", M.toWorld))
                FL.notify("`4[Move World] " .. M.status .. "``")
                return
            end
            M.totalMoved = M.totalMoved + moved
            M.trips = M.trips + 1
            st.totalMoved, st.trips = M.totalMoved, M.trips
            st.phase = "SOURCE"
            moveStatus(string.format("Trip %d selesai (%d item). Balik ke asal [%s]...", M.trips, M.totalMoved, M.fromWorld))
            return FL.warpWithState(st, M.fromWorld, M.fromDoor)
        end

        -- SOURCE: sapu semua item target
        if not hereIs(M.fromWorld) then
            moveStatus(string.format("Warp ke asal [%s]...", M.fromWorld))
            return FL.warpWithState(st, M.fromWorld, M.fromDoor)
        end
        local carried = 0
        M.busy = true
        for i, id in ipairs(M.itemIds) do
            if not alive() then M.busy = false return end
            moveStatus(string.format("[ASAL %s] Sapu %s...", M.fromWorld, M.itemNames[i] or ("#" .. id)))
            FL.collectItem(id, MAX_STACK)
            carried = carried + getRealtimeItemCount(id)
        end
        M.busy = false
        if not alive() then return end
        if carried <= 0 then
            local remaining = false
            for _, id in ipairs(M.itemIds) do
                if FL.worldHasDrops(id) then remaining = true break end
            end
            FL.moveStop(remaining and "[!] Tas penuh / drop tidak terjangkau, move dihentikan"
                or string.format("SELESAI: %d item dipindah dalam %d trip", M.totalMoved, M.trips))
            FL.notify(string.format("`2[Move World] %s``", M.status))
            return
        end
        st.phase = "DEST"
        moveStatus(string.format("Bawa %d item, warp ke tujuan [%s]...", carried, M.toWorld))
        return FL.warpWithState(st, M.toWorld, M.toDoor)
    end

    ------------------------------------------------------------------
    -- Dispatcher & resume
    ------------------------------------------------------------------
    local function restoreMoveFromState(st)
        local s = type(st.move) == "table" and st.move or {}
        M.itemIds = s.itemIds or M.itemIds
        M.itemNames = s.itemNames or M.itemNames
        M.fromWorld, M.fromDoor = s.fromWorld or M.fromWorld, s.fromDoor or M.fromDoor
        M.toWorld, M.toDoor = s.toWorld or M.toWorld, s.toDoor or M.toDoor
        M.toX, M.toY = tonumber(s.toX) or M.toX, tonumber(s.toY) or M.toY
    end

    function FL.runState(st)
        FL.restoreCfgFromState(st)
        local fn
        if st.mode == "PLANT" then
            AutoPlant.active = true
            fn = runPlant
        elseif st.mode == "HARVEST" then
            AutoHarvest.active = true
            fn = runHarvest
        elseif st.mode == "MOVE" then
            restoreMoveFromState(st)
            M.active = true
            fn = runMove
        else
            FL.clearState()
            return
        end
        FL.runToken = FL.runToken + 1
        local token = FL.runToken
        if FL.runnerThread then pcall(task.cancel, FL.runnerThread) end
        local th = task.spawn(function()
            local ok, err = pcall(fn, st, token)
            if not ok then warn("[FARM-LOGI] " .. tostring(st.mode) .. " error: " .. tostring(err)) end
        end)
        FL.runnerThread = th
        if st.mode == "PLANT" then AutoPlant.thread = th elseif st.mode == "HARVEST" then AutoHarvest.thread = th end
        if updatePlantUI then pcall(updatePlantUI) end
        if updateHarvestUI then pcall(updateHarvestUI) end
        if updateMoveUI then pcall(updateMoveUI) end
    end

    function FL.runnerAlive()
        return FL.runnerThread ~= nil and coroutine.status(FL.runnerThread) ~= "dead"
    end

    function FL.checkResume()
        if FL.busyResuming or FL.halted then return end
        if not FL.readState() then return end
        FL.busyResuming = true
        task.spawn(function()
            local ok, err = pcall(function()
                if not waitForWorldFullyLoaded(nil, 30) then return end
                -- baru saja warp & belum sampai: tunggu sampai di world target (maks 30 dtk)
                local st = FL.readState()
                local target = FL.targetWorldOf(st)
                while st and FL.lastWarpAt and (os.clock() - FL.lastWarpAt) < 30 and target ~= "" and not hereIs(target) do
                    task.wait(0.5)
                    st = FL.readState()
                end
                if st and not hereIs(target) and target ~= "" then
                    waitForWorldFullyLoaded(nil, 15)
                end
                task.wait(0.6)
                st = FL.readState() -- bisa saja sudah di-STOP user selama menunggu
                if not st then return end
                print(string.format("[FARM-LOGI] Lanjut tugas %s (phase %s) di world %s", tostring(st.mode), tostring(st.phase), FL.currentWorld()))
                FL.runState(st)
            end)
            if not ok then warn("[FARM-LOGI] resume error: " .. tostring(err)) end
            FL.busyResuming = false
        end)
    end

    -- Jaring pengaman (tiap 5 dtk): ada tugas tersimpan tapi tidak ada runner -> lanjutkan.
    -- Juga keluar dari World List / Lobby kalau nyangkut di sana.
    task.spawn(function()
        local pickerTicks = 0
        while not FL.halted do
            task.wait(5)
            if FL.halted then break end
            pcall(function()
                local st = FL.readState()
                if not st then pickerTicks = 0 return end
                if isWorldPickerOpen and isWorldPickerOpen() then
                    pickerTicks = pickerTicks + 1
                    local target = FL.targetWorldOf(st)
                    if pickerTicks >= 3 and target ~= "" and nativeJoinWorld then
                        pickerTicks = 0
                        print("[FARM-LOGI] Nyangkut di World List, join ke " .. target)
                        nativeJoinWorld(target)
                    end
                    return
                end
                pickerTicks = 0
                if FL.busyResuming or FL.runnerAlive() then return end
                if FL.lastWarpAt and (os.clock() - FL.lastWarpAt) < 30 then return end
                if FL.currentWorld() == "" then return end
                FL.checkResume()
            end)
        end
    end)

    ------------------------------------------------------------------
    -- Start dari tombol UI
    -- Setting (storage + list world) ikut disimpan di state supaya setelah reload di server
    -- baru tugas tidak bergantung pada config (yang bisa ditimpa versi script lain).
    ------------------------------------------------------------------
    local function snapList(list)
        local out = {}
        for _, e in ipairs(list) do
            out[#out + 1] = { world = e.world, seedId = e.seedId, seedName = e.seedName, door = e.door or "" }
        end
        return out
    end
    local function snapStorage(s)
        return { world = s.world, door = s.door, x = s.x, y = s.y, enabled = s.enabled, threshold = s.threshold }
    end
    function FL.restoreCfgFromState(st)
        local c = type(st) == "table" and st.cfg
        if type(c) ~= "table" then return end
        local function putStorage(dst, src)
            if type(src) ~= "table" then return end
            dst.world = cleanWorld(src.world)
            dst.door = tostring(src.door or "")
            dst.x, dst.y = tonumber(src.x), tonumber(src.y)
            dst.enabled = (src.enabled == true)
            if src.threshold ~= nil then dst.threshold = tonumber(src.threshold) or dst.threshold end
        end
        local function putList(dst, src)
            if type(src) ~= "table" then return end
            table.clear(dst) -- isi ulang tabel yang sama (UI memegang referensinya)
            for _, e in ipairs(src) do
                if type(e) == "table" and type(e.world) == "string" and e.world ~= "" then
                    local sid = tonumber(e.seedId)
                    table.insert(dst, { world = cleanWorld(e.world), seedId = sid, seedName = e.seedName or (sid and FL.itemName(sid)), door = tostring(e.door or "") })
                end
            end
        end
        putStorage(FL.plantStorage, c.plantStorage)
        putStorage(FL.harvestStorage, c.harvestStorage)
        putList(FL.plantWorlds, c.plantWorlds)
        putList(FL.harvestWorlds, c.harvestWorlds)
        if c.selectedSeedId ~= nil and AutoPlant then
            AutoPlant.selectedSeedId = tonumber(c.selectedSeedId)
            AutoPlant.selectedSeedName = c.selectedSeedName or AutoPlant.selectedSeedName
        end
    end

    local function freshState(mode, list)
        local st = { mode = mode, phase = "WORK", idx = 1, loops = 0 }
        if #list > 0 then
            local here = FL.currentWorld()
            for i, e in ipairs(list) do
                if e.world == here then st.idx = i break end -- mulai dari world list yang sedang diinjak
            end
            st.world, st.door = list[st.idx].world, list[st.idx].door
        else
            st.world = FL.currentWorld()
        end
        st.cfg = {
            plantStorage = snapStorage(FL.plantStorage),
            harvestStorage = snapStorage(FL.harvestStorage),
            plantWorlds = snapList(FL.plantWorlds),
            harvestWorlds = snapList(FL.harvestWorlds),
            selectedSeedId = AutoPlant and AutoPlant.selectedSeedId or nil,
            selectedSeedName = AutoPlant and AutoPlant.selectedSeedName or nil,
        }
        return st
    end

    function FL.startPlant()
        local st = freshState("PLANT", FL.plantWorlds)
        if #FL.plantWorlds == 0 then st.seedId = AutoPlant.selectedSeedId end
        FL.saveState(st)
        FL.runState(st)
    end

    function FL.startHarvest()
        local st = freshState("HARVEST", FL.harvestWorlds)
        FL.saveState(st)
        FL.runState(st)
    end

    function FL.moveStart()
        if M.active then return end
        if not FL.moveConfigOk() then
            moveStatus("[!] Lengkapi: item target, world asal, world tujuan + Set Pos Drop")
            return
        end
        if AutoPlant and AutoPlant.active then stopAutoPlant() end
        if AutoHarvest and AutoHarvest.active then stopAutoHarvest() end
        M.totalMoved, M.trips = 0, 0
        local st = {
            mode = "MOVE", phase = hereIs(M.toWorld) and "DEST" or "SOURCE", totalMoved = 0, trips = 0,
            move = {
                itemIds = M.itemIds, itemNames = M.itemNames,
                fromWorld = M.fromWorld, fromDoor = M.fromDoor,
                toWorld = M.toWorld, toDoor = M.toDoor, toX = M.toX, toY = M.toY,
            },
        }
        FL.saveState(st)
        FL.runState(st)
    end

    function FL.moveStop(reason)
        M.active, M.busy = false, false
        FL.clearTask("MOVE")
        moveStatus(reason or "Standby")
    end
end

-- ═══════════════════════════════════════
--  AUTO FACTORY ENGINE (Pabrik PnB & Farm Terpadu)
-- ═══════════════════════════════════════
local function factoryBreakBlock(tx, ty, blockId, customLayer)
    local layer = customLayer or ((ItemDB and ItemDB[blockId] and ItemDB[blockId].background == true) and "bg" or "fg")
    local cur = getRealtimeTile(layer, tx, ty)
    if not cur or cur == 0 then return true end

    local hits = (calculateBlockHits and calculateBlockHits(cur)) or (ItemDB and ItemDB[blockId] and ItemDB[blockId].hits) or 3
    if hits <= 0 then hits = 3 end
    local hitDelay = (PNB and PNB.hitDelay) or 0.18

    for i = 1, hits do
        if not AutoFactory.active then return false end
        if i > 1 and getRealtimeTile(layer, tx, ty) == 0 then break end
        sendActPacket(ACT_KIND.HIT, tx, ty)
        if i < hits then
            task.wait(hitDelay)
        end
    end

    task.wait(0.015)
    sendTilePacket(layer, tx, ty, 0, false)
    forceClientTileUpdate(layer, tx, ty, 0)
    return true
end

stopAutoFactory = function()
    if not AutoFactory.active then return end
    AutoFactory.active = false
    AutoFactory.busy = false
    if AutoFactory.thread then
        pcall(task.cancel, AutoFactory.thread)
        AutoFactory.thread = nil
    end
    AutoFactory.status = "Standby"
    print("[SYSHUB] Auto Factory dihentikan.")
    if updateFactoryUI then updateFactoryUI() end
end

startAutoFactory = function()
    if AutoFactory.active then return end

    -- Validasi Setup sebelum start: Auto-detect posBreak jika belum diset
    if not AutoFactory.posBreakX or not AutoFactory.posBreakY then
        local px, py = getPlayerTilePos()
        if px and py then
            AutoFactory.posBreakX = px + 1
            AutoFactory.posBreakY = py + 1
            if lblPosBreak and lblPosBreak.set then
                lblPosBreak:set(string.format("`2Pos Break: (%d, %d) [Auto]``", px + 1, py + 1))
            end
        else
            AutoFactory.status = "[!] Tentukan Pos Break terlebih dahulu!"
            if lblFactoryStatus and lblFactoryStatus.set then
                lblFactoryStatus:set("`4[!] Pos Break belum ditentukan! Klik 'Set Pos Break'``")
            end
            return
        end
    end

    if not AutoFactory.targetSeedId then
        AutoFactory.status = "[!] Pilih Seed target pabrik terlebih dahulu!"
        if lblFactoryStatus and lblFactoryStatus.set then
            lblFactoryStatus:set("`4[!] Pilih Seed target terlebih dahulu di dropdown!``")
        end
        return
    end

    -- Pastikan targetBlockId terisi
    if not AutoFactory.targetBlockId then
        local it = ItemDB and ItemDB[AutoFactory.targetSeedId]
        AutoFactory.targetBlockId = (it and it.block) or (AutoFactory.targetSeedId - 1)
        local bIt = ItemDB and ItemDB[AutoFactory.targetBlockId]
        AutoFactory.targetBlockName = (bIt and bIt.name) or ("Block #" .. tostring(AutoFactory.targetBlockId))
    end

    -- Hentikan automasi lain agar tidak bentrok
    if PNB and PNB.active and stopPNB then stopPNB() end
    if ClearWorld and ClearWorld.active and stopClearWorld then stopClearWorld() end
    if AutoBuildDF and AutoBuildDF.active and stopAutoBuildDF then stopAutoBuildDF() end
    if AutoPlant and AutoPlant.active and stopAutoPlant then stopAutoPlant() end
    if AutoHarvest and AutoHarvest.active and stopAutoHarvest then stopAutoHarvest() end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end

    AutoFactory.active = true
    AutoFactory.busy = false
    AutoFactory.status = "Memulai Auto Factory..."
    print("[SYSHUB] Auto Factory dimulai!")
    if updateFactoryUI then updateFactoryUI() end

    AutoFactory.thread = task.spawn(function()
        local worldW = 100
        local worldH = 60
        local w = getNativeWorld()
        if w and w.worldSize then
            worldW = w.worldSize.x or worldW
            worldH = w.worldSize.y or worldH
        end

        ensureMobilityHooks()

        while AutoFactory.active do
            local px, py = getPlayerTilePos()
            if not px or not py then
                task.wait(0.2)
                continue
            end

            local seedId = AutoFactory.targetSeedId
            local blockId = AutoFactory.targetBlockId
            local seedStock = getRealtimeItemCount(seedId)
            local blockStock = getRealtimeItemCount(blockId)

            -- Internal 0-based coordinates for movement & world engine (UI uses 1-based +1)
            local bX = AutoFactory.posBreakX and (AutoFactory.posBreakX - 1)
            local bY = AutoFactory.posBreakY and (AutoFactory.posBreakY - 1)
            local dX = AutoFactory.posDropX and (AutoFactory.posDropX - 1)
            local dY = AutoFactory.posDropY and (AutoFactory.posDropY - 1)

            if not bX or not bY then
                AutoFactory.status = "[!] Tentukan Pos Break terlebih dahulu!"
                if updateFactoryUI then updateFactoryUI() end
                task.wait(0.5)
                continue
            end

            local fieldStartX = bX
            local fieldEndX = math.min(worldW - 1, bX + AutoFactory.factoryLength)
            local fieldY = bY

            -- Scan spot kosong di baris pabrik yang siap ditanami
            local plantSpots = {}
            for tx = fieldStartX, fieldEndX do
                if tx >= 0 and tx < worldW then
                    local curFg = getRealtimeTile("fg", tx, fieldY)
                    if curFg == 0 and not isTileLocked(tx, fieldY) and not isSolidTile(tx, fieldY) then
                        local belowFg = getRealtimeTile("fg", tx, fieldY + 1)
                        if belowFg and belowFg > 0 and not isSeedOrTreeId(belowFg) then
                            table.insert(plantSpots, tx)
                        end
                    end
                end
            end

            -- ═════════════════════════════════════════
            --  PHASE 1: PLANT SEEDS (MODAL AWAL / PRIORITAS UTAMA)
            --  Tanam bibit dari tas ke seluruh spot kosong di area pabrik
            -- ═════════════════════════════════════════
            if seedStock > 0 and #plantSpots > 0 then
                AutoFactory.status = string.format("Phase 1: Tanam modal bibit (Stock: %d, Butuh: %d spot)...", seedStock, #plantSpots)
                if updateFactoryUI then updateFactoryUI() end

                for _, spotX in ipairs(plantSpots) do
                    if not AutoFactory.active then break end
                    if getRealtimeItemCount(seedId) <= 0 then break end

                    local curFg = getRealtimeTile("fg", spotX, fieldY)
                    if curFg == 0 then
                        local curPx, curPy = getPlayerTilePos()
                        if curPx and (math.abs(curPx - spotX) > 2 or curPy ~= fieldY) then
                            approachTile(spotX, fieldY, worldW, worldH)
                        else
                            stepToColumn(spotX, fieldY)
                        end

                        if not AutoFactory.active then break end

                        curFg = getRealtimeTile("fg", spotX, fieldY)
                        if curFg == 0 then
                            sendActPacket(ACT_KIND.PLANT, spotX, fieldY)
                            sendTilePacket("fg", spotX, fieldY, seedId, false)
                            forceClientTileUpdate("fg", spotX, fieldY, seedId)
                            AutoFactory.totalPlanted = AutoFactory.totalPlanted + 1
                            if updateFactoryUI then updateFactoryUI() end
                            task.wait(0.18) -- Delay tanam factory dinaikkan
                        end
                    end
                end

                task.wait(0.04)
                continue
            end

            -- Refresh stok bibit setelah proses tanam selesai
            seedStock = getRealtimeItemCount(seedId)

            -- ═════════════════════════════════════════
            --  PHASE 2: DROP PROFIT CHECK
            --  HANYA berjalan jika lahan pabrik sudah penuh (#plantSpots == 0)!
            --  Sisa bibit di tas setelah lahan penuh dihitung sebagai MURNI PROFIT.
            -- ═════════════════════════════════════════
            if #plantSpots == 0 and seedStock >= AutoFactory.profitLimit then
                if dX and dY then
                    AutoFactory.status = string.format("Phase 2: Buang profit %d seed ke samping Pos Drop (%d, %d)...",
                        AutoFactory.profitLimit, AutoFactory.posDropX, AutoFactory.posDropY)
                    if updateFactoryUI then updateFactoryUI() end

                    walkOrPathfindTo(dX, dY, worldW, worldH)
                    task.wait(0.08)

                    local curPx, curPy, curRawX, curRawY = getPlayerTilePos()
                    -- Tepat di sebelah kanan pos drop dan di atas permukaan block solid (bukan di dalam block)
                    local dropX = (curRawX and (curRawX + 0.85)) or (dX + 1.35)
                    local dropY = (curRawY and (curRawY - 0.45)) or (dY + 0.55)
                    local dropAmt = AutoFactory.profitLimit

                    sendDropPacket(seedId, dropAmt, dropX, dropY)
                    local inv = getNativeInventory()
                    if inv and inv.remove then
                        pcall(inv.remove, inv, seedId, dropAmt)
                    end
                    if Sfx and Sfx.play then pcall(Sfx.play, "object_spawn2") end

                    AutoFactory.totalProfitDropped = (AutoFactory.totalProfitDropped or 0) + (tonumber(dropAmt) or 0)
                    if updateFactoryUI then updateFactoryUI() end
                    task.wait(0.08)

                    -- Kembali ke Pos Break
                    walkOrPathfindTo(bX, bY, worldW, worldH)
                    task.wait(0.05)
                    continue
                else
                    AutoFactory.status = "[!] Pos Drop belum diset! Melewati drop profit..."
                    if updateFactoryUI then updateFactoryUI() end
                    task.wait(0.1)
                end
            end

            -- ═════════════════════════════════════════
            --  PHASE 3: PNB BLOCKS
            -- ═════════════════════════════════════════
            blockStock = getRealtimeItemCount(blockId)
            if (seedStock == 0 or #plantSpots == 0) and blockStock > 0 then
                -- Karakter harus berdiri tepat di posBreak (bX, bY)
                local curPx, curPy = getPlayerTilePos()
                if not curPx or curPx ~= bX or curPy ~= bY then
                    AutoFactory.status = string.format("Phase 3: Menuju Pos Break (%d, %d)...", AutoFactory.posBreakX, AutoFactory.posBreakY)
                    if updateFactoryUI then updateFactoryUI() end
                    walkOrPathfindTo(bX, bY, worldW, worldH)
                    task.wait(0.05)
                end

                local targetX = bX
                local targetY = bY - 1 -- Tepat 1 tile di atas kepala
                if bY <= 0 or isSolidTile(bX, bY - 1) then
                    -- Jika berdiri di baris teratas (y=0) atau di atas kepala terhalang solid: break di samping!
                    targetX = (bX <= 10) and ((bX > 0) and (bX - 1) or 1) or ((bX < worldW - 1) and (bX + 1) or (bX - 1))
                    targetY = bY
                end

                AutoFactory.status = string.format("Phase 3: PnB [%s] (Sisa: %d)...", AutoFactory.targetBlockName, blockStock)
                if updateFactoryUI then updateFactoryUI() end

                local facLayer = (ItemDB and ItemDB[blockId] and ItemDB[blockId].background == true) and "bg" or "fg"
                while AutoFactory.active and getRealtimeItemCount(blockId) > 0 do
                    -- 0. Set facing direction ke arah tile break
                    local px, py, rawX, rawY = getPlayerTilePos()
                    if safeSendMove and px and py then
                        local facingBit = (targetX < bX) and 0 or ((targetX > bX) and 1 or ((bX <= 10) and 0 or 1))
                        safeSendMove({
                            x = (rawX or (bX + 0.5)),
                            y = (rawY or (bY + 1.0)),
                            vx = 0,
                            vy = 0,
                            flags = 2 + facingBit
                        })
                    end

                    -- 1. Place Block jika kosong
                    local curTile = getRealtimeTile(facLayer, targetX, targetY)
                    if curTile == 0 then
                        sendActPacket(ACT_KIND.BUILD, targetX, targetY)
                        sendTilePacket(facLayer, targetX, targetY, blockId, false)
                        forceClientTileUpdate(facLayer, targetX, targetY, blockId)
                        local inv = getNativeInventory and getNativeInventory()
                        if inv and inv.remove then
                            pcall(inv.remove, inv, blockId, 1)
                        end
                        if refreshInventory then task.spawn(refreshInventory) end
                        task.wait(0.15)
                    end

                    -- 2. Break Block
                    curTile = getRealtimeTile(facLayer, targetX, targetY)
                    if curTile and curTile ~= 0 then
                        factoryBreakBlock(targetX, targetY, blockId, facLayer)
                        AutoFactory.totalPnB = AutoFactory.totalPnB + 1
                        if updateFactoryUI then updateFactoryUI() end
                        task.wait(0.02)
                    end

                    -- 3. Collect Drops di tile break
                    collectDropsAtTiles({{ x = targetX, y = targetY }}, bX, bY, bX + 0.5, bY + 1.0)

                    -- Cek apakah profit seed sudah mencapai limit saat PnB
                    if getRealtimeItemCount(seedId) >= AutoFactory.profitLimit then
                        break
                    end
                    task.wait(0.02)
                end

                task.wait(0.04)
                continue
            end

            -- ═════════════════════════════════════════
            --  PHASE 4: HARVEST TREES
            -- ═════════════════════════════════════════
            blockStock = getRealtimeItemCount(blockId)
            seedStock = getRealtimeItemCount(seedId)

            if blockStock == 0 and (seedStock == 0 or #plantSpots == 0) then
                local allTrees = scanWorldTrees()
                local ripeTrees = {}
                local unreadyTrees = 0

                for _, t in ipairs(allTrees) do
                    if t.y == fieldY and t.x >= fieldStartX and t.x <= fieldEndX then
                        if not AutoFactory.targetSeedId or t.seedId == AutoFactory.targetSeedId then
                            if t.isRipe then
                                table.insert(ripeTrees, t)
                            else
                                unreadyTrees = unreadyTrees + 1
                            end
                        end
                    end
                end

                if #ripeTrees > 0 then
                    AutoFactory.status = string.format("Phase 4: Memanen %d pohon matang...", #ripeTrees)
                    if updateFactoryUI then updateFactoryUI() end

                    table.sort(ripeTrees, function(a, b) return a.x < b.x end)

                    for _, tree in ipairs(ripeTrees) do
                        if not AutoFactory.active then break end

                        local curFg = getRealtimeTile("fg", tree.x, tree.y)
                        if curFg ~= 0 then
                            -- Dekati pohon
                            approachTile(tree.x, tree.y, worldW, worldH)
                            if not AutoFactory.active then break end

                            -- Pukul / Harvest
                            sendActPacket(ACT_KIND.HIT, tree.x, tree.y)
                            task.wait(0.08) -- Delay hit panen dinaikkan
                            sendTilePacket("fg", tree.x, tree.y, 0, false)
                            forceClientTileUpdate("fg", tree.x, tree.y, 0)
                            local w_fh = getNativeWorld and getNativeWorld()
                            if w_fh and w_fh.setTree then
                                pcall(w_fh.setTree, tree.x, tree.y, nil)
                            end
                            AutoFactory.totalHarvested = AutoFactory.totalHarvested + 1
                            if updateFactoryUI then updateFactoryUI() end

                            -- Ambil drop seed & buah
                            collectDropsAtTiles({{ x = tree.x, y = tree.y }}, tree.x, tree.y, tree.x + 0.5, tree.y + 1.0)
                            task.wait(0.12) -- Delay jeda panen dinaikkan
                        end
                    end

                    task.wait(0.04)
                    continue
                end

                -- ═════════════════════════════════════════
                --  PHASE 5: STANDBY / WAIT
                -- ═════════════════════════════════════════
                local curPx, curPy = getPlayerTilePos()
                if not curPx or curPx ~= bX or curPy ~= bY then
                    walkOrPathfindTo(bX, bY, worldW, worldH)
                    task.wait(0.05)
                end

                AutoFactory.status = string.format("Waiting for trees to ripen... (%d pohon belum matang)", unreadyTrees)
                if updateFactoryUI then updateFactoryUI() end
                task.wait(1.5)
            end
        end
    end)
end

-- ═══════════════════════════════════════
--  AUTO ROTATION ENGINE (Multi-World Full-World Farm Rotation)
-- ═══════════════════════════════════════
stopAutoRotation = function()
    AutoRotation.active = false
    AutoRotation.busy = false
    if AutoRotation.thread then
        pcall(task.cancel, AutoRotation.thread)
        AutoRotation.thread = nil
    end
    if AutoRotation.clearState then AutoRotation.clearState() end
    AutoRotation.status = "Standby"
    print("[SYSHUB] Auto Rotation dihentikan.")
    if updateRotationUI then updateRotationUI() end
end
AutoRotation.stop = stopAutoRotation

startAutoRotation = function()
    if AutoRotation.thread and coroutine.status(AutoRotation.thread) ~= "dead" then
        return
    end

    if #AutoRotation.worlds == 0 then
        AutoRotation.status = "[!] Daftar World Farm kosong! Tambahkan minimal 1 world."
        if lblRotationStatus and lblRotationStatus.set then
            lblRotationStatus:set("`4[!] Daftar World Farm kosong! Masukkan NAMEWORLD|IDSEED di inputbox.``")
        end
        return
    end

    -- Hentikan automasi lain agar tidak bentrok
    if PNB and PNB.active and stopPNB then stopPNB() end
    if ClearWorld and ClearWorld.active and stopClearWorld then stopClearWorld() end
    if AutoBuildDF and AutoBuildDF.active and stopAutoBuildDF then stopAutoBuildDF() end
    if AutoPlant and AutoPlant.active and stopAutoPlant then stopAutoPlant() end
    if AutoHarvest and AutoHarvest.active and stopAutoHarvest then stopAutoHarvest() end
    if AutoFactory and AutoFactory.active and stopAutoFactory then stopAutoFactory() end

    AutoRotation.active = true
    AutoRotation.busy = false
    AutoRotation.status = "Memulai Auto Rotation..."
    print("[SYSHUB] Auto Rotation dimulai!")
    if AutoRotation.saveState then
        AutoRotation.saveState({ subtask = "ROTATION_LOOP", currentWorldIndex = AutoRotation.currentWorldIndex })
    end
    if updateRotationUI then updateRotationUI() end

    AutoRotation.start = startAutoRotation
    AutoRotation.thread = task.spawn(function()
        ensureMobilityHooks()

        while AutoRotation.active do
            -- JIKA SEDANG DI WORLD LIST / LOBBY, JANGAN COBA BERGERAK ATAU MENJALANKAN TASK!
            while AutoRotation.active and (isWorldPickerOpen and isWorldPickerOpen()) do
                AutoRotation.status = "[STANDBY] Berada di World List / Lobby..."
                if updateRotationUI then updateRotationUI() end
                task.wait(1.0)
            end
            if not AutoRotation.active then break end

            while AutoRotation.active and AntiStaff and AntiStaff.isFrozen do
                AutoRotation.status = "[ANTI-STAFF] Freeze: Staff di world!"
                if updateRotationUI then updateRotationUI() end
                task.wait(1)
            end
            if not AutoRotation.active then break end

            local numWorlds = #AutoRotation.worlds
            if numWorlds == 0 then
                AutoRotation.status = "[!] Daftar World Farm kosong! Standby."
                if updateRotationUI then updateRotationUI() end
                task.wait(1.5)
                continue
            end

            if AutoRotation.currentWorldIndex > numWorlds or AutoRotation.currentWorldIndex < 1 then
                AutoRotation.currentWorldIndex = 1
            end

            local curEntry = AutoRotation.worlds[AutoRotation.currentWorldIndex]
            if not curEntry then
                AutoRotation.currentWorldIndex = 1
                task.wait(0.5)
                continue
            end

            local targetWorldName = string.upper((curEntry.worldName or ""):gsub("%s+", ""))
            local targetSeedId = tonumber(curEntry.seedId) or 3
            local seedItem = ItemDB and ItemDB[targetSeedId]
            local targetBlockId = (findBlockForSeed and findBlockForSeed(targetSeedId)) or (targetSeedId - 1)
            AutoRotation.targetBlockId = targetBlockId
            AutoRotation.targetSeedId = targetSeedId
            local seedName = (seedItem and seedItem.name) or ("Seed #" .. tostring(targetSeedId))
            local blockName = (ItemDB and ItemDB[targetBlockId] and ItemDB[targetBlockId].name) or ("Block #" .. tostring(targetBlockId))

            -- 1. Warp ke target world farm jika belum berada di dalamnya
            local curNativeW = getNativeWorld and getNativeWorld()
            local curWorldName = curNativeW and curNativeW.name and string.upper(curNativeW.name) or ""

            if curWorldName ~= targetWorldName then
                AutoRotation.status = string.format("Warping ke World [%s] (Queue %d/%d)...", targetWorldName, AutoRotation.currentWorldIndex, numWorlds)
                if updateRotationUI then updateRotationUI() end

                if AutoRotation.saveState then
                    AutoRotation.saveState({
                        subtask = "ROTATION_LOOP",
                        currentWorldIndex = AutoRotation.currentWorldIndex,
                        farmWorld = targetWorldName,
                        farmDoor = curEntry.door
                    })
                end
                warpToWorld(targetWorldName, curEntry.door)
                return
            end

            -- Update referensi world setelah tiba
            local w = getNativeWorld and getNativeWorld()
            local worldW = (w and w.w) or 100
            local worldH = (w and w.h) or 60

            -- 2. Cek Pohon Matang (Ripe Trees) di world ini
            local allTrees = scanWorldTrees and scanWorldTrees() or {}
            local ripeTrees = {}
            local unreadyTrees = 0
            local minTimeLeft = 999999
            local serverNow = workspace:GetServerTimeNow()
            local nativeTrees = getNativeTrees and getNativeTrees()

            for _, t in ipairs(allTrees) do
                if t.seedId == targetSeedId or t.fruitId == targetBlockId then
                    if t.isRipe then
                        table.insert(ripeTrees, t)
                    else
                        unreadyTrees = unreadyTrees + 1
                        if nativeTrees then
                            local numKey = t.y * worldW + t.x
                            local entry = nativeTrees[numKey] or nativeTrees[tostring(numKey)]
                            if entry and entry.p and entry.p > 0 then
                                local gTime = (ItemDB and ItemDB[targetSeedId] and ItemDB[targetSeedId].grow) or 30
                                local elapsed = serverNow - entry.p
                                local rem = math.max(0, gTime - elapsed)
                                if rem < minTimeLeft then minTimeLeft = rem end
                            end
                        end
                    end
                end
            end

            curEntry.ripeCount = #ripeTrees
            curEntry.unreadyCount = unreadyTrees

            -- JIKA TIDAK ADA POHON RIPE DAN TAS TIDAK MEMILIKI BLOK MAUPUN SEED:
            local initBlockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
            local initSeedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0

            local function checkWorldTargetDrops()
                local w_chk = getNativeWorld and getNativeWorld()
                if not w_chk or not w_chk.dropList then return false end
                local drops = w_chk.dropList()
                if not drops then return false end
                for _, d in ipairs(drops) do
                    if d and d.uid and not d.taking and d.n and d.n > 0 then
                        if d.id == targetBlockId or d.id == targetSeedId then
                            return true
                        end
                    end
                end
                return false
            end

            -- Cek apakah lahan tanam sudah penuh (Full World)
            local earlyPlantRows = scanPlantableRows and scanPlantableRows(worldW, worldH) or {}
            local isWorldFullOfTrees = (#earlyPlantRows == 0)

            -- Sapu sisa droppan jika blok kosong dan masih ada tempat tanam / butuh bahan
            if initBlockStock <= 0 and (initSeedStock <= 0 or not isWorldFullOfTrees) and checkWorldTargetDrops() then
                AutoRotation.status = string.format("[%s] Tas kosong tapi ada droppan target, menyapu droppan...", targetWorldName)
                if updateRotationUI then updateRotationUI() end
                if sweepTargetDropsRowByRow then
                    sweepTargetDropsRowByRow(targetBlockId, 180)
                    sweepTargetDropsRowByRow(targetSeedId, 180)
                end
                initBlockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
                initSeedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
            end

            -- KONDISI PINDAH: Pohon ready = 0, Blok di tas = 0, dan (Lahan SUDAH FULL atau Bibit di tas habis)
            local canPlantMore = (not isWorldFullOfTrees) and (initSeedStock > 0)
            if #ripeTrees == 0 and initBlockStock <= 0 and not canPlantMore then
                local growDur = (ItemDB and ItemDB[targetSeedId] and ItemDB[targetSeedId].grow) or 30
                local remSec = (minTimeLeft < 999999) and minTimeLeft or growDur
                curEntry.countdownEndsAt = os.clock() + remSec

                if numWorlds > 1 then
                    AutoRotation.status = string.format("[%s] World selesai (Pohon unready & lahan penuh)! Pindah...", targetWorldName)
                    if updateRotationUI then updateRotationUI() end
                    task.wait(0.8)
                    AutoRotation.currentWorldIndex = AutoRotation.currentWorldIndex + 1
                    if AutoRotation.currentWorldIndex > numWorlds then
                        AutoRotation.currentWorldIndex = 1
                    end
                    local nextEntry = AutoRotation.worlds[AutoRotation.currentWorldIndex]
                    local nextWorld = nextEntry and string.upper((nextEntry.worldName or ""):gsub("%s+", "")) or ""
                    local nextDoor = nextEntry and nextEntry.door or ""
                    if AutoRotation.saveState then
                        AutoRotation.saveState({
                            subtask = "ROTATION_LOOP",
                            currentWorldIndex = AutoRotation.currentWorldIndex,
                            farmWorld = nextWorld,
                            farmDoor = nextDoor
                        })
                    end
                    if nextWorld ~= "" and nextWorld ~= targetWorldName then
                        AutoRotation.status = string.format("Warp ke World berikutnya [%s] (Queue %d/%d)...", nextWorld, AutoRotation.currentWorldIndex, numWorlds)
                        if updateRotationUI then updateRotationUI() end
                        warpToWorld(nextWorld, nextDoor)
                        return
                    end
                    continue
                else
                    AutoRotation.status = string.format("[%s] Menunggu pohon matang (~%ds)...", targetWorldName, math.floor(remSec))
                    if updateRotationUI then updateRotationUI() end
                    task.wait(2.0)
                    continue
                end
            end

            -- 3. JIKA ADA POHON RIPE ATAU ADA BAHAN: JALANKAN SIKLUS FARM ROTASI (PRIORITAS BREAK!)

            -- =========================================================================
            -- STEP 1: PLANT SEEDS (jika ada seed di tas & ada tanah kosong sebelum break)
            -- =========================================================================
            local seedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
            if seedStock > 0 then
                local rowList, rowsWithSpots = scanPlantableRows(worldW, worldH)
                if #rowList > 0 then
                    AutoRotation.status = string.format("[%s] Menanam bibit %s...", targetWorldName, seedName)
                    if updateRotationUI then updateRotationUI() end
                    for rowIndex, rY in ipairs(rowList) do
                        if not AutoRotation.active or ((getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0) <= 0 then break end
                        local spots = rowsWithSpots[rY] or {}
                        if #spots > 0 then
                            -- ZIGZAG BOUSTROPHEDON (Persis Tab Farm):
                            -- Baris 1: Kiri ke Kanan -> Baris 2: Kanan ke Kiri -> Baris 3: Kiri ke Kanan ...
                            local isLeftToRight = (rowIndex % 2 == 1)
                            table.sort(spots, function(a, b)
                                if isLeftToRight then
                                    return a.x < b.x
                                else
                                    return a.x > b.x
                                end
                            end)

                            for _, spot in ipairs(spots) do
                                if not AutoRotation.active or ((getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0) <= 0 then break end
                                if getRealtimeTile("fg", spot.x, spot.y) == 0 then
                                    local reached = approachTile(spot.x, spot.y, worldW, worldH)
                                    if reached and getRealtimeTile("fg", spot.x, spot.y) == 0 then
                                        sendActPacket(ACT_KIND.PLANT, spot.x, spot.y)
                                        sendTilePacket("fg", spot.x, spot.y, targetSeedId, false)
                                        forceClientTileUpdate("fg", spot.x, spot.y, targetSeedId)
                                        local inv = getNativeInventory and getNativeInventory()
                                        if inv and inv.remove then
                                            pcall(inv.remove, inv, targetSeedId, 1)
                                        end
                                        if refreshInventory then task.spawn(refreshInventory) end
                                        AutoRotation.totalPlanted = AutoRotation.totalPlanted + 1
                                        if updateRotationUI then updateRotationUI() end
                                        task.wait(0.18) -- Delay tanam rotasi dinaikkan
                                    end
                                end
                            end
                        end
                    end
                    curEntry.lastPlantedTime = os.clock()
                end
            end

            -- =========================================================================
            -- STEP 2: BREAK (PnB) (JIKA ADA STOK BLOK DI TAS - PRIORITAS UTAMA SEBELUM PANEN!)
            -- =========================================================================
            local blockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
            if blockStock > 0 then
                -- =========================================================================
                -- CARI SPOT PNB: "PIJAKAN TERATAS PALING KIRI" (Topmost Leftmost Platform / Sign)
                -- Independent dari scanPlantableRows (tidak terpengaruh status tanam pohon)!
                -- =========================================================================
                local standX, standY, breakX, breakY = nil, nil, nil, nil
                local curPx, curPy = getPlayerTilePos()

                -- 1. PRIORITAS UTAMA: Cari Pijakan (Solid Block Apapun / Platform / Mushroom) TERATAS di kolom kiri (x = 1..4, y = 1..worldH-1)
                -- Apapun jenis bloknya (Dirt, Rock, Wood Block, Bedrock, Brick, Platform, dsb) yang penting solid/platform dan ada ruang berdiri!
                for y = 1, worldH - 1 do
                    for x = 1, 4 do
                        local t = getRealtimeTile("fg", x, y)
                        if t and t > 0 then
                            local db = ItemDB and ItemDB[t]
                            local isSolid = isSolidTile(x, y) or (db and db.solid == true)
                            local isPlat = isPlatformTile(x, y) or (db and (db.platform or db.bouncy)) or (t == 102) or (t == 194)
                            if isSolid or isPlat then
                                local aboveSolid = (y - 1 >= 0) and isSolidTile(x, y - 1)
                                local isHazard = db and (db.deadly or db.hurts)
                                if not aboveSolid and not isHazard then
                                    standX = x
                                    standY = y - 1
                                    break
                                end
                            end
                        end
                    end
                    if standX then break end
                end

                -- 2. PRIORITAS KEDUA: Cari Pijakan (Solid Block Apapun / Platform / Mushroom) TERATAS di ujung kanan (x = worldW - 5 .. worldW - 2)
                if not standX then
                    for y = 1, worldH - 1 do
                        for x = worldW - 5, worldW - 2 do
                            local t = getRealtimeTile("fg", x, y)
                            if t and t > 0 then
                                local db = ItemDB and ItemDB[t]
                                local isSolid = isSolidTile(x, y) or (db and db.solid == true)
                                local isPlat = isPlatformTile(x, y) or (db and (db.platform or db.bouncy)) or (t == 102) or (t == 194)
                                if isSolid or isPlat then
                                    local aboveSolid = (y - 1 >= 0) and isSolidTile(x, y - 1)
                                    local isHazard = db and (db.deadly or db.hurts)
                                    if not aboveSolid and not isHazard then
                                        standX = x
                                        standY = y - 1
                                        break
                                    end
                                end
                            end
                        end
                        if standX then break end
                    end
                end

                -- 3. PRIORITAS KETIGA: Deteksi Sign penanda di SELURUH world (sy = 0..worldH-1, sx = 1..worldW-2)
                if not standX then
                    for sy = 0, worldH - 1 do
                        for sx = 1, worldW - 2 do
                            local fg = getRealtimeTile("fg", sx, sy)
                            if fg and ItemDB and ItemDB[fg] and ItemDB[fg].name and string.find(string.lower(ItemDB[fg].name), "sign") then
                                standX = sx
                                standY = sy
                                break
                            end
                        end
                        if standX then break end
                    end
                end

                -- 4. PRIORITAS KEEMPAT: Jika tidak ada platform, gunakan posisi berdiri saat ini jika di area tepi kiri/kanan
                if not standX then
                    if curPx and curPy and curPx >= 1 and curPx <= (worldW - 2) then
                        if curPx <= 4 or curPx >= (worldW - 5) then
                            standX = curPx
                            standY = curPy
                        end
                    end
                end

                -- 5. Fallback Default mutlak (DILARANG KERAS SCAN DIRT BARIS FARM!)
                if not standX then
                    if curPx and curPx > (worldW / 2) then
                        standX = worldW - 3
                    else
                        standX = 1
                    end
                    standY = (curPy and math.clamp(curPy, 0, worldH - 1)) or 0
                end

                standX = math.clamp(standX, 0, worldW - 1)
                standY = math.clamp(standY, 0, worldH - 1)

                -- 6. PENENTUAN TILE BREAK MUTLAK:
                -- Jika berdiri di sisi kiri (standX <= 10): break SELALU DI KIRI (standX - 1)!
                -- Contoh: berdiri di x=1 (UI 2) -> breakX=0 (UI 1, KIRI, facingBit=0, menghadap kiri ke arah border!)
                -- Jika mepet border x=0, barulah break di x=1.
                -- Jika berdiri di ujung kanan (standX > 10): break SELALU DI KANAN (standX + 1)!
                -- Contoh: berdiri di x=worldW-2 -> breakX=worldW-1 (KANAN, facingBit=1, menghadap kanan ke arah border!)
                if standX <= 10 then
                    if standX > 0 then
                        breakX = standX - 1
                    else
                        breakX = 1
                    end
                else
                    if standX < (worldW - 1) then
                        breakX = standX + 1
                    else
                        breakX = standX - 1
                    end
                end
                breakY = standY
                breakX = math.clamp(breakX, 0, worldW - 1)
                breakY = math.clamp(breakY, 0, worldH - 1)

                -- Karakter hanya perlu bergerak jika belum berada tepat di posisi standX, standY
                local initPx, initPy = getPlayerTilePos()
                if not initPx or initPx ~= standX or initPy ~= standY then
                    AutoRotation.status = string.format("[%s] Menuju Spot PnB (%d, %d)...", targetWorldName, standX + 1, standY + 1)
                    if updateRotationUI then updateRotationUI() end

                    local reached = walkOrPathfindTo(standX, standY, worldW, worldH)
                    if not reached and approachTile then
                        approachTile(standX, standY, worldW, worldH)
                    end
                    task.wait(0.08)

                    -- Pastikan koordinat karakter benar-benar sampai di standX, standY!
                    local cPx, cPy = getPlayerTilePos()
                    if (cPx ~= standX or cPy ~= standY) and stepToColumn then
                        stepToColumn(standX, standY)
                        task.wait(0.04)
                    end
                end

                AutoRotation.status = string.format("[%s] PnB [%s] (Sisa: %d blok)...", targetWorldName, blockName, blockStock)
                if updateRotationUI then updateRotationUI() end

                local blockDb = ItemDB and ItemDB[targetBlockId]
                local rotLayer = (blockDb and blockDb.background == true) and "bg" or "fg"
                local isBg = (rotLayer == "bg")

                -- SIKLUS PNB ROTASI PERSIS LOGIKA TAB FARM:
                -- PLACE (ACT_KIND.BUILD + sendTilePacket layer yg sesuai) -> BREAK -> COLLECT -> BALIK HOME!
                while AutoRotation.active and ((getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0) > 0 do
                    while AutoRotation.active and AntiStaff and AntiStaff.isFrozen do
                        AutoRotation.status = "[ANTI-STAFF] Freeze: Staff di world!"
                        if updateRotationUI then updateRotationUI() end
                        task.wait(1)
                    end
                    if not AutoRotation.active then break end

                    -- 0. Cek jarak aman karakter ke tile break (Bypass Error 267)
                    local px, py, rawX, rawY = getPlayerTilePos()
                    if not px or not py then break end

                    local dist = math.sqrt((breakX - px)^2 + (breakY - py)^2)
                    if dist > 1.8 then
                        -- Karakter belum sampai atau terlempar! Jangan pernah kirim paket dari jarak jauh!
                        AutoRotation.status = string.format("[%s] Menuju spot PnB (%d, %d)...", targetWorldName, standX + 1, standY + 1)
                        if updateRotationUI then updateRotationUI() end
                        local arrived = walkOrPathfindTo(standX, standY, worldW, worldH)
                        if not arrived and approachTile then
                            approachTile(standX, standY, worldW, worldH)
                        end
                        task.wait(0.1)
                        continue
                    end

                    local homePx = px
                    local homePy = py
                    local homeRawX = rawX or (px + 0.5)
                    local homeRawY = rawY or (py + 1.0)

                    -- 1. PHASE PLACE: Tempatkan blok pada layer yang sesuai (fg atau bg) jika kosong
                    local curTile = getRealtimeTile(rotLayer, breakX, breakY)
                    if curTile == 0 then
                        if safeSendMove and homeRawX and homeRawY then
                            local facingBit = (breakX < homePx) and 0 or ((breakX > homePx) and 1 or ((homePx <= 10) and 0 or 1))
                            safeSendMove({
                                x = homeRawX,
                                y = homeRawY,
                                vx = 0,
                                vy = 0,
                                flags = 2 + facingBit
                            })
                        end
                        -- Kirim paket BUILD resmi diikuti Tile Packet ByteNet dengan layer yang sesuai (fg=1, bg=2)
                        sendActPacket(ACT_KIND.BUILD, breakX, breakY)
                        sendTilePacket(rotLayer, breakX, breakY, targetBlockId, false)
                        forceClientTileUpdate(rotLayer, breakX, breakY, targetBlockId)

                        -- Kurangi inventory lokal seketika (Sync Backpack Real-time persis Auto DF)
                        local inv = getNativeInventory and getNativeInventory()
                        if inv and inv.remove then
                            pcall(inv.remove, inv, targetBlockId, 1)
                        end
                        if refreshInventory then task.spawn(refreshInventory) end

                        task.wait(0.15) -- Delay place presisi (mengikuti rate limit resmi u3604.actAt >= 0.135s)
                    end

                    -- 2. PHASE BREAK: Pukul & hancurkan blok pada layer yang sesuai sampai hancur
                    local brokenTiles = {}
                    local afterTile = getRealtimeTile(rotLayer, breakX, breakY)
                    if afterTile and afterTile ~= 0 then
                        if safeSendMove and homeRawX and homeRawY then
                            local facingBit = (breakX < homePx) and 0 or ((breakX > homePx) and 1 or ((homePx <= 10) and 0 or 1))
                            safeSendMove({
                                x = homeRawX,
                                y = homeRawY,
                                vx = 0,
                                vy = 0,
                                flags = 2 + facingBit
                            })
                        end
                        local hits = (calculateBlockHits and calculateBlockHits(afterTile)) or (blockDb and blockDb.hits) or 3
                        if hits <= 0 then hits = 3 end
                        for h = 1, hits do
                            if not AutoRotation.active then break end
                            if h > 1 and getRealtimeTile(rotLayer, breakX, breakY) == 0 then break end
                            sendActPacket(ACT_KIND.HIT, breakX, breakY)
                            task.wait(0.16) -- Delay hit resmi game (anti packet flood)
                        end
                        task.wait(0.015)
                        sendTilePacket(rotLayer, breakX, breakY, 0, false)
                        forceClientTileUpdate(rotLayer, breakX, breakY, 0)
                        AutoRotation.totalPnB = AutoRotation.totalPnB + 1
                        if updateRotationUI then updateRotationUI() end
                        table.insert(brokenTiles, { x = breakX, y = breakY })
                        task.wait(0.04)
                    end

                    -- 3. PHASE COLLECT & BALIK KE POS NYA: Ambil droppan di sekitar tile target lalu kembali ke home
                    if collectDropsAtTiles and #brokenTiles > 0 then
                        collectDropsAtTiles(brokenTiles, homePx, homePy, homeRawX, homeRawY)
                    end


                    -- =========================================================
                    -- 3.5 AUTO BUY PACK DARI GEMS ROTASI
                    -- Cek terus jumlah gems player selagi PnB; jika cukup,
                    -- berhenti PnB, jalan/warp ke Storage Pack, beli pack, drop isinya, lalu balik PnB
                    -- =========================================================
                    if AutoRotation.autoBuyPack and AutoRotation.buyPackKey and AutoRotation.buyPackKey ~= "" then
                        local packKey = AutoRotation.buyPackKey
                        local packPrice = AutoShop.getOfferPrice(packKey)
                        local packCount = math.max(1, tonumber(AutoRotation.buyPackCount) or 1)
                        local reqGems = packPrice * packCount
                        local curGems = AutoShop.getGems()
                        local storeWorld = AutoRotation.packStorageWorld and string.upper((string.gsub(AutoRotation.packStorageWorld, "%s+", ""))) or ""

                        if curGems >= reqGems and reqGems > 0 and storeWorld ~= "" and AutoRotation.packStorageDropX and AutoRotation.packStorageDropY then
                            AutoRotation.status = string.format("[AUTO BUY] Gems cukup (%d / %d)! Menuju Storage Pack [%s]...", curGems, reqGems, storeWorld)
                            if updateRotationUI then updateRotationUI() end

                            local arrived = true
                            local nwCur = getNativeWorld and getNativeWorld()
                            local hereWorld = nwCur and nwCur.name and string.upper(nwCur.name) or ""

                            if storeWorld ~= hereWorld then
                                if AutoRotation.saveState then
                                    AutoRotation.saveState({
                                        subtask = "BUY_PACK_STORAGE",
                                        currentWorldIndex = AutoRotation.currentWorldIndex,
                                        farmWorld = targetWorldName,
                                        farmDoor = curEntry.door,
                                        packStorageWorld = storeWorld,
                                        packStorageDoor = AutoRotation.packStorageDoor,
                                        packStorageDropX = AutoRotation.packStorageDropX,
                                        packStorageDropY = AutoRotation.packStorageDropY,
                                        buyPackKey = packKey,
                                        buyPackCount = packCount
                                    })
                                end
                                AutoRotation.status = string.format("[AUTO BUY] Warp ke Storage Pack [%s]...", storeWorld)
                                if updateRotationUI then updateRotationUI() end
                                warpToWorld(storeWorld, AutoRotation.packStorageDoor)
                                return
                            end

                            if arrived and AutoRotation.active then
                                task.wait(1.0)
                                local dTileX = AutoRotation.packStorageDropX - 1
                                local dTileY = AutoRotation.packStorageDropY - 1
                                local standTileX, standTileY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
                                local reached = walkOrPathfindTo(standTileX, standTileY, 100, 60)
                                if not reached and approachTile then
                                    approachTile(standTileX, standTileY, 100, 60)
                                end
                                task.wait(0.1)

                                -- Beli pack sejumlah packCount
                                local bought, itemsToDrop = AutoShop.buyPack(packKey, packCount)
                                AutoRotation.totalPacksBought = (AutoRotation.totalPacksBought or 0) + bought

                                -- Drop semua item pack dengan delay dan verifikasi backpack bersih
                                if AutoRotation.dropAndVerifyPackStorageItems then
                                    AutoRotation.dropAndVerifyPackStorageItems(itemsToDrop, dTileX, dTileY)
                                end

                                if updateRotationUI then updateRotationUI() end

                                -- Balik ke farm world
                                if storeWorld ~= hereWorld then
                                    AutoRotation.status = string.format("Kembali ke Farm World [%s]...", targetWorldName)
                                    if updateRotationUI then updateRotationUI() end
                                    if AutoRotation.saveState then
                                        AutoRotation.saveState({
                                            subtask = "RETURN_FROM_PACK_STORAGE",
                                            currentWorldIndex = AutoRotation.currentWorldIndex,
                                            farmWorld = targetWorldName,
                                            farmDoor = curEntry.door
                                        })
                                    end
                                    warpToWorld(targetWorldName, curEntry.door)
                                    task.wait(2.0)
                                    walkOrPathfindTo(homePx, homePy, worldW, worldH)
                                    task.wait(0.1)
                                else
                                    walkOrPathfindTo(homePx, homePy, worldW, worldH)
                                    task.wait(0.1)
                                end
                            end
                        end
                    end

                    -- Garansi karakter kembali dan terkunci sempurna di posisi awal (home)
                    local chkPx, chkPy = getPlayerTilePos()
                    if chkPx ~= homePx or chkPy ~= homePy then
                        if stepToColumn and homePx and homePy then
                            stepToColumn(homePx, homePy)
                        end
                        if homeRawX and homeRawY then
                            setInternalPlayerPos(homeRawX, homeRawY)
                            if safeSendMove then
                                safeSendMove({
                                    x = homeRawX,
                                    y = homeRawY,
                                    vx = 0,
                                    vy = 0,
                                    flags = 2
                                })
                            end
                        end
                        task.wait(0.02)
                    end

                    -- Cek batas drop profit saat PnB
                    local sCount = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
                    local dropThreshold = AutoRotation.seedProfitToDrop + AutoRotation.minSeedReserve
                    if sCount >= dropThreshold then
                        break -- Jeda PnB untuk tanam & buang profit
                    end
                    task.wait(0.02)
                end
            end

            -- =========================================================================
            -- STEP 3: RE-PLANT AFTER BREAK (Tanam hasil seed dari break, sisakan cadangan)
            -- =========================================================================
            seedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
            if seedStock > AutoRotation.minSeedReserve then
                local rowList, rowsWithSpots = scanPlantableRows(worldW, worldH)
                if #rowList > 0 then
                    AutoRotation.status = string.format("[%s] Re-plant hasil PnB...", targetWorldName)
                    if updateRotationUI then updateRotationUI() end
                    for rowIndex, rY in ipairs(rowList) do
                        if not AutoRotation.active or ((getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0) <= AutoRotation.minSeedReserve then break end
                        local spots = rowsWithSpots[rY] or {}
                        if #spots > 0 then
                            -- ZIGZAG BOUSTROPHEDON (Persis Tab Farm):
                            -- Baris 1: Kiri ke Kanan -> Baris 2: Kanan ke Kiri ...
                            local isLeftToRight = (rowIndex % 2 == 1)
                            table.sort(spots, function(a, b)
                                if isLeftToRight then
                                    return a.x < b.x
                                else
                                    return a.x > b.x
                                end
                            end)

                            for _, spot in ipairs(spots) do
                                if not AutoRotation.active or ((getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0) <= AutoRotation.minSeedReserve then break end
                                if getRealtimeTile("fg", spot.x, spot.y) == 0 then
                                    local reached = approachTile(spot.x, spot.y, worldW, worldH)
                                    if reached and getRealtimeTile("fg", spot.x, spot.y) == 0 then
                                        sendActPacket(ACT_KIND.PLANT, spot.x, spot.y)
                                        sendTilePacket("fg", spot.x, spot.y, targetSeedId, false)
                                        forceClientTileUpdate("fg", spot.x, spot.y, targetSeedId)
                                        local inv = getNativeInventory and getNativeInventory()
                                        if inv and inv.remove then
                                            pcall(inv.remove, inv, targetSeedId, 1)
                                        end
                                        if refreshInventory then task.spawn(refreshInventory) end
                                        AutoRotation.totalPlanted = AutoRotation.totalPlanted + 1
                                        if updateRotationUI then updateRotationUI() end
                                        task.wait(0.18) -- Delay re-plant rotasi dinaikkan
                                    end
                                end
                            end
                        end
                    end
                    curEntry.lastPlantedTime = os.clock()
                end
            end

            -- =========================================================================
            -- STEP 4: DROP SEED PROFIT (jika seed di tas >= dropThreshold)
            -- =========================================================================
            seedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
            local dropThreshold = AutoRotation.seedProfitToDrop + AutoRotation.minSeedReserve
            if seedStock >= dropThreshold and AutoRotation.storageWorld and AutoRotation.storageWorld ~= "" and AutoRotation.storageDropX and AutoRotation.storageDropY then
                local dropAmt = AutoRotation.seedProfitToDrop
                local storageW = string.upper((string.gsub(AutoRotation.storageWorld, "%s+", "")))

                AutoRotation.status = string.format("Membuang profit %d seed ke storage [%s]...", dropAmt, storageW)
                if updateRotationUI then updateRotationUI() end

                local nwCur = getNativeWorld and getNativeWorld()
                local hereWorld = nwCur and nwCur.name and string.upper(nwCur.name) or ""

                if storageW ~= hereWorld then
                    if AutoRotation.saveState then
                        AutoRotation.saveState({
                            subtask = "DROP_SEED_STORAGE",
                            currentWorldIndex = AutoRotation.currentWorldIndex,
                            farmWorld = targetWorldName,
                            farmDoor = curEntry.door,
                            seedId = targetSeedId,
                            storageWorld = storageW,
                            storageDoor = AutoRotation.storageDoor,
                            storageDropX = AutoRotation.storageDropX,
                            storageDropY = AutoRotation.storageDropY,
                            dropAmt = dropAmt
                        })
                    end
                    AutoRotation.status = string.format("Warp ke Storage Seed [%s]...", storageW)
                    if updateRotationUI then updateRotationUI() end
                    warpToWorld(storageW, AutoRotation.storageDoor)
                    return
                else
                    -- Storage di world yang sama
                    local dTileX = AutoRotation.storageDropX - 1
                    local dTileY = AutoRotation.storageDropY - 1
                    if AutoRotation.dropAndVerifySeedStorage then
                        AutoRotation.dropAndVerifySeedStorage(targetSeedId, dropAmt, dTileX, dTileY)
                    else
                        local standTileX, standTileY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
                        walkOrPathfindTo(standTileX, standTileY, 100, 60)
                        task.wait(0.1)
                        sendDropPacket(targetSeedId, dropAmt, dTileX + 0.5, dTileY + 0.5)
                        local inv = getNativeInventory and getNativeInventory()
                        if inv and inv.remove then pcall(inv.remove, inv, targetSeedId, dropAmt) end
                        AutoRotation.totalProfitDropped = (AutoRotation.totalProfitDropped or 0) + (tonumber(dropAmt) or 0)
                    end
                    if updateRotationUI then updateRotationUI() end
                    task.wait(0.5)
                end
            end

            -- =========================================================================
            -- STEP 5: HARVEST RIPE TREES (HANYA JIKA BLOK DI TAS KOSONG / <= 0 DAN ADA POHON READY!)
            -- =========================================================================
            blockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
            if blockStock <= 0 and #ripeTrees > 0 then
                AutoRotation.status = string.format("[%s] Panen %d pohon %s matang (Target: 180 blok)...", targetWorldName, #ripeTrees, seedName)
                if updateRotationUI then updateRotationUI() end

                -- Kelompokkan pohon matang per baris Y agar panen juga ZIGZAG (Persis Tab Farm)
                local treesByRow = {}
                local harvestRowList = {}
                for _, t in ipairs(ripeTrees) do
                    if not treesByRow[t.y] then
                        treesByRow[t.y] = {}
                        table.insert(harvestRowList, t.y)
                    end
                    table.insert(treesByRow[t.y], t)
                end
                table.sort(harvestRowList, function(a, b) return a < b end)

                for hIndex, rY in ipairs(harvestRowList) do
                    if not AutoRotation.active then break end
                    if ((getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0) >= 180 then break end

                    local rowTrees = treesByRow[rY] or {}
                    local isLeftToRight = (hIndex % 2 == 1)
                    table.sort(rowTrees, function(a, b)
                        if isLeftToRight then
                            return a.x < b.x
                        else
                            return a.x > b.x
                        end
                    end)

                    for _, t in ipairs(rowTrees) do
                        if not AutoRotation.active then break end
                        if ((getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0) >= 180 then break end

                        local curFg = getRealtimeTile("fg", t.x, t.y)
                        if curFg ~= 0 then
                            local reached = approachTile(t.x, t.y, worldW, worldH)
                            if reached then
                                sendActPacket(ACT_KIND.HIT, t.x, t.y)
                                task.wait(0.08) -- Delay hit panen rotasi dinaikkan
                                sendTilePacket("fg", t.x, t.y, 0, false)
                                forceClientTileUpdate("fg", t.x, t.y, 0)
                                if w and w.setTree then pcall(w.setTree, t.x, t.y, nil) end
                                AutoRotation.totalHarvested = AutoRotation.totalHarvested + 1
                                if updateRotationUI then updateRotationUI() end
                                task.wait(0.12) -- Delay jeda antar pohon rotasi dinaikkan
                            end
                        end
                    end
                end

                -- Sapu bersih hasil panen secara row-by-row
                if sweepTargetDropsRowByRow then
                    sweepTargetDropsRowByRow(targetBlockId, 180)
                    sweepTargetDropsRowByRow(targetSeedId, 180)
                end
            end

            -- =========================================================================
            -- STEP 6: CEK KELENGKAPAN WORLD & PINDAH ROTASI
            -- =========================================================================
            local recheckTrees = scanWorldTrees and scanWorldTrees() or {}
            local remainingRipe = 0
            for _, t in ipairs(recheckTrees) do
                if (t.seedId == targetSeedId or t.fruitId == targetBlockId) and t.isRipe then
                    remainingRipe = remainingRipe + 1
                end
            end

            blockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
            seedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0

            -- Cek apakah lahan tanam sudah habis / world sudah full pohon
            local endPlantRows = scanPlantableRows and scanPlantableRows(worldW, worldH) or {}
            local isWorldFull = (#endPlantRows == 0)

            -- Sapu sisa droppan jika blok kosong dan masih ada tempat tanam
            if blockStock <= 0 and (seedStock <= 0 or not isWorldFull) and checkWorldTargetDrops() then
                AutoRotation.status = string.format("[%s] Menyapu sisa droppan target di world...", targetWorldName)
                if updateRotationUI then updateRotationUI() end
                if sweepTargetDropsRowByRow then
                    sweepTargetDropsRowByRow(targetBlockId, 180)
                    sweepTargetDropsRowByRow(targetSeedId, 180)
                end
                blockStock = (getRealtimeItemCount and getRealtimeItemCount(targetBlockId)) or 0
                seedStock = (getRealtimeItemCount and getRealtimeItemCount(targetSeedId)) or 0
            end

            -- LOGIKA ROTASI FIX:
            -- Syarat pindah terpenuhi jika:
            -- 1. Tidak ada pohon ripe (remainingRipe == 0)
            -- 2. Tidak ada blok di tas (blockStock <= 0)
            -- 3. World sudah FULL (isWorldFull == true) ATAU sisa bibit sudah <= cadangan (seedStock <= minSeedReserve)
            local canPlant = (not isWorldFull) and (seedStock > AutoRotation.minSeedReserve)
            if remainingRipe == 0 and blockStock <= 0 and not canPlant then
                local growDur = (ItemDB and ItemDB[targetSeedId] and ItemDB[targetSeedId].grow) or 30
                curEntry.countdownEndsAt = os.clock() + growDur
                AutoRotation.totalWorldsRotated = AutoRotation.totalWorldsRotated + 1

                AutoRotation.status = string.format("[%s] Beres! Pohon unready & lahan selesai. Lanjut world berikutnya...", targetWorldName)
                if updateRotationUI then updateRotationUI() end
                task.wait(0.8)
                AutoRotation.currentWorldIndex = AutoRotation.currentWorldIndex + 1
                if AutoRotation.currentWorldIndex > numWorlds then
                    AutoRotation.currentWorldIndex = 1
                end
                local nextEntry = AutoRotation.worlds[AutoRotation.currentWorldIndex]
                local nextWorld = nextEntry and string.upper((nextEntry.worldName or ""):gsub("%s+", "")) or ""
                local nextDoor = nextEntry and nextEntry.door or ""
                if AutoRotation.saveState then
                    AutoRotation.saveState({
                        subtask = "ROTATION_LOOP",
                        currentWorldIndex = AutoRotation.currentWorldIndex,
                        farmWorld = nextWorld,
                        farmDoor = nextDoor
                    })
                end
                if nextWorld ~= "" and nextWorld ~= targetWorldName then
                    AutoRotation.status = string.format("Warp ke World berikutnya [%s] (Queue %d/%d)...", nextWorld, AutoRotation.currentWorldIndex, numWorlds)
                    if updateRotationUI then updateRotationUI() end
                    warpToWorld(nextWorld, nextDoor)
                    return
                end
            end

            task.wait(0.2)
        end
    end)
end
AutoRotation.start = startAutoRotation

