-- ═══════════════════════════════════════
--  AUTO FARMCHECK CONTROLLER (Auto Solve Math Captcha)
-- ═══════════════════════════════════════
local AutoFarmCheck = {
    enabled = true,
    lastSolved = 0,
    totalSolved = 0,
    lastQuestion = "",
    lastAnswer = nil,
    busy = false,
    updateUI = nil,
    lblStatus = nil,
    lblStats = nil,
    btnToggle = nil,
}

local function solveFarmCheck(say)
    if not say or type(say) ~= "string" or say == "" then return nil end
    local s = string.lower(say)

    local tens = {
        ["twenty"] = 20, ["thirty"] = 30, ["forty"] = 40, ["fifty"] = 50,
        ["sixty"] = 60, ["seventy"] = 70, ["eighty"] = 80, ["ninety"] = 90,
        ["dua puluh"] = 20, ["tiga puluh"] = 30, ["empat puluh"] = 40, ["lima puluh"] = 50
    }
    local ones = {
        ["zero"] = 0, ["one"] = 1, ["two"] = 2, ["three"] = 3, ["four"] = 4,
        ["five"] = 5, ["six"] = 6, ["seven"] = 7, ["eight"] = 8, ["nine"] = 9,
        ["ten"] = 10, ["eleven"] = 11, ["twelve"] = 12, ["thirteen"] = 13,
        ["fourteen"] = 14, ["fifteen"] = 15, ["sixteen"] = 16, ["seventeen"] = 17,
        ["eighteen"] = 18, ["nineteen"] = 19,
        ["nol"] = 0, ["satu"] = 1, ["dua"] = 2, ["tiga"] = 3, ["empat"] = 4,
        ["lima"] = 5, ["enam"] = 6, ["tujuh"] = 7, ["delapan"] = 8, ["sembilan"] = 9,
        ["sepuluh"] = 10, ["sebelas"] = 11, ["dua belas"] = 12, ["tiga belas"] = 13,
        ["empat belas"] = 14, ["lima belas"] = 15, ["enam belas"] = 16, ["tujuh belas"] = 17,
        ["delapan belas"] = 18, ["sembilan belas"] = 19
    }

    for t_word, t_val in pairs(tens) do
        for o_word, o_val in pairs(ones) do
            local pat = "%f[%a]" .. t_word .. "[%s%-]+" .. o_word .. "%f[%A]"
            s = string.gsub(s, pat, tostring(t_val + o_val))
        end
    end

    for t_word, t_val in pairs(tens) do
        s = string.gsub(s, "%f[%a]" .. t_word .. "%f[%A]", tostring(t_val))
    end

    for o_word, o_val in pairs(ones) do
        s = string.gsub(s, "%f[%a]" .. o_word .. "%f[%A]", tostring(o_val))
    end

    s = string.gsub(s, "%f[%a]plus%f[%A]", "+")
    s = string.gsub(s, "%f[%a]added%s+to%f[%A]", "+")
    s = string.gsub(s, "%f[%a]add%f[%A]", "+")
    s = string.gsub(s, "%f[%a]tambah%f[%A]", "+")

    s = string.gsub(s, "%f[%a]minus%f[%A]", "-")
    s = string.gsub(s, "%f[%a]subtracted%s+by%f[%A]", "-")
    s = string.gsub(s, "%f[%a]subtract%f[%A]", "-")
    s = string.gsub(s, "%f[%a]kurang%f[%A]", "-")

    s = string.gsub(s, "%f[%a]times%f[%A]", "*")
    s = string.gsub(s, "%f[%a]multiplied%s+by%f[%A]", "*")
    s = string.gsub(s, "%f[%a]multiply%f[%A]", "*")
    s = string.gsub(s, "%f[%a]kali%f[%A]", "*")

    s = string.gsub(s, "%f[%a]divided%s+by%f[%A]", "/")
    s = string.gsub(s, "%f[%a]divide%f[%A]", "/")
    s = string.gsub(s, "%f[%a]bagi%f[%A]", "/")

    local n1, op, n2 = string.match(s, "(%d+)%s*([%+%-%*%/x])%s*(%d+)")
    if n1 and op and n2 then
        local num1 = tonumber(n1)
        local num2 = tonumber(n2)
        if num1 and num2 then
            if op == "+" then return num1 + num2
            elseif op == "-" then return num1 - num2
            elseif op == "*" or op == "x" then return num1 * num2
            elseif op == "/" then return (num2 ~= 0) and math.floor(num1 / num2) or 0
            end
        end
    end

    local singleNum = string.match(s, "%d+")
    if singleNum then
        return tonumber(singleNum)
    end

    return nil
end

local function installFarmCheckHook()
    if not (Net and Net.on) then return end

    local function handleIncomingFarmCheck(a1, a2, a3, a4, a5)
        if a4 == "math" and type(a5) == "string" and AutoFarmCheck.enabled then
            task.spawn(function()
                if AutoFarmCheck.busy then return end
                AutoFarmCheck.busy = true
                AutoFarmCheck.lastQuestion = a5
                print(string.format("[FARMCHECK] 🚨 Deteksi FarmCheck Masuk! Soal: '%s'", a5))
                if Proxy and Proxy.notify then
                    Proxy.notify(string.format("`e[FarmCheck] Terdeteksi! Soal: '%s'``", a5))
                end

                local ans = solveFarmCheck(a5)
                if ans ~= nil then
                    print(string.format("[FARMCHECK] Solusi dihitung: %d. Menunggu delay manusiawi...", ans))
                    task.wait(2.0)

                    if not AutoFarmCheck.enabled then
                        AutoFarmCheck.busy = false
                        return
                    end

                    if Net and Net.call then
                        local success, okAns, errMsg = pcall(Net.call, "FarmAnswer", ans)
                        print("[FARMCHECK] Submit Jawaban:", ans, "Hasil:", success, okAns, errMsg)
                        if success and okAns then
                            AutoFarmCheck.totalSolved = AutoFarmCheck.totalSolved + 1
                            AutoFarmCheck.lastAnswer = ans
                            AutoFarmCheck.lastSolved = os.clock()
                            print(string.format("[FARMCHECK] ✅ Berhasil terjawab tuntas! (Jawaban: %d, Total: %d)", ans, AutoFarmCheck.totalSolved))
                            if Proxy and Proxy.notify then
                                Proxy.notify(string.format("`2[FarmCheck] ✅ Berhasil dijawab otomatis: %d! Lanjut farming...``", ans))
                            end
                            if AutoFarmCheck.updateUI then AutoFarmCheck.updateUI() end

                            pcall(function()
                                local lp = Players.LocalPlayer
                                local pgui = lp and lp:FindFirstChild("PlayerGui")
                                local fcGui = pgui and pgui:FindFirstChild("FarmCheckGui")
                                if fcGui then fcGui:Destroy() end
                            end)
                        else
                            warn("[FARMCHECK] ⚠️ Jawaban salah atau ditolak server:", errMsg)
                            if Proxy and Proxy.notify then
                                Proxy.notify(string.format("`4[FarmCheck] Gagal submit: %s``", tostring(errMsg or "Jawaban salah")))
                            end
                        end
                    end
                else
                    warn("[FARMCHECK] ❌ Format soal tidak dikenali! Mohon jawab manual:", a5)
                    if Proxy and Proxy.notify then
                        Proxy.notify(string.format("`4[FarmCheck ALERT] Soal tidak dapat dihitung: '%s'! Segera jawab manual!``", a5))
                    end
                end

                AutoFarmCheck.busy = false
            end)
        end
    end

    pcall(function()
        if debug and debug.getupvalues then
            local upvals = debug.getupvalues(Net.on)
            local handlers = upvals and upvals[1]
            if type(handlers) == "table" then
                local origFC = handlers["FarmCheck"]
                handlers["FarmCheck"] = function(...)
                    if origFC then pcall(origFC, ...) end
                    handleIncomingFarmCheck(...)
                end
            end
        end
    end)

    if not Net._farmCheckHookInstalled then
        Net._farmCheckHookInstalled = true
        local origOn = Net.on
        Net.on = function(name, fn)
            if name == "FarmCheck" then
                local wrapped = function(...)
                    pcall(fn, ...)
                    handleIncomingFarmCheck(...)
                end
                return origOn(name, wrapped)
            end
            return origOn(name, fn)
        end
    end
end

-- Auto install hook immediately
pcall(installFarmCheckHook)

