--  ANTI-BOUNCE & ANTI-HAZARD CONTROLLER
-- =======================================
-- ANTI-HAZARD & IMMUNITY CONTROLLER
-- =======================================
local AntiHazard = {
    enabled = false,
    antiLava = true,
    antiDeadly = true,
    antiBounce = true,
    antiLaser = true,
    antiBumper = true,
    hoverOffset = 0.06,
    lastHoverTick = 0,
    origLaserAt = nil,
    origUnderFeet = nil,
    currentWorld = nil,
    nativeTouchBlocks = nil,
    origTouchingHurt = nil,
    customTouchingHurt = nil,
    hookedDie = false,
    origDie = nil,
    heartbeatConn = nil,
    origProps = {},
    scanned = false,
    protected = {},
    deadlyIds = {
        162, 454, 1520, 1706, 1870, 1990, 2008, 2226, 2276, 3568,
        3570, 3748, 4100, 4102, 4158, 4342, 4800, 5274, 5978, 6410,
        6976, 6994, 7048, 8688, 11600, 11606, 12254, 13208, 16204
    },
    hurtIds = { 4 },
    bouncyIds = {
        194, 624, 1002, 1774, 2516, 4392, 4394, 4396, 4398, 4400,
        4624, 4878, 5364, 5384, 5388, 6992, 7442, 7882, 8478, 9754,
        10482, 10696, 10742, 11268, 11368, 11732, 11776, 12536, 12538, 12782,
        12792, 13302, 13304, 13388, 13622, 14178, 14348, 14808, 15000, 15208, 15830
    },
    bumperIds = { 466, 468, 470, 526 },
    laserIds = { 5666 },
}
_G.AntiHazard = AntiHazard

function AntiHazard.isHazardBlock(id)
    if not id or id <= 0 then return false end
    local prop = AntiHazard.origProps[id]
    if prop then
        if AntiHazard.antiDeadly ~= false and prop.deadly then return true end
        if AntiHazard.antiLava ~= false and prop.hurts then return true end
        if (AntiHazard.antiBounce ~= false or AntiHazard.antiLava ~= false) and prop.bouncy then return true end
        if AntiHazard.antiBumper ~= false and prop.bumper then return true end
    end
    if AntiHazard.antiDeadly ~= false and (id == 162 or id == 454 or id == 1520 or id == 1706 or id == 1870 or id == 1990) then return true end
    if AntiHazard.antiLava ~= false and id == 4 then return true end
    if (AntiHazard.antiBounce ~= false or AntiHazard.antiLava ~= false) and (id == 194 or id == 624 or id == 1002) then return true end
    if AntiHazard.antiBumper ~= false and (id == 526 or id == 466 or id == 468 or id == 470) then return true end
    return false
end

function AntiHazard.stepMicroHover()
    if not AntiHazard.enabled then return end
    if AntiHazard.antiDeadly == false and AntiHazard.antiLava == false and AntiHazard.antiBounce == false then return end

    local tb = AntiHazard.nativeTouchBlocks
    local w = AntiHazard.currentWorld
    if not tb or not w or not w.fg or not debug or not debug.getupvalue or not debug.setupvalue then return end

    local curY = debug.getupvalue(tb, 3)
    local curX = debug.getupvalue(tb, 4)
    if not curX or not curY then return end

    local vy = debug.getupvalue(tb, 8) or 0
    local x1 = math.floor(curX - 0.28)
    local x2 = math.floor(curX + 0.28)
    local floorY = math.floor(curY + 0.1)
    local bodyY = math.floor(curY - 0.02)
    local offset = AntiHazard.hoverOffset or 0.06

    -- 1. Hazard floor below player feet
    local hasHazardFloor = false
    local rowF = w.fg[floorY]
    if rowF then
        for x = x1, x2 do
            local id = rowF[x]
            if id and AntiHazard.isHazardBlock(id) then
                hasHazardFloor = true
                break
            end
        end
    end

    if hasHazardFloor then
        local safeY = floorY - offset
        if curY >= safeY - 0.25 and curY <= floorY + 0.5 then
            if curY >= safeY or (vy >= 0 and curY >= safeY - 0.08) then
                debug.setupvalue(tb, 3, safeY)
                if vy > 0 then
                    debug.setupvalue(tb, 8, 0)
                end
                debug.setupvalue(tb, 9, true)
                AntiHazard.lastHoverTick = os.clock()
                return
            end
        end
    end

    -- 2. Hazard block inside body / obstacle
    local hasHazardBody = false
    local rowB = w.fg[bodyY]
    if rowB then
        for x = x1, x2 do
            local id = rowB[x]
            if id and AntiHazard.isHazardBlock(id) then
                hasHazardBody = true
                break
            end
        end
    end

    if hasHazardBody then
        local safeY = bodyY - offset
        if curY >= safeY - 0.25 and curY <= bodyY + 0.6 then
            debug.setupvalue(tb, 3, safeY)
            if vy > 0 then
                debug.setupvalue(tb, 8, 0)
            end
            debug.setupvalue(tb, 9, true)
            AntiHazard.lastHoverTick = os.clock()
            return
        end
    end

    -- 3. Ceiling spikes
    local ceilY = math.floor(curY - 0.95)
    local rowC = w.fg[ceilY]
    if rowC and (AntiHazard.antiDeadly ~= false or AntiHazard.antiLava ~= false) then
        local hasCeilHazard = false
        for x = x1, x2 do
            local id = rowC[x]
            if id and AntiHazard.isHazardBlock(id) then
                hasCeilHazard = true
                break
            end
        end
        if hasCeilHazard then
            local ceilSafeY = ceilY + 1.95 + offset
            if curY <= ceilSafeY and vy < 0 then
                debug.setupvalue(tb, 3, ceilSafeY)
                debug.setupvalue(tb, 8, 0)
            end
        end
    end
end

function AntiHazard.protectItem(it, id)
    if not it or type(it) ~= 'table' then return end
    if AntiHazard.protected[it] then return end
    AntiHazard.protected[it] = true

    setmetatable(it, {
        __index = function(t, k)
            if AntiHazard.enabled then
                if k == 'deadly' and AntiHazard.antiDeadly ~= false then return nil end
                if k == 'hurts' and AntiHazard.antiLava ~= false then return nil end
                if k == 'bouncy' and (AntiHazard.antiBounce ~= false or AntiHazard.antiLava ~= false) then return nil end
                if k == 'bumper' and AntiHazard.antiBumper ~= false then return nil end
                if k == 'laser' and AntiHazard.antiLaser ~= false then return nil end
            end
            return rawget(t, k)
        end,
        __newindex = function(t, k, v)
            if AntiHazard.enabled then
                if k == 'deadly' and AntiHazard.antiDeadly ~= false then rawset(t, k, nil) return end
                if k == 'hurts' and AntiHazard.antiLava ~= false then rawset(t, k, nil) return end
                if k == 'bouncy' and (AntiHazard.antiBounce ~= false or AntiHazard.antiLava ~= false) then rawset(t, k, nil) return end
                if k == 'bumper' and AntiHazard.antiBumper ~= false then rawset(t, k, nil) return end
                if k == 'laser' and AntiHazard.antiLaser ~= false then rawset(t, k, nil) return end
            end
            rawset(t, k, v)
        end
    })
end

local function applyAntiHazard()
    local dbs = {}
    if ItemDB then table.insert(dbs, ItemDB) end
    pcall(function()
        local bdb = Shared:FindFirstChild('BlocksDB')
        if bdb then
            local req = require(bdb)
            if req then table.insert(dbs, req) end
        end
    end)

    -- Dynamic scan to populate origProps from ItemDB
    if not AntiHazard.scanned and ItemDB then
        AntiHazard.scanned = true
        for id, it in pairs(ItemDB) do
            if type(it) == 'table' and (it.deadly or it.hurts or it.bouncy or it.bumper or it.laser) then
                AntiHazard.origProps[id] = {
                    deadly = it.deadly,
                    hurts = it.hurts,
                    bouncy = it.bouncy,
                    bumper = it.bumper,
                    laser = it.laser,
                }
            end
        end
        for _, id in ipairs(AntiHazard.deadlyIds) do
            if not AntiHazard.origProps[id] then AntiHazard.origProps[id] = { deadly = true } end
        end
        for _, id in ipairs(AntiHazard.hurtIds) do
            if not AntiHazard.origProps[id] then AntiHazard.origProps[id] = { hurts = true } end
        end
        for _, id in ipairs(AntiHazard.bouncyIds) do
            if not AntiHazard.origProps[id] then AntiHazard.origProps[id] = { bouncy = true } end
        end
        for _, id in ipairs(AntiHazard.bumperIds) do
            if not AntiHazard.origProps[id] then AntiHazard.origProps[id] = { bumper = true } end
        end
        for _, id in ipairs(AntiHazard.laserIds) do
            if not AntiHazard.origProps[id] then AntiHazard.origProps[id] = { laser = true } end
        end
    end

    local isDeadlyImmune = (AntiHazard.enabled and AntiHazard.antiDeadly ~= false)
    local isLavaImmune   = (AntiHazard.enabled and AntiHazard.antiLava ~= false)
    local isBounceImmune = (AntiHazard.enabled and AntiHazard.antiBounce ~= false)
    local isBumperImmune = (AntiHazard.enabled and AntiHazard.antiBumper ~= false)
    local isLaserImmune  = (AntiHazard.enabled and AntiHazard.antiLaser ~= false)

    -- Layer 1: Metatable & Raw properties on all DBs
    for _, db in ipairs(dbs) do
        for id, orig in pairs(AntiHazard.origProps) do
            local it = db[id]
            if it and type(it) == 'table' then
                AntiHazard.protectItem(it, id)
                if orig.deadly ~= nil then
                    rawset(it, 'deadly', if isDeadlyImmune then nil else orig.deadly)
                end
                if orig.hurts ~= nil then
                    rawset(it, 'hurts', if isLavaImmune then nil else orig.hurts)
                end
                if orig.bouncy ~= nil then
                    rawset(it, 'bouncy', if (isBounceImmune or isLavaImmune) then nil else orig.bouncy)
                end
                if orig.bumper ~= nil then
                    rawset(it, 'bumper', if isBumperImmune then nil else orig.bumper)
                end
                if orig.laser ~= nil then
                    rawset(it, 'laser', if isLaserImmune then nil else orig.laser)
                end
            end
        end
    end

    local w = getNativeWorld()
    if w then
        AntiHazard.currentWorld = w
        if isBumperImmune or isLavaImmune then
            w.bumpUntil = 0
            w.bumpLit = false
        end

        -- Layer 2: Laser immunity
        if not AntiHazard.origLaserAt and w.laserAt then
            AntiHazard.origLaserAt = w.laserAt
            w.laserAt = function(...)
                if AntiHazard.enabled and AntiHazard.antiLaser ~= false then
                    return false, false
                end
                return AntiHazard.origLaserAt(...)
            end
        end

        -- Layer 3: Anti-Bounce Jamur / Mushroom (w.underFeet)
        if not AntiHazard.origUnderFeet and w.underFeet then
            AntiHazard.origUnderFeet = w.underFeet
            w.underFeet = function(a1)
                if AntiHazard.enabled then
                    if a1 == 'bouncy' and (AntiHazard.antiBounce ~= false or AntiHazard.antiLava ~= false) then
                        return false
                    end
                end
                return AntiHazard.origUnderFeet(a1)
            end
        end

        -- Layer 4: Intercept touchingHurt safely via native engine
        local eng = getNativeEngine()
        if eng and type(eng.touchingHurt) == "function" and not AntiHazard.origTouchingHurt then
            AntiHazard.origTouchingHurt = eng.touchingHurt
            eng.touchingHurt = function(a1)
                if AntiHazard.enabled then
                    if a1 == 'deadly' and AntiHazard.antiDeadly ~= false then
                        return nil
                    end
                    if (a1 == nil or a1 == 'hurts') and AntiHazard.antiLava ~= false then
                        return nil
                    end
                    if a1 == 'bumper' and AntiHazard.antiBumper ~= false then
                        return nil
                    end
                end
                return AntiHazard.origTouchingHurt(a1)
            end
        end

        -- Layer 5: Master Godmode Shield - Hooking die() via native engine
        if eng and type(eng.die) == "function" and not AntiHazard.hookedDie and hookfunction then
            AntiHazard.hookedDie = true
            local origDie
            origDie = hookfunction(eng.die, function(...)
                if AntiHazard.enabled and AntiHazard.antiDeadly ~= false then
                    return
                end
                return origDie(...)
            end)
            AntiHazard.origDie = origDie
        end

        -- Layer 6: Micro-Hover active physics stabilization
        if not AntiHazard.heartbeatConn and RunService and RunService.Heartbeat then
            AntiHazard.heartbeatConn = RunService.Heartbeat:Connect(function()
                if AntiHazard.enabled and (AntiHazard.antiDeadly ~= false or AntiHazard.antiLava ~= false or AntiHazard.antiBounce ~= false) then
                    pcall(AntiHazard.stepMicroHover)
                end
            end)
        end
    end
end

task.spawn(function()
    while true do
        task.wait(0.5)
        if AntiHazard.enabled then
            pcall(applyAntiHazard)
        end
    end
end)

