local closeMainDialog = nil
local toggleMainDialog = nil

local uiScaleMode = "Auto" -- "Auto", "55%", "70%", "85%", "100%"
local uiScaleObj = nil
local btnScaleText = nil
local computeAutoUIScale = nil
local getActiveUIScale = nil
local applyUIScale = nil
local setUIScaleMode = nil
local cycleUIScaleMode = nil

computeAutoUIScale = function()
    local cam = workspace.CurrentCamera
    local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
    local isTouch = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    local isSmall = vp.Y < 640 or vp.X < 960

    if isTouch or isSmall then
        -- Mobile phone or compact screen:
        -- Ensure MainDialog (720x580) fits comfortably within 80% screen height and 75% screen width
        local scaleY = (vp.Y * 0.80) / 580
        local scaleX = (vp.X * 0.75) / 720
        local autoScale = math.min(scaleX, scaleY)
        return math.clamp(math.floor(autoScale * 100 + 0.5) / 100, 0.48, 0.82)
    else
        -- Desktop / larger screen
        local scaleY = (vp.Y * 0.90) / 580
        local scaleX = (vp.X * 0.90) / 720
        local autoScale = math.min(scaleX, scaleY, 1.0)
        return math.clamp(math.floor(autoScale * 100 + 0.5) / 100, 0.70, 1.0)
    end
end

getActiveUIScale = function()
    if uiScaleMode == "55%" then return 0.55
    elseif uiScaleMode == "70%" then return 0.70
    elseif uiScaleMode == "85%" then return 0.85
    elseif uiScaleMode == "100%" then return 1.0
    else return computeAutoUIScale() end
end

local function updateScaleButtonText()
    if not btnScaleText then return end
    pcall(function()
        local curScale = getActiveUIScale()
        local pct = math.floor(curScale * 100 + 0.5)
        if uiScaleMode == "Auto" then
            btnScaleText:set("`cAuto (" .. pct .. "%)``")
        elseif uiScaleMode == "55%" then
            btnScaleText:set("`eMobile 55%``")
        elseif uiScaleMode == "70%" then
            btnScaleText:set("`eMedium 70%``")
        elseif uiScaleMode == "85%" then
            btnScaleText:set("`aLarge 85%``")
        elseif uiScaleMode == "100%" then
            btnScaleText:set("`2PC 100%``")
        else
            btnScaleText:set("`w" .. tostring(uiScaleMode) .. "``")
        end
    end)
end

applyUIScale = function(animate)
    local targetScale = getActiveUIScale()
    if uiScaleObj then
        if animate ~= false and MainDialog and MainDialog.Visible then
            TweenService:Create(uiScaleObj, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Scale = targetScale
            }):Play()
        else
            uiScaleObj.Scale = targetScale
        end
    end
    if Proxy and Proxy._uiLogsRefs and Proxy._uiLogsRefs.uiScale and Proxy.logsDialog and Proxy.logsDialog.Visible then
        if animate ~= false then
            TweenService:Create(Proxy._uiLogsRefs.uiScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Scale = targetScale
            }):Play()
        else
            Proxy._uiLogsRefs.uiScale.Scale = targetScale
        end
    end
    updateScaleButtonText()
end

setUIScaleMode = function(mode, save)
    uiScaleMode = mode or "Auto"
    if Proxy then Proxy.uiScaleMode = uiScaleMode end
    applyUIScale(true)
    if save ~= false and Proxy and Proxy.saveConfig and not (Proxy and Proxy._isLoadingConfig) then
        pcall(Proxy.saveConfig)
    end
end

cycleUIScaleMode = function()
    if uiScaleMode == "Auto" then
        setUIScaleMode("55%")
    elseif uiScaleMode == "55%" then
        setUIScaleMode("70%")
    elseif uiScaleMode == "70%" then
        setUIScaleMode("85%")
    elseif uiScaleMode == "85%" then
        setUIScaleMode("100%")
    else
        setUIScaleMode("Auto")
    end
end

-- Auto-adjust scale dynamically on screen resize or device orientation rotate
pcall(function()
    workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
        if uiScaleMode == "Auto" then
            applyUIScale(false)
        end
    end)
end)

