-- ═══════════════════════════════════════
--  FLOATING DRAGGABLE SYSHUB TOGGLE BUTTON (MOBILE & PC)
-- ═══════════════════════════════════════
do
    -- Download & cache official SysHub logo .jpg (https://syshub.my.id/syshub-logo.jpg)
    local logoAsset = nil
    local logoFile = "syshub_logo.jpg"
    local logoUrl = "https://syshub.my.id/syshub-logo.jpg"

    if isfile and isfile(logoFile) and getcustomasset then
        local ok, aid = pcall(getcustomasset, logoFile)
        if ok and aid then logoAsset = aid end
    end

    -- Floating button container (parented directly to SG for 100% reliable visibility on Mobile & PC)
    local floatBtn = Instance.new("ImageButton")
    floatBtn.Name                   = "SyshubFloatingButton"
    floatBtn.BackgroundTransparency = 0
    floatBtn.BackgroundColor3       = Color3.fromRGB(12, 110, 240) -- Matching blue bg
    floatBtn.Size                   = UDim2.fromOffset(42, 42)
    floatBtn.AnchorPoint            = Vector2.new(1, 0.5)
    floatBtn.Position               = UDim2.new(1, -14, 0.5, -21)
    floatBtn.AutoButtonColor        = false
    floatBtn.BorderSizePixel        = 0
    floatBtn.ClipsDescendants       = true -- Full edge-to-edge clipping
    floatBtn.ZIndex                 = 50
    floatBtn.Parent                 = SG
    corner(floatBtn, 12)

    -- Outer border stroke (cyan glow accent)
    local strokeOuter = Instance.new("UIStroke", floatBtn)
    strokeOuter.Color = Color3.fromRGB(75, 255, 255)
    strokeOuter.Thickness = 2.0
    strokeOuter.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Logo Image (100% full edge-to-edge cover tanpa margin hitam)
    local imgLogo = Instance.new("ImageLabel", floatBtn)
    imgLogo.Name                   = "LogoImage"
    imgLogo.BackgroundTransparency = 1
    imgLogo.Size                   = UDim2.fromScale(1, 1)
    imgLogo.Position               = UDim2.fromScale(0.5, 0.5)
    imgLogo.AnchorPoint            = Vector2.new(0.5, 0.5)
    imgLogo.ScaleType              = Enum.ScaleType.Crop
    imgLogo.ZIndex                 = 52
    corner(imgLogo, 12)

    local fallbackIcon = nil
    if logoAsset then
        imgLogo.Image = logoAsset
        imgLogo.Visible = true
    else
        imgLogo.Visible = false
        if ItemIcon and ItemIcon.new then
            local icon = ItemIcon.new(floatBtn, UDim2.fromOffset(44, 44), 2)
            ItemIcon.set(icon, 1784)
            icon.frame.AnchorPoint = Vector2.new(0.5, 0.5)
            icon.frame.Position    = UDim2.fromScale(0.5, 0.5)
            icon.frame.ZIndex      = 52
            fallbackIcon = icon.frame
        end

        -- Background download loader jika file belum ada
        if writefile and getcustomasset then
            task.spawn(function()
                local rawData = nil
                if game and game.HttpGet then
                    local ok, res = pcall(game.HttpGet, game, logoUrl)
                    if ok and res and #res > 100 then rawData = res end
                elseif request then
                    local ok, res = pcall(request, { Url = logoUrl, Method = "GET" })
                    if ok and res and res.Body and #res.Body > 100 then rawData = res.Body end
                end
                if rawData then
                    pcall(writefile, logoFile, rawData)
                    local ok, aid = pcall(getcustomasset, logoFile)
                    if ok and aid and imgLogo and imgLogo.Parent then
                        imgLogo.Image = aid
                        imgLogo.Visible = true
                        if fallbackIcon then fallbackIcon.Visible = false end
                    end
                end
            end)
        end
    end

    local uiscale = Instance.new("UIScale", floatBtn)

    -- Draggable Controller (Touch & Mouse Support dengan Drag Threshold agar tidak bentrok dengan tap)
    local isPressed = false
    local isDragging = false
    local dragStart = nil
    local startPos = nil
    local dragThreshold = 8 -- pixels moved sebelum dianggap dragging

    floatBtn.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isPressed = true
            isDragging = false
            dragStart = input.Position
            startPos = floatBtn.Position
            uiscale.Scale = 0.92
            floatBtn.BackgroundColor3 = Color3.fromRGB(10, 85, 190)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if isPressed and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local currentPos = input.Position
            local delta = currentPos - dragStart
            if not isDragging then
                if math.abs(delta.X) > dragThreshold or math.abs(delta.Y) > dragThreshold then
                    isDragging = true
                end
            end
            if isDragging and startPos then
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
                local btnSize = 42
                local curX = startPos.X.Scale * vp.X + startPos.X.Offset + delta.X
                local curY = startPos.Y.Scale * vp.Y + startPos.Y.Offset + delta.Y

                -- Clamp agar tombol tidak bisa ditarik keluar dari layar (aman di semua device/layar HP)
                curX = math.clamp(curX, btnSize, vp.X)
                curY = math.clamp(curY, btnSize / 2, vp.Y - btnSize / 2)

                floatBtn.Position = UDim2.fromOffset(curX, curY)
            end
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if isPressed then
                isPressed = false
                uiscale.Scale = 1.0
                floatBtn.BackgroundColor3 = Color3.fromRGB(12, 110, 240)

                -- Jika tidak dragging, berarti tap/klik -> Toggle UI!
                if not isDragging then
                    if Sfx and Sfx.play then pcall(Sfx.play, "click") end
                    toggleMainDialog()
                end
                isDragging = false
            end
        end
    end)
end

