--  TAB NAVIGATION BAR (NATIVE GAZETTE STYLE)
-- ═══════════════════════════════════════
local tabData = {
    { key = "player",   label = "PLAYER",   itemId = 32 },   -- Wrench
    { key = "farm",     label = "FARM",     itemId = 3 },    -- Seed
    { key = "factory",  label = "FACTORY",  itemId = 10 },   -- Rock
    { key = "rotation", label = "ROTATION", itemId = 6 },    -- Door
    { key = "shop",     label = "SHOP",     itemId = 112 },  -- Gems
    { key = "event",    label = "EVENT",    itemId = 4 },    -- Lava (Burn Rarity)
    { key = "world",    label = "WORLD",    itemId = 242 },  -- World Lock
    { key = "spam",     label = "SPAM",     itemId = 18 },   -- Fist
    { key = "proxy",    label = "PROXY",    itemId = 1796 }, -- Diamond Lock
}

local TabBar = Instance.new("Frame", MainDialog)
TabBar.Name                   = "TabBar"
TabBar.Size                   = UDim2.new(1, -40, 0, 40)
TabBar.Position               = UDim2.fromOffset(20, 102)
TabBar.BackgroundTransparency = 1

local tabButtons = {}
local tabWidth = math.floor((720 - 40 - (#tabData - 1) * 8) / #tabData)

-- Container for Content Pages
local PagesContainer = Instance.new("Frame", MainDialog)
PagesContainer.Name                   = "PagesContainer"
PagesContainer.Size                   = UDim2.new(1, -40, 1, -232)
PagesContainer.Position               = UDim2.fromOffset(20, 148)
PagesContainer.BackgroundColor3       = C.dark
PagesContainer.BackgroundTransparency = 0.55
PagesContainer.BorderSizePixel        = 0
corner(PagesContainer, 8)
stroke(PagesContainer, C.rim, 2)

pages = {}

do
    local function createPage(key)
        local sf = Instance.new("ScrollingFrame", PagesContainer)
        sf.Name                   = "Page_" .. key
        sf.Size                   = UDim2.fromScale(1, 1)
        sf.BackgroundTransparency = 1
        sf.BorderSizePixel        = 0
        sf.ScrollBarThickness     = 8
        sf.ScrollBarImageColor3   = C.rim
        sf.ScrollingDirection     = Enum.ScrollingDirection.Y
        sf.AutomaticCanvasSize    = Enum.AutomaticSize.Y
        sf.CanvasSize             = UDim2.new()
        sf.Visible                = false

        local pad = Instance.new("UIPadding", sf)
        pad.PaddingLeft   = UDim.new(0, 12)
        pad.PaddingRight  = UDim.new(0, 16)
        pad.PaddingTop    = UDim.new(0, 10)
        pad.PaddingBottom = UDim.new(0, 14)

        local layout = Instance.new("UIListLayout", sf)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding   = UDim.new(0, 8)

        pages[key] = sf
        return sf
    end

    for _, t in ipairs(tabData) do
        createPage(t.key)
    end
end

local activeTabKey = "player"

switchTab = function(tabKey)
    activeTabKey = tabKey
    for _, t in ipairs(tabData) do
        local isCurrent = (t.key == tabKey)
        local btnObj = tabButtons[t.key]
        if btnObj then
            btnObj.btn.BackgroundColor3 = isCurrent and C.green or C.button
        end
        if pages[t.key] then
            pages[t.key].Visible = isCurrent
        end
    end
    if tabKey == "rotation" and updateRotationUI then
        pcall(updateRotationUI)
    end
    if tabKey == "shop" and AutoShop.updateUI then
        pcall(AutoShop.updateUI)
    end
    if tabKey == "event" and updateEventUI then
        pcall(updateEventUI)
    end
    if not (Proxy and Proxy._isLoadingConfig) then
        if Proxy and Proxy.saveConfig then
            task.spawn(Proxy.saveConfig)
        end
    end
end
getgenv().SysHubSwitchTab = switchTab

for i, t in ipairs(tabData) do
    local btnTuple = { makeButton(
        TabBar,
        t.label,
        12,
        (t.key == activeTabKey) and C.green or C.button,
        4,
        42,
        function()
            switchTab(t.key)
        end,
        tabWidth
    ) }
    btnTuple[1].Position = UDim2.fromOffset((i - 1) * (tabWidth + 8), 0)
    local btnFrame = btnTuple[1]
    local btnObj = btnTuple[3]
    local btnLbl = btnTuple[4]

    -- Native game item icon untuk setiap tab
    if ItemIcon and ItemIcon.new and t.itemId then
        local icon = ItemIcon.new(btnObj, UDim2.fromOffset(16, 16), 3)
        local totalW = 16 + 4 + (btnLbl.contentWidth or 40)
        local startX = math.max(2, math.floor((tabWidth - totalW) / 2))
        icon.frame.AnchorPoint = Vector2.new(0, 0.5)
        icon.frame.Position = UDim2.new(0, startX, 0.5, 0)
        ItemIcon.set(icon, t.itemId)
        if btnLbl and btnLbl.frame then
            btnLbl.frame.AnchorPoint = Vector2.new(0, 0.5)
            btnLbl.frame.Position = UDim2.new(0, startX + 19, 0.5, 0)
        end
    end

    tabButtons[t.key] = { frame = btnFrame, btn = btnObj, label = btnLbl }
end

