    local lblWorld = makeLabel(row1, "`e[World: -]``", 18, UDim2.fromOffset(134, 2))

    -- Eye Toggle Button (Streamer / Privacy Mode: Sembunyikan Nama Player)
    local btnEyePlayer = Instance.new("TextButton", row1)
    btnEyePlayer.Name = "BtnEyePlayer"
    btnEyePlayer.Size = UDim2.fromOffset(22, 20)
    btnEyePlayer.Position = UDim2.fromOffset(236, 2)
    btnEyePlayer.BackgroundColor3 = (Proxy and Proxy.hidePlayerName) and C.rim or C.box
    btnEyePlayer.BorderSizePixel = 0
    btnEyePlayer.Text = (Proxy and Proxy.hidePlayerName) and "🔒" or "👁"
    btnEyePlayer.TextSize = 13
    btnEyePlayer.TextColor3 = Color3.new(1, 1, 1)
    btnEyePlayer.ZIndex = 5
    corner(btnEyePlayer, 4)
    stroke(btnEyePlayer, C.rim, 1)

    if Proxy then
        Proxy.btnEyeWorld = btnEye
        Proxy.btnEyePlayer = btnEyePlayer
    end

    local lblPlayer = makeLabel(row1, "`w| Player``", 18, UDim2.fromOffset(262, 2))
    local lblLevel = makeLabel(row1, "`eLv. 1``", 18, UDim2.fromOffset(380, 2))

    -- EXP Progress Bar
    local expBg = Instance.new("Frame", row1)
    expBg.Name = "ExpBg"
    expBg.Size = UDim2.fromOffset(70, 10)
    expBg.Position = UDim2.fromOffset(432, 7)
    expBg.BackgroundColor3 = C.rimInner
    expBg.BorderSizePixel = 0
    corner(expBg, 3)

    local expFill = Instance.new("Frame", expBg)
    expFill.Name = "ExpFill"
    expFill.Size = UDim2.fromScale(0, 1)
    expFill.BackgroundColor3 = Color3.fromRGB(255, 175, 20)
    expFill.BorderSizePixel = 0
    corner(expFill, 3)

    local expText = makeLabel(row1, "`o(0/0)``", 14, UDim2.fromOffset(508, 4))

    local lastEyeWorldClick = 0
    local function toggleEyeWorld()
        local now = os.clock()
        if now - lastEyeWorldClick < 0.2 then return end
        lastEyeWorldClick = now

        if Proxy then
            Proxy.hideWorldName = not Proxy.hideWorldName
            btnEye.Text = Proxy.hideWorldName and "🔒" or "👁"
            btnEye.BackgroundColor3 = Proxy.hideWorldName and C.rim or C.box
            local px, py = getPlayerTilePos()
            local pickerOpen = isWorldPickerOpen and isWorldPickerOpen()
            local w = not pickerOpen and getNativeWorld() or nil
            local worldName = pickerOpen and "WORLD LIST" or ((w and w.name) or "World")
            if Proxy.updateHudRow1 then
                Proxy.updateHudRow1(px, py, worldName)
            end
            if Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end
    btnEye.MouseButton1Click:Connect(toggleEyeWorld)

    local lastEyePlayerClick = 0
    local function toggleEyePlayer()
        local now = os.clock()
        if now - lastEyePlayerClick < 0.2 then return end
        lastEyePlayerClick = now

        if Proxy then
            Proxy.hidePlayerName = not Proxy.hidePlayerName
            btnEyePlayer.Text = Proxy.hidePlayerName and "🔒" or "👁"
            btnEyePlayer.BackgroundColor3 = Proxy.hidePlayerName and C.rim or C.box
            local px, py = getPlayerTilePos()
            local pickerOpen = isWorldPickerOpen and isWorldPickerOpen()
            local w = not pickerOpen and getNativeWorld() or nil
            local worldName = pickerOpen and "WORLD LIST" or ((w and w.name) or "World")
            if Proxy.updateHudRow1 then
                Proxy.updateHudRow1(px, py, worldName)
            end
            if Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end
    btnEyePlayer.MouseButton1Click:Connect(toggleEyePlayer)

    -- ROW 2 (Y = 34): Status (Kiri) & Currencies dengan ItemIcon Native (Kanan)
    local row2 = Instance.new("Frame", Footer)
    row2.Name = "Row2"
    row2.BackgroundTransparency = 1
    row2.Size = UDim2.new(1, -16, 0, 24)
    row2.Position = UDim2.fromOffset(8, 35)

    lblStatus = makeLabel(row2, "`oStatus: Idle``", 18, UDim2.fromOffset(2, 2))

    -- Currency Container di sebelah kanan (Gems, WL, DL, BGL)
    local currContainer = Instance.new("Frame", row2)
    currContainer.Name = "Currencies"
    currContainer.BackgroundTransparency = 1
    currContainer.Size = UDim2.new(0, 360, 1, 0)
    currContainer.Position = UDim2.new(1, 0, 0, 0)
    currContainer.AnchorPoint = Vector2.new(1, 0)

    local cItems = {
        { id = 112,  key = "gems", color = "`#" }, -- Gems
        { id = 242,  key = "wl",   color = "`e" }, -- World Lock
        { id = 1796, key = "dl",   color = "`b" }, -- Diamond Lock
        { id = 7188, key = "bgl",  color = "`q" }, -- Blue Gem Lock
    }

    local hudCurrencies = {}
    local slotW = 90
    for idx, ci in ipairs(cItems) do
        local cFrame = Instance.new("Frame", currContainer)
        cFrame.Name = "Curr_" .. ci.key
        cFrame.BackgroundTransparency = 1
        cFrame.Size = UDim2.fromOffset(slotW, 22)
        cFrame.Position = UDim2.fromOffset((idx - 1) * slotW, 0)

        if ItemIcon and ItemIcon.new then
            local icon = ItemIcon.new(cFrame, UDim2.fromOffset(16, 16), 2)
            icon.frame.AnchorPoint = Vector2.new(0, 0.5)
            icon.frame.Position = UDim2.new(0, 2, 0.5, 0)
            ItemIcon.set(icon, ci.id)
        end

        local cLbl = makeLabel(cFrame, ci.color .. "0``", 16, UDim2.new(0, 22, 0.5, 0), {anchor = Vector2.new(0, 0.5)})
        hudCurrencies[ci.key] = cLbl
    end

    Proxy.updateHudRow1 = function(px, py, rawWorldName)
        local pickerOpen = isWorldPickerOpen and isWorldPickerOpen()
        if px and py and not pickerOpen then
            lblLivePos:set(string.format("`cPos: (%d, %d)``", px + 1, py + 1))
        else
            lblLivePos:set("`oPos: (-, -)``")
        end

        local displayWorld = pickerOpen and "WORLD LIST" or (rawWorldName or "-")
        if not pickerOpen and Proxy and Proxy.hideWorldName and displayWorld ~= "WORLD LIST" and displayWorld ~= "-" then
            displayWorld = "***"
        end
        lblWorld:set(string.format((not pickerOpen and Proxy and Proxy.hideWorldName) and "`o[%s]``" or "`e[%s]``", displayWorld))

        local lp = Players.LocalPlayer
        local activeNick = (lp and lp:GetAttribute("Nick")) or (Proxy and Proxy.fakeNick) or (lp and (lp.DisplayName or lp.Name)) or "Player"
        if Proxy and Proxy.hidePlayerName then
            lblPlayer:set("`o| [***]``")
        else
            if #activeNick > 12 then activeNick = string.sub(activeNick, 1, 11) .. "." end
            lblPlayer:set("`w| " .. activeNick .. "``")
        end

        if Proxy then
            if Proxy.btnEyeWorld then
                Proxy.btnEyeWorld.Text = Proxy.hideWorldName and "🔒" or "👁"
                Proxy.btnEyeWorld.BackgroundColor3 = Proxy.hideWorldName and C.rim or C.box
            end
            if Proxy.btnEyePlayer then
                Proxy.btnEyePlayer.Text = Proxy.hidePlayerName and "🔒" or "👁"
                Proxy.btnEyePlayer.BackgroundColor3 = Proxy.hidePlayerName and C.rim or C.box
            end
        end

        lblLevel:set(string.format("`eLv. %d``", (Proxy and Proxy.cachedPlayerLevel) or 1))

        local curE = (Proxy and Proxy.cachedCurExp) or 0
        local maxE = (Proxy and Proxy.cachedMaxExp) or 0
        local ratio = (maxE > 0) and math.clamp(curE / maxE, 0, 1) or 0
        if expFill then
            expFill.Size = UDim2.fromScale(ratio, 1)
        end
        if expText then
            expText:set(string.format("`o(%d/%d)``", curE, maxE))
        end
    end

    -- Background loop updater for Economy (Gems, WL, DL, BGL) and Level / EXP
    task.spawn(function()
        local function fmtComma(n)
            local s = tostring(math.floor(n or 0))
            local k
            while true do
                s, k = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2")
                if k == 0 then break end
            end
            return s
        end

        while true do
            task.wait(1.0)
            pcall(function()
                if Net and Net.call then
                    local okGems, gems = pcall(Net.call, "GetGems")
                    if okGems and type(gems) == "number" then
                        Proxy.cachedGemsCount = gems
                        if hudCurrencies.gems and hudCurrencies.gems.set then
                            hudCurrencies.gems:set(string.format("`#%s``", fmtComma(gems)))
                        end
                    end
                    local okLvl, lvl, curExp, maxExp = pcall(Net.call, "GetLevel")
                    if okLvl and type(lvl) == "number" then
                        Proxy.cachedPlayerLevel = lvl
                        Proxy.cachedCurExp = curExp or 0
                        Proxy.cachedMaxExp = maxExp or 0
                    end
                end
                local inv = getNativeInventory()
                if inv and inv.count then
                    local wl = inv:count(242) or 0
                    local dl = inv:count(1796) or 0
                    local bgl = inv:count(7188) or 0
                    if hudCurrencies.wl and hudCurrencies.wl.set then
                        hudCurrencies.wl:set(string.format("`e%s``", fmtComma(wl)))
                    end
                    if hudCurrencies.dl and hudCurrencies.dl.set then
                        hudCurrencies.dl:set(string.format("`b%s``", fmtComma(dl)))
                    end
                    if hudCurrencies.bgl and hudCurrencies.bgl.set then
                        hudCurrencies.bgl:set(string.format("`q%s``", fmtComma(bgl)))
                    end
                end
            end)
        end
    end)
end
end

-- Forward variables for PNB Page
inpItemId = nil
inpHits = nil
inpHitDelay = nil

-- ═══════════════════════════════════════
--  PAGE 1: PLAYER (HAZARDS & MOBILITY)
-- ═══════════════════════════════════════
local Setups = {}
Setups.player = function(page)
    -- Section 1: Anti-Bounce & Hazard (Lava & Spikes)
    local secHazard = createSection(page, "Anti-Bounce & Hazard (Lava & Spikes)", true, 1)

    local lblHazardStatus = nil
    local btnHazardFrame, btnHazard, btnHazardLabel
    btnHazardFrame, _, btnHazard, btnHazardLabel = makeButton(
        secHazard.body,
        "Anti-Hazard: OFF",
        20,
        C.button,
        8,
        38,
        function()
            AntiHazard.enabled = not AntiHazard.enabled
            applyAntiHazard()
            if AntiHazard.enabled then
                btnHazard.BackgroundColor3 = C.green
                btnHazardLabel:set("Anti-Hazard: ON")
                secHazard.setBadge("`2[ACTIVE]``")
                if lblHazardStatus then
                    lblHazardStatus:set("`2Status: Aktif | Kebal Lava, Spikes & Jamur``")
                end
            else
                btnHazard.BackgroundColor3 = C.button
                btnHazardLabel:set("Anti-Hazard: OFF")
                secHazard.setBadge("`o[OFF]``")
                if lblHazardStatus then
                    lblHazardStatus:set("`oStatus: Nonaktif | Normal Game Physics``")
                end
            end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secHazard.setBadge("`o[OFF]``")

    local cbAntiLava = checkbox(secHazard.body, "`oAnti-Lava (No Damage & No Bounce)``", UDim2.new(), function(val)
        AntiHazard.antiLava = val
        if AntiHazard.enabled then applyAntiHazard() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, AntiHazard.antiLava ~= false)

    local cbAntiSpikes = checkbox(secHazard.body, "`oAnti-Spikes & Deadly (Kebal Spikes / Mati)``", UDim2.new(), function(val)
        AntiHazard.antiDeadly = val
        if AntiHazard.enabled then applyAntiHazard() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, AntiHazard.antiDeadly ~= false)

    local cbAntiBounce = checkbox(secHazard.body, "`oAnti-Bounce Jamur & Trampoline (No Jump)``", UDim2.new(), function(val)
        AntiHazard.antiBounce = val
        if AntiHazard.enabled then applyAntiHazard() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, AntiHazard.antiBounce ~= false)

    local cbAntiLaser = checkbox(secHazard.body, "`oAnti-Laser & Pinball Bumpers``", UDim2.new(), function(val)
        AntiHazard.antiLaser = val
        AntiHazard.antiBumper = val
        if AntiHazard.enabled then applyAntiHazard() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, AntiHazard.antiLaser ~= false)

    lblHazardStatus = makeLabel(secHazard.body, "`oStatus: Standby | Kebal Lava, Spikes & Jamur``", 18, UDim2.new())

    -- Section 4: Click-to-Pathfind (Navigasi Klik Layar)
    local secClickPath = createSection(page, "Click-to-Pathfind (Navigasi Klik Layar)", false, 2)

    local btnClickPathFrame, btnClickPath, btnClickPathLabel
    btnClickPathFrame, _, btnClickPath, btnClickPathLabel = makeButton(
        secClickPath.body,
        "Shift + Click Pathfind: OFF",
        20,
        C.button,
        8,
        38,
        function()
            ClickPathfind.enabled = not ClickPathfind.enabled
            if ClickPathfind.enabled then
                btnClickPath.BackgroundColor3 = C.cyan
                if btnClickPathLabel and btnClickPathLabel.set then
                    btnClickPathLabel:set("Shift + Click Pathfind: ON")
                end
                secClickPath.setBadge("`c[ACTIVE]``")
                if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
                    ClickPathfind.lblStatus:set("`2Status: Standby | Tahan [SHIFT] untuk memunculkan grid & klik tile``")
                end
                toggleClickPathfindGrid(true)
            else
                if ClickPathfind.thread then
                    task.cancel(ClickPathfind.thread)
                    ClickPathfind.thread = nil
                end
                ClickPathfind.busy = false
                btnClickPath.BackgroundColor3 = C.button
                if btnClickPathLabel and btnClickPathLabel.set then
                    btnClickPathLabel:set("Shift + Click Pathfind: OFF")
                end
                secClickPath.setBadge("`o[OFF]``")
                if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
                    ClickPathfind.lblStatus:set("`oStatus: Nonaktif | Standby``")
                end
                toggleClickPathfindGrid(false)
            end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secClickPath.setBadge("`o[OFF]``")

    makeLabel(secClickPath.body, "`oTahan tombol [SHIFT] di keyboard untuk memunculkan grid tile transparan, lalu klik tile tujuan untuk jalan otomatis!``", 17, UDim2.new())
    ClickPathfind.lblStatus = makeLabel(secClickPath.body, "`oStatus: Standby | Tahan [SHIFT] lalu klik tile di layar``", 18, UDim2.new())

    -- Section 5: Speed Mode (Super Run / Multiplier)
    local secSpeed = createSection(page, "Speed Mode (Kecepatan Gerak / Run)", false, 3)

    local lblSpeedVal = nil
    local updateSpeedDisplay = function()
        if lblSpeedVal then
            lblSpeedVal:set(string.format("`wKecepatan: `2%.1fx``  `o(Normal: 1.0x)``", Mobility.speedMultiplier))
        end
    end

    local btnSpeedFrame, btnSpeed, btnSpeedLabel
    btnSpeedFrame, _, btnSpeed, btnSpeedLabel = makeButton(
        secSpeed.body,
        "Speed Mode: OFF",
        20,
        C.button,
        8,
        38,
        function()
            Mobility.speedEnabled = not Mobility.speedEnabled
            applySpeedMode()
            if Mobility.speedEnabled then
                btnSpeed.BackgroundColor3 = C.green
                btnSpeedLabel:set("Speed Mode: ON")
                secSpeed.setBadge(string.format("`2[%.1fx]``", Mobility.speedMultiplier))
            else
                btnSpeed.BackgroundColor3 = C.button
                btnSpeedLabel:set("Speed Mode: OFF")
                secSpeed.setBadge("`o[OFF]``")
            end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secSpeed.setBadge("`o[OFF]``")

    lblSpeedVal = makeLabel(secSpeed.body, string.format("`wKecepatan: `2%.1fx``  `o(Normal: 1.0x)``", Mobility.speedMultiplier), 19, UDim2.new())

    -- Preset Speed Buttons Row
    local presetRow = Instance.new("Frame", secSpeed.body)
    presetRow.Size               = UDim2.new(1, 0, 0, 32)
    presetRow.BackgroundTransparency = 1

    local speedPresets = {
        { val = 1.0, label = "1.0x" },
        { val = 1.5, label = "1.5x" },
        { val = 2.0, label = "2.0x" },
        { val = 2.5, label = "2.5x" },
        { val = 3.0, label = "3.0x" },
        { val = 4.0, label = "4.0x" },
    }
    local presetBtns = {}
    local pWidth = 88
    for i, sp in ipairs(speedPresets) do
        local isSel = math.abs(Mobility.speedMultiplier - sp.val) < 0.05
        local pf, _, pb = makeButton(
            presetRow,
            sp.label,
            18,
            isSel and C.green or C.button,
            4,
            30,
            function()
                Mobility.speedMultiplier = sp.val
                applySpeedMode()
                updateSpeedDisplay()
                if Mobility.speedEnabled then
                    secSpeed.setBadge(string.format("`2[%.1fx]``", sp.val))
                end
                for _, other in ipairs(speedPresets) do
                    if presetBtns[other.val] then
                        presetBtns[other.val].BackgroundColor3 = (math.abs(Mobility.speedMultiplier - other.val) < 0.05) and C.green or C.button
                    end
                end
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end,
            pWidth
        )
        pf.Position = UDim2.fromOffset((i - 1) * (pWidth + 6), 0)
        presetBtns[sp.val] = pb
    end

    -- Interactive Slider Bar
    local sliderBg = Instance.new("Frame", secSpeed.body)
    sliderBg.Name                   = "SpeedSliderBg"
    sliderBg.Size                   = UDim2.new(1, -20, 0, 16)
    sliderBg.BackgroundColor3       = C.dark
    sliderBg.BorderSizePixel        = 0
    corner(sliderBg, 8)
    stroke(sliderBg, C.fieldRim, 1)

    local sliderFill = Instance.new("Frame", sliderBg)
    sliderFill.Name                   = "Fill"
    local initRatio = math.clamp((Mobility.speedMultiplier - 1.0) / 4.0, 0, 1)
    sliderFill.Size                   = UDim2.new(initRatio, 0, 1, 0)
    sliderFill.BackgroundColor3       = C.cyan
    sliderFill.BorderSizePixel        = 0
    corner(sliderFill, 8)

    local sliderBtn = Instance.new("TextButton", sliderBg)
    sliderBtn.Size                   = UDim2.fromScale(1, 1)
    sliderBtn.BackgroundTransparency = 1
    sliderBtn.Text                   = ""

    local dragging = false
    local function updateSliderFromX(x)
        local relX = math.clamp(x - sliderBg.AbsolutePosition.X, 0, sliderBg.AbsoluteSize.X)
        local ratio = (sliderBg.AbsoluteSize.X > 0) and (relX / sliderBg.AbsoluteSize.X) or 0
        local newSpd = math.round((1.0 + ratio * 4.0) * 10) / 10
        Mobility.speedMultiplier = newSpd
        sliderFill.Size = UDim2.new(ratio, 0, 1, 0)
        applySpeedMode()
        updateSpeedDisplay()
        if Mobility.speedEnabled then
            secSpeed.setBadge(string.format("`2[%.1fx]``", newSpd))
        end
        for _, other in ipairs(speedPresets) do
            if presetBtns[other.val] then
                presetBtns[other.val].BackgroundColor3 = (math.abs(Mobility.speedMultiplier - other.val) < 0.05) and C.green or C.button
            end
        end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end

    sliderBtn.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            updateSliderFromX(input.Position.X)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            updateSliderFromX(input.Position.X)
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    -- Section 6: Fast Inventory (Drop & Recycle)
    local secFastInv = createSection(page, "Fast Inventory (Drop & Recycle)", false, 4)

    local lblFastInvStatus = nil
    local function updateFastInvStatus()
        if not lblFastInvStatus then return end
        local dropMode = FastInventory.fastDrop and (FastInventory.customCountEnabled and string.format("`2ON (%d)``", FastInventory.customCount) or "`2ON (Semua)``") or "`oOFF``"
        local recMode = FastInventory.fastRecycle and (FastInventory.customCountEnabled and string.format("`2ON (%d)``", FastInventory.customCount) or "`2ON (Semua)``") or "`oOFF``"
        lblFastInvStatus:set(string.format("`oStatus: Drop: %s `o| Recycle: %s", dropMode, recMode))
    end

    local btnDropFrame, btnDrop, btnDropLabel
    btnDropFrame, _, btnDrop, btnDropLabel = makeButton(
        secFastInv.body,
        "Fast Drop: OFF",
        20,
        C.button,
        8,
        38,
        function()
            FastInventory.fastDrop = not FastInventory.fastDrop
            ensureFastInventoryOverlays()
            if FastInventory.fastDrop then
                btnDrop.BackgroundColor3 = C.green
                btnDropLabel:set("Fast Drop: ON")
                secFastInv.setBadge("`2[ACTIVE]``")
            else
                btnDrop.BackgroundColor3 = C.button
                btnDropLabel:set("Fast Drop: OFF")
                if not FastInventory.fastRecycle then
                    secFastInv.setBadge("`o[OFF]``")
                end
            end
            updateFastInvStatus()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )

    local btnRecycleFrame, btnRecycle, btnRecycleLabel
    btnRecycleFrame, _, btnRecycle, btnRecycleLabel = makeButton(
        secFastInv.body,
        "Fast Trash / Recycle: OFF",
        20,
        C.button,
        8,
        38,
        function()
            FastInventory.fastRecycle = not FastInventory.fastRecycle
            ensureFastInventoryOverlays()
            if FastInventory.fastRecycle then
                btnRecycle.BackgroundColor3 = C.red
                btnRecycleLabel:set("Fast Trash / Recycle: ON")
                secFastInv.setBadge("`2[ACTIVE]``")
            else
                btnRecycle.BackgroundColor3 = C.button
                btnRecycleLabel:set("Fast Trash / Recycle: OFF")
                if not FastInventory.fastDrop then
                    secFastInv.setBadge("`o[OFF]``")
                end
            end
            updateFastInvStatus()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secFastInv.setBadge("`o[OFF]``")

    -- Checkbox Custom Count Drop / Recycle
    local cbCustomCount = checkbox(secFastInv.body, "`oCustom Count Drop/Recycle (Uncheck: Drop Semua Stack)``", UDim2.new(), function(val)
        FastInventory.customCountEnabled = val
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, FastInventory.customCountEnabled == true)

    -- Row for custom count input
    local countRow = Instance.new("Frame", secFastInv.body)
    countRow.Size = UDim2.new(1, 0, 0, 36)
    countRow.BackgroundTransparency = 1

    local lblCount = makeLabel(countRow, "`wJumlah Item:``", 18, UDim2.new(0, 0, 0, 8))

    local countBox = Instance.new("TextBox", countRow)
    countBox.Size = UDim2.new(0, 100, 0, 30)
    countBox.Position = UDim2.new(0, 115, 0, 3)
    countBox.BackgroundColor3 = C.field
    countBox.BorderSizePixel = 0
    countBox.Font = Enum.Font.FredokaOne
    countBox.TextSize = 18
    countBox.TextColor3 = C.text
    countBox.Text = tostring(FastInventory.customCount or 1)
    countBox.ClearTextOnFocus = false
    corner(countBox, 6)
    stroke(countBox, C.fieldRim, 1)

    countBox.FocusLost:Connect(function()
        local num = tonumber(countBox.Text)
        if num and num > 0 then
            FastInventory.customCount = math.floor(num)
        else
            FastInventory.customCount = 1
            countBox.Text = "1"
        end
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Quick Adjust Buttons (+1, +10, +50, Reset)
    local function makeQuickBtn(xOff, text, w, cb)
        local f, _, b = makeButton(countRow, text, 16, C.button, 4, 30, cb, w)
        f.Position = UDim2.new(0, xOff, 0, 3)
        return b
    end

    makeQuickBtn(225, "+1", 38, function()
        FastInventory.customCount = (FastInventory.customCount or 1) + 1
        countBox.Text = tostring(FastInventory.customCount)
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeQuickBtn(269, "+10", 46, function()
        FastInventory.customCount = (FastInventory.customCount or 1) + 10
        countBox.Text = tostring(FastInventory.customCount)
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeQuickBtn(321, "+50", 46, function()
        FastInventory.customCount = (FastInventory.customCount or 1) + 50
        countBox.Text = tostring(FastInventory.customCount)
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeQuickBtn(373, "Reset", 52, function()
        FastInventory.customCount = 1
        countBox.Text = "1"
        updateFastInvStatus()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    lblFastInvStatus = makeLabel(secFastInv.body, "`oStatus: Standby | Drop: OFF | Recycle: OFF``", 18, UDim2.new())
    makeLabel(secFastInv.body, "`oKlik DROP atau RECYCLE di tas/inventory langsung jalan instan tanpa konfirmasi dialog!``", 17, UDim2.new())

    -- Section 7: Infinite Zoom Out Camera (World View)
    local secZoom = createSection(page, "Camera Zoom (Bawaan Game Unlocked)", false, 5)

    local btnZoomFrame, btnZoom, btnZoomLabel
    local lblZoomStatus = nil
    local zoomPresetBtns = {}

    local function updateZoomUIElements()
        if btnZoom and btnZoomLabel then
            btnZoom.BackgroundColor3 = CameraZoom.enabled and C.cyan or C.button
            btnZoomLabel:set(CameraZoom.enabled and "Infinite Zoom: ON" or "Unlock Zoom: OFF")
        end
        if secZoom and secZoom.setBadge then
            secZoom.setBadge(CameraZoom.enabled and "`c[ACTIVE]``" or "`o[OFF]``")
        end
        if lblZoomStatus and lblZoomStatus.set then
            if CameraZoom.enabled then
                local pct = math.round(CameraZoom.zoomScale * 100)
                lblZoomStatus:set(string.format("`2Status: Aktif (Batas Game Unlocked) | Scale: %.2f (%d%%)``", CameraZoom.zoomScale, pct))
            else
                lblZoomStatus:set("`oStatus: Nonaktif | Normal Game Camera``")
            end
        end
        for scaleVal, btnRef in pairs(zoomPresetBtns) do
            if btnRef then
                local isCur = math.abs((CameraZoom.zoomScale or 0.5) - scaleVal) < 0.03
                btnRef.BackgroundColor3 = isCur and C.green or C.button
            end
        end
    end
    CameraZoom.updateUI = updateZoomUIElements

    btnZoomFrame, _, btnZoom, btnZoomLabel = makeButton(
        secZoom.body,
        "Infinite Zoom: OFF",
        20,
        C.button,
        8,
        38,
        function()
            CameraZoom.enabled = not CameraZoom.enabled
            CameraZoom.apply()
            updateZoomUIElements()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secZoom.setBadge("`o[OFF]``")

    lblZoomStatus = makeLabel(secZoom.body, "`oStatus: Nonaktif | Normal Game Camera``", 18, UDim2.new())

    makeLabel(secZoom.body, "`9Preset Zoom Cepat:``", 17, UDim2.new())

    local presetRow = Instance.new("Frame")
    presetRow.Name = "ZoomPresetRow"
    presetRow.Size = UDim2.new(1, 0, 0, 32)
    presetRow.BackgroundTransparency = 1
    presetRow.Parent = secZoom.body

    local presets = {
        { name = "25% Ultra", scale = 0.25 },
        { name = "50% Wide",  scale = 0.50 },
        { name = "75% Mid",   scale = 0.75 },
        { name = "100% Norm", scale = 1.00 },
        { name = "150% Close", scale = 1.50 },
    }
    for idx, pr in ipairs(presets) do
        local pFrame, _, pBtn, _ = makeButton(
            presetRow,
            pr.name,
            16,
            C.button,
            6,
            28,
            function()
                CameraZoom.enabled = true
                CameraZoom.zoomScale = pr.scale
                CameraZoom.apply()
                updateZoomUIElements()
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end
        )
        pFrame.Size = UDim2.new(0.185, 0, 0, 28)
        pFrame.Position = UDim2.new((idx - 1) * 0.205, 0, 0, 0)
        zoomPresetBtns[pr.scale] = pBtn
    end

    local adjRow = Instance.new("Frame")
    adjRow.Name = "ZoomAdjRow"
    adjRow.Size = UDim2.new(1, 0, 0, 32)
    adjRow.BackgroundTransparency = 1
    adjRow.Parent = secZoom.body

    local fMinus, _, _, _ = makeButton(adjRow, "[-] Zoom Out (-5%)", 16, C.button, 6, 28, function()
        CameraZoom.enabled = true
        CameraZoom.zoomScale = math.clamp(math.round((CameraZoom.zoomScale - 0.05) * 100) / 100, 0.1, 2.5)
        CameraZoom.apply()
        updateZoomUIElements()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)
    fMinus.Size = UDim2.new(0.485, 0, 0, 28)
    fMinus.Position = UDim2.new(0, 0, 0, 0)

    local fPlus, _, _, _ = makeButton(adjRow, "[+] Zoom In (+5%)", 16, C.button, 6, 28, function()
        CameraZoom.enabled = true
        CameraZoom.zoomScale = math.clamp(math.round((CameraZoom.zoomScale + 0.05) * 100) / 100, 0.1, 2.5)
        CameraZoom.apply()
        updateZoomUIElements()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)
    fPlus.Size = UDim2.new(0.485, 0, 0, 28)
    fPlus.Position = UDim2.new(0.515, 0, 0, 0)

    makeLabel(secZoom.body, "`oTips: Batas zoom bawaan game dibuka (zoomMin 0.08)! Scroll Mouse Wheel bebas tanpa offset error!``", 16, UDim2.new())

    -- Section 8: Anti-Staff & Moderator Protection
    local secAntiStaff = createSection(page, "Anti-Staff & Moderator Protection", true, 6)

    local btnAntiStaffFrame, btnAntiStaff, btnAntiStaffLabel
    local lblAntiStaffStatus = nil
    local lblStaffList = nil
    local cbAutoFreeze = nil
    local cbAutoKick = nil

    local function updateAntiStaffUIElements()
        if btnAntiStaff and btnAntiStaffLabel then
            btnAntiStaff.BackgroundColor3 = AntiStaff.enabled and C.green or C.button
            btnAntiStaffLabel:set(AntiStaff.enabled and "Anti-Staff: AKTIF (Protected)" or "Anti-Staff: NONAKTIF")
        end
        if secAntiStaff and secAntiStaff.setBadge then
            if AntiStaff.isFrozen then
                secAntiStaff.setBadge("`4[FREEZE ALERT!]``")
            elseif AntiStaff.enabled then
                secAntiStaff.setBadge("`2[PROTECTED]``")
            else
                secAntiStaff.setBadge("`o[OFF]``")
            end
        end
        if lblAntiStaffStatus and lblAntiStaffStatus.set then
            if not AntiStaff.enabled then
                lblAntiStaffStatus:set("`oStatus: Sistem Nonaktif (Tidak ada proteksi)``")
            elseif AntiStaff.isFrozen then
                local staffNames = {}
                for _, s in pairs(AntiStaff.detectedStaff or {}) do
                    table.insert(staffNames, string.format("%s (%s)", s.name, s.role))
                end
                local listStr = (#staffNames > 0) and table.concat(staffNames, ", ") or "Staff"
                lblAntiStaffStatus:set(string.format("`4[!] AWAS: Staff '%s' ada di World! KARAKTER MEMATUNG (FREEZE)``", listStr))
            else
                lblAntiStaffStatus:set("`2Status: Aman | Memantau seluruh player di world (Auto-Freeze / Kick)``")
            end
        end
        if lblStaffList and lblStaffList.set then
            local count = 0
            for _ in pairs(AntiStaff.detectedStaff or {}) do count = count + 1 end
            lblStaffList:set(string.format("`9Staff Terdeteksi di World: %d orang``", count))
        end
        if cbAutoFreeze and cbAutoFreeze.set then cbAutoFreeze.set(AntiStaff.autoFreeze ~= false) end
        if cbAutoKick and cbAutoKick.set then cbAutoKick.set(AntiStaff.autoKick == true) end
    end
    AntiStaff.updateUI = updateAntiStaffUIElements

    btnAntiStaffFrame, _, btnAntiStaff, btnAntiStaffLabel = makeButton(
        secAntiStaff.body,
        "Anti-Staff: AKTIF (Protected)",
        20,
        C.green,
        8,
        38,
        function()
            AntiStaff.enabled = not AntiStaff.enabled
            if AntiStaff.scan then AntiStaff.scan() end
            updateAntiStaffUIElements()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    )
    secAntiStaff.setBadge("`2[PROTECTED]``")

    lblAntiStaffStatus = makeLabel(secAntiStaff.body, "`2Status: Aman | Memantau seluruh player di world (Auto-Freeze / Kick)``", 18, UDim2.new())
    lblStaffList = makeLabel(secAntiStaff.body, "`9Staff Terdeteksi di World: 0 orang``", 17, UDim2.new())

    cbAutoFreeze = checkbox(secAntiStaff.body, "`oAuto-Freeze / Mematung saat Staff join (Otomatis Resume saat leave)``", UDim2.new(), function(val)
        AntiStaff.autoFreeze = val
        if AntiStaff.scan then AntiStaff.scan() end
        updateAntiStaffUIElements()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)
    cbAutoFreeze.set(AntiStaff.autoFreeze ~= false)

    cbAutoKick = checkbox(secAntiStaff.body, "`4Auto-Kick saat Staff join (Langsung keluar game demi keamanan)``", UDim2.new(), function(val)
        AntiStaff.autoKick = val
        if AntiStaff.scan then AntiStaff.scan() end
        updateAntiStaffUIElements()
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)
    cbAutoKick.set(AntiStaff.autoKick == true)

    makeLabel(secAntiStaff.body, "`oDeteksi: Developer, Moderator, Admin, Staff Tag (@), dan Rank resmi game.``", 16, UDim2.new())

    updatePlayerUI = function()
        -- Hazard
        if btnHazard and btnHazardLabel then
            btnHazard.BackgroundColor3 = AntiHazard.enabled and C.green or C.button
            btnHazardLabel:set(AntiHazard.enabled and "Anti-Hazard: ON" or "Anti-Hazard: OFF")
        end
        if secHazard and secHazard.setBadge then
            secHazard.setBadge(AntiHazard.enabled and "`2[ACTIVE]``" or "`o[OFF]``")
        end
        if lblHazardStatus and lblHazardStatus.set then
            lblHazardStatus:set(AntiHazard.enabled and "`2Status: Aktif | Kebal Lava, Spikes & Jamur``" or "`oStatus: Nonaktif | Normal Game Physics``")
        end
        if cbAntiLava and cbAntiLava.set then cbAntiLava.set(AntiHazard.antiLava ~= false) end
        if cbAntiSpikes and cbAntiSpikes.set then cbAntiSpikes.set(AntiHazard.antiDeadly ~= false) end
        if cbAntiBounce and cbAntiBounce.set then cbAntiBounce.set(AntiHazard.antiBounce ~= false) end
        if cbAntiLaser and cbAntiLaser.set then cbAntiLaser.set(AntiHazard.antiLaser ~= false) end

        -- Click Pathfind
        if btnClickPath and btnClickPathLabel then
            btnClickPath.BackgroundColor3 = ClickPathfind.enabled and C.cyan or C.button
            btnClickPathLabel:set(ClickPathfind.enabled and "Shift + Click Pathfind: ON" or "Shift + Click Pathfind: OFF")
        end
        if secClickPath and secClickPath.setBadge then
            secClickPath.setBadge(ClickPathfind.enabled and "`c[ACTIVE]``" or "`o[OFF]``")
        end
        if ClickPathfind.lblStatus and ClickPathfind.lblStatus.set then
            ClickPathfind.lblStatus:set(ClickPathfind.enabled and "`2Status: Standby | Tahan [SHIFT] untuk memunculkan grid & klik tile``" or "`oStatus: Nonaktif | Standby``")
        end

        -- Speed
        if btnSpeed and btnSpeedLabel then
            btnSpeed.BackgroundColor3 = Mobility.speedEnabled and C.green or C.button
            btnSpeedLabel:set(Mobility.speedEnabled and "Speed Mode: ON" or "Speed Mode: OFF")
        end
        if secSpeed and secSpeed.setBadge then
            secSpeed.setBadge(Mobility.speedEnabled and string.format("`2[%.1fx]``", Mobility.speedMultiplier) or "`o[OFF]``")
        end
        if updateSpeedDisplay then updateSpeedDisplay() end
        if sliderFill then
            local ratio = math.clamp((Mobility.speedMultiplier - 1.0) / 4.0, 0, 1)
            sliderFill.Size = UDim2.new(ratio, 0, 1, 0)
        end
        for _, other in ipairs(speedPresets) do
            if presetBtns[other.val] then
                presetBtns[other.val].BackgroundColor3 = (math.abs(Mobility.speedMultiplier - other.val) < 0.05) and C.green or C.button
            end
        end

        -- Fast Inv
        if btnDrop and btnDropLabel then
            btnDrop.BackgroundColor3 = FastInventory.fastDrop and C.green or C.button
            btnDropLabel:set(FastInventory.fastDrop and "Fast Drop: ON" or "Fast Drop: OFF")
        end
        if btnRecycle and btnRecycleLabel then
            btnRecycle.BackgroundColor3 = FastInventory.fastRecycle and C.red or C.button
            btnRecycleLabel:set(FastInventory.fastRecycle and "Fast Trash / Recycle: ON" or "Fast Trash / Recycle: OFF")
        end
        if secFastInv and secFastInv.setBadge then
            secFastInv.setBadge((FastInventory.fastDrop or FastInventory.fastRecycle) and "`2[ACTIVE]``" or "`o[OFF]``")
        end
        if cbCustomCount and cbCustomCount.set then cbCustomCount.set(FastInventory.customCountEnabled == true) end
        if countBox then countBox.Text = tostring(FastInventory.customCount or 1) end
        if updateFastInvStatus then updateFastInvStatus() end

        -- Zoom & Anti-Staff UI updates
        if updateZoomUIElements then updateZoomUIElements() end
        if updateAntiStaffUIElements then updateAntiStaffUIElements() end
    end
end

Setups.farmMagnet = function(body)
    local cbMagnet
    cbMagnet = checkbox(body, "`oAktifkan Auto-Collect Drops (A* Pathfinding)``", UDim2.new(), function(val)
        Magnet.enabled = val
        if Magnet.enabled then
            startMagnetLoop()
        else
            stopMagnetLoop()
        end
        if updateMagnetUI then updateMagnetUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, Magnet.enabled == true)

    local cbDontReturn
    cbDontReturn = checkbox(body, "`oJangan Balik ke Pos Awal (Tetap di Titik Akhir)``", UDim2.new(), function(val)
        Magnet.dontReturnToStart = val
        if updateMagnetUI then updateMagnetUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, Magnet.dontReturnToStart == true)

    makeLabel(body, "`oRadius Jangkauan (Input Angka / Preset):``", 19, UDim2.new())

    local radRow = Instance.new("Frame", body)
    radRow.Size               = UDim2.new(1, 0, 0, 34)
    radRow.BackgroundTransparency = 1

    local inpRadius = Instance.new("TextBox", radRow)
    inpRadius.Size                   = UDim2.fromOffset(130, 32)
    inpRadius.Position               = UDim2.fromOffset(0, 1)
    inpRadius.BackgroundColor3       = C.field
    inpRadius.BorderSizePixel        = 0
    inpRadius.Font                   = Enum.Font.GothamBold
    inpRadius.TextSize               = 15
    inpRadius.TextColor3             = C.text
    inpRadius.PlaceholderColor3      = C.placeholder
    inpRadius.PlaceholderText        = "Radius (1-999)"
    inpRadius.Text                   = tostring(Magnet.radius or 12)
    corner(inpRadius, 4)
    stroke(inpRadius, C.fieldRim, 1)

    inpRadius.FocusLost:Connect(function()
        local val = tonumber(inpRadius.Text)
        if val and val > 0 then
            Magnet.radius = math.clamp(math.floor(val), 1, 999)
        else
            Magnet.radius = 12
        end
        inpRadius.Text = tostring(Magnet.radius)
        if updateMagnetUI then updateMagnetUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    local radBtns = {}
    local radPresets = {
        { rad = 12,  label = "12 Tiles" },
        { rad = 24,  label = "24 Tiles" },
        { rad = 999, label = "Full World (Row Sweep)" },
    }
    local pWidth = 140
    for i, r in ipairs(radPresets) do
        local f, _, b = makeButton(radRow, r.label, 17, (Magnet.radius == r.rad) and C.cyan or C.button, 4, 30, function()
            Magnet.radius = r.rad
            inpRadius.Text = tostring(Magnet.radius)
            for _, o in ipairs(radPresets) do
                if radBtns[o.rad] then
                    radBtns[o.rad].BackgroundColor3 = (Magnet.radius == o.rad) and C.cyan or C.button
                end
            end
            if updateMagnetUI then updateMagnetUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end, (i == 3 and 180 or pWidth))
        local xOffset = 140 + (i == 1 and 0 or (pWidth + 6)) + (i == 3 and (pWidth + 6) or 0)
        f.Position = UDim2.fromOffset(xOffset, 1)
        radBtns[r.rad] = b
    end

    local statsRow = Instance.new("Frame", body)
    statsRow.Size               = UDim2.new(1, 0, 0, 34)
    statsRow.BackgroundTransparency = 1

    lblMagnetStats = makeLabel(statsRow, "`9● Total Tersedot: 0 item | Rad: 12T | Flt: ALL``", 20, UDim2.fromOffset(0, 6))

    local btnResetStatsFrame = makeButton(
        statsRow,
        "Reset",
        18,
        C.button,
        6,
        30,
        function()
            Magnet.totalPicked = 0
            if updateMagnetUI then updateMagnetUI() end
        end,
        100
    )
    btnResetStatsFrame.AnchorPoint = Vector2.new(1, 0.5)
    btnResetStatsFrame.Position    = UDim2.new(1, 0, 0.5, 0)

    updateMagnetUI = function()
        if cbMagnet and cbMagnet.set then cbMagnet.set(Magnet.enabled == true) end
        if cbDontReturn and cbDontReturn.set then cbDontReturn.set(Magnet.dontReturnToStart == true) end
        if inpRadius and not inpRadius:IsFocused() then
            inpRadius.Text = tostring(Magnet.radius or 12)
        end
        for _, o in ipairs(radPresets) do
            if radBtns[o.rad] then
                radBtns[o.rad].BackgroundColor3 = (Magnet.radius == o.rad) and C.cyan or C.button
            end
        end
        if lblMagnetStats and lblMagnetStats.set then
            lblMagnetStats:set(string.format("`9● Tersedot: %d | Rad: %s | Flt: ALL | Pos: %s``",
                Magnet.totalPicked or 0,
                (Magnet.radius and Magnet.radius >= 900) and "World (Row-by-Row)" or (tostring(Magnet.radius or 12) .. "T"),
                (Magnet.dontReturnToStart and "Tetap di Akhir" or "Balik ke Awal (PNB)")))
        end
    end
end

Setups.farmPNB = function(body)
    -- Row 1: Start PNB button + Mode Switchers
    local pnbTopRow = Instance.new("Frame", body)
    pnbTopRow.Size               = UDim2.new(1, 0, 0, 38)
    pnbTopRow.BackgroundTransparency = 1

    local pnbBtnFrame, _, pnbBtn, pnbBtnLabel = makeButton(
        pnbTopRow,
        "START PNB",
        20,
        C.green,
        8,
        36,
        function()
            if onTogglePNB then onTogglePNB() end
        end,
        180
    )
    pnbBtnFrame.Position = UDim2.fromOffset(0, 0)
    btnToggle = pnbBtn
    btnToggleLabel = pnbBtnLabel

    local modeBtns = {}
    local modeList = {
        { mode = "PNB",   label = "P & B" },
        { mode = "BREAK", label = "Break" },
        { mode = "PLACE", label = "Place" },
    }

    refreshMode = function()
        for _, m in ipairs(modeList) do
            local b = modeBtns[m.mode]
            if b then
                b.BackgroundColor3 = (PNB.mode == m.mode) and C.green or C.button
            end
        end
    end

    local mWidth = 118
    for i, m in ipairs(modeList) do
        local f, _, b = makeButton(
            pnbTopRow,
            m.label,
            18,
            (PNB.mode == m.mode) and C.green or C.button,
            6,
            36,
            function()
                PNB.mode = m.mode
                refreshMode()
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end,
            mWidth
        )
        f.Position = UDim2.fromOffset(190 + (i - 1) * (mWidth + 6), 0)
        modeBtns[m.mode] = b
    end

    -- Row 2: Selected Item Dropdown & Refresh
    local invRow = Instance.new("Frame", body)
    invRow.Size               = UDim2.new(1, 0, 0, 36)
    invRow.BackgroundTransparency = 1

    local dropListContainer = Instance.new("Frame", body)
    dropListContainer.Size             = UDim2.new(1, 0, 0, 190)
    dropListContainer.BackgroundColor3 = C.dark
    dropListContainer.BorderSizePixel  = 0
    dropListContainer.Visible          = false
    dropListContainer.ClipsDescendants = true
    corner(dropListContainer, 6)
    dialogBorder(dropListContainer)

    -- Kolom Pencarian Item di Tas
    local searchFrame = Instance.new("Frame", dropListContainer)
    searchFrame.Size                   = UDim2.new(1, -12, 0, 32)
    searchFrame.Position               = UDim2.fromOffset(6, 6)
    searchFrame.BackgroundColor3       = C.box
    searchFrame.BorderSizePixel        = 0
    corner(searchFrame, 6)
    stroke(searchFrame, C.rimInner, 1)

    local inpSearch = Instance.new("TextBox", searchFrame)
    inpSearch.Size                   = UDim2.new(1, -12, 1, 0)
    inpSearch.Position               = UDim2.fromOffset(6, 0)
    inpSearch.BackgroundTransparency = 1
    inpSearch.Font                   = Enum.Font.FredokaOne
    inpSearch.TextSize               = 17
    inpSearch.TextColor3             = C.text
    inpSearch.PlaceholderColor3      = C.placeholder
    inpSearch.PlaceholderText        = "Cari nama blok / ID tas..."
    inpSearch.Text                   = ""
    inpSearch.ClearTextOnFocus       = false

    local dropScroll = Instance.new("ScrollingFrame", dropListContainer)
    dropScroll.Size                   = UDim2.new(1, -12, 1, -46)
    dropScroll.Position               = UDim2.fromOffset(6, 42)
    dropScroll.BackgroundTransparency = 1
    dropScroll.BorderSizePixel        = 0
    dropScroll.ScrollBarThickness     = 6
    dropScroll.ScrollBarImageColor3   = C.rim

    local dropListLayout = Instance.new("UIListLayout", dropScroll)
    dropListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    dropListLayout.Padding   = UDim.new(0, 4)

    local btnDropdownFrame, _, _, btnDropdownLabel = makeButton(
        invRow,
        "Pilih Blok v",
        19,
        C.button,
        8,
        34,
        function()
            dropListContainer.Visible = not dropListContainer.Visible
            if dropListContainer.Visible then
                inpSearch.Text = ""
                if refreshInventory then refreshInventory() end
            end
        end,
        510
    )
    btnDropdownFrame.Position = UDim2.fromOffset(0, 0)

    local btnRefFrame = makeButton(
        invRow,
        "[Ref]",
        20,
        C.button,
        4,
        34,
        function()
            if refreshInventory then refreshInventory() end
        end,
        44
    )
    btnRefFrame.Position = UDim2.fromOffset(518, 0)

    -- Row 3: Manual Settings (Layer / ID / Hits)
    local manualRow = Instance.new("Frame", body)
    manualRow.Size               = UDim2.new(1, 0, 0, 36)
    manualRow.BackgroundTransparency = 1

    local btnLayerFrame, _, btnLayer, btnLayerLabel = makeButton(
        manualRow,
        string.upper(PNB.layer or "fg"),
        20,
        C.green,
        8,
        34,
        function()
            local curL = string.lower(PNB.layer or "fg")
            PNB.layer = (curL == "fg") and "bg" or "fg"
            updateLayerUI()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end,
        64
    )
    btnLayerFrame.Position = UDim2.fromOffset(0, 0)

    updateLayerUI = function()
        local isFg = (string.lower(PNB.layer or "fg") == "fg")
        btnLayerLabel:set(isFg and "FG" or "BG")
        btnLayer.BackgroundColor3 = isFg and C.green or C.cyan
    end

    inpItemId = Instance.new("TextBox", manualRow)
    inpItemId.Size                   = UDim2.fromOffset(100, 34)
    inpItemId.Position               = UDim2.fromOffset(72, 0)
    inpItemId.BackgroundColor3       = C.field
    inpItemId.BorderSizePixel        = 0
    inpItemId.Font                   = Enum.Font.GothamBold
    inpItemId.TextSize               = 15
    inpItemId.TextColor3             = C.text
    inpItemId.PlaceholderColor3      = C.placeholder
    inpItemId.PlaceholderText        = "Item ID"
    inpItemId.Text                   = tostring(PNB.targetItemId or PNB.itemId or 2)
    corner(inpItemId, 4)
    stroke(inpItemId, C.fieldRim, 1)

    inpHits = Instance.new("TextBox", manualRow)
    inpHits.Size                     = UDim2.fromOffset(80, 34)
    inpHits.Position                 = UDim2.fromOffset(176, 0)
    inpHits.BackgroundColor3         = C.field
    inpHits.BorderSizePixel          = 0
    inpHits.Font                     = Enum.Font.GothamBold
    inpHits.TextSize                 = 15
    inpHits.TextColor3               = C.text
    inpHits.PlaceholderColor3        = C.placeholder
    inpHits.PlaceholderText          = "Hits (1-20)"
    inpHits.Text                     = tostring(PNB.hitsPerBlock or PNB.hits or 3)
    corner(inpHits, 4)
    stroke(inpHits, C.fieldRim, 1)

    inpHitDelay = Instance.new("TextBox", manualRow)
    inpHitDelay.Size                 = UDim2.fromOffset(80, 34)
    inpHitDelay.Position             = UDim2.fromOffset(260, 0)
    inpHitDelay.BackgroundColor3     = C.field
    inpHitDelay.BorderSizePixel      = 0
    inpHitDelay.Font                 = Enum.Font.GothamBold
    inpHitDelay.TextSize             = 15
    inpHitDelay.TextColor3           = C.text
    inpHitDelay.PlaceholderColor3    = C.placeholder
    inpHitDelay.PlaceholderText      = "Delay (s)"
    inpHitDelay.Text                 = tostring(PNB.hitDelay or 0.18)
    corner(inpHitDelay, 4)
    stroke(inpHitDelay, C.fieldRim, 1)

    inpHitDelay.FocusLost:Connect(function()
        local d = tonumber(inpHitDelay.Text)
        if d and d > 0 then
            PNB.hitDelay = math.max(0.05, d)
            inpHitDelay.Text = tostring(PNB.hitDelay)
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end)

    local lblSelectedInfo = makeLabel(manualRow, "`w[FG] Dirt (ID: 2) | Hits: 3``", 18, UDim2.fromOffset(346, 8))

    inpItemId.FocusLost:Connect(function()
        local id = tonumber(inpItemId.Text)
        if id and ItemDB and ItemDB[id] then
            PNB.targetItemId = id
            PNB.itemId       = id
            PNB.itemName     = ItemDB[id].name or "Item"
            local hits = calculateBlockHits(id)
            PNB.hitsPerBlock = hits
            PNB.hits         = hits
            inpHits.Text = tostring(hits)
            lblSelectedInfo:set(string.format("`w[%s] %s (ID: %d) | Hits: %d``", string.upper(PNB.layer or "fg"), PNB.itemName, id, hits))
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end)

    inpHits.FocusLost:Connect(function()
        local h = tonumber(inpHits.Text)
        if h and h > 0 then
            PNB.hitsPerBlock = math.clamp(h, 1, 50)
            PNB.hits         = PNB.hitsPerBlock
            inpHits.Text = tostring(PNB.hitsPerBlock)
            lblSelectedInfo:set(string.format("`w[%s] ID: %d | Hits: %d``", string.upper(PNB.layer or "fg"), PNB.targetItemId or PNB.itemId or 2, PNB.hitsPerBlock))
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end)

    -- Row 4: 5x5 Grid Selection & Presets
    local gridCard = Instance.new("Frame", body)
    gridCard.Size                   = UDim2.new(1, 0, 0, 230)
    gridCard.BackgroundColor3       = C.dark
    gridCard.BackgroundTransparency = 0.5
    gridCard.BorderSizePixel        = 0
    corner(gridCard, 6)
    stroke(gridCard, C.fieldRim, 1)

    makeLabel(gridCard, "`oTarget Tile di Sekitar Karakter (Grid 5x5):``", 20, UDim2.fromOffset(12, 6))

    local presetsRow = Instance.new("Frame", gridCard)
    presetsRow.Size               = UDim2.new(1, -24, 0, 30)
    presetsRow.Position           = UDim2.fromOffset(12, 30)
    presetsRow.BackgroundTransparency = 1

    local pWidth = 125
    local function mkPreset(idx, txt, fn)
        local f = makeButton(presetsRow, txt, 17, C.button, 4, 28, function()
            fn()
            if updateGridVisuals then updateGridVisuals() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end, pWidth)
        f.Position = UDim2.fromOffset((idx - 1) * (pWidth + 8), 0)
    end

    mkPreset(1, "Kanan 1x1", function()
        PNB.targets = { ["1_0"] = { dx = 1, dy = 0 } }
    end)
    mkPreset(2, "Kanan 1x2", function()
        PNB.targets = { ["1_0"] = { dx = 1, dy = 0 }, ["1_-1"] = { dx = 1, dy = -1 } }
    end)
    mkPreset(3, "Kiri 1x2", function()
        PNB.targets = { ["-1_0"] = { dx = -1, dy = 0 }, ["-1_-1"] = { dx = -1, dy = -1 } }
    end)
    mkPreset(4, "Reset", function()
        PNB.targets = {}
    end)

    local gridFrame = Instance.new("Frame", gridCard)
    gridFrame.Size             = UDim2.fromOffset(160, 160)
    gridFrame.AnchorPoint      = Vector2.new(0.5, 0)
    gridFrame.Position         = UDim2.new(0.5, 0, 0, 64)
    gridFrame.BackgroundTransparency = 1

    local gridLayout = Instance.new("UIGridLayout", gridFrame)
    gridLayout.CellSize        = UDim2.fromOffset(28, 28)
    gridLayout.CellPadding     = UDim2.fromOffset(4, 4)
    gridLayout.SortOrder       = Enum.SortOrder.LayoutOrder

    local gridButtons = {}

    updateGridVisuals = function()
        for key, bObj in pairs(gridButtons) do
            local dx = bObj.btn:GetAttribute("dx")
            local dy = bObj.btn:GetAttribute("dy")
            local isSelected = (PNB.targets[key] ~= nil)

            if isSelected then
                bObj.btn.BackgroundColor3 = C.gold
                bObj.lbl:set((dx == 0 and dy == 0) and "`b*P*``" or "`b*``")
            elseif dx == 0 and dy == 0 then
                bObj.btn.BackgroundColor3 = C.green
                bObj.lbl:set("`wP``")
            else
                bObj.btn.BackgroundColor3 = C.field
                bObj.lbl:set("`s.``")
            end
        end
    end

    local orderCount = 1
    for dy = -2, 2 do
        for dx = -2, 2 do
            local btnCell = Instance.new("TextButton", gridFrame)
            btnCell.Size             = UDim2.fromOffset(28, 28)
            btnCell.BorderSizePixel  = 0
            btnCell.LayoutOrder      = orderCount
            btnCell.Text             = ""
            btnCell.BackgroundColor3 = C.field
            corner(btnCell, 4)
            stroke(btnCell, C.fieldRim, 1)

            btnCell:SetAttribute("dx", dx)
            btnCell:SetAttribute("dy", dy)
            local key = string.format("%d_%d", dx, dy)

            local cellLbl = makeLabel(btnCell, "·", 20, UDim2.fromScale(0.5, 0.5), {anchor = Vector2.new(0.5, 0.5)})

            btnCell.Activated:Connect(function()
                pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
                if PNB.targets[key] then
                    PNB.targets[key] = nil
                else
                    PNB.targets[key] = { dx = dx, dy = dy }
                end
                updateGridVisuals()
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end)

            gridButtons[key] = { btn = btnCell, lbl = cellLbl }
            orderCount = orderCount + 1
        end
    end

    local cachedInvItems = {}
    local function renderDropItems(query)
        for _, ch in ipairs(dropScroll:GetChildren()) do
            if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                ch:Destroy()
            end
        end

        local q = (query and string.lower(query):gsub("^%s+", ""):gsub("%s+$", "")) or ""
        local shown = 0
        for _, it in ipairs(cachedInvItems) do
            if it.count and it.count > 0 then
                local layerTag = (it.layer == "bg") and "BG" or "FG"
                local itemHits = it.hits or calculateBlockHits(it.id)
                local itName = it.name or "Item"
                local itIdStr = tostring(it.id)

                local match = true
                if #q > 0 then
                    match = (string.find(string.lower(itName), q, 1, true) ~= nil) or
                            (string.find(itIdStr, q, 1, true) ~= nil)
                end

                if match then
                    shown = shown + 1
                    makeButton(
                        dropScroll,
                        string.format("[%s] %s  x%d  (Hits: %d)", layerTag, itName, it.count, itemHits),
                        19,
                        ((PNB.targetItemId or PNB.itemId) == it.id) and C.green or C.button,
                        8,
                        32,
                        function()
                            PNB.targetItemId = it.id
                            PNB.itemId       = it.id
                            PNB.itemName     = itName
                            PNB.layer        = (layerTag == "BG") and "bg" or "fg"
                            PNB.hitsPerBlock = itemHits
                            PNB.hits         = itemHits

                            inpItemId.Text = tostring(it.id)
                            inpHits.Text   = tostring(itemHits)
                            updateLayerUI()
                            btnDropdownLabel:set(string.format("[%s] %s x%d", layerTag, itName, it.count))
                            lblSelectedInfo:set(string.format("`w[%s] %s (ID: %d) | Hits: %d``", layerTag, itName, it.id, itemHits))
                            dropListContainer.Visible = false
                            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                        end,
                        530
                    )
                end
            end
        end

        if shown == 0 then
            if #cachedInvItems == 0 then
                makeLabel(dropScroll, "`oTas Kosong / Tidak ada blok``", 18, UDim2.new())
            else
                makeLabel(dropScroll, "`4Tidak ada blok sesuai pencarian!``", 18, UDim2.new())
            end
        end
    end

    inpSearch:GetPropertyChangedSignal("Text"):Connect(function()
        renderDropItems(inpSearch.Text)
    end)

    refreshInventory = function()
        btnDropdownLabel:set("Memuat inventori...")
        task.spawn(function()
            cachedInvItems = fetchInventoryItems()
            renderDropItems(inpSearch.Text)

            if #cachedInvItems > 0 then
                local curId = PNB.targetItemId or PNB.itemId or 2
                local cur = ItemDB and ItemDB[curId]
                local curCount = getRealtimeItemCount(curId)
                local layerUpper = string.upper(PNB.layer or "fg")
                btnDropdownLabel:set(cur and string.format("[%s] %s x%d", layerUpper, cur.name or "Item", curCount) or "Pilih Blok v")
            else
                btnDropdownLabel:set("Tas Kosong / Item Habis ▼")
            end
        end)
    end

    updateFarmUI = function()
        if refreshMode then refreshMode() end
        if updateLayerUI then updateLayerUI() end
        if updateGridVisuals then updateGridVisuals() end
        local curId = PNB.targetItemId or PNB.itemId or 2
        local curHits = PNB.hitsPerBlock or PNB.hits or 3
        if inpItemId then inpItemId.Text = tostring(curId) end
        if inpHits then inpHits.Text = tostring(curHits) end
        if inpHitDelay then inpHitDelay.Text = tostring(PNB.hitDelay or 0.18) end
        if lblSelectedInfo and lblSelectedInfo.set then
            local name = PNB.itemName or (ItemDB and ItemDB[curId] and ItemDB[curId].name) or "Item"
            lblSelectedInfo:set(string.format("`w[%s] %s (ID: %d) | Hits: %d``", string.upper(PNB.layer or "fg"), name, curId, curHits))
        end
        if btnDropdownLabel and btnDropdownLabel.set then
            local name = PNB.itemName or (ItemDB and ItemDB[curId] and ItemDB[curId].name) or "Item"
            local cnt = getRealtimeItemCount(curId)
            btnDropdownLabel:set(string.format("[%s] %s x%d", string.upper(PNB.layer or "fg"), name, cnt))
        end
        if updatePlantUI then updatePlantUI() end
        if updateHarvestUI then updateHarvestUI() end
        if updateMagnetUI then updateMagnetUI() end
    end
end

-- Baris input storage generik: [Set Pos di Sini] | World | Door | status
-- cfg = FarmLogistics.plantStorage / .harvestStorage, withPos = butuh titik drop
local function buildStorageRow(body, cfg, title, withPos, onChange)
    local lblInfo
    local function infoText()
        if cfg.world == "" then
            return "`oStorage: (belum diset)``"
        elseif withPos and cfg.x and cfg.y then
            return string.format("`2Storage: %s | Drop: (%d, %d)``", cfg.world, cfg.x, cfg.y)
        elseif withPos then
            return string.format("`eStorage: %s | Pos drop belum diset!``", cfg.world)
        end
        return string.format("`2Storage: %s``", cfg.world)
    end
    local function refresh()
        if lblInfo and lblInfo.set then lblInfo:set(infoText()) end
        if onChange then onChange() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end

    local rowTop = Instance.new("Frame", body)
    rowTop.Size = UDim2.new(1, 0, 0, 36)
    rowTop.BackgroundTransparency = 1

    local cbEnable = checkbox(rowTop, title, UDim2.fromOffset(0, 0), function(v)
        cfg.enabled = v
        refresh()
    end, cfg.enabled == true)

    local btnSetFrame = makeButton(rowTop, withPos and "Set Pos Drop di Sini" or "Set World di Sini", 18, C.button, 6, 32, function()
        local w = getNativeWorld and getNativeWorld()
        local name = (w and w.name) or (Proxy and Proxy.lastWorldName) or ""
        local px, py = getPlayerTilePos()
        if name == "" then
            Proxy.notify("`4[Storage] Kamu belum berada di dalam world!``")
            return
        end
        cfg.world = FarmLogistics.cleanWorld(name)
        if withPos and px and py then
            cfg.x, cfg.y = px + 1, py + 1
        end
        cfg.enabled = true
        if cbEnable and cbEnable.set then cbEnable.set(true) end
        refresh()
        Proxy.notify(string.format("`2[Storage] %s diset ke %s%s``", title, cfg.world,
            (withPos and cfg.x) and string.format(" (%d, %d)", cfg.x, cfg.y) or ""))
    end, 190)
    btnSetFrame.Position = UDim2.fromOffset(300, 1)

    local rowIn = Instance.new("Frame", body)
    rowIn.Size = UDim2.new(1, 0, 0, 36)
    rowIn.BackgroundTransparency = 1

    local inpWorld = Instance.new("TextBox", rowIn)
    inpWorld.Size = UDim2.fromOffset(190, 32)
    inpWorld.Position = UDim2.fromOffset(0, 2)
    inpWorld.BackgroundColor3 = C.field
    inpWorld.BorderSizePixel = 0
    inpWorld.Font = Enum.Font.GothamBold
    inpWorld.TextSize = 14
    inpWorld.TextColor3 = C.text
    inpWorld.PlaceholderColor3 = C.placeholder
    inpWorld.PlaceholderText = "Nama Storage World"
    inpWorld.Text = cfg.world or ""
    corner(inpWorld, 4)
    stroke(inpWorld, C.fieldRim, 1)
    inpWorld.FocusLost:Connect(function()
        cfg.world = FarmLogistics.cleanWorld(inpWorld.Text)
        inpWorld.Text = cfg.world
        refresh()
    end)

    local inpDoor = Instance.new("TextBox", rowIn)
    inpDoor.Size = UDim2.fromOffset(150, 32)
    inpDoor.Position = UDim2.fromOffset(196, 2)
    inpDoor.BackgroundColor3 = C.field
    inpDoor.BorderSizePixel = 0
    inpDoor.Font = Enum.Font.GothamBold
    inpDoor.TextSize = 14
    inpDoor.TextColor3 = C.text
    inpDoor.PlaceholderColor3 = C.placeholder
    inpDoor.PlaceholderText = "Door ID (opsional)"
    inpDoor.Text = cfg.door or ""
    corner(inpDoor, 4)
    stroke(inpDoor, C.fieldRim, 1)
    inpDoor.FocusLost:Connect(function()
        cfg.door = (inpDoor.Text or ""):gsub("%s+", "")
        inpDoor.Text = cfg.door
        refresh()
    end)

    lblInfo = makeLabel(body, infoText(), 18, UDim2.new())
    return {
        refresh = refresh,
        sync = function()
            if cbEnable and cbEnable.set then cbEnable.set(cfg.enabled == true) end
            if not inpWorld:IsFocused() then inpWorld.Text = cfg.world or "" end
            if not inpDoor:IsFocused() then inpDoor.Text = cfg.door or "" end
            if lblInfo and lblInfo.set then lblInfo:set(infoText()) end
        end,
    }
end

-- List world farm generik (dipakai Auto Plant & Auto Harvest): input "WORLD|SEED|DOOR",
-- tampil daftar dengan penanda world aktif, tombol Warp & hapus.
-- mode = "PLANT" / "HARVEST" (untuk menandai world yang sedang dikerjakan)
local function buildWorldList(body, list, mode, seedHint)
    makeLabel(body, string.format("`wList World Farm (Format: NAMAWORLD|%s|DOOR) - kosong = world ini saja``", seedHint), 18, UDim2.new())

    local addRow = Instance.new("Frame", body)
    addRow.Size = UDim2.new(1, 0, 0, 36)
    addRow.BackgroundTransparency = 1

    local inpAdd = Instance.new("TextBox", addRow)
    inpAdd.Size = UDim2.new(1, -240, 0, 34)
    inpAdd.Position = UDim2.fromOffset(0, 1)
    inpAdd.BackgroundColor3 = C.field
    inpAdd.BorderSizePixel = 0
    inpAdd.Font = Enum.Font.GothamBold
    inpAdd.TextSize = 15
    inpAdd.TextColor3 = C.text
    inpAdd.PlaceholderColor3 = C.placeholder
    inpAdd.PlaceholderText = "cth: MYFARM|3  atau  MYFARM|Dirt Seed"
    inpAdd.Text = ""
    inpAdd.ClearTextOnFocus = false
    corner(inpAdd, 4)
    stroke(inpAdd, C.fieldRim, 1)

    local container = Instance.new("Frame", body)
    container.Size = UDim2.new(1, 0, 0, 130)
    container.BackgroundColor3 = C.dark
    container.BackgroundTransparency = 0.5
    container.BorderSizePixel = 0
    corner(container, 6)
    stroke(container, C.fieldRim, 1)

    local scroll = Instance.new("ScrollingFrame", container)
    scroll.Size = UDim2.new(1, -8, 1, -8)
    scroll.Position = UDim2.fromOffset(4, 4)
    scroll.BackgroundTransparency = 1
    scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 6
    scroll.ScrollBarImageColor3 = C.rim
    scroll.ScrollingDirection = Enum.ScrollingDirection.Y
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    scroll.CanvasSize = UDim2.new()
    local layout = Instance.new("UIListLayout", scroll)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 4)

    local lastSig = nil
    local refresh
    refresh = function(force)
        local st = FarmLogistics.readState and FarmLogistics.state
        local activeIdx = (st and st.active and st.mode == mode) and tonumber(st.idx) or nil
        local sig = tostring(#list) .. ":" .. tostring(activeIdx)
        for _, e in ipairs(list) do sig = sig .. "|" .. e.world .. ":" .. tostring(e.seedId) end
        if not force and sig == lastSig then return end
        lastSig = sig
        for _, ch in ipairs(scroll:GetChildren()) do
            if ch:IsA("Frame") then ch:Destroy() end
        end
        if #list == 0 then
            local emptyRow = Instance.new("Frame", scroll)
            emptyRow.Size = UDim2.new(1, 0, 0, 30)
            emptyRow.BackgroundTransparency = 1
            makeLabel(emptyRow, "`o(List kosong - hanya mengerjakan world saat ini)``", 18, UDim2.fromScale(0.5, 0.5), {anchor = Vector2.new(0.5, 0.5)})
            return
        end
        for idx, e in ipairs(list) do
            local row = Instance.new("Frame", scroll)
            row.Size = UDim2.new(1, 0, 0, 34)
            row.BackgroundColor3 = (idx == activeIdx) and C.green or C.field
            row.BackgroundTransparency = (idx == activeIdx) and 0.55 or 0.4
            corner(row, 4)
            local seedTxt = e.seedId and string.format("%s (#%d)", e.seedName or FarmLogistics.itemName(e.seedId), e.seedId)
                or ((mode == "HARVEST") and "Semua pohon" or "Bibit dari dropdown/tas")
            makeLabel(row, string.format("`c#%d. %s`` | `9%s``%s%s", idx, e.world, seedTxt,
                (e.door ~= "" and ("`o | door: " .. e.door .. "``") or ""),
                (idx == activeIdx) and " `2<- aktif``" or ""), 17, UDim2.fromOffset(8, 7))
            local btnWarp = makeButton(row, "Warp", 16, C.cyan, 4, 26, function()
                warpToWorld(e.world, e.door)
            end, 60)
            btnWarp.Position = UDim2.new(1, -150, 0, 4)
            local btnUp = makeButton(row, "^", 16, C.button, 4, 26, function()
                if idx > 1 then
                    list[idx], list[idx - 1] = list[idx - 1], list[idx]
                    refresh(true)
                    if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                end
            end, 32)
            btnUp.Position = UDim2.new(1, -84, 0, 4)
            local btnDel = makeButton(row, "X", 16, C.red, 4, 26, function()
                table.remove(list, idx)
                refresh(true)
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end, 36)
            btnDel.Position = UDim2.new(1, -44, 0, 4)
        end
    end

    local function addFromInput()
        local entry, err = FarmLogistics.parseWorldEntry(inpAdd.Text)
        if not entry then
            Proxy.notify("`4[List World] Gagal tambah: " .. tostring(err) .. "``")
            return
        end
        for _, e in ipairs(list) do
            if e.world == entry.world then
                e.seedId, e.seedName, e.door = entry.seedId, entry.seedName, entry.door
                inpAdd.Text = ""
                refresh(true)
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                Proxy.notify("`2[List World] " .. entry.world .. " diperbarui``")
                return
            end
        end
        table.insert(list, entry)
        inpAdd.Text = ""
        refresh(true)
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end

    local btnAdd = makeButton(addRow, "+ Tambah", 17, C.button, 6, 34, addFromInput, 110)
    btnAdd.Position = UDim2.new(1, -232, 0, 1)
    local btnHere = makeButton(addRow, "+ World Ini", 17, C.button, 6, 34, function()
        local cw = FarmLogistics.currentWorld()
        if cw == "" then
            Proxy.notify("`4[List World] Kamu belum berada di world!``")
            return
        end
        local seedPart = ""
        if mode == "PLANT" and AutoPlant.selectedSeedId then seedPart = "|" .. tostring(AutoPlant.selectedSeedId) end
        inpAdd.Text = cw .. seedPart
        addFromInput()
    end, 116)
    btnHere.Position = UDim2.new(1, -118, 0, 1)
    inpAdd.FocusLost:Connect(function(enter) if enter then addFromInput() end end)

    refresh(true)
    return { refresh = refresh }
end

Setups.farmPlant = function(body)
    lblPlantStatus = makeLabel(body, "`oStatus: Standby | Siap deteksi tanah kosong``", 19, UDim2.new())

    local plantBtnRow = Instance.new("Frame", body)
    plantBtnRow.Size               = UDim2.new(1, 0, 0, 38)
    plantBtnRow.BackgroundTransparency = 1

    local btnTogglePlantFrame, btnTogglePlant, btnTogglePlantLabel
    btnTogglePlantFrame, _, btnTogglePlant, btnTogglePlantLabel = makeButton(
        plantBtnRow,
        "START AUTO PLANT",
        19,
        C.green,
        8,
        36,
        function()
            if AutoPlant.active then
                stopAutoPlant()
            else
                startAutoPlant()
            end
        end,
        210
    )
    btnTogglePlantFrame.Position = UDim2.fromOffset(0, 0)

    -- Dropdown Container untuk Pemilihan Bibit di Tas
    local seedDropList = Instance.new("Frame", body)
    seedDropList.Size                   = UDim2.new(1, 0, 0, 140)
    seedDropList.BackgroundColor3       = C.dark
    seedDropList.BackgroundTransparency = 0.2
    seedDropList.BorderSizePixel        = 0
    seedDropList.Visible                = false
    corner(seedDropList, 6)
    stroke(seedDropList, C.fieldRim, 1)

    local seedScroll = Instance.new("ScrollingFrame", seedDropList)
    seedScroll.Size               = UDim2.new(1, -12, 1, -12)
    seedScroll.Position           = UDim2.fromOffset(6, 6)
    seedScroll.BackgroundTransparency = 1
    seedScroll.BorderSizePixel    = 0
    seedScroll.ScrollBarThickness = 4
    seedScroll.ScrollBarImageColor3 = C.rim
    seedScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    seedScroll.CanvasSize         = UDim2.new(0, 0, 0, 0)

    local seedListLayout = Instance.new("UIListLayout", seedScroll)
    seedListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    seedListLayout.Padding   = UDim.new(0, 4)

    local btnSelectSeedFrame, _, _, btnSelectSeedLabel
    local function refreshSeedDropdown()
        for _, ch in ipairs(seedScroll:GetChildren()) do
            if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                ch:Destroy()
            end
        end

        makeButton(
            seedScroll,
            "[Otomatis] Bibit Pertama di Tas",
            19,
            (AutoPlant.selectedSeedId == nil) and C.green or C.button,
            8,
            30,
            function()
                AutoPlant.selectedSeedId = nil
                AutoPlant.selectedSeedName = "Bibit Otomatis (Tas)"
                btnSelectSeedLabel:set("Bibit: Otomatis dari Tas v")
                seedDropList.Visible = false
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end,
            530
        )

        local inv = fetchInventoryItems()
        local seedCount = 0
        for _, it in ipairs(inv) do
            if (it.kind == "seed" or string.find((it.name or ""):lower(), "seed")) and it.count > 0 then
                seedCount = seedCount + 1
                local isSelected = (AutoPlant.selectedSeedId == it.id)
                makeButton(
                    seedScroll,
                    string.format("[Seed] %s  x%d  (ID: %d)", it.name or "Seed", tonumber(it.count) or 0, tonumber(it.id) or 0),
                    19,
                    isSelected and C.green or C.button,
                    8,
                    30,
                    function()
                        AutoPlant.selectedSeedId = it.id
                        AutoPlant.selectedSeedName = it.name
                        btnSelectSeedLabel:set(string.format("[Seed] %s x%d v", it.name or "Seed", it.count))
                        seedDropList.Visible = false
                        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                    end,
                    530
                )
            end
        end

        if seedCount == 0 then
            local emptyNotice = Instance.new("Frame", seedScroll)
            emptyNotice.Size = UDim2.new(1, 0, 0, 30)
            emptyNotice.BackgroundTransparency = 1
            makeLabel(emptyNotice, "`o(Tidak ada bibit terdeteksi di dalam tas)``", 18, UDim2.fromScale(0.5, 0.5), {anchor = Vector2.new(0.5, 0.5)})
        end
    end

    btnSelectSeedFrame, _, _, btnSelectSeedLabel = makeButton(
        plantBtnRow,
        (AutoPlant.selectedSeedId and AutoPlant.selectedSeedName) and string.format("[Seed] %s v", AutoPlant.selectedSeedName) or "Bibit: Otomatis dari Tas v",
        18,
        C.button,
        8,
        36,
        function()
            seedDropList.Visible = not seedDropList.Visible
            if seedDropList.Visible then
                refreshSeedDropdown()
            end
        end,
        220
    )
    btnSelectSeedFrame.Position = UDim2.fromOffset(216, 0)

    lblPlantStats = makeLabel(plantBtnRow, "`9Tertanam: 0 bibit``", 19, UDim2.fromOffset(445, 8))

    -- List world farm: tanam semua world di list bergiliran (tetap jalan walau pindah server)
    local plantListUI = buildWorldList(body, FarmLogistics.plantWorlds, "PLANT", "SEED")

    -- Storage Seed: kalau bibit habis di tas, warp ke storage ambil bibit lalu lanjut tanam
    makeLabel(body, "`wAmbil Seed dari Storage (otomatis saat bibit di tas habis)``", 18, UDim2.new())
    local plantStorageUI = buildStorageRow(body, FarmLogistics.plantStorage, "Restock Seed dari Storage", false)
    makeLabel(body, "`oTips: isi SEED di list world (atau pilih bibit di dropdown) supaya yang diambil dari storage selalu bibit itu.``", 16, UDim2.new())

    updatePlantUI = function()
        if plantStorageUI then plantStorageUI.sync() end
        if plantListUI then plantListUI.refresh() end
        if AutoPlant.active then
            if btnTogglePlant then btnTogglePlant.BackgroundColor3 = C.red end
            if btnTogglePlantLabel and btnTogglePlantLabel.set then btnTogglePlantLabel:set("STOP AUTO PLANT") end
            if lblPlantStatus and lblPlantStatus.set then
                lblPlantStatus:set(string.format("`cStatus: %s``", AutoPlant.status or "Running Auto Plant..."))
            end
        else
            if btnTogglePlant then btnTogglePlant.BackgroundColor3 = C.green end
            if btnTogglePlantLabel and btnTogglePlantLabel.set then btnTogglePlantLabel:set("START AUTO PLANT") end
            if lblPlantStatus and lblPlantStatus.set then
                lblPlantStatus:set(string.format("`oStatus: %s``", AutoPlant.status or "Standby | Siap deteksi tanah kosong & tanam bibit"))
            end
        end
        if lblPlantStats and lblPlantStats.set then
            lblPlantStats:set(string.format("`9Tertanam: %d bibit``", AutoPlant.totalPlanted or 0))
        end
        if btnSelectSeedLabel and btnSelectSeedLabel.set then
            if AutoPlant.selectedSeedId and AutoPlant.selectedSeedName then
                local cnt = getRealtimeItemCount(AutoPlant.selectedSeedId)
                btnSelectSeedLabel:set(string.format("[Seed] %s x%d v", AutoPlant.selectedSeedName, cnt))
            else
                btnSelectSeedLabel:set("Bibit: Otomatis dari Tas v")
            end
        end
    end
end

Setups.farmHarvest = function(body)
    lblHarvestStatus = makeLabel(body, "`oStatus: Standby | Siap deteksi pohon ripe``", 19, UDim2.new())

