            if lblHarvestStatus and lblHarvestStatus.set then
                lblHarvestStatus:set(string.format("`cStatus: %s``", AutoHarvest.status or "Running Auto Harvest..."))
            end
        else
            if btnToggleHarvest then btnToggleHarvest.BackgroundColor3 = C.green end
            if btnToggleHarvestLabel and btnToggleHarvestLabel.set then btnToggleHarvestLabel:set("START AUTO HARVEST") end
            if lblHarvestStatus and lblHarvestStatus.set then
                lblHarvestStatus:set(string.format("`oStatus: %s``", AutoHarvest.status or "Standby | Siap deteksi pohon ripe"))
            end
        end
        if lblHarvestStats and lblHarvestStats.set then
            lblHarvestStats:set(string.format("`9Panen: %d pohon``", AutoHarvest.totalHarvested or 0))
        end
    end
end


Setups.farmCheck = function(body)
    AutoFarmCheck.lblStatus = makeLabel(body, "`2Status: Aktif (Auto-Solve Math Captcha)``", 19, UDim2.new())
    AutoFarmCheck.lblStats  = makeLabel(body, "`9Total Terjawab: 0 | Terakhir: --``", 18, UDim2.new())

    local btnRow = Instance.new("Frame", body)
    btnRow.Size = UDim2.new(1, 0, 0, 36)
    btnRow.BackgroundTransparency = 1

    AutoFarmCheck.btnToggle = Instance.new("TextButton", btnRow)
    AutoFarmCheck.btnToggle.Size = UDim2.fromOffset(200, 36)
    AutoFarmCheck.btnToggle.BackgroundColor3 = AutoFarmCheck.enabled and C.green or C.button
    AutoFarmCheck.btnToggle.Font = Enum.Font.GothamBold
    AutoFarmCheck.btnToggle.TextSize = 14
    AutoFarmCheck.btnToggle.TextColor3 = C.text
    AutoFarmCheck.btnToggle.Text = AutoFarmCheck.enabled and "AUTO SOLVE: [ON]" or "AUTO SOLVE: [OFF]"
    corner(AutoFarmCheck.btnToggle, 4)
    stroke(AutoFarmCheck.btnToggle, C.rim, 1)

    AutoFarmCheck.updateUI = function()
        if AutoFarmCheck.btnToggle then
            AutoFarmCheck.btnToggle.BackgroundColor3 = AutoFarmCheck.enabled and C.green or C.button
            AutoFarmCheck.btnToggle.Text = AutoFarmCheck.enabled and "AUTO SOLVE: [ON]" or "AUTO SOLVE: [OFF]"
        end
        if AutoFarmCheck.lblStatus then
            AutoFarmCheck.lblStatus:set(AutoFarmCheck.enabled and "`2Status: Aktif (Auto-Solve Math Captcha)``" or "`4Status: Nonaktif (Manual)``")
        end
        if AutoFarmCheck.lblStats then
            local lastStr = (AutoFarmCheck.lastAnswer ~= nil) and string.format("Jawaban %d (Soal: '%s')", AutoFarmCheck.lastAnswer, AutoFarmCheck.lastQuestion) or "--"
            AutoFarmCheck.lblStats:set(string.format("`9Total Terjawab: %d | Terakhir: %s``", AutoFarmCheck.totalSolved, lastStr))
        end
    end

    AutoFarmCheck.btnToggle.Activated:Connect(function()
        AutoFarmCheck.enabled = not AutoFarmCheck.enabled
        AutoFarmCheck.updateUI()
        pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
    end)
end

Setups.farmMove = function(body)
    local M = FarmLogistics.move
    local lblMoveStatus = makeLabel(body, "`oStatus: Standby``", 19, UDim2.new())
    local lblMoveStats  = makeLabel(body, "`9Dipindah: 0 item | Trip: 0``", 18, UDim2.new())

    local btnRow = Instance.new("Frame", body)
    btnRow.Size = UDim2.new(1, 0, 0, 38)
    btnRow.BackgroundTransparency = 1

    local btnToggleFrame, _, btnToggle, btnToggleLabel = makeButton(btnRow, "START MOVE WORLD", 19, C.green, 8, 36, function()
        if M.active then
            FarmLogistics.moveStop("Dihentikan manual")
        else
            FarmLogistics.moveStart()
        end
    end, 220)
    btnToggleFrame.Position = UDim2.fromOffset(0, 0)

    -- Pilih item target (bisa lebih dari satu) dari isi tas
    local itemDropList = Instance.new("Frame", body)
    itemDropList.Size = UDim2.new(1, 0, 0, 160)
    itemDropList.BackgroundColor3 = C.dark
    itemDropList.BackgroundTransparency = 0.2
    itemDropList.BorderSizePixel = 0
    itemDropList.Visible = false
    corner(itemDropList, 6)
    stroke(itemDropList, C.fieldRim, 1)

    local itemScroll = Instance.new("ScrollingFrame", itemDropList)
    itemScroll.Size = UDim2.new(1, -12, 1, -12)
    itemScroll.Position = UDim2.fromOffset(6, 6)
    itemScroll.BackgroundTransparency = 1
    itemScroll.BorderSizePixel = 0
    itemScroll.ScrollBarThickness = 4
    itemScroll.ScrollBarImageColor3 = C.rim
    itemScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    itemScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
    local itemLayout = Instance.new("UIListLayout", itemScroll)
    itemLayout.SortOrder = Enum.SortOrder.LayoutOrder
    itemLayout.Padding = UDim.new(0, 4)

    local btnPickLabel
    local function pickText()
        if #M.itemIds == 0 then return "Pilih Item Target v" end
        local names = {}
        for i = 1, math.min(#M.itemNames, 3) do names[#names + 1] = M.itemNames[i] end
        local more = (#M.itemIds > 3) and string.format(" +%d", #M.itemIds - 3) or ""
        return "Item: " .. table.concat(names, ", ") .. more .. " v"
    end
    local function isPicked(id)
        for i, v in ipairs(M.itemIds) do if v == id then return i end end
        return nil
    end
    local refreshItemList
    refreshItemList = function()
        for _, ch in ipairs(itemScroll:GetChildren()) do
            if ch:IsA("GuiObject") then ch:Destroy() end
        end
        makeButton(itemScroll, "[Kosongkan pilihan]", 18, C.button, 8, 28, function()
            M.itemIds, M.itemNames = {}, {}
            if btnPickLabel then btnPickLabel:set(pickText()) end
            refreshItemList()
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end, 530)
        for _, it in ipairs(fetchInventoryItems()) do
            if (it.count or 0) > 0 and it.id ~= 18 and it.id ~= 32 then -- skip Fist & Wrench
                local idx = isPicked(it.id)
                makeButton(itemScroll, string.format("%s %s  x%d  (ID: %d)", idx and "[v]" or "[ ]", it.name or "Item", it.count, it.id),
                    18, idx and C.green or C.button, 8, 28, function()
                        local i = isPicked(it.id)
                        if i then
                            table.remove(M.itemIds, i)
                            table.remove(M.itemNames, i)
                        else
                            table.insert(M.itemIds, it.id)
                            table.insert(M.itemNames, it.name or ("#" .. it.id))
                        end
                        if btnPickLabel then btnPickLabel:set(pickText()) end
                        refreshItemList()
                        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                    end, 530)
            end
        end
    end
    local btnPickFrame
    btnPickFrame, _, _, btnPickLabel = makeButton(btnRow, pickText(), 18, C.button, 8, 36, function()
        itemDropList.Visible = not itemDropList.Visible
        if itemDropList.Visible then refreshItemList() end
    end, 300)
    btnPickFrame.Position = UDim2.fromOffset(226, 0)
    makeLabel(body, "`oPilih item di tas (bisa banyak). Item harus ada di tas sekali untuk dipilih.``", 16, UDim2.new())

    -- World asal & tujuan
    local function worldInput(parent, x, w, placeholder, get, set)
        local tb = Instance.new("TextBox", parent)
        tb.Size = UDim2.fromOffset(w, 32)
        tb.Position = UDim2.fromOffset(x, 2)
        tb.BackgroundColor3 = C.field
        tb.BorderSizePixel = 0
        tb.Font = Enum.Font.GothamBold
        tb.TextSize = 14
        tb.TextColor3 = C.text
        tb.PlaceholderColor3 = C.placeholder
        tb.PlaceholderText = placeholder
        tb.Text = get() or ""
        corner(tb, 4)
        stroke(tb, C.fieldRim, 1)
        tb.FocusLost:Connect(function()
            set(tb.Text)
            tb.Text = get() or ""
            if updateMoveUI then updateMoveUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end)
        return tb
    end

    local rowFrom = Instance.new("Frame", body)
    rowFrom.Size = UDim2.new(1, 0, 0, 36)
    rowFrom.BackgroundTransparency = 1
    makeLabel(rowFrom, "`oAsal:``", 18, UDim2.fromOffset(0, 8))
    local inpFrom = worldInput(rowFrom, 70, 170, "World asal (disapu)",
        function() return M.fromWorld end, function(v) M.fromWorld = FarmLogistics.cleanWorld(v) end)
    local inpFromDoor = worldInput(rowFrom, 246, 120, "Door (ops.)",
        function() return M.fromDoor end, function(v) M.fromDoor = (v or ""):gsub("%s+", "") end)
    local btnFromHere = makeButton(rowFrom, "World Ini", 17, C.button, 6, 32, function()
        local cw = FarmLogistics.currentWorld()
        if cw ~= "" then M.fromWorld = cw; inpFrom.Text = cw end
        if updateMoveUI then updateMoveUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, 110)
    btnFromHere.Position = UDim2.fromOffset(372, 1)

    local rowTo = Instance.new("Frame", body)
    rowTo.Size = UDim2.new(1, 0, 0, 36)
    rowTo.BackgroundTransparency = 1
    makeLabel(rowTo, "`oTujuan:``", 18, UDim2.fromOffset(0, 8))
    local inpTo = worldInput(rowTo, 70, 170, "World tujuan (drop)",
        function() return M.toWorld end, function(v) M.toWorld = FarmLogistics.cleanWorld(v) end)
    local inpToDoor = worldInput(rowTo, 246, 120, "Door (ops.)",
        function() return M.toDoor end, function(v) M.toDoor = (v or ""):gsub("%s+", "") end)
    local btnToHere = makeButton(rowTo, "Set Pos Drop", 17, C.button, 6, 32, function()
        local cw = FarmLogistics.currentWorld()
        local px, py = getPlayerTilePos()
        if cw == "" or not px then
            Proxy.notify("`4[Move World] Berdiri di world tujuan dulu, lalu klik Set Pos Drop!``")
            return
        end
        M.toWorld, M.toX, M.toY = cw, px + 1, py + 1
        inpTo.Text = cw
        if updateMoveUI then updateMoveUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        Proxy.notify(string.format("`2[Move World] Tujuan: %s, drop di (%d, %d)``", cw, M.toX, M.toY))
    end, 110)
    btnToHere.Position = UDim2.fromOffset(372, 1)

    local lblDest = makeLabel(body, "`oPos drop tujuan: (belum diset)``", 18, UDim2.new())
    makeLabel(body, "`oCara pakai: pilih item, isi world asal, berdiri di world tujuan & klik Set Pos Drop, lalu START. Bot bolak-balik sampai drop item target di world asal habis.``", 16, UDim2.new())

    updateMoveUI = function()
        if M.active then
            if btnToggle then btnToggle.BackgroundColor3 = C.red end
            if btnToggleLabel and btnToggleLabel.set then btnToggleLabel:set("STOP MOVE WORLD") end
            if lblMoveStatus and lblMoveStatus.set then lblMoveStatus:set("`cStatus: " .. tostring(M.status) .. "``") end
        else
            if btnToggle then btnToggle.BackgroundColor3 = C.green end
            if btnToggleLabel and btnToggleLabel.set then btnToggleLabel:set("START MOVE WORLD") end
            if lblMoveStatus and lblMoveStatus.set then lblMoveStatus:set("`oStatus: " .. tostring(M.status) .. "``") end
        end
        if lblMoveStats and lblMoveStats.set then
            lblMoveStats:set(string.format("`9Dipindah: %d item | Trip: %d``", M.totalMoved or 0, M.trips or 0))
        end
        if btnPickLabel and btnPickLabel.set then btnPickLabel:set(pickText()) end
        if lblDest and lblDest.set then
            lblDest:set((M.toX and M.toY) and string.format("`2Pos drop tujuan: %s (%d, %d)``", M.toWorld ~= "" and M.toWorld or "?", M.toX, M.toY)
                or "`oPos drop tujuan: (belum diset)``")
        end
        if inpFrom and not inpFrom:IsFocused() then inpFrom.Text = M.fromWorld or "" end
        if inpFromDoor and not inpFromDoor:IsFocused() then inpFromDoor.Text = M.fromDoor or "" end
        if inpTo and not inpTo:IsFocused() then inpTo.Text = M.toWorld or "" end
        if inpToDoor and not inpToDoor:IsFocused() then inpToDoor.Text = M.toDoor or "" end
    end
end

Setups.farm = function(page)
    local secPNB = createSection(page, "PNB Controller (Place & Break)", true, 1)
    Setups.farmPNB(secPNB.body)

    local secPlant = createSection(page, "Auto Plant Seeds", false, 2)
    Setups.farmPlant(secPlant.body)

    local secHarvest = createSection(page, "Auto Harvest Trees", false, 3)
    Setups.farmHarvest(secHarvest.body)

    local secMove = createSection(page, "Move World to World (Pindah Item)", false, 4)
    Setups.farmMove(secMove.body)

    local secMagnet = createSection(page, "Auto Collect Drops (Magnet A*)", false, 5)
    Setups.farmMagnet(secMagnet.body)

    local secFarmCheck = createSection(page, "Auto Solve FarmCheck (Math Captcha)", true, 6)
    Setups.farmCheck(secFarmCheck.body)
end

-- ═══════════════════════════════════════
--  PAGE 3: AUTO FACTORY (Pabrik PnB & Farm Terpadu)
-- ═══════════════════════════════════════
Setups.factory = function(page)
    -- Section 1: Controller & Realtime Status
    local secCtrl = createSection(page, "Auto Factory Controller", true, 1)
    local bodyCtrl = secCtrl.body

    lblFactoryStatus = makeLabel(bodyCtrl, "`oStatus: Standby | Tentukan Pos Break & Seed target``", 19, UDim2.new())
    lblFactoryStats  = makeLabel(bodyCtrl, "`9Tertanam: 0 | PnB: 0 | Panen: 0 | Profit Drop: 0``", 18, UDim2.new())

    local ctrlBtnRow = Instance.new("Frame", bodyCtrl)
    ctrlBtnRow.Size                   = UDim2.new(1, 0, 0, 38)
    ctrlBtnRow.BackgroundTransparency = 1

    local btnToggleFactoryFrame
    btnToggleFactoryFrame, _, btnToggleFactory, btnToggleFactoryLabel = makeButton(
        ctrlBtnRow,
        "START AUTO FACTORY",
        19,
        C.green,
        8,
        36,
        function()
            if AutoFactory.active then
                stopAutoFactory()
            else
                startAutoFactory()
            end
        end,
        240
    )
    btnToggleFactoryFrame.Position = UDim2.fromOffset(0, 0)

    -- Section 2: Titik Koordinat & Range Pabrik
    local secCoords = createSection(page, "Koordinat & Konfigurasi Lahan", true, 2)
    local bodyCoords = secCoords.body

    -- Row Pos Break
    local rowBreak = Instance.new("Frame", bodyCoords)
    rowBreak.Size                   = UDim2.new(1, 0, 0, 36)
    rowBreak.BackgroundTransparency = 1

    local lblPosBreak
    local btnSetBreakFrame = makeButton(
        rowBreak,
        "Set Pos Break",
        18,
        C.button,
        6,
        32,
        function()
            local px, py = getPlayerTilePos()
            if px and py then
                AutoFactory.posBreakX = px + 1
                AutoFactory.posBreakY = py + 1
                if lblPosBreak and lblPosBreak.set then
                    lblPosBreak:set(string.format("`2Pos Break: (%d, %d) [Tersimpan]``", px + 1, py + 1))
                end
                print(string.format("[FACTORY] Pos Break diset ke (%d, %d)", px + 1, py + 1))
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end
        end,
        150
    )
    btnSetBreakFrame.Position = UDim2.fromOffset(0, 2)

    local curBreakText = (AutoFactory.posBreakX and AutoFactory.posBreakY)
        and string.format("`2Pos Break: (%d, %d)``", AutoFactory.posBreakX, AutoFactory.posBreakY)
        or "`oPos Break: (Belum diset - Berdiri di spot PnB & klik Set)``"
    lblPosBreak = makeLabel(rowBreak, curBreakText, 18, UDim2.fromOffset(160, 8))

    -- Row Pos Drop
    local rowDrop = Instance.new("Frame", bodyCoords)
    rowDrop.Size                   = UDim2.new(1, 0, 0, 36)
    rowDrop.BackgroundTransparency = 1

    local lblPosDrop
    local btnSetDropFrame = makeButton(
        rowDrop,
        "Set Pos Drop",
        18,
        C.button,
        6,
        32,
        function()
            local px, py = getPlayerTilePos()
            if px and py then
                AutoFactory.posDropX = px + 1
                AutoFactory.posDropY = py + 1
                if lblPosDrop and lblPosDrop.set then
                    lblPosDrop:set(string.format("`2Pos Drop: (%d, %d) [Tersimpan]``", px + 1, py + 1))
                end
                print(string.format("[FACTORY] Pos Drop diset ke (%d, %d)", px + 1, py + 1))
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end
        end,
        150
    )
    btnSetDropFrame.Position = UDim2.fromOffset(0, 2)

    local curDropText = (AutoFactory.posDropX and AutoFactory.posDropY)
        and string.format("`2Pos Drop: (%d, %d)``", AutoFactory.posDropX, AutoFactory.posDropY)
        or "`oPos Drop: (Belum diset - Berdiri di storage & klik Set)``"
    lblPosDrop = makeLabel(rowDrop, curDropText, 18, UDim2.fromOffset(160, 8))

    -- Row Input Angka: Factory Length & Profit Limit
    local rowInputs = Instance.new("Frame", bodyCoords)
    rowInputs.Size                   = UDim2.new(1, 0, 0, 36)
    rowInputs.BackgroundTransparency = 1

    makeLabel(rowInputs, "`9Panjang Lahan (Tile):``", 18, UDim2.fromOffset(0, 8))

    local inpLength = Instance.new("TextBox", rowInputs)
    inpLength.Size                   = UDim2.fromOffset(70, 30)
    inpLength.Position               = UDim2.fromOffset(180, 2)
    inpLength.BackgroundColor3       = C.field
    inpLength.BorderSizePixel        = 0
    inpLength.Font                   = Enum.Font.FredokaOne
    inpLength.TextSize               = 17
    inpLength.TextColor3             = C.text
    inpLength.Text                   = tostring(AutoFactory.factoryLength or 30)
    corner(inpLength, 6)
    stroke(inpLength, C.fieldRim, 1)

    inpLength.FocusLost:Connect(function()
        local val = tonumber(inpLength.Text)
        if val and val > 0 then
            AutoFactory.factoryLength = math.clamp(math.floor(val), 1, 100)
            inpLength.Text = tostring(AutoFactory.factoryLength)
        else
            inpLength.Text = tostring(AutoFactory.factoryLength or 30)
        end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowInputs, "`9Drop Limit (Seeds):``", 18, UDim2.fromOffset(270, 8))

    local inpProfit = Instance.new("TextBox", rowInputs)
    inpProfit.Size                   = UDim2.fromOffset(70, 30)
    inpProfit.Position               = UDim2.fromOffset(450, 2)
    inpProfit.BackgroundColor3       = C.field
    inpProfit.BorderSizePixel        = 0
    inpProfit.Font                   = Enum.Font.FredokaOne
    inpProfit.TextSize               = 17
    inpProfit.TextColor3             = C.text
    inpProfit.Text                   = tostring(AutoFactory.profitLimit or 100)
    corner(inpProfit, 6)
    stroke(inpProfit, C.fieldRim, 1)

    inpProfit.FocusLost:Connect(function()
        local val = tonumber(inpProfit.Text)
        if val and val > 0 then
            AutoFactory.profitLimit = math.clamp(math.floor(val), 1, 200)
            inpProfit.Text = tostring(AutoFactory.profitLimit)
        else
            inpProfit.Text = tostring(AutoFactory.profitLimit or 100)
        end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Section 3: Seed & Block Pairing
    local secPair = createSection(page, "Pemilihan Pasangan Seed & Blok", true, 3)
    local bodyPair = secPair.body

    local lblPairInfo = makeLabel(
        bodyPair,
        string.format("`wTarget Seed: %s (#%s)  |  Target Blok: %s (#%s)``",
            AutoFactory.targetSeedName or "Belum dipilih",
            AutoFactory.targetSeedId and tostring(AutoFactory.targetSeedId) or "-",
            AutoFactory.targetBlockName or "Belum terpasang",
            AutoFactory.targetBlockId and tostring(AutoFactory.targetBlockId) or "-"
        ),
        19,
        UDim2.new()
    )

    local pairBtnRow = Instance.new("Frame", bodyPair)
    pairBtnRow.Size                   = UDim2.new(1, 0, 0, 36)
    pairBtnRow.BackgroundTransparency = 1

    -- Dropdown Container List Bibit
    local factorySeedDropList = Instance.new("Frame", bodyPair)
    factorySeedDropList.Size                   = UDim2.new(1, 0, 0, 160)
    factorySeedDropList.BackgroundColor3       = C.dark
    factorySeedDropList.BackgroundTransparency = 0.2
    factorySeedDropList.BorderSizePixel        = 0
    factorySeedDropList.Visible                = false
    corner(factorySeedDropList, 6)
    stroke(factorySeedDropList, C.fieldRim, 1)

    local factorySeedScroll = Instance.new("ScrollingFrame", factorySeedDropList)
    factorySeedScroll.Size               = UDim2.new(1, -12, 1, -12)
    factorySeedScroll.Position           = UDim2.fromOffset(6, 6)
    factorySeedScroll.BackgroundTransparency = 1
    factorySeedScroll.BorderSizePixel    = 0
    factorySeedScroll.ScrollBarThickness = 4
    factorySeedScroll.ScrollBarImageColor3 = C.rim
    factorySeedScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    factorySeedScroll.CanvasSize         = UDim2.new(0, 0, 0, 0)

    local seedListLayout = Instance.new("UIListLayout", factorySeedScroll)
    seedListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    seedListLayout.Padding   = UDim.new(0, 4)

    local btnSelectFactorySeedFrame, _, _, btnSelectFactorySeedLabel

    local function refreshFactorySeedDropdown()
        for _, ch in ipairs(factorySeedScroll:GetChildren()) do
            if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                ch:Destroy()
            end
        end

        local inv = fetchInventoryItems()
        local seedCount = 0
        for _, it in ipairs(inv) do
            if (it.kind == "seed" or string.find((it.name or ""):lower(), "seed")) and it.count > 0 then
                seedCount = seedCount + 1
                local isSelected = (AutoFactory.targetSeedId == it.id)
                local bId = (ItemDB and ItemDB[it.id] and ItemDB[it.id].block) or (it.id - 1)
                local bName = (ItemDB and ItemDB[bId] and ItemDB[bId].name) or ("Block #" .. bId)

                makeButton(
                    factorySeedScroll,
                    string.format("[Seed] %s x%d (#%d) ➔ Blok: %s (#%d)",
                        it.name or "Seed", it.count, it.id, bName, bId),
                    18,
                    isSelected and C.green or C.button,
                    6,
                    30,
                    function()
                        AutoFactory.targetSeedId = it.id
                        AutoFactory.targetSeedName = it.name or ("Seed #" .. it.id)
                        AutoFactory.targetBlockId = bId
                        AutoFactory.targetBlockName = bName

                        if btnSelectFactorySeedLabel and btnSelectFactorySeedLabel.set then
                            btnSelectFactorySeedLabel:set(string.format("[Seed] %s v", AutoFactory.targetSeedName))
                        end
                        if lblPairInfo and lblPairInfo.set then
                            lblPairInfo:set(string.format("`wTarget Seed: %s (#%d)  |  Target Blok: %s (#%d)``",
                                AutoFactory.targetSeedName, AutoFactory.targetSeedId,
                                AutoFactory.targetBlockName, AutoFactory.targetBlockId))
                        end
                        factorySeedDropList.Visible = false
                        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                    end,
                    530
                )
            end
        end

        if seedCount == 0 then
            local emptyNotice = Instance.new("Frame", factorySeedScroll)
            emptyNotice.Size = UDim2.new(1, 0, 0, 30)
            emptyNotice.BackgroundTransparency = 1
            makeLabel(emptyNotice, "`o(Tidak ada bibit terdeteksi di dalam tas)``", 18, UDim2.fromScale(0.5, 0.5), {anchor = Vector2.new(0.5, 0.5)})
        end
    end

    btnSelectFactorySeedFrame, _, _, btnSelectFactorySeedLabel = makeButton(
        pairBtnRow,
        AutoFactory.targetSeedName and ("[Seed] " .. AutoFactory.targetSeedName .. " v") or "Pilih Seed Pabrik v",
        18,
        C.button,
        6,
        32,
        function()
            factorySeedDropList.Visible = not factorySeedDropList.Visible
            if factorySeedDropList.Visible then
                refreshFactorySeedDropdown()
            end
        end,
        250
    )
    btnSelectFactorySeedFrame.Position = UDim2.fromOffset(0, 2)

    local btnRefPairFrame = makeButton(
        pairBtnRow,
        "[Ref]",
        19,
        C.button,
        6,
        32,
        function()
            if refreshInventory then refreshInventory() end
            refreshFactorySeedDropdown()
        end,
        70
    )
    btnRefPairFrame.Position = UDim2.fromOffset(258, 2)

    updateFactoryUI = function()
        if AutoFactory.active then
            if btnToggleFactory then btnToggleFactory.BackgroundColor3 = C.red end
            if btnToggleFactoryLabel and btnToggleFactoryLabel.set then
                btnToggleFactoryLabel:set("STOP AUTO FACTORY")
            end
            if lblFactoryStatus and lblFactoryStatus.set then
                lblFactoryStatus:set(string.format("`cStatus: %s``", AutoFactory.status or "Running..."))
            end
        else
            if btnToggleFactory then btnToggleFactory.BackgroundColor3 = C.green end
            if btnToggleFactoryLabel and btnToggleFactoryLabel.set then
                btnToggleFactoryLabel:set("START AUTO FACTORY")
            end
            if lblFactoryStatus and lblFactoryStatus.set then
                lblFactoryStatus:set(string.format("`oStatus: %s``", AutoFactory.status or "Standby"))
            end
        end

        if lblFactoryStats and lblFactoryStats.set then
            lblFactoryStats:set(string.format("`9Tertanam: %d | PnB: %d | Panen: %d | Profit Drop: %d``",
                AutoFactory.totalPlanted or 0,
                AutoFactory.totalPnB or 0,
                AutoFactory.totalHarvested or 0,
                AutoFactory.totalProfitDropped or 0
            ))
        end

        if lblPosBreak and lblPosBreak.set then
            local curBreakText = (AutoFactory.posBreakX and AutoFactory.posBreakY)
                and string.format("`2Pos Break: (%d, %d)``", AutoFactory.posBreakX, AutoFactory.posBreakY)
                or "`oPos Break: (Belum diset - Berdiri di spot PnB & klik Set)``"
            lblPosBreak:set(curBreakText)
        end

        if lblPosDrop and lblPosDrop.set then
            local curDropText = (AutoFactory.posDropX and AutoFactory.posDropY)
                and string.format("`2Pos Drop: (%d, %d)``", AutoFactory.posDropX, AutoFactory.posDropY)
                or "`oPos Drop: (Belum diset - Berdiri di storage & klik Set)``"
            lblPosDrop:set(curDropText)
        end

        if inpLength then inpLength.Text = tostring(AutoFactory.factoryLength or 30) end
        if inpProfit then inpProfit.Text = tostring(AutoFactory.profitLimit or 100) end

        if btnSelectFactorySeedLabel and btnSelectFactorySeedLabel.set then
            btnSelectFactorySeedLabel:set(AutoFactory.targetSeedName and string.format("[Seed] %s v", AutoFactory.targetSeedName) or "Pilih Seed Pabrik v")
        end

        if lblPairInfo and lblPairInfo.set then
            lblPairInfo:set(string.format("`wTarget Seed: %s (#%s)  |  Target Blok: %s (#%s)``",
                AutoFactory.targetSeedName or "Belum dipilih",
                AutoFactory.targetSeedId and tostring(AutoFactory.targetSeedId) or "-",
                AutoFactory.targetBlockName or "Belum terpasang",
                AutoFactory.targetBlockId and tostring(AutoFactory.targetBlockId) or "-"
            ))
        end
    end
end

-- ═══════════════════════════════════════
--  PAGE: AUTO ROTATION (Multi-World Farm Queue & Storage Drop)
-- ═══════════════════════════════════════
Setups.rotation = function(page)
    -- Section 1: Controller & Status
    local secCtrl = createSection(page, "Auto Rotation Controller", true, 1)
    local bodyCtrl = secCtrl.body

    lblRotationStatus = makeLabel(bodyCtrl, "`oStatus: Standby | Tambahkan world farm di bawah``", 19, UDim2.new())
    lblRotationStats  = makeLabel(bodyCtrl, "`9Rotasi: 0 World | Panen: 0 | Tanam: 0 | PnB: 0 | Profit Drop: 0``", 18, UDim2.new())

    local ctrlBtnRow = Instance.new("Frame", bodyCtrl)
    ctrlBtnRow.Size                   = UDim2.new(1, 0, 0, 38)
    ctrlBtnRow.BackgroundTransparency = 1

    local btnToggleRotationFrame
    btnToggleRotationFrame, _, btnToggleRotation, btnToggleRotationLabel = makeButton(
        ctrlBtnRow,
        AutoRotation.active and "STOP AUTO ROTATION" or "START AUTO ROTATION",
        19,
        AutoRotation.active and C.red or C.green,
        8,
        36,
        function()
            if AutoRotation.active then
                stopAutoRotation()
            else
                startAutoRotation()
            end
        end,
        250
    )
    btnToggleRotationFrame.Position = UDim2.fromOffset(0, 0)

    -- Section 2: Daftar World Farm (Queue List)
    local secWorlds = createSection(page, "Daftar World Farm (Queue / Rotation List)", true, 2)
    local bodyWorlds = secWorlds.body

    makeLabel(bodyWorlds, "`oTambah World (Format: NAMEWORLD|IDSEED atau Nama Saja):``", 18, UDim2.new())

    local addRow = Instance.new("Frame", bodyWorlds)
    addRow.Size                   = UDim2.new(1, 0, 0, 36)
    addRow.BackgroundTransparency = 1

    local inpAddWorld = Instance.new("TextBox", addRow)
    inpAddWorld.Size                   = UDim2.new(1, -170, 0, 34)
    inpAddWorld.Position               = UDim2.fromOffset(0, 1)
    inpAddWorld.BackgroundColor3       = C.field
    inpAddWorld.BorderSizePixel        = 0
    inpAddWorld.Font                   = Enum.Font.GothamBold
    inpAddWorld.TextSize               = 15
    inpAddWorld.TextColor3             = C.text
    inpAddWorld.PlaceholderColor3      = C.placeholder
    inpAddWorld.PlaceholderText        = "NAMEWORLD|IDSEED (cth: MYFARM|3)"
    inpAddWorld.Text                   = ""
    corner(inpAddWorld, 4)
    stroke(inpAddWorld, C.fieldRim, 1)

    local btnAddWorldFrame = makeButton(
        addRow,
        "+ Tambah World",
        18,
        C.button,
        6,
        34,
        function()
            local text = inpAddWorld.Text
            if text and text ~= "" then
                local parts = string.split(text, "|")
                local wName = string.upper((parts[1] or ""):gsub("%s+", ""))
                local rawSeed = parts[2] and (parts[2]:gsub("^%s*(.-)%s*$", "%1")) or ""
                local sId = tonumber(rawSeed)
                if not sId and rawSeed ~= "" and ItemDB then
                    local lowSeed = rawSeed:lower()
                    for id, v in pairs(ItemDB) do
                        if type(v) == "table" and v.name and v.name:lower() == lowSeed then
                            sId = id
                            break
                        end
                    end
                end
                sId = sId or 3
                local dId = parts[3] and (parts[3]:gsub("%s+", "")) or ""

                if wName ~= "" then
                    local sItem = ItemDB and ItemDB[sId]
                    local sName = (sItem and sItem.name) or ("Seed #" .. tostring(sId))

                    table.insert(AutoRotation.worlds, {
                        worldName = wName,
                        seedId = sId,
                        seedName = sName,
                        door = dId,
                        countdownEndsAt = 0,
                        lastPlantedTime = 0,
                        ripeCount = 0,
                        unreadyCount = 0,
                    })

                    inpAddWorld.Text = ""
                    if refreshRotationWorldList then refreshRotationWorldList() end
                    if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                end
            end
        end,
        160
    )
    btnAddWorldFrame.Position = UDim2.new(1, -160, 0, 1)

    -- Scrollable Queue Container
    local queueContainer = Instance.new("Frame", bodyWorlds)
    queueContainer.Size                   = UDim2.new(1, 0, 0, 160)
    queueContainer.BackgroundColor3       = C.dark
    queueContainer.BackgroundTransparency = 0.5
    queueContainer.BorderSizePixel        = 0
    corner(queueContainer, 6)
    stroke(queueContainer, C.fieldRim, 1)

    local queueScroll = Instance.new("ScrollingFrame", queueContainer)
    queueScroll.Size                   = UDim2.new(1, -8, 1, -8)
    queueScroll.Position               = UDim2.fromOffset(4, 4)
    queueScroll.BackgroundTransparency = 1
    queueScroll.BorderSizePixel        = 0
    queueScroll.ScrollBarThickness     = 6
    queueScroll.ScrollBarImageColor3   = C.rim
    queueScroll.ScrollingDirection     = Enum.ScrollingDirection.Y
    queueScroll.AutomaticCanvasSize    = Enum.AutomaticSize.Y
    queueScroll.CanvasSize             = UDim2.new()

    local queueLayout = Instance.new("UIListLayout", queueScroll)
    queueLayout.SortOrder = Enum.SortOrder.LayoutOrder
    queueLayout.Padding   = UDim.new(0, 4)

    local countdownLabels = {}

    refreshRotationWorldList = function()
        for _, child in ipairs(queueScroll:GetChildren()) do
            if child:IsA("Frame") then child:Destroy() end
        end
        table.clear(countdownLabels)

        if #AutoRotation.worlds == 0 then
            local emptyRow = Instance.new("Frame", queueScroll)
            emptyRow.Size = UDim2.new(1, 0, 0, 30)
            emptyRow.BackgroundTransparency = 1
            makeLabel(emptyRow, "`o(Belum ada World Farm ditambahkan - Masukkan di atas)``", 18, UDim2.fromScale(0.5, 0.5), {anchor = Vector2.new(0.5, 0.5)})
            return
        end

        for idx, entry in ipairs(AutoRotation.worlds) do
            local itemRow = Instance.new("Frame", queueScroll)
            itemRow.Size                   = UDim2.new(1, 0, 0, 36)
            itemRow.BackgroundColor3       = C.field
            itemRow.BackgroundTransparency = 0.4
            corner(itemRow, 4)

            -- Left: Name & Seed
            local nameText = string.format("`c#%d. %s`` | `9%s (#%d)``", idx, entry.worldName, entry.seedName or "Seed", entry.seedId or 3)
            makeLabel(itemRow, nameText, 18, UDim2.fromOffset(8, 8))

            -- Center: Countdown / Status badge
            local lblCountdown = makeLabel(itemRow, "`o[Standby]``", 17, UDim2.fromOffset(360, 8))
            countdownLabels[idx] = { lbl = lblCountdown, entry = entry }

            -- Right: Warp & Delete buttons
            local btnWarp = makeButton(itemRow, "Warp", 16, C.cyan, 4, 26, function()
                warpToWorld(entry.worldName, entry.door)
            end, 65)
            btnWarp.Position = UDim2.new(1, -115, 0, 5)

            local btnDel = makeButton(itemRow, "X", 16, C.red, 4, 26, function()
                table.remove(AutoRotation.worlds, idx)
                if refreshRotationWorldList then refreshRotationWorldList() end
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end, 36)
            btnDel.Position = UDim2.new(1, -44, 0, 5)
        end
    end

    -- Section 3: Konfigurasi Storage Seed & Profit
    local secStorage = createSection(page, "Konfigurasi Storage Seed & Profit Drop", true, 3)
    local bodyStorage = secStorage.body

    local lblStoragePos
    local inpStoreWorld, inpStoreDoor, inpStoreX, inpStoreY, inpProfitDrop, inpSeedReserve

    local rowSetDrop = Instance.new("Frame", bodyStorage)
    rowSetDrop.Size                   = UDim2.new(1, 0, 0, 36)
    rowSetDrop.BackgroundTransparency = 1

    local btnSetStoreFrame = makeButton(
        rowSetDrop,
        "Set Pos Drop Seed",
        18,
        C.button,
        6,
        32,
        function()
            local px, py = getPlayerTilePos()
            local w = getNativeWorld and getNativeWorld()
            local curWorldName = (w and w.name) or (Proxy and Proxy.lastWorldName) or ""
            if curWorldName ~= "" and px and py then
                AutoRotation.storageWorld = string.upper(curWorldName)
                AutoRotation.storageDropX = px + 1
                AutoRotation.storageDropY = py + 1
                if inpStoreWorld then inpStoreWorld.Text = AutoRotation.storageWorld end
                if inpStoreX then inpStoreX.Text = tostring(AutoRotation.storageDropX) end
                if inpStoreY then inpStoreY.Text = tostring(AutoRotation.storageDropY) end
                if lblStoragePos and lblStoragePos.set then
                    lblStoragePos:set(string.format("`2Storage: %s | Pos: (%d, %d) [Tersimpan]``", AutoRotation.storageWorld, px + 1, py + 1))
                end
                print(string.format("[ROTATION] Storage set: %s (%d, %d)", AutoRotation.storageWorld, px + 1, py + 1))
                if updateRotationUI then updateRotationUI() end
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end
        end,
        170
    )
    btnSetStoreFrame.Position = UDim2.fromOffset(0, 2)

    local curStoreText = (AutoRotation.storageWorld and AutoRotation.storageWorld ~= "" and AutoRotation.storageDropX and AutoRotation.storageDropY)
        and string.format("`2Storage: %s | Pos: (%d, %d)``", AutoRotation.storageWorld, AutoRotation.storageDropX, AutoRotation.storageDropY)
        or "`oStorage: (Belum diset - Berdiri di storage world & klik Set)``"
    lblStoragePos = makeLabel(rowSetDrop, curStoreText, 18, UDim2.fromOffset(180, 8))

    -- Row Input: Manual World & Door ID
    local rowManualStorage = Instance.new("Frame", bodyStorage)
    rowManualStorage.Size                   = UDim2.new(1, 0, 0, 36)
    rowManualStorage.BackgroundTransparency = 1

    makeLabel(rowManualStorage, "`oNama Storage:``", 18, UDim2.fromOffset(0, 8))

    inpStoreWorld = Instance.new("TextBox", rowManualStorage)
    inpStoreWorld.Size                   = UDim2.fromOffset(140, 32)
    inpStoreWorld.Position               = UDim2.fromOffset(115, 2)
    inpStoreWorld.BackgroundColor3       = C.field
    inpStoreWorld.BorderSizePixel        = 0
    inpStoreWorld.Font                   = Enum.Font.GothamBold
    inpStoreWorld.TextSize               = 15
    inpStoreWorld.TextColor3             = C.text
    inpStoreWorld.PlaceholderText        = "World Name"
    inpStoreWorld.Text                   = AutoRotation.storageWorld or ""
    corner(inpStoreWorld, 4)
    stroke(inpStoreWorld, C.fieldRim, 1)

    inpStoreWorld.FocusLost:Connect(function()
        local txt = string.upper((string.gsub(inpStoreWorld.Text or "", "%s+", "")))
        if txt ~= "" then
            AutoRotation.storageWorld = txt
        end
        inpStoreWorld.Text = AutoRotation.storageWorld or ""
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowManualStorage, "`oID Door:``", 18, UDim2.fromOffset(270, 8))

    inpStoreDoor = Instance.new("TextBox", rowManualStorage)
    inpStoreDoor.Size                   = UDim2.fromOffset(100, 32)
    inpStoreDoor.Position               = UDim2.fromOffset(340, 2)
    inpStoreDoor.BackgroundColor3       = C.field
    inpStoreDoor.BorderSizePixel        = 0
    inpStoreDoor.Font                   = Enum.Font.GothamBold
    inpStoreDoor.TextSize               = 15
    inpStoreDoor.TextColor3             = C.text
    inpStoreDoor.PlaceholderText        = "(Opsional)"
    inpStoreDoor.Text                   = AutoRotation.storageDoor or ""
    corner(inpStoreDoor, 4)
    stroke(inpStoreDoor, C.fieldRim, 1)

    inpStoreDoor.FocusLost:Connect(function()
        local txt = string.gsub(inpStoreDoor.Text or "", "%s+", "")
        AutoRotation.storageDoor = txt
        inpStoreDoor.Text = txt
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Row Input: Manual Drop Coordinates X & Y
    local rowManualPos = Instance.new("Frame", bodyStorage)
    rowManualPos.Size                   = UDim2.new(1, 0, 0, 36)
    rowManualPos.BackgroundTransparency = 1

    makeLabel(rowManualPos, "`oPos Drop X:``", 18, UDim2.fromOffset(0, 8))

    inpStoreX = Instance.new("TextBox", rowManualPos)
    inpStoreX.Size                   = UDim2.fromOffset(100, 32)
    inpStoreX.Position               = UDim2.fromOffset(100, 2)
    inpStoreX.BackgroundColor3       = C.field
    inpStoreX.BorderSizePixel        = 0
    inpStoreX.Font                   = Enum.Font.GothamBold
    inpStoreX.TextSize               = 15
    inpStoreX.TextColor3             = C.text
    inpStoreX.PlaceholderText        = "Tile X"
    inpStoreX.Text                   = tostring(AutoRotation.storageDropX or "")
    corner(inpStoreX, 4)
    stroke(inpStoreX, C.fieldRim, 1)

    inpStoreX.FocusLost:Connect(function()
        local v = tonumber(inpStoreX.Text)
        if v and v > 0 then
            AutoRotation.storageDropX = math.floor(v)
        end
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowManualPos, "`oPos Drop Y:``", 18, UDim2.fromOffset(220, 8))

    inpStoreY = Instance.new("TextBox", rowManualPos)
    inpStoreY.Size                   = UDim2.fromOffset(100, 32)
    inpStoreY.Position               = UDim2.fromOffset(320, 2)
    inpStoreY.BackgroundColor3       = C.field
    inpStoreY.BorderSizePixel        = 0
    inpStoreY.Font                   = Enum.Font.GothamBold
    inpStoreY.TextSize               = 15
    inpStoreY.TextColor3             = C.text
    inpStoreY.PlaceholderText        = "Tile Y"
    inpStoreY.Text                   = tostring(AutoRotation.storageDropY or "")
    corner(inpStoreY, 4)
    stroke(inpStoreY, C.fieldRim, 1)

    inpStoreY.FocusLost:Connect(function()
        local v = tonumber(inpStoreY.Text)
        if v and v > 0 then
            AutoRotation.storageDropY = math.floor(v)
        end
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Row Input: Seed Profit to Drop & Min Reserve
    local rowProfitInputs = Instance.new("Frame", bodyStorage)
    rowProfitInputs.Size                   = UDim2.new(1, 0, 0, 36)
    rowProfitInputs.BackgroundTransparency = 1

    makeLabel(rowProfitInputs, "`oDrop Profit:``", 18, UDim2.fromOffset(0, 8))

    inpProfitDrop = Instance.new("TextBox", rowProfitInputs)
    inpProfitDrop.Size                   = UDim2.fromOffset(100, 32)
    inpProfitDrop.Position               = UDim2.fromOffset(100, 2)
    inpProfitDrop.BackgroundColor3       = C.field
    inpProfitDrop.BorderSizePixel        = 0
    inpProfitDrop.Font                   = Enum.Font.GothamBold
    inpProfitDrop.TextSize               = 15
    inpProfitDrop.TextColor3             = C.text
    inpProfitDrop.Text                   = tostring(AutoRotation.seedProfitToDrop or 100)
    corner(inpProfitDrop, 4)
    stroke(inpProfitDrop, C.fieldRim, 1)

    inpProfitDrop.FocusLost:Connect(function()
        local v = tonumber(inpProfitDrop.Text)
        if v and v > 0 then AutoRotation.seedProfitToDrop = math.floor(v) else AutoRotation.seedProfitToDrop = 100 end
        inpProfitDrop.Text = tostring(AutoRotation.seedProfitToDrop)
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowProfitInputs, "`oCadangan Tanam:``", 18, UDim2.fromOffset(220, 8))

    inpSeedReserve = Instance.new("TextBox", rowProfitInputs)
    inpSeedReserve.Size                   = UDim2.fromOffset(100, 32)
    inpSeedReserve.Position               = UDim2.fromOffset(360, 2)
    inpSeedReserve.BackgroundColor3       = C.field
    inpSeedReserve.BorderSizePixel        = 0
    inpSeedReserve.Font                   = Enum.Font.GothamBold
    inpSeedReserve.TextSize               = 15
    inpSeedReserve.TextColor3             = C.text
    inpSeedReserve.Text                   = tostring(AutoRotation.minSeedReserve or 90)
    corner(inpSeedReserve, 4)
    stroke(inpSeedReserve, C.fieldRim, 1)

    inpSeedReserve.FocusLost:Connect(function()
        local v = tonumber(inpSeedReserve.Text)
        if v and v >= 0 then AutoRotation.minSeedReserve = math.floor(v) else AutoRotation.minSeedReserve = 90 end
        inpSeedReserve.Text = tostring(AutoRotation.minSeedReserve)
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(bodyStorage, "`9💡 Info: Profit 100 seed dibuang saat isi tas >= 190 bibit (100 dibuang, 90 disimpan untuk tanam berikutnya)``", 16, UDim2.new())

    -- Section 4: Auto Buy Store Pack & Drop (Gems PnB)
    local secAutoBuyPack = createSection(page, "Auto Buy Store Pack & Drop (Gems PnB)", true, 4)
    local bodyAutoBuyPack = secAutoBuyPack.body

    local btnToggleAutoBuyPack, btnToggleAutoBuyPackLabel
    local btnPickPack, btnPickPackLabel
    local lblSelectedPackInfo, lblPackStoragePos
    local inpBuyPackCount, inpPackStoreWorld, inpPackStoreDoor, inpPackStoreX, inpPackStoreY

    local rowToggleBuyPack = Instance.new("Frame", bodyAutoBuyPack)
    rowToggleBuyPack.Size                   = UDim2.new(1, 0, 0, 36)
    rowToggleBuyPack.BackgroundTransparency = 1

    local btnTupleBuy = { makeButton(
        rowToggleBuyPack,
        AutoRotation.autoBuyPack and "Auto Buy Pack: ON" or "Auto Buy Pack: OFF",
        18,
        AutoRotation.autoBuyPack and C.green or C.button,
        6,
        32,
        function()
            AutoRotation.autoBuyPack = not AutoRotation.autoBuyPack
            if updateRotationUI then updateRotationUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end,
        180
    ) }
    btnToggleAutoBuyPack = btnTupleBuy[1]
    btnToggleAutoBuyPackLabel = btnTupleBuy[4]

    -- Row: Pack Picker / Selector
    local rowPackPicker = Instance.new("Frame", bodyAutoBuyPack)
    rowPackPicker.Size                   = UDim2.new(1, 0, 0, 36)
    rowPackPicker.BackgroundTransparency = 1

    makeLabel(rowPackPicker, "`oTarget Pack:``", 18, UDim2.fromOffset(0, 8))

    local curPackDef = AutoShop.getOfferByKey(AutoRotation.buyPackKey or "world_lock")
    local curPackName = curPackDef and curPackDef.name or "World Lock"
    local curPackPrice = AutoShop.getOfferPrice(AutoRotation.buyPackKey or "world_lock")
    if curPackPrice <= 0 then curPackPrice = curPackDef and curPackDef.price or 2200 end

    local btnTuplePick = { makeButton(
        rowPackPicker,
        string.format("%s (%d Gems)", curPackName, curPackPrice),
        16,
        C.button,
        6,
        32,
        function()
            -- Buka modal / cycling atau pindah ke Tab Shop untuk pilih pack
            if switchTab then switchTab("shop") end
        end,
        220
    ) }
    btnPickPack = btnTuplePick[1]
    btnPickPackLabel = btnTuplePick[4]
    btnPickPack.Position = UDim2.fromOffset(115, 2)

    makeLabel(rowPackPicker, "`oJumlah:``", 18, UDim2.fromOffset(345, 8))

    inpBuyPackCount = Instance.new("TextBox", rowPackPicker)
    inpBuyPackCount.Size                   = UDim2.fromOffset(80, 32)
    inpBuyPackCount.Position               = UDim2.fromOffset(410, 2)
    inpBuyPackCount.BackgroundColor3       = C.field
    inpBuyPackCount.BorderSizePixel        = 0
    inpBuyPackCount.Font                   = Enum.Font.GothamBold
    inpBuyPackCount.TextSize               = 15
    inpBuyPackCount.TextColor3             = C.text
    inpBuyPackCount.PlaceholderText        = "Jml Pack"
    inpBuyPackCount.Text                   = tostring(AutoRotation.buyPackCount or 1)
    corner(inpBuyPackCount, 4)
    stroke(inpBuyPackCount, C.fieldRim, 1)

    inpBuyPackCount.FocusLost:Connect(function()
        local v = tonumber(inpBuyPackCount.Text)
        if v and v > 0 then
            AutoRotation.buyPackCount = math.floor(v)
        else
            AutoRotation.buyPackCount = 1
        end
        inpBuyPackCount.Text = tostring(AutoRotation.buyPackCount)
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    lblSelectedPackInfo = makeLabel(bodyAutoBuyPack, string.format("`2Target: %dx %s = %d Gems (Klik nama pack untuk buka Tab Shop)``", AutoRotation.buyPackCount or 1, curPackName, (AutoRotation.buyPackCount or 1) * curPackPrice), 16, UDim2.new())

    -- Row: Set Pos Drop Pack
    local rowSetPackDrop = Instance.new("Frame", bodyAutoBuyPack)
    rowSetPackDrop.Size                   = UDim2.new(1, 0, 0, 36)
    rowSetPackDrop.BackgroundTransparency = 1

    local btnSetPackFrame = makeButton(
        rowSetPackDrop,
        "Set Pos Drop Pack",
        18,
        C.button,
        6,
        32,
        function()
            local px, py = getPlayerTilePos()
            local w = getNativeWorld and getNativeWorld()
            local curWorldName = (w and w.name) or (Proxy and Proxy.lastWorldName) or ""
            if curWorldName ~= "" and px and py then
                AutoRotation.packStorageWorld = string.upper(curWorldName)
                AutoRotation.packStorageDropX = px + 1
                AutoRotation.packStorageDropY = py + 1
                if inpPackStoreWorld then inpPackStoreWorld.Text = AutoRotation.packStorageWorld end
                if inpPackStoreX then inpPackStoreX.Text = tostring(AutoRotation.packStorageDropX) end
                if inpPackStoreY then inpPackStoreY.Text = tostring(AutoRotation.packStorageDropY) end
                print(string.format("[ROTATION] Storage Pack set: %s (%d, %d)", AutoRotation.packStorageWorld, px + 1, py + 1))
                if updateRotationUI then updateRotationUI() end
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end
        end,
        170
    )
    btnSetPackFrame.Position = UDim2.fromOffset(0, 2)

    local curPackStoreText = (AutoRotation.packStorageWorld and AutoRotation.packStorageWorld ~= "" and AutoRotation.packStorageDropX and AutoRotation.packStorageDropY)
        and string.format("`2Storage Pack: %s | Pos: (%d, %d)``", AutoRotation.packStorageWorld, AutoRotation.packStorageDropX, AutoRotation.packStorageDropY)
        or "`oStorage Pack: (Belum diset - Berdiri di storage world & klik Set)``"
    lblPackStoragePos = makeLabel(rowSetPackDrop, curPackStoreText, 18, UDim2.fromOffset(180, 8))

    -- Row Input: Manual World Pack & Door ID
    local rowManualPackStorage = Instance.new("Frame", bodyAutoBuyPack)
    rowManualPackStorage.Size                   = UDim2.new(1, 0, 0, 36)
    rowManualPackStorage.BackgroundTransparency = 1

    makeLabel(rowManualPackStorage, "`oNama Storage Pack:``", 18, UDim2.fromOffset(0, 8))

    inpPackStoreWorld = Instance.new("TextBox", rowManualPackStorage)
    inpPackStoreWorld.Size                   = UDim2.fromOffset(140, 32)
    inpPackStoreWorld.Position               = UDim2.fromOffset(150, 2)
    inpPackStoreWorld.BackgroundColor3       = C.field
    inpPackStoreWorld.BorderSizePixel        = 0
    inpPackStoreWorld.Font                   = Enum.Font.GothamBold
    inpPackStoreWorld.TextSize               = 15
    inpPackStoreWorld.TextColor3             = C.text
    inpPackStoreWorld.PlaceholderText        = "World Pack"
    inpPackStoreWorld.Text                   = AutoRotation.packStorageWorld or ""
    corner(inpPackStoreWorld, 4)
    stroke(inpPackStoreWorld, C.fieldRim, 1)

    inpPackStoreWorld.FocusLost:Connect(function()
        local txt = string.upper((string.gsub(inpPackStoreWorld.Text or "", "%s+", "")))
        if txt ~= "" then AutoRotation.packStorageWorld = txt end
        inpPackStoreWorld.Text = AutoRotation.packStorageWorld or ""
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowManualPackStorage, "`oID Door:``", 18, UDim2.fromOffset(300, 8))

    inpPackStoreDoor = Instance.new("TextBox", rowManualPackStorage)
    inpPackStoreDoor.Size                   = UDim2.fromOffset(100, 32)
    inpPackStoreDoor.Position               = UDim2.fromOffset(370, 2)
    inpPackStoreDoor.BackgroundColor3       = C.field
    inpPackStoreDoor.BorderSizePixel        = 0
    inpPackStoreDoor.Font                   = Enum.Font.GothamBold
    inpPackStoreDoor.TextSize               = 15
    inpPackStoreDoor.TextColor3             = C.text
    inpPackStoreDoor.PlaceholderText        = "(Opsional)"
    inpPackStoreDoor.Text                   = AutoRotation.packStorageDoor or ""
    corner(inpPackStoreDoor, 4)
    stroke(inpPackStoreDoor, C.fieldRim, 1)

    inpPackStoreDoor.FocusLost:Connect(function()
        local txt = string.gsub(inpPackStoreDoor.Text or "", "%s+", "")
        AutoRotation.packStorageDoor = txt
        inpPackStoreDoor.Text = txt
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Row Input: Manual Pos Drop X & Y Pack
    local rowManualPackPos = Instance.new("Frame", bodyAutoBuyPack)
    rowManualPackPos.Size                   = UDim2.new(1, 0, 0, 36)
    rowManualPackPos.BackgroundTransparency = 1

    makeLabel(rowManualPackPos, "`oPos Drop Pack X:``", 18, UDim2.fromOffset(0, 8))

    inpPackStoreX = Instance.new("TextBox", rowManualPackPos)
    inpPackStoreX.Size                   = UDim2.fromOffset(100, 32)
    inpPackStoreX.Position               = UDim2.fromOffset(140, 2)
    inpPackStoreX.BackgroundColor3       = C.field
    inpPackStoreX.BorderSizePixel        = 0
    inpPackStoreX.Font                   = Enum.Font.GothamBold
    inpPackStoreX.TextSize               = 15
    inpPackStoreX.TextColor3             = C.text
    inpPackStoreX.PlaceholderText        = "Tile X"
    inpPackStoreX.Text                   = tostring(AutoRotation.packStorageDropX or "")
    corner(inpPackStoreX, 4)
    stroke(inpPackStoreX, C.fieldRim, 1)

    inpPackStoreX.FocusLost:Connect(function()
        local v = tonumber(inpPackStoreX.Text)
        if v and v > 0 then AutoRotation.packStorageDropX = math.floor(v) end
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(rowManualPackPos, "`oPos Drop Pack Y:``", 18, UDim2.fromOffset(260, 8))

    inpPackStoreY = Instance.new("TextBox", rowManualPackPos)
    inpPackStoreY.Size                   = UDim2.fromOffset(100, 32)
    inpPackStoreY.Position               = UDim2.fromOffset(390, 2)
    inpPackStoreY.BackgroundColor3       = C.field
    inpPackStoreY.BorderSizePixel        = 0
    inpPackStoreY.Font                   = Enum.Font.GothamBold
    inpPackStoreY.TextSize               = 15
    inpPackStoreY.TextColor3             = C.text
    inpPackStoreY.PlaceholderText        = "Tile Y"
    inpPackStoreY.Text                   = tostring(AutoRotation.packStorageDropY or "")
    corner(inpPackStoreY, 4)
    stroke(inpPackStoreY, C.fieldRim, 1)

    inpPackStoreY.FocusLost:Connect(function()
        local v = tonumber(inpPackStoreY.Text)
        if v and v > 0 then AutoRotation.packStorageDropY = math.floor(v) end
        if updateRotationUI then updateRotationUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(bodyAutoBuyPack, "`9 Selagi PnB, jika Gems >= (Harga x Jumlah), bot otomatis ke Storage Pack, beli pack, drop isinya, lalu lanjut PnB!``", 16, UDim2.new())

    -- Update UI Function
    updateRotationUI = function()
        if AutoRotation.active then
            if btnToggleRotation then btnToggleRotation.BackgroundColor3 = C.red end
            if btnToggleRotationLabel and btnToggleRotationLabel.set then
                btnToggleRotationLabel:set("STOP AUTO ROTATION")
            end
            if lblRotationStatus and lblRotationStatus.set then
                lblRotationStatus:set(string.format("`cStatus: %s``", AutoRotation.status or "Running..."))
            end
        else
            if btnToggleRotation then btnToggleRotation.BackgroundColor3 = C.green end
            if btnToggleRotationLabel and btnToggleRotationLabel.set then
                btnToggleRotationLabel:set("START AUTO ROTATION")
            end
            if lblRotationStatus and lblRotationStatus.set then
                lblRotationStatus:set(string.format("`oStatus: %s``", AutoRotation.status or "Standby"))
            end
        end

        if lblRotationStats and lblRotationStats.set then
            lblRotationStats:set(string.format("`9Rotasi: %d World | Panen: %d | Tanam: %d | PnB: %d | Profit: %d``",
                AutoRotation.totalWorldsRotated or 0,
                AutoRotation.totalHarvested or 0,
                AutoRotation.totalPlanted or 0,
                AutoRotation.totalPnB or 0,
                AutoRotation.totalProfitDropped or 0
            ))
        end

        if inpStoreWorld and not inpStoreWorld:IsFocused() then
            inpStoreWorld.Text = AutoRotation.storageWorld or ""
        end
        if inpStoreDoor and not inpStoreDoor:IsFocused() then
            inpStoreDoor.Text = AutoRotation.storageDoor or ""
        end
        if inpStoreX and not inpStoreX:IsFocused() then
            inpStoreX.Text = tostring(AutoRotation.storageDropX or "")
        end
        if inpStoreY and not inpStoreY:IsFocused() then
            inpStoreY.Text = tostring(AutoRotation.storageDropY or "")
        end
        if inpProfitDrop and not inpProfitDrop:IsFocused() then
            inpProfitDrop.Text = tostring(AutoRotation.seedProfitToDrop or 100)
        end
        if inpSeedReserve and not inpSeedReserve:IsFocused() then
            inpSeedReserve.Text = tostring(AutoRotation.minSeedReserve or 90)
        end

        if lblStoragePos and lblStoragePos.set then
            local text = (AutoRotation.storageWorld and AutoRotation.storageWorld ~= "" and AutoRotation.storageDropX and AutoRotation.storageDropY)
                and string.format("`2Storage: %s | Pos: (%d, %d)``", AutoRotation.storageWorld, AutoRotation.storageDropX, AutoRotation.storageDropY)
                or "`oStorage: (Belum diset - Berdiri di storage world & klik Set)``"
            lblStoragePos:set(text)
        end

        if btnToggleAutoBuyPack then
            btnToggleAutoBuyPack.BackgroundColor3 = AutoRotation.autoBuyPack and C.green or C.button
        end
        if btnToggleAutoBuyPackLabel and btnToggleAutoBuyPackLabel.set then
            btnToggleAutoBuyPackLabel:set(AutoRotation.autoBuyPack and "Auto Buy Pack: ON" or "Auto Buy Pack: OFF")
        end

        local pDef = AutoShop.getOfferByKey(AutoRotation.buyPackKey or "world_lock")
        local pName = pDef and pDef.name or "World Lock"
        local pPrice = AutoShop.getOfferPrice(AutoRotation.buyPackKey or "world_lock")
        if pPrice <= 0 then pPrice = pDef and pDef.price or 2200 end
        local pCnt = AutoRotation.buyPackCount or 1
        if btnPickPackLabel and btnPickPackLabel.set then
            btnPickPackLabel:set(string.format("%s (%d Gems)", pName, pPrice))
        end
        if lblSelectedPackInfo and lblSelectedPackInfo.set then
            lblSelectedPackInfo:set(string.format("`2Target: %dx %s = %d Gems (Klik nama pack untuk buka Tab Shop)``", pCnt, pName, pCnt * pPrice))
        end
        if inpBuyPackCount and not inpBuyPackCount:IsFocused() then
            inpBuyPackCount.Text = tostring(AutoRotation.buyPackCount or 1)
        end
        if inpPackStoreWorld and not inpPackStoreWorld:IsFocused() then
            inpPackStoreWorld.Text = AutoRotation.packStorageWorld or ""
        end
        if inpPackStoreDoor and not inpPackStoreDoor:IsFocused() then
            inpPackStoreDoor.Text = AutoRotation.packStorageDoor or ""
        end
        if inpPackStoreX and not inpPackStoreX:IsFocused() then
            inpPackStoreX.Text = tostring(AutoRotation.packStorageDropX or "")
        end
        if inpPackStoreY and not inpPackStoreY:IsFocused() then
            inpPackStoreY.Text = tostring(AutoRotation.packStorageDropY or "")
        end
        if lblPackStoragePos and lblPackStoragePos.set then
            local text = (AutoRotation.packStorageWorld and AutoRotation.packStorageWorld ~= "" and AutoRotation.packStorageDropX and AutoRotation.packStorageDropY)
                and string.format("`2Storage Pack: %s | Pos: (%d, %d)``", AutoRotation.packStorageWorld, AutoRotation.packStorageDropX, AutoRotation.packStorageDropY)
                or "`oStorage Pack: (Belum diset - Berdiri di storage world & klik Set)``"
            lblPackStoragePos:set(text)
        end
    end

    -- Live countdown ticker loop
    task.spawn(function()
        while true do
            task.wait(1.0)
            if #countdownLabels > 0 then
                for idx, cData in pairs(countdownLabels) do
                    local entry = cData.entry
                    local lbl = cData.lbl
                    if entry and lbl and lbl.set then
                        if AutoRotation.active and idx == AutoRotation.currentWorldIndex then
                            lbl:set("`a[ACTIVE]``")
                        elseif entry.countdownEndsAt and entry.countdownEndsAt > os.clock() then
                            local remSec = math.ceil(entry.countdownEndsAt - os.clock())
                            local mm = math.floor(remSec / 60)
                            local ss = remSec % 60
                            lbl:set(string.format("`e[Tumbuh: %02d:%02d]``", mm, ss))
                        elseif entry.ripeCount and entry.ripeCount > 0 then
                            lbl:set(string.format("`2[READY: %d Pohon]``", entry.ripeCount))
                        else
                            lbl:set("`o[Standby]``")
                        end
                    end
                end
            end
        end
    end)

    refreshRotationWorldList()
end

-- =========================================================================
-- TAB SHOP IMPLEMENTATION (STORE CATALOG, QUICK BUY & AUTO BUY)
-- =========================================================================
Setups.shop = function(page)
    local lblShopGems = nil
    local currentCategory = "all"
    local currentSearch = ""
    local catalogContainer = nil
    local btnToggleAutoShop, btnToggleAutoShopLabel
    local lblAutoShopStatus, lblAutoShopTarget

    -- Header / Gems Balance Display
    local secHeader = createSection(page, "Informasi Saldo Gems & Quick Actions", false, 1)
    local bodyHeader = secHeader.body

    local rowGems = Instance.new("Frame", bodyHeader)
    rowGems.Size                   = UDim2.new(1, 0, 0, 38)
    rowGems.BackgroundTransparency = 1

    lblShopGems = makeLabel(rowGems, string.format("`# Saldo Gems: %s Gems``", tostring(AutoShop.cachedGems or 0)), 20, UDim2.fromOffset(0, 8))

    local btnRefreshGems = makeButton(
        rowGems,
        "Refresh Gems",
        16,
        C.button,
        6,
        32,
        function()
            task.spawn(function()
                local g = AutoShop.getGems()
                if lblShopGems and lblShopGems.set then
                    lblShopGems:set(string.format("`# Saldo Gems: %s Gems``", tostring(g or 0)))
                end
                if Proxy and Proxy.notify then
                    Proxy.notify(string.format("`2[SHOP] Saldo Gems terupdate: %s Gems``", tostring(g or 0)))
                end
            end)
        end,
        140
    )
    btnRefreshGems.Position = UDim2.new(1, -145, 0, 2)

    -- Section 1: Auto Buy Store (Standalone / Background)
    local secAutoShop = createSection(page, "Auto Buy Pack Store (Standalone)", true, 2)
    local bodyAutoShop = secAutoShop.body

    local rowAutoShopControls = Instance.new("Frame", bodyAutoShop)
    rowAutoShopControls.Size                   = UDim2.new(1, 0, 0, 36)
    rowAutoShopControls.BackgroundTransparency = 1

    local btnTupleShop = { makeButton(
        rowAutoShopControls,
        AutoShop.active and "STOP AUTO BUY" or "START AUTO BUY",
        18,
        AutoShop.active and C.red or C.green,
        6,
        32,
        function()
            AutoShop.active = not AutoShop.active
            if AutoShop.active then
                AutoShop.boughtCount = 0
                AutoShop.status = "Running..."
                AutoShop.thread = task.spawn(function()
                    local packKey = AutoShop.targetPackKey or "world_lock"
                    local packPrice = AutoShop.getOfferPrice(packKey)
                    local targetAmt = math.max(1, tonumber(AutoShop.targetCount) or 1)

                    while AutoShop.active and AutoShop.boughtCount < targetAmt do
                        local curGems = AutoShop.getGems()
                        if curGems < packPrice then
                            AutoShop.status = string.format("Gems tidak cukup (%d / %d)! Berhenti...", curGems, packPrice)
                            if Proxy and Proxy.notify then
                                Proxy.notify("`4[AUTO BUY] Saldo Gems tidak mencukupi untuk membeli pack!``")
                            end
                            break
                        end

                        local ok, success, data = pcall(function()
                            return AutoShop.buyPack(packKey, 1)
                        end)
                        if ok and success and success > 0 then
                            AutoShop.boughtCount = AutoShop.boughtCount + 1
                            AutoShop.status = string.format("Terbeli: %d / %d pack", AutoShop.boughtCount, targetAmt)
                            if AutoShop.updateUI then AutoShop.updateUI() end

                            -- Auto Drop jika diaktifkan
                            if AutoShop.autoDrop and AutoShop.dropX and AutoShop.dropY then
                                task.wait(0.5)
                                if AutoShop.syncInventory then pcall(AutoShop.syncInventory) end
                                local offerDef = AutoShop.getOfferByKey(packKey)
                                local dTileX = AutoShop.dropX - 1
                                local dTileY = AutoShop.dropY - 1
                                local standX, standY = AutoRotation.getStorageStandPosition(dTileX, dTileY)
                                local curPx, curPy = getPlayerTilePos()
                                if curPx and curPy and curPx == dTileX and curPy == dTileY then
                                    walkOrPathfindTo(standX, standY, 100, 60)
                                    task.wait(0.2)
                                end
                                if offerDef and offerDef.items then
                                    for _, itm in ipairs(offerDef.items) do
                                        local st = (getRealtimeItemCount and getRealtimeItemCount(itm[1])) or 0
                                        if st > 0 then
                                            sendDropPacket(itm[1], st, dTileX + 0.5, dTileY + 0.5)
                                            local inv = getNativeInventory and getNativeInventory()
                                            if inv and inv.remove then pcall(inv.remove, inv, itm[1], st) end
                                            task.wait(0.25)
                                        end
                                    end
                                end
                            end
                        else
                            task.wait(1.0)
                        end
                        task.wait(0.4)
                    end
                    AutoShop.active = false
                    AutoShop.status = string.format("Selesai! Berhasil beli %d pack.", AutoShop.boughtCount)
                    if AutoShop.updateUI then AutoShop.updateUI() end
                end)
            else
                if AutoShop.thread then task.cancel(AutoShop.thread) AutoShop.thread = nil end
                AutoShop.status = "Dihentikan oleh pengguna."
            end
            if AutoShop.updateUI then AutoShop.updateUI() end
        end,
        180
    ) }
    btnToggleAutoShop = btnTupleShop[1]
    btnToggleAutoShopLabel = btnTupleShop[4]

    lblAutoShopStatus = makeLabel(rowAutoShopControls, "`oStatus: Standby``", 18, UDim2.fromOffset(195, 8))

    -- Row: Target Pack & Jumlah
    local rowTargetShop = Instance.new("Frame", bodyAutoShop)
    rowTargetShop.Size                   = UDim2.new(1, 0, 0, 36)
    rowTargetShop.BackgroundTransparency = 1

    local curASDef = AutoShop.getOfferByKey(AutoShop.targetPackKey or "world_lock")
    local curASName = curASDef and curASDef.name or "World Lock"
    local curASPrice = AutoShop.getOfferPrice(AutoShop.targetPackKey or "world_lock")
    if curASPrice <= 0 then curASPrice = curASDef and curASDef.price or 2200 end

    lblAutoShopTarget = makeLabel(rowTargetShop, string.format("`2Target: %s (%d Gems)``", curASName, curASPrice), 18, UDim2.fromOffset(0, 8))

    makeLabel(rowTargetShop, "`oJumlah:``", 18, UDim2.fromOffset(260, 8))

    local inpASTargetCount = Instance.new("TextBox", rowTargetShop)
    inpASTargetCount.Size                   = UDim2.fromOffset(80, 32)
    inpASTargetCount.Position               = UDim2.fromOffset(320, 2)
    inpASTargetCount.BackgroundColor3       = C.field
    inpASTargetCount.BorderSizePixel        = 0
    inpASTargetCount.Font                   = Enum.Font.GothamBold
    inpASTargetCount.TextSize               = 15
    inpASTargetCount.TextColor3             = C.text
    inpASTargetCount.PlaceholderText        = "Jml"
    inpASTargetCount.Text                   = tostring(AutoShop.targetCount or 1)
    corner(inpASTargetCount, 4)
    stroke(inpASTargetCount, C.fieldRim, 1)

    inpASTargetCount.FocusLost:Connect(function()
        local v = tonumber(inpASTargetCount.Text)
        if v and v > 0 then AutoShop.targetCount = math.floor(v) else AutoShop.targetCount = 1 end
        inpASTargetCount.Text = tostring(AutoShop.targetCount)
    end)

    -- Section 2: Katalog Store & Quick Buy
    local secCatalog = createSection(page, "Katalog Store & Quick Buy (Semua Pack Gems)", true, 3)
    local bodyCatalog = secCatalog.body

    -- Category filter bar
    local categories = {
        { id = "all", label = "ALL" },
        { id = "locks", label = "LOCKS" },
        { id = "building", label = "BUILDING" },
        { id = "activities", label = "ACTIVITIES" },
        { id = "selling", label = "SELLING" },
        { id = "upgrades", label = "UPGRADES" },
        { id = "clothes", label = "CLOTHES" },
        { id = "limiteds", label = "LIMITEDS" },
    }

    local rowCat = Instance.new("Frame", bodyCatalog)
    rowCat.Size                   = UDim2.new(1, 0, 0, 36)
    rowCat.BackgroundTransparency = 1

    local catButtons = {}
    local catWidth = math.floor((720 - 40 - (#categories - 1) * 6) / #categories)

    local function refreshCatalog()
        if not catalogContainer then return end
        for _, ch in ipairs(catalogContainer:GetChildren()) do
            if ch:IsA("GuiObject") and not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then
                ch:Destroy()
            end
        end

        local allOffers = AutoShop.getAllOffers()
        local matched = {}
        local q = string.lower(string.gsub(currentSearch or "", "%s+", ""))

        for _, off in ipairs(allOffers) do
            local passCat = (currentCategory == "all") or (off.tab == currentCategory)
            local passSearch = true
            if q ~= "" then
                local nLow = string.lower(off.name or "")
                local kLow = string.lower(off.key or "")
                passSearch = (string.find(nLow, q, 1, true) ~= nil) or (string.find(kLow, q, 1, true) ~= nil)
            end
            if passCat and passSearch then
                table.insert(matched, off)
            end
        end

        for _, off in ipairs(matched) do
            local card = Instance.new("Frame", catalogContainer)
            card.Size                   = UDim2.new(1, 0, 0, 72)
            card.BackgroundColor3       = Color3.fromRGB(22, 38, 48)
            card.BorderSizePixel        = 0
            corner(card, 6)
            stroke(card, C.fieldRim, 1)

            -- Item Name & Price
            local catTag = string.upper(off.tab or "STORE")
            makeLabel(card, string.format("`e%s`` `o[%s]`` - `#%d Gems``", off.name or off.key, catTag, off.price or 0), 17, UDim2.fromOffset(12, 6))

            -- Blurb / Content
            local itemSummary = {}
            if off.items and #off.items > 0 then
                for _, it in ipairs(off.items) do
                    local itName = (ItemDB and ItemDB[it[1]] and ItemDB[it[1]].name) or ("Item #" .. tostring(it[1]))
                    table.insert(itemSummary, string.format("%dx %s", it[2], itName))
                end
            end
            local blurbText = off.blurb or (table.concat(itemSummary, ", "))
            if #itemSummary > 0 and off.blurb then
                blurbText = off.blurb .. " (" .. table.concat(itemSummary, ", ") .. ")"
            end
            makeLabel(card, string.format("`9%s``", blurbText:sub(1, 65)), 14, UDim2.fromOffset(12, 28))

            -- Action: Tombol Quick Buy 1x
            local btnBuy1 = makeButton(
                card,
                "Beli 1x",
                15,
                C.green,
                4,
                28,
                function()
                    task.spawn(function()
                        local curGems = AutoShop.getGems()
                        if curGems < (off.price or 0) then
                            if Proxy and Proxy.notify then
                                Proxy.notify("`4[SHOP] Gems tidak cukup untuk beli " .. tostring(off.name) .. "!``")
                            end
                            return
                        end
                        local bought, items = AutoShop.buyPack(off.key, 1)
                        if bought > 0 then
                            if Proxy and Proxy.notify then
                                Proxy.notify(string.format("`2[SHOP] Berhasil membeli 1x %s!``", tostring(off.name)))
                            end
                            if AutoShop.updateUI then AutoShop.updateUI() end
                        else
                            if Proxy and Proxy.notify then
                                Proxy.notify("`4[SHOP] Gagal membeli " .. tostring(off.name) .. "! Coba lagi.``")
                            end
                        end
                    end)
                end,
                78
            )
            btnBuy1.Position = UDim2.new(1, -250, 0, 6)

            -- Action: Set sbg Target Auto Buy
            local btnSetTarget = makeButton(
                card,
                "Pilih Target",
                14,
                C.button,
                4,
                28,
                function()
                    AutoShop.targetPackKey = off.key
                    AutoRotation.buyPackKey = off.key
                    if AutoShop.updateUI then AutoShop.updateUI() end
                    if updateRotationUI then updateRotationUI() end
                    if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                    if Proxy and Proxy.notify then
                        Proxy.notify(string.format("`2[SHOP] Target pack diset ke: %s (%d Gems)``", off.name, off.price))
                    end
                end,
                90
            )
            btnSetTarget.Position = UDim2.new(1, -165, 0, 6)

            -- Action: Custom Beli (Nx)
            local inpCustomCount = Instance.new("TextBox", card)
            inpCustomCount.Size                   = UDim2.fromOffset(36, 26)
            inpCustomCount.Position               = UDim2.new(1, -68, 0, 7)
            inpCustomCount.BackgroundColor3       = C.field
            inpCustomCount.BorderSizePixel        = 0
            inpCustomCount.Font                   = Enum.Font.GothamBold
            inpCustomCount.TextSize               = 14
            inpCustomCount.TextColor3             = C.text
            inpCustomCount.Text                   = "5"
            corner(inpCustomCount, 4)

            local btnBuyN = makeButton(
                card,
                ">",
                15,
                C.cyan,
                4,
                26,
                function()
                    local cnt = tonumber(inpCustomCount.Text) or 1
                    task.spawn(function()
                        local totalCost = (off.price or 0) * cnt
                        local curGems = AutoShop.getGems()
                        if curGems < totalCost then
                            if Proxy and Proxy.notify then
                                Proxy.notify(string.format("`4[SHOP] Gems tidak cukup (%d / %d)!``", curGems, totalCost))
                            end
                            return
                        end
                        local bought = AutoShop.buyPack(off.key, cnt)
                        if Proxy and Proxy.notify then
                            Proxy.notify(string.format("`2[SHOP] Berhasil membeli %dx %s!``", bought, tostring(off.name)))
                        end
                        if AutoShop.updateUI then AutoShop.updateUI() end
                    end)
                end,
                26
            )
            btnBuyN.Position = UDim2.new(1, -30, 0, 7)
        end
    end

    for i, cat in ipairs(categories) do
        local btnCatTuple = { makeButton(
            rowCat,
            cat.label,
            14,
            (cat.id == currentCategory) and C.green or C.button,
            4,
            30,
            function()
                currentCategory = cat.id
                for cId, b in pairs(catButtons) do
                    b.BackgroundColor3 = (cId == currentCategory) and C.green or C.button
                end
                refreshCatalog()
            end,
            catWidth
        ) }
        btnCatTuple[1].Position = UDim2.fromOffset((i - 1) * (catWidth + 6), 2)
        catButtons[cat.id] = btnCatTuple[1]
    end

    -- Search Box
    local rowSearch = Instance.new("Frame", bodyCatalog)
    rowSearch.Size                   = UDim2.new(1, 0, 0, 36)
    rowSearch.BackgroundTransparency = 1

    local inpSearchPack = Instance.new("TextBox", rowSearch)
    inpSearchPack.Size                   = UDim2.new(1, 0, 0, 32)
    inpSearchPack.Position               = UDim2.fromOffset(0, 2)
    inpSearchPack.BackgroundColor3       = C.field
    inpSearchPack.BorderSizePixel        = 0
    inpSearchPack.Font                   = Enum.Font.GothamBold
    inpSearchPack.TextSize               = 15
    inpSearchPack.TextColor3             = C.text
    inpSearchPack.PlaceholderText        = "Cari nama pack/item (cth: lock, seed, bag, spray)..."
    inpSearchPack.Text                   = ""
    corner(inpSearchPack, 4)
    stroke(inpSearchPack, C.fieldRim, 1)

    inpSearchPack:GetPropertyChangedSignal("Text"):Connect(function()
        currentSearch = inpSearchPack.Text
        refreshCatalog()
    end)

    -- Container cards
    catalogContainer = Instance.new("Frame", bodyCatalog)
    catalogContainer.Size                   = UDim2.new(1, 0, 0, 0)
    catalogContainer.AutomaticSize          = Enum.AutomaticSize.Y
    catalogContainer.BackgroundTransparency = 1

    local catLayout = Instance.new("UIListLayout", catalogContainer)
    catLayout.SortOrder = Enum.SortOrder.LayoutOrder
    catLayout.Padding   = UDim.new(0, 6)

    AutoShop.updateUI = function()
        if lblShopGems and lblShopGems.set then
            lblShopGems:set(string.format("`# Saldo Gems: %s Gems``", tostring(AutoShop.cachedGems or 0)))
        end
        if btnToggleAutoShop then
            btnToggleAutoShop.BackgroundColor3 = AutoShop.active and C.red or C.green
        end
        if btnToggleAutoShopLabel and btnToggleAutoShopLabel.set then
            btnToggleAutoShopLabel:set(AutoShop.active and "STOP AUTO BUY" or "START AUTO BUY")
        end
        if lblAutoShopStatus and lblAutoShopStatus.set then
            lblAutoShopStatus:set(string.format("`oStatus: %s``", AutoShop.status or "Standby"))
        end
        local asDef = AutoShop.getOfferByKey(AutoShop.targetPackKey or "world_lock")
        local asPrice = AutoShop.getOfferPrice(AutoShop.targetPackKey or "world_lock")
        if asPrice <= 0 then asPrice = asDef and asDef.price or 2200 end
        if lblAutoShopTarget and lblAutoShopTarget.set and asDef then
            lblAutoShopTarget:set(string.format("`2Target: %s (%d Gems)``", asDef.name or asDef.key, asPrice))
        end
        if refreshCatalog then pcall(refreshCatalog) end
    end

    refreshCatalog()
end

Setups.event = function(page)
    -- Section 1: Event Controller & Status
    local secCtrl = createSection(page, "Event Controller & Status", true, 1)
    local bodyCtrl = secCtrl.body

    lblEventStatus = makeLabel(bodyCtrl, "`oStatus: Standby | Siapkan bahan atau atur storage world``", 19, UDim2.new())
    lblEventStats  = makeLabel(bodyCtrl, "`9[Stats] Burned: 0 Item | Total Trips: 0 | Target: Dirt (ID 2)``", 18, UDim2.new())

    -- PARAGRAPH DATA GAME (LWKEY'S INFERNO EVENT)
    local pnlInferno = Instance.new("Frame", bodyCtrl)
    pnlInferno.Size                   = UDim2.new(1, 0, 0, 116)
    pnlInferno.BackgroundColor3       = Color3.fromRGB(24, 20, 28)
    pnlInferno.BorderSizePixel        = 0
    corner(pnlInferno, 6)
    stroke(pnlInferno, Color3.fromRGB(180, 80, 30), 1)

    local infernoLayout = Instance.new("UIListLayout", pnlInferno)
    infernoLayout.SortOrder = Enum.SortOrder.LayoutOrder
    infernoLayout.Padding   = UDim.new(0, 4)

    local infernoPad = Instance.new("UIPadding", pnlInferno)
    infernoPad.PaddingTop    = UDim.new(0, 6)
    infernoPad.PaddingBottom = UDim.new(0, 6)
    infernoPad.PaddingLeft   = UDim.new(0, 10)
    infernoPad.PaddingRight  = UDim.new(0, 10)

    makeLabel(pnlInferno, "`4🔥 EVENT: LWKEY'S INFERNO (World: LOWKEYMOUNTAIN 1-10)``", 18, UDim2.new())
    lblEventRarityProg = makeLabel(pnlInferno, "`oYour Rarity: `21,267`` / `95,000,000`` `o(Sisa: `w4,998,733`` Rarity)``", 17, UDim2.new())
    lblEventMilestones = makeLabel(pnlInferno, "`9[Rewards Milestone]`` `o📦 625k (2 IOTM) | 📢 1.25M (5 Mega) | 🌐 2.5M (10 Spray) | 🪽 5M (Phoenix Wings)``", 16, UDim2.new())
    lblEventNpcCoord   = makeLabel(pnlInferno, "`oPosisi NPC Lowkey: `wAuto-Detect / Standby``", 16, UDim2.new())

    local ctrlBtnRow = Instance.new("Frame", bodyCtrl)
    ctrlBtnRow.Size                   = UDim2.new(1, 0, 0, 38)
    ctrlBtnRow.BackgroundTransparency = 1

    btnToggleEventFrame, _, btnToggleEvent, btnToggleEventLabel = makeButton(
        ctrlBtnRow,
        AutoEvent.active and "STOP AUTO EVENT BURN" or "START AUTO EVENT BURN",
        19,
        AutoEvent.active and C.red or C.green,
        8,
        36,
        function()
            if AutoEvent.active then
                stopAutoEvent()
            else
                startAutoEvent()
            end
        end,
        280
    )
    btnToggleEventFrame.Position = UDim2.fromOffset(0, 0)

    -- Section 2: Target Bahan untuk di-Burn (Item Selector & Preset)
    local secItem = createSection(page, "Target Bahan Burn (Pilih Item / Dropdown Tas)", true, 2)
    local bodyItem = secItem.body

    makeLabel(bodyItem, "`oInput Item ID Bahan Target yang Akan di-Burn:``", 18, UDim2.new())

    local itemRow = Instance.new("Frame", bodyItem)
    itemRow.Size                   = UDim2.new(1, 0, 0, 34)
    itemRow.BackgroundTransparency = 1

    local inpItemId = Instance.new("TextBox", itemRow)
    inpItemId.Size                   = UDim2.fromOffset(130, 32)
    inpItemId.Position               = UDim2.fromOffset(0, 0)
    inpItemId.BackgroundColor3       = C.field
    inpItemId.BorderSizePixel        = 0
    inpItemId.Font                   = Enum.Font.GothamBold
    inpItemId.TextSize               = 15
    inpItemId.TextColor3             = C.text
    inpItemId.PlaceholderColor3      = C.placeholder
    inpItemId.PlaceholderText        = "Item ID (cth: 2)"
    inpItemId.Text                   = tostring(AutoEvent.burnItemId or 2)
    corner(inpItemId, 4)
    stroke(inpItemId, C.fieldRim, 1)

    local lblItemChosen = makeLabel(itemRow, string.format("`2%s (ID %d)``", AutoEvent.burnItemName or "Dirt", AutoEvent.burnItemId or 2), 18, UDim2.fromOffset(140, 6))

    inpItemId:GetPropertyChangedSignal("Text"):Connect(function()
        local nid = tonumber(inpItemId.Text)
        if nid and nid > 0 then
            AutoEvent.burnItemId = nid
            AutoEvent.burnItemName = getDFItemName(nid)
            if lblItemChosen and lblItemChosen.set then
                lblItemChosen:set(string.format("`2%s (ID %d)``", AutoEvent.burnItemName, AutoEvent.burnItemId))
            end
        end
    end)

    inpItemId.FocusLost:Connect(function()
        local nid = tonumber(inpItemId.Text)
        if nid and nid > 0 then
            AutoEvent.burnItemId = nid
            AutoEvent.burnItemName = getDFItemName(nid)
            if updateEventUI then updateEventUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end)

    -- Quick Preset Buttons: Dirt (2), Rock (10), Wood (12), Wooden Platform (102), Lava (4)
    makeLabel(bodyItem, "`oPreset Pilihan Cepat:``", 18, UDim2.new())
    local presetRow = Instance.new("Frame", bodyItem)
    presetRow.Size                   = UDim2.new(1, 0, 0, 32)
    presetRow.BackgroundTransparency = 1

    local presets = {
        { name = "Dirt", id = 2 },
        { name = "Rock", id = 10 },
        { name = "Wood", id = 12 },
        { name = "Platform", id = 102 },
        { name = "Lava", id = 4 },
    }
    for idx, pr in ipairs(presets) do
        local pBtn = makeButton(
            presetRow,
            pr.name,
            16,
            (AutoEvent.burnItemId == pr.id) and C.green or C.button,
            4,
            28,
            function()
                AutoEvent.burnItemId = pr.id
                AutoEvent.burnItemName = pr.name
                inpItemId.Text = tostring(pr.id)
                if updateEventUI then updateEventUI() end
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            end,
            96
        )
        pBtn.Position = UDim2.fromOffset((idx - 1) * 102, 0)
    end

    -- Dropdown pilih langsung dari item tas
    local dropBtnRow = Instance.new("Frame", bodyItem)
    dropBtnRow.Size                   = UDim2.new(1, 0, 0, 32)
    dropBtnRow.BackgroundTransparency = 1

    local itemDropContainer = Instance.new("Frame", bodyItem)
    itemDropContainer.Size                   = UDim2.new(1, 0, 0, 130)
    itemDropContainer.BackgroundColor3       = C.dark
    itemDropContainer.BackgroundTransparency = 0.2
    itemDropContainer.BorderSizePixel        = 0
    itemDropContainer.Visible                = false
    corner(itemDropContainer, 6)
    stroke(itemDropContainer, C.fieldRim, 1)

    local itemDropScroll = Instance.new("ScrollingFrame", itemDropContainer)
    itemDropScroll.Size                   = UDim2.new(1, -12, 1, -12)
    itemDropScroll.Position               = UDim2.fromOffset(6, 6)
    itemDropScroll.BackgroundTransparency = 1
    itemDropScroll.BorderSizePixel        = 0
    itemDropScroll.ScrollBarThickness     = 4
    itemDropScroll.ScrollBarImageColor3   = C.rim
    itemDropScroll.AutomaticCanvasSize    = Enum.AutomaticSize.Y
    itemDropScroll.CanvasSize             = UDim2.new()

    local dropLayout = Instance.new("UIListLayout", itemDropScroll)
    dropLayout.SortOrder = Enum.SortOrder.LayoutOrder
    dropLayout.Padding   = UDim.new(0, 4)

    local function refreshItemDrop()
        for _, ch in ipairs(itemDropScroll:GetChildren()) do
            if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                ch:Destroy()
            end
        end
        local inv = fetchInventoryItems and fetchInventoryItems() or {}
        local countFound = 0
        for _, it in ipairs(inv) do
            if it.count and it.count > 0 then
                countFound = countFound + 1
                makeButton(
                    itemDropScroll,
                    string.format("%s (ID %d) x%d", it.name or "Item", it.id, it.count),
                    18,
                    (AutoEvent.burnItemId == it.id) and C.green or C.button,
                    6,
                    28,
                    function()
                        AutoEvent.burnItemId = it.id
                        AutoEvent.burnItemName = it.name or getDFItemName(it.id)
                        inpItemId.Text = tostring(it.id)
                        itemDropContainer.Visible = false
                        if updateEventUI then updateEventUI() end
                        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                    end,
                    510
                )
            end
        end
        if countFound == 0 then
            makeLabel(itemDropScroll, "`oTidak ada item di tas saat ini``", 17, UDim2.new())
        end
    end

    local btnOpenDrop = makeButton(
        dropBtnRow,
        "Pilih Item dari Tas (Dropdown)",
        17,
        C.button,
        6,
        30,
        function()
            itemDropContainer.Visible = not itemDropContainer.Visible
            if itemDropContainer.Visible then refreshItemDrop() end
        end,
        250
    )
    btnOpenDrop.Position = UDim2.fromOffset(0, 0)

    -- Target Batch Count
    makeLabel(bodyItem, "`oJumlah Target Ambil Bahan per Trip (Default: 200 / Full Stack):``", 18, UDim2.new())
    local inpTargetAmt = Instance.new("TextBox", bodyItem)
    inpTargetAmt.Size                   = UDim2.new(1, 0, 0, 32)
    inpTargetAmt.BackgroundColor3       = C.field
    inpTargetAmt.BorderSizePixel        = 0
    inpTargetAmt.Font                   = Enum.Font.GothamBold
    inpTargetAmt.TextSize               = 15
    inpTargetAmt.TextColor3             = C.text
    inpTargetAmt.PlaceholderColor3      = C.placeholder
    inpTargetAmt.PlaceholderText        = "Target ambil bahan per trip (cth: 200)"
    inpTargetAmt.Text                   = tostring(AutoEvent.burnTargetCount or 200)
    corner(inpTargetAmt, 4)
    stroke(inpTargetAmt, C.fieldRim, 1)

    inpTargetAmt:GetPropertyChangedSignal("Text"):Connect(function()
        local n = tonumber(inpTargetAmt.Text)
        if n and n > 0 then
            AutoEvent.burnTargetCount = n
        end
    end)

    inpTargetAmt.FocusLost:Connect(function()
        local n = tonumber(inpTargetAmt.Text)
        if n and n > 0 then
            AutoEvent.burnTargetCount = n
            if updateEventUI then updateEventUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
        end
    end)

    -- Section 3: Storage World & Restock Settings
    local secStorage = createSection(page, "Pengaturan Storage World (Restock Saat Tas Habis)", true, 3)
    local bodyStorage = secStorage.body

    makeLabel(bodyStorage, "`oNama World Storage Bahan:``", 18, UDim2.new())
    local inpEvStorageWorld = Instance.new("TextBox", bodyStorage)
    inpEvStorageWorld.Size                   = UDim2.new(1, 0, 0, 32)
    inpEvStorageWorld.BackgroundColor3       = C.field
    inpEvStorageWorld.BorderSizePixel        = 0
    inpEvStorageWorld.Font                   = Enum.Font.GothamBold
    inpEvStorageWorld.TextSize               = 15
    inpEvStorageWorld.TextColor3             = C.text
    inpEvStorageWorld.PlaceholderColor3      = C.placeholder
    inpEvStorageWorld.PlaceholderText        = "Nama Storage World (cth: VIVOBOOK)"
    inpEvStorageWorld.Text                   = AutoEvent.storageWorld or ""
    corner(inpEvStorageWorld, 4)
    stroke(inpEvStorageWorld, C.fieldRim, 1)

    inpEvStorageWorld:GetPropertyChangedSignal("Text"):Connect(function()
        AutoEvent.storageWorld = string.upper((inpEvStorageWorld.Text or ""):gsub("%s+", ""))
    end)

    inpEvStorageWorld.FocusLost:Connect(function()
        AutoEvent.storageWorld = string.upper((inpEvStorageWorld.Text or ""):gsub("%s+", ""))
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    makeLabel(bodyStorage, "`oDoor ID Storage World (Opsional):``", 18, UDim2.new())
    local inpEvStorageDoor = Instance.new("TextBox", bodyStorage)
    inpEvStorageDoor.Size                   = UDim2.new(1, 0, 0, 32)
    inpEvStorageDoor.BackgroundColor3       = C.field
    inpEvStorageDoor.BorderSizePixel        = 0
    inpEvStorageDoor.Font                   = Enum.Font.GothamBold
    inpEvStorageDoor.TextSize               = 15
    inpEvStorageDoor.TextColor3             = C.text
    inpEvStorageDoor.PlaceholderColor3      = C.placeholder
    inpEvStorageDoor.PlaceholderText        = "Door ID (Kosongkan jika pintu utama)"
    inpEvStorageDoor.Text                   = AutoEvent.storageDoor or ""
    corner(inpEvStorageDoor, 4)
    stroke(inpEvStorageDoor, C.fieldRim, 1)

    inpEvStorageDoor:GetPropertyChangedSignal("Text"):Connect(function()
        AutoEvent.storageDoor = (inpEvStorageDoor.Text or ""):gsub("%s+", "")
    end)

    inpEvStorageDoor.FocusLost:Connect(function()
        AutoEvent.storageDoor = (inpEvStorageDoor.Text or ""):gsub("%s+", "")
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end)

    -- Tombol Simpan Pengaturan & Simpan Posisi NPC
    local storageBtnRow = Instance.new("Frame", bodyStorage)
    storageBtnRow.Size                   = UDim2.new(1, 0, 0, 36)
    storageBtnRow.BackgroundTransparency = 1

    local btnSaveEventCfg = makeButton(
        storageBtnRow,
        "💾 SIMPAN PENGATURAN EVENT",
        17,
        C.green,
        6,
        32,
        function()
            if inpEvStorageWorld and inpEvStorageWorld.Text ~= "" then
                AutoEvent.storageWorld = string.upper((inpEvStorageWorld.Text):gsub("%s+", ""))
            end
            if inpEvStorageDoor then
                AutoEvent.storageDoor = (inpEvStorageDoor.Text or ""):gsub("%s+", "")
            end
            if inpTargetAmt and tonumber(inpTargetAmt.Text) then
                AutoEvent.burnTargetCount = tonumber(inpTargetAmt.Text)
            end
            if inpItemId and tonumber(inpItemId.Text) then
                AutoEvent.burnItemId = tonumber(inpItemId.Text)
                AutoEvent.burnItemName = getDFItemName(AutoEvent.burnItemId)
            end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            if updateEventUI then updateEventUI() end
            if Proxy and Proxy.notify then
                Proxy.notify(string.format("`2[Config] Pengaturan Storage (%s) & Event tersimpan permanen!``", AutoEvent.storageWorld or "World"))
            end
        end,
        250
    )
    btnSaveEventCfg.Position = UDim2.fromOffset(0, 0)

    local btnSetNpcHere = makeButton(
        storageBtnRow,
        "📍 SIMPAN POSISI NPC SAYA",
        16,
        C.button,
        6,
        32,
        function()
            local px, py = getPlayerTilePos()
            if px and py then
                AutoEvent.npcPos = { x = px, y = py }
                if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
                if updateEventUI then updateEventUI() end
                if Proxy and Proxy.notify then
                    Proxy.notify(string.format("`2[NPC] Posisi NPC Lowkey berhasil disimpan di tile (%d, %d)!``", px, py))
                end
            else
                if Proxy and Proxy.notify then
                    Proxy.notify("`4[NPC] Gagal mendeteksi posisi player! Pastikan berada di dalam world.``")
                end
            end
        end,
        220
    )
    btnSetNpcHere.Position = UDim2.fromOffset(258, 0)

    -- Simpan referensi input ke AutoEvent
    AutoEvent.inpStorageWorld = inpEvStorageWorld
    AutoEvent.inpStorageDoor  = inpEvStorageDoor
    AutoEvent.inpTargetAmt    = inpTargetAmt
    AutoEvent.inpItemId       = inpItemId

    -- Helper format angka ribuan
    local function fmtCommas(val)
        local str = tostring(math.floor(tonumber(val) or 0))
        local left, num, right = string.match(str, "^([^%d]*%d)(%d*)(.-)$")
        if not left then return str end
        return left .. (num:reverse():gsub("(%d%d%d)", "%1,"):reverse()) .. right
    end

    -- UI Updater
    updateEventUI = function()
        if btnToggleEvent then
            btnToggleEvent.BackgroundColor3 = AutoEvent.active and C.red or C.green
        end
        if btnToggleEventLabel and btnToggleEventLabel.set then
            btnToggleEventLabel:set(AutoEvent.active and "STOP AUTO EVENT BURN" or "START AUTO EVENT BURN")
        end
        if lblEventStatus and lblEventStatus.set then
            lblEventStatus:set(string.format("`oStatus: %s``", AutoEvent.status or "Standby"))
        end
        if lblEventStats and lblEventStats.set then
            lblEventStats:set(string.format("`9[Stats Sesi] Burned: %d Item | Total Trips: %d | Target: %s (ID %d)``",
                AutoEvent.totalBurned or 0,
                AutoEvent.totalTrips or 0,
                AutoEvent.burnItemName or "Dirt",
                AutoEvent.burnItemId or 2
            ))
        end
        if lblItemChosen and lblItemChosen.set then
            lblItemChosen:set(string.format("`2%s (ID %d)``", AutoEvent.burnItemName or "Dirt", AutoEvent.burnItemId or 2))
        end

        -- Paragraph Game Event Data Update
        if lblEventRarityProg and lblEventRarityProg.set then
            local curRarity = AutoEvent.gameRarity or 1267
            local tgtRarity = AutoEvent.gameTargetRarity or 5000000
            local leftRarity = math.max(0, tgtRarity - curRarity)
            lblEventRarityProg:set(string.format("`oYour Rarity: `2%s`` / `9%s`` `o(Sisa: `w%s`` Rarity)``",
                fmtCommas(curRarity),
                fmtCommas(tgtRarity),
                fmtCommas(leftRarity)
            ))
        end
        if lblEventNpcCoord and lblEventNpcCoord.set then
            if AutoEvent.npcPos and AutoEvent.npcPos.x and AutoEvent.npcPos.y then
                lblEventNpcCoord:set(string.format("`oPosisi NPC Lowkey: `2Tersimpan di (%d, %d)``", AutoEvent.npcPos.x, AutoEvent.npcPos.y))
            else
                lblEventNpcCoord:set("`oPosisi NPC Lowkey: `wAuto-Detect dari World Data``")
            end
        end

        -- Sinkronkan Textbox jika tidak sedang diedit player
        if AutoEvent.inpStorageWorld and not AutoEvent.inpStorageWorld:IsFocused() then
            AutoEvent.inpStorageWorld.Text = AutoEvent.storageWorld or ""
        end
        if AutoEvent.inpStorageDoor and not AutoEvent.inpStorageDoor:IsFocused() then
            AutoEvent.inpStorageDoor.Text = AutoEvent.storageDoor or ""
        end
        if AutoEvent.inpTargetAmt and not AutoEvent.inpTargetAmt:IsFocused() then
            AutoEvent.inpTargetAmt.Text = tostring(AutoEvent.burnTargetCount or 200)
        end
        if AutoEvent.inpItemId and not AutoEvent.inpItemId:IsFocused() then
            AutoEvent.inpItemId.Text = tostring(AutoEvent.burnItemId or 2)
        end
    end
end

