Setups.worldClear = function(body)
    local clearBtnRow = Instance.new("Frame", body)
    clearBtnRow.Size               = UDim2.new(1, 0, 0, 40)
    clearBtnRow.BackgroundTransparency = 1

    local btnToggleClearFrame, btnToggleClear, btnToggleClearLabel
    btnToggleClearFrame, _, btnToggleClear, btnToggleClearLabel = makeButton(
        clearBtnRow,
        "START CLEAR WORLD",
        22,
        C.green,
        14,
        38,
        function()
            if ClearWorld.active then
                stopClearWorld()
            else
                startClearWorld()
            end
        end,
        260
    )
    btnToggleClearFrame.Position = UDim2.fromOffset(0, 0)

    local cbClearBG = checkbox(body, "`oHancurkan Background (BG) Sekaligus``", UDim2.new(), function(val)
        ClearWorld.clearBG = val
        if updateClearWorldUI then updateClearWorldUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, ClearWorld.clearBG ~= false)

    local cbClearSweep = checkbox(body, "`oAuto Sweep Drops (Sapu & Sedot Bersih Droppan ke Tas)``", UDim2.new(), function(val)
        ClearWorld.autoSweep = val
        if updateClearWorldUI then updateClearWorldUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, ClearWorld.autoSweep ~= false)

    local cbClearTrash = checkbox(body, "`oAuto Trash Hasil Sapuan (Khusus Dirt/Cave/Rock/Lava)``", UDim2.new(), function(val)
        ClearWorld.autoTrash = val
        if updateClearWorldUI then updateClearWorldUI() end
        if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
    end, ClearWorld.autoTrash == true)

    lblClearStatus = makeLabel(body, "`oStatus: Idle | 6-Block Batch (3x2)``", 19, UDim2.new())
    lblClearStats = makeLabel(body, "`s● Hancur: 0 tile | Aman: Bedrock, Main Door, Locks (Skip All)``", 18, UDim2.new())

    updateClearWorldUI = function()
        if ClearWorld.active then
            if btnToggleClear then btnToggleClear.BackgroundColor3 = C.red end
            if btnToggleClearLabel and btnToggleClearLabel.set then btnToggleClearLabel:set("STOP CLEAR WORLD") end
            if lblClearStatus and lblClearStatus.set then lblClearStatus:set("`cStatus: Running Clear World (6-Block)...``") end
        else
            if btnToggleClear then btnToggleClear.BackgroundColor3 = C.green end
            if btnToggleClearLabel and btnToggleClearLabel.set then btnToggleClearLabel:set("START CLEAR WORLD") end
            if lblClearStatus and lblClearStatus.set then lblClearStatus:set("`oStatus: Idle | 6-Block Batch (3x2)``") end
        end

        if cbClearBG and cbClearBG.set then cbClearBG.set(ClearWorld.clearBG ~= false) end
        if cbClearSweep and cbClearSweep.set then cbClearSweep.set(ClearWorld.autoSweep ~= false) end
        if cbClearTrash and cbClearTrash.set then cbClearTrash.set(ClearWorld.autoTrash == true) end
        if lblClearStats and lblClearStats.set then
            lblClearStats:set(string.format("`s● Hancur: %d tile | Aman: Bedrock, Main Door, Locks (Skip All)``", ClearWorld.totalCleared or 0))
        end
    end
end

