local function getLocalNativeName()
    -- Nama asli in-game TANPA /nick (GameName -> nama Roblox). Shared.Roles sudah tidak ada,
    -- jadi versi lama selalu jatuh ke "SYSHUB". Tampilan /nick diterapkan terpisah lewat
    -- Proxy.applyNick supaya logs lama ikut balik ke nama asli saat /unnick.
    local lp = Players.LocalPlayer
    if not lp then return "Player" end
    local gn = lp:GetAttribute("GameName")
    if type(gn) == "string" and gn ~= "" then
        return (gn:gsub("`%w", ""):gsub("``", ""):gsub("^@", ""))
    end
    return lp.Name
end

-- /nick (Streamer Mode): ganti nama asli kita dengan nick di chat sistem, bubble & logs
do
    local function isWordByte(b)
        return b ~= nil and ((b >= 48 and b <= 57) or (b >= 65 and b <= 90) or (b >= 97 and b <= 122) or b == 95)
    end
    local namesCache, namesAt = nil, 0

    local nickCache, nickAt = nil, -1
    function Proxy.getNick()
        -- dipanggil dari hook BitmapText.set (sering), jadi di-cache sebentar
        local now = os.clock()
        if (now - nickAt) < 0.3 then return nickCache end
        nickAt = now
        nickCache = nil
        local lp = Players.LocalPlayer
        local n = lp and lp:GetAttribute("Nick")
        if type(n) == "string" then
            n = n:gsub("^%s*(.-)%s*$", "%1")
            if n ~= "" then nickCache = n end
        end
        return nickCache
    end
    function Proxy.resetNickCache()
        nickAt = -1
        namesAt = 0
    end

    function Proxy.getLocalRealNames()
        local now = os.clock()
        if namesCache and (now - namesAt) < 2 then return namesCache end
        local lp = Players.LocalPlayer
        local out, seen = {}, {}
        local function add(s)
            if type(s) ~= "string" then return end
            s = s:gsub("`%w", ""):gsub("``", ""):gsub("^@", "")
            if #s >= 3 and not seen[s:lower()] then
                seen[s:lower()] = true
                table.insert(out, s)
            end
        end
        if lp then
            -- Nama yang dipakai game: Nick -> GameName -> Name (DisplayName tidak dipakai game,
            -- dan sengaja tidak diganti supaya kata umum di chat tidak ikut kena).
            add(lp:GetAttribute("GameName"))
            add(lp.Name)
        end
        table.sort(out, function(a, b) return #a > #b end)
        namesCache, namesAt = out, now
        return out
    end

    -- Ganti nama asli -> nick (case-insensitive, utuh per kata, aman untuk kode warna `w)
    local function replaceName(text, lowText, real, nick)
        local lowReal = real:lower()
        if nick:lower():find(lowReal, 1, true) or not lowText:find(lowReal, 1, true) then
            return text, lowText
        end
        local parts, pos, changed = {}, 1, false
        while true do
            local s, e = lowText:find(lowReal, pos, true)
            if not s then break end
            local b1 = s > 1 and lowText:byte(s - 1) or nil
            local b2 = s > 2 and lowText:byte(s - 2) or nil
            local okBefore = (not isWordByte(b1)) or b2 == 96 -- 96 = '`' (kode warna, mis. `wNama)
            local okAfter = not isWordByte(lowText:byte(e + 1))
            if okBefore and okAfter then
                parts[#parts + 1] = text:sub(pos, s - 1)
                parts[#parts + 1] = nick
                changed = true
            else
                parts[#parts + 1] = text:sub(pos, e)
            end
            pos = e + 1
        end
        if not changed then return text, lowText end
        parts[#parts + 1] = text:sub(pos)
        text = table.concat(parts)
        return text, text:lower()
    end

    -- Nick pengguna SysHub lain (diisi sync profil /vsync): [userId] = { nick = "...", reals = {...} }
    Proxy.remoteNicks = Proxy.remoteNicks or {}

    function Proxy.applyNick(text)
        if type(text) ~= "string" or text == "" then return text end
        local lowText = nil
        local nick = Proxy.getNick()
        if nick then
            lowText = text:lower()
            for _, real in ipairs(Proxy.getLocalRealNames()) do
                text, lowText = replaceName(text, lowText, real, nick)
            end
        end
        local remote = Proxy.remoteNicks
        if remote and next(remote) ~= nil then
            lowText = lowText or text:lower()
            for _, r in pairs(remote) do
                if type(r) == "table" and type(r.nick) == "string" and type(r.reals) == "table" then
                    for _, real in ipairs(r.reals) do
                        text, lowText = replaceName(text, lowText, real, r.nick)
                    end
                end
            end
        end
        return text
    end
end

local function getPlayerNativeName(userId, fallback)
    if not userId then return fallback or "Unknown" end
    local lp = Players.LocalPlayer
    if lp and tostring(userId) == tostring(lp.UserId) then
        return getLocalNativeName() .. " (You)"
    end

    local sUserId = tostring(userId)

    -- 1. Check direct userIdToName cache
    if Proxy and Proxy.userIdToName and Proxy.userIdToName[sUserId] then
        return Proxy.userIdToName[sUserId]
    end

    -- 2. Check othersPlayerTable (stores exact native in-game names from server)
    if othersPlayerTable then
        for peerId, op in pairs(othersPlayerTable) do
            if type(op) == "table" and op.userId and tostring(op.userId) == sUserId then
                if op.name and op.name ~= "" then
                    if Proxy and Proxy.userIdToName then Proxy.userIdToName[sUserId] = op.name end
                    return op.name
                end
            end
        end
    end

    -- 3. Check knownPeers cache
    if Proxy and Proxy.logsData and Proxy.logsData.knownPeers then
        for _, peer in pairs(Proxy.logsData.knownPeers) do
            if peer.userId and tostring(peer.userId) == sUserId and peer.name and peer.name ~= "" then
                if Proxy and Proxy.userIdToName then Proxy.userIdToName[sUserId] = peer.name end
                return peer.name
            end
        end
    end

    -- 4. Check Players service via Roles.nameOf
    local p = Players:GetPlayerByUserId(userId)
    if p then
        local pName = nil
        pcall(function()
            local rep = game:GetService("ReplicatedStorage")
            local Shared = rep:FindFirstChild("Shared")
            local RolesMod = Shared and Shared:FindFirstChild("Roles")
            if RolesMod then
                local ok, Roles = pcall(require, RolesMod)
                if ok and Roles and Roles.nameOf then
                    pName = Roles.nameOf(p)
                end
            end
        end)
        if pName and pName ~= "" then
            local clean = pName:gsub("`%w", ""):gsub("``", ""):gsub("^@", "")
            if clean ~= p.Name then
                if Proxy and Proxy.userIdToName then Proxy.userIdToName[sUserId] = clean end
                return clean
            end
        end
        local attr = p:GetAttribute("Nick") or p:GetAttribute("GameName") or p:GetAttribute("Name")
        if attr and attr ~= "" then return tostring(attr) end
    end

    return fallback or ("Player (" .. tostring(userId) .. ")")
end
