function Proxy.notify(str)
    pcall(function()
        if Proxy.chatTableRef and Proxy.chatTableRef.add then
            Proxy.chatTableRef.add(str)
        else
            print("[Proxy Notify]", str)
        end
    end)
end

function Proxy.getOwnedCount(itemId)
    if Proxy.invRef and type(Proxy.invRef.count) == "function" then
        local success, count = pcall(function() return Proxy.invRef:count(itemId) end)
        if success and type(count) == "number" then return count end
    end
    if Proxy.invRef and type(Proxy.invRef.slots) == "table" then
        for _, slot in ipairs(Proxy.invRef.slots) do
            if type(slot) == "table" and slot[1] == itemId then
                return slot[2] or 0
            end
        end
    end
    local inv = getNativeInventory()
    if inv and type(inv.count) == "function" then
        local s, c = pcall(function() return inv:count(itemId) end)
        if s and type(c) == "number" then return c end
    end
    if inv and type(inv.slots) == "table" then
        for _, slot in ipairs(inv.slots) do
            if type(slot) == "table" and slot[1] == itemId then
                return slot[2] or 0
            end
        end
    end
    return 0
end

function Proxy.saveConfig()
    task.spawn(function()
        pcall(function()
            if not writefile then return end

        -- Selalu sinkronkan inputbox Storage World & Door ke AutoBuildDF sebelum menyimpan
        if inpStorageWorld and inpStorageWorld.Text ~= "" then
            AutoBuildDF.storageWorld = string.upper((string.gsub(inpStorageWorld.Text or "", "%s+", "")))
        end
        if inpStorageDoor then
            AutoBuildDF.storageDoor = string.gsub(inpStorageDoor.Text or "", "%s+", "")
        end

        local curNick = (Players.LocalPlayer and Players.LocalPlayer:GetAttribute("Nick")) or nil
        local curAccName = (Players.LocalPlayer and Players.LocalPlayer.Name) or ""
        local curAccId = (Players.LocalPlayer and Players.LocalPlayer.UserId) or 0

        local cfg = {
            accountName = curAccName,
            accountUserId = curAccId,
            -- Active Tab
            activeTab = activeTabKey or "player",
            hideWorldName = (Proxy and Proxy.hideWorldName == true),
            hidePlayerName = (Proxy and Proxy.hidePlayerName == true),

            -- Tab 1: PLAYER
            player = {
                hazardEnabled = (AntiHazard and AntiHazard.enabled == true),
                antiLava = (AntiHazard and AntiHazard.antiLava ~= false),
                antiDeadly = (AntiHazard and AntiHazard.antiDeadly ~= false),
                antiBounce = (AntiHazard and AntiHazard.antiBounce ~= false),
                antiLaser = (AntiHazard and AntiHazard.antiLaser ~= false),
                antiBumper = (AntiHazard and AntiHazard.antiBumper ~= false),
                clickPathfind = (ClickPathfind and ClickPathfind.enabled == true),
                speedEnabled = (Mobility and Mobility.speedEnabled == true),
                speedMultiplier = (Mobility and Mobility.speedMultiplier) or 2.0,
                fastDrop = (FastInventory and FastInventory.fastDrop == true),
                fastRecycle = (FastInventory and FastInventory.fastRecycle == true),
                customCountEnabled = (FastInventory and FastInventory.customCountEnabled == true),
                customCount = (FastInventory and FastInventory.customCount) or 1,
                camera = {
                    enabled = (CameraZoom and CameraZoom.enabled == true),
                    zoomScale = (CameraZoom and CameraZoom.zoomScale) or 0.5,
                },
                antiStaff = {
                    enabled = (AntiStaff and AntiStaff.enabled ~= false),
                    autoKick = (AntiStaff and AntiStaff.autoKick == true),
                    autoFreeze = (AntiStaff and AntiStaff.autoFreeze ~= false),
                },
            },

            -- Tab 2: FARM
            farm = {
                pnb = {
                    targets = (PNB and type(PNB.targets) == "table") and PNB.targets or {},
                    itemId = PNB and (PNB.itemId or PNB.targetItemId) or 2,
                    itemName = PNB and PNB.itemName or "Dirt",
                    itemKind = PNB and PNB.itemKind or "block",
                    hits = PNB and (PNB.hits or PNB.hitsPerBlock) or 3,
                    hitDelay = PNB and PNB.hitDelay or 0.18,
                    loopDelay = PNB and PNB.loopDelay or 0.12,
                    mode = PNB and PNB.mode or "PNB",
                    layer = PNB and PNB.layer or "fg",
                },
                plant = {
                    selectedSeedId = AutoPlant and AutoPlant.selectedSeedId or nil,
                    selectedSeedName = AutoPlant and AutoPlant.selectedSeedName or "Bibit Otomatis (Tas)",
                    radius = AutoPlant and AutoPlant.radius or 50,
                    storage = FarmLogistics and FarmLogistics.plantStorage or nil,
                    worlds = FarmLogistics and FarmLogistics.plantWorlds or nil,
                },
                harvest = {
                    radius = AutoHarvest and AutoHarvest.radius or 999,
                    storage = FarmLogistics and FarmLogistics.harvestStorage or nil,
                    worlds = FarmLogistics and FarmLogistics.harvestWorlds or nil,
                },
                moveWorld = FarmLogistics and {
                    itemIds = FarmLogistics.move.itemIds,
                    itemNames = FarmLogistics.move.itemNames,
                    fromWorld = FarmLogistics.move.fromWorld,
                    fromDoor = FarmLogistics.move.fromDoor,
                    toWorld = FarmLogistics.move.toWorld,
                    toDoor = FarmLogistics.move.toDoor,
                    toX = FarmLogistics.move.toX,
                    toY = FarmLogistics.move.toY,
                } or nil,
                magnet = {
                    enabled = Magnet and (Magnet.enabled == true) or false,
                    radius = Magnet and Magnet.radius or 12,
                    filterMode = "ALL",
                    dontReturnToStart = Magnet and (Magnet.dontReturnToStart == true) or false,
                    delay = Magnet and Magnet.delay or 0.25,
                },
            },

            -- Tab 3: FACTORY
            factory = {
                posBreakX = AutoFactory and AutoFactory.posBreakX or nil,
                posBreakY = AutoFactory and AutoFactory.posBreakY or nil,
                posDropX = AutoFactory and AutoFactory.posDropX or nil,
                posDropY = AutoFactory and AutoFactory.posDropY or nil,
                factoryLength = AutoFactory and AutoFactory.factoryLength or 30,
                profitLimit = AutoFactory and AutoFactory.profitLimit or 100,
                targetSeedId = AutoFactory and AutoFactory.targetSeedId or nil,
                targetSeedName = AutoFactory and AutoFactory.targetSeedName or "Pilih Seed",
                targetBlockId = AutoFactory and AutoFactory.targetBlockId or nil,
                targetBlockName = AutoFactory and AutoFactory.targetBlockName or "Block",
            },

            -- Tab ROTATION
            rotation = {
                worlds = AutoRotation and AutoRotation.worlds or {},
                storageWorld = AutoRotation and AutoRotation.storageWorld or "",
                storageDoor = AutoRotation and AutoRotation.storageDoor or "",
                storageDropX = AutoRotation and AutoRotation.storageDropX or nil,
                storageDropY = AutoRotation and AutoRotation.storageDropY or nil,
                seedProfitToDrop = AutoRotation and AutoRotation.seedProfitToDrop or 100,
                minSeedReserve = AutoRotation and AutoRotation.minSeedReserve or 90,
                autoBuyPack = AutoRotation and (AutoRotation.autoBuyPack == true) or false,
                buyPackKey = AutoRotation and AutoRotation.buyPackKey or "world_lock",
                buyPackCount = AutoRotation and AutoRotation.buyPackCount or 1,
                packStorageWorld = AutoRotation and AutoRotation.packStorageWorld or "",
                packStorageDoor = AutoRotation and AutoRotation.packStorageDoor or "",
                packStorageDropX = AutoRotation and AutoRotation.packStorageDropX or nil,
                packStorageDropY = AutoRotation and AutoRotation.packStorageDropY or nil,
            },

            -- Tab EVENT
            event = {
                storageWorld = AutoEvent and (AutoEvent.inpStorageWorld and AutoEvent.inpStorageWorld.Text ~= "" and string.upper((AutoEvent.inpStorageWorld.Text):gsub("%s+", "")) or AutoEvent.storageWorld) or "",
                storageDoor = AutoEvent and (AutoEvent.inpStorageDoor and (AutoEvent.inpStorageDoor.Text):gsub("%s+", "") or AutoEvent.storageDoor) or "",
                burnItemId = AutoEvent and (AutoEvent.inpItemId and tonumber(AutoEvent.inpItemId.Text) or AutoEvent.burnItemId) or 2,
                burnItemName = AutoEvent and AutoEvent.burnItemName or "Dirt",
                burnTargetCount = AutoEvent and (AutoEvent.inpTargetAmt and tonumber(AutoEvent.inpTargetAmt.Text) or AutoEvent.burnTargetCount) or 200,
                npcPos = AutoEvent and AutoEvent.npcPos or nil,
                gameRarity = AutoEvent and AutoEvent.gameRarity or 1267,
            },

            -- Tab 4: WORLD
            world = {
                dirtFarm = {
                    mainBlockId = AutoBuildDF and AutoBuildDF.mainBlockId or 2,
                    mainBlockName = AutoBuildDF and AutoBuildDF.mainBlockName or "Dirt",
                    platBlockId = AutoBuildDF and AutoBuildDF.platBlockId or 102,
                    platBlockName = AutoBuildDF and AutoBuildDF.platBlockName or "Wooden Platform",
                    platWidth = 1,
                    bottomY = 53,
                    topY = 2,
                    stepY = 2,
                    minX = 1,
                    maxX = 98,
                    buildDelay = AutoBuildDF and AutoBuildDF.buildDelay or 0.06,
                    autoRestock = AutoBuildDF and (AutoBuildDF.autoRestock == true) or false,
                    storageWorld = AutoBuildDF and AutoBuildDF.storageWorld or "",
                    storageDoor = AutoBuildDF and AutoBuildDF.storageDoor or "",
                },
                clearWorld = {
                    clearBG = ClearWorld and (ClearWorld.clearBG ~= false),
                    autoSweep = ClearWorld and (ClearWorld.autoSweep ~= false),
                    autoTrash = ClearWorld and (ClearWorld.autoTrash == true),
                    hitDelay = ClearWorld and ClearWorld.hitDelay or 0.14,
                },
            },

            -- Tab 5: SPAM
            spam = {
                delay = SpamConfig and SpamConfig.delay or 3.0,
                messages = SpamConfig and SpamConfig.messages or {
                    "SELL WORLD / DROP ITEMS!",
                    "BUY DL / ITEMS PROMO!",
                    "VISIT MY SHOP NOW!",
                },
            },

            -- Tab 6: PROXY
            proxy = {
                fastPK = (Proxy and Proxy.fastPKEnabled == true),
                punchGemsCheck = (Proxy and Proxy.punchGemsCheck == true),
                fastRoulette = (Proxy and Proxy.fastRoulette ~= false),
                rouletteDetector = (Proxy and Proxy.rouletteDetector ~= false),
                autoJoinEnabled = (AutoRejoin and AutoRejoin.enabled ~= false),
                autoConvertEnabled = (autoConvertRunning ~= false),
                casino = {
                    hostPos = Proxy and Proxy.casino and Proxy.casino.hostPos or nil,
                    positions = Proxy and Proxy.casino and Proxy.casino.positions or {},
                    taxRate = Proxy and Proxy.casino and Proxy.casino.taxRate or 10,
                },
                nick = curNick,
                lastWorldName = Proxy and Proxy.lastWorldName or "",
            },

            -- Root level backwards compatibility
            pnb = {
                targets = (PNB and type(PNB.targets) == "table") and PNB.targets or {},
                itemId = PNB and (PNB.itemId or PNB.targetItemId) or 2,
                itemName = PNB and PNB.itemName or "Dirt",
                itemKind = PNB and PNB.itemKind or "block",
                hits = PNB and (PNB.hits or PNB.hitsPerBlock) or 3,
                hitDelay = PNB and PNB.hitDelay or 0.18,
                loopDelay = PNB and PNB.loopDelay or 0.12,
                mode = PNB and PNB.mode or "PNB",
                layer = PNB and PNB.layer or "fg",
            },
            casino = {
                hostPos = Proxy and Proxy.casino and Proxy.casino.hostPos or nil,
                positions = Proxy and Proxy.casino and Proxy.casino.positions or {},
                taxRate = Proxy and Proxy.casino and Proxy.casino.taxRate or 10,
            },
            nick = curNick,
            uiScaleMode = uiScaleMode or "Auto",
            fastPK = (Proxy and Proxy.fastPKEnabled == true),
            punchGemsCheck = (Proxy and Proxy.punchGemsCheck == true),
            fastRoulette = (Proxy and Proxy.fastRoulette ~= false),
            rouletteDetector = (Proxy and Proxy.rouletteDetector ~= false),
        }

        local targetCfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or CONFIG_FILE
        writefile(targetCfgFile, HttpService:JSONEncode(cfg))
    end)
    end)
end

function Proxy.loadConfig()
    pcall(function()
        if not isfile or not readfile then return end
        local targetCfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or CONFIG_FILE
        local fileToRead = nil
        if isfile(targetCfgFile) then
            fileToRead = targetCfgFile
        elseif isfile(CONFIG_FILE) then
            fileToRead = CONFIG_FILE
        end
        if not fileToRead then return end
        local raw = readfile(fileToRead)
        if not raw or raw == "" then return end
        local cfg = HttpService:JSONDecode(raw)
        if type(cfg) ~= "table" then return end

        -- Auto-migrasi ke file akun jika dibaca dari legacy file lama
        if fileToRead == CONFIG_FILE and fileToRead ~= targetCfgFile and writefile then
            pcall(function()
                writefile(targetCfgFile, raw)
            end)
        end

        Proxy._isLoadingConfig = true
        if cfg.hideWorldName ~= nil and Proxy then
            Proxy.hideWorldName = cfg.hideWorldName
            if Proxy.btnEyeWorld then
                Proxy.btnEyeWorld.Text = Proxy.hideWorldName and "🔒" or "👁"
                Proxy.btnEyeWorld.BackgroundColor3 = Proxy.hideWorldName and C.rim or C.box
            end
        end
        if cfg.hidePlayerName ~= nil and Proxy then
            Proxy.hidePlayerName = cfg.hidePlayerName
            if Proxy.btnEyePlayer then
                Proxy.btnEyePlayer.Text = Proxy.hidePlayerName and "🔒" or "👁"
                Proxy.btnEyePlayer.BackgroundColor3 = Proxy.hidePlayerName and C.rim or C.box
            end
        end

        if cfg.uiScaleMode ~= nil and setUIScaleMode then
            setUIScaleMode(cfg.uiScaleMode, false)
        end

        -- 1. PLAYER TAB
        if cfg.player and type(cfg.player) == "table" then
            local p = cfg.player
            if p.hazardEnabled ~= nil and AntiHazard then AntiHazard.enabled = p.hazardEnabled end
            if p.antiLava ~= nil and AntiHazard then AntiHazard.antiLava = p.antiLava end
            if p.antiDeadly ~= nil and AntiHazard then AntiHazard.antiDeadly = p.antiDeadly end
            if p.antiBounce ~= nil and AntiHazard then AntiHazard.antiBounce = p.antiBounce end
            if p.antiLaser ~= nil and AntiHazard then AntiHazard.antiLaser = p.antiLaser end
            if p.antiBumper ~= nil and AntiHazard then AntiHazard.antiBumper = p.antiBumper end
            if p.clickPathfind ~= nil and ClickPathfind then ClickPathfind.enabled = p.clickPathfind end
            if p.speedEnabled ~= nil and Mobility then Mobility.speedEnabled = p.speedEnabled end
            if p.speedMultiplier ~= nil and Mobility then Mobility.speedMultiplier = p.speedMultiplier end
            if p.fastDrop ~= nil and FastInventory then FastInventory.fastDrop = p.fastDrop end
            if p.fastRecycle ~= nil and FastInventory then FastInventory.fastRecycle = p.fastRecycle end
            if p.customCountEnabled ~= nil and FastInventory then FastInventory.customCountEnabled = p.customCountEnabled end
            if p.customCount ~= nil and FastInventory then FastInventory.customCount = p.customCount end

            -- Apply player systems
            if applyAntiHazard then pcall(applyAntiHazard) end
            if applySpeedMode then pcall(applySpeedMode) end
            if toggleClickPathfindGrid and ClickPathfind then pcall(toggleClickPathfindGrid, ClickPathfind.enabled) end
            if ensureFastInventoryOverlays then pcall(ensureFastInventoryOverlays) end

            if p.camera and CameraZoom then
                if p.camera.enabled ~= nil then CameraZoom.enabled = p.camera.enabled end
                if p.camera.zoomScale ~= nil then CameraZoom.zoomScale = p.camera.zoomScale end
                if CameraZoom.apply then CameraZoom.apply() end
                if CameraZoom.updateUI then CameraZoom.updateUI() end
            end
            if p.antiStaff and AntiStaff then
                if p.antiStaff.enabled ~= nil then AntiStaff.enabled = p.antiStaff.enabled end
                if p.antiStaff.autoKick ~= nil then AntiStaff.autoKick = p.antiStaff.autoKick end
                if p.antiStaff.autoFreeze ~= nil then AntiStaff.autoFreeze = p.antiStaff.autoFreeze end
                if AntiStaff.updateUI then AntiStaff.updateUI() end
            end
        end

        -- 2. FARM TAB
        local farmCfg = cfg.farm or {}
        local pnbCfg = farmCfg.pnb or cfg.pnb
        if pnbCfg and PNB then
            if type(pnbCfg.targets) == "table" and next(pnbCfg.targets) ~= nil then
                PNB.targets = pnbCfg.targets
            end
            if pnbCfg.itemId then
                PNB.itemId = pnbCfg.itemId
                PNB.targetItemId = pnbCfg.itemId
            end
            if pnbCfg.itemName then PNB.itemName = pnbCfg.itemName end
            if pnbCfg.itemKind then PNB.itemKind = pnbCfg.itemKind end
            if pnbCfg.hits then
                PNB.hits = pnbCfg.hits
                PNB.hitsPerBlock = pnbCfg.hits
            end
            if pnbCfg.hitDelay then PNB.hitDelay = pnbCfg.hitDelay end
            if pnbCfg.loopDelay then PNB.loopDelay = pnbCfg.loopDelay end
            if pnbCfg.mode then PNB.mode = pnbCfg.mode end
            if pnbCfg.layer then PNB.layer = pnbCfg.layer end
            PNB.active = false
        end

        if farmCfg.plant and AutoPlant then
            if farmCfg.plant.selectedSeedId ~= nil then AutoPlant.selectedSeedId = farmCfg.plant.selectedSeedId end
            if farmCfg.plant.selectedSeedName ~= nil then AutoPlant.selectedSeedName = farmCfg.plant.selectedSeedName end
            if farmCfg.plant.radius ~= nil then AutoPlant.radius = farmCfg.plant.radius end
        end

        if farmCfg.harvest and AutoHarvest then
            if farmCfg.harvest.radius ~= nil then AutoHarvest.radius = farmCfg.harvest.radius end
        end

        if FarmLogistics then
            local function loadStorage(dst, src)
                if type(src) ~= "table" then return end
                dst.world = FarmLogistics.cleanWorld(src.world)
                dst.door = tostring(src.door or "")
                dst.x = tonumber(src.x)
                dst.y = tonumber(src.y)
                dst.enabled = (src.enabled == true)
                if src.threshold ~= nil then dst.threshold = math.clamp(math.floor(tonumber(src.threshold) or 180), 1, 200) end
            end
            loadStorage(FarmLogistics.plantStorage, farmCfg.plant and farmCfg.plant.storage)
            loadStorage(FarmLogistics.harvestStorage, farmCfg.harvest and farmCfg.harvest.storage)
            -- List world farm (isi ulang tabel yang SAMA, karena UI memegang referensinya)
            local function loadWorlds(dst, src)
                if type(src) ~= "table" then return end
                table.clear(dst)
                for _, e in ipairs(src) do
                    if type(e) == "table" and type(e.world) == "string" and e.world ~= "" then
                        local sid = tonumber(e.seedId)
                        table.insert(dst, {
                            world = FarmLogistics.cleanWorld(e.world),
                            seedId = sid,
                            seedName = (sid and (e.seedName or FarmLogistics.itemName(sid))) or nil,
                            door = tostring(e.door or ""),
                        })
                    end
                end
            end
            loadWorlds(FarmLogistics.plantWorlds, farmCfg.plant and farmCfg.plant.worlds)
            loadWorlds(FarmLogistics.harvestWorlds, farmCfg.harvest and farmCfg.harvest.worlds)
            local mv = farmCfg.moveWorld
            if type(mv) == "table" and not FarmLogistics.move.active then
                local M = FarmLogistics.move
                M.itemIds, M.itemNames = {}, {}
                for i, id in ipairs(type(mv.itemIds) == "table" and mv.itemIds or {}) do
                    if tonumber(id) then
                        table.insert(M.itemIds, tonumber(id))
                        table.insert(M.itemNames, (type(mv.itemNames) == "table" and mv.itemNames[i]) or ("#" .. id))
                    end
                end
                M.fromWorld = FarmLogistics.cleanWorld(mv.fromWorld)
                M.fromDoor = tostring(mv.fromDoor or "")
                M.toWorld = FarmLogistics.cleanWorld(mv.toWorld)
                M.toDoor = tostring(mv.toDoor or "")
                M.toX, M.toY = tonumber(mv.toX), tonumber(mv.toY)
            end
            if updateMoveUI then pcall(updateMoveUI) end
        end

        if farmCfg.magnet and Magnet then
            if farmCfg.magnet.enabled ~= nil then
                Magnet.enabled = farmCfg.magnet.enabled
                if Magnet.enabled and startMagnetLoop then
                    startMagnetLoop()
                elseif not Magnet.enabled and stopMagnetLoop then
                    stopMagnetLoop()
                end
            end
            if farmCfg.magnet.radius ~= nil then Magnet.radius = farmCfg.magnet.radius end
            Magnet.filterMode = "ALL"
            if farmCfg.magnet.dontReturnToStart ~= nil then Magnet.dontReturnToStart = (farmCfg.magnet.dontReturnToStart == true) end
            if farmCfg.magnet.delay ~= nil then Magnet.delay = farmCfg.magnet.delay end
        end

        -- 3. FACTORY TAB
        if cfg.factory and AutoFactory then
            local fac = cfg.factory
            if fac.posBreakX ~= nil then AutoFactory.posBreakX = fac.posBreakX end
            if fac.posBreakY ~= nil then AutoFactory.posBreakY = fac.posBreakY end
            if fac.posDropX ~= nil then AutoFactory.posDropX = fac.posDropX end
            if fac.posDropY ~= nil then AutoFactory.posDropY = fac.posDropY end
            if fac.factoryLength ~= nil then AutoFactory.factoryLength = fac.factoryLength end
            if fac.profitLimit ~= nil then AutoFactory.profitLimit = fac.profitLimit end
            if fac.targetSeedId ~= nil then AutoFactory.targetSeedId = fac.targetSeedId end
            if fac.targetSeedName ~= nil then AutoFactory.targetSeedName = fac.targetSeedName end
            if fac.targetBlockId ~= nil then AutoFactory.targetBlockId = fac.targetBlockId end
            if fac.targetBlockName ~= nil then AutoFactory.targetBlockName = fac.targetBlockName end
        end

        -- ROTATION TAB
        if cfg.rotation and AutoRotation then
            local rot = cfg.rotation
            if type(rot.worlds) == "table" then AutoRotation.worlds = rot.worlds end
            if rot.storageWorld ~= nil then AutoRotation.storageWorld = rot.storageWorld end
            if rot.storageDoor ~= nil then AutoRotation.storageDoor = rot.storageDoor end
            if rot.storageDropX ~= nil then AutoRotation.storageDropX = rot.storageDropX end
            if rot.storageDropY ~= nil then AutoRotation.storageDropY = rot.storageDropY end
            if rot.seedProfitToDrop ~= nil then AutoRotation.seedProfitToDrop = rot.seedProfitToDrop end
            if rot.minSeedReserve ~= nil then AutoRotation.minSeedReserve = rot.minSeedReserve end
            if rot.autoBuyPack ~= nil then AutoRotation.autoBuyPack = (rot.autoBuyPack == true) end
            if rot.buyPackKey ~= nil then
                AutoRotation.buyPackKey = rot.buyPackKey
                if AutoShop then AutoShop.targetPackKey = rot.buyPackKey end
            end
            if rot.buyPackCount ~= nil then
                AutoRotation.buyPackCount = tonumber(rot.buyPackCount) or 1
                if AutoShop then AutoShop.targetCount = AutoRotation.buyPackCount end
            end
            if rot.packStorageWorld ~= nil then AutoRotation.packStorageWorld = rot.packStorageWorld end
            if rot.packStorageDoor ~= nil then AutoRotation.packStorageDoor = rot.packStorageDoor end
            if rot.packStorageDropX ~= nil then AutoRotation.packStorageDropX = rot.packStorageDropX end
            if rot.packStorageDropY ~= nil then AutoRotation.packStorageDropY = rot.packStorageDropY end
            if refreshRotationWorldList then refreshRotationWorldList() end
            if updateRotationUI then updateRotationUI() end
        end

        -- EVENT TAB
        if cfg.event and AutoEvent then
            local ev = cfg.event
            if ev.storageWorld ~= nil then AutoEvent.storageWorld = ev.storageWorld end
            if ev.storageDoor ~= nil then AutoEvent.storageDoor = ev.storageDoor end
            if ev.burnItemId ~= nil then AutoEvent.burnItemId = ev.burnItemId end
            if ev.burnItemName ~= nil then AutoEvent.burnItemName = ev.burnItemName end
            if ev.burnTargetCount ~= nil then AutoEvent.burnTargetCount = ev.burnTargetCount end
            if ev.npcPos ~= nil then AutoEvent.npcPos = ev.npcPos end
            if ev.gameRarity ~= nil then AutoEvent.gameRarity = ev.gameRarity end
            if updateEventUI then updateEventUI() end
        end

        -- 4. WORLD TAB
        if cfg.world and type(cfg.world) == "table" then
            local w = cfg.world
            if w.dirtFarm and AutoBuildDF then
                local df = w.dirtFarm
                if df.mainBlockId ~= nil then AutoBuildDF.mainBlockId = df.mainBlockId end
                if df.mainBlockName ~= nil then AutoBuildDF.mainBlockName = df.mainBlockName end
                if df.platBlockId ~= nil then AutoBuildDF.platBlockId = df.platBlockId end
                if df.platBlockName ~= nil then AutoBuildDF.platBlockName = df.platBlockName end
                AutoBuildDF.platWidth = 1
                AutoBuildDF.bottomY = 53
                AutoBuildDF.topY = 2
                AutoBuildDF.stepY = 2
                AutoBuildDF.minX = 1
                AutoBuildDF.maxX = 98
                if df.buildDelay ~= nil then AutoBuildDF.buildDelay = df.buildDelay end
                if df.autoRestock ~= nil then AutoBuildDF.autoRestock = df.autoRestock end
                if df.storageWorld ~= nil then AutoBuildDF.storageWorld = df.storageWorld end
                if df.storageDoor ~= nil then AutoBuildDF.storageDoor = df.storageDoor end
            end
            if w.clearWorld and ClearWorld then
                local cw = w.clearWorld
                if cw.clearBG ~= nil then ClearWorld.clearBG = cw.clearBG end
                if cw.autoSweep ~= nil then ClearWorld.autoSweep = cw.autoSweep end
                if cw.autoTrash ~= nil then ClearWorld.autoTrash = cw.autoTrash end
                if cw.hitDelay ~= nil then ClearWorld.hitDelay = cw.hitDelay end
            end
        end

        -- 5. SPAM TAB
        if cfg.spam and SpamConfig then
            if cfg.spam.delay ~= nil then SpamConfig.delay = cfg.spam.delay end
            if type(cfg.spam.messages) == "table" and #cfg.spam.messages > 0 then
                SpamConfig.messages = cfg.spam.messages
            end
        end

        -- 6. PROXY TAB
        local proxyCfg = cfg.proxy or {}
        local casinoCfg = proxyCfg.casino or cfg.casino
        if casinoCfg and Proxy.casino then
            if type(casinoCfg.hostPos) == "table" then Proxy.casino.hostPos = casinoCfg.hostPos end
            if type(casinoCfg.positions) == "table" then Proxy.casino.positions = casinoCfg.positions end
            if type(casinoCfg.taxRate) == "number" then Proxy.casino.taxRate = casinoCfg.taxRate end
        end

        local fastPKVal = (proxyCfg.fastPK ~= nil and proxyCfg.fastPK) or cfg.fastPK
        if fastPKVal ~= nil then
            Proxy.fastPKEnabled = fastPKVal
        end

        local punchVal = (proxyCfg.punchGemsCheck ~= nil and proxyCfg.punchGemsCheck) or cfg.punchGemsCheck
        if punchVal ~= nil then
            Proxy.punchGemsCheck = punchVal
        end

        local frVal = (proxyCfg.fastRoulette ~= nil and proxyCfg.fastRoulette) or cfg.fastRoulette
        if frVal ~= nil then
            Proxy.fastRoulette = frVal
        end

        local rdVal = (proxyCfg.rouletteDetector ~= nil and proxyCfg.rouletteDetector) or cfg.rouletteDetector
        if rdVal ~= nil then
            Proxy.rouletteDetector = rdVal
        end

        if proxyCfg.autoJoinEnabled ~= nil and AutoRejoin then
            AutoRejoin.enabled = proxyCfg.autoJoinEnabled
        end

        if proxyCfg.autoConvertEnabled ~= nil then
            autoConvertRunning = proxyCfg.autoConvertEnabled
            if _G.autoConvertRunning ~= nil then _G.autoConvertRunning = autoConvertRunning end
        end

        local nickVal = proxyCfg.nick or cfg.nick
        if nickVal and type(nickVal) == "string" and nickVal ~= "" and Players.LocalPlayer then
            Players.LocalPlayer:SetAttribute("Nick", nickVal)
        end

        if proxyCfg.lastWorldName and proxyCfg.lastWorldName ~= "" then
            Proxy.lastWorldName = proxyCfg.lastWorldName
        end

        -- 7. TAB RESTORATION
        if cfg.activeTab and switchTab then
            pcall(switchTab, cfg.activeTab)
        end

        -- 8. REFRESH ALL UI MODULES
        if updatePlayerUI then pcall(updatePlayerUI) end
        if updateFarmUI then pcall(updateFarmUI) end
        if updatePlantUI then pcall(updatePlantUI) end
        if updateHarvestUI then pcall(updateHarvestUI) end
        if updateMagnetUI then pcall(updateMagnetUI) end
        if updateGridVisuals then pcall(updateGridVisuals) end
        if updateFactoryUI then pcall(updateFactoryUI) end
        if updateDirtFarmUI then pcall(updateDirtFarmUI) end
        if updateClearWorldUI then pcall(updateClearWorldUI) end
        if updateSpamUI then pcall(updateSpamUI) end
        if updateEventUI then pcall(updateEventUI) end
        if Proxy.updateUI then pcall(Proxy.updateUI) end
        Proxy._isLoadingConfig = false
    end)
end

function Proxy.clearConfig()
    local deleted = false
    local targetCfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or CONFIG_FILE
    pcall(function()
        if isfile and delfile then
            if isfile(targetCfgFile) then
                delfile(targetCfgFile)
                deleted = true
            end
            if isfile(CONFIG_FILE) then
                delfile(CONFIG_FILE)
                deleted = true
            end
        end
    end)
    if deleted then
        Proxy.notify(string.format("`2[Config] File config %s berhasil dihapus! Silakan execute ulang untuk menguji auto-config default.``", targetCfgFile))
    else
        Proxy.notify(string.format("`e[Config] File config %s tidak ditemukan atau sudah terhapus!``", targetCfgFile))
    end
end

local convertLockRemote = true

-- Multi-tier Lock Currency System: 1 BGL = 100 DL = 10,000 WL | 1 DL = 100 WL | 1 WL = 1 WL
local CURRENCY_LOCK_IDS = {
    [7188] = 10000, -- Blue Gem Lock
    [1796] = 100,   -- Diamond Lock
    [242]  = 1,     -- World Lock
}

function Proxy.splitWL(totalWL)
    totalWL = math.max(0, math.floor(tonumber(totalWL) or 0))
    local bgl = math.floor(totalWL / 10000)
    local rem1 = totalWL % 10000
    local dl = math.floor(rem1 / 100)
    local wl = rem1 % 100
    return bgl, dl, wl
end

function Proxy.formatCurrency(totalWL)
    totalWL = math.max(0, math.floor(tonumber(totalWL) or 0))
    if totalWL == 0 then return "0 WL" end
    local bgl, dl, wl = Proxy.splitWL(totalWL)
    local parts = {}
    if bgl > 0 then table.insert(parts, bgl .. " BGL") end
    if dl > 0 then table.insert(parts, dl .. " DL") end
    if wl > 0 then table.insert(parts, wl .. " WL") end
    return table.concat(parts, " ")
end

function Proxy.parseCurrency(str)
    if not str then return nil end
    if type(str) == "number" then return math.max(0, math.floor(str)) end
    local s = tostring(str):lower()
    local bgl = tonumber(s:match("(%d+)%s*bgl")) or 0
    local dl  = tonumber(s:match("(%d+)%s*dl")) or 0
    local wl  = tonumber(s:match("(%d+)%s*wl")) or 0
    if bgl > 0 or dl > 0 or wl > 0 then
        return (bgl * 10000) + (dl * 100) + wl
    end
    local raw = tonumber(s:match("(%d+)"))
    return raw
end

function Proxy.ensureLocksForPayout(targetBGL, targetDL, targetWL)
    if not convertLockRemote then return end
    targetBGL = targetBGL or 0
    targetDL = targetDL or 0
    targetWL = targetWL or 0

    -- 1. Pastikan jumlah World Lock (242) cukup untuk targetWL
    local curWL = Proxy.getOwnedCount(242)
    if curWL < targetWL then
        local deficitWL = targetWL - curWL
        local dlsNeeded = math.ceil(deficitWL / 100)
        local curDL = Proxy.getOwnedCount(1796)
        if curDL < dlsNeeded and Proxy.getOwnedCount(7188) > 0 then
            local bglsNeeded = math.ceil((dlsNeeded - curDL) / 100)
            for i = 1, bglsNeeded do
                if Proxy.getOwnedCount(7188) > 0 then
                    sendConvertLock(7188, 1796)
                    task.wait(0.1)
                end
            end
        end
        for i = 1, dlsNeeded do
            if Proxy.getOwnedCount(1796) > 0 then
                sendConvertLock(1796, 242)
                task.wait(0.1)
            end
        end
        task.wait(0.12)
    end

    -- 2. Pastikan jumlah Diamond Lock (1796) cukup untuk targetDL
    local curDL2 = Proxy.getOwnedCount(1796)
    if curDL2 < targetDL then
        -- Coba kompres dari WL jika berlebih (curWL >= targetWL + 100)
        while Proxy.getOwnedCount(242) >= (targetWL + 100) and Proxy.getOwnedCount(1796) < targetDL do
            sendConvertLock(242, 1796)
            task.wait(0.1)
        end
        local curDL3 = Proxy.getOwnedCount(1796)
        if curDL3 < targetDL and Proxy.getOwnedCount(7188) > 0 then
            local deficitDL = targetDL - curDL3
            local bglsNeeded = math.ceil(deficitDL / 100)
            for i = 1, bglsNeeded do
                if Proxy.getOwnedCount(7188) > 0 then
                    sendConvertLock(7188, 1796)
                    task.wait(0.1)
                end
            end
        end
        task.wait(0.12)
    end

    -- 3. Pastikan jumlah Blue Gem Lock (7188) cukup untuk targetBGL
    if targetBGL > 0 then
        while Proxy.getOwnedCount(1796) >= 100 and Proxy.getOwnedCount(7188) < targetBGL do
            sendConvertLock(1796, 7188)
            task.wait(0.1)
        end
    end
end

function Proxy.autoPecahForPayout(targetLockId, neededAmt)
    if not convertLockRemote then return end
    if targetLockId == 242 then
        Proxy.ensureLocksForPayout(0, 0, neededAmt)
    elseif targetLockId == 1796 then
        Proxy.ensureLocksForPayout(0, neededAmt, 0)
    elseif targetLockId == 7188 then
        Proxy.ensureLocksForPayout(neededAmt, 0, 0)
    end
end

function Proxy.autoCompressLocks()
    if not convertLockRemote or Proxy.casino.busy then return end
    if Proxy.casino.lastGame and ((Proxy.casino.lastGame.payout and Proxy.casino.lastGame.payout > 0) or (Proxy.casino.lastGame.payoutWL and Proxy.casino.lastGame.payoutWL > 0)) then
        return
    end
    while Proxy.getOwnedCount(242) >= 100 do
        sendConvertLock(242, 1796)
        task.wait(0.1)
    end
    while Proxy.getOwnedCount(1796) >= 100 do
        sendConvertLock(1796, 7188)
        task.wait(0.1)
    end
end

function Proxy.executeSmartLockDrop(cmd, args)
    if not Proxy.onDropFn then
        Proxy.notify("`4[Drop] Fungsi drop game belum terpasang!``")
        return true
    end

    local lockInfo = Proxy.LOCKS[cmd]
    if not lockInfo then return false end

    local lockId = lockInfo.id
    local lockName = lockInfo.name
    local isCurrency = (lockId == 7188 or lockId == 1796 or lockId == 242)

    local dropArg = (args and args[1] and tostring(args[1]):lower()) or "1"
    if #args > 1 then
        dropArg = table.concat(args, " "):lower()
    end

    -- 1. DROP ALL
    if dropArg == "all" then
        local owned = Proxy.getOwnedCount(lockId)
        if owned <= 0 then
            Proxy.notify(string.format("`4[Drop] Kamu tidak punya %s di tas!``", lockName))
            return true
        end

        task.spawn(function()
            local remaining = owned
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                local ok, err = pcall(function() Proxy.onDropFn(lockId, batch) end)
                if not ok then
                    Proxy.notify(string.format("`4[Drop] Gagal drop %s: %s``", lockName, tostring(err)))
                end
                remaining = remaining - batch
                if remaining > 0 then
                    task.wait(0.35)
                end
            end
            Proxy.notify(string.format("`2[Drop] Berhasil drop %d %s!``", owned, lockName))
            task.delay(0.2, Proxy.updateUI)
        end)
        return true
    end

    -- 2. NON-CURRENCY LOCKS (SL 202, BL 204, HL 206)
    if not isCurrency then
        local dropCount = math.floor(tonumber(dropArg) or 1)
        if dropCount <= 0 then dropCount = 1 end
        local owned = Proxy.getOwnedCount(lockId)
        if owned <= 0 then
            Proxy.notify(string.format("`4[Drop] Kamu tidak punya %s di tas!``", lockName))
            return true
        end
        if dropCount > owned then
            Proxy.notify(string.format("`4[Drop] Jumlah kurang! %s lu cuma ada %d di tas!``", lockName, owned))
            return true
        end

        task.spawn(function()
            local remaining = dropCount
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                local ok, err = pcall(function() Proxy.onDropFn(lockId, batch) end)
                if not ok then
                    Proxy.notify(string.format("`4[Drop] Gagal drop %s: %s``", lockName, tostring(err)))
                end
                remaining = remaining - batch
                if remaining > 0 then
                    task.wait(0.35)
                end
            end
            Proxy.notify(string.format("`2[Drop] Berhasil drop %d %s!``", dropCount, lockName))
            task.delay(0.2, Proxy.updateUI)
        end)
        return true
    end

    -- 3. MULTI-TIER CURRENCY LOCKS (WL 242, DL 1796, BGL 7188)
    local targetWL = nil
    if cmd == "dw" or cmd == "wl" or cmd == "dropwl" then
        local parsed = tonumber(dropArg)
        if not parsed and Proxy.parseCurrency then
            parsed = Proxy.parseCurrency(dropArg)
        end
        targetWL = math.floor(parsed or 1)
    elseif cmd == "dd" or cmd == "dl" or cmd == "dropdl" then
        local parsed = tonumber(dropArg)
        if parsed then
            targetWL = math.floor(parsed * 100)
        elseif Proxy.parseCurrency then
            targetWL = Proxy.parseCurrency(dropArg)
        end
        targetWL = targetWL or 100
    elseif cmd == "dbgl" or cmd == "bgl" or cmd == "dropbgl" then
        local parsed = tonumber(dropArg)
        if parsed then
            targetWL = math.floor(parsed * 10000)
        elseif Proxy.parseCurrency then
            targetWL = Proxy.parseCurrency(dropArg)
        end
        targetWL = targetWL or 10000
    end

    if not targetWL or targetWL <= 0 then
        targetWL = 1
    end

    local curBGL = Proxy.getOwnedCount(7188)
    local curDL  = Proxy.getOwnedCount(1796)
    local curWL  = Proxy.getOwnedCount(242)
    local totalWalletWL = (curBGL * 10000) + (curDL * 100) + (curWL * 1)

    if totalWalletWL < targetWL then
        Proxy.notify(string.format("`4[Drop] Jumlah kurang! Total lock di tas setara %s (butuh %s)!``", Proxy.formatCurrency(totalWalletWL), Proxy.formatCurrency(targetWL)))
        return true
    end

    task.spawn(function()
        -- Direct drop jika sudah punya exact item dalam jumlah cukup tanpa perlu konversi
        if (cmd == "dw" or cmd == "wl" or cmd == "dropwl") and targetWL <= 100 and curWL >= targetWL then
            local remaining = targetWL
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                pcall(function() Proxy.onDropFn(242, batch) end)
                remaining = remaining - batch
                if remaining > 0 then task.wait(0.35) end
            end
            Proxy.notify(string.format("`2[Drop] Berhasil drop %d World Lock!``", targetWL))
            task.delay(0.2, Proxy.updateUI)
            return
        end

        if (cmd == "dd" or cmd == "dl" or cmd == "dropdl") and curDL >= math.floor(targetWL / 100) and (targetWL % 100 == 0) and targetWL < 10000 then
            local dlCount = math.floor(targetWL / 100)
            local remaining = dlCount
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                pcall(function() Proxy.onDropFn(1796, batch) end)
                remaining = remaining - batch
                if remaining > 0 then task.wait(0.35) end
            end
            Proxy.notify(string.format("`2[Drop] Berhasil drop %d Diamond Lock!``", dlCount))
            task.delay(0.2, Proxy.updateUI)
            return
        end

        if (cmd == "dbgl" or cmd == "bgl" or cmd == "dropbgl") and curBGL >= math.floor(targetWL / 10000) and (targetWL % 10000 == 0) then
            local bglCount = math.floor(targetWL / 10000)
            local remaining = bglCount
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                pcall(function() Proxy.onDropFn(7188, batch) end)
                remaining = remaining - batch
                if remaining > 0 then task.wait(0.35) end
            end
            Proxy.notify(string.format("`2[Drop] Berhasil drop %d Blue Gem Lock!``", bglCount))
            task.delay(0.2, Proxy.updateUI)
            return
        end

        -- Smart Multi-Tier Drop (Pecah / Kompres otomatis & multi-drop berurutan)
        local targetBGL, targetDL, targetWL_rem = Proxy.splitWL(targetWL)

        Proxy.ensureLocksForPayout(targetBGL, targetDL, targetWL_rem)

        local dropsToMake = {}
        if targetBGL > 0 then
            table.insert(dropsToMake, { id = 7188, count = targetBGL, name = "Blue Gem Lock" })
        end
        if targetDL > 0 then
            table.insert(dropsToMake, { id = 1796, count = targetDL, name = "Diamond Lock" })
        end
        if targetWL_rem > 0 then
            table.insert(dropsToMake, { id = 242, count = targetWL_rem, name = "World Lock" })
        end

        local descParts = {}
        for _, it in ipairs(dropsToMake) do
            table.insert(descParts, it.count .. " " .. it.name)
        end
        local dropDescStr = table.concat(descParts, ", ")

        for i, it in ipairs(dropsToMake) do
            if Proxy.onDropFn and it.count > 0 then
                local remaining = it.count
                while remaining > 0 do
                    local batch = math.min(remaining, 100)
                    local ok, err = pcall(function() Proxy.onDropFn(it.id, batch) end)
                    if not ok then
                        Proxy.notify(string.format("`4[Drop] Gagal drop %s: %s``", it.name, tostring(err)))
                    end
                    remaining = remaining - batch
                    if remaining > 0 then
                        task.wait(0.35)
                    end
                end
                -- Jeda antar jenis lock yang berbeda (minimal 0.35 detik)
                if i < #dropsToMake then
                    task.wait(0.35)
                end
            end
        end

        Proxy.notify(string.format("`2[Drop] Berhasil drop %s!``", dropDescStr))
        task.delay(0.2, Proxy.updateUI)
    end)
    return true
end

