function Proxy.scanWorldDoors(filterArg, extraArg)
    local w = getNativeWorld and getNativeWorld()
    if not w or not w.name or w.name == "" or string.upper(w.name) == "LOBBY" then
        Proxy.notify("`4[Doors] Kamu belum berada di dalam world!``")
        return
    end

    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local ItemDB = resolveItemDB and resolveItemDB()

    local scannedDoors = {}
    local seen = {}

    -- 1. Scan from w.doors (u4)
    if w.doors and type(w.doors.get) == "function" and debug and debug.getupvalues then
        local ok, upvs = pcall(debug.getupvalues, w.doors.get)
        if ok and upvs then
            local u3 = upvs[1] or (w.w or 100)
            local u4 = upvs[2]
            if type(u4) == "table" then
                for k, d in pairs(u4) do
                    local x = d.x or (k % u3)
                    local y = d.y or math.floor(k / u3)
                    local fgId = (w.fg and w.fg[y] and w.fg[y][x]) or 12
                    local dbItem = (ItemDB and ItemDB[fgId]) or {}
                    local key = y * 1000 + x
                    seen[key] = true
                    table.insert(scannedDoors, {
                        x = x,
                        y = y,
                        x1 = x + 1,
                        y1 = y + 1,
                        fgId = fgId,
                        name = dbItem.name or (fgId == 6 and "Main Door" or ("Door #" .. fgId)),
                        label = d.label or "",
                        dest = d.dest or "",
                        locked = d.locked == true,
                        public = d.public == true,
                        source = "doorsTable"
                    })
                end
            end
        end
    end

    -- 2. Scan from w.fg grid (Main Door and any other door tiles not in u4)
    local maxW = (w.w or 100)
    local maxH = (w.h or 60)
    for y = 0, maxH - 1 do
        if w.fg and w.fg[y] then
            for x = 0, maxW - 1 do
                local fgId = w.fg[y][x]
                if fgId and fgId > 0 then
                    local db = ItemDB and ItemDB[fgId]
                    local isDoor = (fgId == 6 or fgId == 12 or fgId == 224) or (db and (db.door or db.entrance or db.vip or db.hub))
                    if isDoor then
                        local key = y * 1000 + x
                        if not seen[key] then
                            seen[key] = true
                            table.insert(scannedDoors, {
                                x = x,
                                y = y,
                                x1 = x + 1,
                                y1 = y + 1,
                                fgId = fgId,
                                name = (db and db.name) or (fgId == 6 and "Main Door" or ("Door #" .. fgId)),
                                label = (fgId == 6 and "EXIT") or "",
                                dest = (fgId == 6 and "EXIT / LOBBY") or "",
                                locked = false,
                                public = true,
                                source = "gridScan"
                            })
                        end
                    end
                end
            end
        end
    end

    -- Sort doors: Main Door (ID 6) first, then doors with non-empty label, then Door (12) over Entrances, then position (y then x)
    table.sort(scannedDoors, function(a, b)
        local aMain = (a.fgId == 6)
        local bMain = (b.fgId == 6)
        if aMain ~= bMain then return aMain end

        local aHasLabel = (a.label and a.label ~= "")
        local bHasLabel = (b.label and b.label ~= "")
        if aHasLabel ~= bHasLabel then return aHasLabel end

        local aIsDoor = (a.fgId == 12)
        local bIsDoor = (b.fgId == 12)
        if aIsDoor ~= bIsDoor then return aIsDoor end

        if a.y == b.y then return a.x < b.x end
        return a.y < b.y
    end)

    if #scannedDoors == 0 then
        Proxy.notify("`4[Doors] Tidak ada pintu terdeteksi di world ini!``")
        return
    end

    local cleanSub = filterArg and tostring(filterArg):lower() or ""

    -- If filter is "close"
    if cleanSub == "close" then
        Proxy.dismissDoorsUI()
        Proxy.notify("`2[Doors] Popup Door Scanner ditutup.``")
        return
    end

    -- If filter is "tp" with index: /doors tp <index>
    if cleanSub == "tp" and extraArg then
        local targetIdx = tonumber(extraArg)
        if targetIdx and scannedDoors[targetIdx] then
            local td = scannedDoors[targetIdx]
            Proxy.notify(string.format("`2[Doors] OTW teleport ke Door #%d (%d,%d)...``", targetIdx, td.x1, td.y1))
            task.spawn(function() Proxy.casinoGlideTo(td.x, td.y) end)
            return
        else
            Proxy.notify(string.format("`4[Doors] Nomor pintu #%s tidak valid! (1 - %d)``", tostring(extraArg), #scannedDoors))
            return
        end
    end

    -- If filter is direct number: /doors 3
    local directNum = tonumber(cleanSub)
    if directNum and scannedDoors[directNum] then
        local td = scannedDoors[directNum]
        Proxy.notify(string.format("`2[Doors] OTW teleport ke Door #%d (%d,%d)...``", directNum, td.x1, td.y1))
        task.spawn(function() Proxy.casinoGlideTo(td.x, td.y) end)
        return
    end

    -- Filter list if cleanSub is not empty, "chat", "all", or "gui"
    local filteredDoors = scannedDoors
    if cleanSub ~= "" and cleanSub ~= "chat" and cleanSub ~= "all" and cleanSub ~= "gui" then
        filteredDoors = {}
        for _, d in ipairs(scannedDoors) do
            local searchStr = string.format("%s %s %d %d %s", d.name or "", d.label or "", d.x1, d.y1, d.dest or ""):lower()
            if searchStr:find(cleanSub, 1, true) then
                table.insert(filteredDoors, d)
            end
        end
    end

    -- Print summary to chat
    local wName = w.name or "WORLD"
    Proxy.notify(string.format("`2[Doors] World [%s]: %d pintu terdeteksi (Menampilkan %d).``", wName, #scannedDoors, #filteredDoors))

    local chatLimit = (cleanSub == "chat" or cleanSub == "all") and #filteredDoors or math.min(8, #filteredDoors)
    for i = 1, chatLimit do
        local d = filteredDoors[i]
        local statusStr = d.public and "`2[Public]``" or "`4[Private]``"
        local passStr = d.locked and " `8[Pass]``" or ""
        local idStr = (d.label and d.label ~= "") and string.format("ID: `9\"%s\"``", d.label) or "`b(No ID)``"
        local destStr = (d.dest and d.dest ~= "") and string.format(" -> `c%s``", d.dest) or ""
        Proxy.notify(string.format("`3#%d`` (%d,%d) `w[%s]`` %s %s%s%s", i, d.x1, d.y1, d.name, idStr, statusStr, passStr, destStr))
    end

    if #filteredDoors > chatLimit then
        Proxy.notify(string.format("`b... dan %d pintu lainnya. Ketik /doors all untuk print semua atau gunakan GUI!``", #filteredDoors - chatLimit))
    end

    -- Open GUI unless user explicitly specified "chat"
    if cleanSub ~= "chat" then
        Proxy.showDoorsUI(filteredDoors, wName)
    end
end

function Proxy.casinoGlideTo(targetTileX, targetTileY)
    local px, py, rawX, rawY = getPlayerTilePos()
    if not px or not py then return false end
    if px == targetTileX and py == targetTileY then return true end

    -- Cari rute pathfinding A* yang otomatis respect pintu / entrance locked
    local path = findPath(px, py, targetTileX, targetTileY, 25000)
    if path and #path > 0 then
        ClickPathfind.busy = true
        followPath(path, 0.85, rawX or (px + 0.5), rawY or (py + 1.0))
        ClickPathfind.busy = false
        task.wait(0.08)
        return true
    else
        -- Jika target persis terhalang atau berada di samping, cari pijakan terbuka di sekitarnya
        local altPath = nil
        for _, off in ipairs({{0, -1}, {-1, 0}, {1, 0}, {0, 1}}) do
            local ax = targetTileX + off[1]
            local ay = targetTileY + off[2]
            if ax >= 0 and ax < 100 and ay >= 0 and ay < 60 and not isSolidTile(ax, ay) then
                local p = findPath(px, py, ax, ay, 25000)
                if p and #p > 0 then
                    altPath = p
                    break
                end
            end
        end

        if altPath and #altPath > 0 then
            ClickPathfind.busy = true
            followPath(altPath, 0.85, rawX or (px + 0.5), rawY or (py + 1.0))
            ClickPathfind.busy = false
            task.wait(0.08)
            return true
        else
            -- Terhalang penuh oleh pintu locked atau dinding tanpa celah
            Proxy.notify(string.format("`4[TP] Jalur ke (%d, %d) terhalang oleh pintu locked atau dinding!``", targetTileX + 1, targetTileY + 1))
            return false
        end
    end
end

function Proxy.getPositionDrops(pos)
    local w = getNativeWorld()
    if not w or not w.dropList then return 0, nil, "", false, nil end
    local drops = w.dropList()
    if not drops or #drops == 0 then return 0, nil, "", false, nil end

    local targetX = pos.x
    local targetY = pos.y

    -- 1. Hitung HANYA lock / mata uang yang sah (Proxy.LOCK_NAMES), ABAIKAN Gems (id 112)!
    -- Strict Tile Match: math.floor(drop.x) == targetX and math.floor(drop.y) == targetY
    local lockCounts = {}
    local seenUids = {}
    for _, drop in ipairs(drops) do
        local uid = drop and (drop.uid or drop)
        if uid and not seenUids[uid] and drop and drop.id and drop.n and drop.n > 0 and drop.id ~= 112 and not drop.taking then
            if type(drop.x) == "number" and type(drop.y) == "number" then
                if math.floor(drop.x) == targetX and math.floor(drop.y) == targetY then
                    seenUids[uid] = true
                    local id = drop.id
                    if Proxy.LOCK_NAMES and Proxy.LOCK_NAMES[id] then
                        lockCounts[id] = (lockCounts[id] or 0) + drop.n
                    end
                end
            end
        end
    end

    -- Cek mata uang utama: BGL (7188), DL (1796), WL (242)
    local bglCount = lockCounts[7188] or 0
    local dlCount  = lockCounts[1796] or 0
    local wlCount  = lockCounts[242]  or 0

    if bglCount > 0 or dlCount > 0 or wlCount > 0 then
        local totalWL = (bglCount * 10000) + (dlCount * 100) + (wlCount * 1)
        local highestId = (bglCount > 0 and 7188) or (dlCount > 0 and 1796) or 242
        local formatted = Proxy.formatCurrency(totalWL)
        local breakdown = { bgl = bglCount, dl = dlCount, wl = wlCount }
        return totalWL, highestId, formatted, true, breakdown
    end

    -- 2. Jika tidak ada currency lock, hitung item lain secara terpisah per item ID
    if not next(lockCounts) then
        seenUids = {}
        for _, drop in ipairs(drops) do
            local uid = drop and (drop.uid or drop)
            if uid and not seenUids[uid] and drop and drop.id and drop.n and drop.n > 0 and drop.id ~= 112 and not drop.taking then
                if type(drop.x) == "number" and type(drop.y) == "number" then
                    if math.floor(drop.x) == targetX and math.floor(drop.y) == targetY then
                        seenUids[uid] = true
                        local id = drop.id
                        lockCounts[id] = (lockCounts[id] or 0) + drop.n
                    end
                end
            end
        end
    end

    local bestId, bestCount = nil, 0
    for id, count in pairs(lockCounts) do
        if count > bestCount then
            bestCount = count
            bestId = id
        end
    end

    if bestId then
        local lname = (Proxy.LOCK_NAMES and Proxy.LOCK_NAMES[bestId]) or (ItemDB and ItemDB[bestId] and ItemDB[bestId].name) or ("Item #" .. bestId)
        return bestCount, bestId, lname, false, nil
    end
    return 0, nil, "", false, nil
end

function Proxy.sweepTileDrops(tileX, tileY)
    local w = getNativeWorld()
    if not w or not w.dropList then return {} end
    local drops = w.dropList()
    if not drops or #drops == 0 then return {} end

    local inv = getNativeInventory()
    local collected = {}
    local seenUids = {}

    for i = #drops, 1, -1 do
        local drop = drops[i]
        local uid = drop and (drop.uid or drop)
        if uid and not seenUids[uid] and drop and drop.uid and drop.n and drop.n > 0 and not drop.taking then
            if type(drop.x) == "number" and type(drop.y) == "number" then
                if math.floor(drop.x) == tileX and math.floor(drop.y) == tileY then
                    seenUids[uid] = true
                    local dropId = drop.id
                    local taken = tryPickupDrop(drop, inv)
                    if taken > 0 then
                        collected[dropId] = (collected[dropId] or 0) + taken
                    end
                end
            end
        end
    end
    return collected
end

function Proxy.runCasinoCollect()
    if Proxy.casino.busy then
        Proxy.notify("`4[Casino] Bot sedang berjalan! Tunggu sebentar...``")
        return
    end

    local activeIndices = {}
    for i = 1, 4 do
        if Proxy.casino.positions[i] then
            table.insert(activeIndices, i)
        end
    end

    if #activeIndices == 0 then
        Proxy.notify("`4[Casino] Belum ada posisi yang di-set! Gunakan tombol Set Pos atau /pos1 - /pos4 dulu.``")
        return
    end

    local px, py = getPlayerTilePos()
    local returnPos = (px and py and { x = px, y = py }) or Proxy.casino.hostPos
    if px and py then
        Proxy.casino.hostPos = { x = px, y = py }
    end

    local posData = {}
    local maxBet = 0
    local mainLockId = nil
    local mainLockName = ""
    local allEqual = true
    local firstBet = nil
    local isCurrencyGame = false

    for _, idx in ipairs(activeIndices) do
        local amt, lid, lname, isCurr, breakdown = Proxy.getPositionDrops(Proxy.casino.positions[idx])
        posData[idx] = { amount = amt, lockId = lid, lockName = lname, isCurrency = isCurr, breakdown = breakdown }
        if isCurr then
            isCurrencyGame = true
        end
        if amt > maxBet then
            maxBet = amt
            mainLockId = lid
            mainLockName = lname
        end
        if firstBet == nil then
            firstBet = amt
        elseif amt ~= firstBet then
            allEqual = false
        end
    end

    if maxBet == 0 then
        Proxy.notify("`o[Casino] Tidak ada taruhan yang ditemukan di meja (Pos 1 - 4 kosong).``")
        return
    end

    if not allEqual or firstBet == 0 then
        Proxy.showCasinoWarningBanner(posData, maxBet, mainLockName, activeIndices, isCurrencyGame)
        local details = {}
        for _, idx in ipairs(activeIndices) do
            local d = posData[idx]
            if d.amount < maxBet then
                local diffStr = (isCurrencyGame and Proxy.formatCurrency(maxBet - d.amount)) or tostring(maxBet - d.amount)
                table.insert(details, "Pos " .. idx .. " kurang " .. diffStr)
            end
        end
        Proxy.notify("`4[Casino] Gagal! Taruhan tidak sama: " .. table.concat(details, ", ") .. "!``")
        pcall(function() if Sfx and Sfx.play then Sfx.play("trash") end end)
        return
    end

    local totalPool = maxBet * #activeIndices
    local taxAmt, payoutAmt, totalDisplay, taxDisplay, payoutDisplay

    if isCurrencyGame then
        -- Multi-tier Lock Economy: 1 BGL = 100 DL = 10,000 WL | 1 DL = 100 WL
        local rawTax = totalPool * (Proxy.casino.taxRate / 100)
        taxAmt = math.floor(rawTax)
        payoutAmt = totalPool - taxAmt
        totalDisplay = Proxy.formatCurrency(totalPool)
        taxDisplay = Proxy.formatCurrency(taxAmt)
        payoutDisplay = Proxy.formatCurrency(payoutAmt)
    else
        local rawTax = totalPool * (Proxy.casino.taxRate / 100)
        taxAmt = math.ceil(rawTax)
        payoutAmt = totalPool - taxAmt
        totalDisplay = totalPool .. " " .. mainLockName
        taxDisplay = taxAmt .. " " .. mainLockName
        payoutDisplay = payoutAmt .. " " .. mainLockName
    end

    Proxy.casino.lastGame = {
        isCurrency = isCurrencyGame,
        lockId = mainLockId,
        lockName = mainLockName,
        total = totalPool,
        tax = taxAmt,
        payout = payoutAmt,
        totalWL = isCurrencyGame and totalPool or nil,
        taxWL = isCurrencyGame and taxAmt or nil,
        payoutWL = isCurrencyGame and payoutAmt or nil,
        totalDisplay = totalDisplay,
        taxDisplay = taxDisplay,
        payoutDisplay = payoutDisplay,
    }

    Proxy.showCasinoBanner(totalDisplay, taxDisplay, payoutDisplay, Proxy.casino.taxRate)
    Proxy.notify("`2[Casino] Taruhan sama! Terkumpul: " .. totalDisplay .. " | Tax " .. Proxy.casino.taxRate .. "%: " .. taxDisplay .. " | Hadiah: " .. payoutDisplay .. "``")

    Proxy.casino.busy = true
    for _, idx in ipairs(activeIndices) do
        local pos = Proxy.casino.positions[idx]
        if pos then
            Proxy.casinoGlideTo(pos.x, pos.y)
            task.wait(0.12)
            Proxy.sweepTileDrops(pos.x, pos.y)
        end
    end

    if returnPos then
        Proxy.casinoGlideTo(returnPos.x, returnPos.y)
    end
    Proxy.casino.busy = false

    Proxy.notify("`2[Casino] Selesai sweep! Ketik /w1 - /w4 (atau /win1 - /win" .. #activeIndices .. ") untuk bayar pemenang!``")
    Proxy.updateUI()
end

function Proxy.runCasinoPayout(slotIndex, customAmount)
    Proxy.dismissCasinoBanner()

    if Proxy.casino.busy then
        Proxy.notify("`4[Casino] Bot sedang berjalan! Tunggu sebentar...``")
        return
    end

    local pos = Proxy.casino.positions[slotIndex]
    if not pos then
        Proxy.notify("`4[Casino] Pos " .. slotIndex .. " belum di-set!``")
        return
    end

    local isCurr = true
    if Proxy.casino.lastGame and Proxy.casino.lastGame.isCurrency == false then
        isCurr = false
    end

    local payoutAmt = customAmount or (Proxy.casino.lastGame and (Proxy.casino.lastGame.payoutWL or Proxy.casino.lastGame.payout)) or 0
    if payoutAmt <= 0 then
        Proxy.notify("`4[Casino] Belum ada data taruhan! Validasi taruhan dulu (/tp) atau isi nominal custom.``")
        return
    end

    local px, py = getPlayerTilePos()
    local returnPos = (px and py and { x = px, y = py }) or Proxy.casino.hostPos
    if px and py then
        Proxy.casino.hostPos = { x = px, y = py }
    end

    if isCurr then
        -- Payout Multi-tier Currency (BGL, DL, WL)
        local targetBGL, targetDL, targetWL = Proxy.splitWL(payoutAmt)
        local payoutDisplay = Proxy.formatCurrency(payoutAmt)

        -- Verifikasi total nilai lock di tas mencukupi
        local totalWalletWL = (Proxy.getOwnedCount(7188) * 10000) + (Proxy.getOwnedCount(1796) * 100) + (Proxy.getOwnedCount(242) * 1)
        if totalWalletWL < payoutAmt then
            Proxy.notify("`4[Casino] Gagal! Total lock di tas kurang (" .. Proxy.formatCurrency(totalWalletWL) .. " / " .. payoutDisplay .. ")!``")
            return
        end

        -- Seimbangkan pecahan di tas (pecah BGL->DL, DL->WL, atau kompres WL->DL)
        Proxy.ensureLocksForPayout(targetBGL, targetDL, targetWL)

        Proxy.casino.busy = true
        Proxy.notify("`2[Casino] Mengantar hadiah " .. payoutDisplay .. " ke Pos " .. slotIndex .. "...``")

        Proxy.casinoGlideTo(pos.x, pos.y)
        task.wait(0.12)

        local targetFacing = pos.facing or 1
        local facingBit = (targetFacing == 1) and 1 or 0
        local targetX = pos.x + 0.5
        local targetY = pos.y + 1.0

        if Proxy.onDropFn and debug and debug.setupvalue then
            pcall(debug.setupvalue, Proxy.onDropFn, 2, targetFacing)
        end

        safeSendMove({
            x = targetX,
            y = targetY,
            vx = (targetFacing == 1 and 0.05 or -0.05),
            vy = 0,
            flags = 2 + facingBit,
        })
        task.wait(0.08)

        -- Siapkan daftar drop pecahan target
        local dropsToMake = {}
        if targetBGL > 0 then
            table.insert(dropsToMake, { id = 7188, count = targetBGL, name = "Blue Gem Lock" })
        end
        if targetDL > 0 then
            table.insert(dropsToMake, { id = 1796, count = targetDL, name = "Diamond Lock" })
        end
        if targetWL > 0 then
            table.insert(dropsToMake, { id = 242, count = targetWL, name = "World Lock" })
        end

        -- Eksekusi drop per jenis lock
        for _, item in ipairs(dropsToMake) do
            if Proxy.onDropFn and item.count > 0 then
                local remaining = item.count
                while remaining > 0 do
                    local batch = math.min(remaining, 100)
                    local ok, err = pcall(function() Proxy.onDropFn(item.id, batch) end)
                    remaining = remaining - batch
                    if remaining > 0 then
                        task.wait(0.35)
                    end
                end
                task.wait(0.35)
            end
        end

        task.wait(0.15)

        if returnPos then
            Proxy.casinoGlideTo(returnPos.x, returnPos.y)
        end
        Proxy.casino.busy = false
        Proxy.casino.lastGame = nil

        Proxy.notify("`2[Casino] Sukses! Pemenang Pos " .. slotIndex .. " dibayar " .. payoutDisplay .. "!``")
        Proxy.updateUI()

        task.spawn(function()
            task.wait(0.4)
            pcall(Proxy.autoCompressLocks)
        end)
    else
        -- Fallback: Non-Currency Item Payout
        local lockId = (Proxy.casino.lastGame and Proxy.casino.lastGame.lockId) or 242
        local lockName = (Proxy.casino.lastGame and Proxy.casino.lastGame.lockName) or "Item"

        local owned = Proxy.getOwnedCount(lockId)
        if owned < payoutAmt then
            Proxy.notify("`4[Casino] Gagal! " .. lockName .. " di tas kurang (" .. owned .. "/" .. payoutAmt .. ")!``")
            return
        end

        Proxy.casino.busy = true
        Proxy.notify("`2[Casino] Mengantar hadiah " .. payoutAmt .. " " .. lockName .. " ke Pos " .. slotIndex .. "...``")

        Proxy.casinoGlideTo(pos.x, pos.y)
        task.wait(0.12)

        local targetFacing = pos.facing or 1
        local facingBit = (targetFacing == 1) and 1 or 0
        local targetX = pos.x + 0.5
        local targetY = pos.y + 1.0

        if Proxy.onDropFn and debug and debug.setupvalue then
            pcall(debug.setupvalue, Proxy.onDropFn, 2, targetFacing)
        end

        safeSendMove({
            x = targetX,
            y = targetY,
            vx = (targetFacing == 1 and 0.05 or -0.05),
            vy = 0,
            flags = 2 + facingBit,
        })
        task.wait(0.08)

        if Proxy.onDropFn then
            local remaining = payoutAmt
            while remaining > 0 do
                local batch = math.min(remaining, 100)
                pcall(function() Proxy.onDropFn(lockId, batch) end)
                remaining = remaining - batch
                if remaining > 0 then
                    task.wait(0.35)
                end
            end
        end
        task.wait(0.2)

        if returnPos then
            Proxy.casinoGlideTo(returnPos.x, returnPos.y)
        end
        Proxy.casino.busy = false
        Proxy.casino.lastGame = nil

        Proxy.notify("`2[Casino] Sukses! Pemenang Pos " .. slotIndex .. " dibayar " .. payoutAmt .. " " .. lockName .. "!``")
        Proxy.updateUI()
    end
end
-- Floating Drop & Gem Text on Block Break / Drop Spawn (Strict 1-Grid Tile & Total Ground Accumulation)
local activeTileLabels = {}
local pendingTileUpdates = {}
local gameDropsTable = nil

local function findGameDropsTable()
    if gameDropsTable then return gameDropsTable end
    local w = getNativeWorld and getNativeWorld()
    if w and type(w.dropList) == "function" then
        local drops = w.dropList()
        if drops then
            gameDropsTable = drops
            return drops
        end
    end
    if Net and Net.dropAdded and Net.dropAdded.getListeners then
        for _, fn in ipairs(Net.dropAdded.getListeners()) do
            local ups = debug.getupvalues(fn)
            for _, v in pairs(ups) do
                if type(v) == "table" and type(v.dropList) == "function" then
                    gameDropsTable = v.dropList()
                    return gameDropsTable
                end
            end
        end
    end
    local wr = ReplicatedStorage:FindFirstChild("WorldRemotes")
    local dtr = wr and wr:FindFirstChild("DropTaken")
    if dtr and getconnections then
        local conns = getconnections(dtr.OnClientEvent)
        for _, c in ipairs(conns or {}) do
            local fn = c.Function
            if type(fn) == "function" then
                local ok1, u1 = pcall(debug.getupvalue, fn, 1)
                if ok1 and type(u1) == "table" then
                    gameDropsTable = u1
                    return gameDropsTable
                end
            end
        end
    end
    return nil
end

local function getTotalDropsOnTile(tx, ty, itemId)
    itemId = itemId or 112
    local drops = nil
    local w = getNativeWorld and getNativeWorld()
    if w and type(w.dropList) == "function" then
        drops = w.dropList()
    end
    if not drops then
        drops = gameDropsTable or (findGameDropsTable and findGameDropsTable())
    end
    local total = 0
    local isGemTarget = (itemId == 112)
    if drops then
        for _, drop in ipairs(drops) do
            if type(drop) == "table" and type(drop.x) == "number" and type(drop.y) == "number" then
                local isMatch = (drop.id == itemId) or (isGemTarget and drop.setGem ~= nil)
                if isMatch then
                    if math.floor(drop.x) == tx and math.floor(drop.y) == ty then
                        total = total + (drop.n or 0)
                    end
                end
            end
        end
    end
    return total
end

local function spawnFloatingDropText(tx, ty, itemId, count, duration)
    itemId = itemId or 112
    local key = tx .. "," .. ty .. ":" .. itemId
    if not count or count <= 0 then
        if activeTileLabels[key] and activeTileLabels[key].Parent then
            pcall(function() activeTileLabels[key]:Destroy() end)
            activeTileLabels[key] = nil
        end
        return nil
    end

    local camera, tiles = getCameraAndTiles()
    if not camera or not tiles then return nil end

    if activeTileLabels[key] and activeTileLabels[key].Parent then
        pcall(function() activeTileLabels[key]:Destroy() end)
        activeTileLabels[key] = nil
    end

    duration = duration or 1.4
    local isGem = (itemId == 112)
    local gemChar = utf8.char(0x1F48E)
    local itemName = isGem and "Gems" or (ItemDB and ItemDB[itemId] and ItemDB[itemId].name or "Item")
    local textColor = isGem and Color3.fromRGB(60, 255, 140) or Color3.fromRGB(255, 230, 100)

    local lbl = Instance.new("TextLabel")
    lbl.Name = "FloatDrop_" .. key
    lbl.BackgroundTransparency = 1
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.Size = UDim2.fromOffset(140, 28)
    lbl.Position = UDim2.fromOffset((tx + 0.5) * 64, (ty + 0.5) * 64)
    lbl.Font = Enum.Font.FredokaOne
    lbl.TextSize = isGem and 18 or 15
    lbl.TextColor3 = textColor
    lbl.Text = tostring(count) .. " " .. (isGem and (gemChar .. " Gems") or itemName)
    lbl.ZIndex = 50000
    lbl.Parent = tiles
    activeTileLabels[key] = lbl

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(0, 0, 0)
    stroke.Thickness = 2.5
    stroke.Parent = lbl

    local scaleComp = Instance.new("UIScale")
    scaleComp.Scale = 0.65
    scaleComp.Parent = lbl

    -- Animasi pop OUT (zoom outward) bukan UP, posisi tetap ngepass di tile
    local popTween = TweenService:Create(scaleComp, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1.25 })
    popTween:Play()

    -- Hold duration, then smoothly fade out
    local holdTime = math.max(0.1, duration - 0.45)
    task.delay(holdTime, function()
        if activeTileLabels[key] ~= lbl or not lbl.Parent then return end
        local fadeOut = TweenService:Create(lbl, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { TextTransparency = 1 })
        local strokeFade = TweenService:Create(stroke, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Transparency = 1 })
        local scaleOut = TweenService:Create(scaleComp, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = 1.45 })
        fadeOut:Play()
        strokeFade:Play()
        scaleOut:Play()
        task.delay(0.42, function()
            if activeTileLabels[key] == lbl then
                activeTileLabels[key] = nil
            end
            pcall(function() lbl:Destroy() end)
        end)
    end)

    return lbl
end

Proxy._tileGemTotals = Proxy._tileGemTotals or {}

local function handleTileDropUpdate(tx, ty, itemId, fallbackCount, dropperName, dropperUserId)
    local key = tx .. "," .. ty .. ":" .. itemId
    local tileKey = tx .. "," .. ty

    if itemId == 112 then
        if pendingTileUpdates[key] then
            if dropperName and not pendingTileUpdates[key].dropperName then
                pendingTileUpdates[key].dropperName = dropperName
                pendingTileUpdates[key].dropperUserId = dropperUserId
            end
            return
        end

        pendingTileUpdates[key] = {
            dropperName = dropperName,
            dropperUserId = dropperUserId,
        }

        task.delay(0.08, function()
            local data = pendingTileUpdates[key]
            pendingTileUpdates[key] = nil

            local currentTotal = getTotalDropsOnTile(tx, ty, 112)
            local prevTotal = Proxy._tileGemTotals[tileKey] or 0

            if currentTotal <= 0 then
                Proxy._tileGemTotals[tileKey] = 0
                if activeTileLabels[key] and activeTileLabels[key].Parent then
                    pcall(function() activeTileLabels[key]:Destroy() end)
                    activeTileLabels[key] = nil
                end
                return
            end

            Proxy._tileGemTotals[tileKey] = currentTotal
            spawnFloatingDropText(tx, ty, 112, currentTotal)

            if currentTotal > prevTotal then
                local delta = currentTotal - prevTotal
                local dName = (data and data.dropperName) or "[World/Break]"
                local dUid = data and data.dropperUserId

                local desc
                if currentTotal > delta then
                    desc = string.format("%s drop %d Gems di (%d, %d) (Total: %d Gems)", dName, delta, tx + 1, ty + 1, currentTotal)
                else
                    desc = string.format("%s drop %d Gems di (%d, %d)", dName, delta, tx + 1, ty + 1)
                end

                Proxy.addLog("DROP", dName, desc, "Gems", delta, tx + 1, ty + 1, dUid, 112)
            end
        end)
        return
    end

    if pendingTileUpdates[key] then
        pendingTileUpdates[key].count = (pendingTileUpdates[key].count or 0) + (fallbackCount or 1)
        return
    end
    pendingTileUpdates[key] = { count = fallbackCount or 1 }

    task.delay(0.08, function()
        local data = pendingTileUpdates[key]
        pendingTileUpdates[key] = nil
        local total = getTotalDropsOnTile(tx, ty, itemId)
        if total <= 0 and data then
            total = data.count
        end
        if total > 0 then
            spawnFloatingDropText(tx, ty, itemId, total)
        else
            if activeTileLabels[key] and activeTileLabels[key].Parent then
                pcall(function() activeTileLabels[key]:Destroy() end)
                activeTileLabels[key] = nil
            end
        end
    end)
end

Proxy.findGameDropsTable = findGameDropsTable
Proxy.getTotalDropsOnTile = getTotalDropsOnTile
Proxy.spawnFloatingDropText = spawnFloatingDropText
Proxy.handleTileDropUpdate = handleTileDropUpdate
Proxy.activeTileLabels = activeTileLabels

--------------------------------------------------------------------------------
-- FAST ROULETTE & REAL/FAKE ROLL DETECTOR SYSTEM (NATIVE BUBBLE & NAMETAG)
--------------------------------------------------------------------------------
Proxy._fastSpunEntries = Proxy._fastSpunEntries or {}
Proxy._lastPlayerSpinNumbers = Proxy._lastPlayerSpinNumbers or {}
Proxy._nativeShowBubble = nil

-- Hitung Angka Reme = digit terakhir dari jumlah digit (0..9)
-- contoh: 0 = 0, 10 = 1, 19 = 0 (1+9=10), 28 = 0 (2+8=10), 29 = 1 (2+9=11), 36 = 9
function Proxy.calcReme(n)
    n = math.floor(math.abs(tonumber(n) or 0))
    local sum = 0
    while n > 0 do
        sum = sum + (n % 10)
        n = math.floor(n / 10)
    end
    return sum % 10
end

-- Format SATU baris pesan Roulette: [REAL]/[FAKE] di depan, REME : <angka> di belakang
function Proxy.formatRouletteLine(line, tag)
    if type(line) ~= "string" or line == "" then return line end
    local clean = line:gsub("`%w", ""):gsub("``", ""):lower()
    if not (clean:find("spun the wheel", 1, true) or clean:find("memutar roulette", 1, true)) then
        return line
    end
    local num = tonumber(clean:match("spun the wheel and got%s*(%d+)"))
        or tonumber(clean:match("spun the wheel and got.-(%d+)"))
        or tonumber(clean:match("memutar roulette.-(%d+)"))
    if num and num >= 65535 then num = nil end -- 65535 = penanda "masih muter", bukan hasil

    -- 1. Tambah REME di belakang jika belum ada
    if num ~= nil and not line:find("REME%s*:") then
        line = string.format("%s `eREME : %d``", line, Proxy.calcReme(num))
    end

    -- 2. Tambah REAL / FAKE di depan jika belum ada
    if not line:find("%[REAL%]") and not line:find("%[FAKE%]") then
        if tag == "FAKE" then
            line = "`4[FAKE]`` " .. line
        else
            line = "`2[REAL]`` " .. line
        end
    end
    return line
end

-- Bubble game menggabungkan beberapa pesan jadi SATU teks multi-baris (dipisah "``\n").
-- Versi lama memformat teks gabungan itu sekaligus: angka spin pertama yang diambil,
-- REME-nya ditempel di ujung (baris ke-2), dan [REAL] cuma sekali di depan. Sekarang per baris.
function Proxy.formatRouletteText(text, tag)
    if type(text) ~= "string" or text == "" then return text end
    local low = text:lower()
    if not (low:find("wheel", 1, true) or low:find("roulette", 1, true)) then
        return text
    end
    if not text:find("\n", 1, true) then
        return Proxy.formatRouletteLine(text, tag)
    end
    local out = {}
    for line in (text .. "\n"):gmatch("(.-)\n") do
        out[#out + 1] = Proxy.formatRouletteLine(line, tag)
    end
    return table.concat(out, "\n")
end

-- Frame NameTag lokal. Nama Instance-nya diacak game (NvKx0ms4BpR.of("NameTag")), jadi
-- FindFirstChild("NameTag") tidak pernah ketemu -> angka spin tidak muncul di nama kita.
-- Game: LocalPlayer.AttributeChanged -> drawTagName (upvalue), dan drawTagName punya upvalue
-- objek BitmapText tag (u1537) dengan .redraw == drawTagName dan .frame.Parent = frame NameTag.
-- Sengaja TIDAK pakai filtergc di sini (scan GC berat & bisa nge-freeze client).
function Proxy.getLocalNameTagFrame()
    local cached = Proxy._localNameTagFrame
    if cached and cached.Parent then return cached end
    Proxy._localNameTagFrame = nil
    local now = os.clock()
    if Proxy._localNameTagScanAt and (now - Proxy._localNameTagScanAt) < 10 then
        return nil
    end
    Proxy._localNameTagScanAt = now
    local found = nil
    local lp = Players.LocalPlayer
    if lp and getconnections and debug and debug.getupvalues then
        local okC, conns = pcall(getconnections, lp.AttributeChanged)
        for _, c in ipairs((okC and conns) or {}) do
            local fn = c.Function
            if type(fn) == "function" and not (iscclosure and iscclosure(fn)) then
                local okU, ups = pcall(debug.getupvalues, fn)
                for _, uv in pairs((okU and ups) or {}) do
                    if type(uv) == "function" and not (iscclosure and iscclosure(uv)) then
                        local okU2, ups2 = pcall(debug.getupvalues, uv)
                        for _, obj in pairs((okU2 and ups2) or {}) do
                            if type(obj) == "table" and rawget(obj, "redraw") == uv then
                                local f = rawget(obj, "frame")
                                if f == nil then
                                    local okF, v = pcall(function() return obj.frame end)
                                    f = okF and v or nil
                                end
                                if typeof(f) == "Instance" and f.Parent and f.Parent:IsA("GuiObject") then
                                    found = f.Parent
                                    break
                                end
                            end
                        end
                    end
                    if found then break end
                end
            end
            if found then break end
        end
    end
    if not found then
        pcall(function()
            local pgui = lp and lp:FindFirstChildOfClass("PlayerGui")
            found = pgui and pgui:FindFirstChild("NameTag", true) or nil
        end)
    end
    Proxy._localNameTagFrame = found
    return found
end

-- Update spin number next to player's name above their head: e.g. putra [36]
function Proxy.updateNameTagSpinNumber(userId, name, num)
    if type(num) ~= "number" or num >= 65535 then return end
    local numText = string.format("[%d]", num)
    local numColor = (num == 0 and Color3.fromRGB(60, 255, 140)) or (num <= 18 and Color3.fromRGB(75, 230, 255)) or Color3.fromRGB(255, 80, 80)

    local function attachLabel(tagFrame)
        if not tagFrame or not tagFrame.Parent then return end
        local lbl = tagFrame:FindFirstChild("SyshubSpinLbl")
        if not lbl then
            lbl = Instance.new("TextLabel")
            lbl.Name = "SyshubSpinLbl"
            lbl.AnchorPoint = Vector2.new(0, 0.5)
            lbl.Position = UDim2.new(1, 4, 0.5, 0)
            lbl.Size = UDim2.fromOffset(50, 20)
            lbl.BackgroundTransparency = 1
            lbl.Font = Enum.Font.FredokaOne
            lbl.TextSize = 15
            lbl.TextXAlignment = Enum.TextXAlignment.Left
            lbl.ZIndex = 10005
            local stroke = Instance.new("UIStroke", lbl)
            stroke.Thickness = 1.5
            stroke.Color = Color3.fromRGB(0, 0, 0)
            lbl.Parent = tagFrame
        end
        -- Geser ke kanan ikon yang nempel di kanan nama (mis. ikon Wrench di nametag lokal)
        local extra = 4
        local fw = tagFrame.Size.X.Offset
        for _, ch in ipairs(tagFrame:GetChildren()) do
            if ch ~= lbl and ch:IsA("GuiObject") and ch.Visible and ch.Position.X.Scale == 0 and ch.Position.X.Offset >= fw - 2 then
                extra = math.max(extra, ch.Position.X.Offset + ch.Size.X.Offset - fw + 4)
            end
        end
        lbl.Position = UDim2.new(1, extra, 0.5, 0)
        lbl.Text = numText
        lbl.TextColor3 = numColor
        lbl.Visible = true
    end

    -- 1. Others nametag
    local oTable = Proxy._othersPlayerTableRef
    if oTable then
        for _, p in pairs(oTable) do
            if type(p) == "table" and p.tag and p.tag.Parent then
                if (userId and p.userId == userId) or (name and p.name and p.name:lower() == name:lower()) then
                    pcall(attachLabel, p.tag)
                end
            end
        end
    end

    -- 2. Local player nametag
    local isLocal = false
    local lp = Players.LocalPlayer
    if userId and lp and tonumber(userId) == lp.UserId then
        isLocal = true
    elseif name and lp then
        local lname = name:lower()
        local nick = Proxy.getNick and Proxy.getNick()
        if lname == getLocalNativeName():lower() or lname == lp.Name:lower() or (nick and lname == nick:lower()) then
            isLocal = true
        end
    end
    if isLocal then
        local tagFrame = Proxy.getLocalNameTagFrame and Proxy.getLocalNameTagFrame()
        if tagFrame then
            pcall(attachLabel, tagFrame)
        end
    end
end

-- Server WheelSpun handler: Instant native Fast Roulette acceleration & sync
-- Tabel "wheel yang lagi muter" milik game ({x,y,id,ends,n,name,userId} per tile).
-- Versi game sekarang: listener WheelSpun lewat Net/ByteNet (w.on), bukan RemoteEvent,
-- jadi cari closure-nya dari konstanta. Dipanggil sekali (hasil di-cache).
function Proxy.findWheelsTable()
    if Proxy._activeWheelsTable then return Proxy._activeWheelsTable end
    if Proxy._wheelTblGcScanned or not filtergc then return nil end
    Proxy._wheelTblGcScanned = true
    pcall(function()
        local fn = filtergc("function", { Constants = { "rollTime", "wheel", "click" } }, true)
        if type(fn) == "table" then fn = fn[1] end
        if type(fn) ~= "function" then return end
        for _, uv in pairs(debug.getupvalues(fn)) do
            -- skip: world (fg), ItemDB (punya metatable), Sfx (playAt)
            if type(uv) == "table" and getmetatable(uv) == nil and rawget(uv, "fg") == nil
                and rawget(uv, "playAt") == nil and rawget(uv, "play") == nil then
                local _, first = next(uv)
                if first == nil or (type(first) == "table" and rawget(first, "ends") ~= nil) then
                    Proxy._activeWheelsTable = uv
                    break
                end
            end
        end
    end)
    return Proxy._activeWheelsTable
end

function Proxy.handleServerWheelSpun(tx, ty, n, playerName, userId)
    -- Server kirim WheelSpun 2x: n=65535 saat mulai muter (game cuma mulai animasi),
    -- lalu n=hasil asli. Yang 65535 jangan dicatat/ditampilkan.
    if type(n) ~= "number" or n >= 65535 then return end
    local sUid = tostring(userId or 0)
    local pName = playerName or "Player"
    local spinData = {
        n = n,
        name = pName,
        userId = userId,
        x = tx,
        y = ty,
        clock = os.clock(),
    }
    _G.SyshubWheelSpins = _G.SyshubWheelSpins or {}
    _G.SyshubWheelSpins["__last"] = spinData
    _G.SyshubWheelSpins[sUid] = spinData
    _G.SyshubWheelSpins[pName:lower()] = spinData
    _G.SyshubWheelSpins["num_" .. tostring(n)] = spinData
    _G.SyshubWheelSpins[pName:lower() .. "_" .. tostring(n)] = spinData

    Proxy._lastRealSpin = spinData
    Proxy._userRealSpins[sUid] = spinData
    table.insert(Proxy.realSpinHistory, 1, spinData)
    if #Proxy.realSpinHistory > 50 then
        table.remove(Proxy.realSpinHistory)
    end

    -- 1. Display number next to player's name above their head (e.g. putra [36])
    Proxy._lastPlayerSpinNumbers = Proxy._lastPlayerSpinNumbers or {}
    Proxy._lastPlayerSpinNumbers[sUid] = n
    Proxy._lastPlayerSpinNumbers[pName:lower()] = n
    Proxy.updateNameTagSpinNumber(userId, pName, n)

    -- 2. Add roulette entry to activity logs (/logs) matching exact game format + Reme
    task.spawn(function()
        local remeVal = Proxy.calcReme(n)
        local formatted = string.format("[REAL] [%s spun the wheel and got %d!] REME : %d", pName, n, remeVal)
        Proxy.addLog("ROULETTE", pName, formatted, "Roulette", n, (tx or 0) + 1, (ty or 0) + 1, userId, 758)
    end)

    -- 3. Fast Roulette: Fast-forward the native game's spin timer to 0 so the native game triggers
    -- exactly 1 instant speech bubble and 1 chat line with zero manual duplicates!
    if Proxy.fastRoulette then
        local function accelerate()
            local tbl = Proxy._activeWheelsTable
            if not tbl then
                local ws = (ReplicatedStorage:FindFirstChild("WorldRemotes") and ReplicatedStorage.WorldRemotes:FindFirstChild("WheelSpun"))
                if ws and getconnections then
                    for _, c in ipairs(getconnections(ws.OnClientEvent) or {}) do
                        if type(c.Function) == "function" then
                            local ups = debug.getupvalues(c.Function)
                            if #ups == 5 and type(ups[3]) == "table" and type(ups[2]) == "table" then
                                Proxy._activeWheelsTable = ups[3]
                                tbl = ups[3]
                                break
                            end
                        end
                    end
                end
            end

            if not tbl and Proxy.findWheelsTable then
                tbl = Proxy.findWheelsTable()
            end

            if tbl then
                for idx, entry in pairs(tbl) do
                    if type(entry) == "table" then
                        entry.ends = 0
                    end
                end
            end
        end

        accelerate()
        task.defer(accelerate)
    end

    pcall(Proxy.updateUI)
end

--------------------------------------------------------------------------------
-- CLIENT-ONLY ANTIGRAVITY (/ag)
-- Bedrock tepat di bawah Main Door diganti (lokal) jadi Antigravity Generator (4992) + switch ON.
-- Game cek gravitasi tiap frame: w.antiGravOn = w.jammerOn(4992), yaitu ada w.switches[y*w+x]
-- dengan .off == true DAN w.fg[y][x] == 4992. Dua-duanya di-set di client saja.
--------------------------------------------------------------------------------
do -- (dibungkus do-block supaya tidak menambah local di main chunk)
Proxy.clientAG = Proxy.clientAG or { wanted = false, active = false }
local AG_ITEM_ID, AG_BEDROCK_ID, AG_MAIN_DOOR_ID = 4992, 8, 6

function Proxy.findMainDoor(w)
    w = w or (getNativeWorld and getNativeWorld())
    if not w or type(w.fg) ~= "table" then return nil end
    local W, H = tonumber(w.w) or 100, tonumber(w.h) or 60
    for y = 0, H - 1 do
        local row = w.fg[y]
        if row then
            for x = 0, W - 1 do
                if row[x] == AG_MAIN_DOOR_ID then
                    return x, y
                end
            end
        end
    end
    return nil
end

local function agSwitchOn(w, x, y)
    local sw = w.switches and w.switches[y * w.w + x]
    return sw ~= nil and sw.off == true
end

function Proxy.enableClientAG(silent)
    local st = Proxy.clientAG
    local w = getNativeWorld and getNativeWorld()
    if not w or type(w.fg) ~= "table" or not tonumber(w.w) or type(w.switches) ~= "table" then
        if not silent then Proxy.notify("`4[AG] World belum siap / kamu belum di dalam world!``") end
        return false
    end
    local dx, dy = Proxy.findMainDoor(w)
    if not dx then
        if not silent then Proxy.notify("`4[AG] Main Door tidak ditemukan di world ini!``") end
        return false
    end
    local ax, ay = dx, dy + 1
    local cur = w.fg[ay] and w.fg[ay][ax]
    if cur ~= AG_BEDROCK_ID and cur ~= AG_ITEM_ID then
        if not silent then
            Proxy.notify(string.format("`4[AG] Tile di bawah Main Door (%d, %d) bukan Bedrock (id %s), dibatalkan.``", ax + 1, ay + 1, tostring(cur)))
        end
        return false
    end

    st.active, st.world, st.x, st.y = true, w.name, ax, ay
    st.orig = AG_BEDROCK_ID
    _G.SysHubClientAGActive = true

    if cur ~= AG_ITEM_ID then
        forceClientTileUpdate("fg", ax, ay, AG_ITEM_ID)
    end
    if not agSwitchOn(w, ax, ay) then
        -- applySwitch = jalur native (tampil pesan "Antigravity generator enabled" + flag redraw)
        if not silent and type(w.applySwitch) == "function" then
            pcall(w.applySwitch, ax, ay, true, false)
        end
        if not agSwitchOn(w, ax, ay) then
            w.switches[ay * w.w + ax] = { off = true, public = false }
        end
    end
    if not silent then
        Proxy.notify(string.format("`2[AG] Antigravity CLIENT aktif di bawah Main Door (%d, %d)! Ketik /ag lagi untuk mematikan.``", ax + 1, ay + 1))
    end
    return true
end

function Proxy.disableClientAG(silent)
    local st = Proxy.clientAG
    local w = getNativeWorld and getNativeWorld()
    if st.active and w and w.name == st.world and st.x and type(w.fg) == "table" and tonumber(w.w) then
        local idx = st.y * w.w + st.x
        if w.switches and w.switches[idx] then
            if not silent and type(w.applySwitch) == "function" then
                pcall(w.applySwitch, st.x, st.y, false, false)
            end
            w.switches[idx] = nil
        end
        local cur = w.fg[st.y] and w.fg[st.y][st.x]
        if cur == AG_ITEM_ID then
            forceClientTileUpdate("fg", st.x, st.y, st.orig or AG_BEDROCK_ID)
        end
    end
    st.active = false
    _G.SysHubClientAGActive = false
    if not silent then
        Proxy.notify("`4[AG] Antigravity CLIENT dimatikan, gravitasi normal lagi.``")
    end
end

-- Jaga AG tetap terpasang: pasang ulang saat pindah/masuk ulang world atau tile di-reset game
local function agStartWatch()
    local st = Proxy.clientAG
    if st._watching then return end
    st._watching = true
    task.spawn(function()
        while st.wanted and Proxy.clientAG == st do
            task.wait(1)
            pcall(function()
                local w = getNativeWorld and getNativeWorld()
                if not (w and w.name and w.name ~= "" and type(w.fg) == "table" and tonumber(w.w)) then return end
                if st.world ~= w.name then
                    st.active = false
                end
                local intact = st.active and st.x and w.fg[st.y] and w.fg[st.y][st.x] == AG_ITEM_ID and agSwitchOn(w, st.x, st.y)
                if intact then return end
                if st.active and st.world == w.name then
                    Proxy.enableClientAG(true)
                elseif st.failedWorld ~= w.name then
                    if Proxy.enableClientAG(false) then
                        st.failedWorld = nil
                    else
                        st.failedWorld = w.name
                    end
                end
            end)
        end
        st._watching = false
    end)
end

function Proxy.toggleClientAG()
    local st = Proxy.clientAG
    if st.wanted then
        st.wanted = false
        Proxy.disableClientAG(false)
        return false
    end
    st.wanted = true
    st.failedWorld = nil
    if Proxy.enableClientAG(false) then
        agStartWatch()
        return true
    end
    st.wanted = false
    return false
end
end -- do (CLIENT-ONLY ANTIGRAVITY)

--------------------------------------------------------------------------------
-- PROXY WORLD ACTIVITY LOGS SYSTEM (/logs)
--------------------------------------------------------------------------------
local _itemNameCache = nil
function Proxy.getItemId(nameOrId)
    if type(nameOrId) == "number" and nameOrId > 0 then return nameOrId end
    if type(nameOrId) ~= "string" or nameOrId == "" then return nil end
    local cleanName = nameOrId:gsub("`%w", ""):gsub("``", ""):gsub("^%s*(.-)%s*$", "%1")
    local low = cleanName:lower()

    if low == "gems" or low:find("gem", 1, true) then return 112 end
    if low == "roulette" or low:find("roulette", 1, true) then return 758 end
    if low == "main door" or low == "door" or low:find("door", 1, true) then return 6 end
    if low == "world lock" or low == "wl" then return 242 end
    if low == "diamond lock" or low == "dl" then return 1796 end
    if low == "blue gem lock" or low == "bgl" then return 7188 end
    if low == "small lock" or low == "sl" then return 202 end
    if low == "big lock" or low == "bl" then return 204 end
    if low == "huge lock" or low == "hl" then return 206 end

    local num = cleanName:match("Item #(%d+)") or cleanName:match("^(%d+)$")
    if num then return tonumber(num) end

    if Proxy.LOCK_NAMES then
        for id, lName in pairs(Proxy.LOCK_NAMES) do
            if lName:lower() == low then return id end
        end
    end

    if not _itemNameCache and ItemDB then
        _itemNameCache = {}
    end
    if _itemNameCache and _itemNameCache[low] then
        return _itemNameCache[low]
    end

    if ItemDB then
        for id, v in pairs(ItemDB) do
            if type(v) == "table" and v.name and v.name:lower() == low then
                if _itemNameCache then _itemNameCache[low] = id end
                return id
            end
        end
    end

    return nil
end

function Proxy.addLog(kind, player, text, item, count, x, y, userId, itemId)
    if not Proxy.logsData or not Proxy.logsData.list then return end

    if not itemId or itemId == 0 then
        if kind == "ENTER" or kind == "EXIT" then
            itemId = 6
        elseif kind == "ROULETTE" then
            itemId = 758
        elseif item == "Gems" or (text and text:find("Gems", 1, true)) then
            itemId = 112
        elseif Proxy.getItemId then
            itemId = Proxy.getItemId(item)
        end
    end

    local entry = {
        id = #Proxy.logsData.list + 1,
        timestamp = os.date("%H:%M:%S"),
        kind = kind or "INFO",
        player = player or "Unknown",
        userId = userId,
        item = item,
        itemId = itemId,
        count = count,
        x = x,
        y = y,
        text = text or "",
        _clock = os.clock(),
    }

    table.insert(Proxy.logsData.list, 1, entry)
    if #Proxy.logsData.list > (Proxy.logsData.maxEntries or 500) then
        table.remove(Proxy.logsData.list)
    end

    if Proxy.refreshLogsUI and Proxy.logsDialog and Proxy.logsDialog.Visible then
        Proxy.refreshLogsUI()
    end
end

function Proxy.clearLogs()
    if Proxy.logsData then
        Proxy.logsData.list = {}
    end
    Proxy._tileGemTotals = {}
    if Proxy.refreshLogsUI then
        Proxy.refreshLogsUI()
    end
    Proxy.notify("`2[Logs] Seluruh riwayat activity logs berhasil dibersihkan!``")
end

function Proxy.createLogsDialog()
    if Proxy.logsDialog and Proxy.logsDialog.Parent then
        return Proxy.logsDialog
    end

    local dialog = Instance.new("Frame")
    dialog.Name = "ProxyLogsDialog"
    dialog.Size = UDim2.fromOffset(560, 500)
    dialog.Position = UDim2.fromScale(0.5, 0.5)
    dialog.AnchorPoint = Vector2.new(0.5, 0.5)
    dialog.BackgroundColor3 = C.box
    dialog.BorderSizePixel = 0
    dialog.Visible = false
    dialog.ZIndex = 60
    dialog.Parent = SG
    corner(dialog, 6)
    dialogBorder(dialog)

    local uiScale = Instance.new("UIScale", dialog)
    uiScale.Scale = 1

    -- Header (Draggable)
    local header = Instance.new("Frame", dialog)
    header.Name = "Header"
    header.Size = UDim2.new(1, 0, 0, 52)
    header.BackgroundTransparency = 1
    header.BorderSizePixel = 0

    local dragging = false
    local dragStart = nil
    local startPos = nil

    header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = dialog.Position
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            dialog.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    -- Header Icon
    local iconFrame = Instance.new("Frame", header)
    iconFrame.Size = UDim2.fromOffset(38, 38)
    iconFrame.Position = UDim2.fromOffset(12, 7)
    iconFrame.BackgroundColor3 = C.dark
    iconFrame.BackgroundTransparency = 0.35
    iconFrame.BorderSizePixel = 0
    corner(iconFrame, 6)
