    btnLogsScale.Size = UDim2.fromOffset(80, 26)
    btnLogsScale.Position = UDim2.new(1, -125, 0, 13)
    btnLogsScale.BackgroundColor3 = C.dark
    btnLogsScale.BorderSizePixel = 0
    btnLogsScale.Text = "Scale"
    btnLogsScale.TextColor3 = C.cyan
    btnLogsScale.Font = Enum.Font.GothamBold
    btnLogsScale.TextSize = 12
    btnLogsScale.ZIndex = 65
