        end)

        tabBtns[def.id] = { btn = tBtn, lbl = tLbl }
    end
    updateTabStyles()

    -- Search & Action Bar
    local searchBar = Instance.new("Frame", dialog)
    searchBar.Name = "SearchBar"
    searchBar.Size = UDim2.new(1, -24, 0, 32)
    searchBar.Position = UDim2.fromOffset(12, 118)
    searchBar.BackgroundTransparency = 1

    -- Search Box Frame
    local searchBoxFrame = Instance.new("Frame", searchBar)
    searchBoxFrame.Size = UDim2.new(0.68, -4, 1, 0)
    searchBoxFrame.BackgroundColor3 = C.dark
    searchBoxFrame.BackgroundTransparency = 0.35
    searchBoxFrame.BorderSizePixel = 0
    corner(searchBoxFrame, 5)
    stroke(searchBoxFrame, C.fieldRim, 1)

    local searchBox = Instance.new("TextBox", searchBoxFrame)
    searchBox.Size = UDim2.new(1, -30, 1, 0)
    searchBox.Position = UDim2.fromOffset(8, 0)
    searchBox.BackgroundTransparency = 1
    searchBox.PlaceholderText = "Search Player / Item / Text..."
    searchBox.PlaceholderColor3 = C.placeholder
    searchBox.Text = Proxy.logsData.searchQuery or ""
