function Proxy.refreshLogsUI()
    if not Proxy._uiLogsRefs or not Proxy.logsDialog or not Proxy.logsDialog.Visible then
        return
    end

    local r = Proxy._uiLogsRefs
    local scroll = r.scroll
    local tab = Proxy.logsData.activeTab
    local subFilter = Proxy.logsData.subFilter or "all"
    local query = (Proxy.logsData.searchQuery or ""):lower():gsub("^%s*(.-)%s*$", "%1")

    -- Filter list
    local filtered = {}
    for _, entry in ipairs(Proxy.logsData.list) do
        local tabMatch = false
        if tab == "all" then
            tabMatch = true
        elseif tab == "drop" and entry.kind == "DROP" then
            tabMatch = true
        elseif tab == "collect" and entry.kind == "COLLECT" then
            tabMatch = true
        elseif tab == "enter_exit" and (entry.kind == "ENTER" or entry.kind == "EXIT") then
            tabMatch = true
        elseif tab == "roulette" and entry.kind == "ROULETTE" then
            tabMatch = true
        end

        local subMatch = true
        if tab ~= "enter_exit" and tab ~= "roulette" and subFilter ~= "all" then
            local isGem = (entry.item == "Gems") or (entry.text and entry.text:find("Gems", 1, true) ~= nil)
            local isLock = false
            if entry.item then
                local iLow = entry.item:lower()
                if iLow:find("lock", 1, true) then isLock = true end
            end
            if entry.text and entry.text:lower():find("lock", 1, true) then
                isLock = true
            end

            if subFilter == "gems" then
                subMatch = isGem
            elseif subFilter == "locks" then
                subMatch = isLock
            end
        end

        if tabMatch and subMatch then
            if query == "" then
                table.insert(filtered, entry)
            else
                local pStr = (Proxy.applyNick and Proxy.applyNick(entry.player or "") or (entry.player or "")):lower()
                local tStr = (Proxy.applyNick and Proxy.applyNick(entry.text or "") or (entry.text or "")):lower()
                local iStr = (entry.item or ""):lower()
                if pStr:find(query, 1, true) or tStr:find(query, 1, true) or iStr:find(query, 1, true) then
                    table.insert(filtered, entry)
                end
            end
        end
    end

    local filterDesc = subFilter == "all" and "SEMUA" or (subFilter == "gems" and "GEMS ONLY" or "LOCK ONLY")
    r.lblCount.Text = string.format("Menampilkan %d dari %d logs (Tab: %s | Filter: %s)", #filtered, #Proxy.logsData.list, tab:upper(), filterDesc)

    -- Clear previous items (Frames and empty TextLabels, keeping layout helpers)
    for _, child in ipairs(scroll:GetChildren()) do
        if child:IsA("GuiObject") and not child:IsA("UIPadding") and not child:IsA("UIListLayout") then
            child:Destroy()
        end
    end

    -- Render top 60 recent entries
    local maxDisplay = math.min(#filtered, 60)
    for i = 1, maxDisplay do
        local item = filtered[i]
        local row = Instance.new("Frame", scroll)
        row.Name = "LogRow_" .. tostring(item.id)
        row.Size = UDim2.new(1, 0, 0, 34)
        row.BackgroundColor3 = C.field
        row.BackgroundTransparency = 0.65
        row.BorderSizePixel = 0
        corner(row, 4)

        -- 1. Timestamp (di sebelah kiri, menggantikan badge teks lama)
        local lblTime = Instance.new("TextLabel", row)
        lblTime.Name = "LblTime"
        lblTime.Size = UDim2.fromOffset(66, 34)
        lblTime.Position = UDim2.fromOffset(6, 0)
        lblTime.BackgroundTransparency = 1
        lblTime.Text = "[" .. (item.timestamp or "") .. "]"
        lblTime.TextColor3 = Color3.fromRGB(240, 245, 250)
        lblTime.Font = Enum.Font.GothamBold
        lblTime.TextSize = 12
        lblTime.TextXAlignment = Enum.TextXAlignment.Left
        lblTime.TextYAlignment = Enum.TextYAlignment.Center

        -- 2. Item Icon (menggantikan posisi timestamp lama)
        local resolvedId = item.itemId
        if not resolvedId or resolvedId == 0 then
            if item.kind == "ENTER" or item.kind == "EXIT" then
                resolvedId = 6
            elseif item.kind == "ROULETTE" then
                resolvedId = 758
            elseif item.item == "Gems" or (item.text and item.text:find("Gems", 1, true)) then
                resolvedId = 112
            elseif Proxy.getItemId then
                resolvedId = Proxy.getItemId(item.item)
            end
        end
        if not resolvedId or resolvedId == 0 then
            resolvedId = (item.kind == "ENTER" or item.kind == "EXIT") and 6 or (item.kind == "ROULETTE" and 758 or 20)
        end

        local iconContainer = Instance.new("Frame", row)
        iconContainer.Name = "IconContainer"
        iconContainer.Size = UDim2.fromOffset(26, 26)
        iconContainer.Position = UDim2.fromOffset(74, 4)
        iconContainer.BackgroundColor3 = C.dark
        iconContainer.BackgroundTransparency = 0.5
        iconContainer.BorderSizePixel = 0
        iconContainer.ZIndex = 61
        corner(iconContainer, 4)

        if resolvedId and resolvedId > 0 and ItemIcon and ItemIcon.new then
            pcall(function()
                local iconObj = ItemIcon.new(iconContainer, UDim2.fromOffset(26, 26), 62)
                if iconObj and iconObj.frame then
                    iconObj.frame.AnchorPoint = Vector2.new(0.5, 0.5)
                    iconObj.frame.Position = UDim2.fromScale(0.5, 0.5)
                end
                ItemIcon.set(iconObj, resolvedId)
            end)
        end

        -- 3. Player & Action Text (di sebelah item icon)
        local lblDesc = Instance.new("TextLabel", row)
        lblDesc.Name = "LblDesc"
        lblDesc.Size = UDim2.new(1, -112, 1, 0)
        lblDesc.Position = UDim2.fromOffset(106, 0)
        lblDesc.BackgroundTransparency = 1
        lblDesc.TextColor3 = C.white
        lblDesc.Font = Enum.Font.GothamBold
        lblDesc.TextSize = 13
        lblDesc.TextXAlignment = Enum.TextXAlignment.Left
        lblDesc.ClipsDescendants = true
        lblDesc.RichText = true

        local rawDesc = (Proxy.applyNick and Proxy.applyNick(item.text or "") or (item.text or "")):gsub("`%w", ""):gsub("``", "")
        if rawDesc:find("%[REAL%]") then
            rawDesc = rawDesc:gsub("%[REAL%]", '<font color="#38ef7d"><b>[REAL]</b></font>')
        elseif rawDesc:find("%[FAKE%]") then
            rawDesc = rawDesc:gsub("%[FAKE%]", '<font color="#ff4b2b"><b>[FAKE]</b></font>')
        end
        if rawDesc:find("REME%s*:%s*%d+") then
            rawDesc = rawDesc:gsub("(REME%s*:%s*%d+)", '<font color="#ffd200"><b>%1</b></font>')
        end
        lblDesc.Text = rawDesc
    end

    if #filtered == 0 then
        local emptyLbl = Instance.new("TextLabel", scroll)
        emptyLbl.Size = UDim2.new(1, 0, 0, 40)
        emptyLbl.BackgroundTransparency = 1
        emptyLbl.Text = (query ~= "") and "Tidak ada logs yang cocok dengan pencarian." or "Belum ada logs aktivitas di world ini."
        emptyLbl.TextColor3 = C.muted
        emptyLbl.Font = Enum.Font.Gotham
        emptyLbl.TextSize = 13
    end
end

function Proxy.openLogsDialog()
    local dialog = Proxy.createLogsDialog()
    if Sfx and Sfx.play then Sfx.play("dialog_open") end
    dialog.Visible = true
    local targetScale = (getActiveUIScale and getActiveUIScale()) or 1.0
    if Proxy._uiLogsRefs and Proxy._uiLogsRefs.uiScale then
        Proxy._uiLogsRefs.uiScale.Scale = targetScale * 0.85
        TweenService:Create(Proxy._uiLogsRefs.uiScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
            Scale = targetScale
        }):Play()
    end
    if Proxy._uiLogsRefs and Proxy._uiLogsRefs.updateTabStyles then Proxy._uiLogsRefs.updateTabStyles() end
    if Proxy._uiLogsRefs and Proxy._uiLogsRefs.updateSubFilterStyles then Proxy._uiLogsRefs.updateSubFilterStyles() end
    Proxy.refreshLogsUI()
end

function Proxy.closeLogsDialog()
    if Proxy.logsDialog then
        if Sfx and Sfx.play then Sfx.play("dialog_close") end
        Proxy.logsDialog.Visible = false
    end
end

function Proxy.toggleLogsDialog()
    if Proxy.logsDialog and Proxy.logsDialog.Visible then
        Proxy.closeLogsDialog()
    else
        Proxy.openLogsDialog()
    end
end

function Proxy.updateUI()
    if not Proxy._uiRefs then return end
    -- Tab Proxy sekarang dikhususkan sebagai Kamus Command Proxy murni tanpa toggle
end

