                row = row,
                catFrame = catFrame,
                cmdText = cItem.cmd:lower(),
                descText = cItem.desc:lower(),
                catText = cat.title:lower(),
            })
        end
    end

    -- Real-time Search Filter Handler
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        local q = searchBox.Text:lower():gsub("^%s*(.-)%s*$", "%1")
        for _, ref in ipairs(allRowRefs) do
            local visible = true
            if q ~= "" then
                visible = (ref.cmdText:find(q, 1, true) ~= nil)
                    or (ref.descText:find(q, 1, true) ~= nil)
                    or (ref.catText:find(q, 1, true) ~= nil)
            end
            ref.row.Visible = visible
        end
    end)
end

