-- ==============================================================================
--  PROXY BACKGROUND SERVICES, HOOKS & CHAT CONTROLLER
-- ==============================================================================
task.spawn(function()
    local LP = Players.LocalPlayer

    -- 1. Grab native hooks (Cached to avoid heavy GC lag)
    local gcCache = _G._GrowbloxGCCache
    if not gcCache then
        gcCache = {}
        _G._GrowbloxGCCache = gcCache
    end

    if not gcCache.onDropFn then
        pcall(function()
            local fns = filtergc("function", { Constants = {"object_spawn2"} })
            for _, f in ipairs(fns or {}) do
                if debug.info(f, "a") == 2 then
                    gcCache.onDropFn = f
                    break
                end
            end
            if gcCache.onDropFn then
                local ups = debug.getupvalues(gcCache.onDropFn)
                for _, u in ipairs(ups or {}) do
                    if type(u) == "table" and (type(u.count) == "function" or type(u.slots) == "table") then
                        gcCache.invRef = u
                        break
                    end
                end
            end
        end)
    end
    Proxy.onDropFn = gcCache.onDropFn
    Proxy.invRef = gcCache.invRef

    local eng, w = getNativeEngine()
    w = w or (eng and eng.world)
    if eng then
        if not gcCache.dieFn then gcCache.dieFn = eng.die end
        if not gcCache.enterWorldFn then gcCache.enterWorldFn = eng.enterWorld end
        if not gcCache.worldMenuRef then gcCache.worldMenuRef = eng.WorldMenu end
    else
        if not gcCache.dieFn and filtergc then
            pcall(function()
                gcCache.dieFn = filtergc("function", { Constants = {"male_scream"} }, true)
                gcCache.enterWorldFn = filtergc("function", { Name = "enterWorld" }, true)
            end)
        end
        if not gcCache.worldMenuRef and filtergc then
            local wmList = filtergc("table", { Keys = {"openPlayer", "openPicker"} }, false)
            gcCache.worldMenuRef = wmList and wmList[1]
        end
    end
    Proxy.dieFn = gcCache.dieFn
    Proxy.enterWorldFn = function(world, door)
        if warpToWorld then return warpToWorld(world, door) end
        if nativeWarp then return nativeWarp(world) end
        if gcCache.enterWorldFn then return gcCache.enterWorldFn(world) end
    end

    local worldRemotesRef = ReplicatedStorage:FindFirstChild("WorldRemotes") or (eng and eng.WorldRemotes)
    local worldCommandRef = worldRemotesRef and worldRemotesRef:FindFirstChild("WorldCommand")
    local dropAddedRemote = worldRemotesRef and worldRemotesRef:FindFirstChild("DropAdded")
    local dropTakenRemote = worldRemotesRef and worldRemotesRef:FindFirstChild("DropTaken")
    local worldMenuRef = gcCache.worldMenuRef

    -- Load config on startup (Langsung buat config default instan jika akun baru pertama kali execute!)
    local targetCfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or CONFIG_FILE
    if not isfile or (not isfile(targetCfgFile) and not isfile(CONFIG_FILE)) then
        pcall(Proxy.saveConfig)
        print(string.format("[CONFIG] %s berhasil dibuat otomatis saat pertama kali dieksekusi!", targetCfgFile))
    else
        Proxy.loadConfig()
    end

    -- Periodic auto-save every 15s
    task.spawn(function()
        while task.wait(15) do
            pcall(Proxy.saveConfig)
        end
    end)

    -- Auto-save on teleport
    pcall(function()
        local LP = Players.LocalPlayer
        if LP and LP.OnTeleport then
            LP.OnTeleport:Connect(function()
                pcall(Proxy.saveConfig)
            end)
        end
    end)

    -- Auto compress loop (100 WL -> 1 DL, 100 DL -> 1 BGL)
    local autoConvertRunning = true  -- Toggle via /autocv command
    local autoConvertLoopAlive = true  -- Loop tetap hidup, cek autoConvertRunning sebelum execute
    _G.autoConvertRunning = autoConvertRunning
    task.spawn(function()
        while autoConvertLoopAlive do
            task.wait(2.5)
            if autoConvertRunning then
                pcall(Proxy.autoCompressLocks)
            end
        end
    end)

    -- Helper sendWorldCommand (Legit ByteNet RPC pipeline to prevent kick)
    local function sendWorldCommand(cmd, targetArg)
        local w = getNativeWorld and getNativeWorld()
        if w and type(w.call) == "function" then
            local ok, err, res = pcall(w.call, "WorldCommand", cmd, targetArg)
            if ok then return true, err, res end
        end
        if Net and type(Net.call) == "function" then
            local ok, err, res = pcall(Net.call, "WorldCommand", cmd, targetArg)
            if ok then return true, err, res end
        end
        return false
    end

    -- Floating gems text listener (Strict 1-Grid Tile & Total Ground Accumulation)
    local gemFloatConn = nil
    local dropTakenConn = nil

    -- Pre-cache drops table on load
    gameDropsTable = findGameDropsTable()

    -- Extract othersPlayerTable early for logs and wrench (Cached)
    if not gcCache.othersRef then
        local othersList = filtergc("table", { Keys = {"wrenchAt"} }, false)
        gcCache.othersRef = othersList and othersList[1]
    end
    local othersRef = gcCache.othersRef
    local othersPlayerTable = nil
    if othersRef and type(othersRef.wrenchAt) == "function" then
        local ups = debug.getupvalues(othersRef.wrenchAt)
        if ups and type(ups[1]) == "table" then
            othersPlayerTable = ups[1]
            Proxy._othersPlayerTableRef = othersPlayerTable  -- for nametag
        end
    end

    Proxy.othersRef = othersRef

    -- Hook others speech bubbles for Real vs Fake Roulette detection + Reme
    if othersRef and type(othersRef.say) == "function" and not othersRef._rouletteHooked then
        othersRef._rouletteHooked = true
        local origOthersSay = othersRef.say
        othersRef.say = function(uid, text, ...)
            if Proxy.rouletteDetector and type(text) == "string" and Proxy.formatRouletteText then
                text = Proxy.formatRouletteText(text, "REAL")
            end
            if Proxy.applyNick then text = Proxy.applyNick(text) end
            return origOthersSay(uid, text, ...)
        end
    end

    -- Pre-cache existing drops into knownDrops and prime _tileGemTotals
    local function syncExistingDrops()
        local w = getNativeWorld and getNativeWorld()
        local drops = (w and type(w.dropList) == "function" and w.dropList()) or gameDropsTable or findGameDropsTable()
        if drops then
            for _, d in ipairs(drops) do
                if type(d) == "table" and d.uid then
                    if not Proxy.logsData.knownDrops[d.uid] then
                        Proxy.logsData.knownDrops[d.uid] = {
                            uid = d.uid,
                            id = d.id,
                            n = d.n,
                            x = d.x,
                            y = d.y,
                            by = d.by,
                            born = d.born or os.clock()
                        }
                    end
                end
                if type(d) == "table" and d.id == 112 and type(d.x) == "number" and type(d.y) == "number" then
                    local tk = string.format("%d,%d", math.floor(d.x), math.floor(d.y))
                    Proxy._tileGemTotals[tk] = (Proxy._tileGemTotals[tk] or 0) + (d.n or 0)
                end
            end
        end
    end
    task.spawn(syncExistingDrops)

    -- Helper to sync native names from othersPlayerTable
    local function syncOthersNativeNames()
        if othersPlayerTable and Proxy and Proxy.userIdToName then
            for peerId, op in pairs(othersPlayerTable) do
                if type(op) == "table" and op.userId and op.name and op.name ~= "" then
                    Proxy.userIdToName[tostring(op.userId)] = op.name
                end
            end
        end
    end
    task.spawn(syncOthersNativeNames)

    -- 1. Hook local collection calls to track when local player collects drops
    if Net and Net.take and type(Net.take.send) == "function" and not Net.take._logsHooked then
        Net.take._logsHooked = true
        local origTakeSend = Net.take.send
        Net.take.send = function(pkt)
            if type(pkt) == "table" and pkt.uid then
                Proxy.localPendingTakes[pkt.uid] = os.clock()
            end
            return origTakeSend(pkt)
        end
    end

    local function hookWorldTakeDrop()
        local w = getNativeWorld and getNativeWorld()
        if w and type(w.takeDrop) == "function" and not w._logsHooked then
            w._logsHooked = true
            local origTakeDrop = w.takeDrop
            w.takeDrop = function(uid, count)
                if uid then
                    Proxy.localPendingTakes[uid] = os.clock()
                end
                local res = origTakeDrop(uid, count)
                if res and res > 0 then
                    Proxy.localPendingTakes[uid] = os.clock()
                end
                return res
            end
        end
    end
    pcall(hookWorldTakeDrop)

    -- Drop and Collect batching trackers
    Proxy._pendingDropBatches = Proxy._pendingDropBatches or {}
    Proxy._pendingCollectBatches = Proxy._pendingCollectBatches or {}

    -- Continuous Nametag spin numbers keep-alive loop
    task.spawn(function()
        while true do
            task.wait(1.0)
            if Proxy._lastPlayerSpinNumbers then
                for idOrName, n in pairs(Proxy._lastPlayerSpinNumbers) do
                    local uId = tonumber(idOrName)
                    Proxy.updateNameTagSpinNumber(uId, not uId and idOrName, n)
                end
            end
        end
    end)

    -- Robust Multi-Channel Server WheelSpun listener, dedupe per wheel (x,y,n,userId)
    -- (w.on dan Net.wheelSpun.listen menerima paket yang sama, jadi wajib dedupe;
    -- dedupe lama cuma pakai angka, jadi 2 wheel dengan angka sama bisa ketelan)
    local recentSpinKeys = {}
    local function dispatchWheelSpun(x, y, n, name, userId)
        if type(n) ~= "number" or n >= 65535 then return end -- 65535 = baru mulai muter
        local now = os.clock()
        local key = string.format("%s:%s:%d:%s", tostring(x), tostring(y), n, tostring(userId))
        local last = recentSpinKeys[key]
        if last and (now - last) < 0.5 then
            return -- Deduplicate identical network packet
        end
        recentSpinKeys[key] = now
        for k, t in pairs(recentSpinKeys) do
            if (now - t) > 5 then recentSpinKeys[k] = nil end
        end
        syncOthersNativeNames()
        Proxy.handleServerWheelSpun(x, y, n, name, userId)
    end

    -- 1. Hook w.on("WheelSpun")
    local function hookWorldWheelSpun()
        local w = getNativeWorld and getNativeWorld()
        if w and type(w.on) == "function" and not w._syshubWheelSpunHooked then
            w._syshubWheelSpunHooked = true
            w.on("WheelSpun", function(x, y, n, name, userId)
                dispatchWheelSpun(x, y, n, name, userId)
            end)
        end
    end
    hookWorldWheelSpun()
    task.spawn(function()
        while true do
            task.wait(1.5)
            hookWorldWheelSpun()
        end
    end)

    -- 2. Hook Net.wheelSpun.listen
    if Net and Net.wheelSpun and type(Net.wheelSpun.listen) == "function" and not Net.wheelSpun._syshubHooked then
        Net.wheelSpun._syshubHooked = true
        Net.wheelSpun.listen(function(pkt)
            if type(pkt) == "table" and type(pkt.n) == "number" then
                dispatchWheelSpun(pkt.x, pkt.y, pkt.n, pkt.name, pkt.userId)
            end
        end)
    end

    -- 3. Hook wheelSpunRemote.OnClientEvent
    local wheelSpunRemote = worldRemotesRef and worldRemotesRef:FindFirstChild("WheelSpun")
    if _G.SyshubWheelConn then
        pcall(function() _G.SyshubWheelConn:Disconnect() end)
        _G.SyshubWheelConn = nil
    end
    if wheelSpunRemote and wheelSpunRemote:IsA("RemoteEvent") then
        _G.SyshubWheelConn = wheelSpunRemote.OnClientEvent:Connect(function(x, y, n, name, userId)
            dispatchWheelSpun(x, y, n, name, userId)
        end)
    end

    -- Cache active wheels table from native game connection
    pcall(function()
        if wheelSpunRemote and getconnections then
            for _, conn in ipairs(getconnections(wheelSpunRemote.OnClientEvent) or {}) do
                if type(conn.Function) == "function" then
                    local ups = debug.getupvalues(conn.Function)
                    if #ups == 5 and type(ups[3]) == "table" and type(ups[2]) == "table" then
                        Proxy._activeWheelsTable = ups[3]
                        break
                    end
                end
            end
        end
    end)
    -- Fallback (game versi baru: WheelSpun lewat ByteNet, bukan RemoteEvent) - scan di background
    task.spawn(function()
        if not Proxy._activeWheelsTable and Proxy.findWheelsTable then
            Proxy.findWheelsTable()
        end
    end)

    -- 2. ByteNet Net.dropAdded (Instant Auto-Display & Drop Activity Logger)
    if Net and Net.dropAdded and type(Net.dropAdded.listen) == "function" then
        Net.dropAdded.listen(function(pkt)
            if type(pkt) == "table" then
                syncOthersNativeNames()

                local prev = pkt.uid and Proxy.logsData.knownDrops[pkt.uid]
                local count = pkt.n or 1
                local addedCount = count

                if prev then
                    local oldN = prev.n or 0
                    if count > oldN then
                        addedCount = count - oldN
                    else
                        addedCount = 0
                    end
                    prev.n = count
                    prev.x = pkt.x or prev.x
                    prev.y = pkt.y or prev.y
                    prev.id = pkt.id or prev.id
                else
                    if pkt.uid then
                        Proxy.logsData.knownDrops[pkt.uid] = {
                            uid = pkt.uid,
                            id = pkt.id,
                            n = count,
                            x = pkt.x,
                            y = pkt.y,
                            by = pkt.by,
                            born = os.clock()
                        }
                    end
                end

                -- Resolve dropper native name
                local dropperName = nil
                local lpUserId = Players.LocalPlayer and Players.LocalPlayer.UserId
                if lpUserId and pkt.by and tostring(pkt.by) == tostring(lpUserId) then
                    dropperName = getLocalNativeName() .. " (You)"
                elseif pkt.by and pkt.by > 0 then
                    dropperName = getPlayerNativeName(pkt.by)
                else
                    dropperName = "[World/Break]"
                end

                -- Gems handling: Ground-truth tile accumulation and accurate merge/drop delta
                if pkt.id == 112 then
                    if type(pkt.x) == "number" and type(pkt.y) == "number" then
                        handleTileDropUpdate(math.floor(pkt.x), math.floor(pkt.y), 112, addedCount > 0 and addedCount or count, dropperName, pkt.by)
                    end
                    return
                end

                if addedCount <= 0 then
                    return
                end

                local itemName = "Item #" .. tostring(pkt.id)
                if pkt.id == 112 then
                    itemName = "Gems"
                elseif Proxy.LOCK_NAMES[pkt.id] then
                    itemName = Proxy.LOCK_NAMES[pkt.id]
                elseif ItemDB and ItemDB[pkt.id] and ItemDB[pkt.id].name then
                    itemName = ItemDB[pkt.id].name
                end

                local tx = math.floor(pkt.x or 0) + 1
                local ty = math.floor(pkt.y or 0) + 1

                -- Batch simultaneous drops at same tile (e.g. 3 small gems from 1 broken block)
                local batchKey = string.format("%d_%d_%d_%s", tx, ty, pkt.id or 0, tostring(dropperName))
                if Proxy._pendingDropBatches[batchKey] then
                    local b = Proxy._pendingDropBatches[batchKey]
                    b.count = b.count + addedCount
                    b.lastTime = os.clock()
                else
                    local b = {
                        player = dropperName,
                        itemName = itemName,
                        itemId = pkt.id,
                        count = addedCount,
                        x = tx,
                        y = ty,
                        userId = pkt.by,
                        firstTime = os.clock(),
                        lastTime = os.clock(),
                    }
                    Proxy._pendingDropBatches[batchKey] = b

                    task.delay(0.12, function()
                        if Proxy._pendingDropBatches[batchKey] == b then
                            Proxy._pendingDropBatches[batchKey] = nil

                            -- Check if top log in list can be merged (< 0.55s ago at exact same tile)
                            local merged = false
                            local top = Proxy.logsData.list and Proxy.logsData.list[1]
                            if top and top.kind == "DROP" and top.player == b.player and top.item == b.itemName and top.x == b.x and top.y == b.y then
                                if top._clock and (os.clock() - top._clock) < 0.55 then
                                    top.count = top.count + b.count
                                    top.itemId = top.itemId or b.itemId
                                    top.text = string.format("%s drop %d %s di (%d, %d)", b.player, top.count, b.itemName, b.x, b.y)
                                    top._clock = os.clock()
                                    merged = true
                                    if Proxy.refreshLogsUI and Proxy.logsDialog and Proxy.logsDialog.Visible then
                                        Proxy.refreshLogsUI()
                                    end
                                end
                            end

                            if not merged then
                                local desc = string.format("%s drop %d %s di (%d, %d)", b.player, b.count, b.itemName, b.x, b.y)
                                Proxy.addLog("DROP", b.player, desc, b.itemName, b.count, b.x, b.y, b.userId, b.itemId)
                            end
                        end
                    end)
                end
            end
        end)
    end

    -- 3. ByteNet Net.dropTaken (Auto-Display & Collect Activity Logger)
    if Net and Net.dropTaken and type(Net.dropTaken.listen) == "function" then
        Net.dropTaken.listen(function(pkt)
            if type(pkt) == "table" and pkt.uid then
                pcall(hookWorldTakeDrop)
                syncOthersNativeNames()

                -- Resolve previous drop data
                local prev = Proxy.logsData.knownDrops[pkt.uid]
                if not prev then
                    local w = getNativeWorld and getNativeWorld()
                    local drops = (w and type(w.dropList) == "function" and w.dropList()) or gameDropsTable
                    if drops then
                        for _, d in ipairs(drops) do
                            if type(d) == "table" and d.uid == pkt.uid then
                                prev = {
                                    uid = d.uid,
                                    id = d.id,
                                    n = d.n,
                                    x = d.x,
                                    y = d.y,
                                    by = d.by,
                                }
                                Proxy.logsData.knownDrops[pkt.uid] = prev
                                break
                            end
                        end
                    end
                end

                local prevCount = (prev and prev.n) or 1
                local newCount = pkt.n or 0
                local takenCount = prevCount - newCount
                if takenCount <= 0 and (pkt.n == nil or pkt.n == 0) then
                    takenCount = prevCount
                end

                if takenCount > 0 then
                    local itemId = (prev and prev.id) or 0
                    local itemName = "Item #" .. tostring(itemId)
                    if itemId == 112 then
                        itemName = "Gems"
                    elseif Proxy.LOCK_NAMES[itemId] then
                        itemName = Proxy.LOCK_NAMES[itemId]
                    elseif ItemDB and ItemDB[itemId] and ItemDB[itemId].name then
                        itemName = ItemDB[itemId].name
                    end

                    local dropX = prev and prev.x or 0
                    local dropY = prev and prev.y or 0
                    local tx = math.floor(dropX) + 1
                    local ty = math.floor(dropY) + 1

                    -- Determine who collected:
                    local isLocalCollect = false
                    if Proxy.localPendingTakes[pkt.uid] and (os.clock() - Proxy.localPendingTakes[pkt.uid]) < 3.5 then
                        isLocalCollect = true
                        Proxy.localPendingTakes[pkt.uid] = nil
                    end

                    local collector = nil
                    local lpUserId = Players.LocalPlayer and Players.LocalPlayer.UserId
                    local px, py = getPlayerTilePos()
                    local distLP = (px and py) and math.sqrt((px - dropX)^2 + (py - dropY)^2) or 999

                    -- Find closest other player
                    local closestOtherName = nil
                    local closestOtherDist = 999
                    if othersPlayerTable then
                        for peerId, op in pairs(othersPlayerTable) do
                            if type(op) == "table" and op.x and op.y then
                                local d = math.sqrt((op.x - dropX)^2 + (op.y - dropY)^2)
                                if d < closestOtherDist then
                                    closestOtherDist = d
                                    closestOtherName = op.name or ("Player_" .. tostring(peerId))
                                end
                            end
                        end
                    end

                    if isLocalCollect then
                        collector = getLocalNativeName() .. " (You)"
                    elseif prev and prev.by and tostring(prev.by) == tostring(lpUserId) then
                        -- YOU dropped this item! If someone collects it, it is ALWAYS the other player!
                        if closestOtherDist <= 2.8 then
                            collector = closestOtherName or "Player Lain"
                        end
                    elseif closestOtherDist < distLP and closestOtherDist <= 2.2 then
                        -- The other player is closer to the drop and within pickup range!
                        collector = closestOtherName
                    elseif distLP <= 1.8 then
                        -- Local player is closest and actively picking it up!
                        collector = getLocalNativeName() .. " (You)"
                    end

                    -- Prevent ghost collect logs when gems merge into larger gem on the same tile
                    if itemId == 112 and not isLocalCollect then
                        local currentTileGems = getTotalDropsOnTile(tx - 1, ty - 1, 112)
                        local prevTileGems = Proxy._tileGemTotals[string.format("%d,%d", tx - 1, ty - 1)] or 0
                        if currentTileGems >= prevTileGems and prevTileGems > 0 then
                            collector = nil
                        end
                    end

                    -- Only log if an actual player was identified and within pickup range
                    -- (Prevents ghost collects when drops merge or despawn)
                    if collector then
                        local cBatchKey = string.format("%d_%d_%s_%s", tx, ty, tostring(itemName), tostring(collector))
                        if Proxy._pendingCollectBatches[cBatchKey] then
                            local cb = Proxy._pendingCollectBatches[cBatchKey]
                            cb.count = cb.count + takenCount
                            cb.lastTime = os.clock()
                        else
                            local cb = {
                                collector = collector,
                                itemName = itemName,
                                itemId = itemId,
                                count = takenCount,
                                x = tx,
                                y = ty,
                                lastTime = os.clock(),
                            }
                            Proxy._pendingCollectBatches[cBatchKey] = cb

                            task.delay(0.12, function()
                                if Proxy._pendingCollectBatches[cBatchKey] == cb then
                                    Proxy._pendingCollectBatches[cBatchKey] = nil

                                    local cMerged = false
                                    local top = Proxy.logsData.list and Proxy.logsData.list[1]
                                    if top and top.kind == "COLLECT" and top.player == cb.collector and top.item == cb.itemName and top.x == cb.x and top.y == cb.y then
                                        if top._clock and (os.clock() - top._clock) < 0.55 then
                                            top.count = top.count + cb.count
                                            top.itemId = top.itemId or cb.itemId
                                            top.text = string.format("%s ambil %d %s di (%d, %d)", cb.collector, top.count, cb.itemName, cb.x, cb.y)
                                            top._clock = os.clock()
                                            cMerged = true
                                            if Proxy.refreshLogsUI and Proxy.logsDialog and Proxy.logsDialog.Visible then
                                                Proxy.refreshLogsUI()
                                            end
                                        end
                                    end

                                    if not cMerged then
                                        local desc = string.format("%s ambil %d %s di (%d, %d)", cb.collector, cb.count, cb.itemName, cb.x, cb.y)
                                        Proxy.addLog("COLLECT", cb.collector, desc, cb.itemName, cb.count, cb.x, cb.y, nil, cb.itemId)
                                    end
                                end
                            end)
                        end
                    end
                end

                if (pkt.n or 0) <= 0 then
                    Proxy.logsData.knownDrops[pkt.uid] = nil
                elseif prev then
                    prev.n = pkt.n
                end

                -- Floating gems handling (immediately update / clear tile on ground)
                local dropTx = prev and prev.x and math.floor(prev.x)
                local dropTy = prev and prev.y and math.floor(prev.y)
                local drops = nil
                local w = getNativeWorld and getNativeWorld()
                if w and type(w.dropList) == "function" then drops = w.dropList() end
                if not drops then drops = gameDropsTable or findGameDropsTable() end
                if drops then
                    for _, drop in ipairs(drops) do
                        if type(drop) == "table" and drop.uid == pkt.uid and drop.id == 112 then
                            dropTx = math.floor(drop.x)
                            dropTy = math.floor(drop.y)
                            break
                        end
                    end
                end
                if dropTx and dropTy then
                    handleTileDropUpdate(dropTx, dropTy, 112, 0)
                end
            end
        end)
    end

    -- 4. ByteNet Net.entered (Player entered world)
    if Net and Net.entered and type(Net.entered.listen) == "function" then
        Net.entered.listen(function(pkt)
            if type(pkt) == "table" and pkt.name then
                local pName = pkt.name
                local pUid = pkt.userId
                Proxy.logsData.knownPeers[pkt.id or pUid or pName] = { name = pName, userId = pUid }
                if pUid then
                    Proxy.userIdToName[tostring(pUid)] = pName
                end
                local desc = string.format("%s masuk ke world", pName)
                Proxy.addLog("ENTER", pName, desc, "Main Door", nil, nil, nil, pUid, 6)
            end
        end)
    end

    -- 5. ByteNet Net.left (Player left world)
    if Net and Net.left and type(Net.left.listen) == "function" then
        Net.left.listen(function(pkt)
            local peerId = pkt
            if type(pkt) == "table" and pkt.id then peerId = pkt.id end
            local pInfo = Proxy.logsData.knownPeers[peerId]
            local pName = pInfo and pInfo.name or (pInfo and pInfo.userId and Proxy.userIdToName[tostring(pInfo.userId)]) or ("Player_" .. tostring(peerId))
            Proxy.logsData.knownPeers[peerId] = nil
            local desc = string.format("%s keluar dari world", pName)
            Proxy.addLog("EXIT", pName, desc, "Main Door", nil, nil, nil, pInfo and pInfo.userId, 6)
        end)
    end

    -- Supplementary Players join/leave connections
    Players.PlayerAdded:Connect(function(plr)
        if plr ~= Players.LocalPlayer then
            local pName = getPlayerNativeName(plr.UserId, plr.DisplayName)
            local desc = string.format("%s bergabung ke server", pName)
            Proxy.addLog("ENTER", pName, desc, "Main Door", nil, nil, nil, plr.UserId, 6)
        end
    end)
    Players.PlayerRemoving:Connect(function(plr)
        if plr ~= Players.LocalPlayer then
            local pName = getPlayerNativeName(plr.UserId, plr.DisplayName)
            local desc = string.format("%s keluar dari server", pName)
            Proxy.addLog("EXIT", pName, desc, "Main Door", nil, nil, nil, plr.UserId, 6)
        end
    end)

    -- Log local player enter with native name
    task.delay(1.5, function()
        local w = getNativeWorld and getNativeWorld()
        local wName = (w and w.name) or (Proxy.lastWorldName ~= "" and Proxy.lastWorldName) or "WORLD"
        local myNativeName = getLocalNativeName()
        Proxy.addLog("ENTER", myNativeName .. " (You)", string.format("Kamu (%s) berada di world '%s'", myNativeName, wName), "Main Door", nil, nil, nil, nil, 6)
    end)

    -- 3. Legacy RemoteEvent fallback (just in case)
    if dropAddedRemote and dropAddedRemote:IsA("RemoteEvent") then
        gemFloatConn = dropAddedRemote.OnClientEvent:Connect(function(uid, itemId, count, x, y, userId)
            if itemId ~= 112 then return end
            if type(count) ~= "number" or count <= 0 or type(x) ~= "number" or type(y) ~= "number" then return end
            local tx = math.floor(x)
            local ty = math.floor(y)
            handleTileDropUpdate(tx, ty, 112, count)
        end)
    end

    if dropTakenRemote and dropTakenRemote:IsA("RemoteEvent") then
        dropTakenConn = dropTakenRemote.OnClientEvent:Connect(function(uid, newCount)
            if type(newCount) ~= "number" or newCount <= 0 then return end
            local drops = gameDropsTable or findGameDropsTable()
            if drops then
                for _, drop in ipairs(drops) do
                    if type(drop) == "table" and drop.uid == uid and drop.id == 112 and type(drop.n) == "number" and newCount > drop.n then
                        local tx = math.floor(drop.x)
                        local ty = math.floor(drop.y)
                        handleTileDropUpdate(tx, ty, 112, newCount)
                        break
                    end
                end
            end
        end)
    end

    -- Hook Fast Action Wrench (LMB = Pull, RMB = Kick) (othersPlayerTable extracted above)

    local function isWrenchActive()
        local nameTag = PlayerGui:FindFirstChild("NameTag", true)
        local wrenchIcon = nameTag and nameTag:FindFirstChild("Wrench")
        if wrenchIcon and wrenchIcon.Visible == true then return true end
        if othersPlayerTable then
            for _, p in pairs(othersPlayerTable) do
                if p.wrench and p.wrench.frame and p.wrench.frame.Visible then
                    return true
                end
            end
        end
        return false
    end

    local function getPlayerAtScreen(pos)
        if othersRef and type(othersRef.wrenchAt) == "function" then
            local t = othersRef.wrenchAt(pos)
            if t and t.userId then return t end
        end
        local closest = nil
        local closestDist = math.huge
        if othersPlayerTable then
            for _, p in pairs(othersPlayerTable) do
                if p.seen and p.tag then
                    local tPos = p.tag.AbsolutePosition
                    local tSize = p.tag.AbsoluteSize
                    local center = Vector2.new(tPos.X + tSize.X / 2, tPos.Y + 45)
                    local minX = tPos.X - 25
                    local maxX = tPos.X + tSize.X + 25
                    local minY = tPos.Y - 15
                    local maxY = tPos.Y + 120
                    if pos.X >= minX and pos.X <= maxX and pos.Y >= minY and pos.Y <= maxY then
                        local dist = (pos - center).Magnitude
                        if dist < closestDist then
                            closestDist = dist
                            closest = { id = p.id, userId = p.userId, name = p.name }
                        end
                    end
                end
            end
        end
        return closest
    end

    local oldOpenPlayer = worldMenuRef and worldMenuRef.openPlayer
    local function customOpenPlayer(target)
        if Proxy.fastPKEnabled and target and (target.userId or target.name) then
            task.spawn(function()
                local idStr = target.userId and ("#" .. tostring(target.userId)) or tostring(target.name)
                local ok = sendWorldCommand("pull", idStr)
                if ok and Sfx and Sfx.play then pcall(Sfx.play, "click") end
            end)
            return nil
        end
        if oldOpenPlayer then
            return oldOpenPlayer(target)
        end
        return nil
    end

    if worldMenuRef then
        worldMenuRef.openPlayer = customOpenPlayer
    end

    -- Dynamic background enforcer agar worldMenu hook tidak lepas saat ganti world / reload
    task.spawn(function()
        while true do
            task.wait(2.0)
            pcall(function()
                if not worldMenuRef and filtergc then
                    local wmList = filtergc("table", { Keys = {"openPlayer", "openHome"} }, false)
                    if wmList and wmList[1] then
                        worldMenuRef = wmList[1]
                    end
                end
                if worldMenuRef and worldMenuRef.openPlayer ~= customOpenPlayer then
                    oldOpenPlayer = worldMenuRef.openPlayer
                    worldMenuRef.openPlayer = customOpenPlayer
                end
            end)
        end
    end)

    local kickConn = UserInputService.InputBegan:Connect(function(input, gpe)
        if not Proxy.fastPKEnabled then return end
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            local mousePos = Vector2.new(input.Position.X, input.Position.Y)
            local target = getPlayerAtScreen(mousePos)
            if target and target.userId then
                task.spawn(function()
                    local ok = sendWorldCommand("kick", "#" .. tostring(target.userId))
                    if ok and Sfx and Sfx.play then pcall(Sfx.play, "punch_hit") end
                end)
            end
        elseif (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) and not gpe then
            if isWrenchActive() then
                local mousePos = Vector2.new(input.Position.X, input.Position.Y)
                local target = getPlayerAtScreen(mousePos)
                if target and (target.userId or target.name) then
                    task.spawn(function()
                        local idStr = target.userId and ("#" .. tostring(target.userId)) or tostring(target.name)
                        local ok = sendWorldCommand("pull", idStr)
                        if ok and Sfx and Sfx.play then pcall(Sfx.play, "click") end
                    end)
                end
            end
        end
    end)

    -- Hook Punch to Check Gems (via Net.act.send + UserInput click fallback)
    if Net and Net.act and type(Net.act.send) == "function" and not Net.act._syshubPunchGemsHookInstalled then
        Net.act._syshubPunchGemsHookInstalled = true
        local origActSend = Net.act.send
        Net.act.send = function(pkt)
            if Proxy.punchGemsCheck and type(pkt) == "table" then
                local kind = pkt.kind
                if kind == 1 or kind == 6 or kind == ACT_KIND.PUNCH or kind == ACT_KIND.HIT then
                    local tx = math.floor(pkt.x or 0)
                    local ty = math.floor(pkt.y or 0)
                    task.spawn(function()
                        local count = getTotalDropsOnTile(tx, ty, 112)
                        local key = tx .. "," .. ty .. ":112"
                        if count and count > 0 then
                            spawnFloatingDropText(tx, ty, 112, count, 3.0)
                        else
                            if activeTileLabels[key] and activeTileLabels[key].Parent then
                                pcall(function() activeTileLabels[key]:Destroy() end)
                                activeTileLabels[key] = nil
                            end
                        end
                    end)
                end
            end
            return origActSend(pkt)
        end
    end

    local punchClickConn = UserInputService.InputBegan:Connect(function(input)
        if not Proxy.punchGemsCheck then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            local pgui = PlayerGui
            local pnbGui = pgui and pgui:FindFirstChild("PNB_UI")
            local mainDlg = pnbGui and pnbGui:FindFirstChild("MainDialog")
            if mainDlg and mainDlg.Visible then
                local ap = mainDlg.AbsolutePosition
                local as = mainDlg.AbsoluteSize
                local mx, my = input.Position.X, input.Position.Y
                if mx >= ap.X and mx <= ap.X + as.X and my >= ap.Y and my <= ap.Y + as.Y then
                    return
                end
            end

            local camera, tiles = getCameraAndTiles()
            if camera and tiles then
                local s = camera:FindFirstChildWhichIsA("UIScale")
                local uiScale = s and s.Scale or 1
                local tileSize = 64 * uiScale
                local absPos = tiles.AbsolutePosition
                local mouseX = input.Position.X
                local mouseY = input.Position.Y
                local tx = math.floor((mouseX - absPos.X) / tileSize)
                local ty = math.floor((mouseY - absPos.Y) / tileSize)
                if tx >= 0 and ty >= 0 then
                    task.delay(0.04, function()
                        local count = getTotalDropsOnTile(tx, ty, 112)
                        local key = tx .. "," .. ty .. ":112"
                        if count and count > 0 then
                            spawnFloatingDropText(tx, ty, 112, count, 3.0)
                        else
                            if activeTileLabels[key] and activeTileLabels[key].Parent then
                                pcall(function() activeTileLabels[key]:Destroy() end)
                                activeTileLabels[key] = nil
                            end
                        end
                    end)
                end
            end
        end
    end)

    if _G.CleanGrowbloxCommands then
        pcall(_G.CleanGrowbloxCommands)
    end

    -- Hook Chat Controller
    local chatTableRef = nil
    for attempt = 1, 30 do
        local chatGui = PlayerGui:FindFirstChild("ChatGui")
        local chatInput = chatGui and chatGui:FindFirstChild("Input", true)
        if chatInput then
            local conns = getconnections(chatInput.FocusLost)
            for _, c in ipairs(conns or {}) do
                local fn = c.Function
                if type(fn) == "function" then
                    local ok4, sendFn = pcall(debug.getupvalue, fn, 4)
                    if ok4 and type(sendFn) == "function" then
                        local ok1, tbl = pcall(debug.getupvalue, sendFn, 1)
                        if ok1 and type(tbl) == "table" and type(tbl.onCommand) == "function" then
                            chatTableRef = tbl
                            Proxy.chatTableRef = tbl
                            break
                        end
                    end
                end
            end
            if chatTableRef then break end
        end
        task.wait(0.5)
    end

    if not chatTableRef then
        warn("[SYSHUB Proxy] Chat controller could not be hooked!")
        return
    end

    -- Hook chat/console for local collect logs
    local function handleCollectText(text)
        if type(text) ~= "string" then return end
        local clean = text:gsub("`%w", ""):gsub("``", "")
        if clean:find("You collected") then
            local countStr, itemName = clean:match("You collected%s+(%d+)%s+([^!]+)")
            if countStr and itemName then
                local count = tonumber(countStr) or 1
                itemName = itemName:gsub("%s*Rarity:.*$", ""):gsub("^%s*(.-)%s*$", "%1")
                local key = itemName .. ":" .. tostring(count)
                if Proxy._lastCollectLogKey == key and (os.clock() - (Proxy._lastCollectLogTime or 0)) < 1.2 then
                    return
                end
                Proxy._lastCollectLogKey = key
                Proxy._lastCollectLogTime = os.clock()
                local myNative = getLocalNativeName()
                local desc = string.format("%s ambil %d %s", myNative .. " (You)", count, itemName)
                Proxy.addLog("COLLECT", myNative .. " (You)", desc, itemName, count, nil, nil, nil, Proxy.getItemId(itemName))
            end
        end
    end

    if type(chatTableRef.add) == "function" and not chatTableRef._collectHooked then
        chatTableRef._collectHooked = true
        local origChatAdd = chatTableRef.add
        chatTableRef.add = function(text, ...)
            handleCollectText(text)
            if Proxy.rouletteDetector and type(text) == "string" and Proxy.formatRouletteText then
                text = Proxy.formatRouletteText(text, "REAL")
            end
            if Proxy.applyNick then text = Proxy.applyNick(text) end
            return origChatAdd(text, ...)
        end
    end

    if type(chatTableRef.console) == "function" and not chatTableRef._consoleHooked then
        chatTableRef._consoleHooked = true
        local origChatConsole = chatTableRef.console
        chatTableRef.console = function(text, ...)
            handleCollectText(text)
            if Proxy.applyNick then text = Proxy.applyNick(text) end
            return origChatConsole(text, ...)
        end
    end

    -- Hook onMessage to detect typed fake roulette messages from users
    if type(chatTableRef.onMessage) == "function" and not chatTableRef._rouletteHooked then
        chatTableRef._rouletteHooked = true
        local origOnMessage = chatTableRef.onMessage
        chatTableRef.onMessage = function(sender, msg, ...)
            if Proxy.rouletteDetector and type(msg) == "string" then
                local cleanMsg = msg:gsub("`%w", ""):gsub("``", ""):lower()
                if cleanMsg:find("spun the wheel") or cleanMsg:find("memutar roulette") then
                    local senderName = (sender and sender.DisplayName) or (sender and sender.Name) or "Player"
                    local sUid = sender and sender.UserId

                    local pNum = tonumber(cleanMsg:match("spun the wheel and got%s*[%`%*]*(%d+)"))
                    local isRecentReal = false
                    local gSpins = _G.SyshubWheelSpins
                    if gSpins then
                        if sUid and gSpins[tostring(sUid)] and (os.clock() - gSpins[tostring(sUid)].clock) < 5.0 then
                            if pNum == nil or gSpins[tostring(sUid)].n == pNum then isRecentReal = true end
                        elseif senderName and gSpins[senderName:lower()] and (os.clock() - gSpins[senderName:lower()].clock) < 5.0 then
                            if pNum == nil or gSpins[senderName:lower()].n == pNum then isRecentReal = true end
                        end
                    end

                    if not isRecentReal then
                        local alert = string.format("`4[⚠️ FAKE ROULETTE DETECTED!] %s MENGETIK ANGKA ROULETTE PALSU DI CHAT! (SCAM)``", senderName)
                        if type(chatTableRef.add) == "function" then
                            chatTableRef.add(alert)
                        end

                        pcall(function()
                            if Sfx and Sfx.play then Sfx.play("cant_place_tile") end
                        end)

                        if Proxy.notify then
                            Proxy.notify(string.format("`4[⚠️ FAKE ROLL] %s mengetik angka roulette palsu!``", senderName))
                        end

                        -- Log fake spin in /logs
                        task.spawn(function()
                            local remeVal = Proxy.calcReme and Proxy.calcReme(pNum or 0) or 0
                            local fakeLog = string.format("[FAKE] [%s typed: %s] REME : %d", senderName, msg, remeVal)
                            Proxy.addLog("ROULETTE", senderName, fakeLog, "Roulette", pNum or 0, nil, nil, sUid, 758)
                        end)

                        if Proxy.formatRouletteText then
                            msg = Proxy.formatRouletteText(msg, "FAKE")
                        else
                            msg = "`4[FAKE]`` " .. msg
                        end
                    end
                end
            end
            return origOnMessage(sender, msg, ...)
        end

        -- Hook ChatUI showBubble if available
        pcall(function()
            if debug and debug.getupvalue then
                local sb = debug.getupvalue(origOnMessage, 6)
                if type(sb) == "function" then
                    Proxy._nativeShowBubble = sb
                    if debug.setupvalue and not sb._rouletteHooked then
                        local origShowBubble = sb
                        local function hookedShowBubble(text, ...)
                            if Proxy.rouletteDetector and type(text) == "string" and Proxy.formatRouletteText then
                                text = Proxy.formatRouletteText(text, "REAL")
                            end
                            if Proxy.applyNick then text = Proxy.applyNick(text) end
                            return origShowBubble(text, ...)
                        end
                        hookedShowBubble._rouletteHooked = true
                        Proxy._nativeShowBubble = hookedShowBubble
                        debug.setupvalue(origOnMessage, 6, hookedShowBubble)
                    end
                end
            end
        end)

        -- Hook GameGui.Game showBubble & BitmapText.set for local player speech bubble
        pcall(function()
            local tbls = filtergc("table", { Keys = {"onSay"} }, false)
            if tbls and tbls[1] and type(tbls[1].onSay) == "function" then
                local sbGame = debug.getupvalue(tbls[1].onSay, 1)
                if type(sbGame) == "function" and not sbGame._rouletteHooked then
                    local origSbGame = sbGame
                    local function hookedSbGame(text, ...)
                        if Proxy.rouletteDetector and type(text) == "string" and Proxy.formatRouletteText then
                            text = Proxy.formatRouletteText(text, "REAL")

                            -- Clean any duplicate lines from bubble history table
                            pcall(function()
                                local linesTable = debug.getupvalue(origSbGame, 2)
                                if type(linesTable) == "table" and #linesTable > 0 then
                                    local cleanCurrent = text:gsub("`%w", ""):gsub("``", "")
                                    for idx = #linesTable, 1, -1 do
                                        local lText = linesTable[idx]
                                        if type(lText) == "string" and lText:gsub("`%w", ""):gsub("``", "") == cleanCurrent then
                                            table.remove(linesTable, idx)
                                        end
                                    end
                                end
                            end)
                        end
                        if Proxy.applyNick then text = Proxy.applyNick(text) end
                        return origSbGame(text, ...)
                    end
                    hookedSbGame._rouletteHooked = true
                    debug.setupvalue(tbls[1].onSay, 1, hookedSbGame)
                end
            end
        end)

        -- Global BitmapText.set hook. Ini jalur UTAMA bubble spin kita sendiri: hasil wheel
        -- memanggil fungsi lokal showBubble game secara langsung (bukan lewat onSay yang di-hook),
        -- lalu showBubble -> BitmapText:set(semua baris digabung "``\n"). Format per baris.
        pcall(function()
            local bm = BitmapText or (filtergc and filtergc("table", { Keys = {"COLORS", "set", "new"} }, false)[1])
            if bm and type(bm.set) == "function" and not bm._syshubHooked then
                bm._syshubHooked = true
                local origBtSet = bm.set
                bm.set = function(self, str, ...)
                    if type(str) == "string" then
                        if Proxy.rouletteDetector and Proxy.formatRouletteText then
                            str = Proxy.formatRouletteText(str, "REAL")
                        end
                        if Proxy.applyNick then str = Proxy.applyNick(str) end
                    end
                    return origBtSet(self, str, ...)
                end
            end
        end)
    end

    if not chatTableRef._origOnCommand then
        chatTableRef._origOnCommand = chatTableRef.onCommand
    end
    local origOnCommand = chatTableRef._origOnCommand


    -- =========================================================================
    -- SYSHUB VISUAL WARDROBE & WORLD WEATHER SYSTEM (CLIENT ONLY)
    -- =========================================================================
    local SysHubVisual = {
        dialog = nil,
        config = { worn = {}, items = {}, weather = nil, title = nil },
        configLoaded = false,
        CONFIG_FILE = "syshub_visual_config.json",
        getConfigFile = function()
            return getAccountFileName and getAccountFileName("syshub_visual_config", "json") or "syshub_visual_config.json"
        end,
        wearItems = nil,
        currentTab = "ALL",
        searchQuery = "",
        renderLimit = 80,
    }

    local SysHubWeather = {
        dialog = nil,
        weathers = nil,
        searchQuery = "",
    }

    local SysHubTitle = {
        allTitles = {
            { key = "supporter",  name = "Supporter",       color = "c", desc = "Supporter of Growblox" },
            { key = "patron",     name = "Patron",          color = "e", desc = "Patron of Growblox" },
            { key = "benefactor", name = "Benefactor",      color = "6", desc = "Benefactor of Growblox" },
            { key = "sponsor",    name = "Sponsor",         color = "d", desc = "Official Game Sponsor" },
            { key = "cc",         name = "Content Creator", color = "9", desc = "Content Creator Verified" },
            { key = "royal",      name = "Royal",           color = "b", desc = "Royal Title" },
            { key = "dr",         name = "Dr.",             color = "4", desc = "Doctor Title" },
            { key = "legend",     name = "Legendary",       color = "o", desc = "of Legend Title" },
        },
    }

    -- 1. CONFIG LOADER & SAVER
    SysHubVisual.loadConfig = function()
        if SysHubVisual.configLoaded then return SysHubVisual.config end
        SysHubVisual.configLoaded = true
        local targetFile = SysHubVisual.getConfigFile and SysHubVisual.getConfigFile() or SysHubVisual.CONFIG_FILE
        local fileToRead = nil
        if isfile and readfile then
            if isfile(targetFile) then
                fileToRead = targetFile
            elseif isfile(SysHubVisual.CONFIG_FILE) then
                fileToRead = SysHubVisual.CONFIG_FILE
            end
        end
        if fileToRead then
            local ok, data = pcall(function()
                local txt = readfile(fileToRead)
                return HttpService:JSONDecode(txt)
            end)
            if ok and type(data) == "table" then
                SysHubVisual.config.worn = type(data.worn) == "table" and data.worn or {}
                SysHubVisual.config.items = type(data.items) == "table" and data.items or {}
                SysHubVisual.config.weather = tonumber(data.weather)
                SysHubVisual.config.title = data.title
                SysHubVisual.config.share = (data.share ~= false)
                -- Auto-migrasi ke file akun jika dibaca dari legacy file lama
                if fileToRead == SysHubVisual.CONFIG_FILE and fileToRead ~= targetFile and writefile then
                    pcall(function()
                        writefile(targetFile, HttpService:JSONEncode(SysHubVisual.config))
                    end)
                end
            end
        end
        return SysHubVisual.config
    end

    SysHubVisual.saveConfig = function()
        if writefile then
            local targetFile = SysHubVisual.getConfigFile and SysHubVisual.getConfigFile() or SysHubVisual.CONFIG_FILE
            pcall(function()
                local txt = HttpService:JSONEncode(SysHubVisual.config)
                writefile(targetFile, txt)
            end)
        end
    end

    -- 2. RESOLVERS & HELPERS
    SysHubVisual.getController = function()
        local eng, w = getNativeEngine()
        if eng and eng.InventoryUI and eng.InventoryUI.current then
            return eng.InventoryUI.current
        end
        if filtergc then
            local list = filtergc("table", { Keys = {"onWear", "isWorn", "refresh"} }, false)
            if list and list[1] then return list[1] end
        end
        return nil
    end

    SysHubVisual.getWornTable = function(ctrl)
        local eng, w = getNativeEngine()
        if eng and type(eng.worn) == "table" then
            return eng.worn
        end
        ctrl = ctrl or SysHubVisual.getController()
        if not ctrl or not ctrl.onWear or not debug or not debug.getupvalues then return nil end
        local ok, ups = pcall(debug.getupvalues, ctrl.onWear)
        if ok and ups then
            if type(ups[1]) == "table" and type(ups[1].worn) == "table" then
                return ups[1].worn
            end
            return ups[3] or nil
        end
        return nil
    end

    local function triggerVisualRefresh(ctrl)
        if ctrl then
            if type(ctrl.refresh) == "function" then
                pcall(ctrl.refresh, ctrl)
                pcall(ctrl.refresh)
            end
            if type(ctrl.applyWorn) == "function" then
                pcall(ctrl.applyWorn, ctrl)
                pcall(ctrl.applyWorn)
            end
        end
        local eng, _ = getNativeEngine()
        if eng then
            if type(eng.applyWorn) == "function" then
                pcall(eng.applyWorn, eng)
                pcall(eng.applyWorn)
            end
            if type(eng.refreshWorn) == "function" then
                pcall(eng.refreshWorn, eng)
                pcall(eng.refreshWorn)
            end
        end
    end

    SysHubVisual.getWearItems = function()
        if SysHubVisual.wearItems then return SysHubVisual.wearItems end
        local db = resolveItemDB()
        if not db then
            local ctrl = SysHubVisual.getController()
            if ctrl and ctrl.onWear and debug and debug.getupvalues then
                local ok, ups = pcall(debug.getupvalues, ctrl.onWear)
                db = ok and ups and ups[1]
            end
        end
        if not db then return {} end

        local list = {}
        for id, it in pairs(db) do
            if type(it) == "table" and it.kind == "cloth" and it.slot then
                local slotName = tostring(it.slot):lower()
                local name = it.name or ("Cloth #" .. tostring(id))
                table.insert(list, {
                    id = id,
                    name = name,
                    slot = slotName,
                    rarity = it.rarity or 0
                })
            end
        end
        table.sort(list, function(a, b)
            return a.name:lower() < b.name:lower()
        end)
        SysHubVisual.wearItems = list
        return list
    end

    SysHubVisual.isWorn = function(id, slot)
        local worn = SysHubVisual.getWornTable()
        if not worn then
            for s, wid in pairs(SysHubVisual.config.worn) do
                if wid == id then return true, s end
            end
            return false, nil
        end
        if slot then
            return worn[slot] == id, slot
        end
        for s, wid in pairs(worn) do
            if wid == id then return true, s end
        end
        return false, nil
    end

    SysHubVisual.toggleWear = function(id, slot)
        local ctrl = SysHubVisual.getController()
        local worn = SysHubVisual.getWornTable(ctrl)
        local db = resolveItemDB()
        if not db then
            local eng, _ = getNativeEngine()
            if eng and eng.Items then db = eng.Items end
        end
        local itemInfo = db and db[id]
        local itemSlot = slot or (itemInfo and itemInfo.slot and tostring(itemInfo.slot):lower())
        local itemName = (itemInfo and itemInfo.name) or ("Item #" .. tostring(id))

        if not itemSlot then
            Proxy.notify("`4[Visual] Gagal mendeteksi slot pakaian untuk ID " .. tostring(id) .. "!``")
            return
        end

        if not worn and not ctrl then
            Proxy.notify("`4[Visual] Controller pakaian game belum siap!``")
            return
        end

        SysHubVisual.loadConfig()
        local isCurrentlyWorn = (worn and worn[itemSlot] == id) or (SysHubVisual.config.worn and SysHubVisual.config.worn[itemSlot] == id)
        if isCurrentlyWorn then
            -- Unequip
            if worn then worn[itemSlot] = nil end
            triggerVisualRefresh(ctrl)
            SysHubVisual.config.worn[itemSlot] = nil
            SysHubVisual.saveConfig()
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify(string.format("`4[Visual] Unequipped %s [%s] (Client Only)``", itemName, itemSlot:upper()))
        else
            -- Equip
            if worn then worn[itemSlot] = id end
            triggerVisualRefresh(ctrl)
            SysHubVisual.config.worn[itemSlot] = id
            SysHubVisual.saveConfig()
            pcall(function() if Sfx and Sfx.play then Sfx.play("change_clothes", "click") end end)
            Proxy.notify(string.format("`2[Visual] Equipped %s [%s] (Client Only)``", itemName, itemSlot:upper()))
        end

        if SysHubVisual.refreshList then
            SysHubVisual.refreshList()
        end
        if SysHubVisual.syncChanged then pcall(SysHubVisual.syncChanged) end
    end

    SysHubVisual.unequipAll = function()
        local ctrl = SysHubVisual.getController()
        local worn = SysHubVisual.getWornTable(ctrl)
        if worn then
            for k in pairs(worn) do worn[k] = nil end
        end
        triggerVisualRefresh(ctrl)
        SysHubVisual.config.worn = {}
        SysHubVisual.saveConfig()
        pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
        Proxy.notify("`4[Visual] Seluruh visual wearable berhasil di-unequip!``")
        if SysHubVisual.refreshList then SysHubVisual.refreshList() end
        if SysHubVisual.syncChanged then pcall(SysHubVisual.syncChanged) end
    end

    SysHubVisual.addToBag = function(id)
        local inv = getNativeInventory and getNativeInventory()
        if not inv or not inv.add then
            Proxy.notify("`4[Visual] Inventory native game tidak ditemukan!``")
            return
        end
        inv:add(id, 1)
        if inv.changed then
            pcall(function()
                if typeof(inv.changed) == "RBXScriptSignal" or type(inv.changed.Fire) == "function" then
                    inv.changed:Fire()
                end
            end)
        end
        SysHubVisual.loadConfig()
        local found = false
        for _, savedId in ipairs(SysHubVisual.config.items) do
            if savedId == id then found = true break end
        end
        if not found then
            table.insert(SysHubVisual.config.items, id)
            SysHubVisual.saveConfig()
        end
        local db = resolveItemDB()
        local itemName = (db and db[id] and db[id].name) or ("Item #" .. tostring(id))
        pcall(function() if Sfx and Sfx.play then Sfx.play("pickup", "click") end end)
        Proxy.notify("`2[Visual] " .. itemName .. " berhasil dimasukkan ke tas! (Client Only)``")
        if SysHubVisual.refreshList then SysHubVisual.refreshList() end
    end

    SysHubVisual.removeFromBag = function(id)
        local inv = getNativeInventory and getNativeInventory()
        if inv and inv.remove then
            inv:remove(id, 1)
            if inv.changed then
                pcall(function()
                    if typeof(inv.changed) == "RBXScriptSignal" or type(inv.changed.Fire) == "function" then
                        inv.changed:Fire()
                    end
                end)
            end
        end
        SysHubVisual.loadConfig()
        for idx = #SysHubVisual.config.items, 1, -1 do
            if SysHubVisual.config.items[idx] == id then
                table.remove(SysHubVisual.config.items, idx)
            end
        end
        SysHubVisual.saveConfig()
        local db = resolveItemDB()
        local itemName = (db and db[id] and db[id].name) or ("Item #" .. tostring(id))
        pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
        Proxy.notify("`4[Visual] " .. itemName .. " dikeluarkan dari tas!``")
        if SysHubVisual.refreshList then SysHubVisual.refreshList() end
    end

    SysHubVisual.autoRestore = function()
        SysHubVisual.loadConfig()
        -- 1. Restore worn clothes
        local ctrl = SysHubVisual.getController()
        local worn = SysHubVisual.getWornTable(ctrl)
        local restoredCount = 0
        if SysHubVisual.config.worn then
            for slot, itemId in pairs(SysHubVisual.config.worn) do
                if tonumber(itemId) then
                    if worn then worn[slot] = tonumber(itemId) end
                    restoredCount = restoredCount + 1
                end
            end
            if restoredCount > 0 then
                triggerVisualRefresh(ctrl)
            end
        end

        -- 2. Restore saved bag items
        local inv = getNativeInventory and getNativeInventory()
        if inv and inv.add and inv.count and SysHubVisual.config.items then
            for _, itemId in ipairs(SysHubVisual.config.items) do
                if tonumber(itemId) and inv:count(itemId) < 1 then
                    inv:add(tonumber(itemId), 1)
                end
            end
            if inv.changed then
                pcall(function()
                    if typeof(inv.changed) == "RBXScriptSignal" or type(inv.changed.Fire) == "function" then
                        inv.changed:Fire()
                    end
                end)
            end
        end
    end

    -- 2b. VISUAL SYNC ANTAR PENGGUNA SYSHUB (/vsync)
    -- Kirim daftar ID baju /visual lewat pesan chat "`{shv1:...}". ChatUI game membuang semua
    -- "`{...}" lalu return kalau teksnya kosong (tanpa chat log, tanpa bubble), jadi pemain biasa
    -- tidak melihat apa-apa. SysHub lain membaca TextChatService.MessageReceived lalu menempelkan
    -- baju itu ke karakter pengirim lewat fungsi setLook game (client-only di sisi penerima).
    do
        if _G.SysHubVisualSync and type(_G.SysHubVisualSync.stop) == "function" then
            pcall(_G.SysHubVisualSync.stop)
        end
        local SHV = {
            PREFIX = "`{shv1:",
            ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz",
            running = true,
            remote = {},                       -- [tostring(userId)] = { ids = {...}, sig = "..." }
            applied = setmetatable({}, { __mode = "k" }), -- [peerTable] = { ver, base, sig }
            known = {},                        -- userId SysHub yang sudah kita balas di world ini
            seenPeers = {},
            lastSend = -100,
            lastSentSig = nil,
            pending = false,
            world = "",
            profiles = {},                     -- [tostring(userId)] = nick/title dari SysHub lain
        }
        _G.SysHubVisualSync = SHV

        function SHV.isEnabled()
            return SysHubVisual.config.share ~= false
        end

        function SHV.encode(ids)
            local a, out, sum = SHV.ALPHA, {}, 0
            for _, id in ipairs(ids) do
                id = math.floor(tonumber(id) or 0)
                if id > 0 and id < 140608 then
                    local d1 = math.floor(id / 2704)
                    local r = id % 2704
                    local d2, d3 = math.floor(r / 52), r % 52
                    out[#out + 1] = a:sub(d1 + 1, d1 + 1) .. a:sub(d2 + 1, d2 + 1) .. a:sub(d3 + 1, d3 + 1)
                    sum = sum + d1 + d2 + d3
                end
            end
            local chk = sum % 52
            return table.concat(out) .. a:sub(chk + 1, chk + 1)
        end

        function SHV.decode(s)
            if type(s) ~= "string" or #s < 1 or (#s % 3) ~= 1 then return nil end
            local a, ids, sum = SHV.ALPHA, {}, 0
            local function idx(ch)
                local p = a:find(ch, 1, true)
                return p and (p - 1) or nil
            end
            for i = 1, #s - 1, 3 do
                local d1, d2, d3 = idx(s:sub(i, i)), idx(s:sub(i + 1, i + 1)), idx(s:sub(i + 2, i + 2))
                if not (d1 and d2 and d3) then return nil end
                sum = sum + d1 + d2 + d3
                ids[#ids + 1] = d1 * 2704 + d2 * 52 + d3
            end
            if idx(s:sub(-1)) ~= (sum % 52) then return nil end -- kena filter chat / rusak
            if #ids > 24 then return nil end
            return ids
        end

        function SHV.myIds()
            local ids = {}
            if SHV.isEnabled() then
                for _, id in pairs(SysHubVisual.config.worn or {}) do
                    if tonumber(id) then ids[#ids + 1] = tonumber(id) end
                end
            end
            table.sort(ids)
            return ids
        end

        -- Ambil setLook + tabel pemain lain dari listener Net.look bawaan game
        function SHV.tools()
            local t = SHV._tools
            if t and t.setLook and t.peers then return t end
            if not (Net and Net.look and type(Net.look.getListeners) == "function") then return nil end
            local okL, list = pcall(Net.look.getListeners)
            for _, fn in ipairs((okL and type(list) == "table" and list) or {}) do
                if type(fn) == "function" and fn ~= SHV._myListener and not (iscclosure and iscclosure(fn)) then
                    local okU, ups = pcall(debug.getupvalues, fn)
                    local peers, setLook, ctx = nil, nil, nil
                    for _, uv in pairs((okU and ups) or {}) do
                        if type(uv) == "function" and not (iscclosure and iscclosure(uv)) then
                            local okU2, ups2 = pcall(debug.getupvalues, uv)
                            for _, t2 in pairs((okU2 and ups2) or {}) do
                                -- rawget saja: ItemDB punya __index berat, jangan dipicu
                                if type(t2) == "table" and getmetatable(t2) == nil and type(rawget(t2, "skins")) == "table" then
                                    setLook, ctx = uv, t2
                                end
                            end
                        elseif type(uv) == "table" then
                            peers = uv
                        end
                    end
                    if setLook and peers then
                        SHV._tools = { setLook = setLook, ctx = ctx, peers = peers }
                        return SHV._tools
                    end
                end
            end
            return nil
        end

        function SHV.skinKey(tools, p)
            local skins = rawget(tools.ctx, "skins")
            if type(skins) == "table" then
                for k, v in pairs(skins) do
                    if v == p.skin then return k end
                end
            end
            return rawget(tools.ctx, "defaultSkin")
        end

        local function slotOf(db, id)
            local it = db and db[id]
            return it and it.slot and tostring(it.slot):lower() or nil
        end

        -- Tempel baju override ke 1 pemain (base = baju asli dia, slot yang di-override diganti)
        function SHV.applyPeer(p, ids, sig)
            local tools = SHV.tools()
            if not tools then return false end
            local rec = SHV.applied[p]
            local base
            if rec and rec.ver == p.lookVer then
                base = rec.base -- kita penulis terakhir, base asli masih valid
            else
                base = {}
                for id in pairs(p.worn or {}) do base[#base + 1] = id end
            end
            local db = resolveItemDB()
            local over = {}
            for _, id in ipairs(ids) do
                local s = slotOf(db, id)
                if s then over[s] = true end
            end
            local result = {}
            for _, id in ipairs(base) do
                local s = slotOf(db, id)
                if not (s and over[s]) then result[#result + 1] = id end
            end
            for _, id in ipairs(ids) do result[#result + 1] = id end
            local ok = pcall(tools.setLook, p, SHV.skinKey(tools, p), result)
            if ok then
                SHV.applied[p] = { ver = p.lookVer, base = base, sig = sig }
            end
            return ok
        end

        function SHV.revertPeer(p)
            local rec = SHV.applied[p]
            SHV.applied[p] = nil
            if rec and rec.ver == p.lookVer then
                local tools = SHV.tools()
                if tools then pcall(tools.setLook, p, SHV.skinKey(tools, p), rec.base) end
            end
        end

        function SHV.forEachPeerOf(uid, fn)
            local tools = SHV.tools()
            if not tools then return end
            for _, p in pairs(tools.peers) do
                if type(p) == "table" and not p.npc and tostring(p.userId) == uid then
                    pcall(fn, p)
                end
            end
        end

        ------------------------------------------------------------------
        -- SYNC PROFIL: /nick + /title (pesan "`{shp2:<kode konsonan>}", lihat encodeProfile)
        -- Game membaca nama & title pemain lain dari atribut Player:
        --   nameOf  -> Nick, lalu GameName, lalu Name
        --   titleOf -> WornTitle (legend lewat HasLegend, dr lewat DrTitle)
        -- Jadi di sisi penerima cukup SetAttribute (lokal, tidak replikasi) di Player pengirim.
        -- Nilai asli dari server disimpan dan dikembalikan saat sync dimatikan / dia lepas.
        ------------------------------------------------------------------
        local TITLE_OK = {
            supporter = true, patron = true, benefactor = true, sponsor = true,
            cc = true, royal = true, dr = true, legend = true,
        }
        local PROFILE_ATTRS = { "Nick", "WornTitle", "HasLegend", "DrTitle" }
        -- Encoding v2: semua huruf KONSONAN (tanpa vokal & angka), jadi filter chat Roblox tidak
        -- melihat kata/angka apapun untuk disensor (nick teks biasa di v1 kena #####).
        -- Title = 1 huruf (index), nick = byte UTF-8, tiap 2 byte -> 3 huruf (42^3 = 74088 >= 65536),
        -- ditutup 1 huruf checksum.
        local TITLE_LIST = { "supporter", "patron", "benefactor", "sponsor", "cc", "royal", "dr", "legend" }
        local NICK_ALPHA = "BCDFGHJKLMNPQRSTVWXYZbcdfghjklmnpqrstvwxyz"
        local NICK_BASE = #NICK_ALPHA -- 42
        local NICK_MAX_BYTES = 32      -- jaga total pesan tetap jauh di bawah batas 200 karakter

        local function capBytes(s, maxB)
            if #s <= maxB then return s end
            local cut = 0
            for pos in utf8.codes(s) do
                if pos - 1 > maxB then break end
                cut = pos - 1
            end
            return s:sub(1, cut)
        end

        function SHV.encodeProfile(title, nick)
            local A, B = NICK_ALPHA, NICK_BASE
            local function ch(i) return A:sub(i + 1, i + 1) end
            local tIdx = 0
            for i, k in ipairs(TITLE_LIST) do
                if k == title then tIdx = i break end
            end
            local out, sum = { ch(tIdx) }, tIdx
            local raw = nick or ""
            for i = 1, #raw, 2 do
                local v = raw:byte(i) * 256 + (raw:byte(i + 1) or 0)
                local d1 = math.floor(v / (B * B))
                local r = v % (B * B)
                local d2, d3 = math.floor(r / B), r % B
                out[#out + 1] = ch(d1) .. ch(d2) .. ch(d3)
                sum = sum + d1 + d2 + d3
            end
            out[#out + 1] = ch(sum % B)
            return table.concat(out)
        end

        function SHV.decodeProfile(s)
            local A, B = NICK_ALPHA, NICK_BASE
            if type(s) ~= "string" or #s < 2 or ((#s - 2) % 3) ~= 0 then return false end
            local function idx(c)
                local p = A:find(c, 1, true)
                return p and (p - 1) or nil
            end
            local tIdx = idx(s:sub(1, 1))
            if not tIdx or tIdx > #TITLE_LIST then return false end
            local sum, parts = tIdx, {}
            for i = 2, #s - 1, 3 do
                local d1, d2, d3 = idx(s:sub(i, i)), idx(s:sub(i + 1, i + 1)), idx(s:sub(i + 2, i + 2))
                if not (d1 and d2 and d3) then return false end
                local v = d1 * B * B + d2 * B + d3
                if v > 65535 then return false end
                sum = sum + d1 + d2 + d3
                parts[#parts + 1] = string.char(math.floor(v / 256), v % 256)
            end
            if idx(s:sub(-1)) ~= (sum % B) then return false end -- rusak / kena filter
            local raw = table.concat(parts)
            while #raw > 0 and raw:byte(#raw) == 0 do raw = raw:sub(1, -2) end -- buang padding
            return true, TITLE_LIST[tIdx], SHV.cleanNick(raw)
        end

        function SHV.cleanNick(s)
            if type(s) ~= "string" then return nil end
            s = s:gsub("[%c`{}]", ""):gsub("^%s+", ""):gsub("%s+$", "")
            local n = utf8.len(s)
            if not n then return nil end -- UTF-8 rusak
            if n > 20 then s = s:sub(1, utf8.offset(s, 21) - 1) end
            if s == "" then return nil end
            return s
        end

        function SHV.myProfile()
            if not SHV.isEnabled() then return nil, nil end
            local title = SysHubVisual.config.title
            if not (type(title) == "string" and TITLE_OK[title]) then title = nil end
            local nick = SHV.cleanNick(Proxy.getNick and Proxy.getNick())
            if nick then nick = capBytes(nick, NICK_MAX_BYTES) end
            return title, nick
        end

        function SHV.hasSomething()
            local title, nick = SHV.myProfile()
            return #SHV.myIds() > 0 or title ~= nil or nick ~= nil
        end

        function SHV.redrawPeerTags(uid)
            SHV.forEachPeerOf(uid, function(p)
                if type(p.redraw) == "function" then p.redraw() end
            end)
        end

        -- Samakan atribut Player pengirim dengan profil yang dia kirim (atau kembalikan ke asli)
        function SHV.enforceProfile(uid)
            local rec = SHV.profiles[uid]
            if not rec then return end
            local plr = Players:GetPlayerByUserId(tonumber(uid) or 0)
            if not plr then return end
            local on = SHV.running and SHV.isEnabled()
            local want = {}
            if on then
                if rec.nick then want.Nick = rec.nick end
                if rec.title == "legend" then
                    want.HasLegend = true
                    want.WornTitle = "none"
                elseif rec.title then
                    want.WornTitle = rec.title
                    if rec.title == "dr" then want.DrTitle = true end
                end
            end
            local changed = false
            for _, a in ipairs(PROFILE_ATTRS) do
                local cur = plr:GetAttribute(a)
                if want[a] ~= nil then
                    if cur ~= want[a] then
                        -- pertama kali, atau server baru saja mengganti nilainya -> itu nilai asli baru
                        if not rec.hasOrig[a] or cur ~= rec.set[a] then
                            rec.orig[a] = cur
                            rec.hasOrig[a] = true
                        end
                        plr:SetAttribute(a, want[a])
                        rec.set[a] = want[a]
                        changed = true
                    end
                elseif rec.hasOrig[a] then
                    if cur == rec.set[a] then
                        plr:SetAttribute(a, rec.orig[a])
                        changed = true
                    end
                    rec.hasOrig[a], rec.orig[a], rec.set[a] = nil, nil, nil
                end
            end
            -- Nama asli pengirim -> nick di chat sistem / bubble spin / logs (lewat Proxy.applyNick)
            if on and rec.nick then
                local reals = {}
                for _, s in ipairs({ plr:GetAttribute("GameName"), plr.Name }) do
                    if type(s) == "string" then
                        s = s:gsub("`%w", ""):gsub("``", ""):gsub("^@", "")
                        if #s >= 3 and s:lower() ~= rec.nick:lower() then reals[#reals + 1] = s end
                    end
                end
                table.sort(reals, function(x, y) return #x > #y end)
                Proxy.remoteNicks[uid] = { nick = rec.nick, reals = reals }
            else
                Proxy.remoteNicks[uid] = nil
            end
            if changed then SHV.redrawPeerTags(uid) end
        end

        function SHV.onProfile(uid, title, nick)
            local rec = SHV.profiles[uid]
            if not title and not nick then
                if rec then SHV.dropProfile(uid) end
                return
            end
            if not rec then
                rec = { orig = {}, hasOrig = {}, set = {} }
                SHV.profiles[uid] = rec
            end
            rec.title, rec.nick = title, nick
            pcall(SHV.enforceProfile, uid)
        end

        function SHV.dropProfile(uid)
            local rec = SHV.profiles[uid]
            if rec then
                rec.title, rec.nick = nil, nil
                pcall(SHV.enforceProfile, uid)
            end
            SHV.profiles[uid] = nil
            Proxy.remoteNicks[uid] = nil
        end

        local function unescapeChat(s)
            return (s:gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&quot;", "\""):gsub("&apos;", "'"):gsub("&amp;", "&"))
        end

        function SHV.parseProfile(txt)
            -- v2: title + nick ter-encode huruf konsonan (tidak bisa disensor filter chat)
            local p2 = txt:match("`{shp2:(%a*)}")
            if p2 then
                return SHV.decodeProfile(p2)
            end
            -- v1 (script versi lama): nick teks biasa
            local pt, pn = txt:match("`{shp1:([%w_%-]*):([^}]*)}")
            if not pt then return false end
            local title = TITLE_OK[pt] and pt or nil
            local nick = SHV.cleanNick(unescapeChat(pn))
            -- Kena filter chat Roblox (jadi ####) -> abaikan nick-nya
            if nick and nick:find("#", 1, true) then nick = nil end
            return true, title, nick
        end

        ------------------------------------------------------------------
        -- SERVER SYNC (Laravel Reverb di syshub.my.id). Kalau server mati / belum dipasang,
        -- otomatis pakai jalur chat kode tersembunyi di bawah.
        -- Isi secret & appKey dari .env server (SYSHUB_SYNC_SECRET, REVERB_APP_KEY).
        ------------------------------------------------------------------
        local SYNC_SERVER = {
            enabled = true,
            api = "https://syshub.my.id/api/syshub-sync",
            ws = "wss://syshub.my.id/syshub-ws/app/",
            secret = "609047b1bec9325209b2b592e92c6b05d1e11cf8c85f2ff9",   -- SYSHUB_SYNC_SECRET
            appKey = "9d69773f76a9a24f1c45",   -- REVERB_APP_KEY
        }
        local srv = { sock = nil, connected = false, job = nil, lastTry = -100, failCount = 0 }
        SHV.server = srv

        local function httpReq(opts)
            local fn = (syn and syn.request) or (http and http.request) or http_request or request
            if not fn then return nil end
            local ok, res = pcall(fn, opts)
            if ok and type(res) == "table" then return res end
            return nil
        end

        function SHV.serverReady()
            return SYNC_SERVER.enabled and SYNC_SERVER.secret ~= "" and SYNC_SERVER.appKey ~= ""
                and WebSocket ~= nil and srv.connected and srv.job == game.JobId
        end

        function SHV.applyServerProfile(p)
            if type(p) ~= "table" then return end
            local uid = tostring(tonumber(p.uid) or "")
            local lp = Players.LocalPlayer
            if uid == "" or (lp and uid == tostring(lp.UserId)) then return end
            -- hanya pemain yang ada di server Roblox ini
            if not Players:GetPlayerByUserId(tonumber(uid)) then return end
            local ids = {}
            if type(p.worn) == "table" then
                for _, id in ipairs(p.worn) do
                    if tonumber(id) then ids[#ids + 1] = math.floor(tonumber(id)) end
                end
            end
            table.sort(ids)
            SHV.onIncoming(uid, ids, "srv:" .. table.concat(ids, ","))
            local title = (type(p.title) == "string" and TITLE_OK[p.title]) and p.title or nil
            SHV.onProfile(uid, title, SHV.cleanNick(type(p.nick) == "string" and p.nick or nil))
        end

        function SHV.serverSnapshot()
            local res = httpReq({
                Url = SYNC_SERVER.api .. "/" .. game.JobId,
                Method = "GET",
                Headers = { ["X-SysHub-Secret"] = SYNC_SERVER.secret, ["Accept"] = "application/json" },
            })
            if not (res and res.StatusCode == 200) then return false end
            local ok, data = pcall(HttpService.JSONDecode, HttpService, res.Body)
            if ok and type(data) == "table" and type(data.profiles) == "table" then
                for _, p in ipairs(data.profiles) do pcall(SHV.applyServerProfile, p) end
            end
            return true
        end

        function SHV.serverPush()
            local title, nick = SHV.myProfile()
            local worn = SHV.myIds()
            local body = { job = game.JobId, uid = tostring(Players.LocalPlayer.UserId), worn = worn, title = title, nick = nick }
            local okE, json = pcall(HttpService.JSONEncode, HttpService, body)
            if not okE then return false end
            local res = httpReq({
                Url = SYNC_SERVER.api .. "/profile",
                Method = "POST",
                Headers = {
                    ["X-SysHub-Secret"] = SYNC_SERVER.secret,
                    ["Content-Type"] = "application/json",
                    ["Accept"] = "application/json",
                },
                Body = json,
            })
            return res ~= nil and res.StatusCode == 200
        end

        function SHV.serverDisconnect()
            local s = srv.sock
            srv.sock, srv.connected, srv.job = nil, false, nil
            if s then pcall(function() s:Close() end) end
        end

        -- Konek ke Reverb (protokol Pusher) dan subscribe channel per server Roblox (JobId)
        function SHV.serverConnect()
            if not (SYNC_SERVER.enabled and SYNC_SERVER.secret ~= "" and SYNC_SERVER.appKey ~= "" and WebSocket) then
                return false
            end
            if srv.connected and srv.job == game.JobId then return true end
            if os.clock() - srv.lastTry < math.min(60, 5 * (2 ^ srv.failCount)) then return false end
            srv.lastTry = os.clock()
            SHV.serverDisconnect()
            local ok, sock = pcall(WebSocket.connect, SYNC_SERVER.ws .. SYNC_SERVER.appKey .. "?protocol=7&client=syshub&version=1")
            if not ok or not sock then
                srv.failCount = math.min(srv.failCount + 1, 4)
                return false
            end
            srv.sock = sock
            local job = game.JobId
            local channel = "syshub-sync." .. job
            pcall(function()
                sock.OnMessage:Connect(function(raw)
                    if srv.sock ~= sock or not SHV.running then return end
                    local okD, msg = pcall(HttpService.JSONDecode, HttpService, raw)
                    if not okD or type(msg) ~= "table" then return end
                    local ev = msg.event
                    if ev == "pusher:connection_established" then
                        pcall(function()
                            sock:Send(HttpService:JSONEncode({ event = "pusher:subscribe", data = { channel = channel } }))
                        end)
                    elseif ev == "pusher_internal:subscription_succeeded" then
                        srv.connected, srv.job, srv.failCount = true, job, 0
                        task.spawn(function()
                            pcall(SHV.serverSnapshot)
                            if SHV.hasSomething() or SHV.lastSentSig then pcall(SHV.serverPush) end
                        end)
                    elseif ev == "pusher:ping" then
                        pcall(function() sock:Send('{"event":"pusher:pong","data":{}}') end)
                    elseif ev == "profile" and msg.channel == channel then
                        local data = msg.data
                        if type(data) == "string" then
                            local okP, dd = pcall(HttpService.JSONDecode, HttpService, data)
                            data = okP and dd or nil
                        end
                        if data then pcall(SHV.applyServerProfile, data) end
                    end
                end)
            end)
            pcall(function()
                sock.OnClose:Connect(function()
                    if srv.sock == sock then
                        srv.sock, srv.connected, srv.job = nil, false, nil
                    end
                end)
            end)
            return true
        end

        function SHV.send()
            local w = getNativeWorld and getNativeWorld()
            if not (w and w.name and w.name ~= "" and w.name ~= "LOBBY") then return end
            local ids = SHV.myIds()
            local vsig = SHV.encode(ids)
            local title, nick = SHV.myProfile()
            local psig = SHV.encodeProfile(title, nick)
            local hasAny = #ids > 0 or title ~= nil or nick ~= nil
            -- Belum pernah kirim apa-apa & tidak ada yang di-share -> tidak perlu kirim
            if not hasAny and SHV.lastSentSig == nil then return end
            -- Jalur utama: server SysHub (tanpa batas chat). Gagal -> lanjut ke chat kode.
            if SHV.serverReady() and SHV.serverPush() then
                SHV.lastSend = os.clock()
                SHV.lastSentSig = hasAny and (vsig .. "|" .. psig) or nil
                return
            end
            local TCS = game:GetService("TextChatService")
            local wc = TCS:FindFirstChild("WorldChannels")
            local ch = wc and (wc:FindFirstChild(w.name) or wc:FindFirstChild(tostring(w.name):upper()))
            if not (ch and ch:IsA("TextChannel")) and wc then
                for _, c in ipairs(wc:GetChildren()) do
                    if c:IsA("TextChannel") then ch = c break end
                end
            end
            if not ch then return end
            SHV.lastSend = os.clock()
            SHV.lastSentSig = hasAny and (vsig .. "|" .. psig) or nil
            -- Satu pesan berisi 2 blok tersembunyi: visual (shv1) + profil nick/title (shp2, ter-encode)
            local msg = SHV.PREFIX .. vsig .. "}`{shp2:" .. psig .. "}"
            task.spawn(function()
                pcall(ch.SendAsync, ch, msg)
            end)
        end

        -- Debounce + jarak minimal antar kirim (server: 1.5 dtk, chat: 4 dtk rate limit Roblox)
        function SHV.requestAnnounce(delay)
            if SHV.pending or not SHV.running then return end
            SHV.pending = true
            local gap = SHV.serverReady() and 1.5 or 4
            local wait = math.max(delay or 1, gap - (os.clock() - SHV.lastSend))
            task.delay(wait, function()
                SHV.pending = false
                if SHV.running then pcall(SHV.send) end
            end)
        end

        function SHV.onIncoming(uid, ids, sig)
            local prev = SHV.remote[uid]
            if #ids == 0 then
                SHV.remote[uid] = nil
                if prev then SHV.forEachPeerOf(uid, SHV.revertPeer) end
            else
                SHV.remote[uid] = { ids = ids, sig = sig }
                if SHV.isEnabled() then
                    SHV.forEachPeerOf(uid, function(p) SHV.applyPeer(p, ids, sig) end)
                end
            end
        end

        -- Pengguna SysHub baru ketemu: balas sekali supaya dia juga lihat visual/nick/title kita
        function SHV.markKnown(uid)
            if not SHV.known[uid] then
                SHV.known[uid] = true
                SHV.requestAnnounce(1.5)
            end
        end

        pcall(function()
            local TCS = game:GetService("TextChatService")
            SHV.conn = TCS.MessageReceived:Connect(function(m)
                if not SHV.running then return end
                local src = m.TextSource
                local lp = Players.LocalPlayer
                if not src or not lp or src.UserId == lp.UserId then return end
                local txt = m.Text
                if type(txt) ~= "string" or not txt:find("`{sh", 1, true) then return end
                local uid = tostring(src.UserId)
                local any = false
                local payload = txt:match("`{shv1:(%a*)}")
                if payload then
                    local ids = SHV.decode(payload)
                    if ids then
                        any = true
                        SHV.onIncoming(uid, ids, payload)
                    end
                end
                local okP, title, nick = SHV.parseProfile(txt)
                if okP then
                    any = true
                    SHV.onProfile(uid, title, nick)
                end
                if any then SHV.markKnown(uid) end
            end)
        end)

        -- Kalau pemain itu ganti baju asli (paket look dari server), tempel ulang override-nya
        pcall(function()
            if Net and Net.look and type(Net.look.listen) == "function" then
                SHV._myListener = function(pkt)
                    if not SHV.running or type(pkt) ~= "table" then return end
                    task.defer(function()
                        local tools = SHV.tools()
                        local p = tools and tools.peers[pkt.id]
                        local r = p and SHV.remote[tostring(p.userId)]
                        if p and r and SHV.isEnabled() then SHV.applyPeer(p, r.ids, r.sig) end
                    end)
                end
                Net.look.listen(SHV._myListener)
            end
        end)

        -- Watcher: pasang ulang untuk pemain yang baru join/respawn, deteksi pindah world & pemain baru
        task.spawn(function()
            while SHV.running do
                task.wait(1.5)
                pcall(function()
                    local w = getNativeWorld and getNativeWorld()
                    local wname = (w and w.name) or ""
                    if wname ~= SHV.world then
                        SHV.world = wname
                        for uid in pairs(SHV.profiles) do SHV.dropProfile(uid) end
                        SHV.known, SHV.seenPeers, SHV.remote = {}, {}, {}
                        SHV.lastSentSig = nil
                        if wname ~= "" and wname ~= "LOBBY" then
                            SHV.requestAnnounce(3)
                            if SHV.serverReady() then task.spawn(SHV.serverSnapshot) end
                        end
                    end
                    -- Server sync: (re)connect di thread terpisah (connect bisa nge-yield lama), dengan backoff
                    if not SHV.serverReady() and not srv.connecting then
                        srv.connecting = true
                        task.spawn(function()
                            pcall(SHV.serverConnect)
                            srv.connecting = false
                        end)
                    end
                    -- Heartbeat: profil di server kadaluarsa 15 menit tanpa update
                    if SHV.serverReady() and SHV.hasSomething() and (os.clock() - SHV.lastSend) > 300 then
                        SHV.requestAnnounce(0.5)
                    end
                    -- Jaga nick/title tetap terpasang (server bisa menimpa atribut kapan saja)
                    for uid in pairs(SHV.profiles) do
                        if Players:GetPlayerByUserId(tonumber(uid) or 0) then
                            pcall(SHV.enforceProfile, uid)
                        else
                            SHV.profiles[uid] = nil -- sudah keluar server
                            Proxy.remoteNicks[uid] = nil
                        end
                    end
                    local tools = SHV.tools()
                    if not tools then return end
                    local newPeer = false
                    for _, p in pairs(tools.peers) do
                        if type(p) == "table" and not p.npc and p.userId then
                            local uid = tostring(p.userId)
                            if not SHV.seenPeers[uid] then
                                SHV.seenPeers[uid] = true
                                newPeer = true
                            end
                            local r = SHV.remote[uid]
                            if r and SHV.isEnabled() then
                                local rec = SHV.applied[p]
                                if not (rec and rec.ver == p.lookVer and rec.sig == r.sig) then
                                    SHV.applyPeer(p, r.ids, r.sig)
                                end
                            end
                        end
                    end
                    -- (lewat server tidak perlu: pemain baru ambil snapshot sendiri)
                    if newPeer and SHV.hasSomething() and not SHV.serverReady() then SHV.requestAnnounce(2.5) end
                end)
            end
        end)

        function SHV.revertAll()
            for uid in pairs(SHV.profiles) do pcall(SHV.enforceProfile, uid) end
            local tools = SHV.tools()
            if not tools then return end
            for _, p in pairs(tools.peers) do
                if type(p) == "table" and SHV.applied[p] then SHV.revertPeer(p) end
            end
        end

        function SHV.stop()
            SHV.running = false
            pcall(SHV.serverDisconnect)
            if SHV.conn then pcall(function() SHV.conn:Disconnect() end) end
            pcall(SHV.revertAll)
            Proxy.remoteNicks = {}
        end

        SysHubVisual.sync = SHV
        SysHubVisual.syncChanged = function()
            SHV.requestAnnounce(1.2)
        end
        SysHubVisual.toggleSync = function()
            SysHubVisual.loadConfig()
            if SHV.isEnabled() then
                SysHubVisual.config.share = false
                SysHubVisual.saveConfig()
                SHV.revertAll()
                SHV.requestAnnounce(0.5) -- kirim "kosong" supaya yang lain balik normal
                Proxy.notify("`4[Sync] Sync visual + nick + title antar SysHub: OFF``")
            else
                SysHubVisual.config.share = true
                SysHubVisual.saveConfig()
                SHV.revertAll() -- (enforce ulang dengan sync ON = pasang lagi nick/title yang tersimpan)
                SHV.requestAnnounce(0.5)
                Proxy.notify("`2[Sync] Sync visual + nick + title antar SysHub: ON (sesama SysHub saling lihat)``")
            end
        end
    end

    -- 3. VISUAL DIALOG UI CREATION
    SysHubVisual.createDialog = function()
        if SysHubVisual.dialog and SysHubVisual.dialog.Parent then
            return SysHubVisual.dialog
        end

        local screenW = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 800
        local screenH = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.Y) or 600
        local dlgW = math.clamp(480, 320, screenW - 20)
        local dlgH = math.clamp(390, 280, screenH - 20)

        local dlg = Instance.new("Frame")
        dlg.Name = "SysHubVisualDialog"
        dlg.Visible = false
        dlg.Size = UDim2.fromOffset(dlgW, dlgH)
        dlg.Position = UDim2.fromScale(0.5, 0.5)
        dlg.AnchorPoint = Vector2.new(0.5, 0.5)
        dlg.BackgroundColor3 = Color3.fromRGB(15, 26, 32)
        dlg.BorderSizePixel = 0
        dlg.ClipsDescendants = true
        dlg.ZIndex = 60
        dlg.Parent = SG
        corner(dlg, 12)

        local stroke = Instance.new("UIStroke", dlg)
        stroke.Color = Color3.fromRGB(75, 255, 255)
        stroke.Thickness = 2.0
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        -- Header Bar (Draggable)
        local header = Instance.new("Frame", dlg)
        header.Name = "Header"
        header.Size = UDim2.new(1, 0, 0, 42)
        header.Position = UDim2.new(0, 0, 0, 0)
        header.BackgroundColor3 = Color3.fromRGB(22, 42, 52)
        header.BorderSizePixel = 0
        header.ZIndex = 61
        corner(header, 12)

        local headerIcon = Instance.new("TextLabel", header)
        headerIcon.Size = UDim2.fromOffset(26, 26)
        headerIcon.Position = UDim2.new(0, 10, 0.5, 0)
        headerIcon.AnchorPoint = Vector2.new(0, 0.5)
        headerIcon.BackgroundTransparency = 1
        headerIcon.Text = "👔"
        headerIcon.TextSize = 18
        headerIcon.ZIndex = 62

        local titleLbl = Instance.new("TextLabel", header)
        titleLbl.Size = UDim2.new(1, -90, 0, 20)
        titleLbl.Position = UDim2.new(0, 42, 0, 4)
        titleLbl.BackgroundTransparency = 1
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.Text = "SYSHUB VISUAL WARDROBE"
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.TextSize = 13
        titleLbl.TextXAlignment = Enum.TextXAlignment.Left
