                slotL.TextColor3 = Color3.fromRGB(80, 215, 245)
                slotL.Text = string.format("[%s] - ID: %d", it.slot:upper(), it.id)
                slotL.Font = Enum.Font.Gotham
                slotL.TextSize = 10
                slotL.TextXAlignment = Enum.TextXAlignment.Left
                slotL.ZIndex = 63

                -- Wear Button
                local btnWear = Instance.new("TextButton", row)
                btnWear.Size = UDim2.fromOffset(72, 28)
                btnWear.Position = UDim2.new(1, -135, 0.5, 0)
                btnWear.AnchorPoint = Vector2.new(0, 0.5)
                btnWear.BackgroundColor3 = isEquipped and Color3.fromRGB(46, 160, 67) or Color3.fromRGB(38, 115, 140)
                btnWear.BorderSizePixel = 0
                btnWear.Text = isEquipped and "EQUIPPED" or "WEAR"
                btnWear.TextColor3 = Color3.fromRGB(255, 255, 255)
