    -- =========================================================================
    -- 4. SYS_HUB WEATHER CONTROLLER & DIALOG
    -- =========================================================================
    SysHubWeather.getWeathers = function()
        if SysHubWeather.weathers then return SysHubWeather.weathers end
        local db = resolveItemDB()
        if not db then return {} end
        local list = {}
        -- 0. Default World Weather
        table.insert(list, {
            id = 0,
            name = "Default / World Native Weather",
            isDefault = true
        })

        local priorityIds = {932, 934, 946, 984, 1210, 1364, 1490, 1750, 2046, 2284, 2744, 3252, 3446, 3534, 3694, 6854, 7644, 8836, 8896, 10058, 10286, 11880, 13070, 13640, 13690, 14032, 14094, 14598, 15150, 15240, 15764, 15802, 15860, 16094, 16282, 16406}
        local seen = {}
        for _, pid in ipairs(priorityIds) do
            local it = db[pid]
            if it and it.weather then
                local cleanName = it.name:gsub("^Weather Machine %- ", ""):gsub("^Draconic Weather Machine %- ", ""):gsub("^Neptune's Weather Machine %- ", "")
                table.insert(list, { id = pid, name = cleanName, rawName = it.name })
                seen[pid] = true
            end
        end

        for id, it in pairs(db) do
            if type(it) == "table" and it.weather == true and not seen[id] and not it.name:find("Seed") then
                local cleanName = it.name:gsub("^Weather Machine %- ", ""):gsub("^Draconic Weather Machine %- ", ""):gsub("^Neptune's Weather Machine %- ", "")
                table.insert(list, { id = id, name = cleanName, rawName = it.name })
                seen[id] = true
            end
        end

        SysHubWeather.weathers = list
        return list
    end

    SysHubWeather.applyWeather = function(targetId)
        local eng, w = getNativeEngine()
        w = w or (eng and eng.world) or (getNativeWorld and getNativeWorld())
        if not w then return end

        local origDrawWeather = w._origDrawWeather or w.drawWeather

        local backdrop = eng and eng.backdrop
        local World = eng and eng.worldFrame
        local UIScale = eng and eng.tilesLayer and eng.tilesLayer.Parent and eng.tilesLayer.Parent:FindFirstChildWhichIsA("UIScale")
        local TileSize = (eng and eng.Assets and eng.Assets.TileSize) or (Assets and Assets.TileSize) or 32
        local u4051 = 1

        if origDrawWeather and debug and debug.getupvalues then
            local ok, ups = pcall(debug.getupvalues, origDrawWeather)
            if ok and ups and #ups >= 6 then
                backdrop = backdrop or ups[3]
                World = World or ups[4]
                u4051 = tonumber(ups[5]) or u4051
                UIScale = UIScale or ups[6]
                TileSize = tonumber(ups[7]) or TileSize
            end
        end

        local function setBackdropHidden(hidden)
            if backdrop then
                if backdrop.setHidden then
                    pcall(backdrop.setHidden, backdrop, hidden)
                end
                backdrop.hidden = hidden
            end
        end

        if not targetId or targetId == 0 then
            -- Reset to native
            if w._origDrawWeather then
                w.drawWeather = w._origDrawWeather
                w._origDrawWeather = nil
            end
            if w.weatherFx and w.weatherFx.set then
                pcall(w.weatherFx.set, w.weatherFx, nil)
            end
            setBackdropHidden(false)
            return
        end

        w._origDrawWeather = origDrawWeather

        if w.weatherFx and w.weatherFx.set then
            pcall(w.weatherFx.set, w.weatherFx, targetId)
            setBackdropHidden(true)
        end

        w.drawWeather = function(a1, a2, a3)
            if w.weatherFx then
                if w.weatherFx.id ~= targetId and w.weatherFx.set then
                    pcall(w.weatherFx.set, w.weatherFx, targetId)
                    setBackdropHidden(true)
                end
                local absSize = (World and World.AbsoluteSize) or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(800, 600)
                local scale = (UIScale and UIScale.Scale) or 1
                local uScale = (u4051 or 1) * scale
                if uScale <= 0 then uScale = 1 end
                local worldW = tonumber(w.w) or 100
                local v2 = (worldW / 2 - absSize.X / 2 / uScale) * (TileSize or 32)
                pcall(w.weatherFx.update, w.weatherFx, a1, a2, absSize, (a3 or 1) * (TileSize or 32), v2)
            end
        end
    end

    SysHubWeather.set = function(targetId)
        SysHubVisual.loadConfig()
        if not targetId or targetId == 0 then
            SysHubVisual.config.weather = nil
            SysHubVisual.saveConfig()
            SysHubWeather.applyWeather(0)
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify("`4[Weather] Cuaca di-reset ke cuaca asli world!``")
        else
            SysHubVisual.config.weather = targetId
            SysHubVisual.saveConfig()
            SysHubWeather.applyWeather(targetId)
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            local db = resolveItemDB()
            local wName = (db and db[targetId] and db[targetId].name) or ("Weather #" .. tostring(targetId))
            Proxy.notify(string.format("`2[Weather] Cuaca berhasil diubah ke: %s (Client Only)``", wName))
        end
        if SysHubWeather.refreshList then SysHubWeather.refreshList() end
    end

    SysHubWeather.applyByQuery = function(query)
        query = query:lower()
        if query == "reset" or query == "default" or query == "normal" or query == "off" then
            SysHubWeather.set(0)
            return
        end
        local num = tonumber(query)
        if num then
            SysHubWeather.set(num)
            return
        end
        local weathers = SysHubWeather.getWeathers()
        for _, w in ipairs(weathers) do
            if not w.isDefault and w.name:lower():find(query, 1, true) then
                SysHubWeather.set(w.id)
                return
            end
        end
        Proxy.notify("`4[Weather] Cuaca '" .. query .. "' tidak ditemukan! Ketik /weather untuk melihat list.``")
    end

    SysHubWeather.autoRestore = function()
        SysHubVisual.loadConfig()
        if SysHubVisual.config.weather then
            SysHubWeather.applyWeather(SysHubVisual.config.weather)
        end
    end

