    -- =========================================================================
    -- 5. SYS_HUB TITLE CONTROLLER (CLIENT-SIDE ALL TITLES UNLOCKED & WEARABLE)
    -- =========================================================================
    SysHubTitle.getRoles = function()
        local Shared = game:GetService("ReplicatedStorage")
        local qz = Shared:GetAttribute("Qz")
        local modTable = qz and shared[qz]
        local Roles = modTable and modTable.si2Za6GXUIg and require(modTable.si2Za6GXUIg)
        if not Roles and filtergc then
            local rList = filtergc("table", { Keys = {"isDeveloper", "isStaff", "TITLES"} }, false)
            if rList and rList[1] then Roles = rList[1] end
        end
        return Roles
    end

    SysHubTitle.unlock = function()
        local lp = Players.LocalPlayer
        if not lp then return end

        -- 1. Setup TitleState in PlayerGui (game native source for owned titles)
        local pgui = lp:FindFirstChild("PlayerGui")
        if pgui then
            local ts = pgui:FindFirstChild("TitleState") or Instance.new("Configuration", pgui)
            ts.Name = "TitleState"
            ts:SetAttribute("Titles", "supporter patron benefactor sponsor cc royal dr legend")
        end

        -- 2. Unlock DrTitle and Legend on LocalPlayer attributes
        lp:SetAttribute("DrTitle", true)
        lp:SetAttribute("HasLegend", true)

        -- 3. Hook Roles.titlesOf to guarantee all titles returned for LocalPlayer
        local Roles = SysHubTitle.getRoles()
        if Roles and not Roles._syshubTitlesHooked then
            Roles._syshubTitlesHooked = true
            local fullTitleKeys = {"supporter", "patron", "benefactor", "sponsor", "cc", "royal", "dr"}
            local oldTitlesOf = Roles.titlesOf
            Roles.titlesOf = function(uid)
                if not uid or (lp and uid == lp.UserId) then
                    return fullTitleKeys
                end
                if oldTitlesOf then return oldTitlesOf(uid) end
                return {}
            end
        end

        -- 4. Hook Network Remote PickTitle so clicking in native Title dialog sets worn title immediately
        local Shared = game:GetService("ReplicatedStorage")
        local qz = Shared:GetAttribute("Qz")
        local modTable = qz and shared[qz]
        local NetMod = modTable and modTable.j1PKXTgzz and require(modTable.j1PKXTgzz)
        if not NetMod and filtergc then
            local nList = filtergc("table", { Keys = {"call", "bind"} }, false)
            if nList and nList[1] then NetMod = nList[1] end
        end
        if NetMod and NetMod.call and not NetMod._syshubTitleHooked then
            NetMod._syshubTitleHooked = true
            local oldCall = NetMod.call
            NetMod.call = function(name, ...)
                if name == "PickTitle" then
                    local chosen = ...
                    pcall(function()
                        SysHubTitle.set(chosen, true)
                    end)
                end
                return oldCall(name, ...)
            end
        end
    end

    SysHubTitle.set = function(titleKey, fromUI)
        local lp = Players.LocalPlayer
        if not lp then return end

        titleKey = tostring(titleKey or "none"):lower():match("^%s*(.-)%s*$")
        if titleKey == "reset" or titleKey == "off" or titleKey == "clear" or titleKey == "" or titleKey == "notitle" then
            titleKey = "none"
        end

        -- Pastikan semua title telah ter-unlock di memory client
        SysHubTitle.unlock()

        -- Set attribute WornTitle
        if titleKey == "legend" then
            lp:SetAttribute("HasLegend", true)
            lp:SetAttribute("WornTitle", "none")
        else
            lp:SetAttribute("WornTitle", titleKey)
            if titleKey == "dr" then
                lp:SetAttribute("DrTitle", true)
            end
        end

        -- Trigger drawName nametag update game dengan menyentuh attribute OwnTitle
        local curOwn = lp:GetAttribute("OwnTitle")
        lp:SetAttribute("OwnTitle", (curOwn == " " and "" or " "))

        -- Simpan ke konfigurasi visual
        SysHubVisual.loadConfig()
        SysHubVisual.config.title = (titleKey ~= "none" and titleKey or nil)
        SysHubVisual.saveConfig()
        if SysHubVisual.syncChanged then pcall(SysHubVisual.syncChanged) end

        if not fromUI then
            local display = titleKey
            for _, t in ipairs(SysHubTitle.allTitles) do
                if t.key == titleKey then display = t.name break end
            end
            if titleKey == "none" then display = "No Title (Dilepas)" end
            Proxy.notify(string.format("`2[Title] Berhasil memakai title: %s``", display))
        end
    end

    SysHubTitle.autoRestore = function()
        SysHubTitle.unlock()
        SysHubVisual.loadConfig()
        if SysHubVisual.config.title then
            SysHubTitle.set(SysHubVisual.config.title, true)
        end
    end

    SysHubTitle.openMenu = function()
        local opened = false
        if filtergc then
            local eList = filtergc("table", { Keys = {"openProfile"} }, false)
            if eList and eList[1] and eList[1].openProfile then
                pcall(eList[1].openProfile)
                opened = true
            end
        end
        if not opened then
            Proxy.notify("`2[Title] Semua Title Unlocked! Buka menu Profile -> Title untuk memilih, atau gunakan chat /title [nama]``")
        end
    end


