    -- =========================================================================
    -- =========================================================================
    -- 6. SYS_HUB WELCOME UI & NATIVE GAZETTE INTEGRATION (/news, /about, /welcome)
    -- =========================================================================
    local SysHubWelcome = {
        dialog = nil,
        overlay = nil,
        panel = nil,
        page = nil,
        body = nil,
        currentTab = "about",
        isFirstLaunch = true,
        bannerAsset = nil,
        logoAsset = nil,
        discordOnline = "560+ Online",
        discordTotal = "20,578+ Members",
        fetchedDiscord = false,
        bannerImgRef = nil,
        statOnlineRef = nil,
        statTotalRef = nil,
        tabButtons = {},
    }
    _G.SysHubWelcome = SysHubWelcome

    local BANNER_FILE = "syshub_banner.png"
    local BANNER_URL = "https://syshub.my.id/SysBannerGT.png"
    local LOGO_FILE = "syshub_logo.jpg"
    local PLANS_URL = "https://syshub.my.id/#plans"

    SysHubWelcome.loadAssets = function()
        if not SysHubWelcome.bannerAsset then
            if isfile and isfile(BANNER_FILE) and getcustomasset then
                local ok, aid = pcall(getcustomasset, BANNER_FILE)
                if ok and aid then SysHubWelcome.bannerAsset = aid end
            end
        end
        if not SysHubWelcome.bannerAsset and writefile and getcustomasset then
            task.spawn(function()
                local raw = nil
                if game and game.HttpGet then
                    local ok, res = pcall(game.HttpGet, game, BANNER_URL)
                    if ok and res and #res > 5000 then raw = res end
                elseif request then
                    local ok, res = pcall(request, { Url = BANNER_URL, Method = "GET" })
                    if ok and res and res.Body and #res.Body > 5000 then raw = res.Body end
                end
                if raw then
                    pcall(writefile, BANNER_FILE, raw)
                    local ok, aid = pcall(getcustomasset, BANNER_FILE)
                    if ok and aid then
                        SysHubWelcome.bannerAsset = aid
                        if SysHubWelcome.bannerImgRef and SysHubWelcome.bannerImgRef.Parent then
                            SysHubWelcome.bannerImgRef.Image = aid
                        end
                    end
                end
            end)
        end

        if not SysHubWelcome.logoAsset then
            if isfile and isfile(LOGO_FILE) and getcustomasset then
                local ok, aid = pcall(getcustomasset, LOGO_FILE)
                if ok and aid then SysHubWelcome.logoAsset = aid end
            end
        end
        return SysHubWelcome.bannerAsset, SysHubWelcome.logoAsset
    end

    SysHubWelcome.fetchDiscordStats = function()
        if SysHubWelcome.fetchedDiscord then return end
        task.spawn(function()
            local urls = {
                "https://discord.com/api/v9/invites/zYeRjW6bZ?with_counts=true",
                "https://discord.com/api/v10/invites/zYeRjW6bZ?with_counts=true"
            }
            for _, u in ipairs(urls) do
                local body = nil
                if game and game.HttpGet then
                    local ok, res = pcall(game.HttpGet, game, u)
                    if ok and res and #res > 10 then body = res end
                elseif request then
                    local ok, res = pcall(request, { Url = u, Method = "GET" })
                    if ok and res and res.Body and #res.Body > 10 then body = res.Body end
                end
                if body then
                    local online = body:match('"approximate_presence_count"%s*:%s*(%d+)')
                    local total = body:match('"approximate_member_count"%s*:%s*(%d+)')
                    if online and total then
                        local sOnline = string.gsub(string.reverse((string.gsub(string.reverse(tostring(online)), "(%d%d%d)", "%1,"))), "^,", "")
                        local sTotal = string.gsub(string.reverse((string.gsub(string.reverse(tostring(total)), "(%d%d%d)", "%1,"))), "^,", "")
                        SysHubWelcome.discordOnline = sOnline .. " Online"
                        SysHubWelcome.discordTotal = sTotal .. " Members"
                        SysHubWelcome.fetchedDiscord = true
                        if SysHubWelcome.statOnlineRef and SysHubWelcome.statOnlineRef.set then
                            SysHubWelcome.statOnlineRef:set("`2ONLINE:`` `w" .. SysHubWelcome.discordOnline .. "``")
                        end
                        if SysHubWelcome.statTotalRef and SysHubWelcome.statTotalRef.set then
                            SysHubWelcome.statTotalRef:set("`9MEMBERS:`` `w" .. SysHubWelcome.discordTotal .. "``")
                        end
                        break
                    end
                end
            end
        end)
    end

    SysHubWelcome.createDialog = function()
        if SysHubWelcome.dialog and SysHubWelcome.dialog.Parent then
            return SysHubWelcome.dialog
        end

        SysHubWelcome.loadAssets()

        -- Native Gazette Layer / Overlay (Darkened Backdrop)
        local overlay = Instance.new("Frame")
        overlay.Name = "SysHubWelcomeOverlay"
        overlay.Active = true
        overlay.BackgroundColor3 = Color3.new(0, 0, 0)
        overlay.BackgroundTransparency = 0.45
        overlay.BorderSizePixel = 0
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.ZIndex = 80
        overlay.Visible = false
        overlay.Parent = SG
        SysHubWelcome.overlay = overlay

        -- Compact Native Gazette Main Panel (820 x 540)
        local panel = Instance.new("Frame")
        panel.Name = "SysHubWelcomePanel"
        panel.Active = true
        panel.BackgroundColor3 = C.box
        panel.BackgroundTransparency = 0.08
        panel.BorderSizePixel = 0
        panel.AnchorPoint = Vector2.new(0.5, 0.5)
        panel.Position = UDim2.fromScale(0.5, 0.5)
        panel.Size = UDim2.fromOffset(820, 540)
        panel.ZIndex = 81
        panel.Parent = overlay
        SysHubWelcome.panel = panel

        corner(panel, 6)
        dialogBorder(panel)

        -- Responsive Scale (82% of viewport, stays compact on PC and fits Mobile smoothly)
        local uiscale = Instance.new("UIScale", panel)
        local function updateScale()
            local cam = workspace.CurrentCamera
            local vp = (cam and cam.ViewportSize) or Vector2.new(1920, 1080)
            local s = math.clamp(math.min((vp.X * 0.82) / 820, (vp.Y * 0.82) / 540), 0.38, 1.0)
            uiscale.Scale = s
        end
        updateScale()
        if workspace.CurrentCamera then
            workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(updateScale)
        end

        -- Top Header: Logo Icon & Clear Separated Title / Subtitle
        local headerContainer = Instance.new("Frame", panel)
        headerContainer.Name = "HeaderContainer"
        headerContainer.BackgroundTransparency = 1
        headerContainer.AnchorPoint = Vector2.new(0.5, 0)
        headerContainer.Position = UDim2.new(0.5, 0, 0, 10)
        headerContainer.Size = UDim2.fromOffset(500, 68)
        headerContainer.ZIndex = 82

        local logoFrame = Instance.new("Frame", headerContainer)
        logoFrame.Name = "LogoFrame"
        logoFrame.BackgroundColor3 = Color3.fromRGB(12, 110, 240)
        logoFrame.BorderSizePixel = 0
        logoFrame.AnchorPoint = Vector2.new(0, 0.5)
