    SysHubWelcome.renderContent = function()
        if not SysHubWelcome.page then return end
        local page = SysHubWelcome.page
        page:ClearAllChildren()

        local body = Instance.new("Frame", page)
        body.Name = "Body"
        body.BackgroundTransparency = 1
