        local curY = 12

        local function done()
            body.Size = UDim2.new(1, -16, 0, curY + 12)
            page.CanvasSize = UDim2.fromOffset(0, curY + 12)
            page.CanvasPosition = Vector2.zero
        end

        local function line(parent, text, size, x, y, col, wrap)
            return makeLabel(parent, text, size, UDim2.fromOffset(x, y), {
                color = col,
                wrap = wrap
            })
        end

        local function heading(text, col)
            local v1 = line(body, text, 28, 12, curY, col or Color3.fromRGB(75, 255, 255))
            curY = curY + (v1.height or 26) + 10
        end

        local function card(icon, title, desc, fixedHeight)
            local Frame = Instance.new("Frame", body)
