    SysHubWelcome.open = function(tab)
        local dlg = SysHubWelcome.createDialog()
        if tab and type(tab) == "string" then
            tab = tab:lower()
            if tab == "feature" or tab == "features" then SysHubWelcome.currentTab = "features"
            elseif tab == "shop" or tab == "store" or tab == "buy" then SysHubWelcome.currentTab = "shop"
            elseif tab == "update" or tab == "updates" or tab == "logs" or tab == "changelog" then SysHubWelcome.currentTab = "updates"
            else SysHubWelcome.currentTab = "about" end
        end
        if SysHubWelcome.tabButtons then
            for k, b in pairs(SysHubWelcome.tabButtons) do
                b.BackgroundColor3 = (SysHubWelcome.currentTab == k) and C.green or C.button
            end
        end
        SysHubWelcome.renderContent()
        if Sfx and Sfx.play then pcall(Sfx.play, "dialog_open") end
        dlg.Visible = true
    end

    SysHubWelcome.close = function()
        if SysHubWelcome.overlay then
            if Sfx and Sfx.play then pcall(Sfx.play, "dialog_close") end
            SysHubWelcome.overlay.Visible = false
        end
    end

    chatTableRef.onCommand = function(msg)
        if type(msg) ~= "string" then
            if origOnCommand and origOnCommand ~= chatTableRef.onCommand then
                return origOnCommand(msg)
            end
            return true
        end

        local trimmed = msg:match("^%s*(.-)%s*$")
        local cmd, rest = trimmed:match("^/(%S+)%s*(.*)$")
        if not cmd then
            if origOnCommand and origOnCommand ~= chatTableRef.onCommand then
                return origOnCommand(msg)
            end
            return true
        end

        cmd = cmd:lower()
        local args = {}
        for a in rest:gmatch("%S+") do
            table.insert(args, a)
        end

        -- 1. PROXY GUI TOGGLE / TAB SWITCH
        if cmd == "proxy" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("proxy") end
            return true
        end

        if cmd == "rotation" or cmd == "rot" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("rotation") end
            return true
        end

        if cmd == "event" or cmd == "autoevent" or cmd == "burn" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("event") end
            return true
        end

        if cmd == "shop" or cmd == "store" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("shop") end
            return true
        end

        if cmd == "farm" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("farm") end
            return true
        end

        if cmd == "factory" or cmd == "fac" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("factory") end
            return true
        end

        if cmd == "world" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("world") end
            return true
        end

        if cmd == "player" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("player") end
            return true
        end

        if cmd == "spam" then
            if openMainDialog then openMainDialog() end
            if switchTab then switchTab("spam") end
            return true
        end

        if cmd == "gs" or cmd == "growscan" then
            pcall(function()
                local w = getNativeWorld()
                if w and w.growScan and w.growScan.open then
                    w.growScan.open({
                        item = 3120,
                        owner = true,
                        blocksPublic = true,
                        floatingPublic = true,
                    }, function(...) end)
                else
                    local curr = getInventoryUICurrent()
                    if curr and curr.onSay then
                        curr.onSay("`4[SysHub] GrowScan bawaan tidak dapat dibuka di world ini!``")
                    end
                end
            end)
            return true
        end

        if cmd == "zoom" then
            local targetVal = tonumber(args[1])
            if targetVal then
                if targetVal > 5 then
                    targetVal = targetVal / 100
                end
                CameraZoom.enabled = true
                CameraZoom.zoomScale = math.clamp(targetVal, 0.08, 2.0)
            else
                CameraZoom.enabled = not CameraZoom.enabled
            end
            if CameraZoom.apply then CameraZoom.apply() end
            if CameraZoom.updateUI then CameraZoom.updateUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            pcall(function()
                local curr = getInventoryUICurrent()
                if curr and curr.onSay then
                    curr.onSay(string.format("`c[SysHub] Native Camera Zoom: %s (Scale: %.2f)``", CameraZoom.enabled and "ON (Unlocked)" or "OFF (Default)", CameraZoom.zoomScale))
                end
            end)
            return true
        end

        if cmd == "antistaff" then
            AntiStaff.enabled = not AntiStaff.enabled
            if AntiStaff.scan then AntiStaff.scan() end
            if AntiStaff.updateUI then AntiStaff.updateUI() end
            if Proxy and Proxy.saveConfig then pcall(Proxy.saveConfig) end
            pcall(function()
                local curr = getInventoryUICurrent()
                if curr and curr.onSay then
                    curr.onSay(string.format("`c[SysHub] Anti-Staff Protection: %s``", AntiStaff.enabled and "ON" or "OFF"))
                end
            end)
            return true
        end

        -- 2. CASINO COMMANDS
        if cmd == "fastwheel" or cmd == "fwheel" or cmd == "fastroulette" then
            Proxy.fastRoulette = not Proxy.fastRoulette
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify(Proxy.fastRoulette and "`2[Roulette] Fast Roulette: ON (Instan Muncul Angka)``" or "`4[Roulette] Fast Roulette: OFF``")
            Proxy.saveConfig()
            Proxy.updateUI()
            return true
        end

        if cmd == "rdetect" or cmd == "fakecheck" or cmd == "roulettedetect" then
            Proxy.rouletteDetector = not Proxy.rouletteDetector
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify(Proxy.rouletteDetector and "`2[Roulette] Deteksi Real/Fake Roulette: ON``" or "`4[Roulette] Deteksi Real/Fake Roulette: OFF``")
            Proxy.saveConfig()
            Proxy.updateUI()
            return true
        end

        if cmd == "lastwheel" or cmd == "lastspin" or cmd == "rinfo" then
            if Proxy._lastRealSpin then
                local sp = Proxy._lastRealSpin
                local col = (sp.n == 0 and "`2") or (sp.n <= 18 and "`b") or "`4"
                local ago = math.max(0, math.floor(os.clock() - (sp.clock or os.clock())))
                local remeVal = Proxy.calcReme and Proxy.calcReme(sp.n) or 0
                Proxy.notify(string.format("`2[Roulette] Roll: %s`*%d*`` `2[REAL]`` `eREME : %d`` | Player: %s | Pos: (%d, %d) | %d dtk lalu``",
                    col, sp.n, remeVal, (Proxy.applyNick and Proxy.applyNick(sp.name or "?")) or sp.name or "?", (sp.x or 0) + 1, (sp.y or 0) + 1, ago))
            else
                Proxy.notify("`4[Roulette] Belum ada record spin roulette asli dari server di world ini!``")
            end
            return true
        end

        local posIdx = cmd:match("^pos([1-4])$")
        if posIdx then
            local idx = tonumber(posIdx)
            local px, py = getPlayerTilePos()
            if px and py then
                local curFacing = 1
                if Proxy.onDropFn and debug and debug.getupvalue then
                    local f = debug.getupvalue(Proxy.onDropFn, 2)
                    if f == -1 or f == 1 then curFacing = f end
                end
                Proxy.casino.positions[idx] = { x = px, y = py, facing = curFacing }
                Proxy.saveConfig()
                local dirText = (curFacing == 1) and "Kanan" or "Kiri"
                Proxy.showPosMarker(idx, px, py)
                Proxy.notify(string.format("`2[Casino] Pos %d tersimpan di (X: %d, Y: %d) [Hadap: %s]``", idx, px + 1, py + 1, dirText))
                pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
                Proxy.updateUI()
            else
                Proxy.notify("`4[Casino] Gagal mendeteksi koordinat karakter!``")
            end
            return true
        end

-- /host telah dihilangkan: Titik bandar otomatis fleksibel mengikuti posisi sebelum /tp atau payout

        if cmd == "tax" then
            local rate = tonumber(args[1])
            if rate and rate >= 0 and rate <= 100 then
                Proxy.casino.taxRate = rate
                Proxy.saveConfig()
                Proxy.notify(string.format("`2[Casino] Tax diset ke: %d%%``", rate))
                Proxy.updateUI()
            else
                Proxy.notify(string.format("`o[Casino] Tax saat ini: %d%% (Format: /tax <angka>)``", Proxy.casino.taxRate))
            end
            return true
        end

        if cmd == "tp" then
            local arg1 = args[1]
            local arg2 = args[2]
            if arg1 and arg2 and tonumber(arg1) and tonumber(arg2) then
                -- /tp <x> <y>: Meluncur ke koordinat tile tertentu
                local rawX = tonumber(arg1)
                local rawY = tonumber(arg2)
                local w = getNativeWorld()
                local maxW = (w and w.w) or 100
                local maxH = (w and w.h) or 60

                -- Mendukung koordinat 1-based (sesuai tampilan UI 1..100) maupun 0-based
                local targetX = (rawX >= 1 and rawX <= maxW) and (rawX - 1) or rawX
                local targetY = (rawY >= 1 and rawY <= maxH) and (rawY - 1) or rawY
                targetX = math.clamp(math.floor(targetX), 0, maxW - 1)
                targetY = math.clamp(math.floor(targetY), 0, maxH - 1)

                task.spawn(function()
                    Proxy.casinoGlideTo(targetX, targetY)
                end)
                Proxy.notify(string.format("`2[TP] Meluncur ke koordinat (%d, %d)...``", targetX + 1, targetY + 1))
                return true
            elseif arg1 and not tonumber(arg1) then
                -- /tp <nama_player>: Meluncur ke posisi player
                local targetPlr = nil
                local searchName = arg1:lower()
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= Players.LocalPlayer then
                        if p.Name:lower():find(searchName, 1, true) or p.DisplayName:lower():find(searchName, 1, true) then
                            targetPlr = p
                            break
                        end
                    end
                end
                if targetPlr and targetPlr.Character and targetPlr.Character:FindFirstChild("HumanoidRootPart") then
                    local hrp = targetPlr.Character.HumanoidRootPart
                    local targetX = math.clamp(math.floor(hrp.Position.X / DISPLAY_SIZE), 0, 99)
                    local targetY = math.clamp(math.floor(-hrp.Position.Y / DISPLAY_SIZE), 0, 59)
                    task.spawn(function()
                        Proxy.casinoGlideTo(targetX, targetY)
                    end)
                    Proxy.notify(string.format("`2[TP] Meluncur ke player %s (%d, %d)...``", targetPlr.DisplayName, targetX + 1, targetY + 1))
                    return true
                else
                    Proxy.notify(string.format("`4[TP] Player '%s' tidak ditemukan di world!``", arg1))
                    return true
                end
            else
                -- /tp tanpa argumen: Jalankan validasi & sweep taruhan meja kasino
                task.spawn(Proxy.runCasinoCollect)
                return true
            end
        end

        -- Fleksibel win: /w1 - /w4, /win1 - /win4, /wind1 - /wind4, serta format ber-spasi (/w 1, /win 1, /wind 1 [nominal])
        local winIdx = cmd:match("^wind?([1-4])$") or cmd:match("^w([1-4])$")
        local customArg = nil
        if winIdx then
            if #args > 0 then
                customArg = table.concat(args, " ")
            end
        elseif (cmd == "win" or cmd == "wind" or cmd == "w") then
            local arg1Num = tonumber(args[1])
            if arg1Num and arg1Num >= 1 and arg1Num <= 4 then
                winIdx = arg1Num
                if #args >= 2 then
                    local sub = {}
                    for i = 2, #args do table.insert(sub, args[i]) end
                    customArg = table.concat(sub, " ")
                end
            end
        end
        if winIdx then
            local idx = tonumber(winIdx)
            local parsedAmt = customArg and Proxy.parseCurrency and Proxy.parseCurrency(customArg)
            task.spawn(function()
                Proxy.runCasinoPayout(idx, parsedAmt)
            end)
            return true
        end
        if cmd == "cinfo" then
            local pStr = {}
            for i = 1, 4 do
                local p = Proxy.casino.positions[i]
                if p then
                    local fStr = (p.facing == 1) and "Kanan" or "Kiri"
                    table.insert(pStr, string.format("P%d:(%d,%d|%s)", i, p.x + 1, p.y + 1, fStr))
                    Proxy.showPosMarker(i, p.x, p.y)
                end
            end
            local posList = #pStr > 0 and table.concat(pStr, " ") or "Belum ada pos di-set"
            local hostStr = Proxy.casino.hostPos and string.format("(%d,%d)", Proxy.casino.hostPos.x + 1, Proxy.casino.hostPos.y + 1) or "Belum di-set"
            Proxy.notify(string.format("`3[Casino Info] Host: %s | %s | Tax: %d%%``", hostStr, posList, Proxy.casino.taxRate))
            return true
        end

        if cmd == "creset" then
            Proxy.casino.positions = {}
            Proxy.casino.lastGame = nil
            Proxy.dismissCasinoBanner()
            for i = 1, 4 do
                if Proxy.activePosMarkers[i] and Proxy.activePosMarkers[i].Parent then
                    pcall(function() Proxy.activePosMarkers[i]:Destroy() end)
                    Proxy.activePosMarkers[i] = nil
                end
            end
            Proxy.saveConfig()
            Proxy.notify("`2[Casino] Semua posisi taruhan & data game berhasil di-reset!``")
            Proxy.updateUI()
            return true
        end

        -- 3. UTILITY COMMANDS
        if cmd == "warp" then
            local targetWorld = args[1]
            if targetWorld and targetWorld ~= "" then
                Proxy.lastWorldName = targetWorld
                if warpToWorld then
                    warpToWorld(targetWorld)
                elseif nativeWarp then
                    nativeWarp(targetWorld)
                end
                Proxy.notify("`2[Warp] Berpindah ke world " .. targetWorld .. "...``")
                return true
            else
                Proxy.notify("`4[Warp] Gunakan: /warp <nama world>``")
                return true
            end
        elseif cmd == "rw" then
            if Proxy.lastWorldName ~= "" then
                if warpToWorld then
                    warpToWorld(Proxy.lastWorldName)
                elseif nativeWarp then
                    nativeWarp(Proxy.lastWorldName)
                end
                Proxy.notify("`2[Re-warp] Kembali ke world " .. Proxy.lastWorldName .. "...``")
                return true
            else
                Proxy.notify("`4[Re-warp] Belum ada world sebelumnya!``")
                return true
            end
        elseif cmd == "res" then
            if Proxy.dieFn then
                Proxy.dieFn()
                Proxy.notify("`2[Respawn] Normal respawn dijalankan...``")
                return true
            end
            return true
        elseif cmd == "fpk" then
            Proxy.fastPKEnabled = not Proxy.fastPKEnabled
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify(Proxy.fastPKEnabled and "`2[Fast Wrench] Diaktifkan (LMB = Pull, RMB = Kick)``" or "`4[Fast Wrench] Dimatikan``")
            Proxy.saveConfig()
            Proxy.updateUI()
            return true
        elseif cmd == "scale" or cmd == "uiscale" then
            local targetMode = args[1]
            if not targetMode or targetMode == "" then
                cycleUIScaleMode()
                Proxy.notify("`2[UI Scale] Mode: " .. tostring(uiScaleMode) .. " (" .. math.floor(getActiveUIScale() * 100 + 0.5) .. "%)``")
                return true
            end
            targetMode = targetMode:lower()
            if targetMode == "auto" then
                setUIScaleMode("Auto")
            elseif targetMode == "55" or targetMode == "55%" or targetMode == "mobile" or targetMode == "hp" then
                setUIScaleMode("55%")
            elseif targetMode == "70" or targetMode == "70%" or targetMode == "med" then
                setUIScaleMode("70%")
            elseif targetMode == "85" or targetMode == "85%" or targetMode == "tab" then
                setUIScaleMode("85%")
            elseif targetMode == "100" or targetMode == "100%" or targetMode == "pc" or targetMode == "full" then
                setUIScaleMode("100%")
            else
                Proxy.notify("`4[UI Scale] Pilihan: /scale <auto | 55 | 70 | 85 | 100>``")
                return true
            end
            Proxy.notify("`2[UI Scale] Berhasil diubah ke: " .. tostring(uiScaleMode) .. " (" .. math.floor(getActiveUIScale() * 100 + 0.5) .. "%)``")
            return true
        elseif cmd == "doors" or cmd == "scandoors" or cmd == "door" then
            local subArg = args[1]
            local extra = args[2]
            task.spawn(function()
                Proxy.scanWorldDoors(subArg, extra)
            end)
            return true
        end

        -- 4. DROP LOCKS
        -- DROP ALL LOCKS (/daw)
        if cmd == "daw" or cmd == "dropalllocks" or cmd == "dropalllock" then
            if not Proxy.onDropFn then
                Proxy.notify("`4[Drop All Locks] Fungsi drop game belum terpasang!``")
                return true
            end

            local maxPerLock = nil
            if args[1] and args[1] ~= "all" then
                local parsed = tonumber(args[1])
                if parsed and parsed > 0 then
                    maxPerLock = math.floor(parsed)
                end
            end

            local locksToDrop = {
                { id = 7188, name = "Blue Gem Lock" },
                { id = 1796, name = "Diamond Lock" },
                { id = 242,  name = "World Lock" },
                { id = 206,  name = "Huge Lock" },
                { id = 204,  name = "Big Lock" },
                { id = 202,  name = "Small Lock" },
            }

            task.spawn(function()
                local droppedTypes = 0
                for _, lockInfo in ipairs(locksToDrop) do
                    local owned = Proxy.getOwnedCount(lockInfo.id)
                    if owned > 0 then
                        local toDrop = maxPerLock and math.min(owned, maxPerLock) or owned
                        if toDrop > 0 then
                            local remaining = toDrop
                            while remaining > 0 do
                                local batch = math.min(remaining, 100)
                                local ok, err = pcall(function() Proxy.onDropFn(lockInfo.id, batch) end)
                                if not ok then
                                    Proxy.notify(string.format("`4[Drop All] Gagal drop %s: %s``", lockInfo.name, tostring(err)))
                                end
                                remaining = remaining - batch
                                if remaining > 0 then
                                    task.wait(0.35)
                                end
                            end
                            droppedTypes = droppedTypes + 1
                            Proxy.notify(string.format("`2[Drop All] Drop %d %s...``", toDrop, lockInfo.name))
                            -- Jeda antar jenis lock yang berbeda (minimal 0.35 detik)
                            task.wait(0.35)
                        end
                    end
                end

                if droppedTypes > 0 then
                    Proxy.notify(string.format("`2[Drop All Locks] Seluruh %d jenis lock berhasil di-drop!``", droppedTypes))
                else
                    Proxy.notify("`4[Drop All Locks] Kamu tidak memiliki lock apapun di tas!``")
                end
                task.delay(0.2, Proxy.updateUI)
            end)
            return true
        end

        local lockInfo = Proxy.LOCKS[cmd]
        if lockInfo then
            Proxy.executeSmartLockDrop(cmd, args)
            return true
        end

        -- 5. GEMS & CONFIG COMMANDS
        if cmd == "pgems" or cmd == "pgem" then
            Proxy.punchGemsCheck = not Proxy.punchGemsCheck
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.notify(Proxy.punchGemsCheck and "`2[Proxy] Punch to Check Gems: ON``" or "`4[Proxy] Punch to Check Gems: OFF``")
            Proxy.saveConfig()
            Proxy.updateUI()
            return true
        end

        if cmd == "logs" or cmd == "log" then
            Proxy.toggleLogsDialog()
            Proxy.notify("`2[Logs] Menampilkan window World Activity Logs (/logs)``")
            return true
        end

        if cmd == "gems" then
            local w = getNativeWorld and getNativeWorld()
            local drops = (w and type(w.dropList) == "function" and w.dropList()) or gameDropsTable or (findGameDropsTable and findGameDropsTable())
            local gemTiles = {}
            local totalGemsFound = 0
            if drops then
                for _, drop in ipairs(drops) do
                    if type(drop) == "table" and (drop.id == 112 or drop.setGem ~= nil) and type(drop.x) == "number" and type(drop.y) == "number" then
                        local tx = math.floor(drop.x)
                        local ty = math.floor(drop.y)
                        local key = tx .. "," .. ty
                        if not gemTiles[key] then gemTiles[key] = { tx = tx, ty = ty, total = 0 } end
                        local count = drop.n or 0
                        gemTiles[key].total = gemTiles[key].total + count
                        totalGemsFound = totalGemsFound + count
                    end
                end
            end

            local pileCount = 0
            for _, tileData in pairs(gemTiles) do
                if tileData.total > 0 then
                    pileCount = pileCount + 1
                    spawnFloatingDropText(tileData.tx, tileData.ty, 112, tileData.total, 4.0)
                end
            end

            if pileCount > 0 then
                Proxy.notify(string.format("`2[Gems] Menampilkan floating text untuk %d Gems (%d tumpukan) selama 4 detik!``", totalGemsFound, pileCount))
            else
                Proxy.notify("`4[Gems] Tidak ada drop gems yang tergeletak di world saat ini!``")
            end
            return true
        end

        if cmd == "saveconfig" or cmd == "savecfg" then
            Proxy.saveConfig()
            local cfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or "sysgt_config.json"
            Proxy.notify(string.format("`2[Config] Seluruh konfigurasi akun berhasil disimpan ke %s!``", cfgFile))
            return true
        end

        if cmd == "loadconfig" or cmd == "loadcfg" then
            Proxy.loadConfig()
            local cfgFile = Proxy.getConfigFile and Proxy.getConfigFile() or "sysgt_config.json"
            Proxy.notify(string.format("`2[Config] Seluruh konfigurasi akun berhasil dimuat dari %s!``", cfgFile))
            return true
        end

        if cmd == "clearconfig" or cmd == "clearcfg" or cmd == "resetconfig" or cmd == "resetcfg" or cmd == "delcfg" then
            Proxy.clearConfig()
            return true
        end

        if cmd == "nick" then
            local newNick = rest:match("^%s*(.-)%s*$")
            if not newNick or newNick == "" or newNick:lower() == "reset" then
                LP:SetAttribute("Nick", nil)
                if Proxy.resetNickCache then Proxy.resetNickCache() end
                Proxy.saveConfig()
                Proxy.notify("`2[Nick] Nickname berhasil di-reset ke nama asli (" .. LP.Name .. ")!``")
            else
                LP:SetAttribute("Nick", newNick)
                if Proxy.resetNickCache then Proxy.resetNickCache() end
                Proxy.saveConfig()
                Proxy.notify("`2[Nick] Streamer mode aktif! Nama disamarkan menjadi: " .. newNick .. "`` (nametag, chat sistem, bubble spin & /logs)")
            end
            Proxy.updateUI()
            pcall(Proxy.refreshLogsUI)
            if SysHubVisual.syncChanged then pcall(SysHubVisual.syncChanged) end
            return true
        end

        if cmd == "unnick" then
            LP:SetAttribute("Nick", nil)
            if Proxy.resetNickCache then Proxy.resetNickCache() end
            Proxy.saveConfig()
            Proxy.notify("`2[Nick] Nickname berhasil di-reset ke nama asli (" .. LP.Name .. ")!``")
            Proxy.updateUI()
            pcall(Proxy.refreshLogsUI)
            if SysHubVisual.syncChanged then pcall(SysHubVisual.syncChanged) end
            return true
        end

        -- 6. AUTO-JOIN & AUTO-CONVERT TOGGLE COMMANDS
        if cmd == "autojoin" then
            AutoRejoin.enabled = not AutoRejoin.enabled
            local state = AutoRejoin.enabled and "`2ON" or "`4OFF"
            Proxy.notify(string.format("`e[Auto-Join] Auto Rejoin sekarang: %s``", state))
            if Proxy.saveConfig then pcall(Proxy.saveConfig) end
            return true
        end

        if cmd == "autocv" or cmd == "autoconvert" then
            autoConvertRunning = not autoConvertRunning
            _G.autoConvertRunning = autoConvertRunning
            local state = autoConvertRunning and "`2ON" or "`4OFF"
            Proxy.notify(string.format("`e[Auto-Convert] Auto Compress Lock (WL→DL→BGL) sekarang: %s``", state))
            if Proxy.saveConfig then pcall(Proxy.saveConfig) end
            return true
        end

        -- 7. VISUAL WARDROBE & WORLD WEATHER COMMANDS
        if cmd == "ag" or cmd == "antigrav" or cmd == "antigravity" or cmd == "nograv" then
            pcall(function() if Sfx and Sfx.play then Sfx.play("click") end end)
            Proxy.toggleClientAG()
            return true
        end

        if cmd == "visual" or cmd == "vis" or cmd == "visuals" or cmd == "skin" or cmd == "wardrobe" then
            SysHubVisual.toggleDialog()
            Proxy.notify("`2[Visual] Membuka panel Visual Wardrobe & Wearables (/visual)``")
            return true
        end

        if cmd == "vsync" or cmd == "visualsync" or cmd == "sharevisual" then
            if SysHubVisual.toggleSync then SysHubVisual.toggleSync() end
            return true
        end

        if cmd == "vsend" then
            local sync = SysHubVisual.sync
            if sync then
                sync.lastSentSig = sync.lastSentSig or "?"
                sync.requestAnnounce(0.2)
                Proxy.notify("`2[Sync] Visual, nick & title kamu dikirim ulang ke pengguna SysHub di world ini``")
            end
            return true
        end

        if cmd == "weather" or cmd == "weathers" or cmd == "sky" then
            local query = rest:match("^%s*(.-)%s*$")
            if query and query ~= "" then
                SysHubWeather.applyByQuery(query)
            else
                SysHubWeather.toggleDialog()
                Proxy.notify("`2[Weather] Membuka panel World Weather Selector (/weather)``")
            end
            return true
        end

        -- 7. WELCOME & ABOUT GAZETTE DIALOG (/news, /about, /welcome, /gazette)
        if cmd == "news" or cmd == "about" or cmd == "welcome" or cmd == "gazette" or cmd == "info" then
            local query = rest:match("^%s*(.-)%s*$")
            SysHubWelcome.open(query)
            return true
        end

        if cmd == "title" or cmd == "titles" then
            local query = rest:match("^%s*(.-)%s*$")
            if not query or query == "" then
                SysHubTitle.openMenu()
                Proxy.notify("`2[Title] Pilih title dari menu Profile -> Title atau gunakan /title [nama]``")
            else
                local q = query:lower()
                local matched = nil
                if q == "none" or q == "reset" or q == "off" or q == "clear" or q == "notitle" then
                    matched = "none"
                else
                    for _, t in ipairs(SysHubTitle.allTitles) do
                        if t.key == q or t.name:lower():find(q, 1, true) then
                            matched = t.key
                            break
                        end
                    end
                end
                if matched then
                    SysHubTitle.set(matched)
                else
                    Proxy.notify("`4[Title] Title tidak ditemukan! Pilihan: supporter, patron, benefactor, sponsor, cc, royal, dr, legend, none``")
                end
            end
            return true
        end

        if origOnCommand and origOnCommand ~= chatTableRef.onCommand then
            return origOnCommand(msg)
        end
        return true
    end

    local cmdWatchActive = true
    local myOnCommand = chatTableRef.onCommand
    task.spawn(function()
        while cmdWatchActive and task.wait(0.5) do
            if chatTableRef and chatTableRef.onCommand ~= myOnCommand then
                if chatTableRef.onCommand ~= nil and not chatTableRef._isSyshubHook then
                    chatTableRef._origOnCommand = chatTableRef.onCommand
                end
                chatTableRef.onCommand = myOnCommand
            end
        end
    end)

    -- Watchdog World Change untuk Auto-Restore Visual Wearables & Weather
    task.spawn(function()
        local lastRestoredWorld = ""
        while cmdWatchActive and task.wait(1.0) do
            local w = getNativeWorld and getNativeWorld()
            if w and w.name and w.name ~= "" and w.name ~= "LOBBY" then
                if w.name ~= lastRestoredWorld then
                    lastRestoredWorld = w.name
                    task.delay(0.6, function()
                        pcall(SysHubVisual.autoRestore)
                        pcall(SysHubWeather.autoRestore)
                        pcall(SysHubTitle.autoRestore)
                    end)
                end
            end
        end
    end)

    task.delay(1.0, function()
        pcall(SysHubVisual.autoRestore)
        pcall(SysHubWeather.autoRestore)
        pcall(SysHubTitle.autoRestore)
    end)

    -- Hook native Gazette / News dialog caller jika game mencoba membukanya
    task.spawn(function()
        if filtergc then
            local list = filtergc("table", { Keys = {"news", "updates", "features", "rules"} }, false)
            for _, t in ipairs(list or {}) do
                if t and type(t.news) == "function" and not t._syshubHooked then
                    t._syshubHooked = true
                    t.news = function() SysHubWelcome.open("about") end
                    t.features = function() SysHubWelcome.open("features") end
                    t.shop = function() SysHubWelcome.open("shop") end
                    t.updates = function() SysHubWelcome.open("updates") end
                end
            end
        end
    end)

    -- Auto-launch Welcome UI on first script execution
    task.delay(0.2, function()
        pcall(SysHubWelcome.open)
    end)

    _G.CleanGrowbloxCommands = function()
        cmdWatchActive = false
        autoConvertRunning = false
        autoConvertLoopAlive = false
        pcall(function()
            if _G.SysHubVisualSync and _G.SysHubVisualSync.stop then _G.SysHubVisualSync.stop() end
        end)
        pcall(function()
            if Proxy.clientAG then
                Proxy.clientAG.wanted = false
                if Proxy.disableClientAG then Proxy.disableClientAG(true) end
            end
        end)
        Proxy.dismissCasinoBanner()
        Proxy.dismissDoorsUI()
        if chatTableRef and chatTableRef._origOnCommand then
            chatTableRef.onCommand = chatTableRef._origOnCommand
        end
        if worldMenuRef and oldOpenPlayer then
            worldMenuRef.openPlayer = oldOpenPlayer
        end
        if kickConn then
            kickConn:Disconnect()
        end
        if gemFloatConn then
            gemFloatConn:Disconnect()
        end
        if dropTakenConn then
            dropTakenConn:Disconnect()
        end
        pcall(function()
            local pgui = PlayerGui
            local floatGui = pgui and pgui:FindFirstChild("SyshubDropFloatGui")
            if floatGui then floatGui:Destroy() end
            local rGui = pgui and pgui:FindFirstChild("SyshubRouletteFloatGui")
            if rGui then rGui:Destroy() end
        end)
        pcall(function()
            if SysHubVisual and SysHubVisual.dialog then
                SysHubVisual.dialog:Destroy()
                SysHubVisual.dialog = nil
            end
            if SysHubWeather and SysHubWeather.dialog then
                SysHubWeather.dialog:Destroy()
                SysHubWeather.dialog = nil
            end
        end)
        _G.SysHub_InstanceRunning = false
        if getgenv then getgenv().SysHub_InstanceRunning = false end
        _G.SysHub_QueueOnTeleportSet = false
        if getgenv then getgenv().SysHub_QueueOnTeleportSet = false end
        _G.SysHub_BootstrapRunning = false
        if getgenv then getgenv().SysHub_BootstrapRunning = false end
    end

    if checkResumeDFState then
        task.spawn(checkResumeDFState)
    end
    if AutoRotation.checkResume then
        task.spawn(AutoRotation.checkResume)
    end
    if AutoEvent and AutoEvent.checkResume then
        task.spawn(AutoEvent.checkResume)
    end
    if FarmLogistics and FarmLogistics.checkResume then
        task.spawn(FarmLogistics.checkResume)
    end

    print("[GrowbloxCommands] ✅ Chat, Casino (v4 Smart Facing Record) & Wrench loaded!")
end)
